window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JER"]={"book":"JER","editions":{"hbo-source":[[1,1,"דִּבְרֵ֥י יִרְמְיָ֖הוּ בֶּן־חִלְקִיָּ֑הוּ מִן־הַ⁠כֹּֽהֲנִים֙ אֲשֶׁ֣ר בַּ⁠עֲנָת֔וֹת בְּ⁠אֶ֖רֶץ בִּנְיָמִֽן׃","di̇bĕré֥y yirĕmĕyá֖hẇ bėn-ẖilĕqiyá֑̇hẇ min-ha⁠kòֽ̇hàniym֙ ʼàşě֣r bȧ⁠ʻànáţ֔wòţ bĕ̇⁠ʼe֖reẕ bi̇nĕyámiֽn׃"],[1,2,"אֲשֶׁ֨ר הָיָ֤ה דְבַר־יְהוָה֙ אֵלָ֔י⁠ו בִּ⁠ימֵ֛י יֹאשִׁיָּ֥הוּ בֶן־אָמ֖וֹן מֶ֣לֶךְ יְהוּדָ֑ה בִּ⁠שְׁלֹשׁ־עֶשְׂרֵ֥ה שָׁנָ֖ה לְ⁠מָלְכֽ⁠וֹ׃","ʼàşě֨r háyá֤h dĕbar-yĕhwáh֙ ʼélá֔y⁠w bi̇⁠ymé֛y yòʼşǐyá֥̇hẇ ben-ʼám֖wòn me֣lekĕ yĕhẇdá֑h bi̇⁠şĕ̌lòş̌-ʻeşĕ̂ré֥h şá̌ná֖h lĕ⁠málĕkֽ⁠wò׃"],[1,3,"וַ⁠יְהִ֗י בִּ⁠ימֵ֨י יְהוֹיָקִ֤ים בֶּן־יֹאשִׁיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה עַד־תֹּם֙ עַשְׁתֵּ֣י עֶשְׂרֵ֣ה שָׁנָ֔ה לְ⁠צִדְקִיָּ֥הוּ בֶן־יֹאשִׁיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה עַד־גְּל֥וֹת יְרוּשָׁלִַ֖ם בַּ⁠חֹ֥דֶשׁ הַ⁠חֲמִישִֽׁי׃ס","wa⁠yĕhi֗y bi̇⁠ymé֨y yĕhwòyáqi֤ym bėn-yòʼşǐyá̇֨hẇ֙ me֣lekĕ yĕhẇdá֔h ʻad-ţò̇m֙ ʻaşĕ̌ţé֣̇y ʻeşĕ̂ré֣h şá̌ná֔h lĕ⁠ẕidĕqiyá֥̇hẇ ben-yòʼşǐyá֖̇hẇ me֣lekĕ yĕhẇdá֑h ʻad-gĕ̇l֥wòţ yĕrẇşá̌lia֖m bȧ⁠ẖò֥deş̌ ha⁠ẖàmiyşǐֽy׃s"],[1,4,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[1,5,"בְּ⁠טֶ֨רֶם אצור⁠ך בַ⁠בֶּ֨טֶן֙ יְדַעְתִּ֔י⁠ךָ וּ⁠בְ⁠טֶ֛רֶם תֵּצֵ֥א מֵ⁠רֶ֖חֶם הִקְדַּשְׁתִּ֑י⁠ךָ נָבִ֥יא לַ⁠גּוֹיִ֖ם נְתַתִּֽי⁠ךָ׃","bĕ̇⁠te֨rem ʼẕwr⁠k ba⁠bė֨ten֙ yĕdaʻĕţi̇֔y⁠ká ẇ⁠bĕ⁠te֛rem ţé̇ẕé֥ʼ mé⁠re֖ẖem hiqĕdȧşĕ̌ţi֑̇y⁠ká nábi֥yʼ la⁠ġwòyi֖m nĕţaţiֽ̇y⁠ká׃"],[1,6,"וָ⁠אֹמַ֗ר אֲהָהּ֙ אֲדֹנָ֣⁠י יְהֹוִ֔ה הִנֵּ֥ה לֹא־יָדַ֖עְתִּי דַּבֵּ֑ר כִּי־נַ֖עַר אָנֹֽכִי׃פ","wá⁠ʼòma֗r ʼàháḣ֙ ʼàdòná֣⁠y yĕhòwi֔h hiné֥̇h lòʼ-yáda֖ʻĕţi̇y dȧbé֑̇r ki̇y-na֖ʻar ʼánòֽkiy׃p"],[1,7,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י אַל־תֹּאמַ֖ר נַ֣עַר אָנֹ֑כִי כִּ֠י עַֽל־כָּל־אֲשֶׁ֤ר אֶֽשְׁלָחֲ⁠ךָ֙ תֵּלֵ֔ךְ וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר אֲצַוְּ⁠ךָ֖ תְּדַבֵּֽר׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y ʼal-ţò̇ʼma֖r na֣ʻar ʼánò֑kiy ki̇֠y ʻaֽl-ká̇l-ʼàşě֤r ʼֽeşĕ̌láẖà⁠ká֙ ţé̇lé֔kĕ wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r ʼàẕawĕ̇⁠ká֖ ţĕ̇dabéֽ̇r׃"],[1,8,"אַל־תִּירָ֖א מִ⁠פְּנֵי⁠הֶ֑ם כִּֽי־אִתְּ⁠ךָ֥ אֲנִ֛י לְ⁠הַצִּלֶ֖⁠ךָ נְאֻם־יְהוָֽה׃","ʼal-ţi̇yrá֖ʼ mi⁠pĕ̇néy⁠he֑m kiֽ̇y-ʼiţĕ̇⁠ká֥ ʼàni֛y lĕ⁠haẕi̇le֖⁠ká nĕʼum-yĕhwáֽh׃"],[1,9,"וַ⁠יִּשְׁלַ֤ח יְהוָה֙ אֶת־יָד֔⁠וֹ וַ⁠יַּגַּ֖ע עַל־פִּ֑⁠י וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י הִנֵּ֛ה נָתַ֥תִּי דְבָרַ֖⁠י בְּ⁠פִֽי⁠ךָ׃","wa⁠yi̇şĕ̌la֤ẖ yĕhwáh֙ ʼeţ-yád֔⁠wò wa⁠yȧgȧ֖ʻ ʻal-pi֑̇⁠y wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y hiné֛̇h náţa֥ţi̇y dĕbára֖⁠y bĕ̇⁠piֽy⁠ká׃"],[1,10,"רְאֵ֞ה הִפְקַדְתִּ֣י⁠ךָ ׀ הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה עַל־הַ⁠גּוֹיִם֙ וְ⁠עַל־הַ⁠מַּמְלָכ֔וֹת לִ⁠נְת֥וֹשׁ וְ⁠לִ⁠נְת֖וֹץ וּ⁠לְ⁠הַאֲבִ֣יד וְ⁠לַ⁠הֲר֑וֹס לִ⁠בְנ֖וֹת וְ⁠לִ⁠נְטֽוֹעַ׃פ","rĕʼé֞h hipĕqadĕţi֣̇y⁠ká ׀ ha⁠ẏ֣wòm ha⁠zė֗h ʻal-ha⁠ġwòyim֙ wĕ⁠ʻal-ha⁠mȧmĕlák֔wòţ li⁠nĕţ֥wòş̌ wĕ⁠li⁠nĕţ֖wòẕ ẇ⁠lĕ⁠haʼàbi֣yd wĕ⁠la⁠hàr֑wòs li⁠bĕn֖wòţ wĕ⁠li⁠nĕtֽwòʻa׃p"],[1,11,"וַ⁠יְהִ֤י דְבַר־יְהוָה֙ אֵלַ֣⁠י לֵ⁠אמֹ֔ר מָה־אַתָּ֥ה רֹאֶ֖ה יִרְמְיָ֑הוּ וָ⁠אֹמַ֕ר מַקֵּ֥ל שָׁקֵ֖ד אֲנִ֥י רֹאֶֽה׃","wa⁠yĕhi֤y dĕbar-yĕhwáh֙ ʼéla֣⁠y lé⁠ʼmò֔r máh-ʼaţá֥̇h ròʼe֖h yirĕmĕyá֑hẇ wá⁠ʼòma֕r maqé֥̇l şá̌qé֖d ʼàni֥y ròʼeֽh׃"],[1,12,"וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֵלַ֖⁠י הֵיטַ֣בְתָּ לִ⁠רְא֑וֹת כִּֽי־שֹׁקֵ֥ד אֲנִ֛י עַל־דְּבָרִ֖⁠י לַ⁠עֲשֹׂתֽ⁠וֹ׃פ","wa⁠yò֧̇ʼmer yĕhwá֛h ʼéla֖⁠y héyta֣bĕţá̇ li⁠rĕʼ֑wòţ kiֽ̇y-şò̌qé֥d ʼàni֛y ʻal-dĕ̇bári֖⁠y la⁠ʻàşò̂ţֽ⁠wò׃p"],[1,13,"וַ⁠יְהִ֨י דְבַר־יְהוָ֤ה ׀ אֵלַ⁠י֙ שֵׁנִ֣ית לֵ⁠אמֹ֔ר מָ֥ה אַתָּ֖ה רֹאֶ֑ה וָ⁠אֹמַ֗ר סִ֤יר נָפ֨וּחַ֙ אֲנִ֣י רֹאֶ֔ה וּ⁠פָנָ֖י⁠ו מִ⁠פְּנֵ֥י צָפֽוֹנָ⁠ה׃","wa⁠yĕhi֨y dĕbar-yĕhwá֤h ׀ ʼéla⁠y֙ şé̌ni֣yţ lé⁠ʼmò֔r má֥h ʼaţá֖̇h ròʼe֑h wá⁠ʼòma֗r si֤yr náp֨ẇẖa֙ ʼàni֣y ròʼe֔h ẇ⁠páná֖y⁠w mi⁠pĕ̇né֥y ẕápֽwòná⁠h׃"],[1,14,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י מִ⁠צָּפוֹן֙ תִּפָּתַ֣ח הָ⁠רָעָ֔ה עַ֥ל כָּל־יֹשְׁבֵ֖י הָ⁠אָֽרֶץ׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y mi⁠ẕá̇pwòn֙ ţi̇pá̇ţa֣ẖ há⁠ráʻá֔h ʻa֥l ká̇l-yòşĕ̌bé֖y há⁠ʼáֽreẕ׃"],[1,15,"כִּ֣י ׀ הִנְ⁠נִ֣י קֹרֵ֗א לְ⁠כָֽל־מִשְׁפְּח֛וֹת מַמְלְכ֥וֹת צָפ֖וֹנָ⁠ה נְאֻם־יְהוָ֑ה וּ⁠בָ֡אוּ וְֽ⁠נָתְנוּ֩ אִ֨ישׁ כִּסְא֜⁠וֹ פֶּ֣תַח ׀ שַׁעֲרֵ֣י יְרוּשָׁלִַ֗ם וְ⁠עַ֤ל כָּל־חוֹמֹתֶ֨י⁠הָ֙ סָבִ֔יב וְ⁠עַ֖ל כָּל־עָרֵ֥י יְהוּדָֽה׃","ki֣̇y ׀ hinĕ⁠ni֣y qòré֗ʼ lĕ⁠káֽl-mişĕ̌pĕ̇ẖ֛wòţ mamĕlĕk֥wòţ ẕáp֖wòná⁠h nĕʼum-yĕhwá֑h ẇ⁠bá֡ʼẇ wĕֽ⁠náţĕnẇ֩ ʼi֨yş̌ ki̇sĕʼ֜⁠wò pė֣ţaẖ ׀ şǎʻàré֣y yĕrẇşá̌lia֗m wĕ⁠ʻa֤l ká̇l-ẖwòmòţe֨y⁠há֙ sábi֔yb wĕ⁠ʻa֖l ká̇l-ʻáré֥y yĕhẇdáֽh׃"],[1,16,"וְ⁠דִבַּרְתִּ֤י מִשְׁפָּטַ⁠י֙ אוֹתָ֔⁠ם עַ֖ל כָּל־רָעָתָ֑⁠ם אֲשֶׁ֣ר עֲזָב֗וּ⁠נִי וַֽ⁠יְקַטְּרוּ֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יִּֽשְׁתַּחֲו֖וּ לְ⁠מַעֲשֵׂ֥י יְדֵי⁠הֶֽם׃","wĕ⁠dibȧrĕţi֤̇y mişĕ̌pá̇ta⁠y֙ ʼwòţá֔⁠m ʻa֖l ká̇l-ráʻáţá֑⁠m ʼàşě֣r ʻàzáb֗ẇ⁠niy waֽ⁠yĕqatĕ̇rẇ֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym wa⁠yiֽ̇şĕ̌ţȧẖàw֖ẇ lĕ⁠maʻàşé֥̂y yĕdéy⁠heֽm׃"],[1,17,"וְ⁠אַתָּה֙ תֶּאְזֹ֣ר מָתְנֶ֔י⁠ךָ וְ⁠קַמְתָּ֙ וְ⁠דִבַּרְתָּ֣ אֲלֵי⁠הֶ֔ם אֵ֛ת כָּל־אֲשֶׁ֥ר אָנֹכִ֖י אֲצַוֶּ֑⁠ךָּ אַל־תֵּחַת֙ מִ⁠פְּנֵי⁠הֶ֔ם פֶּֽן־אֲחִתְּ⁠ךָ֖ לִ⁠פְנֵי⁠הֶֽם׃","wĕ⁠ʼaţá̇h֙ ţėʼĕzò֣r máţĕne֔y⁠ká wĕ⁠qamĕţá̇֙ wĕ⁠dibȧrĕţá֣̇ ʼàléy⁠he֔m ʼé֛ţ ká̇l-ʼàşě֥r ʼánòki֖y ʼàẕawė֑⁠ká̇ ʼal-ţé̇ẖaţ֙ mi⁠pĕ̇néy⁠he֔m pėֽn-ʼàẖiţĕ̇⁠ká֖ li⁠pĕnéy⁠heֽm׃"],[1,18,"וַ⁠אֲנִ֞י הִנֵּ֧ה נְתַתִּ֣י⁠ךָ הַ⁠יּ֗וֹם לְ⁠עִ֨יר מִבְצָ֜ר וּ⁠לְ⁠עַמּ֥וּד בַּרְזֶ֛ל וּ⁠לְ⁠חֹמ֥וֹת נְחֹ֖שֶׁת עַל־כָּל־הָ⁠אָ֑רֶץ לְ⁠מַלְכֵ֤י יְהוּדָה֙ לְ⁠שָׂרֶ֔י⁠הָ לְ⁠כֹהֲנֶ֖י⁠הָ וּ⁠לְ⁠עַ֥ם הָ⁠אָֽרֶץ׃","wa⁠ʼàni֞y hiné֧̇h nĕţaţi֣̇y⁠ká ha⁠ẏ֗wòm lĕ⁠ʻi֨yr mibĕẕá֜r ẇ⁠lĕ⁠ʻaṁ֥ẇd bȧrĕze֛l ẇ⁠lĕ⁠ẖòm֥wòţ nĕẖò֖şěţ ʻal-ká̇l-há⁠ʼá֑reẕ lĕ⁠malĕké֤y yĕhẇdáh֙ lĕ⁠şá̂re֔y⁠há lĕ⁠kòhàne֖y⁠há ẇ⁠lĕ⁠ʻa֥m há⁠ʼáֽreẕ׃"],[1,19,"וְ⁠נִלְחֲמ֥וּ אֵלֶ֖י⁠ךָ וְ⁠לֹא־י֣וּכְלוּ לָ֑⁠ךְ כִּֽי־אִתְּ⁠ךָ֥ אֲנִ֛י נְאֻם־יְהוָ֖ה לְ⁠הַצִּילֶֽ⁠ךָ׃פ","wĕ⁠nilĕẖàm֥ẇ ʼéle֖y⁠ká wĕ⁠lòʼ-y֣ẇkĕlẇ lá֑⁠kĕ kiֽ̇y-ʼiţĕ̇⁠ká֥ ʼàni֛y nĕʼum-yĕhwá֖h lĕ⁠haẕi̇yleֽ⁠ká׃p"],[2,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[2,2,"הָלֹ֡ךְ וְ⁠קָֽרָאתָ֩ בְ⁠אָזְנֵ֨י יְרוּשָׁלִַ֜ם לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה זָכַ֤רְתִּי לָ⁠ךְ֙ חֶ֣סֶד נְעוּרַ֔יִ⁠ךְ אַהֲבַ֖ת כְּלוּלֹתָ֑יִ⁠ךְ לֶכְתֵּ֤⁠ךְ אַחֲרַ⁠י֙ בַּ⁠מִּדְבָּ֔ר בְּ⁠אֶ֖רֶץ לֹ֥א זְרוּעָֽה׃","hálò֡kĕ wĕ⁠qáֽráʼţá֩ bĕ⁠ʼázĕné֨y yĕrẇşá̌lia֜m lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h záka֤rĕţi̇y lá⁠kĕ֙ ẖe֣sed nĕʻẇra֔yi⁠kĕ ʼahàba֖ţ kĕ̇lẇlòţá֑yi⁠kĕ lekĕţé֤̇⁠kĕ ʼaẖàra⁠y֙ bȧ⁠mi̇dĕbá̇֔r bĕ̇⁠ʼe֖reẕ lò֥ʼ zĕrẇʻáֽh׃"],[2,3,"קֹ֤דֶשׁ יִשְׂרָאֵל֙ לַ⁠יהוָ֔ה רֵאשִׁ֖ית תְּבוּאָתֹ֑⁠ה כָּל־אֹכְלָ֣י⁠ו יֶאְשָׁ֔מוּ רָעָ֛ה תָּבֹ֥א אֲלֵי⁠הֶ֖ם נְאֻם־יְהוָֽה׃פ","qò֤deş̌ yişĕ̂ráʼél֙ la⁠yhwá֔h réʼşǐ֖yţ ţĕ̇bẇʼáţò֑⁠h ká̇l-ʼòkĕlá֣y⁠w yeʼĕşá̌֔mẇ ráʻá֛h ţá̇bò֥ʼ ʼàléy⁠he֖m nĕʼum-yĕhwáֽh׃p"],[2,4,"שִׁמְע֥וּ דְבַר־יְהוָ֖ה בֵּ֣ית יַעֲקֹ֑ב וְ⁠כָֽל־מִשְׁפְּח֖וֹת בֵּ֥ית יִשְׂרָאֵֽל׃","şǐmĕʻ֥ẇ dĕbar-yĕhwá֖h bé֣̇yţ yaʻàqò֑b wĕ⁠káֽl-mişĕ̌pĕ̇ẖ֖wòţ bé֥̇yţ yişĕ̂ráʼéֽl׃"],[2,5,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה מַה־מָּצְא֨וּ אֲבוֹתֵי⁠כֶ֥ם בִּ⁠י֙ עָ֔וֶל כִּ֥י רָחֲק֖וּ מֵ⁠עָלָ֑⁠י וַ⁠יֵּֽלְכ֛וּ אַחֲרֵ֥י הַ⁠הֶ֖בֶל וַ⁠יֶּהְבָּֽלוּ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h mah-má̇ẕĕʼ֨ẇ ʼàbwòţéy⁠ke֥m bi̇⁠y֙ ʻá֔wel ki֥̇y ráẖàq֖ẇ mé⁠ʻálá֑⁠y wa⁠yéֽ̇lĕk֛ẇ ʼaẖàré֥y ha⁠he֖bel wa⁠yėhĕbáֽ̇lẇ׃"],[2,6,"וְ⁠לֹ֣א אָמְר֔וּ אַיֵּ֣ה יְהוָ֔ה הַ⁠מַּעֲלֶ֥ה אֹתָ֖⁠נוּ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם הַ⁠מּוֹלִ֨יךְ אֹתָ֜⁠נוּ בַּ⁠מִּדְבָּ֗ר בְּ⁠אֶ֨רֶץ עֲרָבָ֤ה וְ⁠שׁוּחָה֙ בְּ⁠אֶ֨רֶץ֙ צִיָּ֣ה וְ⁠צַלְמָ֔וֶת בְּ⁠אֶ֗רֶץ לֹֽא־עָ֤בַר בָּ⁠הּ֙ אִ֔ישׁ וְ⁠לֹֽא־יָשַׁ֥ב אָדָ֖ם שָֽׁם׃","wĕ⁠lò֣ʼ ʼámĕr֔ẇ ʼayé֣̇h yĕhwá֔h ha⁠mȧʻàle֥h ʼòţá֖⁠nẇ mé⁠ʼe֣reẕ miẕĕrá֑yim ha⁠ṁwòli֨ykĕ ʼòţá֜⁠nẇ bȧ⁠mi̇dĕbá̇֗r bĕ̇⁠ʼe֨reẕ ʻàrábá֤h wĕ⁠ş̌ẇẖáh֙ bĕ̇⁠ʼe֨reẕ֙ ẕiyá֣̇h wĕ⁠ẕalĕmá֔weţ bĕ̇⁠ʼe֗reẕ lòֽʼ-ʻá֤bar bá̇⁠ḣ֙ ʼi֔yş̌ wĕ⁠lòֽʼ-yáşǎ֥b ʼádá֖m şáֽ̌m׃"],[2,7,"וָ⁠אָבִ֤יא אֶתְ⁠כֶם֙ אֶל־אֶ֣רֶץ הַ⁠כַּרְמֶ֔ל לֶ⁠אֱכֹ֥ל פִּרְיָ֖⁠הּ וְ⁠טוּבָ֑⁠הּ וַ⁠תָּבֹ֨אוּ֙ וַ⁠תְּטַמְּא֣וּ אֶת־אַרְצִ֔⁠י וְ⁠נַחֲלָתִ֥⁠י שַׂמְתֶּ֖ם לְ⁠תוֹעֵבָֽה׃","wá⁠ʼábi֤yʼ ʼeţĕ⁠kem֙ ʼel-ʼe֣reẕ ha⁠kȧrĕme֔l le⁠ʼèkò֥l pi̇rĕyá֖⁠ḣ wĕ⁠tẇbá֑⁠ḣ wa⁠ţá̇bò֨ʼẇ֙ wa⁠ţĕ̇tamĕ̇ʼ֣ẇ ʼeţ-ʼarĕẕi֔⁠y wĕ⁠naẖàláţi֥⁠y şâmĕţė֖m lĕ⁠ţwòʻébáֽh׃"],[2,8,"הַ⁠כֹּהֲנִ֗ים לֹ֤א אָֽמְרוּ֙ אַיֵּ֣ה יְהוָ֔ה וְ⁠תֹפְשֵׂ֤י הַ⁠תּוֹרָה֙ לֹ֣א יְדָע֔וּ⁠נִי וְ⁠הָ⁠רֹעִ֖ים פָּ֣שְׁעוּ בִ֑⁠י וְ⁠הַ⁠נְּבִיאִים֙ נִבְּא֣וּ בַ⁠בַּ֔עַל וְ⁠אַחֲרֵ֥י לֹֽא־יוֹעִ֖לוּ הָלָֽכוּ׃","ha⁠kò̇hàni֗ym lò֤ʼ ʼáֽmĕrẇ֙ ʼayé֣̇h yĕhwá֔h wĕ⁠ţòpĕşé֤̂y ha⁠ţ̇wòráh֙ lò֣ʼ yĕdáʻ֔ẇ⁠niy wĕ⁠há⁠ròʻi֖ym pá֣̇şĕ̌ʻẇ bi֑⁠y wĕ⁠ha⁠nĕ̇biyʼiym֙ nibĕ̇ʼ֣ẇ ba⁠bȧ֔ʻal wĕ⁠ʼaẖàré֥y lòֽʼ-ywòʻi֖lẇ háláֽkẇ׃"],[2,9,"לָ⁠כֵ֗ן עֹ֛ד אָרִ֥יב אִתְּ⁠כֶ֖ם נְאֻם־יְהוָ֑ה וְ⁠אֶת־בְּנֵ֥י בְנֵי⁠כֶ֖ם אָרִֽיב׃","lá⁠ké֗n ʻò֛d ʼári֥yb ʼiţĕ̇⁠ke֖m nĕʼum-yĕhwá֑h wĕ⁠ʼeţ-bĕ̇né֥y bĕnéy⁠ke֖m ʼáriֽyb׃"],[2,10,"כִּ֣י עִבְר֞וּ אִיֵּ֤י כִתִּיִּים֙ וּ⁠רְא֔וּ וְ⁠קֵדָ֛ר שִׁלְח֥וּ וְ⁠הִֽתְבּוֹנְנ֖וּ מְאֹ֑ד וּ⁠רְא֕וּ הֵ֥ן הָיְתָ֖ה כָּ⁠זֹֽאת׃","ki֣̇y ʻibĕr֞ẇ ʼiyé֤̇y kiţi̇yi̇ym֙ ẇ⁠rĕʼ֔ẇ wĕ⁠qédá֛r şǐlĕẖ֥ẇ wĕ⁠hiֽţĕḃwònĕn֖ẇ mĕʼò֑d ẇ⁠rĕʼ֕ẇ hé֥n háyĕţá֖h ká̇⁠zòֽʼţ׃"],[2,11,"הַ⁠הֵימִ֥יר גּוֹי֙ אֱלֹהִ֔ים וְ⁠הֵ֖מָּה לֹ֣א אֱלֹהִ֑ים וְ⁠עַמִּ֛⁠י הֵמִ֥יר כְּבוֹד֖⁠וֹ בְּ⁠ל֥וֹא יוֹעִֽיל׃","ha⁠héymi֥yr ġwòy֙ ʼèlòhi֔ym wĕ⁠hé֖má̇h lò֣ʼ ʼèlòhi֑ym wĕ⁠ʻami֛̇⁠y hémi֥yr kĕ̇bwòd֖⁠wò bĕ̇⁠l֥wòʼ ywòʻiֽyl׃"],[2,12,"שֹׁ֥מּוּ שָׁמַ֖יִם עַל־זֹ֑את וְ⁠שַׂעֲר֛וּ חָרְב֥וּ מְאֹ֖ד נְאֻם־יְהוָֽה׃","şò֥̌ṁẇ şá̌ma֖yim ʻal-zò֑ʼţ wĕ⁠şâʻàr֛ẇ ẖárĕb֥ẇ mĕʼò֖d nĕʼum-yĕhwáֽh׃"],[2,13,"כִּֽי־שְׁתַּ֥יִם רָע֖וֹת עָשָׂ֣ה עַמִּ֑⁠י אֹתִ֨⁠י עָזְב֜וּ מְק֣וֹר ׀ מַ֣יִם חַיִּ֗ים לַ⁠חְצֹ֤ב לָ⁠הֶם֙ בֹּאר֔וֹת בֹּארֹת֙ נִשְׁבָּרִ֔ים אֲשֶׁ֥ר לֹא־יָכִ֖לוּ הַ⁠מָּֽיִם׃","kiֽ̇y-şĕ̌ţȧ֥yim ráʻ֖wòţ ʻáşá֣̂h ʻami֑̇⁠y ʼòţi֨⁠y ʻázĕb֜ẇ mĕq֣wòr ׀ ma֣yim ẖayi̇֗ym la⁠ẖĕẕò֤b lá⁠hem֙ bò̇ʼr֔wòţ bò̇ʼròţ֙ nişĕ̌bá̇ri֔ym ʼàşě֥r lòʼ-yáki֖lẇ ha⁠máֽ̇yim׃"],[2,14,"הַ⁠עֶ֨בֶד֙ יִשְׂרָאֵ֔ל אִם־יְלִ֥יד בַּ֖יִת ה֑וּא מַדּ֖וּעַ הָיָ֥ה לָ⁠בַֽז׃","ha⁠ʻe֨bed֙ yişĕ̂ráʼé֔l ʼim-yĕli֥yd bȧ֖yiţ h֑ẇʼ maḋ֖ẇʻa háyá֥h lá⁠baֽz׃"],[2,15,"עָלָי⁠ו֙ יִשְׁאֲג֣וּ כְפִרִ֔ים נָתְנ֖וּ קוֹלָ֑⁠ם וַ⁠יָּשִׁ֤יתוּ אַרְצ⁠וֹ֙ לְ⁠שַׁמָּ֔ה עָרָ֥י⁠ו נצתה מִ⁠בְּלִ֥י יֹשֵֽׁב׃","ʻáláy⁠w֙ yişĕ̌ʼàg֣ẇ kĕpiri֔ym náţĕn֖ẇ qwòlá֑⁠m wa⁠yá̇şǐ֤yţẇ ʼarĕẕ⁠wò֙ lĕ⁠şǎmá̇֔h ʻárá֥y⁠w nẕţh mi⁠bĕ̇li֥y yòşéֽ̌b׃"],[2,16,"גַּם־בְּנֵי־נֹ֖ף ו⁠תחפנס יִרְע֖וּ⁠ךְ קָדְקֹֽד׃","gȧm-bĕ̇néy-nò֖p w⁠ţẖpns yirĕʻ֖ẇ⁠kĕ qádĕqòֽd׃"],[2,17,"הֲ⁠לוֹא־זֹ֖את תַּעֲשֶׂה־לָּ֑⁠ךְ עָזְבֵ⁠ךְ֙ אֶת־יְהוָ֣ה אֱלֹהַ֔יִ⁠ךְ בְּ⁠עֵ֖ת מוֹלִיכֵ֥⁠ךְ בַּ⁠דָּֽרֶךְ׃","hà⁠lwòʼ-zò֖ʼţ ţȧʻàşêh-lá֑̇⁠kĕ ʻázĕbé⁠kĕ֙ ʼeţ-yĕhwá֣h ʼèlòha֔yi⁠kĕ bĕ̇⁠ʻé֖ţ mwòliyké֥⁠kĕ bȧ⁠dáֽ̇rekĕ׃"],[2,18,"וְ⁠עַתָּ֗ה מַה־לָּ⁠ךְ֙ לְ⁠דֶ֣רֶךְ מִצְרַ֔יִם לִ⁠שְׁתּ֖וֹת מֵ֣י שִׁח֑וֹר וּ⁠מַה־לָּ⁠ךְ֙ לְ⁠דֶ֣רֶךְ אַשּׁ֔וּר לִ⁠שְׁתּ֖וֹת מֵ֥י נָהָֽר׃","wĕ⁠ʻaţá̇֗h mah-lá̇⁠kĕ֙ lĕ⁠de֣rekĕ miẕĕra֔yim li⁠şĕ̌ţ֖̇wòţ mé֣y şǐẖ֑wòr ẇ⁠mah-lá̇⁠kĕ֙ lĕ⁠de֣rekĕ ʼaş̇̌֔ẇr li⁠şĕ̌ţ֖̇wòţ mé֥y náháֽr׃"],[2,19,"תְּיַסְּרֵ֣⁠ךְ רָעָתֵ֗⁠ךְ וּ⁠מְשֻֽׁבוֹתַ֨יִ⁠ךְ֙ תּוֹכִחֻ֔⁠ךְ וּ⁠דְעִ֤י וּ⁠רְאִי֙ כִּי־רַ֣ע וָ⁠מָ֔ר עָזְבֵ֖⁠ךְ אֶת־יְהוָ֣ה אֱלֹהָ֑יִ⁠ךְ וְ⁠לֹ֤א פַחְדָּתִ⁠י֙ אֵלַ֔יִ⁠ךְ נְאֻם־אֲדֹנָ֥⁠י יְהוִ֖ה צְבָאֽוֹת׃","ţĕ̇yasĕ̇ré֣⁠kĕ ráʻáţé֗⁠kĕ ẇ⁠mĕşǔֽbwòţa֨yi⁠kĕ֙ ţ̇wòkiẖu֔⁠kĕ ẇ⁠dĕʻi֤y ẇ⁠rĕʼiy֙ ki̇y-ra֣ʻ wá⁠má֔r ʻázĕbé֖⁠kĕ ʼeţ-yĕhwá֣h ʼèlòhá֑yi⁠kĕ wĕ⁠lò֤ʼ paẖĕdá̇ţi⁠y֙ ʼéla֔yi⁠kĕ nĕʼum-ʼàdòná֥⁠y yĕhwi֖h ẕĕbáʼֽwòţ׃"],[2,20,"כִּ֣י מֵ⁠עוֹלָ֞ם שָׁבַ֣רְתִּי עֻלֵּ֗⁠ךְ נִתַּ֨קְתִּי֙ מוֹסְרֹתַ֔יִ⁠ךְ וַ⁠תֹּאמְרִ֖י לֹ֣א אעבד כִּ֣י עַֽל־כָּל־גִּבְעָ֞ה גְּבֹהָ֗ה וְ⁠תַ֨חַת֙ כָּל־עֵ֣ץ רַעֲנָ֔ן אַ֖תְּ צֹעָ֥ה זֹנָֽה׃","ki֣̇y mé⁠ʻwòlá֞m şá̌ba֣rĕţi̇y ʻulé̇֗⁠kĕ niţȧ֨qĕţi̇y֙ mwòsĕròţa֔yi⁠kĕ wa⁠ţò̇ʼmĕri֖y lò֣ʼ ʼʻbd ki֣̇y ʻaֽl-ká̇l-gi̇bĕʻá֞h gĕ̇bòhá֗h wĕ⁠ţa֨ẖaţ֙ ká̇l-ʻé֣ẕ raʻàná֔n ʼa֖ţĕ̇ ẕòʻá֥h zònáֽh׃"],[2,21,"וְ⁠אָֽנֹכִי֙ נְטַעְתִּ֣י⁠ךְ שֹׂרֵ֔ק כֻּלֹּ֖⁠ה זֶ֣רַע אֱמֶ֑ת וְ⁠אֵיךְ֙ נֶהְפַּ֣כְתְּ לִ֔⁠י סוּרֵ֖י הַ⁠גֶּ֥פֶן נָכְרִיָּֽה׃","wĕ⁠ʼáֽnòkiy֙ nĕtaʻĕţi֣̇y⁠kĕ şò̂ré֔q ku̇lò֖̇⁠h ze֣raʻ ʼème֑ţ wĕ⁠ʼéykĕ֙ nehĕpȧ֣kĕţĕ̇ li֔⁠y sẇré֖y ha⁠gė֥pen nákĕriyáֽ̇h׃"],[2,22,"כִּ֤י אִם־תְּכַבְּסִי֙ בַּ⁠נֶּ֔תֶר וְ⁠תַרְבִּי־לָ֖⁠ךְ בֹּרִ֑ית נִכְתָּ֤ם עֲוֺנֵ⁠ךְ֙ לְ⁠פָנַ֔⁠י נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ki֤̇y ʼim-ţĕ̇kabĕ̇siy֙ bȧ⁠nė֔ţer wĕ⁠ţarĕbi̇y-lá֖⁠kĕ bò̇ri֑yţ nikĕţá֤̇m ʻàwֺné⁠kĕ֙ lĕ⁠pána֔⁠y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[2,23,"אֵ֣יךְ תֹּאמְרִ֞י לֹ֣א נִטְמֵ֗אתִי אַחֲרֵ֤י הַ⁠בְּעָלִים֙ לֹ֣א הָלַ֔כְתִּי רְאִ֤י דַרְכֵּ⁠ךְ֙ בַּ⁠גַּ֔יְא דְּעִ֖י מֶ֣ה עָשִׂ֑ית בִּכְרָ֥ה קַלָּ֖ה מְשָׂרֶ֥כֶת דְּרָכֶֽי⁠הָ׃","ʼé֣ykĕ ţò̇ʼmĕri֞y lò֣ʼ nitĕmé֗ʼţiy ʼaẖàré֤y ha⁠bĕ̇ʻáliym֙ lò֣ʼ hála֔kĕţi̇y rĕʼi֤y darĕké̇⁠kĕ֙ bȧ⁠gȧ֔yĕʼ dĕ̇ʻi֖y me֣h ʻáşî֑yţ bi̇kĕrá֥h qalá֖̇h mĕşá̂re֥keţ dĕ̇rákeֽy⁠há׃"],[2,24,"פֶּ֣רֶה ׀ לִמֻּ֣ד מִדְבָּ֗ר בְּ⁠אַוַּ֤ת נפש⁠ו שָׁאֲפָ֣ה ר֔וּחַ תַּאֲנָתָ֖⁠הּ מִ֣י יְשִׁיבֶ֑⁠נָּה כָּל־מְבַקְשֶׁ֨י⁠הָ֙ לֹ֣א יִיעָ֔פוּ בְּ⁠חָדְשָׁ֖⁠הּ יִמְצָאֽוּ⁠נְהָ׃","pė֣reh ׀ limu֣̇d midĕbá̇֗r bĕ̇⁠ʼawȧ֤ţ npş⁠w şá̌ʼàpá֣h r֔ẇẖa ţȧʼànáţá֖⁠ḣ mi֣y yĕşǐybe֑⁠ná̇h ká̇l-mĕbaqĕşě֨y⁠há֙ lò֣ʼ yiyʻá֔pẇ bĕ̇⁠ẖádĕşá֖̌⁠ḣ yimĕẕáʼֽẇ⁠nĕhá׃"],[2,25,"מִנְעִ֤י רַגְלֵ⁠ךְ֙ מִ⁠יָּחֵ֔ף ו⁠גורנ⁠ך מִ⁠צִּמְאָ֑ה וַ⁠תֹּאמְרִ֣י נוֹאָ֔שׁ ל֕וֹא כִּֽי־אָהַ֥בְתִּי זָרִ֖ים וְ⁠אַחֲרֵי⁠הֶ֥ם אֵלֵֽךְ׃","minĕʻi֤y ragĕlé⁠kĕ֙ mi⁠yá̇ẖé֔p w⁠gwrn⁠k mi⁠ẕi̇mĕʼá֑h wa⁠ţò̇ʼmĕri֣y nwòʼá֔ş̌ l֕wòʼ kiֽ̇y-ʼáha֥bĕţi̇y zári֖ym wĕ⁠ʼaẖàréy⁠he֥m ʼéléֽkĕ׃"],[2,26,"כְּ⁠בֹ֤שֶׁת גַּנָּב֙ כִּ֣י יִמָּצֵ֔א כֵּ֥ן הֹבִ֖ישׁוּ בֵּ֣ית יִשְׂרָאֵ֑ל הֵ֤מָּה מַלְכֵי⁠הֶם֙ שָֽׂרֵי⁠הֶ֔ם וְ⁠כֹהֲנֵי⁠הֶ֖ם וּ⁠נְבִיאֵי⁠הֶֽם׃","kĕ̇⁠bò֤şěţ gȧná̇b֙ ki֣̇y yimá̇ẕé֔ʼ ké֥̇n hòbi֖yş̌ẇ bé֣̇yţ yişĕ̂ráʼé֑l hé֤má̇h malĕkéy⁠hem֙ şáֽ̂réy⁠he֔m wĕ⁠kòhànéy⁠he֖m ẇ⁠nĕbiyʼéy⁠heֽm׃"],[2,27,"אֹמְרִ֨ים לָ⁠עֵ֜ץ אָ֣בִ⁠י אַ֗תָּה וְ⁠לָ⁠אֶ֨בֶן֙ אַ֣תְּ ילדת⁠ני כִּֽי־פָנ֥וּ אֵלַ֛⁠י עֹ֖רֶף וְ⁠לֹ֣א פָנִ֑ים וּ⁠בְ⁠עֵ֤ת רָֽעָתָ⁠ם֙ יֹֽאמְר֔וּ ק֖וּמָ⁠ה וְ⁠הוֹשִׁיעֵֽ⁠נוּ׃","ʼòmĕri֨ym lá⁠ʻé֜ẕ ʼá֣bi⁠y ʼa֗ţá̇h wĕ⁠lá⁠ʼe֨ben֙ ʼa֣ţĕ̇ yldţ⁠ny kiֽ̇y-pán֥ẇ ʼéla֛⁠y ʻò֖rep wĕ⁠lò֣ʼ páni֑ym ẇ⁠bĕ⁠ʻé֤ţ ráֽʻáţá⁠m֙ yòֽʼmĕr֔ẇ q֖ẇmá⁠h wĕ⁠hwòşǐyʻéֽ⁠nẇ׃"],[2,28,"וְ⁠אַיֵּ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֲשֶׁ֣ר עָשִׂ֣יתָ לָּ֔⁠ךְ יָק֕וּמוּ אִם־יוֹשִׁיע֖וּ⁠ךָ בְּ⁠עֵ֣ת רָעָתֶ֑⁠ךָ כִּ֚י מִסְפַּ֣ר עָרֶ֔י⁠ךָ הָי֥וּ אֱלֹהֶ֖י⁠ךָ יְהוּדָֽה׃ס","wĕ⁠ʼayé֤̇h ʼèlòhe֨y⁠ká֙ ʼàşě֣r ʻáşî֣yţá lá̇֔⁠kĕ yáq֕ẇmẇ ʼim-ywòşǐyʻ֖ẇ⁠ká bĕ̇⁠ʻé֣ţ ráʻáţe֑⁠ká ki֚̇y misĕpȧ֣r ʻáre֔y⁠ká háy֥ẇ ʼèlòhe֖y⁠ká yĕhẇdáֽh׃s"],[2,29,"לָ֥⁠מָּה תָרִ֖יבוּ אֵלָ֑⁠י כֻּלְּ⁠כֶ֛ם פְּשַׁעְתֶּ֥ם בִּ֖⁠י נְאֻם־יְהוָֽה׃","lá֥⁠má̇h ţári֖ybẇ ʼélá֑⁠y ku̇lĕ̇⁠ke֛m pĕ̇şǎʻĕţė֥m bi֖̇⁠y nĕʼum-yĕhwáֽh׃"],[2,30,"לַ⁠שָּׁוְא֙ הִכֵּ֣יתִי אֶת־בְּנֵי⁠כֶ֔ם מוּסָ֖ר לֹ֣א לָקָ֑חוּ אָכְלָ֧ה חַרְבְּ⁠כֶ֛ם נְבִֽיאֵי⁠כֶ֖ם כְּ⁠אַרְיֵ֥ה מַשְׁחִֽית׃","la⁠şá̇̌wĕʼ֙ hiké֣̇yţiy ʼeţ-bĕ̇néy⁠ke֔m mẇsá֖r lò֣ʼ láqá֑ẖẇ ʼákĕlá֧h ẖarĕbĕ̇⁠ke֛m nĕbiֽyʼéy⁠ke֖m kĕ̇⁠ʼarĕyé֥h maşĕ̌ẖiֽyţ׃"],[2,31,"הַ⁠דּ֗וֹר אַתֶּם֙ רְא֣וּ דְבַר־יְהוָ֔ה הֲ⁠מִדְבָּ֤ר הָיִ֨יתִי֙ לְ⁠יִשְׂרָאֵ֔ל אִ֛ם אֶ֥רֶץ מַאְפֵּ֖לְיָ֑ה מַדּ֜וּעַ אָמְר֤וּ עַמִּ⁠י֙ רַ֔דְנוּ לֽוֹא־נָב֥וֹא ע֖וֹד אֵלֶֽי⁠ךָ׃","ha⁠ḋ֗wòr ʼaţėm֙ rĕʼ֣ẇ dĕbar-yĕhwá֔h hà⁠midĕbá֤̇r háyi֨yţiy֙ lĕ⁠yişĕ̂ráʼé֔l ʼi֛m ʼe֥reẕ maʼĕpé֖̇lĕyá֑h maḋ֜ẇʻa ʼámĕr֤ẇ ʻami̇⁠y֙ ra֔dĕnẇ lֽwòʼ-náb֥wòʼ ʻ֖wòd ʼéleֽy⁠ká׃"],[2,32,"הֲ⁠תִשְׁכַּ֤ח בְּתוּלָה֙ עֶדְיָ֔⁠הּ כַּלָּ֖ה קִשֻּׁרֶ֑י⁠הָ וְ⁠עַמִּ֣⁠י שְׁכֵח֔וּ⁠נִי יָמִ֖ים אֵ֥ין מִסְפָּֽר׃","hà⁠ţişĕ̌kȧ֤ẖ bĕ̇ţẇláh֙ ʻedĕyá֔⁠ḣ kȧlá֖̇h qişu̇̌re֑y⁠há wĕ⁠ʻami֣̇⁠y şĕ̌kéẖ֔ẇ⁠niy yámi֖ym ʼé֥yn misĕpáֽ̇r׃"],[2,33,"מַה־תֵּיטִ֥בִי דַּרְכֵּ֖⁠ךְ לְ⁠בַקֵּ֣שׁ אַהֲבָ֑ה לָ⁠כֵן֙ גַּ֣ם אֶת־הָ⁠רָע֔וֹת למדתי אֶת־דְּרָכָֽיִ⁠ךְ׃","mah-ţé̇yti֥biy dȧrĕké֖̇⁠kĕ lĕ⁠baqé֣̇ş̌ ʼahàbá֑h lá⁠kén֙ gȧ֣m ʼeţ-há⁠ráʻ֔wòţ lmdţy ʼeţ-dĕ̇rákáֽyi⁠kĕ׃"],[2,34,"גַּ֤ם בִּ⁠כְנָפַ֨יִ⁠ךְ֙ נִמְצְא֔וּ דַּ֛ם נַפְשׁ֥וֹת אֶבְיוֹנִ֖ים נְקִיִּ֑ים לֹֽא־בַ⁠מַּחְתֶּ֥רֶת מְצָאתִ֖י⁠ם כִּ֥י עַל־כָּל־אֵֽלֶּה׃","gȧ֤m bi̇⁠kĕnápa֨yi⁠kĕ֙ nimĕẕĕʼ֔ẇ dȧ֛m napĕş֥̌wòţ ʼebĕywòni֖ym nĕqiyi֑̇ym lòֽʼ-ba⁠mȧẖĕţė֥reţ mĕẕáʼţi֖y⁠m ki֥̇y ʻal-ká̇l-ʼéֽlėh׃"],[2,35,"וַ⁠תֹּֽאמְרִי֙ כִּ֣י נִקֵּ֔יתִי אַ֛ךְ שָׁ֥ב אַפּ֖⁠וֹ מִמֶּ֑⁠נִּי הִנְ⁠נִי֙ נִשְׁפָּ֣ט אוֹתָ֔⁠ךְ עַל־אָמְרֵ֖⁠ךְ לֹ֥א חָטָֽאתִי׃","wa⁠ţòֽ̇ʼmĕriy֙ ki֣̇y niqé̇֔yţiy ʼa֛kĕ şá֥̌b ʼaṗ֖⁠wò mimė֑⁠ni̇y hinĕ⁠niy֙ nişĕ̌pá֣̇t ʼwòţá֔⁠kĕ ʻal-ʼámĕré֖⁠kĕ lò֥ʼ ẖátáֽʼţiy׃"],[2,36,"מַה־תֵּזְלִ֥י מְאֹ֖ד לְ⁠שַׁנּ֣וֹת אֶת־דַּרְכֵּ֑⁠ךְ גַּ֤ם מִ⁠מִּצְרַ֨יִם֙ תֵּב֔וֹשִׁי כַּ⁠אֲשֶׁר־בֹּ֖שְׁתְּ מֵ⁠אַשּֽׁוּר׃","mah-ţé̇zĕli֥y mĕʼò֖d lĕ⁠şǎṅ֣wòţ ʼeţ-dȧrĕké֑̇⁠kĕ gȧ֤m mi⁠mi̇ẕĕra֨yim֙ ţé̇b֔wòşǐy kȧ⁠ʼàşěr-bò֖̇şĕ̌ţĕ̇ mé⁠ʼaşֽ̇̌ẇr׃"],[2,37,"גַּ֣ם מֵ⁠אֵ֥ת זֶה֙ תֵּֽצְאִ֔י וְ⁠יָדַ֖יִ⁠ךְ עַל־רֹאשֵׁ֑⁠ךְ כִּֽי־מָאַ֤ס יְהֹוָה֙ בְּ⁠מִבְטַחַ֔יִ⁠ךְ וְ⁠לֹ֥א תַצְלִ֖יחִי לָ⁠הֶֽם׃","gȧ֣m mé⁠ʼé֥ţ zeh֙ ţéֽ̇ẕĕʼi֔y wĕ⁠yáda֖yi⁠kĕ ʻal-ròʼşé֑̌⁠kĕ kiֽ̇y-máʼa֤s yĕhòwáh֙ bĕ̇⁠mibĕtaẖa֔yi⁠kĕ wĕ⁠lò֥ʼ ţaẕĕli֖yẖiy lá⁠heֽm׃"],[3,1,"לֵ⁠אמֹ֡ר הֵ֣ן יְשַׁלַּ֣ח אִ֣ישׁ אֶת־אִשְׁתּ⁠וֹ֩ וְ⁠הָלְכָ֨ה מֵ⁠אִתּ֜⁠וֹ וְ⁠הָיְתָ֣ה לְ⁠אִישׁ־אַחֵ֗ר הֲ⁠יָשׁ֤וּב אֵלֶ֨י⁠הָ֙ ע֔וֹד הֲ⁠ל֛וֹא חָנ֥וֹף תֶּחֱנַ֖ף הָ⁠אָ֣רֶץ הַ⁠הִ֑יא וְ⁠אַ֗תְּ זָנִית֙ רֵעִ֣ים רַבִּ֔ים וְ⁠שׁ֥וֹב אֵלַ֖⁠י נְאֻם־יְהֹוָֽה׃","lé⁠ʼmò֡r hé֣n yĕşǎlȧ֣ẖ ʼi֣yş̌ ʼeţ-ʼişĕ̌ţ̇⁠wò֩ wĕ⁠hálĕká֨h mé⁠ʼiţ̇֜⁠wò wĕ⁠háyĕţá֣h lĕ⁠ʼiyş̌-ʼaẖé֗r hà⁠yáş֤̌ẇb ʼéle֨y⁠há֙ ʻ֔wòd hà⁠l֛wòʼ ẖán֥wòp ţėẖèna֖p há⁠ʼá֣reẕ ha⁠hi֑yʼ wĕ⁠ʼa֗ţĕ̇ zániyţ֙ réʻi֣ym rabi̇֔ym wĕ⁠ş֥̌wòb ʼéla֖⁠y nĕʼum-yĕhòwáֽh׃"],[3,2,"שְׂאִֽי־עֵינַ֨יִ⁠ךְ עַל־שְׁפָיִ֜ם וּ⁠רְאִ֗י אֵיפֹה֙ לֹ֣א שגלת עַל־דְּרָכִים֙ יָשַׁ֣בְתְּ לָ⁠הֶ֔ם כַּ⁠עֲרָבִ֖י בַּ⁠מִּדְבָּ֑ר וַ⁠תַּחֲנִ֣יפִי אֶ֔רֶץ בִּ⁠זְנוּתַ֖יִ⁠ךְ וּ⁠בְ⁠רָעָתֵֽ⁠ךְ׃","şĕ̂ʼiֽy-ʻéyna֨yi⁠kĕ ʻal-şĕ̌páyi֜m ẇ⁠rĕʼi֗y ʼéypòh֙ lò֣ʼ şglţ ʻal-dĕ̇rákiym֙ yáşǎ֣bĕţĕ̇ lá⁠he֔m kȧ⁠ʻàrábi֖y bȧ⁠mi̇dĕbá֑̇r wa⁠ţȧẖàni֣ypiy ʼe֔reẕ bi̇⁠zĕnẇţa֖yi⁠kĕ ẇ⁠bĕ⁠ráʻáţéֽ⁠kĕ׃"],[3,3,"וַ⁠יִּמָּנְע֣וּ רְבִבִ֔ים וּ⁠מַלְק֖וֹשׁ ל֣וֹא הָיָ֑ה וּ⁠מֵ֨צַח אִשָּׁ֤ה זוֹנָה֙ הָ֣יָה לָ֔⁠ךְ מֵאַ֖נְתְּ הִכָּלֵֽם׃","wa⁠yi̇má̇nĕʻ֣ẇ rĕbibi֔ym ẇ⁠malĕq֖wòş̌ l֣wòʼ háyá֑h ẇ⁠mé֨ẕaẖ ʼişá֤̇̌h zwònáh֙ há֣yáh lá֔⁠kĕ méʼa֖nĕţĕ̇ hiká̇léֽm׃"],[3,4,"הֲ⁠ל֣וֹא מֵ⁠עַ֔תָּה קראתי לִ֖⁠י אָבִ֑⁠י אַלּ֥וּף נְעֻרַ֖⁠י אָֽתָּה׃","hà⁠l֣wòʼ mé⁠ʻa֔ţá̇h qrʼţy li֖⁠y ʼábi֑⁠y ʼal֥̇ẇp nĕʻura֖⁠y ʼáֽţá̇h׃"],[3,5,"הֲ⁠יִנְטֹ֣ר לְ⁠עוֹלָ֔ם אִם־יִשְׁמֹ֖ר לָ⁠נֶ֑צַח הִנֵּ֥ה דברתי וַ⁠תַּעֲשִׂ֥י הָ⁠רָע֖וֹת וַ⁠תּוּכָֽל׃פ","hà⁠yinĕtò֣r lĕ⁠ʻwòlá֔m ʼim-yişĕ̌mò֖r lá⁠ne֑ẕaẖ hiné֥̇h dbrţy wa⁠ţȧʻàşî֥y há⁠ráʻ֖wòţ wa⁠ţ̇ẇkáֽl׃p"],[3,6,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י בִּ⁠ימֵי֙ יֹאשִׁיָּ֣הוּ הַ⁠מֶּ֔לֶךְ הֲֽ⁠רָאִ֔יתָ אֲשֶׁ֥ר עָשְׂתָ֖ה מְשֻׁבָ֣ה יִשְׂרָאֵ֑ל הֹלְכָ֨ה הִ֜יא עַל־כָּל־הַ֣ר גָּבֹ֗הַּ וְ⁠אֶל־תַּ֛חַת כָּל־עֵ֥ץ רַעֲנָ֖ן וַ⁠תִּזְנִי־שָֽׁם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y bi̇⁠yméy֙ yòʼşǐyá֣̇hẇ ha⁠mė֔lekĕ hàֽ⁠ráʼi֔yţá ʼàşě֥r ʻáşĕ̂ţá֖h mĕşǔbá֣h yişĕ̂ráʼé֑l hòlĕká֨h hi֜yʼ ʻal-ká̇l-ha֣r gá̇bò֗hȧ wĕ⁠ʼel-ţȧ֛ẖaţ ká̇l-ʻé֥ẕ raʻàná֖n wa⁠ţi̇zĕniy-şáֽ̌m׃"],[3,7,"וָ⁠אֹמַ֗ר אַחֲרֵ֨י עֲשׂוֹתָ֧⁠הּ אֶת־כָּל־אֵ֛לֶּה אֵלַ֥⁠י תָּשׁ֖וּב וְ⁠לֹא־שָׁ֑בָה ו⁠תראה בָּגוֹדָ֥ה אֲחוֹתָ֖⁠הּ יְהוּדָֽה׃","wá⁠ʼòma֗r ʼaẖàré֨y ʻàş̂wòţá֧⁠ḣ ʼeţ-ká̇l-ʼé֛lėh ʼéla֥⁠y ţá̇ş֖̌ẇb wĕ⁠lòʼ-şá֑̌báh w⁠ţrʼh bá̇gwòdá֥h ʼàẖwòţá֖⁠ḣ yĕhẇdáֽh׃"],[3,8,"וָ⁠אֵ֗רֶא כִּ֤י עַל־כָּל־אֹדוֹת֙ אֲשֶׁ֤ר נִֽאֲפָה֙ מְשֻׁבָ֣ה יִשְׂרָאֵ֔ל שִׁלַּחְתִּ֕י⁠הָ וָ⁠אֶתֵּ֛ן אֶת־סֵ֥פֶר כְּרִיתֻתֶ֖י⁠הָ אֵלֶ֑י⁠הָ וְ⁠לֹ֨א יָֽרְאָ֜ה בֹּֽגֵדָ֤ה יְהוּדָה֙ אֲחוֹתָ֔⁠הּ וַ⁠תֵּ֖לֶךְ וַ⁠תִּ֥זֶן גַּם־הִֽיא׃","wá⁠ʼé֗reʼ ki֤̇y ʻal-ká̇l-ʼòdwòţ֙ ʼàşě֤r niֽʼàpáh֙ mĕşǔbá֣h yişĕ̂ráʼé֔l şǐlȧẖĕţi̇֕y⁠há wá⁠ʼeţé֛̇n ʼeţ-sé֥per kĕ̇riyţuţe֖y⁠há ʼéle֑y⁠há wĕ⁠lò֨ʼ yáֽrĕʼá֜h bòֽ̇gédá֤h yĕhẇdáh֙ ʼàẖwòţá֔⁠ḣ wa⁠ţé֖̇lekĕ wa⁠ţi֥̇zen gȧm-hiֽyʼ׃"],[3,9,"וְ⁠הָיָה֙ מִ⁠קֹּ֣ל זְנוּתָ֔⁠הּ וַ⁠תֶּחֱנַ֖ף אֶת־הָ⁠אָ֑רֶץ וַ⁠תִּנְאַ֥ף אֶת־הָ⁠אֶ֖בֶן וְ⁠אֶת־הָ⁠עֵֽץ׃","wĕ⁠háyáh֙ mi⁠qò֣̇l zĕnẇţá֔⁠ḣ wa⁠ţėẖèna֖p ʼeţ-há⁠ʼá֑reẕ wa⁠ţi̇nĕʼa֥p ʼeţ-há⁠ʼe֖ben wĕ⁠ʼeţ-há⁠ʻéֽẕ׃"],[3,10,"וְ⁠גַם־בְּ⁠כָל־זֹ֗את לֹא־שָׁ֨בָה אֵלַ֜⁠י בָּגוֹדָ֧ה אֲחוֹתָ֛⁠הּ יְהוּדָ֖ה בְּ⁠כָל־לִבָּ֑⁠הּ כִּ֥י אִם־בְּ⁠שֶׁ֖קֶר נְאֻם־יְהוָֽה׃פ","wĕ⁠gam-bĕ̇⁠kál-zò֗ʼţ lòʼ-şá̌֨báh ʼéla֜⁠y bá̇gwòdá֧h ʼàẖwòţá֛⁠ḣ yĕhẇdá֖h bĕ̇⁠kál-libá֑̇⁠ḣ ki֥̇y ʼim-bĕ̇⁠şě֖qer nĕʼum-yĕhwáֽh׃p"],[3,11,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י צִדְּקָ֥ה נַפְשָׁ֖⁠הּ מְשֻׁבָ֣ה יִשְׂרָאֵ֑ל מִ⁠בֹּגֵדָ֖ה יְהוּדָֽה׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y ẕidĕ̇qá֥h napĕşá֖̌⁠ḣ mĕşǔbá֣h yişĕ̂ráʼé֑l mi⁠bò̇gédá֖h yĕhẇdáֽh׃"],[3,12,"הָלֹ֡ךְ וְ⁠קָֽרָאתָ֩ אֶת־הַ⁠דְּבָרִ֨ים הָ⁠אֵ֜לֶּה צָפ֗וֹנָ⁠ה וְ֠⁠אָמַרְתָּ שׁ֣וּבָ⁠ה מְשֻׁבָ֤ה יִשְׂרָאֵל֙ נְאֻם־יְהוָ֔ה לֽוֹא־אַפִּ֥יל פָּנַ֖⁠י בָּ⁠כֶ֑ם כִּֽי־חָסִ֤יד אֲנִי֙ נְאֻם־יְהוָ֔ה לֹ֥א אֶטּ֖וֹר לְ⁠עוֹלָֽם׃","hálò֡kĕ wĕ⁠qֽáráʼţá֩ ʼeţ-ha⁠dĕ̇bári֨ym há⁠ʼé֜lėh ẕáp֗wòná⁠h wĕ֠⁠ʼámarĕţá̇ ş֣̌ẇbá⁠h mĕşǔbá֤h yişĕ̂ráʼél֙ nĕʼum-yĕhwá֔h lֽwòʼ-ʼapi֥̇yl pá̇na֖⁠y bá̇⁠ke֑m kiֽ̇y-ẖási֤yd ʼàniy֙ nĕʼum-yĕhwá֔h lò֥ʼ ʼeṫ֖wòr lĕ⁠ʻwòláֽm׃"],[3,13,"אַ֚ךְ דְּעִ֣י עֲוֺנֵ֔⁠ךְ כִּ֛י בַּ⁠יהוָ֥ה אֱלֹהַ֖יִ⁠ךְ פָּשָׁ֑עַתְּ וַ⁠תְּפַזְּרִ֨י אֶת־דְּרָכַ֜יִ⁠ךְ לַ⁠זָּרִ֗ים תַּ֚חַת כָּל־עֵ֣ץ רַעֲנָ֔ן וּ⁠בְ⁠קוֹלִ֥⁠י לֹא־שְׁמַעְתֶּ֖ם נְאֻם־יְהֹוָֽה׃","ʼa֚kĕ dĕ̇ʻi֣y ʻàwֺné֔⁠kĕ ki֛̇y bȧ⁠yhwá֥h ʼèlòha֖yi⁠kĕ pá̇şá֑̌ʻaţĕ̇ wa⁠ţĕ̇pazĕ̇ri֨y ʼeţ-dĕ̇ráka֜yi⁠kĕ la⁠zá̇ri֗ym ţȧ֚ẖaţ ká̇l-ʻé֣ẕ raʻàná֔n ẇ⁠bĕ⁠qwòli֥⁠y lòʼ-şĕ̌maʻĕţė֖m nĕʼum-yĕhòwáֽh׃"],[3,14,"שׁ֣וּבוּ בָנִ֤ים שׁוֹבָבִים֙ נְאֻם־יְהוָ֔ה כִּ֥י אָנֹכִ֖י בָּעַ֣לְתִּי בָ⁠כֶ֑ם וְ⁠לָקַחְתִּ֨י אֶתְ⁠כֶ֜ם אֶחָ֣ד מֵ⁠עִ֗יר וּ⁠שְׁנַ֨יִם֙ מִ⁠מִּשְׁפָּחָ֔ה וְ⁠הֵבֵאתִ֥י אֶתְ⁠כֶ֖ם צִיּֽוֹן׃","ş֣̌ẇbẇ báni֤ym ş̌wòbábiym֙ nĕʼum-yĕhwá֔h ki֥̇y ʼánòki֖y bá̇ʻa֣lĕţi̇y bá⁠ke֑m wĕ⁠láqaẖĕţi̇֨y ʼeţĕ⁠ke֜m ʼeẖá֣d mé⁠ʻi֗yr ẇ⁠şĕ̌na֨yim֙ mi⁠mi̇şĕ̌pá̇ẖá֔h wĕ⁠hébéʼţi֥y ʼeţĕ⁠ke֖m ẕiẏֽwòn׃"],[3,15,"וְ⁠נָתַתִּ֥י לָ⁠כֶ֛ם רֹעִ֖ים כְּ⁠לִבִּ֑⁠י וְ⁠רָע֥וּ אֶתְ⁠כֶ֖ם דֵּעָ֥ה וְ⁠הַשְׂכֵּֽיל׃","wĕ⁠náţaţi֥̇y lá⁠ke֛m ròʻi֖ym kĕ̇⁠libi֑̇⁠y wĕ⁠ráʻ֥ẇ ʼeţĕ⁠ke֖m dé̇ʻá֥h wĕ⁠haşĕ̂kéֽ̇yl׃"],[3,16,"וְ⁠הָיָ֡ה כִּ֣י תִרְבּוּ֩ וּ⁠פְרִיתֶ֨ם בָּ⁠אָ֜רֶץ בַּ⁠יָּמִ֤ים הָ⁠הֵ֨מָּה֙ נְאֻם־יְהוָ֔ה לֹא־יֹ֣אמְרוּ ע֗וֹד אֲרוֹן֙ בְּרִית־יְהוָ֔ה וְ⁠לֹ֥א יַעֲלֶ֖ה עַל־לֵ֑ב וְ⁠לֹ֤א יִזְכְּרוּ־ב⁠וֹ֙ וְ⁠לֹ֣א יִפְקֹ֔דוּ וְ⁠לֹ֥א יֵעָשֶׂ֖ה עֽוֹד׃","wĕ⁠háyá֡h ki֣̇y ţirĕḃẇ֩ ẇ⁠pĕriyţe֨m bá̇⁠ʼá֜reẕ bȧ⁠yá̇mi֤ym há⁠hé֨má̇h֙ nĕʼum-yĕhwá֔h lòʼ-yò֣ʼmĕrẇ ʻ֗wòd ʼàrwòn֙ bĕ̇riyţ-yĕhwá֔h wĕ⁠lò֥ʼ yaʻàle֖h ʻal-lé֑b wĕ⁠lò֤ʼ yizĕkĕ̇rẇ-b⁠wò֙ wĕ⁠lò֣ʼ yipĕqò֔dẇ wĕ⁠lò֥ʼ yéʻáşê֖h ʻֽwòd׃"],[3,17,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא יִקְרְא֤וּ לִ⁠ירוּשָׁלִַ֨ם֙ כִּסֵּ֣א יְהוָ֔ה וְ⁠נִקְוּ֨וּ אֵלֶ֧י⁠הָ כָֽל־הַ⁠גּוֹיִ֛ם לְ⁠שֵׁ֥ם יְהוָ֖ה לִ⁠ירוּשָׁלִָ֑ם וְ⁠לֹא־יֵלְכ֣וּ ע֔וֹד אַחֲרֵ֕י שְׁרִר֖וּת לִבָּ֥⁠ם הָ⁠רָֽע׃ס","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ yiqĕrĕʼ֤ẇ li⁠yrẇşá̌lia֨m֙ ki̇sé֣̇ʼ yĕhwá֔h wĕ⁠niqĕẇ֨ẇ ʼéle֧y⁠há káֽl-ha⁠ġwòyi֛m lĕ⁠şé֥̌m yĕhwá֖h li⁠yrẇşá̌liá֑m wĕ⁠lòʼ-yélĕk֣ẇ ʻ֔wòd ʼaẖàré֕y şĕ̌rir֖ẇţ libá֥̇⁠m há⁠ráֽʻ׃s"],[3,18,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔מָּה יֵלְכ֥וּ בֵית־יְהוּדָ֖ה עַל־בֵּ֣ית יִשְׂרָאֵ֑ל וְ⁠יָבֹ֤אוּ יַחְדָּו֙ מֵ⁠אֶ֣רֶץ צָפ֔וֹן עַל־הָ⁠אָ֕רֶץ אֲשֶׁ֥ר הִנְחַ֖לְתִּי אֶת־אֲבוֹתֵי⁠כֶֽם׃","bȧ⁠yá̇mi֣ym há⁠hé֔má̇h yélĕk֥ẇ béyţ-yĕhẇdá֖h ʻal-bé֣̇yţ yişĕ̂ráʼé֑l wĕ⁠yábò֤ʼẇ yaẖĕdá̇w֙ mé⁠ʼe֣reẕ ẕáp֔wòn ʻal-há⁠ʼá֕reẕ ʼàşě֥r hinĕẖa֖lĕţi̇y ʼeţ-ʼàbwòţéy⁠keֽm׃"],[3,19,"וְ⁠אָנֹכִ֣י אָמַ֗רְתִּי אֵ֚יךְ אֲשִׁיתֵ֣⁠ךְ בַּ⁠בָּנִ֔ים וְ⁠אֶתֶּן־לָ⁠ךְ֙ אֶ֣רֶץ חֶמְדָּ֔ה נַחֲלַ֥ת צְבִ֖י צִבְא֣וֹת גּוֹיִ֑ם וָ⁠אֹמַ֗ר אָבִ⁠י֙ תקראו־לִ֔⁠י וּ⁠מֵ⁠אַחֲרַ֖⁠י לֹ֥א תשובו׃","wĕ⁠ʼánòki֣y ʼáma֗rĕţi̇y ʼé֚ykĕ ʼàşǐyţé֣⁠kĕ bȧ⁠bá̇ni֔ym wĕ⁠ʼeţėn-lá⁠kĕ֙ ʼe֣reẕ ẖemĕdá̇֔h naẖàla֥ţ ẕĕbi֖y ẕibĕʼ֣wòţ ġwòyi֑m wá⁠ʼòma֗r ʼábi⁠y֙ ţqrʼw-li֔⁠y ẇ⁠mé⁠ʼaẖàra֖⁠y lò֥ʼ ţşwbw׃"],[3,20,"אָכֵ֛ן בָּגְדָ֥ה אִשָּׁ֖ה מֵ⁠רֵעָ֑⁠הּ כֵּ֣ן בְּגַדְתֶּ֥ם בִּ֛⁠י בֵּ֥ית יִשְׂרָאֵ֖ל נְאֻם־יְהוָֽה׃","ʼáké֛n bá̇gĕdá֥h ʼişá֖̇̌h mé⁠réʻá֑⁠ḣ ké֣̇n bĕ̇gadĕţė֥m bi֛̇⁠y bé֥̇yţ yişĕ̂ráʼé֖l nĕʼum-yĕhwáֽh׃"],[3,21,"ק֚וֹל עַל־שְׁפָיִ֣ים נִשְׁמָ֔ע בְּכִ֥י תַחֲנוּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל כִּ֤י הֶעֱוּוּ֙ אֶת־דַּרְכָּ֔⁠ם שָׁכְח֖וּ אֶת־יְהֹוָ֥ה אֱלֹהֵי⁠הֶֽם׃","q֚wòl ʻal-şĕ̌páyi֣ym nişĕ̌má֔ʻ bĕ̇ki֥y ţaẖànẇné֖y bĕ̇né֣y yişĕ̂ráʼé֑l ki֤̇y heʻèẇẇ֙ ʼeţ-dȧrĕká̇֔⁠m şá̌kĕẖ֖ẇ ʼeţ-yĕhòwá֥h ʼèlòhéy⁠heֽm׃"],[3,22,"שׁ֚וּבוּ בָּנִ֣ים שׁוֹבָבִ֔ים אֶרְפָּ֖ה מְשׁוּבֹֽתֵי⁠כֶ֑ם הִנְ⁠נוּ֙ אָתָ֣נוּ לָ֔⁠ךְ כִּ֥י אַתָּ֖ה יְהֹוָ֥ה אֱלֹהֵֽי⁠נוּ׃","ş֚̌ẇbẇ bá̇ni֣ym ş̌wòbábi֔ym ʼerĕpá֖̇h mĕş̌ẇbòֽţéy⁠ke֑m hinĕ⁠nẇ֙ ʼáţá֣nẇ lá֔⁠kĕ ki֥̇y ʼaţá֖̇h yĕhòwá֥h ʼèlòhéֽy⁠nẇ׃"],[3,23,"אָכֵ֥ן לַ⁠שֶּׁ֛קֶר מִ⁠גְּבָע֖וֹת הָמ֣וֹן הָרִ֑ים אָכֵן֙ בַּ⁠יהֹוָ֣ה אֱלֹהֵ֔י⁠נוּ תְּשׁוּעַ֖ת יִשְׂרָאֵֽל׃","ʼáké֥n la⁠şė֛̌qer mi⁠gĕ̇báʻ֖wòţ hám֣wòn hári֑ym ʼákén֙ bȧ⁠yhòwá֣h ʼèlòhé֔y⁠nẇ ţĕ̇ş̌ẇʻa֖ţ yişĕ̂ráʼéֽl׃"],[3,24,"וְ⁠הַ⁠בֹּ֗שֶׁת אָֽכְלָ֛ה אֶת־יְגִ֥יעַ אֲבוֹתֵ֖י⁠נוּ מִ⁠נְּעוּרֵ֑י⁠נוּ אֶת־צֹאנָ⁠ם֙ וְ⁠אֶת־בְּקָרָ֔⁠ם אֶת־בְּנֵי⁠הֶ֖ם וְ⁠אֶת־בְּנוֹתֵי⁠הֶֽם׃","wĕ⁠ha⁠bò̇֗şěţ ʼáֽkĕlá֛h ʼeţ-yĕgi֥yʻa ʼàbwòţé֖y⁠nẇ mi⁠nĕ̇ʻẇré֑y⁠nẇ ʼeţ-ẕòʼná⁠m֙ wĕ⁠ʼeţ-bĕ̇qárá֔⁠m ʼeţ-bĕ̇néy⁠he֖m wĕ⁠ʼeţ-bĕ̇nwòţéy⁠heֽm׃"],[3,25,"נִשְׁכְּבָ֣ה בְּ⁠בָשְׁתֵּ֗⁠נוּ וּֽ⁠תְכַסֵּ⁠נוּ֮ כְּלִמָּתֵ⁠נוּ֒ כִּי֩ לַ⁠יהוָ֨ה אֱלֹהֵ֜י⁠נוּ חָטָ֗אנוּ אֲנַ֨חְנוּ֙ וַ⁠אֲבוֹתֵ֔י⁠נוּ מִ⁠נְּעוּרֵ֖י⁠נוּ וְ⁠עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וְ⁠לֹ֣א שָׁמַ֔עְנוּ בְּ⁠ק֖וֹל יְהֹוָ֥ה אֱלֹהֵֽי⁠נוּ׃ס","nişĕ̌kĕ̇bá֣h bĕ̇⁠báşĕ̌ţé̇֗⁠nẇ ẇֽ⁠ţĕkasé̇⁠nẇ֮ kĕ̇limá̇ţé⁠nẇ֒ ki̇y֩ la⁠yhwá֨h ʼèlòhé֜y⁠nẇ ẖátá֗ʼnẇ ʼàna֨ẖĕnẇ֙ wa⁠ʼàbwòţé֔y⁠nẇ mi⁠nĕ̇ʻẇré֖y⁠nẇ wĕ⁠ʻad-ha⁠ẏ֣wòm ha⁠zė֑h wĕ⁠lò֣ʼ şá̌ma֔ʻĕnẇ bĕ̇⁠q֖wòl yĕhòwá֥h ʼèlòhéֽy⁠nẇ׃s"],[4,1,"אִם־תָּשׁ֨וּב יִשְׂרָאֵ֧ל ׀ נְאֻם־יְהוָ֛ה אֵלַ֖⁠י תָּשׁ֑וּב וְ⁠אִם־תָּסִ֧יר שִׁקּוּצֶ֛י⁠ךָ מִ⁠פָּנַ֖⁠י וְ⁠לֹ֥א תָנֽוּד׃","ʼim-ţá̇ş̌֨ẇb yişĕ̂ráʼé֧l ׀ nĕʼum-yĕhwá֛h ʼéla֖⁠y ţá̇ş֑̌ẇb wĕ⁠ʼim-ţá̇si֧yr şǐq̇ẇẕe֛y⁠ká mi⁠pá̇na֖⁠y wĕ⁠lò֥ʼ ţánֽẇd׃"],[4,2,"וְ⁠נִשְׁבַּ֨עְתָּ֙ חַי־יְהוָ֔ה בֶּ⁠אֱמֶ֖ת בְּ⁠מִשְׁפָּ֣ט וּ⁠בִ⁠צְדָקָ֑ה וְ⁠הִתְבָּ֥רְכוּ ב֛⁠וֹ גּוֹיִ֖ם וּ⁠ב֥⁠וֹ יִתְהַלָּֽלוּ׃ס","wĕ⁠nişĕ̌bȧ֨ʻĕţá̇֙ ẖay-yĕhwá֔h bė⁠ʼème֖ţ bĕ̇⁠mişĕ̌pá֣̇t ẇ⁠bi⁠ẕĕdáqá֑h wĕ⁠hiţĕbá֥̇rĕkẇ b֛⁠wò ġwòyi֖m ẇ⁠b֥⁠wò yiţĕhaláֽ̇lẇ׃s"],[4,3,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהֹוָ֗ה לְ⁠אִ֤ישׁ יְהוּדָה֙ וְ⁠לִ⁠יר֣וּשָׁלִַ֔ם נִ֥ירוּ לָ⁠כֶ֖ם נִ֑יר וְ⁠אַֽל־תִּזְרְע֖וּ אֶל־קוֹצִֽים׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhòwá֗h lĕ⁠ʼi֤yş̌ yĕhẇdáh֙ wĕ⁠li⁠yr֣ẇşá̌lia֔m ni֥yrẇ lá⁠ke֖m ni֑yr wĕ⁠ʼaֽl-ţi̇zĕrĕʻ֖ẇ ʼel-qwòẕiֽym׃"],[4,4,"הִמֹּ֣לוּ לַ⁠יהֹוָ֗ה וְ⁠הָסִ֨רוּ֙ עָרְל֣וֹת לְבַבְ⁠כֶ֔ם אִ֥ישׁ יְהוּדָ֖ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם פֶּן־תֵּצֵ֨א כָ⁠אֵ֜שׁ חֲמָתִ֗⁠י וּ⁠בָעֲרָה֙ וְ⁠אֵ֣ין מְכַבֶּ֔ה מִ⁠פְּנֵ֖י רֹ֥עַ מַעַלְלֵי⁠כֶֽם׃","himò֣̇lẇ la⁠yhòwá֗h wĕ⁠hási֨rẇ֙ ʻárĕl֣wòţ lĕbabĕ⁠ke֔m ʼi֥yş̌ yĕhẇdá֖h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌liá֑m pėn-ţé̇ẕé֨ʼ ká⁠ʼé֜ş̌ ẖàmáţi֗⁠y ẇ⁠báʻàráh֙ wĕ⁠ʼé֣yn mĕkabė֔h mi⁠pĕ̇né֖y rò֥ʻa maʻalĕléy⁠keֽm׃"],[4,5,"הַגִּ֣ידוּ בִֽ⁠יהוּדָ֗ה וּ⁠בִ⁠ירוּשָׁלִַ֨ם֙ הַשְׁמִ֔יעוּ וְ⁠אִמְר֕וּ ו⁠תקעו שׁוֹפָ֖ר בָּ⁠אָ֑רֶץ קִרְא֤וּ מַלְאוּ֙ וְ⁠אִמְר֔וּ הֵאָסְפ֥וּ וְ⁠נָב֖וֹאָה אֶל־עָרֵ֥י הַ⁠מִּבְצָֽר׃","hagi֣̇ydẇ biֽ⁠yhẇdá֗h ẇ⁠bi⁠yrẇşá̌lia֨m֙ haşĕ̌mi֔yʻẇ wĕ⁠ʼimĕr֕ẇ w⁠ţqʻw ş̌wòpá֖r bá̇⁠ʼá֑reẕ qirĕʼ֤ẇ malĕʼẇ֙ wĕ⁠ʼimĕr֔ẇ héʼásĕp֥ẇ wĕ⁠náb֖wòʼáh ʼel-ʻáré֥y ha⁠mi̇bĕẕáֽr׃"],[4,6,"שְׂאוּ־נֵ֣ס צִיּ֔וֹנָ⁠ה הָעִ֖יזוּ אַֽל־תַּעֲמֹ֑דוּ כִּ֣י רָעָ֗ה אָנֹכִ֛י מֵבִ֥יא מִ⁠צָּפ֖וֹן וְ⁠שֶׁ֥בֶר גָּדֽוֹל׃","şĕ̂ʼẇ-né֣s ẕiẏ֔wòná⁠h háʻi֖yzẇ ʼaֽl-ţȧʻàmò֑dẇ ki֣̇y ráʻá֗h ʼánòki֛y mébi֥yʼ mi⁠ẕá̇p֖wòn wĕ⁠şě֥ber gá̇dֽwòl׃"],[4,7,"עָלָ֤ה אַרְיֵה֙ מִֽ⁠סֻּבְּכ֔⁠וֹ וּ⁠מַשְׁחִ֣ית גּוֹיִ֔ם נָסַ֖ע יָצָ֣א מִ⁠מְּקֹמ֑⁠וֹ לָ⁠שׂ֤וּם אַרְצֵ⁠ךְ֙ לְ⁠שַׁמָּ֔ה עָרַ֥יִ⁠ךְ תִּצֶּ֖ינָה מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","ʻálá֤h ʼarĕyéh֙ miֽ⁠su̇bĕ̇k֔⁠wò ẇ⁠maşĕ̌ẖi֣yţ ġwòyi֔m nása֖ʻ yáẕá֣ʼ mi⁠mĕ̇qòm֑⁠wò lá⁠ş֤̂ẇm ʼarĕẕé⁠kĕ֙ lĕ⁠şǎmá̇֔h ʻára֥yi⁠kĕ ţi̇ẕė֖ynáh mé⁠ʼé֥yn ywòşéֽ̌b׃"],[4,8,"עַל־זֹ֛את חִגְר֥וּ שַׂקִּ֖ים סִפְד֣וּ וְ⁠הֵילִ֑ילוּ כִּ֥י לֹא־שָׁ֛ב חֲר֥וֹן אַף־יְהֹוָ֖ה מִמֶּֽ⁠נּוּ׃פ","ʻal-zò֛ʼţ ẖigĕr֥ẇ şâqi֖̇ym sipĕd֣ẇ wĕ⁠héyli֑ylẇ ki֥̇y lòʼ-şá֛̌b ẖàr֥wòn ʼap-yĕhòwá֖h mimėֽ⁠ṅẇ׃p"],[4,9,"וְ⁠הָיָ֤ה בַ⁠יּוֹם־הַ⁠הוּא֙ נְאֻם־יְהוָ֔ה יֹאבַ֥ד לֵב־הַ⁠מֶּ֖לֶךְ וְ⁠לֵ֣ב הַ⁠שָּׂרִ֑ים וְ⁠נָשַׁ֨מּוּ֙ הַ⁠כֹּ֣הֲנִ֔ים וְ⁠הַ⁠נְּבִיאִ֖ים יִתְמָֽהוּ׃","wĕ⁠háyá֤h ba⁠ẏwòm-ha⁠hẇʼ֙ nĕʼum-yĕhwá֔h yòʼba֥d léb-ha⁠mė֖lekĕ wĕ⁠lé֣b ha⁠şá̇̂ri֑ym wĕ⁠náşǎ֨ṁẇ֙ ha⁠kò֣̇hàni֔ym wĕ⁠ha⁠nĕ̇biyʼi֖ym yiţĕmáֽhẇ׃"],[4,10,"וָ⁠אֹמַ֞ר אֲהָ֣הּ ׀ אֲדֹנָ֣⁠י יְהוִ֗ה אָכֵן֩ הַשֵּׁ֨א הִשֵּׁ֜אתָ לָ⁠עָ֤ם הַ⁠זֶּה֙ וְ⁠לִ⁠ירוּשָׁלִַ֣ם לֵ⁠אמֹ֔ר שָׁל֖וֹם יִהְיֶ֣ה לָ⁠כֶ֑ם וְ⁠נָגְעָ֥ה חֶ֖רֶב עַד־הַ⁠נָּֽפֶשׁ׃","wá⁠ʼòma֞r ʼàhá֣ḣ ׀ ʼàdòná֣⁠y yĕhwi֗h ʼákén֩ haşé̇̌֨ʼ hişé̇̌֜ʼţá lá⁠ʻá֤m ha⁠zėh֙ wĕ⁠li⁠yrẇşá̌lia֣m lé⁠ʼmò֔r şá̌l֖wòm yihĕye֣h lá⁠ke֑m wĕ⁠nágĕʻá֥h ẖe֖reb ʻad-ha⁠náֽ̇peş̌׃"],[4,11,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא יֵאָמֵ֤ר לָֽ⁠עָם־הַ⁠זֶּה֙ וְ⁠לִ⁠יר֣וּשָׁלִַ֔ם ר֣וּחַ צַ֤ח שְׁפָיִים֙ בַּ⁠מִּדְבָּ֔ר דֶּ֖רֶךְ בַּת־עַמִּ֑⁠י ל֥וֹא לִ⁠זְר֖וֹת וְ⁠ל֥וֹא לְ⁠הָבַֽר׃","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ yéʼámé֤r láֽ⁠ʻám-ha⁠zėh֙ wĕ⁠li⁠yr֣ẇşá̌lia֔m r֣ẇẖa ẕa֤ẖ şĕ̌páyiym֙ bȧ⁠mi̇dĕbá̇֔r dė֖rekĕ bȧţ-ʻami֑̇⁠y l֥wòʼ li⁠zĕr֖wòţ wĕ⁠l֥wòʼ lĕ⁠hábaֽr׃"],[4,12,"ר֧וּחַ מָלֵ֛א מֵ⁠אֵ֖לֶּה יָ֣בוֹא לִ֑⁠י עַתָּ֕ה גַּם־אֲנִ֛י אֲדַבֵּ֥ר מִשְׁפָּטִ֖ים אוֹתָֽ⁠ם׃","r֧ẇẖa málé֛ʼ mé⁠ʼé֖lėh yá֣bwòʼ li֑⁠y ʻaţá̇֕h gȧm-ʼàni֛y ʼàdabé֥̇r mişĕ̌pá̇ti֖ym ʼwòţáֽ⁠m׃"],[4,13,"הִנֵּ֣ה ׀ כַּ⁠עֲנָנִ֣ים יַעֲלֶ֗ה וְ⁠כַ⁠סּוּפָה֙ מַרְכְּבוֹתָ֔י⁠ו קַלּ֥וּ מִ⁠נְּשָׁרִ֖ים סוּסָ֑י⁠ו א֥וֹי לָ֖⁠נוּ כִּ֥י שֻׁדָּֽדְנוּ׃","hiné֣̇h ׀ kȧ⁠ʻànáni֣ym yaʻàle֗h wĕ⁠ka⁠ṡẇpáh֙ marĕkĕ̇bwòţá֔y⁠w qal֥̇ẇ mi⁠nĕ̇şá̌ri֖ym sẇsá֑y⁠w ʼ֥wòy lá֖⁠nẇ ki֥̇y şǔdáֽ̇dĕnẇ׃"],[4,14,"כַּבְּסִ֨י מֵ⁠רָעָ֤ה לִבֵּ⁠ךְ֙ יְר֣וּשָׁלִַ֔ם לְמַ֖עַן תִּוָּשֵׁ֑עִי עַד־מָתַ֛י תָּלִ֥ין בְּ⁠קִרְבֵּ֖⁠ךְ מַחְשְׁב֥וֹת אוֹנֵֽ⁠ךְ׃","kȧbĕ̇si֨y mé⁠ráʻá֤h libé̇⁠kĕ֙ yĕr֣ẇşá̌lia֔m lĕma֖ʻan ţi̇wá̇şé֑̌ʻiy ʻad-máţa֛y ţá̇li֥yn bĕ̇⁠qirĕbé֖̇⁠kĕ maẖĕşĕ̌b֥wòţ ʼwònéֽ⁠kĕ׃"],[4,15,"כִּ֛י ק֥וֹל מַגִּ֖יד מִ⁠דָּ֑ן וּ⁠מַשְׁמִ֥יעַ אָ֖וֶן מֵ⁠הַ֥ר אֶפְרָֽיִם׃","ki֛̇y q֥wòl magi֖̇yd mi⁠dá֑̇n ẇ⁠maşĕ̌mi֥yʻa ʼá֖wen mé⁠ha֥r ʼepĕráֽyim׃"],[4,16,"הַזְכִּ֣ירוּ לַ⁠גּוֹיִ֗ם הִנֵּה֙ הַשְׁמִ֣יעוּ עַל־יְרוּשָׁלִַ֔ם נֹצְרִ֥ים בָּאִ֖ים מֵ⁠אֶ֣רֶץ הַ⁠מֶּרְחָ֑ק וַֽ⁠יִּתְּנ֛וּ עַל־עָרֵ֥י יְהוּדָ֖ה קוֹלָֽ⁠ם׃","hazĕki֣̇yrẇ la⁠ġwòyi֗m hiné̇h֙ haşĕ̌mi֣yʻẇ ʻal-yĕrẇşá̌lia֔m nòẕĕri֥ym bá̇ʼi֖ym mé⁠ʼe֣reẕ ha⁠mėrĕẖá֑q waֽ⁠yi̇ţĕ̇n֛ẇ ʻal-ʻáré֥y yĕhẇdá֖h qwòláֽ⁠m׃"],[4,17,"כְּ⁠שֹׁמְרֵ֣י שָׂדַ֔י הָי֥וּ עָלֶ֖י⁠הָ מִ⁠סָּבִ֑יב כִּי־אֹתִ֥⁠י מָרָ֖תָה נְאֻם־יְהוָֽה׃","kĕ̇⁠şò̌mĕré֣y şá̂da֔y háy֥ẇ ʻále֖y⁠há mi⁠sá̇bi֑yb ki̇y-ʼòţi֥⁠y márá֖ţáh nĕʼum-yĕhwáֽh׃"],[4,18,"דַּרְכֵּ⁠ךְ֙ וּ⁠מַ֣עֲלָלַ֔יִ⁠ךְ עָשׂ֥וֹ אֵ֖לֶּה לָ֑⁠ךְ זֹ֤את רָעָתֵ⁠ךְ֙ כִּ֣י מָ֔ר כִּ֥י נָגַ֖ע עַד־לִבֵּֽ⁠ךְ׃ס","dȧrĕké̇⁠kĕ֙ ẇ⁠ma֣ʻàlála֔yi⁠kĕ ʻáş֥̂wò ʼé֖lėh lá֑⁠kĕ zò֤ʼţ ráʻáţé⁠kĕ֙ ki֣̇y má֔r ki֥̇y nága֖ʻ ʻad-libéֽ̇⁠kĕ׃s"],[4,19,"מֵעַ֣⁠י ׀ מֵעַ֨⁠י ׀ אחולה קִיר֥וֹת לִבִּ֛⁠י הֹֽמֶה־לִּ֥⁠י לִבִּ֖⁠י לֹ֣א אַחֲרִ֑ישׁ כִּ֣י ק֤וֹל שׁוֹפָר֙ שמעתי נַפְשִׁ֔⁠י תְּרוּעַ֖ת מִלְחָמָֽה׃","méʻa֣⁠y ׀ méʻa֨⁠y ׀ ʼẖwlh qiyr֥wòţ libi֛̇⁠y hòֽmeh-li֥̇⁠y libi֖̇⁠y lò֣ʼ ʼaẖàri֑yş̌ ki֣̇y q֤wòl ş̌wòpár֙ şmʻţy napĕşǐ֔⁠y ţĕ̇rẇʻa֖ţ milĕẖámáֽh׃"],[4,20,"שֶׁ֤בֶר עַל־שֶׁ֨בֶר֙ נִקְרָ֔א כִּ֥י שֻׁדְּדָ֖ה כָּל־הָ⁠אָ֑רֶץ פִּתְאֹם֙ שֻׁדְּד֣וּ אֹהָלַ֔⁠י רֶ֖גַע יְרִיעֹתָֽ⁠י׃","şě֤ber ʻal-şě֨ber֙ niqĕrá֔ʼ ki֥̇y şǔdĕ̇dá֖h ká̇l-há⁠ʼá֑reẕ pi̇ţĕʼòm֙ şǔdĕ̇d֣ẇ ʼòhála֔⁠y re֖gaʻ yĕriyʻòţáֽ⁠y׃"],[4,21,"עַד־מָתַ֖י אֶרְאֶה־נֵּ֑ס אֶשְׁמְעָ֖ה ק֥וֹל שׁוֹפָֽר׃ס","ʻad-máţa֖y ʼerĕʼeh-né֑̇s ʼeşĕ̌mĕʻá֖h q֥wòl ş̌wòpáֽr׃s"],[4,22,"כִּ֣י ׀ אֱוִ֣יל עַמִּ֗⁠י אוֹתִ⁠י֙ לֹ֣א יָדָ֔עוּ בָּנִ֤ים סְכָלִים֙ הֵ֔מָּה וְ⁠לֹ֥א נְבוֹנִ֖ים הֵ֑מָּה חֲכָמִ֥ים הֵ֨מָּה֙ לְ⁠הָרַ֔ע וּ⁠לְ⁠הֵיטִ֖יב לֹ֥א יָדָֽעוּ׃","ki֣̇y ׀ ʼèwi֣yl ʻami̇֗⁠y ʼwòţi⁠y֙ lò֣ʼ yádá֔ʻẇ bá̇ni֤ym sĕkáliym֙ hé֔má̇h wĕ⁠lò֥ʼ nĕbwòni֖ym hé֑má̇h ẖàkámi֥ym hé֨má̇h֙ lĕ⁠hára֔ʻ ẇ⁠lĕ⁠héyti֖yb lò֥ʼ yádáֽʻẇ׃"],[4,23,"רָאִ֨יתִי֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠הִנֵּה־תֹ֖הוּ וָ⁠בֹ֑הוּ וְ⁠אֶל־הַ⁠שָּׁמַ֖יִם וְ⁠אֵ֥ין אוֹרָֽ⁠ם׃","ráʼi֨yţiy֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠hiné̇h-ţò֖hẇ wá⁠bò֑hẇ wĕ⁠ʼel-ha⁠şá̇̌ma֖yim wĕ⁠ʼé֥yn ʼwòráֽ⁠m׃"],[4,24,"רָאִ֨יתִי֙ הֶֽ⁠הָרִ֔ים וְ⁠הִנֵּ֖ה רֹעֲשִׁ֑ים וְ⁠כָל־הַ⁠גְּבָע֖וֹת הִתְקַלְקָֽלוּ׃","ráʼi֨yţiy֙ heֽ⁠hári֔ym wĕ⁠hiné֖̇h ròʻàşǐ֑ym wĕ⁠kál-ha⁠gĕ̇báʻ֖wòţ hiţĕqalĕqáֽlẇ׃"],[4,25,"רָאִ֕יתִי וְ⁠הִנֵּ֖ה אֵ֣ין הָ⁠אָדָ֑ם וְ⁠כָל־ע֥וֹף הַ⁠שָּׁמַ֖יִם נָדָֽדוּ׃","ráʼi֕yţiy wĕ⁠hiné֖̇h ʼé֣yn há⁠ʼádá֑m wĕ⁠kál-ʻ֥wòp ha⁠şá̇̌ma֖yim nádáֽdẇ׃"],[4,26,"רָאִ֕יתִי וְ⁠הִנֵּ֥ה הַ⁠כַּרְמֶ֖ל הַ⁠מִּדְבָּ֑ר וְ⁠כָל־עָרָ֗י⁠ו נִתְּצוּ֙ מִ⁠פְּנֵ֣י יְהוָ֔ה מִ⁠פְּנֵ֖י חֲר֥וֹן אַפּֽ⁠וֹ׃ס","ráʼi֕yţiy wĕ⁠hiné֥̇h ha⁠kȧrĕme֖l ha⁠mi̇dĕbá֑̇r wĕ⁠kál-ʻárá֗y⁠w niţĕ̇ẕẇ֙ mi⁠pĕ̇né֣y yĕhwá֔h mi⁠pĕ̇né֖y ẖàr֥wòn ʼaṗֽ⁠wò׃s"],[4,27,"כִּי־כֹה֙ אָמַ֣ר יְהוָ֔ה שְׁמָמָ֥ה תִהְיֶ֖ה כָּל־הָ⁠אָ֑רֶץ וְ⁠כָלָ֖ה לֹ֥א אֶעֱשֶֽׂה׃","ki̇y-kòh֙ ʼáma֣r yĕhwá֔h şĕ̌mámá֥h ţihĕye֖h ká̇l-há⁠ʼá֑reẕ wĕ⁠kálá֖h lò֥ʼ ʼeʻèşêֽh׃"],[4,28,"עַל־זֹאת֙ תֶּאֱבַ֣ל הָ⁠אָ֔רֶץ וְ⁠קָדְר֥וּ הַ⁠שָּׁמַ֖יִם מִ⁠מָּ֑עַל עַ֤ל כִּי־דִבַּ֨רְתִּי֙ זַמֹּ֔תִי וְ⁠לֹ֥א נִחַ֖מְתִּי וְ⁠לֹא־אָשׁ֥וּב מִמֶּֽ⁠נָּה׃","ʻal-zòʼţ֙ ţėʼèba֣l há⁠ʼá֔reẕ wĕ⁠qádĕr֥ẇ ha⁠şá̇̌ma֖yim mi⁠má֑̇ʻal ʻa֤l ki̇y-dibȧ֨rĕţi̇y֙ zamò̇֔ţiy wĕ⁠lò֥ʼ niẖa֖mĕţi̇y wĕ⁠lòʼ-ʼáş֥̌ẇb mimėֽ⁠ná̇h׃"],[4,29,"מִ⁠קּ֨וֹל פָּרָ֜שׁ וְ⁠רֹ֣מֵה קֶ֗שֶׁת בֹּרַ֨חַת֙ כָּל־הָ⁠עִ֔יר בָּ֚אוּ בֶּ⁠עָבִ֔ים וּ⁠בַ⁠כֵּפִ֖ים עָל֑וּ כָּל־הָ⁠עִ֣יר עֲזוּבָ֔ה וְ⁠אֵין־יוֹשֵׁ֥ב בָּ⁠הֵ֖ן אִֽישׁ׃","mi⁠q̇֨wòl pá̇rá֜ş̌ wĕ⁠rò֣méh qe֗şěţ bò̇ra֨ẖaţ֙ ká̇l-há⁠ʻi֔yr bá֚̇ʼẇ bė⁠ʻábi֔ym ẇ⁠ba⁠ké̇pi֖ym ʻál֑ẇ ká̇l-há⁠ʻi֣yr ʻàzẇbá֔h wĕ⁠ʼéyn-ywòşé֥̌b bá̇⁠hé֖n ʼiֽyş̌׃"],[4,30,"ו⁠אתי שָׁד֜וּד מַֽה־תַּעֲשִׂ֗י כִּֽי־תִלְבְּשִׁ֨י שָׁנִ֜י כִּי־תַעְדִּ֣י עֲדִי־זָהָ֗ב כִּֽי־תִקְרְעִ֤י בַ⁠פּוּךְ֙ עֵינַ֔יִ⁠ךְ לַ⁠שָּׁ֖וְא תִּתְיַפִּ֑י מָאֲסוּ־בָ֥⁠ךְ עֹגְבִ֖ים נַפְשֵׁ֥⁠ךְ יְבַקֵּֽשׁוּ׃","w⁠ʼţy şá̌d֜ẇd maֽh-ţȧʻàşî֗y kiֽ̇y-ţilĕbĕ̇şǐ֨y şá̌ni֜y ki̇y-ţaʻĕdi֣̇y ʻàdiy-záhá֗b kiֽ̇y-ţiqĕrĕʻi֤y ba⁠ṗẇkĕ֙ ʻéyna֔yi⁠kĕ la⁠şá֖̇̌wĕʼ ţi̇ţĕyapi֑̇y máʼàsẇ-bá֥⁠kĕ ʻògĕbi֖ym napĕşé֥̌⁠kĕ yĕbaqéֽ̇ş̌ẇ׃"],[4,31,"כִּי֩ ק֨וֹל כְּ⁠חוֹלָ֜ה שָׁמַ֗עְתִּי צָרָה֙ כְּ⁠מַבְכִּירָ֔ה ק֧וֹל בַּת־צִיּ֛וֹן תִּתְיַפֵּ֖חַ תְּפָרֵ֣שׂ כַּפֶּ֑י⁠הָ אֽוֹי־נָ֣א לִ֔⁠י כִּֽי־עָיְפָ֥ה נַפְשִׁ֖⁠י לְ⁠הֹרְגִֽים׃פ","ki̇y֩ q֨wòl kĕ̇⁠ẖwòlá֜h şá̌ma֗ʻĕţi̇y ẕáráh֙ kĕ̇⁠mabĕki̇yrá֔h q֧wòl bȧţ-ẕiẏ֛wòn ţi̇ţĕyapé֖̇ẖa ţĕ̇páré֣ş̂ kȧpė֑y⁠há ʼֽwòy-ná֣ʼ li֔⁠y kiֽ̇y-ʻáyĕpá֥h napĕşǐ֖⁠y lĕ⁠hòrĕgiֽym׃p"],[5,1,"שׁוֹטְט֞וּ בְּ⁠חוּצ֣וֹת יְרוּשָׁלִַ֗ם וּ⁠רְאוּ־נָ֤א וּ⁠דְעוּ֙ וּ⁠בַקְשׁ֣וּ בִ⁠רְחוֹבוֹתֶ֔י⁠הָ אִם־תִּמְצְא֣וּ אִ֔ישׁ אִם־יֵ֛שׁ עֹשֶׂ֥ה מִשְׁפָּ֖ט מְבַקֵּ֣שׁ אֱמוּנָ֑ה וְ⁠אֶסְלַ֖ח לָֽ⁠הּ׃","ş̌wòtĕt֞ẇ bĕ̇⁠ẖẇẕ֣wòţ yĕrẇşá̌lia֗m ẇ⁠rĕʼẇ-ná֤ʼ ẇ⁠dĕʻẇ֙ ẇ⁠baqĕş֣̌ẇ bi⁠rĕẖwòbwòţe֔y⁠há ʼim-ţi̇mĕẕĕʼ֣ẇ ʼi֔yş̌ ʼim-yé֛ş̌ ʻòşê֥h mişĕ̌pá֖̇t mĕbaqé֣̇ş̌ ʼèmẇná֑h wĕ⁠ʼesĕla֖ẖ láֽ⁠ḣ׃"],[5,2,"וְ⁠אִ֥ם חַי־יְהֹוָ֖ה יֹאמֵ֑רוּ לָ⁠כֵ֥ן לַ⁠שֶּׁ֖קֶר יִשָּׁבֵֽעוּ׃","wĕ⁠ʼi֥m ẖay-yĕhòwá֖h yòʼmé֑rẇ lá⁠ké֥n la⁠şė֖̌qer yişá̇̌béֽʻẇ׃"],[5,3,"יְהֹוָ֗ה עֵינֶי⁠ךָ֮ הֲ⁠ל֣וֹא לֶ⁠אֱמוּנָה֒ הִכִּ֤יתָה אֹתָ⁠ם֙ וְֽ⁠לֹא־חָ֔לוּ כִּלִּיתָ֕⁠ם מֵאֲנ֖וּ קַ֣חַת מוּסָ֑ר חִזְּק֤וּ פְנֵי⁠הֶם֙ מִ⁠סֶּ֔לַע מֵאֲנ֖וּ לָ⁠שֽׁוּב׃","yĕhòwá֗h ʻéyney⁠ká֮ hà⁠l֣wòʼ le⁠ʼèmẇnáh֒ hiki֤̇yţáh ʼòţá⁠m֙ wĕֽ⁠lòʼ-ẖá֔lẇ ki̇li̇yţá֕⁠m méʼàn֖ẇ qa֣ẖaţ mẇsá֑r ẖizĕ̇q֤ẇ pĕnéy⁠hem֙ mi⁠sė֔laʻ méʼàn֖ẇ lá⁠şֽ̌ẇb׃"],[5,4,"וַ⁠אֲנִ֣י אָמַ֔רְתִּי אַךְ־דַּלִּ֖ים הֵ֑ם נוֹאֲל֕וּ כִּ֣י לֹ֤א יָדְעוּ֙ דֶּ֣רֶךְ יְהוָ֔ה מִשְׁפַּ֖ט אֱלֹהֵי⁠הֶֽם׃","wa⁠ʼàni֣y ʼáma֔rĕţi̇y ʼakĕ-dȧli֖̇ym hé֑m nwòʼàl֕ẇ ki֣̇y lò֤ʼ yádĕʻẇ֙ dė֣rekĕ yĕhwá֔h mişĕ̌pȧ֖t ʼèlòhéy⁠heֽm׃"],[5,5,"אֵֽלֲכָה־לִּ֤⁠י אֶל־הַ⁠גְּדֹלִים֙ וַ⁠אֲדַבְּרָ֣ה אוֹתָ֔⁠ם כִּ֣י הֵ֗מָּה יָדְעוּ֙ דֶּ֣רֶךְ יְהוָ֔ה מִשְׁפַּ֖ט אֱלֹהֵי⁠הֶ֑ם אַ֣ךְ הֵ֤מָּה יַחְדָּו֙ שָׁ֣בְרוּ עֹ֔ל נִתְּק֖וּ מוֹסֵרֽוֹת׃","ʼéֽlàkáh-li֤̇⁠y ʼel-ha⁠gĕ̇dòliym֙ wa⁠ʼàdabĕ̇rá֣h ʼwòţá֔⁠m ki֣̇y hé֗má̇h yádĕʻẇ֙ dė֣rekĕ yĕhwá֔h mişĕ̌pȧ֖t ʼèlòhéy⁠he֑m ʼa֣kĕ hé֤má̇h yaẖĕdá̇w֙ şá֣̌bĕrẇ ʻò֔l niţĕ̇q֖ẇ mwòsérֽwòţ׃"],[5,6,"עַל־כֵּן֩ הִכָּ֨⁠ם אַרְיֵ֜ה מִ⁠יַּ֗עַר זְאֵ֤ב עֲרָבוֹת֙ יְשָׁדְדֵ֔⁠ם נָמֵ֤ר שֹׁקֵד֙ עַל־עָ֣רֵי⁠הֶ֔ם כָּל־הַ⁠יּוֹצֵ֥א מֵ⁠הֵ֖נָּה יִטָּרֵ֑ף כִּ֤י רַבּוּ֙ פִּשְׁעֵי⁠הֶ֔ם עָצְמ֖וּ משבותי⁠הם׃","ʻal-ké̇n֩ hiká̇֨⁠m ʼarĕyé֜h mi⁠yȧ֗ʻar zĕʼé֤b ʻàrábwòţ֙ yĕşá̌dĕdé֔⁠m námé֤r şò̌qéd֙ ʻal-ʻá֣réy⁠he֔m ká̇l-ha⁠ẏwòẕé֥ʼ mé⁠hé֖ná̇h yitá̇ré֑p ki֤̇y raḃẇ֙ pi̇şĕ̌ʻéy⁠he֔m ʻáẕĕm֖ẇ mşbwţy⁠hm׃"],[5,7,"אֵ֤י לָ⁠זֹאת֙ אסלוח־לָ֔⁠ךְ בָּנַ֣יִ⁠ךְ עֲזָב֔וּ⁠נִי וַ⁠יִּשָּׁבְע֖וּ בְּ⁠לֹ֣א אֱלֹהִ֑ים וָ⁠אַשְׂבִּ֤עַ אוֹתָ⁠ם֙ וַ⁠יִּנְאָ֔פוּ וּ⁠בֵ֥ית זוֹנָ֖ה יִתְגֹּדָֽדוּ׃","ʼé֤y lá⁠zòʼţ֙ ʼslwẖ-lá֔⁠kĕ bá̇na֣yi⁠kĕ ʻàzáb֔ẇ⁠niy wa⁠yi̇şá̇̌bĕʻ֖ẇ bĕ̇⁠lò֣ʼ ʼèlòhi֑ym wá⁠ʼaşĕ̂bi֤̇ʻa ʼwòţá⁠m֙ wa⁠yi̇nĕʼá֔pẇ ẇ⁠bé֥yţ zwòná֖h yiţĕgò̇dáֽdẇ׃"],[5,8,"סוּסִ֥ים מְיֻזָּנִ֖ים מַשְׁכִּ֣ים הָי֑וּ אִ֛ישׁ אֶל־אֵ֥שֶׁת רֵעֵ֖⁠הוּ יִצְהָֽלוּ׃","sẇsi֥ym mĕyuzá̇ni֖ym maşĕ̌ki֣̇ym háy֑ẇ ʼi֛yş̌ ʼel-ʼé֥şěţ réʻé֖⁠hẇ yiẕĕháֽlẇ׃"],[5,9,"הַֽ⁠עַל־אֵ֥לֶּה לוֹא־אֶפְקֹ֖ד נְאֻם־יְהֹוָ֑ה וְ⁠אִם֙ בְּ⁠ג֣וֹי אֲשֶׁר־כָּ⁠זֶ֔ה לֹ֥א תִתְנַקֵּ֖ם נַפְשִֽׁ⁠י׃ס","haֽ⁠ʻal-ʼé֥lėh lwòʼ-ʼepĕqò֖d nĕʼum-yĕhòwá֑h wĕ⁠ʼim֙ bĕ̇⁠g֣wòy ʼàşěr-ká̇⁠ze֔h lò֥ʼ ţiţĕnaqé֖̇m napĕşǐֽ⁠y׃s"],[5,10,"עֲל֤וּ בְ⁠שָׁרוֹתֶ֨י⁠הָ֙ וְ⁠שַׁחֵ֔תוּ וְ⁠כָלָ֖ה אַֽל־תַּעֲשׂ֑וּ הָסִ֨ירוּ֙ נְטִ֣ישׁוֹתֶ֔י⁠הָ כִּ֛י ל֥וֹא לַ⁠יהוָ֖ה הֵֽמָּה׃","ʻàl֤ẇ bĕ⁠şá̌rwòţe֨y⁠há֙ wĕ⁠şǎẖé֔ţẇ wĕ⁠kálá֖h ʼaֽl-ţȧʻàş֑̂ẇ hási֨yrẇ֙ nĕti֣yş̌wòţe֔y⁠há ki֛̇y l֥wòʼ la⁠yhwá֖h héֽmá̇h׃"],[5,11,"כִּי֩ בָג֨וֹד בָּגְד֜וּ בִּ֗⁠י בֵּ֧ית יִשְׂרָאֵ֛ל וּ⁠בֵ֥ית יְהוּדָ֖ה נְאֻם־יְהוָֽה׃","ki̇y֩ bág֨wòd bá̇gĕd֜ẇ bi̇֗⁠y bé֧̇yţ yişĕ̂ráʼé֛l ẇ⁠bé֥yţ yĕhẇdá֖h nĕʼum-yĕhwáֽh׃"],[5,12,"כִּֽחֲשׁוּ֙ בַּ⁠יהוָ֔ה וַ⁠יֹּאמְר֖וּ לֹא־ה֑וּא וְ⁠לֹא־תָב֤וֹא עָלֵ֨י⁠נוּ֙ רָעָ֔ה וְ⁠חֶ֥רֶב וְ⁠רָעָ֖ב ל֥וֹא נִרְאֶֽה׃","kiֽ̇ẖàş̌ẇ֙ bȧ⁠yhwá֔h wa⁠yò̇ʼmĕr֖ẇ lòʼ-h֑ẇʼ wĕ⁠lòʼ-ţáb֤wòʼ ʻálé֨y⁠nẇ֙ ráʻá֔h wĕ⁠ẖe֥reb wĕ⁠ráʻá֖b l֥wòʼ nirĕʼeֽh׃"],[5,13,"וְ⁠הַ⁠נְּבִיאִים֙ יִֽהְי֣וּ לְ⁠ר֔וּחַ וְ⁠הַ⁠דִּבֵּ֖ר אֵ֣ין בָּ⁠הֶ֑ם כֹּ֥ה יֵעָשֶׂ֖ה לָ⁠הֶֽם׃ס","wĕ⁠ha⁠nĕ̇biyʼiym֙ yiֽhĕy֣ẇ lĕ⁠r֔ẇẖa wĕ⁠ha⁠di̇bé֖̇r ʼé֣yn bá̇⁠he֑m kò֥̇h yéʻáşê֖h lá⁠heֽm׃s"],[5,14,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י צְבָא֔וֹת יַ֚עַן דַּבֶּרְ⁠כֶ֔ם אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה הִנְ⁠נִ֣י נֹתֵן֩ דְּבָרַ֨⁠י בְּ⁠פִ֜י⁠ךָ לְ⁠אֵ֗שׁ וְ⁠הָ⁠עָ֥ם הַ⁠זֶּ֛ה עֵצִ֖ים וַ⁠אֲכָלָֽתַ⁠ם׃","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y ẕĕbáʼ֔wòţ ya֚ʻan dȧbėrĕ⁠ke֔m ʼeţ-ha⁠dá̇bá֖r ha⁠zė֑h hinĕ⁠ni֣y nòţén֩ dĕ̇bára֨⁠y bĕ̇⁠pi֜y⁠ká lĕ⁠ʼé֗ş̌ wĕ⁠há⁠ʻá֥m ha⁠zė֛h ʻéẕi֖ym wa⁠ʼàkáláֽţa⁠m׃"],[5,15,"הִנְ⁠נִ֣י מֵבִיא֩ עֲלֵי⁠כֶ֨ם גּ֧וֹי מִ⁠מֶּרְחָ֛ק בֵּ֥ית יִשְׂרָאֵ֖ל נְאֻם־יְהֹוָ֑ה גּ֣וֹי ׀ אֵיתָ֣ן ה֗וּא גּ֤וֹי מֵ⁠עוֹלָם֙ ה֔וּא גּ֚וֹי לֹא־תֵדַ֣ע לְשֹׁנ֔⁠וֹ וְ⁠לֹ֥א תִשְׁמַ֖ע מַה־יְדַבֵּֽר׃","hinĕ⁠ni֣y mébiyʼ֩ ʻàléy⁠ke֨m ġ֧wòy mi⁠mėrĕẖá֛q bé֥̇yţ yişĕ̂ráʼé֖l nĕʼum-yĕhòwá֑h ġ֣wòy ׀ ʼéyţá֣n h֗ẇʼ ġ֤wòy mé⁠ʻwòlám֙ h֔ẇʼ ġ֚wòy lòʼ-ţéda֣ʻ lĕşò̌n֔⁠wò wĕ⁠lò֥ʼ ţişĕ̌ma֖ʻ mah-yĕdabéֽ̇r׃"],[5,16,"אַשְׁפָּת֖⁠וֹ כְּ⁠קֶ֣בֶר פָּת֑וּחַ כֻּלָּ֖⁠ם גִּבּוֹרִֽים׃","ʼaşĕ̌pá̇ţ֖⁠wò kĕ̇⁠qe֣ber pá̇ţ֑ẇẖa ku̇lá֖̇⁠m gi̇ḃwòriֽym׃"],[5,17,"וְ⁠אָכַ֨ל קְצִֽירְ⁠ךָ֜ וְ⁠לַחְמֶ֗⁠ךָ יֹאכְלוּ֙ בָּנֶ֣י⁠ךָ וּ⁠בְנוֹתֶ֔י⁠ךָ יֹאכַ֤ל צֹאנְ⁠ךָ֙ וּ⁠בְקָרֶ֔⁠ךָ יֹאכַ֥ל גַּפְנְ⁠ךָ֖ וּ⁠תְאֵנָתֶ֑⁠ךָ יְרֹשֵׁ֞שׁ עָרֵ֣י מִבְצָרֶ֗י⁠ךָ אֲשֶׁ֥ר אַתָּ֛ה בּוֹטֵ֥חַ בָּ⁠הֵ֖נָּה בֶּ⁠חָֽרֶב׃","wĕ⁠ʼáka֨l qĕẕiֽyrĕ⁠ká֜ wĕ⁠laẖĕme֗⁠ká yòʼkĕlẇ֙ bá̇ne֣y⁠ká ẇ⁠bĕnwòţe֔y⁠ká yòʼka֤l ẕòʼnĕ⁠ká֙ ẇ⁠bĕqáre֔⁠ká yòʼka֥l gȧpĕnĕ⁠ká֖ ẇ⁠ţĕʼénáţe֑⁠ká yĕròşé̌֞ş̌ ʻáré֣y mibĕẕáre֗y⁠ká ʼàşě֥r ʼaţá֛̇h ḃwòté֥ẖa bá̇⁠hé֖ná̇h bė⁠ẖáֽreb׃"],[5,18,"וְ⁠גַ֛ם בַּ⁠יָּמִ֥ים הָ⁠הֵ֖מָּה נְאֻם־יְהֹוָ֑ה לֹֽא־אֶעֱשֶׂ֥ה אִתְּ⁠כֶ֖ם כָּלָֽה׃","wĕ⁠ga֛m bȧ⁠yá̇mi֥ym há⁠hé֖má̇h nĕʼum-yĕhòwá֑h lòֽʼ-ʼeʻèşê֥h ʼiţĕ̇⁠ke֖m ká̇láֽh׃"],[5,19,"וְ⁠הָיָה֙ כִּ֣י תֹאמְר֔וּ תַּ֣חַת מֶ֗ה עָשָׂ֨ה יְהֹוָ֧ה אֱלֹהֵ֛י⁠נוּ לָ֖⁠נוּ אֶת־כָּל־אֵ֑לֶּה וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם כַּ⁠אֲשֶׁ֨ר עֲזַבְתֶּ֤ם אוֹתִ⁠י֙ וַ⁠תַּעַבְד֞וּ אֱלֹהֵ֤י נֵכָר֙ בְּ⁠אַרְצְ⁠כֶ֔ם כֵּ֚ן תַּעַבְד֣וּ זָרִ֔ים בְּ⁠אֶ֖רֶץ לֹ֥א לָ⁠כֶֽם׃ס","wĕ⁠háyáh֙ ki֣̇y ţòʼmĕr֔ẇ ţȧ֣ẖaţ me֗h ʻáşá̂֨h yĕhòwá֧h ʼèlòhé֛y⁠nẇ lá֖⁠nẇ ʼeţ-ká̇l-ʼé֑lėh wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m kȧ⁠ʼàşě֨r ʻàzabĕţė֤m ʼwòţi⁠y֙ wa⁠ţȧʻabĕd֞ẇ ʼèlòhé֤y nékár֙ bĕ̇⁠ʼarĕẕĕ⁠ke֔m ké֚̇n ţȧʻabĕd֣ẇ zári֔ym bĕ̇⁠ʼe֖reẕ lò֥ʼ lá⁠keֽm׃s"],[5,20,"הַגִּ֥ידוּ זֹ֖את בְּ⁠בֵ֣ית יַעֲקֹ֑ב וְ⁠הַשְׁמִיע֥וּ⁠הָ בִ⁠יהוּדָ֖ה לֵ⁠אמֹֽר׃","hagi֥̇ydẇ zò֖ʼţ bĕ̇⁠bé֣yţ yaʻàqò֑b wĕ⁠haşĕ̌miyʻ֥ẇ⁠há bi⁠yhẇdá֖h lé⁠ʼmòֽr׃"],[5,21,"שִׁמְעוּ־נָ֣א זֹ֔את עַ֥ם סָכָ֖ל וְ⁠אֵ֣ין לֵ֑ב עֵינַ֤יִם לָ⁠הֶם֙ וְ⁠לֹ֣א יִרְא֔וּ אָזְנַ֥יִם לָ⁠הֶ֖ם וְ⁠לֹ֥א יִשְׁמָֽעוּ׃","şǐmĕʻẇ-ná֣ʼ zò֔ʼţ ʻa֥m sáká֖l wĕ⁠ʼé֣yn lé֑b ʻéyna֤yim lá⁠hem֙ wĕ⁠lò֣ʼ yirĕʼ֔ẇ ʼázĕna֥yim lá⁠he֖m wĕ⁠lò֥ʼ yişĕ̌máֽʻẇ׃"],[5,22,"הַ⁠אוֹתִ֨⁠י לֹא־תִירָ֜אוּ נְאֻם־יְהֹוָ֗ה אִ֤ם מִ⁠פָּנַ⁠י֙ לֹ֣א תָחִ֔ילוּ אֲשֶׁר־שַׂ֤מְתִּי חוֹל֙ גְּב֣וּל לַ⁠יָּ֔ם חָק־עוֹלָ֖ם וְ⁠לֹ֣א יַעַבְרֶ֑⁠נְהוּ וַ⁠יִּֽתְגָּעֲשׁוּ֙ וְ⁠לֹ֣א יוּכָ֔לוּ וְ⁠הָמ֥וּ גַלָּ֖י⁠ו וְ⁠לֹ֥א יַעַבְרֻֽ⁠נְהוּ׃","ha⁠ʼwòţi֨⁠y lòʼ-ţiyrá֜ʼẇ nĕʼum-yĕhòwá֗h ʼi֤m mi⁠pá̇na⁠y֙ lò֣ʼ ţáẖi֔ylẇ ʼàşěr-şâ֤mĕţi̇y ẖwòl֙ gĕ̇b֣ẇl la⁠yá̇֔m ẖáq-ʻwòlá֖m wĕ⁠lò֣ʼ yaʻabĕre֑⁠nĕhẇ wa⁠yiֽ̇ţĕgá̇ʻàş̌ẇ֙ wĕ⁠lò֣ʼ yẇká֔lẇ wĕ⁠hám֥ẇ galá֖̇y⁠w wĕ⁠lò֥ʼ yaʻabĕruֽ⁠nĕhẇ׃"],[5,23,"וְ⁠לָ⁠עָ֤ם הַ⁠זֶּה֙ הָיָ֔ה לֵ֖ב סוֹרֵ֣ר וּ⁠מוֹרֶ֑ה סָ֖רוּ וַ⁠יֵּלֵֽכוּ׃","wĕ⁠lá⁠ʻá֤m ha⁠zėh֙ háyá֔h lé֖b swòré֣r ẇ⁠mwòre֑h sá֖rẇ wa⁠yé̇léֽkẇ׃"],[5,24,"וְ⁠לֹֽא־אָמְר֣וּ בִ⁠לְבָבָ֗⁠ם נִ֤ירָא נָא֙ אֶת־יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ הַ⁠נֹּתֵ֗ן גֶּ֛שֶׁם ו⁠ירה וּ⁠מַלְק֖וֹשׁ בְּ⁠עִתּ֑⁠וֹ שְׁבֻע֛וֹת חֻקּ֥וֹת קָצִ֖יר יִשְׁמָר־לָֽ⁠נוּ׃","wĕ⁠lòֽʼ-ʼámĕr֣ẇ bi⁠lĕbábá֗⁠m ni֤yráʼ náʼ֙ ʼeţ-yĕhwá֣h ʼèlòhé֔y⁠nẇ ha⁠nò̇ţé֗n gė֛şěm w⁠yrh ẇ⁠malĕq֖wòş̌ bĕ̇⁠ʻiţ֑̇⁠wò şĕ̌buʻ֛wòţ ẖuq֥̇wòţ qáẕi֖yr yişĕ̌már-láֽ⁠nẇ׃"],[5,25,"עֲוֺנוֹתֵי⁠כֶ֖ם הִטּוּ־אֵ֑לֶּה וְ⁠חַטֹּ֣אותֵי⁠כֶ֔ם מָנְע֥וּ הַ⁠טּ֖וֹב מִ⁠כֶּֽם׃","ʻàwֺnwòţéy⁠ke֖m hiṫẇ-ʼé֑lėh wĕ⁠ẖatò֣̇ʼwţéy⁠ke֔m mánĕʻ֥ẇ ha⁠ṫ֖wòb mi⁠kėֽm׃"],[5,26,"כִּי־נִמְצְא֥וּ בְ⁠עַמִּ֖⁠י רְשָׁעִ֑ים יָשׁוּר֙ כְּ⁠שַׁ֣ךְ יְקוּשִׁ֔ים הִצִּ֥יבוּ מַשְׁחִ֖ית אֲנָשִׁ֥ים יִלְכֹּֽדוּ׃","ki̇y-nimĕẕĕʼ֥ẇ bĕ⁠ʻami֖̇⁠y rĕşá̌ʻi֑ym yáş̌ẇr֙ kĕ̇⁠şǎ֣kĕ yĕqẇşǐ֔ym hiẕi֥̇ybẇ maşĕ̌ẖi֖yţ ʼànáşǐ֥ym yilĕkòֽ̇dẇ׃"],[5,27,"כִּ⁠כְלוּב֙ מָ֣לֵא ע֔וֹף כֵּ֥ן בָּתֵּי⁠הֶ֖ם מְלֵאִ֣ים מִרְמָ֑ה עַל־כֵּ֥ן גָּדְל֖וּ וַֽ⁠יַּעֲשִֽׁירוּ׃","ki̇⁠kĕlẇb֙ má֣léʼ ʻ֔wòp ké֥̇n bá̇ţé̇y⁠he֖m mĕléʼi֣ym mirĕmá֑h ʻal-ké֥̇n gá̇dĕl֖ẇ waֽ⁠yȧʻàşǐֽyrẇ׃"],[5,28,"שָׁמְנ֣וּ עָשְׁת֗וּ גַּ֚ם עָֽבְר֣וּ דִבְרֵי־רָ֔ע דִּ֣ין לֹא־דָ֔נוּ דִּ֥ין יָת֖וֹם וְ⁠יַצְלִ֑יחוּ וּ⁠מִשְׁפַּ֥ט אֶבְיוֹנִ֖ים לֹ֥א שָׁפָֽטוּ׃","şá̌mĕn֣ẇ ʻáşĕ̌ţ֗ẇ gȧ֚m ʻáֽbĕr֣ẇ dibĕréy-rá֔ʻ di֣̇yn lòʼ-dá֔nẇ di֥̇yn yáţ֖wòm wĕ⁠yaẕĕli֑yẖẇ ẇ⁠mişĕ̌pȧ֥t ʼebĕywòni֖ym lò֥ʼ şá̌páֽtẇ׃"],[5,29,"הַֽ⁠עַל־אֵ֥לֶּה לֹֽא־אֶפְקֹ֖ד נְאֻם־יְהֹוָ֑ה אִ֚ם בְּ⁠ג֣וֹי אֲשֶׁר־כָּ⁠זֶ֔ה לֹ֥א תִתְנַקֵּ֖ם נַפְשִֽׁ⁠י׃ס","haֽ⁠ʻal-ʼé֥lėh lòֽʼ-ʼepĕqò֖d nĕʼum-yĕhòwá֑h ʼi֚m bĕ̇⁠g֣wòy ʼàşěr-ká̇⁠ze֔h lò֥ʼ ţiţĕnaqé֖̇m napĕşǐֽ⁠y׃s"],[5,30,"שַׁמָּה֙ וְ⁠שַׁ֣עֲרוּרָ֔ה נִהְיְתָ֖ה בָּ⁠אָֽרֶץ׃","şǎmá̇h֙ wĕ⁠şǎ֣ʻàrẇrá֔h nihĕyĕţá֖h bá̇⁠ʼáֽreẕ׃"],[5,31,"הַ⁠נְּבִיאִ֞ים נִבְּא֣וּ־בַ⁠שֶּׁ֗קֶר וְ⁠הַ⁠כֹּהֲנִים֙ יִרְדּ֣וּ עַל־יְדֵי⁠הֶ֔ם וְ⁠עַמִּ֖⁠י אָ֣הֲבוּ כֵ֑ן וּ⁠מַֽה־תַּעֲשׂ֖וּ לְ⁠אַחֲרִיתָֽ⁠הּ׃","ha⁠nĕ̇biyʼi֞ym nibĕ̇ʼ֣ẇ-ba⁠şė̌֗qer wĕ⁠ha⁠kò̇hàniym֙ yirĕḋ֣ẇ ʻal-yĕdéy⁠he֔m wĕ⁠ʻami֖̇⁠y ʼá֣hàbẇ ké֑n ẇ⁠maֽh-ţȧʻàş֖̂ẇ lĕ⁠ʼaẖàriyţáֽ⁠ḣ׃"],[6,1,"הָעִ֣זוּ ׀ בְּנֵ֣י בִניָמִ֗ן מִ⁠קֶּ֨רֶב֙ יְר֣וּשָׁלִַ֔ם וּ⁠בִ⁠תְק֨וֹעַ֙ תִּקְע֣וּ שׁוֹפָ֔ר וְ⁠עַל־בֵּ֥ית הַכֶּ֖רֶם שְׂא֣וּ מַשְׂאֵ֑ת כִּ֥י רָעָ֛ה נִשְׁקְפָ֥ה מִ⁠צָּפ֖וֹן וְ⁠שֶׁ֥בֶר גָּדֽוֹל׃","háʻi֣zẇ ׀ bĕ̇né֣y binyámi֗n mi⁠qė֨reb֙ yĕr֣ẇşá̌lia֔m ẇ⁠bi⁠ţĕq֨wòʻa֙ ţi̇qĕʻ֣ẇ ş̌wòpá֔r wĕ⁠ʻal-bé֥̇yţ hakė֖rem şĕ̂ʼ֣ẇ maşĕ̂ʼé֑ţ ki֥̇y ráʻá֛h nişĕ̌qĕpá֥h mi⁠ẕá̇p֖wòn wĕ⁠şě֥ber gá̇dֽwòl׃"],[6,2,"הַ⁠נָּוָה֙ וְ⁠הַ⁠מְּעֻנָּגָ֔ה דָּמִ֖יתִי בַּת־צִיּֽוֹן׃","ha⁠ná̇wáh֙ wĕ⁠ha⁠mĕ̇ʻuná̇gá֔h dá̇mi֖yţiy bȧţ-ẕiẏֽwòn׃"],[6,3,"אֵלֶ֛י⁠הָ יָבֹ֥אוּ רֹעִ֖ים וְ⁠עֶדְרֵי⁠הֶ֑ם תָּקְע֨וּ עָלֶ֤י⁠הָ אֹהָלִים֙ סָבִ֔יב רָע֖וּ אִ֥ישׁ אֶת־יָדֽ⁠וֹ׃","ʼéle֛y⁠há yábò֥ʼẇ ròʻi֖ym wĕ⁠ʻedĕréy⁠he֑m ţá̇qĕʻ֨ẇ ʻále֤y⁠há ʼòháliym֙ sábi֔yb ráʻ֖ẇ ʼi֥yş̌ ʼeţ-yádֽ⁠wò׃"],[6,4,"קַדְּשׁ֤וּ עָלֶ֨י⁠הָ֙ מִלְחָמָ֔ה ק֖וּמוּ וְ⁠נַעֲלֶ֣ה בַֽ⁠צָּהֳרָ֑יִם א֥וֹי לָ֨⁠נוּ֙ כִּי־פָנָ֣ה הַ⁠יּ֔וֹם כִּ֥י יִנָּט֖וּ צִלְלֵי־עָֽרֶב׃","qadĕ̇ş֤̌ẇ ʻále֨y⁠há֙ milĕẖámá֔h q֖ẇmẇ wĕ⁠naʻàle֣h baֽ⁠ẕá̇horá֑yim ʼ֥wòy lá֨⁠nẇ֙ ki̇y-páná֣h ha⁠ẏ֔wòm ki֥̇y yiná̇t֖ẇ ẕilĕléy-ʻáֽreb׃"],[6,5,"ק֚וּמוּ וְ⁠נַעֲלֶ֣ה בַ⁠לָּ֔יְלָה וְ⁠נַשְׁחִ֖יתָה אַרְמְנוֹתֶֽי⁠הָ׃ס","q֚ẇmẇ wĕ⁠naʻàle֣h ba⁠lá̇֔yĕláh wĕ⁠naşĕ̌ẖi֖yţáh ʼarĕmĕnwòţeֽy⁠há׃s"],[6,6,"כִּ֣י כֹ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת כִּרְת֣וּ עֵצָ֔ה וְ⁠שִׁפְכ֥וּ עַל־יְרוּשָׁלִַ֖ם סֹלְלָ֑ה הִ֚יא הָ⁠עִ֣יר הָפְקַ֔ד כֻּלָּ֖⁠הּ עֹ֥שֶׁק בְּ⁠קִרְבָּֽ⁠הּ׃","ki֣̇y kò֤h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ki̇rĕţ֣ẇ ʻéẕá֔h wĕ⁠şǐpĕk֥ẇ ʻal-yĕrẇşá̌lia֖m sòlĕlá֑h hi֚yʼ há⁠ʻi֣yr hápĕqa֔d ku̇lá֖̇⁠ḣ ʻò֥şěq bĕ̇⁠qirĕbáֽ̇⁠ḣ׃"],[6,7,"כְּ⁠הָקִ֥יר בור מֵימֶ֔י⁠הָ כֵּ֖ן הֵקֵ֣רָה רָעָתָ֑⁠הּ חָמָ֣ס וָ֠⁠שֹׁד יִשָּׁ֨מַע בָּ֧⁠הּ עַל־פָּנַ֛⁠י תָּמִ֖יד חֳלִ֥י וּ⁠מַכָּֽה׃","kĕ̇⁠háqi֥yr bwr méyme֔y⁠há ké֖̇n héqé֣ráh ráʻáţá֑⁠ḣ ẖámá֣s wá֠⁠şò̌d yişá̇̌֨maʻ bá֧̇⁠ḣ ʻal-pá̇na֛⁠y ţá̇mi֖yd ẖoli֥y ẇ⁠makáֽ̇h׃"],[6,8,"הִוָּסְרִי֙ יְר֣וּשָׁלִַ֔ם פֶּן־תֵּקַ֥ע נַפְשִׁ֖⁠י מִמֵּ֑⁠ךְ פֶּן־אֲשִׂימֵ֣⁠ךְ שְׁמָמָ֔ה אֶ֖רֶץ ל֥וֹא נוֹשָֽׁבָה׃פ","hiwá̇sĕriy֙ yĕr֣ẇşá̌lia֔m pėn-ţé̇qa֥ʻ napĕşǐ֖⁠y mimé֑̇⁠kĕ pėn-ʼàşîymé֣⁠kĕ şĕ̌mámá֔h ʼe֖reẕ l֥wòʼ nwòşáֽ̌báh׃p"],[6,9,"כֹּ֤ה אָמַר֙ יְהֹוָ֣ה צְבָא֔וֹת עוֹלֵ֛ל יְעוֹלְל֥וּ כַ⁠גֶּ֖פֶן שְׁאֵרִ֣ית יִשְׂרָאֵ֑ל הָשֵׁב֙ יָדְ⁠ךָ֔ כְּ⁠בוֹצֵ֖ר עַל־סַלְסִלּֽוֹת׃","kò֤̇h ʼámar֙ yĕhòwá֣h ẕĕbáʼ֔wòţ ʻwòlé֛l yĕʻwòlĕl֥ẇ ka⁠gė֖pen şĕ̌ʼéri֣yţ yişĕ̂ráʼé֑l háşé̌b֙ yádĕ⁠ká֔ kĕ̇⁠bwòẕé֖r ʻal-salĕsilֽ̇wòţ׃"],[6,10,"עַל־מִ֨י אֲדַבְּרָ֤ה וְ⁠אָעִ֨ידָה֙ וְ⁠יִשְׁמָ֔עוּ הִנֵּה֙ עֲרֵלָ֣ה אָזְנָ֔⁠ם וְ⁠לֹ֥א יוּכְל֖וּ לְ⁠הַקְשִׁ֑יב הִנֵּ֣ה דְבַר־יְהוָ֗ה הָיָ֥ה לָ⁠הֶ֛ם לְ⁠חֶרְפָּ֖ה לֹ֥א יַחְפְּצוּ־בֽ⁠וֹ׃","ʻal-mi֨y ʼàdabĕ̇rá֤h wĕ⁠ʼáʻi֨ydáh֙ wĕ⁠yişĕ̌má֔ʻẇ hiné̇h֙ ʻàrélá֣h ʼázĕná֔⁠m wĕ⁠lò֥ʼ yẇkĕl֖ẇ lĕ⁠haqĕşǐ֑yb hiné֣̇h dĕbar-yĕhwá֗h háyá֥h lá⁠he֛m lĕ⁠ẖerĕpá֖̇h lò֥ʼ yaẖĕpĕ̇ẕẇ-bֽ⁠wò׃"],[6,11,"וְ⁠אֵת֩ חֲמַ֨ת יְהוָ֤ה ׀ מָלֵ֨אתִי֙ נִלְאֵ֣יתִי הָכִ֔יל שְׁפֹ֤ךְ עַל־עוֹלָל֙ בַּ⁠ח֔וּץ וְ⁠עַ֛ל ס֥וֹד בַּחוּרִ֖ים יַחְדָּ֑ו כִּֽי־גַם־אִ֤ישׁ עִם־אִשָּׁה֙ יִלָּכֵ֔דוּ זָקֵ֖ן עִם־מְלֵ֥א יָמִֽים׃","wĕ⁠ʼéţ֩ ẖàma֨ţ yĕhwá֤h ׀ málé֨ʼţiy֙ nilĕʼé֣yţiy háki֔yl şĕ̌pò֤kĕ ʻal-ʻwòlál֙ bȧ⁠ẖ֔ẇẕ wĕ⁠ʻa֛l s֥wòd bȧẖẇri֖ym yaẖĕdá֑̇w kiֽ̇y-gam-ʼi֤yş̌ ʻim-ʼişá̇̌h֙ yilá̇ké֔dẇ záqé֖n ʻim-mĕlé֥ʼ yámiֽym׃"],[6,12,"וְ⁠נָסַ֤בּוּ בָֽתֵּי⁠הֶם֙ לַ⁠אֲחֵרִ֔ים שָׂד֥וֹת וְ⁠נָשִׁ֖ים יַחְדָּ֑ו כִּֽי־אַטֶּ֧ה אֶת־יָדִ֛⁠י עַל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ נְאֻם־יְהוָֽה׃","wĕ⁠nása֤ḃẇ báֽţé̇y⁠hem֙ la⁠ʼàẖéri֔ym şá̂d֥wòţ wĕ⁠náşǐ֖ym yaẖĕdá֑̇w kiֽ̇y-ʼatė֧h ʼeţ-yádi֛⁠y ʻal-yòşĕ̌bé֥y há⁠ʼá֖reẕ nĕʼum-yĕhwáֽh׃"],[6,13,"כִּ֤י מִ⁠קְּטַנָּ⁠ם֙ וְ⁠עַד־גְּדוֹלָ֔⁠ם כֻּלּ֖⁠וֹ בּוֹצֵ֣עַ בָּ֑צַע וּ⁠מִ⁠נָּבִיא֙ וְ⁠עַד־כֹּהֵ֔ן כֻּלּ֖⁠וֹ עֹ֥שֶׂה שָּֽׁקֶר׃","ki֤̇y mi⁠qĕ̇taná̇⁠m֙ wĕ⁠ʻad-gĕ̇dwòlá֔⁠m ku̇l֖̇⁠wò ḃwòẕé֣ʻa bá֑̇ẕaʻ ẇ⁠mi⁠ná̇biyʼ֙ wĕ⁠ʻad-kò̇hé֔n ku̇l֖̇⁠wò ʻò֥şêh şáֽ̇̌qer׃"],[6,14,"וַֽ⁠יְרַפְּא֞וּ אֶת־שֶׁ֤בֶר עַמִּ⁠י֙ עַל־נְקַלָּ֔ה לֵ⁠אמֹ֖ר שָׁל֣וֹם ׀ שָׁל֑וֹם וְ⁠אֵ֖ין שָׁלֽוֹם׃","waֽ⁠yĕrapĕ̇ʼ֞ẇ ʼeţ-şě֤ber ʻami̇⁠y֙ ʻal-nĕqalá̇֔h lé⁠ʼmò֖r şá̌l֣wòm ׀ şá̌l֑wòm wĕ⁠ʼé֖yn şá̌lֽwòm׃"],[6,15,"הֹבִ֕ישׁוּ כִּ֥י תוֹעֵבָ֖ה עָשׂ֑וּ גַּם־בּ֣וֹשׁ לֹֽא־יֵב֗וֹשׁוּ גַּם־הַכְלִים֙ לֹ֣א יָדָ֔עוּ לָ⁠כֵ֞ן יִפְּל֧וּ בַ⁠נֹּפְלִ֛ים בְּ⁠עֵת־פְּקַדְתִּ֥י⁠ם יִכָּשְׁל֖וּ אָמַ֥ר יְהוָֽה׃ס","hòbi֕yş̌ẇ ki֥̇y ţwòʻébá֖h ʻáş֑̂ẇ gȧm-ḃ֣wòş̌ lòֽʼ-yéb֗wòş̌ẇ gȧm-hakĕliym֙ lò֣ʼ yádá֔ʻẇ lá⁠ké֞n yipĕ̇l֧ẇ ba⁠nò̇pĕli֛ym bĕ̇⁠ʻéţ-pĕ̇qadĕţi֥̇y⁠m yiká̇şĕ̌l֖ẇ ʼáma֥r yĕhwáֽh׃s"],[6,16,"כֹּ֣ה אָמַ֣ר יְהוָ֡ה עִמְדוּ֩ עַל־דְּרָכִ֨ים וּ⁠רְא֜וּ וְ⁠שַׁאֲל֣וּ ׀ לִ⁠נְתִב֣וֹת עוֹלָ֗ם אֵי־זֶ֨ה דֶ֤רֶךְ הַ⁠טּוֹב֙ וּ⁠לְכוּ־בָ֔⁠הּ וּ⁠מִצְא֥וּ מַרְגּ֖וֹעַ לְ⁠נַפְשְׁ⁠כֶ֑ם וַ⁠יֹּאמְר֖וּ לֹ֥א נֵלֵֽךְ׃","kò֣̇h ʼáma֣r yĕhwá֡h ʻimĕdẇ֩ ʻal-dĕ̇ráki֨ym ẇ⁠rĕʼ֜ẇ wĕ⁠şǎʼàl֣ẇ ׀ li⁠nĕţib֣wòţ ʻwòlá֗m ʼéy-ze֨h de֤rekĕ ha⁠ṫwòb֙ ẇ⁠lĕkẇ-bá֔⁠ḣ ẇ⁠miẕĕʼ֥ẇ marĕġ֖wòʻa lĕ⁠napĕşĕ̌⁠ke֑m wa⁠yò̇ʼmĕr֖ẇ lò֥ʼ néléֽkĕ׃"],[6,17,"וַ⁠הֲקִמֹתִ֤י עֲלֵי⁠כֶם֙ צֹפִ֔ים הַקְשִׁ֖יבוּ לְ⁠ק֣וֹל שׁוֹפָ֑ר וַ⁠יֹּאמְר֖וּ לֹ֥א נַקְשִֽׁיב׃","wa⁠hàqimòţi֤y ʻàléy⁠kem֙ ẕòpi֔ym haqĕşǐ֖ybẇ lĕ⁠q֣wòl ş̌wòpá֑r wa⁠yò̇ʼmĕr֖ẇ lò֥ʼ naqĕşǐֽyb׃"],[6,18,"לָ⁠כֵ֖ן שִׁמְע֣וּ הַ⁠גּוֹיִ֑ם וּ⁠דְעִ֥י עֵדָ֖ה אֶת־אֲשֶׁר־בָּֽ⁠ם׃","lá⁠ké֖n şǐmĕʻ֣ẇ ha⁠ġwòyi֑m ẇ⁠dĕʻi֥y ʻédá֖h ʼeţ-ʼàşěr-báֽ̇⁠m׃"],[6,19,"שִׁמְעִ֣י הָ⁠אָ֔רֶץ הִנֵּ֨ה אָנֹכִ֜י מֵבִ֥יא רָעָ֛ה אֶל־הָ⁠עָ֥ם הַ⁠זֶּ֖ה פְּרִ֣י מַחְשְׁבוֹתָ֑⁠ם כִּ֤י עַל־דְּבָרַ⁠י֙ לֹ֣א הִקְשִׁ֔יבוּ וְ⁠תוֹרָתִ֖⁠י וַ⁠יִּמְאֲסוּ־בָֽ⁠הּ׃","şǐmĕʻi֣y há⁠ʼá֔reẕ hiné̇֨h ʼánòki֜y mébi֥yʼ ráʻá֛h ʼel-há⁠ʻá֥m ha⁠zė֖h pĕ̇ri֣y maẖĕşĕ̌bwòţá֑⁠m ki֤̇y ʻal-dĕ̇bára⁠y֙ lò֣ʼ hiqĕşǐ֔ybẇ wĕ⁠ţwòráţi֖⁠y wa⁠yi̇mĕʼàsẇ-báֽ⁠ḣ׃"],[6,20,"לָ⁠מָּה־זֶּ֨ה לִ֤⁠י לְבוֹנָה֙ מִ⁠שְּׁבָ֣א תָב֔וֹא וְ⁠קָנֶ֥ה הַ⁠טּ֖וֹב מֵ⁠אֶ֣רֶץ מֶרְחָ֑ק עֹלֽוֹתֵי⁠כֶם֙ לֹ֣א לְ⁠רָצ֔וֹן וְ⁠זִבְחֵי⁠כֶ֖ם לֹא־עָ֥רְבוּ לִֽ⁠י׃ס","lá⁠má̇h-zė֨h li֤⁠y lĕbwònáh֙ mi⁠şĕ̇̌bá֣ʼ ţáb֔wòʼ wĕ⁠qáne֥h ha⁠ṫ֖wòb mé⁠ʼe֣reẕ merĕẖá֑q ʻòlֽwòţéy⁠kem֙ lò֣ʼ lĕ⁠ráẕ֔wòn wĕ⁠zibĕẖéy⁠ke֖m lòʼ-ʻá֥rĕbẇ liֽ⁠y׃s"],[6,21,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֥י נֹתֵ֛ן אֶל־הָ⁠עָ֥ם הַ⁠זֶּ֖ה מִכְשֹׁלִ֑ים וְ⁠כָ֣שְׁלוּ בָ֠⁠ם אָב֨וֹת וּ⁠בָנִ֥ים יַחְדָּ֛ו שָׁכֵ֥ן וְ⁠רֵע֖⁠וֹ יאבדו׃פ","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֥y nòţé֛n ʼel-há⁠ʻá֥m ha⁠zė֖h mikĕşò̌li֑ym wĕ⁠ká֣şĕ̌lẇ bá֠⁠m ʼáb֨wòţ ẇ⁠báni֥ym yaẖĕdá֛̇w şá̌ké֥n wĕ⁠réʻ֖⁠wò yʼbdw׃p"],[6,22,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנֵּ֛ה עַ֥ם בָּ֖א מֵ⁠אֶ֣רֶץ צָפ֑וֹן וְ⁠ג֣וֹי גָּד֔וֹל יֵע֖וֹר מִ⁠יַּרְכְּתֵי־אָֽרֶץ׃","kò֚̇h ʼáma֣r yĕhwá֔h hiné֛̇h ʻa֥m bá֖̇ʼ mé⁠ʼe֣reẕ ẕáp֑wòn wĕ⁠g֣wòy gá̇d֔wòl yéʻ֖wòr mi⁠yȧrĕkĕ̇ţéy-ʼáֽreẕ׃"],[6,23,"קֶ֣שֶׁת וְ⁠כִיד֞וֹן יַחֲזִ֗יקוּ אַכְזָרִ֥י הוּא֙ וְ⁠לֹ֣א יְרַחֵ֔מוּ קוֹלָ⁠ם֙ כַּ⁠יָּ֣ם יֶהֱמֶ֔ה וְ⁠עַל־סוּסִ֖ים יִרְכָּ֑בוּ עָר֗וּךְ כְּ⁠אִישׁ֙ לַ⁠מִּלְחָמָ֔ה עָלַ֖יִ⁠ךְ בַּת־צִיּֽוֹן׃","qe֣şěţ wĕ⁠kiyd֞wòn yaẖàzi֗yqẇ ʼakĕzári֥y hẇʼ֙ wĕ⁠lò֣ʼ yĕraẖé֔mẇ qwòlá⁠m֙ kȧ⁠yá֣̇m yehème֔h wĕ⁠ʻal-sẇsi֖ym yirĕká֑̇bẇ ʻár֗ẇkĕ kĕ̇⁠ʼiyş̌֙ la⁠mi̇lĕẖámá֔h ʻála֖yi⁠kĕ bȧţ-ẕiẏֽwòn׃"],[6,24,"שָׁמַ֥עְנוּ אֶת־שָׁמְע֖⁠וֹ רָפ֣וּ יָדֵ֑י⁠נוּ צָרָה֙ הֶחֱזִיקַ֔תְ⁠נוּ חִ֖יל כַּ⁠יּוֹלֵדָֽה׃","şá̌ma֥ʻĕnẇ ʼeţ-şá̌mĕʻ֖⁠wò ráp֣ẇ yádé֑y⁠nẇ ẕáráh֙ heẖèziyqa֔ţĕ⁠nẇ ẖi֖yl kȧ⁠ẏwòlédáֽh׃"],[6,25,"אַל־תצאי הַ⁠שָּׂדֶ֔ה וּ⁠בַ⁠דֶּ֖רֶךְ אַל־תלכי כִּ֚י חֶ֣רֶב לְ⁠אֹיֵ֔ב מָג֖וֹר מִ⁠סָּבִֽיב׃","ʼal-ţẕʼy ha⁠şá̇̂de֔h ẇ⁠ba⁠dė֖rekĕ ʼal-ţlky ki֚̇y ẖe֣reb lĕ⁠ʼòyé֔b mág֖wòr mi⁠sá̇biֽyb׃"],[6,26,"בַּת־עַמִּ֤⁠י חִגְרִי־שָׂק֙ וְ⁠הִתְפַּלְּשִׁ֣י בָ⁠אֵ֔פֶר אֵ֤בֶל יָחִיד֙ עֲשִׂ֣י לָ֔⁠ךְ מִסְפַּ֖ד תַּמְרוּרִ֑ים כִּ֣י פִתְאֹ֔ם יָבֹ֥א הַ⁠שֹּׁדֵ֖ד עָלֵֽי⁠נוּ׃","bȧţ-ʻami֤̇⁠y ẖigĕriy-şá̂q֙ wĕ⁠hiţĕpȧlĕ̇şǐ֣y bá⁠ʼé֔per ʼé֤bel yáẖiyd֙ ʻàşî֣y lá֔⁠kĕ misĕpȧ֖d ţȧmĕrẇri֑ym ki֣̇y piţĕʼò֔m yábò֥ʼ ha⁠şò̇̌dé֖d ʻáléֽy⁠nẇ׃"],[6,27,"בָּח֛וֹן נְתַתִּ֥י⁠ךָ בְ⁠עַמִּ֖⁠י מִבְצָ֑ר וְ⁠תֵדַ֕ע וּ⁠בָחַנְתָּ֖ אֶת־דַּרְכָּֽ⁠ם׃","bá̇ẖ֛wòn nĕţaţi֥̇y⁠ká bĕ⁠ʻami֖̇⁠y mibĕẕá֑r wĕ⁠ţéda֕ʻ ẇ⁠báẖanĕţá֖̇ ʼeţ-dȧrĕkáֽ̇⁠m׃"],[6,28,"כֻּלָּ⁠ם֙ סָרֵ֣י סֽוֹרְרִ֔ים הֹלְכֵ֥י רָכִ֖יל נְחֹ֣שֶׁת וּ⁠בַרְזֶ֑ל כֻּלָּ֥⁠ם מַשְׁחִיתִ֖ים הֵֽמָּה׃","ku̇lá̇⁠m֙ sáré֣y sֽwòrĕri֔ym hòlĕké֥y ráki֖yl nĕẖò֣şěţ ẇ⁠barĕze֑l ku̇lá֥̇⁠m maşĕ̌ẖiyţi֖ym héֽmá̇h׃"],[6,29,"נָחַ֣ר מַפֻּ֔חַ מ⁠אשת⁠ם עֹפָ֑רֶת לַ⁠שָּׁוְא֙ צָרַ֣ף צָר֔וֹף וְ⁠רָעִ֖ים לֹ֥א נִתָּֽקוּ׃","náẖa֣r mapu̇֔ẖa m⁠ʼşţ⁠m ʻòpá֑reţ la⁠şá̇̌wĕʼ֙ ẕára֣p ẕár֔wòp wĕ⁠ráʻi֖ym lò֥ʼ niţáֽ̇qẇ׃"],[6,30,"כֶּ֣סֶף נִמְאָ֔ס קָרְא֖וּ לָ⁠הֶ֑ם כִּֽי־מָאַ֥ס יְהוָ֖ה בָּ⁠הֶֽם׃פ","kė֣sep nimĕʼá֔s qárĕʼ֖ẇ lá⁠he֑m kiֽ̇y-máʼa֥s yĕhwá֖h bá̇⁠heֽm׃p"],[7,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר הָיָ֣ה אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","ha⁠dá̇bár֙ ʼàşě֣r háyá֣h ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[7,2,"עֲמֹ֗ד בְּ⁠שַׁ֨עַר֙ בֵּ֣ית יְהוָ֔ה וְ⁠קָרָ֣אתָ שָּׁ֔ם אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה וְ⁠אָמַרְתָּ֞ שִׁמְע֣וּ דְבַר־יְהוָ֗ה כָּל־יְהוּדָה֙ הַ⁠בָּאִים֙ בַּ⁠שְּׁעָרִ֣ים הָ⁠אֵ֔לֶּה לְ⁠הִֽשְׁתַּחֲוֺ֖ת לַ⁠יהוָֽה׃ס","ʻàmò֗d bĕ̇⁠şǎ֨ʻar֙ bé֣̇yţ yĕhwá֔h wĕ⁠qárá֣ʼţá şá̇̌֔m ʼeţ-ha⁠dá̇bá֖r ha⁠zė֑h wĕ⁠ʼámarĕţá̇֞ şǐmĕʻ֣ẇ dĕbar-yĕhwá֗h ká̇l-yĕhẇdáh֙ ha⁠bá̇ʼiym֙ bȧ⁠şĕ̇̌ʻári֣ym há⁠ʼé֔lėh lĕ⁠hiֽşĕ̌ţȧẖàwֺ֖ţ la⁠yhwáֽh׃s"],[7,3,"כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הֵיטִ֥יבוּ דַרְכֵי⁠כֶ֖ם וּ⁠מַֽעַלְלֵי⁠כֶ֑ם וַ⁠אֲשַׁכְּנָ֣ה אֶתְ⁠כֶ֔ם בַּ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l héyti֥ybẇ darĕkéy⁠ke֖m ẇ⁠maֽʻalĕléy⁠ke֑m wa⁠ʼàşǎkĕ̇ná֣h ʼeţĕ⁠ke֔m bȧ⁠má̇q֥wòm ha⁠zėֽh׃"],[7,4,"אַל־תִּבְטְח֣וּ לָ⁠כֶ֔ם אֶל־דִּבְרֵ֥י הַ⁠שֶּׁ֖קֶר לֵ⁠אמֹ֑ר הֵיכַ֤ל יְהוָה֙ הֵיכַ֣ל יְהוָ֔ה הֵיכַ֥ל יְהוָ֖ה הֵֽמָּה׃","ʼal-ţi̇bĕtĕẖ֣ẇ lá⁠ke֔m ʼel-di̇bĕré֥y ha⁠şė֖̌qer lé⁠ʼmò֑r héyka֤l yĕhwáh֙ héyka֣l yĕhwá֔h héyka֥l yĕhwá֖h héֽmá̇h׃"],[7,5,"כִּ֤י אִם־הֵיטֵיב֙ תֵּיטִ֔יבוּ אֶת־דַּרְכֵי⁠כֶ֖ם וְ⁠אֶת־מַֽעַלְלֵי⁠כֶ֑ם אִם־עָשׂ֤וֹ תַֽעֲשׂוּ֙ מִשְׁפָּ֔ט בֵּ֥ין אִ֖ישׁ וּ⁠בֵ֥ין רֵעֵֽ⁠הוּ׃","ki֤̇y ʼim-héytéyb֙ ţé̇yti֔ybẇ ʼeţ-dȧrĕkéy⁠ke֖m wĕ⁠ʼeţ-maֽʻalĕléy⁠ke֑m ʼim-ʻáş֤̂wò ţaֽʻàş̂ẇ֙ mişĕ̌pá̇֔t bé֥̇yn ʼi֖yş̌ ẇ⁠bé֥yn réʻéֽ⁠hẇ׃"],[7,6,"גֵּ֣ר יָת֤וֹם וְ⁠אַלְמָנָה֙ לֹ֣א תַֽעֲשֹׁ֔קוּ וְ⁠דָ֣ם נָקִ֔י אַֽל־תִּשְׁפְּכ֖וּ בַּ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וְ⁠אַחֲרֵ֨י אֱלֹהִ֧ים אֲחֵרִ֛ים לֹ֥א תֵלְכ֖וּ לְ⁠רַ֥ע לָ⁠כֶֽם׃","gé֣̇r yáţ֤wòm wĕ⁠ʼalĕmánáh֙ lò֣ʼ ţaֽʻàşò̌֔qẇ wĕ⁠dá֣m náqi֔y ʼaֽl-ţi̇şĕ̌pĕ̇k֖ẇ bȧ⁠má̇q֣wòm ha⁠zė֑h wĕ⁠ʼaẖàré֨y ʼèlòhi֧ym ʼàẖéri֛ym lò֥ʼ ţélĕk֖ẇ lĕ⁠ra֥ʻ lá⁠keֽm׃"],[7,7,"וְ⁠שִׁכַּנְתִּ֤י אֶתְ⁠כֶם֙ בַּ⁠מָּק֣וֹם הַ⁠זֶּ֔ה בָּ⁠אָ֕רֶץ אֲשֶׁ֥ר נָתַ֖תִּי לַ⁠אֲבֽוֹתֵי⁠כֶ֑ם לְ⁠מִן־עוֹלָ֖ם וְ⁠עַד־עוֹלָֽם׃","wĕ⁠şǐkȧnĕţi֤̇y ʼeţĕ⁠kem֙ bȧ⁠má̇q֣wòm ha⁠zė֔h bá̇⁠ʼá֕reẕ ʼàşě֥r náţa֖ţi̇y la⁠ʼàbֽwòţéy⁠ke֑m lĕ⁠min-ʻwòlá֖m wĕ⁠ʻad-ʻwòláֽm׃"],[7,8,"הִנֵּ֤ה אַתֶּם֙ בֹּטְחִ֣ים לָ⁠כֶ֔ם עַל־דִּבְרֵ֖י הַ⁠שָּׁ֑קֶר לְ⁠בִלְתִּ֖י הוֹעִֽיל׃","hiné֤̇h ʼaţėm֙ bò̇tĕẖi֣ym lá⁠ke֔m ʻal-di̇bĕré֖y ha⁠şá֑̇̌qer lĕ⁠bilĕţi֖̇y hwòʻiֽyl׃"],[7,9,"הֲ⁠גָנֹ֤ב ׀ רָצֹ֨חַ֙ וְֽ⁠נָאֹ֔ף וְ⁠הִשָּׁבֵ֥עַ לַ⁠שֶּׁ֖קֶר וְ⁠קַטֵּ֣ר לַ⁠בָּ֑עַל וְ⁠הָלֹ֗ךְ אַחֲרֵ֛י אֱלֹהִ֥ים אֲחֵרִ֖ים אֲשֶׁ֥ר לֹֽא־יְדַעְתֶּֽם׃","hà⁠gánò֤b ׀ ráẕò֨ẖa֙ wĕֽ⁠náʼò֔p wĕ⁠hişá̇̌bé֥ʻa la⁠şė֖̌qer wĕ⁠qaté֣̇r la⁠bá֑̇ʻal wĕ⁠hálò֗kĕ ʼaẖàré֛y ʼèlòhi֥ym ʼàẖéri֖ym ʼàşě֥r lòֽʼ-yĕdaʻĕţėֽm׃"],[7,10,"וּ⁠בָאתֶ֞ם וַ⁠עֲמַדְתֶּ֣ם לְ⁠פָנַ֗⁠י בַּ⁠בַּ֤יִת הַ⁠זֶּה֙ אֲשֶׁ֣ר נִקְרָא־שְׁמִ֣⁠י עָלָ֔י⁠ו וַ⁠אֲמַרְתֶּ֖ם נִצַּ֑לְנוּ לְמַ֣עַן עֲשׂ֔וֹת אֵ֥ת כָּל־הַ⁠תּוֹעֵב֖וֹת הָ⁠אֵֽלֶּה׃","ẇ⁠báʼţe֞m wa⁠ʻàmadĕţė֣m lĕ⁠pána֗⁠y bȧ⁠bȧ֤yiţ ha⁠zėh֙ ʼàşě֣r niqĕráʼ-şĕ̌mi֣⁠y ʻálá֔y⁠w wa⁠ʼàmarĕţė֖m niẕȧ֑lĕnẇ lĕma֣ʻan ʻàş̂֔wòţ ʼé֥ţ ká̇l-ha⁠ţ̇wòʻéb֖wòţ há⁠ʼéֽlėh׃"],[7,11,"הַ⁠מְעָרַ֣ת פָּרִצִ֗ים הָיָ֨ה הַ⁠בַּ֧יִת הַ⁠זֶּ֛ה אֲשֶׁר־נִקְרָֽא־שְׁמִ֥⁠י עָלָ֖י⁠ו בְּ⁠עֵינֵי⁠כֶ֑ם גַּ֧ם אָנֹכִ֛י הִנֵּ֥ה רָאִ֖יתִי נְאֻם־יְהוָֽה׃ס","ha⁠mĕʻára֣ţ pá̇riẕi֗ym háyá֨h ha⁠bȧ֧yiţ ha⁠zė֛h ʼàşěr-niqĕráֽʼ-şĕ̌mi֥⁠y ʻálá֖y⁠w bĕ̇⁠ʻéynéy⁠ke֑m gȧ֧m ʼánòki֛y hiné֥̇h ráʼi֖yţiy nĕʼum-yĕhwáֽh׃s"],[7,12,"כִּ֣י לְכוּ־נָ֗א אֶל־מְקוֹמִ⁠י֙ אֲשֶׁ֣ר בְּ⁠שִׁיל֔וֹ אֲשֶׁ֨ר שִׁכַּ֧נְתִּֽי שְׁמִ֛⁠י שָׁ֖ם בָּ⁠רִֽאשׁוֹנָ֑ה וּ⁠רְאוּ֙ אֵ֣ת אֲשֶׁר־עָשִׂ֣יתִי ל֔⁠וֹ מִ⁠פְּנֵ֕י רָעַ֖ת עַמִּ֥⁠י יִשְׂרָאֵֽל׃","ki֣̇y lĕkẇ-ná֗ʼ ʼel-mĕqwòmi⁠y֙ ʼàşě֣r bĕ̇⁠şǐyl֔wò ʼàşě֨r şǐkȧ֧nĕţiֽ̇y şĕ̌mi֛⁠y şá֖̌m bá̇⁠riֽʼş̌wòná֑h ẇ⁠rĕʼẇ֙ ʼé֣ţ ʼàşěr-ʻáşî֣yţiy l֔⁠wò mi⁠pĕ̇né֕y ráʻa֖ţ ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[7,13,"וְ⁠עַתָּ֗ה יַ֧עַן עֲשׂוֹתְ⁠כֶ֛ם אֶת־כָּל־הַ⁠מַּֽעֲשִׂ֥ים הָ⁠אֵ֖לֶּה נְאֻם־יְהוָ֑ה וָ⁠אֲדַבֵּ֨ר אֲלֵי⁠כֶ֜ם הַשְׁכֵּ֤ם וְ⁠דַבֵּר֙ וְ⁠לֹ֣א שְׁמַעְתֶּ֔ם וָ⁠אֶקְרָ֥א אֶתְ⁠כֶ֖ם וְ⁠לֹ֥א עֲנִיתֶֽם׃","wĕ⁠ʻaţá̇֗h ya֧ʻan ʻàş̂wòţĕ⁠ke֛m ʼeţ-ká̇l-ha⁠ṁֽaʻàşî֥ym há⁠ʼé֖lėh nĕʼum-yĕhwá֑h wá⁠ʼàdabé̇֨r ʼàléy⁠ke֜m haşĕ̌ké֤̇m wĕ⁠dabé̇r֙ wĕ⁠lò֣ʼ şĕ̌maʻĕţė֔m wá⁠ʼeqĕrá֥ʼ ʼeţĕ⁠ke֖m wĕ⁠lò֥ʼ ʻàniyţeֽm׃"],[7,14,"וְ⁠עָשִׂ֜יתִי לַ⁠בַּ֣יִת ׀ אֲשֶׁ֧ר נִֽקְרָא־שְׁמִ֣⁠י עָלָ֗י⁠ו אֲשֶׁ֤ר אַתֶּם֙ בֹּטְחִ֣ים בּ֔⁠וֹ וְ⁠לַ֨⁠מָּק֔וֹם אֲשֶׁר־נָתַ֥תִּי לָ⁠כֶ֖ם וְ⁠לַ⁠אֲבֽוֹתֵי⁠כֶ֑ם כַּ⁠אֲשֶׁ֥ר עָשִׂ֖יתִי לְ⁠שִׁלֽוֹ׃","wĕ⁠ʻáşî֜yţiy la⁠bȧ֣yiţ ׀ ʼàşě֧r niֽqĕráʼ-şĕ̌mi֣⁠y ʻálá֗y⁠w ʼàşě֤r ʼaţėm֙ bò̇tĕẖi֣ym ḃ֔⁠wò wĕ⁠la֨⁠má̇q֔wòm ʼàşěr-náţa֥ţi̇y lá⁠ke֖m wĕ⁠la⁠ʼàbֽwòţéy⁠ke֑m kȧ⁠ʼàşě֥r ʻáşî֖yţiy lĕ⁠şǐlֽwò׃"],[7,15,"וְ⁠הִשְׁלַכְתִּ֥י אֶתְ⁠כֶ֖ם מֵ⁠עַ֣ל פָּנָ֑⁠י כַּ⁠אֲשֶׁ֤ר הִשְׁלַ֨כְתִּי֙ אֶת־כָּל־אֲחֵי⁠כֶ֔ם אֵ֖ת כָּל־זֶ֥רַע אֶפְרָֽיִם׃ס","wĕ⁠hişĕ̌lakĕţi֥̇y ʼeţĕ⁠ke֖m mé⁠ʻa֣l pá̇ná֑⁠y kȧ⁠ʼàşě֤r hişĕ̌la֨kĕţi̇y֙ ʼeţ-ká̇l-ʼàẖéy⁠ke֔m ʼé֖ţ ká̇l-ze֥raʻ ʼepĕráֽyim׃s"],[7,16,"וְ⁠אַתָּ֞ה אַל־תִּתְפַּלֵּ֣ל ׀ בְּעַד־הָ⁠עָ֣ם הַ⁠זֶּ֗ה וְ⁠אַל־תִּשָּׂ֧א בַעֲדָ֛⁠ם רִנָּ֥ה וּ⁠תְפִלָּ֖ה וְ⁠אַל־תִּפְגַּע־בִּ֑⁠י כִּי־אֵינֶ֥⁠נִּי שֹׁמֵ֖עַ אֹתָֽ⁠ךְ׃","wĕ⁠ʼaţá̇֞h ʼal-ţi̇ţĕpȧlé֣̇l ׀ bĕ̇ʻad-há⁠ʻá֣m ha⁠zė֗h wĕ⁠ʼal-ţi̇şá֧̇̂ʼ baʻàdá֛⁠m riná֥̇h ẇ⁠ţĕpilá֖̇h wĕ⁠ʼal-ţi̇pĕgȧʻ-bi֑̇⁠y ki̇y-ʼéyne֥⁠ni̇y şò̌mé֖ʻa ʼòţáֽ⁠kĕ׃"],[7,17,"הַֽ⁠אֵינְ⁠ךָ֣ רֹאֶ֔ה מָ֛ה הֵ֥מָּה עֹשִׂ֖ים בְּ⁠עָרֵ֣י יְהוּדָ֑ה וּ⁠בְ⁠חֻצ֖וֹת יְרוּשָׁלִָֽם׃","haֽ⁠ʼéynĕ⁠ká֣ ròʼe֔h má֛h hé֥má̇h ʻòşî֖ym bĕ̇⁠ʻáré֣y yĕhẇdá֑h ẇ⁠bĕ⁠ẖuẕ֖wòţ yĕrẇşá̌liáֽm׃"],[7,18,"הַ⁠בָּנִ֞ים מְלַקְּטִ֣ים עֵצִ֗ים וְ⁠הָֽ⁠אָבוֹת֙ מְבַעֲרִ֣ים אֶת־הָ⁠אֵ֔שׁ וְ⁠הַ⁠נָּשִׁ֖ים לָשׁ֣וֹת בָּצֵ֑ק לַ⁠עֲשׂ֨וֹת כַּוָּנִ֜ים לִ⁠מְלֶ֣כֶת הַ⁠שָּׁמַ֗יִם וְ⁠הַסֵּ֤ךְ נְסָכִים֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים לְמַ֖עַן הַכְעִסֵֽ⁠נִי׃","ha⁠bá̇ni֞ym mĕlaqĕ̇ti֣ym ʻéẕi֗ym wĕ⁠háֽ⁠ʼábwòţ֙ mĕbaʻàri֣ym ʼeţ-há⁠ʼé֔ş̌ wĕ⁠ha⁠ná̇şǐ֖ym láş֣̌wòţ bá̇ẕé֑q la⁠ʻàş̂֨wòţ kȧwá̇ni֜ym li⁠mĕle֣keţ ha⁠şá̇̌ma֗yim wĕ⁠hasé֤̇kĕ nĕsákiym֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym lĕma֖ʻan hakĕʻiséֽ⁠niy׃"],[7,19,"הַ⁠אֹתִ֛⁠י הֵ֥ם מַכְעִסִ֖ים נְאֻם־יְהוָ֑ה הֲ⁠ל֣וֹא אֹתָ֔⁠ם לְמַ֖עַן בֹּ֥שֶׁת פְּנֵי⁠הֶֽם׃ס","ha⁠ʼòţi֛⁠y hé֥m makĕʻisi֖ym nĕʼum-yĕhwá֑h hà⁠l֣wòʼ ʼòţá֔⁠m lĕma֖ʻan bò֥̇şěţ pĕ̇néy⁠heֽm׃s"],[7,20,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה הִנֵּ֨ה אַפִּ֤⁠י וַֽ⁠חֲמָתִ⁠י֙ נִתֶּ֨כֶת֙ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה עַל־הָֽ⁠אָדָם֙ וְ⁠עַל־הַ⁠בְּהֵמָ֔ה וְ⁠עַל־עֵ֥ץ הַ⁠שָּׂדֶ֖ה וְ⁠עַל־פְּרִ֣י הָֽ⁠אֲדָמָ֑ה וּ⁠בָעֲרָ֖ה וְ⁠לֹ֥א תִכְבֶּֽה׃ס","lá⁠ké֞n kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h hiné̇֨h ʼapi֤̇⁠y waֽ⁠ẖàmáţi⁠y֙ niţė֨keţ֙ ʼel-ha⁠má̇q֣wòm ha⁠zė֔h ʻal-háֽ⁠ʼádám֙ wĕ⁠ʻal-ha⁠bĕ̇hémá֔h wĕ⁠ʻal-ʻé֥ẕ ha⁠şá̇̂de֖h wĕ⁠ʻal-pĕ̇ri֣y háֽ⁠ʼàdámá֑h ẇ⁠báʻàrá֖h wĕ⁠lò֥ʼ ţikĕbėֽh׃s"],[7,21,"כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל עֹלוֹתֵי⁠כֶ֛ם סְפ֥וּ עַל־זִבְחֵי⁠כֶ֖ם וְ⁠אִכְל֥וּ בָשָֽׂר׃","kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhé֣y yişĕ̂ráʼé֑l ʻòlwòţéy⁠ke֛m sĕp֥ẇ ʻal-zibĕẖéy⁠ke֖m wĕ⁠ʼikĕl֥ẇ báşáֽ̂r׃"],[7,22,"כִּ֠י לֹֽא־דִבַּ֤רְתִּי אֶת־אֲבֽוֹתֵי⁠כֶם֙ וְ⁠לֹ֣א צִוִּיתִ֔י⁠ם בְּ⁠י֛וֹם הוציא אוֹתָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם עַל־דִּבְרֵ֥י עוֹלָ֖ה וָ⁠זָֽבַח׃","ki̇֠y lòֽʼ-dibȧ֤rĕţi̇y ʼeţ-ʼàbֽwòţéy⁠kem֙ wĕ⁠lò֣ʼ ẕiwi̇yţi֔y⁠m bĕ̇⁠y֛wòm hwẕyʼ ʼwòţá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim ʻal-di̇bĕré֥y ʻwòlá֖h wá⁠záֽbaẖ׃"],[7,23,"כִּ֣י אִֽם־אֶת־הַ⁠דָּבָ֣ר הַ֠⁠זֶּה צִוִּ֨יתִי אוֹתָ֤⁠ם לֵ⁠אמֹר֙ שִׁמְע֣וּ בְ⁠קוֹלִ֔⁠י וְ⁠הָיִ֤יתִי לָ⁠כֶם֙ לֵֽ⁠אלֹהִ֔ים וְ⁠אַתֶּ֖ם תִּֽהְיוּ־לִ֣⁠י לְ⁠עָ֑ם וַ⁠הֲלַכְתֶּ֗ם בְּ⁠כָל־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר אֲצַוֶּ֣ה אֶתְ⁠כֶ֔ם לְמַ֖עַן יִיטַ֥ב לָ⁠כֶֽם׃","ki֣̇y ʼiֽm-ʼeţ-ha⁠dá̇bá֣r ha֠⁠zėh ẕiwi̇֨yţiy ʼwòţá֤⁠m lé⁠ʼmòr֙ şǐmĕʻ֣ẇ bĕ⁠qwòli֔⁠y wĕ⁠háyi֤yţiy lá⁠kem֙ léֽ⁠ʼlòhi֔ym wĕ⁠ʼaţė֖m ţiֽ̇hĕyẇ-li֣⁠y lĕ⁠ʻá֑m wa⁠hàlakĕţė֗m bĕ̇⁠kál-ha⁠dė֨rekĕ֙ ʼàşě֣r ʼàẕawė֣h ʼeţĕ⁠ke֔m lĕma֖ʻan yiyta֥b lá⁠keֽm׃"],[7,24,"וְ⁠לֹ֤א שָֽׁמְעוּ֙ וְ⁠לֹֽא־הִטּ֣וּ אֶת־אָזְנָ֔⁠ם וַ⁠יֵּֽלְכוּ֙ בְּ⁠מֹ֣עֵצ֔וֹת בִּ⁠שְׁרִר֖וּת לִבָּ֣⁠ם הָ⁠רָ֑ע וַ⁠יִּהְי֥וּ לְ⁠אָח֖וֹר וְ⁠לֹ֥א לְ⁠פָנִֽים׃","wĕ⁠lò֤ʼ şáֽ̌mĕʻẇ֙ wĕ⁠lòֽʼ-hiṫ֣ẇ ʼeţ-ʼázĕná֔⁠m wa⁠yéֽ̇lĕkẇ֙ bĕ̇⁠mò֣ʻéẕ֔wòţ bi̇⁠şĕ̌rir֖ẇţ libá֣̇⁠m há⁠rá֑ʻ wa⁠yi̇hĕy֥ẇ lĕ⁠ʼáẖ֖wòr wĕ⁠lò֥ʼ lĕ⁠pániֽym׃"],[7,25,"לְ⁠מִן־הַ⁠יּ֗וֹם אֲשֶׁ֨ר יָצְא֤וּ אֲבֽוֹתֵי⁠כֶם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וָ⁠אֶשְׁלַ֤ח אֲלֵי⁠כֶם֙ אֶת־כָּל־עֲבָדַ֣⁠י הַ⁠נְּבִיאִ֔ים י֖וֹם הַשְׁכֵּ֥ם וְ⁠שָׁלֹֽחַ׃","lĕ⁠min-ha⁠ẏ֗wòm ʼàşě֨r yáẕĕʼ֤ẇ ʼàbֽwòţéy⁠kem֙ mé⁠ʼe֣reẕ miẕĕra֔yim ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h wá⁠ʼeşĕ̌la֤ẖ ʼàléy⁠kem֙ ʼeţ-ká̇l-ʻàbáda֣⁠y ha⁠nĕ̇biyʼi֔ym y֖wòm haşĕ̌ké֥̇m wĕ⁠şá̌lòֽẖa׃"],[7,26,"וְ⁠ל֤וֹא שָׁמְעוּ֙ אֵלַ֔⁠י וְ⁠לֹ֥א הִטּ֖וּ אֶת־אָזְנָ֑⁠ם וַ⁠יַּקְשׁוּ֙ אֶת־עָרְפָּ֔⁠ם הֵרֵ֖עוּ מֵ⁠אֲבוֹתָֽ⁠ם׃","wĕ⁠l֤wòʼ şá̌mĕʻẇ֙ ʼéla֔⁠y wĕ⁠lò֥ʼ hiṫ֖ẇ ʼeţ-ʼázĕná֑⁠m wa⁠yȧqĕş̌ẇ֙ ʼeţ-ʻárĕpá̇֔⁠m héré֖ʻẇ mé⁠ʼàbwòţáֽ⁠m׃"],[7,27,"וְ⁠דִבַּרְתָּ֤ אֲלֵי⁠הֶם֙ אֶת־כָּל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וְ⁠לֹ֥א יִשְׁמְע֖וּ אֵלֶ֑י⁠ךָ וְ⁠קָרָ֥אתָ אֲלֵי⁠הֶ֖ם וְ⁠לֹ֥א יַעֲנֽוּ⁠כָה׃","wĕ⁠dibȧrĕţá֤̇ ʼàléy⁠hem֙ ʼeţ-ká̇l-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wĕ⁠lò֥ʼ yişĕ̌mĕʻ֖ẇ ʼéle֑y⁠ká wĕ⁠qárá֥ʼţá ʼàléy⁠he֖m wĕ⁠lò֥ʼ yaʻànֽẇ⁠káh׃"],[7,28,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם זֶ֤ה הַ⁠גּוֹי֙ אֲשֶׁ֣ר לֽוֹא־שָׁמְע֗וּ בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהָ֔י⁠ו וְ⁠לֹ֥א לָקְח֖וּ מוּסָ֑ר אָֽבְדָה֙ הָֽ⁠אֱמוּנָ֔ה וְ⁠נִכְרְתָ֖ה מִ⁠פִּי⁠הֶֽם׃ס","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m ze֤h ha⁠ġwòy֙ ʼàşě֣r lֽwòʼ-şá̌mĕʻ֗ẇ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhá֔y⁠w wĕ⁠lò֥ʼ láqĕẖ֖ẇ mẇsá֑r ʼáֽbĕdáh֙ háֽ⁠ʼèmẇná֔h wĕ⁠nikĕrĕţá֖h mi⁠pi̇y⁠heֽm׃s"],[7,29,"גָּזִּ֤י נִזְרֵ⁠ךְ֙ וְֽ⁠הַשְׁלִ֔יכִי וּ⁠שְׂאִ֥י עַל־שְׁפָיִ֖ם קִינָ֑ה כִּ֚י מָאַ֣ס יְהוָ֔ה וַ⁠יִּטֹּ֖שׁ אֶת־דּ֥וֹר עֶבְרָתֽ⁠וֹ׃","gá̇zi֤̇y nizĕré⁠kĕ֙ wĕֽ⁠haşĕ̌li֔ykiy ẇ⁠şĕ̂ʼi֥y ʻal-şĕ̌páyi֖m qiyná֑h ki֚̇y máʼa֣s yĕhwá֔h wa⁠yi̇tò֖̇ş̌ ʼeţ-ḋ֥wòr ʻebĕráţֽ⁠wò׃"],[7,30,"כִּֽי־עָשׂ֨וּ בְנֵי־יְהוּדָ֥ה הָ⁠רַ֛ע בְּ⁠עֵינַ֖⁠י נְאֻום־יְהוָ֑ה שָׂ֣מוּ שִׁקּֽוּצֵי⁠הֶ֗ם בַּ⁠בַּ֛יִת אֲשֶׁר־נִקְרָא־שְׁמִ֥⁠י עָלָ֖י⁠ו לְ⁠טַמְּאֽ⁠וֹ׃","kiֽ̇y-ʻáş̂֨ẇ bĕnéy-yĕhẇdá֥h há⁠ra֛ʻ bĕ̇⁠ʻéyna֖⁠y nĕʼuwm-yĕhwá֑h şá֣̂mẇ şǐqֽ̇ẇẕéy⁠he֗m bȧ⁠bȧ֛yiţ ʼàşěr-niqĕráʼ-şĕ̌mi֥⁠y ʻálá֖y⁠w lĕ⁠tamĕ̇ʼֽ⁠wò׃"],[7,31,"וּ⁠בָנ֞וּ בָּמ֣וֹת הַ⁠תֹּ֗פֶת אֲשֶׁר֙ בְּ⁠גֵ֣יא בֶן־הִנֹּ֔ם לִ⁠שְׂרֹ֛ף אֶת־בְּנֵי⁠הֶ֥ם וְ⁠אֶת־בְּנֹתֵי⁠הֶ֖ם בָּ⁠אֵ֑שׁ אֲשֶׁר֙ לֹ֣א צִוִּ֔יתִי וְ⁠לֹ֥א עָלְתָ֖ה עַל־לִבִּֽ⁠י׃ס","ẇ⁠bán֞ẇ bá̇m֣wòţ ha⁠ţò̇֗peţ ʼàşěr֙ bĕ̇⁠gé֣yʼ ben-hinò̇֔m li⁠şĕ̂rò֛p ʼeţ-bĕ̇néy⁠he֥m wĕ⁠ʼeţ-bĕ̇nòţéy⁠he֖m bá̇⁠ʼé֑ş̌ ʼàşěr֙ lò֣ʼ ẕiwi̇֔yţiy wĕ⁠lò֥ʼ ʻálĕţá֖h ʻal-libiֽ̇⁠y׃s"],[7,32,"לָ⁠כֵ֞ן הִנֵּֽה־יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וְ⁠לֹא־יֵאָמֵ֨ר ע֤וֹד הַ⁠תֹּ֨פֶת֙ וְ⁠גֵ֣יא בֶן־הִנֹּ֔ם כִּ֖י אִם־גֵּ֣יא הַ⁠הֲרֵגָ֑ה וְ⁠קָבְר֥וּ בְ⁠תֹ֖פֶת מֵ⁠אֵ֥ין מָקֽוֹם׃","lá⁠ké֞n hinéֽ̇h-yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wĕ⁠lòʼ-yéʼámé֨r ʻ֤wòd ha⁠ţò̇֨peţ֙ wĕ⁠gé֣yʼ ben-hinò̇֔m ki֖̇y ʼim-gé֣̇yʼ ha⁠hàrégá֑h wĕ⁠qábĕr֥ẇ bĕ⁠ţò֖peţ mé⁠ʼé֥yn máqֽwòm׃"],[7,33,"וְֽ⁠הָ֨יְתָ֜ה נִבְלַ֨ת הָ⁠עָ֤ם הַ⁠זֶּה֙ לְ⁠מַֽאֲכָ֔ל לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֣ת הָ⁠אָ֑רֶץ וְ⁠אֵ֖ין מַחֲרִֽיד׃","wĕֽ⁠há֨yĕţá֜h nibĕla֨ţ há⁠ʻá֤m ha⁠zėh֙ lĕ⁠maֽʼàká֔l lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֣ţ há⁠ʼá֑reẕ wĕ⁠ʼé֖yn maẖàriֽyd׃"],[7,34,"וְ⁠הִשְׁבַּתִּ֣י ׀ מֵ⁠עָרֵ֣י יְהוּדָ֗ה וּ⁠מֵֽ⁠חֻצוֹת֙ יְר֣וּשָׁלִַ֔ם ק֤וֹל שָׂשׂוֹן֙ וְ⁠ק֣וֹל שִׂמְחָ֔ה ק֥וֹל חָתָ֖ן וְ⁠ק֣וֹל כַּלָּ֑ה כִּ֥י לְ⁠חָרְבָּ֖ה תִּהְיֶ֥ה הָ⁠אָֽרֶץ׃","wĕ⁠hişĕ̌bȧţi֣̇y ׀ mé⁠ʻáré֣y yĕhẇdá֗h ẇ⁠méֽ⁠ẖuẕwòţ֙ yĕr֣ẇşá̌lia֔m q֤wòl şá̂ş̂wòn֙ wĕ⁠q֣wòl şîmĕẖá֔h q֥wòl ẖáţá֖n wĕ⁠q֣wòl kȧlá֑̇h ki֥̇y lĕ⁠ẖárĕbá֖̇h ţi̇hĕye֥h há⁠ʼáֽreẕ׃"],[8,1,"בָּ⁠עֵ֣ת הַ⁠הִ֣יא נְאֻם־יְהוָ֡ה ו⁠יציאו אֶת־עַצְמ֣וֹת מַלְכֵֽי־יְהוּדָ֣ה וְ⁠אֶת־עַצְמוֹת־שָׂרָי⁠ו֩ וְ⁠אֶת־עַצְמ֨וֹת הַ⁠כֹּהֲנִ֜ים וְ⁠אֵ֣ת ׀ עַצְמ֣וֹת הַ⁠נְּבִיאִ֗ים וְ⁠אֵ֛ת עַצְמ֥וֹת יוֹשְׁבֵֽי־יְרוּשָׁלִָ֖ם מִ⁠קִּבְרֵי⁠הֶֽם׃","bá̇⁠ʻé֣ţ ha⁠hi֣yʼ nĕʼum-yĕhwá֡h w⁠yẕyʼw ʼeţ-ʻaẕĕm֣wòţ malĕkéֽy-yĕhẇdá֣h wĕ⁠ʼeţ-ʻaẕĕmwòţ-şá̂ráy⁠w֩ wĕ⁠ʼeţ-ʻaẕĕm֨wòţ ha⁠kò̇hàni֜ym wĕ⁠ʼé֣ţ ׀ ʻaẕĕm֣wòţ ha⁠nĕ̇biyʼi֗ym wĕ⁠ʼé֛ţ ʻaẕĕm֥wòţ ywòşĕ̌béֽy-yĕrẇşá̌liá֖m mi⁠qi̇bĕréy⁠heֽm׃"],[8,2,"וּ⁠שְׁטָחוּ⁠ם֩ לַ⁠שֶּׁ֨מֶשׁ וְ⁠לַ⁠יָּרֵ֜חַ וּ⁠לְ⁠כֹ֣ל ׀ צְבָ֣א הַ⁠שָּׁמַ֗יִם אֲשֶׁ֨ר אֲהֵב֜וּ⁠ם וַ⁠אֲשֶׁ֤ר עֲבָדוּ⁠ם֙ וַֽ⁠אֲשֶׁר֙ הָלְכ֣וּ אַֽחֲרֵי⁠הֶ֔ם וַ⁠אֲשֶׁ֣ר דְּרָשׁ֔וּ⁠ם וַ⁠אֲשֶׁ֥ר הִֽשְׁתַּחֲו֖וּ לָ⁠הֶ֑ם לֹ֤א יֵאָֽסְפוּ֙ וְ⁠לֹ֣א יִקָּבֵ֔רוּ לְ⁠דֹ֛מֶן עַל־פְּנֵ֥י הָ⁠אֲדָמָ֖ה יִֽהְיֽוּ׃","ẇ⁠şĕ̌táẖẇ⁠m֩ la⁠şė̌֨meş̌ wĕ⁠la⁠yá̇ré֜ẖa ẇ⁠lĕ⁠kò֣l ׀ ẕĕbá֣ʼ ha⁠şá̇̌ma֗yim ʼàşě֨r ʼàhéb֜ẇ⁠m wa⁠ʼàşě֤r ʻàbádẇ⁠m֙ waֽ⁠ʼàşěr֙ hálĕk֣ẇ ʼaֽẖàréy⁠he֔m wa⁠ʼàşě֣r dĕ̇ráş̌֔ẇ⁠m wa⁠ʼàşě֥r hiֽşĕ̌ţȧẖàw֖ẇ lá⁠he֑m lò֤ʼ yéʼáֽsĕpẇ֙ wĕ⁠lò֣ʼ yiqá̇bé֔rẇ lĕ⁠dò֛men ʻal-pĕ̇né֥y há⁠ʼàdámá֖h yiֽhĕyֽẇ׃"],[8,3,"וְ⁠נִבְחַ֥ר מָ֨וֶת֙ מֵֽ⁠חַיִּ֔ים לְ⁠כֹ֗ל הַ⁠שְּׁאֵרִית֙ הַ⁠נִּשְׁאָרִ֔ים מִן־הַ⁠מִּשְׁפָּחָ֥ה הָֽ⁠רָעָ֖ה הַ⁠זֹּ֑את בְּ⁠כָל־הַ⁠מְּקֹמ֤וֹת הַ⁠נִּשְׁאָרִים֙ אֲשֶׁ֣ר הִדַּחְתִּ֣י⁠ם שָׁ֔ם נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃ס","wĕ⁠nibĕẖa֥r má֨weţ֙ méֽ⁠ẖayi̇֔ym lĕ⁠kò֗l ha⁠şĕ̇̌ʼériyţ֙ ha⁠ni̇şĕ̌ʼári֔ym min-ha⁠mi̇şĕ̌pá̇ẖá֥h háֽ⁠ráʻá֖h ha⁠zò֑̇ʼţ bĕ̇⁠kál-ha⁠mĕ̇qòm֤wòţ ha⁠ni̇şĕ̌ʼáriym֙ ʼàşě֣r hidȧẖĕţi֣̇y⁠m şá̌֔m nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃s"],[8,4,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם כֹּ֚ה אָמַ֣ר יְהוָ֔ה הֲ⁠יִפְּל֖וּ וְ⁠לֹ֣א יָק֑וּמוּ אִם־יָשׁ֖וּב וְ⁠לֹ֥א יָשֽׁוּב׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m kò֚̇h ʼáma֣r yĕhwá֔h hà⁠yipĕ̇l֖ẇ wĕ⁠lò֣ʼ yáq֑ẇmẇ ʼim-yáş֖̌ẇb wĕ⁠lò֥ʼ yáşֽ̌ẇb׃"],[8,5,"מַדּ֨וּעַ שׁוֹבְבָ֜ה הָ⁠עָ֥ם הַ⁠זֶּ֛ה יְרוּשָׁלִַ֖ם מְשֻׁבָ֣ה נִצַּ֑חַת הֶחֱזִ֨יקוּ֙ בַּ⁠תַּרְמִ֔ית מֵאֲנ֖וּ לָ⁠שֽׁוּב׃","maḋ֨ẇʻa ş̌wòbĕbá֜h há⁠ʻá֥m ha⁠zė֛h yĕrẇşá̌lia֖m mĕşǔbá֣h niẕȧ֑ẖaţ heẖèzi֨yqẇ֙ bȧ⁠ţȧrĕmi֔yţ méʼàn֖ẇ lá⁠şֽ̌ẇb׃"],[8,6,"הִקְשַׁ֤בְתִּי וָֽ⁠אֶשְׁמָע֙ לוֹא־כֵ֣ן יְדַבֵּ֔רוּ אֵ֣ין אִ֗ישׁ נִחָם֙ עַל־רָ֣עָת֔⁠וֹ לֵ⁠אמֹ֖ר מֶ֣ה עָשִׂ֑יתִי כֻּלֹּ֗⁠ה שָׁ֚ב ב⁠מרצות⁠ם כְּ⁠ס֥וּס שׁוֹטֵ֖ף בַּ⁠מִּלְחָמָֽה׃","hiqĕşǎ֤bĕţi̇y wáֽ⁠ʼeşĕ̌máʻ֙ lwòʼ-ké֣n yĕdabé̇֔rẇ ʼé֣yn ʼi֗yş̌ niẖám֙ ʻal-rá֣ʻáţ֔⁠wò lé⁠ʼmò֖r me֣h ʻáşî֑yţiy ku̇lò̇֗⁠h şá֚̌b b⁠mrẕwţ⁠m kĕ̇⁠s֥ẇs ş̌wòté֖p bȧ⁠mi̇lĕẖámáֽh׃"],[8,7,"גַּם־חֲסִידָ֣ה בַ⁠שָּׁמַ֗יִם יָֽדְעָה֙ מֽוֹעֲדֶ֔י⁠הָ וְ⁠תֹ֤ר ו⁠סוס וְ⁠עָג֔וּר שָׁמְר֖וּ אֶת־עֵ֣ת בֹּאָ֑⁠נָה וְ⁠עַמִּ֕⁠י לֹ֣א יָֽדְע֔וּ אֵ֖ת מִשְׁפַּ֥ט יְהוָֽה׃","gȧm-ẖàsiydá֣h ba⁠şá̇̌ma֗yim yáֽdĕʻáh֙ mֽwòʻàde֔y⁠há wĕ⁠ţò֤r w⁠sws wĕ⁠ʻág֔ẇr şá̌mĕr֖ẇ ʼeţ-ʻé֣ţ bò̇ʼá֑⁠náh wĕ⁠ʻami̇֕⁠y lò֣ʼ yáֽdĕʻ֔ẇ ʼé֖ţ mişĕ̌pȧ֥t yĕhwáֽh׃"],[8,8,"אֵיכָ֤ה תֹֽאמְרוּ֙ חֲכָמִ֣ים אֲנַ֔חְנוּ וְ⁠תוֹרַ֥ת יְהוָ֖ה אִתָּ֑⁠נוּ אָכֵן֙ הִנֵּ֣ה לַ⁠שֶּׁ֣קֶר עָשָׂ֔ה עֵ֖ט שֶׁ֥קֶר סֹפְרִֽים׃","ʼéyká֤h ţòֽʼmĕrẇ֙ ẖàkámi֣ym ʼàna֔ẖĕnẇ wĕ⁠ţwòra֥ţ yĕhwá֖h ʼiţá֑̇⁠nẇ ʼákén֙ hiné֣̇h la⁠şė֣̌qer ʻáşá̂֔h ʻé֖t şě֥qer sòpĕriֽym׃"],[8,9,"הֹבִ֣ישׁוּ חֲכָמִ֔ים חַ֖תּוּ וַ⁠יִּלָּכֵ֑דוּ הִנֵּ֤ה בִ⁠דְבַר־יְהוָה֙ מָאָ֔סוּ וְ⁠חָכְמַֽת־מֶ֖ה לָ⁠הֶֽם׃ס","hòbi֣yş̌ẇ ẖàkámi֔ym ẖa֖ţ̇ẇ wa⁠yi̇lá̇ké֑dẇ hiné֤̇h bi⁠dĕbar-yĕhwáh֙ máʼá֔sẇ wĕ⁠ẖákĕmaֽţ-me֖h lá⁠heֽm׃s"],[8,10,"לָ⁠כֵן֩ אֶתֵּ֨ן אֶת־נְשֵׁי⁠הֶ֜ם לַ⁠אֲחֵרִ֗ים שְׂדֽוֹתֵי⁠הֶם֙ לְ⁠י֣וֹרְשִׁ֔ים כִּ֤י מִ⁠קָּטֹן֙ וְ⁠עַד־גָּד֔וֹל כֻּלֹּ֖⁠ה בֹּצֵ֣עַ בָּ֑צַע מִ⁠נָּבִיא֙ וְ⁠עַד־כֹּהֵ֔ן כֻּלֹּ֖⁠ה עֹ֥שֶׂה שָּֽׁקֶר׃","lá⁠kén֩ ʼeţé̇֨n ʼeţ-nĕşé̌y⁠he֜m la⁠ʼàẖéri֗ym şĕ̂dֽwòţéy⁠hem֙ lĕ⁠y֣wòrĕşǐ֔ym ki֤̇y mi⁠qá̇tòn֙ wĕ⁠ʻad-gá̇d֔wòl ku̇lò֖̇⁠h bò̇ẕé֣ʻa bá֑̇ẕaʻ mi⁠ná̇biyʼ֙ wĕ⁠ʻad-kò̇hé֔n ku̇lò֖̇⁠h ʻò֥şêh şáֽ̇̌qer׃"],[8,11,"וַ⁠יְרַפּ֞וּ אֶת־שֶׁ֤בֶר בַּת־עַמִּ⁠י֙ עַל־נְקַלָּ֔ה לֵ⁠אמֹ֖ר שָׁל֣וֹם ׀ שָׁל֑וֹם וְ⁠אֵ֖ין שָׁלֽוֹם׃","wa⁠yĕraṗ֞ẇ ʼeţ-şě֤ber bȧţ-ʻami̇⁠y֙ ʻal-nĕqalá̇֔h lé⁠ʼmò֖r şá̌l֣wòm ׀ şá̌l֑wòm wĕ⁠ʼé֖yn şá̌lֽwòm׃"],[8,12,"הֹבִ֕שׁוּ כִּ֥י תוֹעֵבָ֖ה עָשׂ֑וּ גַּם־בּ֣וֹשׁ לֹֽא־יֵבֹ֗שׁוּ וְ⁠הִכָּלֵם֙ לֹ֣א יָדָ֔עוּ לָ⁠כֵ֞ן יִפְּל֣וּ בַ⁠נֹּפְלִ֗ים בְּ⁠עֵ֧ת פְּקֻדָּתָ֛⁠ם יִכָּשְׁל֖וּ אָמַ֥ר יְהוָֽה׃ס","hòbi֕ş̌ẇ ki֥̇y ţwòʻébá֖h ʻáş֑̂ẇ gȧm-ḃ֣wòş̌ lòֽʼ-yébò֗ş̌ẇ wĕ⁠hiká̇lém֙ lò֣ʼ yádá֔ʻẇ lá⁠ké֞n yipĕ̇l֣ẇ ba⁠nò̇pĕli֗ym bĕ̇⁠ʻé֧ţ pĕ̇qudá̇ţá֛⁠m yiká̇şĕ̌l֖ẇ ʼáma֥r yĕhwáֽh׃s"],[8,13,"אָסֹ֥ף אֲסִיפֵ֖⁠ם נְאֻם־יְהֹוָ֑ה אֵין֩ עֲנָבִ֨ים בַּ⁠גֶּ֜פֶן וְ⁠אֵ֧ין תְּאֵנִ֣ים בַּ⁠תְּאֵנָ֗ה וְ⁠הֶֽ⁠עָלֶה֙ נָבֵ֔ל וָ⁠אֶתֵּ֥ן לָ⁠הֶ֖ם יַעַבְרֽוּ⁠ם׃","ʼásò֥p ʼàsiypé֖⁠m nĕʼum-yĕhòwá֑h ʼéyn֩ ʻànábi֨ym bȧ⁠gė֜pen wĕ⁠ʼé֧yn ţĕ̇ʼéni֣ym bȧ⁠ţĕ̇ʼéná֗h wĕ⁠heֽ⁠ʻáleh֙ nábé֔l wá⁠ʼeţé֥̇n lá⁠he֖m yaʻabĕrֽẇ⁠m׃"],[8,14,"עַל־מָה֙ אֲנַ֣חְנוּ יֹֽשְׁבִ֔ים הֵֽאָסְפ֗וּ וְ⁠נָב֛וֹא אֶל־עָרֵ֥י הַ⁠מִּבְצָ֖ר וְ⁠נִדְּמָה־שָּׁ֑ם כִּי֩ יְהוָ֨ה אֱלֹהֵ֤י⁠נוּ הֲדִמָּ֨⁠נוּ֙ וַ⁠יַּשְׁקֵ֣⁠נוּ מֵי־רֹ֔אשׁ כִּ֥י חָטָ֖אנוּ לַ⁠יהוָֽה׃","ʻal-máh֙ ʼàna֣ẖĕnẇ yòֽşĕ̌bi֔ym héֽʼásĕp֗ẇ wĕ⁠náb֛wòʼ ʼel-ʻáré֥y ha⁠mi̇bĕẕá֖r wĕ⁠nidĕ̇máh-şá֑̇̌m ki̇y֩ yĕhwá֨h ʼèlòhé֤y⁠nẇ hàdimá̇֨⁠nẇ֙ wa⁠yȧşĕ̌qé֣⁠nẇ méy-rò֔ʼş̌ ki֥̇y ẖátá֖ʼnẇ la⁠yhwáֽh׃"],[8,15,"קַוֵּ֥ה לְ⁠שָׁל֖וֹם וְ⁠אֵ֣ין ט֑וֹב לְ⁠עֵ֥ת מַרְפֵּ֖ה וְ⁠הִנֵּ֥ה בְעָתָֽה׃","qawé֥̇h lĕ⁠şá̌l֖wòm wĕ⁠ʼé֣yn t֑wòb lĕ⁠ʻé֥ţ marĕpé֖̇h wĕ⁠hiné֥̇h bĕʻáţáֽh׃"],[8,16,"מִ⁠דָּ֤ן נִשְׁמַע֙ נַחְרַ֣ת סוּסָ֗י⁠ו מִ⁠קּוֹל֙ מִצְהֲל֣וֹת אַבִּירָ֔י⁠ו רָעֲשָׁ֖ה כָּל־הָ⁠אָ֑רֶץ וַ⁠יָּב֗וֹאוּ וַ⁠יֹּֽאכְלוּ֙ אֶ֣רֶץ וּ⁠מְלוֹאָ֔⁠הּ עִ֖יר וְ⁠יֹ֥שְׁבֵי בָֽ⁠הּ׃ס","mi⁠dá֤̇n nişĕ̌maʻ֙ naẖĕra֣ţ sẇsá֗y⁠w mi⁠q̇wòl֙ miẕĕhàl֣wòţ ʼabi̇yrá֔y⁠w ráʻàşá֖̌h ká̇l-há⁠ʼá֑reẕ wa⁠yá̇b֗wòʼẇ wa⁠yòֽ̇ʼkĕlẇ֙ ʼe֣reẕ ẇ⁠mĕlwòʼá֔⁠ḣ ʻi֖yr wĕ⁠yò֥şĕ̌béy báֽ⁠ḣ׃s"],[8,17,"כִּי֩ הִנְ⁠נִ֨י מְשַׁלֵּ֜חַ בָּ⁠כֶ֗ם נְחָשִׁים֙ צִפְעֹנִ֔ים אֲשֶׁ֥ר אֵין־לָ⁠הֶ֖ם לָ֑חַשׁ וְ⁠נִשְּׁכ֥וּ אֶתְ⁠כֶ֖ם נְאֻם־יְהוָֽה׃ס","ki̇y֩ hinĕ⁠ni֨y mĕşǎlé̇֜ẖa bá̇⁠ke֗m nĕẖáşǐym֙ ẕipĕʻòni֔ym ʼàşě֥r ʼéyn-lá⁠he֖m lá֑ẖaş̌ wĕ⁠nişĕ̇̌k֥ẇ ʼeţĕ⁠ke֖m nĕʼum-yĕhwáֽh׃s"],[8,18,"מַבְלִ֥יגִיתִ֖⁠י עֲלֵ֣י יָג֑וֹן עָלַ֖⁠י לִבִּ֥⁠י דַוָּֽי׃","mabĕli֥ygiyţi֖⁠y ʻàlé֣y yág֑wòn ʻála֖⁠y libi֥̇⁠y dawáֽ̇y׃"],[8,19,"הִנֵּה־ק֞וֹל שַֽׁוְעַ֣ת בַּת־עַמִּ֗⁠י מֵ⁠אֶ֨רֶץ֙ מַרְחַקִּ֔ים הַֽ⁠יהוָה֙ אֵ֣ין בְּ⁠צִיּ֔וֹן אִם־מַלְכָּ֖⁠הּ אֵ֣ין בָּ֑⁠הּ מַדּ֗וּעַ הִכְעִס֛וּ⁠נִי בִּ⁠פְסִלֵי⁠הֶ֖ם בְּ⁠הַבְלֵ֥י נֵכָֽר׃","hiné̇h-q֞wòl şǎֽwĕʻa֣ţ bȧţ-ʻami̇֗⁠y mé⁠ʼe֨reẕ֙ marĕẖaqi̇֔ym haֽ⁠yhwáh֙ ʼé֣yn bĕ̇⁠ẕiẏ֔wòn ʼim-malĕká֖̇⁠ḣ ʼé֣yn bá֑̇⁠ḣ maḋ֗ẇʻa hikĕʻis֛ẇ⁠niy bi̇⁠pĕsiléy⁠he֖m bĕ̇⁠habĕlé֥y nékáֽr׃"],[8,20,"עָבַ֥ר קָצִ֖יר כָּ֣לָה קָ֑יִץ וַ⁠אֲנַ֖חְנוּ ל֥וֹא נוֹשָֽׁעְנוּ׃","ʻába֥r qáẕi֖yr ká֣̇láh qá֑yiẕ wa⁠ʼàna֖ẖĕnẇ l֥wòʼ nwòşáֽ̌ʻĕnẇ׃"],[8,21,"עַל־שֶׁ֥בֶר בַּת־עַמִּ֖⁠י הָשְׁבָּ֑רְתִּי קָדַ֕רְתִּי שַׁמָּ֖ה הֶחֱזִקָֽתְ⁠נִי׃","ʻal-şě֥ber bȧţ-ʻami֖̇⁠y háşĕ̌bá֑̇rĕţi̇y qáda֕rĕţi̇y şǎmá֖̇h heẖèziqáֽţĕ⁠niy׃"],[8,22,"הַ⁠צֳרִי֙ אֵ֣ין בְּ⁠גִלְעָ֔ד אִם־רֹפֵ֖א אֵ֣ין שָׁ֑ם כִּ֗י מַדּ֨וּעַ֙ לֹ֣א עָֽלְתָ֔ה אֲרֻכַ֖ת בַּת־עַמִּֽ⁠י׃","ha⁠ẕoriy֙ ʼé֣yn bĕ̇⁠gilĕʻá֔d ʼim-ròpé֖ʼ ʼé֣yn şá֑̌m ki̇֗y maḋ֨ẇʻa֙ lò֣ʼ ʻáֽlĕţá֔h ʼàruka֖ţ bȧţ-ʻamiֽ̇⁠y׃"],[9,1,"מִֽי־יִתֵּ֤ן רֹאשִׁ⁠י֙ מַ֔יִם וְ⁠עֵינִ֖⁠י מְק֣וֹר דִּמְעָ֑ה וְ⁠אֶבְכֶּה֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה אֵ֖ת חַֽלְלֵ֥י בַת־עַמִּֽ⁠י׃","miֽy-yiţé֤̇n ròʼşǐ⁠y֙ ma֔yim wĕ⁠ʻéyni֖⁠y mĕq֣wòr di̇mĕʻá֑h wĕ⁠ʼebĕkėh֙ ywòmá֣m wá⁠la֔yĕláh ʼé֖ţ ẖaֽlĕlé֥y baţ-ʻamiֽ̇⁠y׃"],[9,2,"מִֽי־יִתְּנֵ֣⁠נִי בַ⁠מִּדְבָּ֗ר מְלוֹן֙ אֹֽרְחִ֔ים וְ⁠אֶֽעֶזְבָה֙ אֶת־עַמִּ֔⁠י וְ⁠אֵלְכָ֖ה מֵֽ⁠אִתָּ֑⁠ם כִּ֤י כֻלָּ⁠ם֙ מְנָ֣אֲפִ֔ים עֲצֶ֖רֶת בֹּגְדִֽים׃","miֽy-yiţĕ̇né֣⁠niy ba⁠mi̇dĕbá̇֗r mĕlwòn֙ ʼòֽrĕẖi֔ym wĕ⁠ʼeֽʻezĕbáh֙ ʼeţ-ʻami̇֔⁠y wĕ⁠ʼélĕká֖h méֽ⁠ʼiţá֑̇⁠m ki֤̇y kulá̇⁠m֙ mĕná֣ʼàpi֔ym ʻàẕe֖reţ bò̇gĕdiֽym׃"],[9,3,"וַֽ⁠יַּדְרְכ֤וּ אֶת־לְשׁוֹנָ⁠ם֙ קַשְׁתָּ֣⁠ם שֶׁ֔קֶר וְ⁠לֹ֥א לֶ⁠אֱמוּנָ֖ה גָּבְר֣וּ בָ⁠אָ֑רֶץ כִּי֩ מֵ⁠רָעָ֨ה אֶל־רָעָ֧ה ׀ יָצָ֛אוּ וְ⁠אֹתִ֥⁠י לֹֽא־יָדָ֖עוּ נְאֻם־יְהוָֽה׃ס","waֽ⁠yȧdĕrĕk֤ẇ ʼeţ-lĕş̌wòná⁠m֙ qaşĕ̌ţá֣̇⁠m şě֔qer wĕ⁠lò֥ʼ le⁠ʼèmẇná֖h gá̇bĕr֣ẇ bá⁠ʼá֑reẕ ki̇y֩ mé⁠ráʻá֨h ʼel-ráʻá֧h ׀ yáẕá֛ʼẇ wĕ⁠ʼòţi֥⁠y lòֽʼ-yádá֖ʻẇ nĕʼum-yĕhwáֽh׃s"],[9,4,"אִ֤ישׁ מֵ⁠רֵעֵ֨⁠הוּ֙ הִשָּׁמֵ֔רוּ וְ⁠עַל־כָּל־אָ֖ח אַל־תִּבְטָ֑חוּ כִּ֤י כָל־אָח֙ עָק֣וֹב יַעְקֹ֔ב וְ⁠כָל־רֵ֖עַ רָכִ֥יל יַהֲלֹֽךְ׃","ʼi֤yş̌ mé⁠réʻé֨⁠hẇ֙ hişá̇̌mé֔rẇ wĕ⁠ʻal-ká̇l-ʼá֖ẖ ʼal-ţi̇bĕtá֑ẖẇ ki֤̇y kál-ʼáẖ֙ ʻáq֣wòb yaʻĕqò֔b wĕ⁠kál-ré֖ʻa ráki֥yl yahàlòֽkĕ׃"],[9,5,"וְ⁠אִ֤ישׁ בְּ⁠רֵעֵ֨⁠הוּ֙ יְהָתֵ֔לּוּ וֶ⁠אֱמֶ֖ת לֹ֣א יְדַבֵּ֑רוּ לִמְּד֧וּ לְשׁוֹנָ֛⁠ם דַּבֶּר־שֶׁ֖קֶר הַעֲוֵ֥ה נִלְאֽוּ׃","wĕ⁠ʼi֤yş̌ bĕ̇⁠réʻé֨⁠hẇ֙ yĕháţé֔l̇ẇ we⁠ʼème֖ţ lò֣ʼ yĕdabé֑̇rẇ limĕ̇d֧ẇ lĕş̌wòná֛⁠m dȧbėr-şě֖qer haʻàwé֥h nilĕʼֽẇ׃"],[9,6,"שִׁבְתְּ⁠ךָ֖ בְּ⁠ת֣וֹךְ מִרְמָ֑ה בְּ⁠מִרְמָ֛ה מֵאֲנ֥וּ דַֽעַת־אוֹתִ֖⁠י נְאֻם־יְהוָֽה׃ס","şǐbĕţĕ̇⁠ká֖ bĕ̇⁠ţ֣wòkĕ mirĕmá֑h bĕ̇⁠mirĕmá֛h méʼàn֥ẇ daֽʻaţ-ʼwòţi֖⁠y nĕʼum-yĕhwáֽh׃s"],[9,7,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִ֥י צוֹרְפָ֖⁠ם וּ⁠בְחַנְתִּ֑י⁠ם כִּֽי־אֵ֣יךְ אֶעֱשֶׂ֔ה מִ⁠פְּנֵ֖י בַּת־עַמִּֽ⁠י׃","lá⁠ké֗n kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠ni֥y ẕwòrĕpá֖⁠m ẇ⁠bĕẖanĕţi֑̇y⁠m kiֽ̇y-ʼé֣ykĕ ʼeʻèşê֔h mi⁠pĕ̇né֖y bȧţ-ʻamiֽ̇⁠y׃"],[9,8,"חֵ֥ץ שוחט לְשׁוֹנָ֖⁠ם מִרְמָ֣ה דִבֵּ֑ר בְּ⁠פִ֗י⁠ו שָׁל֤וֹם אֶת־רֵעֵ֨⁠הוּ֙ יְדַבֵּ֔ר וּ⁠בְ⁠קִרְבּ֖⁠וֹ יָשִׂ֥ים אָרְבּֽ⁠וֹ׃","ẖé֥ẕ şwẖt lĕş̌wòná֖⁠m mirĕmá֣h dibé֑̇r bĕ̇⁠pi֗y⁠w şá̌l֤wòm ʼeţ-réʻé֨⁠hẇ֙ yĕdabé̇֔r ẇ⁠bĕ⁠qirĕḃ֖⁠wò yáşî֥ym ʼárĕḃֽ⁠wò׃"],[9,9,"הַ⁠עַל־אֵ֥לֶּה לֹֽא־אֶפְקָד־בָּ֖⁠ם נְאֻם־יְהוָ֑ה אִ֚ם בְּ⁠ג֣וֹי אֲשֶׁר־כָּ⁠זֶ֔ה לֹ֥א תִתְנַקֵּ֖ם נַפְשִֽׁ⁠י׃ס","ha⁠ʻal-ʼé֥lėh lòֽʼ-ʼepĕqád-bá֖̇⁠m nĕʼum-yĕhwá֑h ʼi֚m bĕ̇⁠g֣wòy ʼàşěr-ká̇⁠ze֔h lò֥ʼ ţiţĕnaqé֖̇m napĕşǐֽ⁠y׃s"],[9,10,"עַל־הֶ֨⁠הָרִ֜ים אֶשָּׂ֧א בְכִ֣י וָ⁠נֶ֗הִי וְ⁠עַל־נְא֤וֹת מִדְבָּר֙ קִינָ֔ה כִּ֤י נִצְּתוּ֙ מִ⁠בְּלִי־אִ֣ישׁ עֹבֵ֔ר וְ⁠לֹ֥א שָׁמְע֖וּ ק֣וֹל מִקְנֶ֑ה מֵ⁠ע֤וֹף הַ⁠שָּׁמַ֨יִם֙ וְ⁠עַד־בְּהֵמָ֔ה נָדְד֖וּ הָלָֽכוּ׃","ʻal-he֨⁠hári֜ym ʼeşá֧̇̂ʼ bĕki֣y wá⁠ne֗hiy wĕ⁠ʻal-nĕʼ֤wòţ midĕbá̇r֙ qiyná֔h ki֤̇y niẕĕ̇ţẇ֙ mi⁠bĕ̇liy-ʼi֣yş̌ ʻòbé֔r wĕ⁠lò֥ʼ şá̌mĕʻ֖ẇ q֣wòl miqĕne֑h mé⁠ʻ֤wòp ha⁠şá̇̌ma֨yim֙ wĕ⁠ʻad-bĕ̇hémá֔h nádĕd֖ẇ háláֽkẇ׃"],[9,11,"וְ⁠נָתַתִּ֧י אֶת־יְרוּשָׁלִַ֛ם לְ⁠גַלִּ֖ים מְע֣וֹן תַּנִּ֑ים וְ⁠אֶת־עָרֵ֧י יְהוּדָ֛ה אֶתֵּ֥ן שְׁמָמָ֖ה מִ⁠בְּלִ֖י יוֹשֵֽׁב׃ס","wĕ⁠náţaţi֧̇y ʼeţ-yĕrẇşá̌lia֛m lĕ⁠gali֖̇ym mĕʻ֣wòn ţȧni֑̇ym wĕ⁠ʼeţ-ʻáré֧y yĕhẇdá֛h ʼeţé֥̇n şĕ̌mámá֖h mi⁠bĕ̇li֖y ywòşéֽ̌b׃s"],[9,12,"מִֽי־הָ⁠אִ֤ישׁ הֶֽ⁠חָכָם֙ וְ⁠יָבֵ֣ן אֶת־זֹ֔את וַ⁠אֲשֶׁ֨ר דִּבֶּ֧ר פִּֽי־יְהוָ֛ה אֵלָ֖י⁠ו וְ⁠יַגִּדָ֑⁠הּ עַל־מָה֙ אָבְדָ֣ה הָ⁠אָ֔רֶץ נִצְּתָ֥ה כַ⁠מִּדְבָּ֖ר מִ⁠בְּלִ֖י עֹבֵֽר׃ס","miֽy-há⁠ʼi֤yş̌ heֽ⁠ẖákám֙ wĕ⁠yábé֣n ʼeţ-zò֔ʼţ wa⁠ʼàşě֨r di̇bė֧r piֽ̇y-yĕhwá֛h ʼélá֖y⁠w wĕ⁠yagi̇dá֑⁠ḣ ʻal-máh֙ ʼábĕdá֣h há⁠ʼá֔reẕ niẕĕ̇ţá֥h ka⁠mi̇dĕbá֖̇r mi⁠bĕ̇li֖y ʻòbéֽr׃s"],[9,13,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה עַל־עָזְבָ⁠ם֙ אֶת־תּ֣וֹרָתִ֔⁠י אֲשֶׁ֥ר נָתַ֖תִּי לִ⁠פְנֵי⁠הֶ֑ם וְ⁠לֹא־שָׁמְע֥וּ בְ⁠קוֹלִ֖⁠י וְ⁠לֹא־הָ֥לְכוּ בָֽ⁠הּ׃","wa⁠yò֣̇ʼmer yĕhwá֔h ʻal-ʻázĕbá⁠m֙ ʼeţ-ţ֣̇wòráţi֔⁠y ʼàşě֥r náţa֖ţi̇y li⁠pĕnéy⁠he֑m wĕ⁠lòʼ-şá̌mĕʻ֥ẇ bĕ⁠qwòli֖⁠y wĕ⁠lòʼ-há֥lĕkẇ báֽ⁠ḣ׃"],[9,14,"וַ⁠יֵּ֣לְכ֔וּ אַחֲרֵ֖י שְׁרִר֣וּת לִבָּ֑⁠ם וְ⁠אַחֲרֵי֙ הַ⁠בְּעָלִ֔ים אֲשֶׁ֥ר לִמְּד֖וּ⁠ם אֲבוֹתָֽ⁠ם׃ס","wa⁠yé֣̇lĕk֔ẇ ʼaẖàré֖y şĕ̌rir֣ẇţ libá֑̇⁠m wĕ⁠ʼaẖàréy֙ ha⁠bĕ̇ʻáli֔ym ʼàşě֥r limĕ̇d֖ẇ⁠m ʼàbwòţáֽ⁠m׃s"],[9,15,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֧י מַאֲכִילָ֛⁠ם אֶת־הָ⁠עָ֥ם הַ⁠זֶּ֖ה לַֽעֲנָ֑ה וְ⁠הִשְׁקִיתִ֖י⁠ם מֵי־רֹֽאשׁ׃","lá⁠ké֗n kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֧y maʼàkiylá֛⁠m ʼeţ-há⁠ʻá֥m ha⁠zė֖h laֽʻàná֑h wĕ⁠hişĕ̌qiyţi֖y⁠m méy-ròֽʼş̌׃"],[9,16,"וַ⁠הֲפִֽצוֹתִי⁠ם֙ בַּ⁠גּוֹיִ֔ם אֲשֶׁר֙ לֹ֣א יָֽדְע֔וּ הֵ֖מָּה וַֽ⁠אֲבוֹתָ֑⁠ם וְ⁠שִׁלַּחְתִּ֤י אַֽחֲרֵי⁠הֶם֙ אֶת־הַ⁠חֶ֔רֶב עַ֥ד כַּלּוֹתִ֖⁠י אוֹתָֽ⁠ם׃פ","wa⁠hàpiֽẕwòţiy⁠m֙ bȧ⁠ġwòyi֔m ʼàşěr֙ lò֣ʼ yáֽdĕʻ֔ẇ hé֖má̇h waֽ⁠ʼàbwòţá֑⁠m wĕ⁠şǐlȧẖĕţi֤̇y ʼaֽẖàréy⁠hem֙ ʼeţ-ha⁠ẖe֔reb ʻa֥d kȧl̇wòţi֖⁠y ʼwòţáֽ⁠m׃p"],[9,17,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִתְבּֽוֹנְנ֛וּ וְ⁠קִרְא֥וּ לַ⁠מְקוֹנְנ֖וֹת וּ⁠תְבוֹאֶ֑ינָה וְ⁠אֶל־הַ⁠חֲכָמ֥וֹת שִׁלְח֖וּ וְ⁠תָבֽוֹאנָה׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hiţĕḃֽwònĕn֛ẇ wĕ⁠qirĕʼ֥ẇ la⁠mĕqwònĕn֖wòţ ẇ⁠ţĕbwòʼe֑ynáh wĕ⁠ʼel-ha⁠ẖàkám֥wòţ şǐlĕẖ֖ẇ wĕ⁠ţábֽwòʼnáh׃"],[9,18,"וּ⁠תְמַהֵ֕רְנָה וְ⁠תִשֶּׂ֥נָה עָלֵ֖י⁠נוּ נֶ֑הִי וְ⁠תֵרַ֤דְנָה עֵינֵ֨י⁠נוּ֙ דִּמְעָ֔ה וְ⁠עַפְעַפֵּ֖י⁠נוּ יִזְּלוּ־מָֽיִם׃","ẇ⁠ţĕmahé֕rĕnáh wĕ⁠ţişė֥̂náh ʻálé֖y⁠nẇ ne֑hiy wĕ⁠ţéra֤dĕnáh ʻéyné֨y⁠nẇ֙ di̇mĕʻá֔h wĕ⁠ʻapĕʻapé֖̇y⁠nẇ yizĕ̇lẇ-máֽyim׃"],[9,19,"כִּ֣י ק֥וֹל נְהִ֛י נִשְׁמַ֥ע מִ⁠צִּיּ֖וֹן אֵ֣יךְ שֻׁדָּ֑דְנוּ בֹּ֤שְׁנֽוּ מְאֹד֙ כִּֽי־עָזַ֣בְנוּ אָ֔רֶץ כִּ֥י הִשְׁלִ֖יכוּ מִשְׁכְּנוֹתֵֽי⁠נוּ׃ס","ki֣̇y q֥wòl nĕhi֛y nişĕ̌ma֥ʻ mi⁠ẕi̇ẏ֖wòn ʼé֣ykĕ şǔdá֑̇dĕnẇ bò֤̇şĕ̌nֽẇ mĕʼòd֙ kiֽ̇y-ʻáza֣bĕnẇ ʼá֔reẕ ki֥̇y hişĕ̌li֖ykẇ mişĕ̌kĕ̇nwòţéֽy⁠nẇ׃s"],[9,20,"כִּֽי־שְׁמַ֤עְנָה נָשִׁים֙ דְּבַר־יְהוָ֔ה וְ⁠תִקַּ֥ח אָזְנְ⁠כֶ֖ם דְּבַר־פִּ֑י⁠ו וְ⁠לַמֵּ֤דְנָה בְנֽוֹתֵי⁠כֶם֙ נֶ֔הִי וְ⁠אִשָּׁ֥ה רְעוּתָ֖⁠הּ קִינָֽה׃","kiֽ̇y-şĕ̌ma֤ʻĕnáh náşǐym֙ dĕ̇bar-yĕhwá֔h wĕ⁠ţiqȧ֥ẖ ʼázĕnĕ⁠ke֖m dĕ̇bar-pi֑̇y⁠w wĕ⁠lamé֤̇dĕnáh bĕnֽwòţéy⁠kem֙ ne֔hiy wĕ⁠ʼişá֥̇̌h rĕʻẇţá֖⁠ḣ qiynáֽh׃"],[9,21,"כִּֽי־עָ֤לָה מָ֨וֶת֙ בְּ⁠חַלּוֹנֵ֔י⁠נוּ בָּ֖א בְּ⁠אַרְמְנוֹתֵ֑י⁠נוּ לְ⁠הַכְרִ֤ית עוֹלָל֙ מִ⁠ח֔וּץ בַּחוּרִ֖ים מֵ⁠רְחֹבֽוֹת׃","kiֽ̇y-ʻá֤láh má֨weţ֙ bĕ̇⁠ẖal̇wòné֔y⁠nẇ bá֖̇ʼ bĕ̇⁠ʼarĕmĕnwòţé֑y⁠nẇ lĕ⁠hakĕri֤yţ ʻwòlál֙ mi⁠ẖ֔ẇẕ bȧẖẇri֖ym mé⁠rĕẖòbֽwòţ׃"],[9,22,"דַּבֵּ֗ר כֹּ֚ה נְאֻם־יְהוָ֔ה וְ⁠נָֽפְלָה֙ נִבְלַ֣ת הָֽ⁠אָדָ֔ם כְּ⁠דֹ֖מֶן עַל־פְּנֵ֣י הַ⁠שָּׂדֶ֑ה וּ⁠כְ⁠עָמִ֛יר מֵ⁠אַחֲרֵ֥י הַ⁠קֹּצֵ֖ר וְ⁠אֵ֥ין מְאַסֵּֽף׃ס","dȧbé̇֗r kò֚̇h nĕʼum-yĕhwá֔h wĕ⁠náֽpĕláh֙ nibĕla֣ţ háֽ⁠ʼádá֔m kĕ̇⁠dò֖men ʻal-pĕ̇né֣y ha⁠şá̇̂de֑h ẇ⁠kĕ⁠ʻámi֛yr mé⁠ʼaẖàré֥y ha⁠qò̇ẕé֖r wĕ⁠ʼé֥yn mĕʼaséֽ̇p׃s"],[9,23,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אַל־יִתְהַלֵּ֤ל חָכָם֙ בְּ⁠חָכְמָת֔⁠וֹ וְ⁠אַל־יִתְהַלֵּ֥ל הַ⁠גִּבּ֖וֹר בִּ⁠גְבֽוּרָת֑⁠וֹ אַל־יִתְהַלֵּ֥ל עָשִׁ֖יר בְּ⁠עָשְׁרֽ⁠וֹ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼal-yiţĕhalé֤̇l ẖákám֙ bĕ̇⁠ẖákĕmáţ֔⁠wò wĕ⁠ʼal-yiţĕhalé֥̇l ha⁠gi̇ḃ֖wòr bi̇⁠gĕbֽẇráţ֑⁠wò ʼal-yiţĕhalé֥̇l ʻáşǐ֖yr bĕ̇⁠ʻáşĕ̌rֽ⁠wò׃"],[9,24,"כִּ֣י אִם־בְּ⁠זֹ֞את יִתְהַלֵּ֣ל הַ⁠מִּתְהַלֵּ֗ל הַשְׂכֵּל֮ וְ⁠יָדֹ֣עַ אוֹתִ⁠י֒ כִּ֚י אֲנִ֣י יְהוָ֔ה עֹ֥שֶׂה חֶ֛סֶד מִשְׁפָּ֥ט וּ⁠צְדָקָ֖ה בָּ⁠אָ֑רֶץ כִּֽי־בְ⁠אֵ֥לֶּה חָפַ֖צְתִּי נְאֻם־יְהוָֽה׃ס","ki֣̇y ʼim-bĕ̇⁠zò֞ʼţ yiţĕhalé֣̇l ha⁠mi̇ţĕhalé̇֗l haşĕ̂ké̇l֮ wĕ⁠yádò֣ʻa ʼwòţi⁠y֒ ki֚̇y ʼàni֣y yĕhwá֔h ʻò֥şêh ẖe֛sed mişĕ̌pá֥̇t ẇ⁠ẕĕdáqá֖h bá̇⁠ʼá֑reẕ kiֽ̇y-bĕ⁠ʼé֥lėh ẖápa֖ẕĕţi̇y nĕʼum-yĕhwáֽh׃s"],[9,25,"הִנֵּ֛ה יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וּ⁠פָ֣קַדְתִּ֔י עַל־כָּל־מ֖וּל בְּ⁠עָרְלָֽה׃","hiné֛̇h yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h ẇ⁠pá֣qadĕţi̇֔y ʻal-ká̇l-m֖ẇl bĕ̇⁠ʻárĕláֽh׃"],[9,26,"עַל־מִצְרַ֣יִם וְ⁠עַל־יְהוּדָ֗ה וְ⁠עַל־אֱד֞וֹם וְ⁠עַל־בְּנֵ֤י עַמּוֹן֙ וְ⁠עַל־מוֹאָ֔ב וְ⁠עַל֙ כָּל־קְצוּצֵ֣י פֵאָ֔ה הַ⁠יֹּשְׁבִ֖ים בַּ⁠מִּדְבָּ֑ר כִּ֤י כָל־הַ⁠גּוֹיִם֙ עֲרֵלִ֔ים וְ⁠כָל־בֵּ֥ית יִשְׂרָאֵ֖ל עַרְלֵי־לֵֽב׃ס","ʻal-miẕĕra֣yim wĕ⁠ʻal-yĕhẇdá֗h wĕ⁠ʻal-ʼèd֞wòm wĕ⁠ʻal-bĕ̇né֤y ʻaṁwòn֙ wĕ⁠ʻal-mwòʼá֔b wĕ⁠ʻal֙ ká̇l-qĕẕẇẕé֣y péʼá֔h ha⁠yò̇şĕ̌bi֖ym bȧ⁠mi̇dĕbá֑̇r ki֤̇y kál-ha⁠ġwòyim֙ ʻàréli֔ym wĕ⁠kál-bé֥̇yţ yişĕ̂ráʼé֖l ʻarĕléy-léֽb׃s"],[10,1,"שִׁמְע֣וּ אֶת־הַ⁠דָּבָ֗ר אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה עֲלֵי⁠כֶ֖ם בֵּ֥ית יִשְׂרָאֵֽל׃","şǐmĕʻ֣ẇ ʼeţ-ha⁠dá̇bá֗r ʼàşě֨r di̇bė֧r yĕhwá֛h ʻàléy⁠ke֖m bé֥̇yţ yişĕ̂ráʼéֽl׃"],[10,2,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אֶל־דֶּ֤רֶךְ הַ⁠גּוֹיִם֙ אַל־תִּלְמָ֔דוּ וּ⁠מֵ⁠אֹת֥וֹת הַ⁠שָּׁמַ֖יִם אַל־תֵּחָ֑תּוּ כִּֽי־יֵחַ֥תּוּ הַ⁠גּוֹיִ֖ם מֵ⁠הֵֽמָּה׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼel-dė֤rekĕ ha⁠ġwòyim֙ ʼal-ţi̇lĕmá֔dẇ ẇ⁠mé⁠ʼòţ֥wòţ ha⁠şá̇̌ma֖yim ʼal-ţé̇ẖá֑ţ̇ẇ kiֽ̇y-yéẖa֥ţ̇ẇ ha⁠ġwòyi֖m mé⁠héֽmá̇h׃"],[10,3,"כִּֽי־חֻקּ֥וֹת הָֽ⁠עַמִּ֖ים הֶ֣בֶל ה֑וּא כִּֽי־עֵץ֙ מִ⁠יַּ֣עַר כְּרָת֔⁠וֹ מַעֲשֵׂ֥ה יְדֵ֥י־חָרָ֖שׁ בַּֽ⁠מַּעֲצָֽד׃","kiֽ̇y-ẖuq֥̇wòţ háֽ⁠ʻami֖̇ym he֣bel h֑ẇʼ kiֽ̇y-ʻéẕ֙ mi⁠yȧ֣ʻar kĕ̇ráţ֔⁠wò maʻàşé֥̂h yĕdé֥y-ẖárá֖ş̌ bȧֽ⁠mȧʻàẕáֽd׃"],[10,4,"בְּ⁠כֶ֥סֶף וּ⁠בְ⁠זָהָ֖ב יְיַפֵּ֑⁠הוּ בְּ⁠מַסְמְר֧וֹת וּ⁠בְ⁠מַקָּב֛וֹת יְחַזְּק֖וּ⁠ם וְ⁠ל֥וֹא יָפִֽיק׃","bĕ̇⁠ke֥sep ẇ⁠bĕ⁠záhá֖b yĕyapé֑̇⁠hẇ bĕ̇⁠masĕmĕr֧wòţ ẇ⁠bĕ⁠maqá̇b֛wòţ yĕẖazĕ̇q֖ẇ⁠m wĕ⁠l֥wòʼ yápiֽyq׃"],[10,5,"כְּ⁠תֹ֨מֶר מִקְשָׁ֥ה הֵ֨מָּה֙ וְ⁠לֹ֣א יְדַבֵּ֔רוּ נָשׂ֥וֹא יִנָּשׂ֖וּא כִּ֣י לֹ֣א יִצְעָ֑דוּ אַל־תִּֽירְא֤וּ מֵ⁠הֶם֙ כִּי־לֹ֣א יָרֵ֔עוּ וְ⁠גַם־הֵיטֵ֖יב אֵ֥ין אוֹתָֽ⁠ם׃ס","kĕ̇⁠ţò֨mer miqĕşá֥̌h hé֨má̇h֙ wĕ⁠lò֣ʼ yĕdabé̇֔rẇ náş֥̂wòʼ yiná̇ş֖̂ẇʼ ki֣̇y lò֣ʼ yiẕĕʻá֑dẇ ʼal-ţiֽ̇yrĕʼ֤ẇ mé⁠hem֙ ki̇y-lò֣ʼ yáré֔ʻẇ wĕ⁠gam-héyté֖yb ʼé֥yn ʼwòţáֽ⁠m׃s"],[10,6,"מֵ⁠אֵ֥ין כָּמ֖וֹ⁠ךָ יְהוָ֑ה גָּד֥וֹל אַתָּ֛ה וְ⁠גָד֥וֹל שִׁמְ⁠ךָ֖ בִּ⁠גְבוּרָֽה׃","mé⁠ʼé֥yn ká̇m֖wò⁠ká yĕhwá֑h gá̇d֥wòl ʼaţá֛̇h wĕ⁠gád֥wòl şǐmĕ⁠ká֖ bi̇⁠gĕbẇráֽh׃"],[10,7,"מִ֣י לֹ֤א יִֽרָאֲ⁠ךָ֙ מֶ֣לֶךְ הַ⁠גּוֹיִ֔ם כִּ֥י לְ⁠ךָ֖ יָאָ֑תָה כִּ֣י בְ⁠כָל־חַכְמֵ֧י הַ⁠גּוֹיִ֛ם וּ⁠בְ⁠כָל־מַלְכוּתָ֖⁠ם מֵ⁠אֵ֥ין כָּמֽוֹ⁠ךָ׃","mi֣y lò֤ʼ yiֽráʼà⁠ká֙ me֣lekĕ ha⁠ġwòyi֔m ki֥̇y lĕ⁠ká֖ yáʼá֑ţáh ki֣̇y bĕ⁠kál-ẖakĕmé֧y ha⁠ġwòyi֛m ẇ⁠bĕ⁠kál-malĕkẇţá֖⁠m mé⁠ʼé֥yn ká̇mֽwò⁠ká׃"],[10,8,"וּ⁠בְ⁠אַחַ֖ת יִבְעֲר֣וּ וְ⁠יִכְסָ֑לוּ מוּסַ֥ר הֲבָלִ֖ים עֵ֥ץ הֽוּא׃","ẇ⁠bĕ⁠ʼaẖa֖ţ yibĕʻàr֣ẇ wĕ⁠yikĕsá֑lẇ mẇsa֥r hàbáli֖ym ʻé֥ẕ hֽẇʼ׃"],[10,9,"כֶּ֣סֶף מְרֻקָּ֞ע מִ⁠תַּרְשִׁ֣ישׁ יוּבָ֗א וְ⁠זָהָב֙ מֵֽ⁠אוּפָ֔ז מַעֲשֵׂ֥ה חָרָ֖שׁ וִ⁠ידֵ֣י צוֹרֵ֑ף תְּכֵ֤לֶת וְ⁠אַרְגָּמָן֙ לְבוּשָׁ֔⁠ם מַעֲשֵׂ֥ה חֲכָמִ֖ים כֻּלָּֽ⁠ם׃","kė֣sep mĕruqá̇֞ʻ mi⁠ţȧrĕşǐ֣yş̌ yẇbá֗ʼ wĕ⁠záháb֙ méֽ⁠ʼẇpá֔z maʻàşé֥̂h ẖárá֖ş̌ wi⁠ydé֣y ẕwòré֑p ţĕ̇ké֤leţ wĕ⁠ʼarĕgá̇mán֙ lĕbẇşá̌֔⁠m maʻàşé֥̂h ẖàkámi֖ym ku̇láֽ̇⁠m׃"],[10,10,"וַֽ⁠יהוָ֤ה אֱלֹהִים֙ אֱמֶ֔ת הֽוּא־אֱלֹהִ֥ים חַיִּ֖ים וּ⁠מֶ֣לֶךְ עוֹלָ֑ם מִ⁠קִּצְפּ⁠וֹ֙ תִּרְעַ֣שׁ הָ⁠אָ֔רֶץ וְ⁠לֹֽא־יָכִ֥לוּ גוֹיִ֖ם זַעְמֽ⁠וֹ׃ס","waֽ⁠yhwá֤h ʼèlòhiym֙ ʼème֔ţ hֽẇʼ-ʼèlòhi֥ym ẖayi֖̇ym ẇ⁠me֣lekĕ ʻwòlá֑m mi⁠qi̇ẕĕṗ⁠wò֙ ţi̇rĕʻa֣ş̌ há⁠ʼá֔reẕ wĕ⁠lòֽʼ-yáki֥lẇ gwòyi֖m zaʻĕmֽ⁠wò׃s"],[10,11,"כִּ⁠דְנָה֙ תֵּאמְר֣וּן לְ⁠ה֔וֹם אֱלָ֣הַיָּ֔⁠א דִּֽי־שְׁמַיָּ֥⁠א וְ⁠אַרְקָ֖⁠א לָ֣א עֲבַ֑דוּ יֵאבַ֧דוּ מֵֽ⁠אַרְעָ֛⁠א וּ⁠מִן־תְּח֥וֹת שְׁמַיָּ֖⁠א אֵֽלֶּה׃ס","ki̇⁠dĕnáh֙ ţé̇ʼmĕr֣ẇn lĕ⁠h֔wòm ʼèlá֣hayá̇֔⁠ʼ diֽ̇y-şĕ̌mayá֥̇⁠ʼ wĕ⁠ʼarĕqá֖⁠ʼ lá֣ʼ ʻàba֑dẇ yéʼba֧dẇ méֽ⁠ʼarĕʻá֛⁠ʼ ẇ⁠min-ţĕ̇ẖ֥wòţ şĕ̌mayá֖̇⁠ʼ ʼéֽlėh׃s"],[10,12,"עֹשֵׂ֥ה אֶ֨רֶץ֙ בְּ⁠כֹח֔⁠וֹ מֵכִ֥ין תֵּבֵ֖ל בְּ⁠חָכְמָת֑⁠וֹ וּ⁠בִ⁠תְבוּנָת֖⁠וֹ נָטָ֥ה שָׁמָֽיִם׃","ʻòşé֥̂h ʼe֨reẕ֙ bĕ̇⁠kòẖ֔⁠wò méki֥yn ţé̇bé֖l bĕ̇⁠ẖákĕmáţ֑⁠wò ẇ⁠bi⁠ţĕbẇnáţ֖⁠wò nátá֥h şá̌máֽyim׃"],[10,13,"לְ⁠ק֨וֹל תִּתּ֜⁠וֹ הֲמ֥וֹן מַ֨יִם֙ בַּ⁠שָּׁמַ֔יִם וַ⁠יַּעֲלֶ֥ה נְשִׂאִ֖ים מִ⁠קְצֵ֣ה ארץ בְּרָקִ֤ים לַ⁠מָּטָר֙ עָשָׂ֔ה וַ⁠יּ֥וֹצֵא ר֖וּחַ מֵ⁠אֹצְרֹתָֽי⁠ו׃","lĕ⁠q֨wòl ţi̇ţ̇֜⁠wò hàm֥wòn ma֨yim֙ bȧ⁠şá̇̌ma֔yim wa⁠yȧʻàle֥h nĕşîʼi֖ym mi⁠qĕẕé֣h ʼrẕ bĕ̇ráqi֤ym la⁠má̇tár֙ ʻáşá̂֔h wa⁠ẏ֥wòẕéʼ r֖ẇẖa mé⁠ʼòẕĕròţáֽy⁠w׃"],[10,14,"נִבְעַ֤ר כָּל־אָדָם֙ מִ⁠דַּ֔עַת הֹבִ֥ישׁ כָּל־צוֹרֵ֖ף מִ⁠פָּ֑סֶל כִּ֛י שֶׁ֥קֶר נִסְכּ֖⁠וֹ וְ⁠לֹא־ר֥וּחַ בָּֽ⁠ם׃","nibĕʻa֤r ká̇l-ʼádám֙ mi⁠dȧ֔ʻaţ hòbi֥yş̌ ká̇l-ẕwòré֖p mi⁠pá֑̇sel ki֛̇y şě֥qer nisĕk֖̇⁠wò wĕ⁠lòʼ-r֥ẇẖa báֽ̇⁠m׃"],[10,15,"הֶ֣בֶל הֵ֔מָּה מַעֲשֵׂ֖ה תַּעְתֻּעִ֑ים בְּ⁠עֵ֥ת פְּקֻדָּתָ֖⁠ם יֹאבֵֽדוּ׃","he֣bel hé֔má̇h maʻàşé֖̂h ţȧʻĕţu̇ʻi֑ym bĕ̇⁠ʻé֥ţ pĕ̇qudá̇ţá֖⁠m yòʼbéֽdẇ׃"],[10,16,"לֹֽא־כְ⁠אֵ֜לֶּה חֵ֣לֶק יַעֲקֹ֗ב כִּֽי־יוֹצֵ֤ר הַ⁠כֹּל֙ ה֔וּא וְ⁠יִ֨שְׂרָאֵ֔ל שֵׁ֖בֶט נַֽחֲלָת֑⁠וֹ יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃ס","lòֽʼ-kĕ⁠ʼé֜lėh ẖé֣leq yaʻàqò֗b kiֽ̇y-ywòẕé֤r ha⁠kò̇l֙ h֔ẇʼ wĕ⁠yi֨şĕ̂ráʼé֔l şé֖̌bet naֽẖàláţ֑⁠wò yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃s"],[10,17,"אִסְפִּ֥י מֵ⁠אֶ֖רֶץ כִּנְעָתֵ֑⁠ךְ ישבתי בַּ⁠מָּצֽוֹר׃ס","ʼisĕpi֥̇y mé⁠ʼe֖reẕ ki̇nĕʻáţé֑⁠kĕ yşbţy bȧ⁠má̇ẕֽwòr׃s"],[10,18,"כִּֽי־כֹה֙ אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֥י קוֹלֵ֛עַ אֶת־יוֹשְׁבֵ֥י הָ⁠אָ֖רֶץ בַּ⁠פַּ֣עַם הַ⁠זֹּ֑את וַ⁠הֲצֵר֥וֹתִי לָ⁠הֶ֖ם לְמַ֥עַן יִמְצָֽאוּ׃ס","kiֽ̇y-kòh֙ ʼáma֣r yĕhwá֔h hinĕ⁠ni֥y qwòlé֛ʻa ʼeţ-ywòşĕ̌bé֥y há⁠ʼá֖reẕ bȧ⁠pȧ֣ʻam ha⁠zò֑̇ʼţ wa⁠hàẕér֥wòţiy lá⁠he֖m lĕma֥ʻan yimĕẕáֽʼẇ׃s"],[10,19,"א֥וֹי לִ⁠י֙ עַל־שִׁבְרִ֔⁠י נַחְלָ֖ה מַכָּתִ֑⁠י וַ⁠אֲנִ֣י אָמַ֔רְתִּי אַ֛ךְ זֶ֥ה חֳלִ֖י וְ⁠אֶשָּׂאֶֽ⁠נּוּ׃","ʼ֥wòy li⁠y֙ ʻal-şǐbĕri֔⁠y naẖĕlá֖h maká̇ţi֑⁠y wa⁠ʼàni֣y ʼáma֔rĕţi̇y ʼa֛kĕ ze֥h ẖoli֖y wĕ⁠ʼeşá̇̂ʼeֽ⁠ṅẇ׃"],[10,20,"אָהֳלִ֣⁠י שֻׁדָּ֔ד וְ⁠כָל־מֵיתָרַ֖⁠י נִתָּ֑קוּ בָּנַ֤⁠י יְצָאֻ֨⁠נִי֙ וְ⁠אֵינָ֔⁠ם אֵין־נֹטֶ֥ה עוֹד֙ אָהֳלִ֔⁠י וּ⁠מֵקִ֖ים יְרִיעוֹתָֽ⁠י׃","ʼáholi֣⁠y şǔdá̇֔d wĕ⁠kál-méyţára֖⁠y niţá֑̇qẇ bá̇na֤⁠y yĕẕáʼu֨⁠niy֙ wĕ⁠ʼéyná֔⁠m ʼéyn-nòte֥h ʻwòd֙ ʼáholi֔⁠y ẇ⁠méqi֖ym yĕriyʻwòţáֽ⁠y׃"],[10,21,"כִּ֤י נִבְעֲרוּ֙ הָֽ⁠רֹעִ֔ים וְ⁠אֶת־יְהוָ֖ה לֹ֣א דָרָ֑שׁוּ עַל־כֵּן֙ לֹ֣א הִשְׂכִּ֔ילוּ וְ⁠כָל־מַרְעִיתָ֖⁠ם נָפֽוֹצָה׃ס","ki֤̇y nibĕʻàrẇ֙ háֽ⁠ròʻi֔ym wĕ⁠ʼeţ-yĕhwá֖h lò֣ʼ dárá֑ş̌ẇ ʻal-ké̇n֙ lò֣ʼ hişĕ̂ki̇֔ylẇ wĕ⁠kál-marĕʻiyţá֖⁠m nápֽwòẕáh׃s"],[10,22,"ק֤וֹל שְׁמוּעָה֙ הִנֵּ֣ה בָאָ֔ה וְ⁠רַ֥עַשׁ גָּד֖וֹל מֵ⁠אֶ֣רֶץ צָפ֑וֹן לָ⁠שׂ֞וּם אֶת־עָרֵ֧י יְהוּדָ֛ה שְׁמָמָ֖ה מְע֥וֹן תַּנִּֽים׃ס","q֤wòl şĕ̌mẇʻáh֙ hiné֣̇h báʼá֔h wĕ⁠ra֥ʻaş̌ gá̇d֖wòl mé⁠ʼe֣reẕ ẕáp֑wòn lá⁠ş̂֞ẇm ʼeţ-ʻáré֧y yĕhẇdá֛h şĕ̌mámá֖h mĕʻ֥wòn ţȧniֽ̇ym׃s"],[10,23,"יָדַ֣עְתִּי יְהוָ֔ה כִּ֛י לֹ֥א לָ⁠אָדָ֖ם דַּרְכּ֑⁠וֹ לֹֽא־לְ⁠אִ֣ישׁ הֹלֵ֔ךְ וְ⁠הָכִ֖ין אֶֽת־צַעֲדֽ⁠וֹ׃","yáda֣ʻĕţi̇y yĕhwá֔h ki֛̇y lò֥ʼ lá⁠ʼádá֖m dȧrĕk֑̇⁠wò lòֽʼ-lĕ⁠ʼi֣yş̌ hòlé֔kĕ wĕ⁠háki֖yn ʼeֽţ-ẕaʻàdֽ⁠wò׃"],[10,24,"יַסְּרֵ֥⁠נִי יְהוָ֖ה אַךְ־בְּ⁠מִשְׁפָּ֑ט אַל־בְּ⁠אַפְּ⁠ךָ֖ פֶּן־תַּמְעִטֵֽ⁠נִי׃","yasĕ̇ré֥⁠niy yĕhwá֖h ʼakĕ-bĕ̇⁠mişĕ̌pá֑̇t ʼal-bĕ̇⁠ʼapĕ̇⁠ká֖ pėn-ţȧmĕʻitéֽ⁠niy׃"],[10,25,"שְׁפֹ֣ךְ חֲמָתְ⁠ךָ֗ עַל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר לֹֽא־יְדָע֔וּ⁠ךָ וְ⁠עַל֙ מִשְׁפָּח֔וֹת אֲשֶׁ֥ר בְּ⁠שִׁמְ⁠ךָ֖ לֹ֣א קָרָ֑אוּ כִּֽי־אָכְל֣וּ אֶֽת־יַעֲקֹ֗ב וַ⁠אֲכָלֻ֨⁠הוּ֙ וַ⁠יְכַלֻּ֔⁠הוּ וְ⁠אֶת־נָוֵ֖⁠הוּ הֵשַֽׁמּוּ׃פ","şĕ̌pò֣kĕ ẖàmáţĕ⁠ká֗ ʻal-ha⁠ġwòyim֙ ʼàşě֣r lòֽʼ-yĕdáʻ֔ẇ⁠ká wĕ⁠ʻal֙ mişĕ̌pá̇ẖ֔wòţ ʼàşě֥r bĕ̇⁠şǐmĕ⁠ká֖ lò֣ʼ qárá֑ʼẇ kiֽ̇y-ʼákĕl֣ẇ ʼeֽţ-yaʻàqò֗b wa⁠ʼàkálu֨⁠hẇ֙ wa⁠yĕkalu̇֔⁠hẇ wĕ⁠ʼeţ-náwé֖⁠hẇ héşǎֽṁẇ׃p"],[11,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר הָיָ֣ה אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","ha⁠dá̇bár֙ ʼàşě֣r háyá֣h ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[11,2,"שִׁמְע֕וּ אֶת־דִּבְרֵ֖י הַ⁠בְּרִ֣ית הַ⁠זֹּ֑את וְ⁠דִבַּרְתָּ⁠ם֙ אֶל־אִ֣ישׁ יְהוּדָ֔ה וְ⁠עַל־יֹשְׁבֵ֖י יְרוּשָׁלִָֽם׃","şǐmĕʻ֕ẇ ʼeţ-di̇bĕré֖y ha⁠bĕ̇ri֣yţ ha⁠zò֑̇ʼţ wĕ⁠dibȧrĕţá̇⁠m֙ ʼel-ʼi֣yş̌ yĕhẇdá֔h wĕ⁠ʻal-yòşĕ̌bé֖y yĕrẇşá̌liáֽm׃"],[11,3,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אָר֣וּר הָ⁠אִ֔ישׁ אֲשֶׁר֙ לֹ֣א יִשְׁמַ֔ע אֶת־דִּבְרֵ֖י הַ⁠בְּרִ֥ית הַ⁠זֹּֽאת׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼár֣ẇr há⁠ʼi֔yş̌ ʼàşěr֙ lò֣ʼ yişĕ̌ma֔ʻ ʼeţ-di̇bĕré֖y ha⁠bĕ̇ri֥yţ ha⁠zòֽ̇ʼţ׃"],[11,4,"אֲשֶׁ֣ר צִוִּ֣יתִי אֶת־אֲבֽוֹתֵי⁠כֶ֡ם בְּ⁠י֣וֹם הוֹצִיאִֽ⁠י־אוֹתָ֣⁠ם מֵ⁠אֶֽרֶץ־מִצְרַיִם֩ מִ⁠כּ֨וּר הַ⁠בַּרְזֶ֜ל לֵ⁠אמֹ֗ר שִׁמְע֤וּ בְ⁠קוֹלִ⁠י֙ וַ⁠עֲשִׂיתֶ֣ם אוֹתָ֔⁠ם כְּ⁠כֹ֥ל אֲשֶׁר־אֲצַוֶּ֖ה אֶתְ⁠כֶ֑ם וִ⁠הְיִ֤יתֶם לִ⁠י֙ לְ⁠עָ֔ם וְ⁠אָ֣נֹכִ֔י אֶהְיֶ֥ה לָ⁠כֶ֖ם לֵ⁠אלֹהִֽים׃","ʼàşě֣r ẕiwi֣̇yţiy ʼeţ-ʼàbֽwòţéy⁠ke֡m bĕ̇⁠y֣wòm hwòẕiyʼiֽ⁠y-ʼwòţá֣⁠m mé⁠ʼeֽreẕ-miẕĕrayim֩ mi⁠k̇֨ẇr ha⁠bȧrĕze֜l lé⁠ʼmò֗r şǐmĕʻ֤ẇ bĕ⁠qwòli⁠y֙ wa⁠ʻàşîyţe֣m ʼwòţá֔⁠m kĕ̇⁠kò֥l ʼàşěr-ʼàẕawė֖h ʼeţĕ⁠ke֑m wi⁠hĕyi֤yţem li⁠y֙ lĕ⁠ʻá֔m wĕ⁠ʼá֣nòki֔y ʼehĕye֥h lá⁠ke֖m lé⁠ʼlòhiֽym׃"],[11,5,"לְמַעַן֩ הָקִ֨ים אֶת־הַ⁠שְּׁבוּעָ֜ה אֲשֶׁר־נִשְׁבַּ֣עְתִּי לַ⁠אֲבֽוֹתֵי⁠כֶ֗ם לָ⁠תֵ֤ת לָ⁠הֶם֙ אֶ֣רֶץ זָבַ֥ת חָלָ֛ב וּ⁠דְבַ֖שׁ כַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה וָ⁠אַ֥עַן וָ⁠אֹמַ֖ר אָמֵ֥ן ׀ יְהוָֽה׃ס","lĕmaʻan֩ háqi֨ym ʼeţ-ha⁠şĕ̇̌bẇʻá֜h ʼàşěr-nişĕ̌bȧ֣ʻĕţi̇y la⁠ʼàbֽwòţéy⁠ke֗m lá⁠ţé֤ţ lá⁠hem֙ ʼe֣reẕ zába֥ţ ẖálá֛b ẇ⁠dĕba֖ş̌ kȧ⁠ẏ֣wòm ha⁠zė֑h wá⁠ʼa֥ʻan wá⁠ʼòma֖r ʼámé֥n ׀ yĕhwáֽh׃s"],[11,6,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י קְרָ֨א אֶת־כָּל־הַ⁠דְּבָרִ֤ים הָ⁠אֵ֨לֶּה֙ בְּ⁠עָרֵ֣י יְהוּדָ֔ה וּ⁠בְ⁠חֻצ֥וֹת יְרוּשָׁלִַ֖ם לֵ⁠אמֹ֑ר שִׁמְע֗וּ אֶת־דִּבְרֵי֙ הַ⁠בְּרִ֣ית הַ⁠זֹּ֔את וַ⁠עֲשִׂיתֶ֖ם אוֹתָֽ⁠ם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y qĕrá֨ʼ ʼeţ-ká̇l-ha⁠dĕ̇bári֤ym há⁠ʼé֨lėh֙ bĕ̇⁠ʻáré֣y yĕhẇdá֔h ẇ⁠bĕ⁠ẖuẕ֥wòţ yĕrẇşá̌lia֖m lé⁠ʼmò֑r şǐmĕʻ֗ẇ ʼeţ-di̇bĕréy֙ ha⁠bĕ̇ri֣yţ ha⁠zò̇֔ʼţ wa⁠ʻàşîyţe֖m ʼwòţáֽ⁠m׃"],[11,7,"כִּי֩ הָעֵ֨ד הַעִדֹ֜תִי בַּ⁠אֲבֽוֹתֵי⁠כֶ֗ם בְּ⁠יוֹם֩ הַעֲלוֹתִ֨⁠י אוֹתָ֜⁠ם מֵ⁠אֶ֤רֶץ מִצְרַ֨יִם֙ וְ⁠עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה הַשְׁכֵּ֥ם וְ⁠הָעֵ֖ד לֵ⁠אמֹ֑ר שִׁמְע֖וּ בְּ⁠קוֹלִֽ⁠י׃","ki̇y֩ háʻé֨d haʻidò֜ţiy bȧ⁠ʼàbֽwòţéy⁠ke֗m bĕ̇⁠ywòm֩ haʻàlwòţi֨⁠y ʼwòţá֜⁠m mé⁠ʼe֤reẕ miẕĕra֨yim֙ wĕ⁠ʻad-ha⁠ẏ֣wòm ha⁠zė֔h haşĕ̌ké֥̇m wĕ⁠háʻé֖d lé⁠ʼmò֑r şǐmĕʻ֖ẇ bĕ̇⁠qwòliֽ⁠y׃"],[11,8,"וְ⁠לֹ֤א שָֽׁמְעוּ֙ וְ⁠לֹֽא־הִטּ֣וּ אֶת־אָזְנָ֔⁠ם וַ⁠יֵּ֣לְכ֔וּ אִ֕ישׁ בִּ⁠שְׁרִיר֖וּת לִבָּ֣⁠ם הָ⁠רָ֑ע וָ⁠אָבִ֨יא עֲלֵי⁠הֶ֜ם אֶֽת־כָּל־דִּבְרֵ֧י הַ⁠בְּרִית־הַ⁠זֹּ֛את אֲשֶׁר־צִוִּ֥יתִי לַ⁠עֲשׂ֖וֹת וְ⁠לֹ֥א עָשֽׂוּ׃ס","wĕ⁠lò֤ʼ şáֽ̌mĕʻẇ֙ wĕ⁠lòֽʼ-hiṫ֣ẇ ʼeţ-ʼázĕná֔⁠m wa⁠yé֣̇lĕk֔ẇ ʼi֕yş̌ bi̇⁠şĕ̌riyr֖ẇţ libá֣̇⁠m há⁠rá֑ʻ wá⁠ʼábi֨yʼ ʻàléy⁠he֜m ʼeֽţ-ká̇l-di̇bĕré֧y ha⁠bĕ̇riyţ-ha⁠zò֛̇ʼţ ʼàşěr-ẕiwi֥̇yţiy la⁠ʻàş֖̂wòţ wĕ⁠lò֥ʼ ʻáşֽ̂ẇ׃s"],[11,9,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י נִֽמְצָא־קֶ֨שֶׁר֙ בְּ⁠אִ֣ישׁ יְהוּדָ֔ה וּ⁠בְ⁠יֹשְׁבֵ֖י יְרוּשָׁלִָֽם׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y niֽmĕẕáʼ-qe֨şěr֙ bĕ̇⁠ʼi֣yş̌ yĕhẇdá֔h ẇ⁠bĕ⁠yòşĕ̌bé֖y yĕrẇşá̌liáֽm׃"],[11,10,"שָׁ֩בוּ֩ עַל־עֲוֺנֹ֨ת אֲבוֹתָ֜⁠ם הָ⁠רִֽאשֹׁנִ֗ים אֲשֶׁ֤ר מֵֽאֲנוּ֙ לִ⁠שְׁמ֣וֹעַ אֶת־דְּבָרַ֔⁠י וְ⁠הֵ֣מָּה הָלְכ֗וּ אַחֲרֵ֛י אֱלֹהִ֥ים אֲחֵרִ֖ים לְ⁠עָבְדָ֑⁠ם הֵפֵ֤רוּ בֵֽית־יִשְׂרָאֵל֙ וּ⁠בֵ֣ית יְהוּדָ֔ה אֶת־בְּרִיתִ֕⁠י אֲשֶׁ֥ר כָּרַ֖תִּי אֶת־אֲבוֹתָֽ⁠ם׃ס","şá̌֩bẇ֩ ʻal-ʻàwֺnò֨ţ ʼàbwòţá֜⁠m há⁠riֽʼşò̌ni֗ym ʼàşě֤r méֽʼànẇ֙ li⁠şĕ̌m֣wòʻa ʼeţ-dĕ̇bára֔⁠y wĕ⁠hé֣má̇h hálĕk֗ẇ ʼaẖàré֛y ʼèlòhi֥ym ʼàẖéri֖ym lĕ⁠ʻábĕdá֑⁠m hépé֤rẇ béֽyţ-yişĕ̂ráʼél֙ ẇ⁠bé֣yţ yĕhẇdá֔h ʼeţ-bĕ̇riyţi֕⁠y ʼàşě֥r ká̇ra֖ţi̇y ʼeţ-ʼàbwòţáֽ⁠m׃s"],[11,11,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֨י מֵבִ֤יא אֲלֵי⁠הֶם֙ רָעָ֔ה אֲשֶׁ֥ר לֹֽא־יוּכְל֖וּ לָ⁠צֵ֣את מִמֶּ֑⁠נָּה וְ⁠זָעֲק֣וּ אֵלַ֔⁠י וְ⁠לֹ֥א אֶשְׁמַ֖ע אֲלֵי⁠הֶֽם׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֨y mébi֤yʼ ʼàléy⁠hem֙ ráʻá֔h ʼàşě֥r lòֽʼ-yẇkĕl֖ẇ lá⁠ẕé֣ʼţ mimė֑⁠ná̇h wĕ⁠záʻàq֣ẇ ʼéla֔⁠y wĕ⁠lò֥ʼ ʼeşĕ̌ma֖ʻ ʼàléy⁠heֽm׃"],[11,12,"וְ⁠הָֽלְכ֞וּ עָרֵ֣י יְהוּדָ֗ה וְ⁠יֹשְׁבֵי֙ יְר֣וּשָׁלִַ֔ם וְ⁠זָֽעֲקוּ֙ אֶל־הָ֣⁠אֱלֹהִ֔ים אֲשֶׁ֛ר הֵ֥ם מְקַטְּרִ֖ים לָ⁠הֶ֑ם וְ⁠הוֹשֵׁ֛עַ לֹֽא־יוֹשִׁ֥יעוּ לָ⁠הֶ֖ם בְּ⁠עֵ֥ת רָעָתָֽ⁠ם׃","wĕ⁠háֽlĕk֞ẇ ʻáré֣y yĕhẇdá֗h wĕ⁠yòşĕ̌béy֙ yĕr֣ẇşá̌lia֔m wĕ⁠záֽʻàqẇ֙ ʼel-há֣⁠ʼèlòhi֔ym ʼàşě֛r hé֥m mĕqatĕ̇ri֖ym lá⁠he֑m wĕ⁠hwòşé֛̌ʻa lòֽʼ-ywòşǐ֥yʻẇ lá⁠he֖m bĕ̇⁠ʻé֥ţ ráʻáţáֽ⁠m׃"],[11,13,"כִּ֚י מִסְפַּ֣ר עָרֶ֔י⁠ךָ הָי֥וּ אֱלֹהֶ֖י⁠ךָ יְהוּדָ֑ה וּ⁠מִסְפַּ֞ר חֻצ֣וֹת יְרוּשָׁלִַ֗ם שַׂמְתֶּ֤ם מִזְבְּחוֹת֙ לַ⁠בֹּ֔שֶׁת מִזְבְּח֖וֹת לְ⁠קַטֵּ֥ר לַ⁠בָּֽעַל׃ס","ki֚̇y misĕpȧ֣r ʻáre֔y⁠ká háy֥ẇ ʼèlòhe֖y⁠ká yĕhẇdá֑h ẇ⁠misĕpȧ֞r ẖuẕ֣wòţ yĕrẇşá̌lia֗m şâmĕţė֤m mizĕbĕ̇ẖwòţ֙ la⁠bò̇֔şěţ mizĕbĕ̇ẖ֖wòţ lĕ⁠qaté֥̇r la⁠báֽ̇ʻal׃s"],[11,14,"וְ⁠אַתָּ֗ה אַל־תִּתְפַּלֵּל֙ בְּעַד־הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠אַל־תִּשָּׂ֥א בַעֲדָ֖⁠ם רִנָּ֣ה וּ⁠תְפִלָּ֑ה כִּ֣י אֵינֶ֣⁠נִּי שֹׁמֵ֗עַ בְּ⁠עֵ֛ת קָרְאָ֥⁠ם אֵלַ֖⁠י בְּעַ֥ד רָעָתָֽ⁠ם׃ס","wĕ⁠ʼaţá̇֗h ʼal-ţi̇ţĕpȧlé̇l֙ bĕ̇ʻad-há⁠ʻá֣m ha⁠zė֔h wĕ⁠ʼal-ţi̇şá֥̇̂ʼ baʻàdá֖⁠m riná֣̇h ẇ⁠ţĕpilá֑̇h ki֣̇y ʼéyne֣⁠ni̇y şò̌mé֗ʻa bĕ̇⁠ʻé֛ţ qárĕʼá֥⁠m ʼéla֖⁠y bĕ̇ʻa֥d ráʻáţáֽ⁠m׃s"],[11,15,"מֶ֣ה לִֽ⁠ידִידִ֞⁠י בְּ⁠בֵיתִ֗⁠י עֲשׂוֹתָ֤⁠הּ הַֽ⁠מְזִמָּ֨תָ⁠ה֙ הָֽ⁠רַבִּ֔ים וּ⁠בְשַׂר־קֹ֖דֶשׁ יַעַבְר֣וּ מֵֽ⁠עָלָ֑יִ⁠ךְ כִּ֥י רָעָתֵ֖⁠כִי אָ֥ז תַּעֲלֹֽזִי׃","me֣h liֽ⁠ydiydi֞⁠y bĕ̇⁠béyţi֗⁠y ʻàş̂wòţá֤⁠ḣ haֽ⁠mĕzimá̇֨ţá⁠h֙ háֽ⁠rabi̇֔ym ẇ⁠bĕşâr-qò֖deş̌ yaʻabĕr֣ẇ méֽ⁠ʻálá֑yi⁠kĕ ki֥̇y ráʻáţé֖⁠kiy ʼá֥z ţȧʻàlòֽziy׃"],[11,16,"זַ֤יִת רַֽעֲנָן֙ יְפֵ֣ה פְרִי־תֹ֔אַר קָרָ֥א יְהוָ֖ה שְׁמֵ֑⁠ךְ לְ⁠ק֣וֹל ׀ הֲמוּלָּ֣ה גְדֹלָ֗ה הִצִּ֥ית אֵשׁ֙ עָלֶ֔י⁠הָ וְ⁠רָע֖וּ דָּלִיּוֹתָֽי⁠ו׃","za֤yiţ raֽʻànán֙ yĕpé֣h pĕriy-ţò֔ʼar qárá֥ʼ yĕhwá֖h şĕ̌mé֑⁠kĕ lĕ⁠q֣wòl ׀ hàmẇlá֣̇h gĕdòlá֗h hiẕi֥̇yţ ʼéş̌֙ ʻále֔y⁠há wĕ⁠ráʻ֖ẇ dá̇liẏwòţáֽy⁠w׃"],[11,17,"וַ⁠יהוָ֤ה צְבָאוֹת֙ הַ⁠נּוֹטֵ֣עַ אוֹתָ֔⁠ךְ דִּבֶּ֥ר עָלַ֖יִ⁠ךְ רָעָ֑ה בִּ֠⁠גְלַל רָעַ֨ת בֵּֽית־יִשְׂרָאֵ֜ל וּ⁠בֵ֣ית יְהוּדָ֗ה אֲשֶׁ֨ר עָשׂ֥וּ לָ⁠הֶ֛ם לְ⁠הַכְעִסֵ֖⁠נִי לְ⁠קַטֵּ֥ר לַ⁠בָּֽעַל׃ס","wa⁠yhwá֤h ẕĕbáʼwòţ֙ ha⁠ṅwòté֣ʻa ʼwòţá֔⁠kĕ di̇bė֥r ʻála֖yi⁠kĕ ráʻá֑h bi̇֠⁠gĕlal ráʻa֨ţ béֽ̇yţ-yişĕ̂ráʼé֜l ẇ⁠bé֣yţ yĕhẇdá֗h ʼàşě֨r ʻáş֥̂ẇ lá⁠he֛m lĕ⁠hakĕʻisé֖⁠niy lĕ⁠qaté֥̇r la⁠báֽ̇ʻal׃s"],[11,18,"וַֽ⁠יהוָ֥ה הֽוֹדִיעַ֖⁠נִי וָֽ⁠אֵדָ֑עָ⁠ה אָ֖ז הִרְאִיתַ֥⁠נִי מַעַלְלֵי⁠הֶֽם׃","waֽ⁠yhwá֥h hֽwòdiyʻa֖⁠niy wáֽ⁠ʼédá֑ʻá⁠h ʼá֖z hirĕʼiyţa֥⁠niy maʻalĕléy⁠heֽm׃"],[11,19,"וַ⁠אֲנִ֕י כְּ⁠כֶ֥בֶשׂ אַלּ֖וּף יוּבַ֣ל לִ⁠טְב֑וֹחַ וְ⁠לֹֽא־יָדַ֜עְתִּי כִּֽי־עָלַ֣⁠י ׀ חָשְׁב֣וּ מַחֲשָׁב֗וֹת נַשְׁחִ֨יתָה עֵ֤ץ בְּ⁠לַחְמ⁠וֹ֙ וְ⁠נִכְרְתֶ֨⁠נּוּ֙ מֵ⁠אֶ֣רֶץ חַיִּ֔ים וּ⁠שְׁמ֖⁠וֹ לֹֽא־יִזָּכֵ֥ר עֽוֹד׃","wa⁠ʼàni֕y kĕ̇⁠ke֥beş̂ ʼal֖̇ẇp yẇba֣l li⁠tĕb֑wòẖa wĕ⁠lòֽʼ-yáda֜ʻĕţi̇y kiֽ̇y-ʻála֣⁠y ׀ ẖáşĕ̌b֣ẇ maẖàşá̌b֗wòţ naşĕ̌ẖi֨yţáh ʻé֤ẕ bĕ̇⁠laẖĕm⁠wò֙ wĕ⁠nikĕrĕţe֨⁠ṅẇ֙ mé⁠ʼe֣reẕ ẖayi̇֔ym ẇ⁠şĕ̌m֖⁠wò lòֽʼ-yizá̇ké֥r ʻֽwòd׃"],[11,20,"וַֽ⁠יהוָ֤ה צְבָאוֹת֙ שֹׁפֵ֣ט צֶ֔דֶק בֹּחֵ֥ן כְּלָי֖וֹת וָ⁠לֵ֑ב אֶרְאֶ֤ה נִקְמָֽתְ⁠ךָ֙ מֵ⁠הֶ֔ם כִּ֥י אֵלֶ֖י⁠ךָ גִּלִּ֥יתִי אֶת־רִיבִֽ⁠י׃ס","waֽ⁠yhwá֤h ẕĕbáʼwòţ֙ şò̌pé֣t ẕe֔deq bò̇ẖé֥n kĕ̇láy֖wòţ wá⁠lé֑b ʼerĕʼe֤h niqĕmáֽţĕ⁠ká֙ mé⁠he֔m ki֥̇y ʼéle֖y⁠ká gi̇li֥̇yţiy ʼeţ-riybiֽ⁠y׃s"],[11,21,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ עַל־אַנְשֵׁ֣י עֲנָת֔וֹת הַֽ⁠מְבַקְשִׁ֥ים אֶֽת־נַפְשְׁ⁠ךָ֖ לֵ⁠אמֹ֑ר לֹ֤א תִנָּבֵא֙ בְּ⁠שֵׁ֣ם יְהוָ֔ה וְ⁠לֹ֥א תָמ֖וּת בְּ⁠יָדֵֽ⁠נוּ׃ס","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʻal-ʼanĕşé֣̌y ʻànáţ֔wòţ haֽ⁠mĕbaqĕşǐ֥ym ʼeֽţ-napĕşĕ̌⁠ká֖ lé⁠ʼmò֑r lò֤ʼ ţiná̇béʼ֙ bĕ̇⁠şé֣̌m yĕhwá֔h wĕ⁠lò֥ʼ ţám֖ẇţ bĕ̇⁠yádéֽ⁠nẇ׃s"],[11,22,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִ֥י פֹקֵ֖ד עֲלֵי⁠הֶ֑ם הַ⁠בַּֽחוּרִים֙ יָמֻ֣תוּ בַ⁠חֶ֔רֶב בְּנֵי⁠הֶם֙ וּ⁠בְנ֣וֹתֵי⁠הֶ֔ם יָמֻ֖תוּ בָּ⁠רָעָֽב׃","lá⁠ké֗n kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠ni֥y pòqé֖d ʻàléy⁠he֑m ha⁠bȧֽẖẇriym֙ yámu֣ţẇ ba⁠ẖe֔reb bĕ̇néy⁠hem֙ ẇ⁠bĕn֣wòţéy⁠he֔m yámu֖ţẇ bá̇⁠ráʻáֽb׃"],[11,23,"וּ⁠שְׁאֵרִ֕ית לֹ֥א תִֽהְיֶ֖ה לָ⁠הֶ֑ם כִּֽי־אָבִ֥יא רָעָ֛ה אֶל־אַנְשֵׁ֥י עֲנָת֖וֹת שְׁנַ֥ת פְּקֻדָּתָֽ⁠ם׃ס","ẇ⁠şĕ̌ʼéri֕yţ lò֥ʼ ţiֽhĕye֖h lá⁠he֑m kiֽ̇y-ʼábi֥yʼ ráʻá֛h ʼel-ʼanĕşé֥̌y ʻànáţ֖wòţ şĕ̌na֥ţ pĕ̇qudá̇ţáֽ⁠m׃s"],[12,1,"צַדִּ֤יק אַתָּה֙ יְהוָ֔ה כִּ֥י אָרִ֖יב אֵלֶ֑י⁠ךָ אַ֤ךְ מִשְׁפָּטִים֙ אֲדַבֵּ֣ר אוֹתָ֔⁠ךְ מַדּ֗וּעַ דֶּ֤רֶךְ רְשָׁעִים֙ צָלֵ֔חָה שָׁל֖וּ כָּל־בֹּ֥גְדֵי בָֽגֶד׃","ẕadi֤̇yq ʼaţá̇h֙ yĕhwá֔h ki֥̇y ʼári֖yb ʼéle֑y⁠ká ʼa֤kĕ mişĕ̌pá̇tiym֙ ʼàdabé֣̇r ʼwòţá֔⁠kĕ maḋ֗ẇʻa dė֤rekĕ rĕşá̌ʻiym֙ ẕálé֔ẖáh şá̌l֖ẇ ká̇l-bò֥̇gĕdéy báֽged׃"],[12,2,"נְטַעְתָּ⁠ם֙ גַּם־שֹׁרָ֔שׁוּ יֵלְכ֖וּ גַּם־עָ֣שׂוּ פֶ֑רִי קָר֤וֹב אַתָּה֙ בְּ⁠פִי⁠הֶ֔ם וְ⁠רָח֖וֹק מִ⁠כִּלְיוֹתֵי⁠הֶֽם׃","nĕtaʻĕţá̇⁠m֙ gȧm-şò̌rá֔ş̌ẇ yélĕk֖ẇ gȧm-ʻá֣ş̂ẇ pe֑riy qár֤wòb ʼaţá̇h֙ bĕ̇⁠piy⁠he֔m wĕ⁠ráẖ֖wòq mi⁠ki̇lĕywòţéy⁠heֽm׃"],[12,3,"וְ⁠אַתָּ֤ה יְהוָה֙ יְדַעְתָּ֔⁠נִי תִּרְאֵ֕⁠נִי וּ⁠בָחַנְתָּ֥ לִבִּ֖⁠י אִתָּ֑⁠ךְ הַתִּקֵ⁠ם֙ כְּ⁠צֹ֣אן לְ⁠טִבְחָ֔ה וְ⁠הַקְדִּשֵׁ֖⁠ם לְ⁠י֥וֹם הֲרֵגָֽה׃ס","wĕ⁠ʼaţá֤̇h yĕhwáh֙ yĕdaʻĕţá̇֔⁠niy ţi̇rĕʼé֕⁠niy ẇ⁠báẖanĕţá֥̇ libi֖̇⁠y ʼiţá֑̇⁠kĕ haţi̇qé⁠m֙ kĕ̇⁠ẕò֣ʼn lĕ⁠tibĕẖá֔h wĕ⁠haqĕdi̇şé֖̌⁠m lĕ⁠y֥wòm hàrégáֽh׃s"],[12,4,"עַד־מָתַי֙ תֶּאֱבַ֣ל הָ⁠אָ֔רֶץ וְ⁠עֵ֥שֶׂב כָּל־הַ⁠שָּׂדֶ֖ה יִיבָ֑שׁ מֵ⁠רָעַ֣ת יֹֽשְׁבֵי־בָ֗⁠הּ סָפְתָ֤ה בְהֵמוֹת֙ וָ⁠ע֔וֹף כִּ֣י אָמְר֔וּ לֹ֥א יִרְאֶ֖ה אֶת־אַחֲרִיתֵֽ⁠נוּ׃","ʻad-máţay֙ ţėʼèba֣l há⁠ʼá֔reẕ wĕ⁠ʻé֥şêb ká̇l-ha⁠şá̇̂de֖h yiybá֑ş̌ mé⁠ráʻa֣ţ yòֽşĕ̌béy-bá֗⁠ḣ sápĕţá֤h bĕhémwòţ֙ wá⁠ʻ֔wòp ki֣̇y ʼámĕr֔ẇ lò֥ʼ yirĕʼe֖h ʼeţ-ʼaẖàriyţéֽ⁠nẇ׃"],[12,5,"כִּ֣י אֶת־רַגְלִ֥ים ׀ רַ֨צְתָּה֙ וַ⁠יַּלְא֔וּ⁠ךָ וְ⁠אֵ֥יךְ תְּתַֽחֲרֶ֖ה אֶת־הַ⁠סּוּסִ֑ים וּ⁠בְ⁠אֶ֤רֶץ שָׁלוֹם֙ אַתָּ֣ה בוֹטֵ֔חַ וְ⁠אֵ֥יךְ תַּעֲשֶׂ֖ה בִּ⁠גְא֥וֹן הַ⁠יַּרְדֵּֽן׃","ki֣̇y ʼeţ-ragĕli֥ym ׀ ra֨ẕĕţá̇h֙ wa⁠yȧlĕʼ֔ẇ⁠ká wĕ⁠ʼé֥ykĕ ţĕ̇ţaֽẖàre֖h ʼeţ-ha⁠ṡẇsi֑ym ẇ⁠bĕ⁠ʼe֤reẕ şá̌lwòm֙ ʼaţá֣̇h bwòté֔ẖa wĕ⁠ʼé֥ykĕ ţȧʻàşê֖h bi̇⁠gĕʼ֥wòn ha⁠yȧrĕdéֽ̇n׃"],[12,6,"כִּ֧י גַם־אַחֶ֣י⁠ךָ וּ⁠בֵית־אָבִ֗י⁠ךָ גַּם־הֵ֨מָּה֙ בָּ֣גְדוּ בָ֔⁠ךְ גַּם־הֵ֛מָּה קָרְא֥וּ אַחֲרֶ֖י⁠ךָ מָלֵ֑א אַל־תַּאֲמֵ֣ן בָּ֔⁠ם כִּֽי־יְדַבְּר֥וּ אֵלֶ֖י⁠ךָ טוֹבֽוֹת׃ס","ki֧̇y gam-ʼaẖe֣y⁠ká ẇ⁠béyţ-ʼábi֗y⁠ká gȧm-hé֨má̇h֙ bá֣̇gĕdẇ bá֔⁠kĕ gȧm-hé֛má̇h qárĕʼ֥ẇ ʼaẖàre֖y⁠ká málé֑ʼ ʼal-ţȧʼàmé֣n bá̇֔⁠m kiֽ̇y-yĕdabĕ̇r֥ẇ ʼéle֖y⁠ká twòbֽwòţ׃s"],[12,7,"עָזַ֨בְתִּי֙ אֶת־בֵּיתִ֔⁠י נָטַ֖שְׁתִּי אֶת־נַחֲלָתִ֑⁠י נָתַ֛תִּי אֶת־יְדִד֥וּת נַפְשִׁ֖⁠י בְּ⁠כַ֥ף אֹיְבֶֽי⁠הָ׃","ʻáza֨bĕţi̇y֙ ʼeţ-bé̇yţi֔⁠y náta֖şĕ̌ţi̇y ʼeţ-naẖàláţi֑⁠y náţa֛ţi̇y ʼeţ-yĕdid֥ẇţ napĕşǐ֖⁠y bĕ̇⁠ka֥p ʼòyĕbeֽy⁠há׃"],[12,8,"הָיְתָה־לִּ֥⁠י נַחֲלָתִ֖⁠י כְּ⁠אַרְיֵ֣ה בַ⁠יָּ֑עַר נָתְנָ֥ה עָלַ֛⁠י בְּ⁠קוֹלָ֖⁠הּ עַל־כֵּ֥ן שְׂנֵאתִֽי⁠הָ׃","háyĕţáh-li֥̇⁠y naẖàláţi֖⁠y kĕ̇⁠ʼarĕyé֣h ba⁠yá֑̇ʻar náţĕná֥h ʻála֛⁠y bĕ̇⁠qwòlá֖⁠ḣ ʻal-ké֥̇n şĕ̂néʼţiֽy⁠há׃"],[12,9,"הַ⁠עַ֨יִט צָב֤וּעַ נַחֲלָתִ⁠י֙ לִ֔⁠י הַ⁠עַ֖יִט סָבִ֣יב עָלֶ֑י⁠הָ לְכ֗וּ אִסְפ֛וּ כָּל־חַיַּ֥ת הַ⁠שָּׂדֶ֖ה הֵתָ֥יוּ לְ⁠אָכְלָֽה׃","ha⁠ʻa֨yit ẕáb֤ẇʻa naẖàláţi⁠y֙ li֔⁠y ha⁠ʻa֖yit sábi֣yb ʻále֑y⁠há lĕk֗ẇ ʼisĕp֛ẇ ká̇l-ẖayȧ֥ţ ha⁠şá̇̂de֖h héţá֥yẇ lĕ⁠ʼákĕláֽh׃"],[12,10,"רֹעִ֤ים רַבִּים֙ שִֽׁחֲת֣וּ כַרְמִ֔⁠י בֹּסְס֖וּ אֶת־חֶלְקָתִ֑⁠י נָֽתְנ֛וּ אֶת־חֶלְקַ֥ת חֶמְדָּתִ֖⁠י לְ⁠מִדְבַּ֥ר שְׁמָמָֽה׃","ròʻi֤ym rabi̇ym֙ şǐֽẖàţ֣ẇ karĕmi֔⁠y bò̇sĕs֖ẇ ʼeţ-ẖelĕqáţi֑⁠y náֽţĕn֛ẇ ʼeţ-ẖelĕqa֥ţ ẖemĕdá̇ţi֖⁠y lĕ⁠midĕbȧ֥r şĕ̌mámáֽh׃"],[12,11,"שָׂמָ⁠הּ֙ לִ⁠שְׁמָמָ֔ה אָבְלָ֥ה עָלַ֖⁠י שְׁמֵמָ֑ה נָשַׁ֨מָּה֙ כָּל־הָ⁠אָ֔רֶץ כִּ֛י אֵ֥ין אִ֖ישׁ שָׂ֥ם עַל־לֵֽב׃","şá̂má⁠ḣ֙ li⁠şĕ̌mámá֔h ʼábĕlá֥h ʻála֖⁠y şĕ̌mémá֑h náşǎ֨má̇h֙ ká̇l-há⁠ʼá֔reẕ ki֛̇y ʼé֥yn ʼi֖yş̌ şá֥̂m ʻal-léֽb׃"],[12,12,"עַֽל־כָּל־שְׁפָיִ֣ם בַּ⁠מִּדְבָּ֗ר בָּ֚אוּ שֹֽׁדְדִ֔ים כִּ֣י חֶ֤רֶב לַֽ⁠יהוָה֙ אֹֽכְלָ֔ה מִ⁠קְצֵה־אֶ֖רֶץ וְ⁠עַד־קְצֵ֣ה הָ⁠אָ֑רֶץ אֵ֥ין שָׁל֖וֹם לְ⁠כָל־בָּשָֽׂר׃ס","ʻaֽl-ká̇l-şĕ̌páyi֣m bȧ⁠mi̇dĕbá̇֗r bá֚̇ʼẇ şòֽ̌dĕdi֔ym ki֣̇y ẖe֤reb laֽ⁠yhwáh֙ ʼòֽkĕlá֔h mi⁠qĕẕéh-ʼe֖reẕ wĕ⁠ʻad-qĕẕé֣h há⁠ʼá֑reẕ ʼé֥yn şá̌l֖wòm lĕ⁠kál-bá̇şáֽ̂r׃s"],[12,13,"זָרְע֤וּ חִטִּים֙ וְ⁠קֹצִ֣ים קָצָ֔רוּ נֶחְל֖וּ לֹ֣א יוֹעִ֑לוּ וּ⁠בֹ֨שׁוּ֙ מִ⁠תְּבוּאֹ֣תֵי⁠כֶ֔ם מֵ⁠חֲר֖וֹן אַף־יְהוָֽה׃ס","zárĕʻ֤ẇ ẖiti̇ym֙ wĕ⁠qòẕi֣ym qáẕá֔rẇ neẖĕl֖ẇ lò֣ʼ ywòʻi֑lẇ ẇ⁠bò֨ş̌ẇ֙ mi⁠ţĕ̇bẇʼò֣ţéy⁠ke֔m mé⁠ẖàr֖wòn ʼap-yĕhwáֽh׃s"],[12,14,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה עַל־כָּל־שְׁכֵנַ⁠י֙ הָֽ⁠רָעִ֔ים הַ⁠נֹּֽגְעִים֙ בַּֽ⁠נַּחֲלָ֔ה אֲשֶׁר־הִנְחַ֥לְתִּי אֶת־עַמִּ֖⁠י אֶת־יִשְׂרָאֵ֑ל הִנְ⁠נִ֤י נֹֽתְשָׁ⁠ם֙ מֵ⁠עַ֣ל אַדְמָתָ֔⁠ם וְ⁠אֶת־בֵּ֥ית יְהוּדָ֖ה אֶתּ֥וֹשׁ מִ⁠תּוֹכָֽ⁠ם׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʻal-ká̇l-şĕ̌kéna⁠y֙ háֽ⁠ráʻi֔ym ha⁠nòֽ̇gĕʻiym֙ bȧֽ⁠nȧẖàlá֔h ʼàşěr-hinĕẖa֥lĕţi̇y ʼeţ-ʻami֖̇⁠y ʼeţ-yişĕ̂ráʼé֑l hinĕ⁠ni֤y nòֽţĕşá̌⁠m֙ mé⁠ʻa֣l ʼadĕmáţá֔⁠m wĕ⁠ʼeţ-bé֥̇yţ yĕhẇdá֖h ʼeţ֥̇wòş̌ mi⁠ţ̇wòkáֽ⁠m׃"],[12,15,"וְ⁠הָיָ֗ה אַֽחֲרֵי֙ נָתְשִׁ֣⁠י אוֹתָ֔⁠ם אָשׁ֖וּב וְ⁠רִֽחַמְתִּ֑י⁠ם וַ⁠הֲשִׁבֹתִ֛י⁠ם אִ֥ישׁ לְ⁠נַחֲלָת֖⁠וֹ וְ⁠אִ֥ישׁ לְ⁠אַרְצֽ⁠וֹ׃","wĕ⁠háyá֗h ʼaֽẖàréy֙ náţĕşǐ֣⁠y ʼwòţá֔⁠m ʼáş֖̌ẇb wĕ⁠riֽẖamĕţi֑̇y⁠m wa⁠hàşǐbòţi֛y⁠m ʼi֥yş̌ lĕ⁠naẖàláţ֖⁠wò wĕ⁠ʼi֥yş̌ lĕ⁠ʼarĕẕֽ⁠wò׃"],[12,16,"וְ⁠הָיָ֡ה אִם־לָמֹ֣ד יִלְמְדוּ֩ אֶת־דַּֽרְכֵ֨י עַמִּ֜⁠י לְ⁠הִשָּׁבֵ֤עַ בִּ⁠שְׁמִ⁠י֙ חַי־יְהוָ֔ה כַּ⁠אֲשֶׁ֤ר לִמְּדוּ֙ אֶת־עַמִּ֔⁠י לְ⁠הִשָּׁבֵ֖עַ בַּ⁠בָּ֑עַל וְ⁠נִבְנ֖וּ בְּ⁠ת֥וֹךְ עַמִּֽ⁠י׃","wĕ⁠háyá֡h ʼim-lámò֣d yilĕmĕdẇ֩ ʼeţ-dȧֽrĕké֨y ʻami̇֜⁠y lĕ⁠hişá̇̌bé֤ʻa bi̇⁠şĕ̌mi⁠y֙ ẖay-yĕhwá֔h kȧ⁠ʼàşě֤r limĕ̇dẇ֙ ʼeţ-ʻami̇֔⁠y lĕ⁠hişá̇̌bé֖ʻa bȧ⁠bá֑̇ʻal wĕ⁠nibĕn֖ẇ bĕ̇⁠ţ֥wòkĕ ʻamiֽ̇⁠y׃"],[12,17,"וְ⁠אִ֖ם לֹ֣א יִשְׁמָ֑עוּ וְ⁠נָ֨תַשְׁתִּ֜י אֶת־הַ⁠גּ֥וֹי הַ⁠ה֛וּא נָת֥וֹשׁ וְ⁠אַבֵּ֖ד נְאֻם־יְהוָֽה׃ס","wĕ⁠ʼi֖m lò֣ʼ yişĕ̌má֑ʻẇ wĕ⁠ná֨ţaşĕ̌ţi̇֜y ʼeţ-ha⁠ġ֥wòy ha⁠h֛ẇʼ náţ֥wòş̌ wĕ⁠ʼabé֖̇d nĕʼum-yĕhwáֽh׃s"],[13,1,"כֹּֽה־אָמַ֨ר יְהוָ֜ה אֵלַ֗⁠י הָל֞וֹךְ וְ⁠קָנִ֤יתָ לְּ⁠ךָ֙ אֵז֣וֹר פִּשְׁתִּ֔ים וְ⁠שַׂמְתּ֖⁠וֹ עַל־מָתְנֶ֑י⁠ךָ וּ⁠בַ⁠מַּ֖יִם לֹ֥א תְבִאֵֽ⁠הוּ׃","kòֽ̇h-ʼáma֨r yĕhwá֜h ʼéla֗⁠y hál֞wòkĕ wĕ⁠qáni֤yţá lĕ̇⁠ká֙ ʼéz֣wòr pi̇şĕ̌ţi̇֔ym wĕ⁠şâmĕţ֖̇⁠wò ʻal-máţĕne֑y⁠ká ẇ⁠ba⁠mȧ֖yim lò֥ʼ ţĕbiʼéֽ⁠hẇ׃"],[13,2,"וָ⁠אֶקְנֶ֥ה אֶת־הָ⁠אֵז֖וֹר כִּ⁠דְבַ֣ר יְהוָ֑ה וָ⁠אָשִׂ֖ם עַל־מָתְנָֽ⁠י׃ס","wá⁠ʼeqĕne֥h ʼeţ-há⁠ʼéz֖wòr ki̇⁠dĕba֣r yĕhwá֑h wá⁠ʼáşî֖m ʻal-máţĕnáֽ⁠y׃s"],[13,3,"וַ⁠יְהִ֧י דְבַר־יְהוָ֛ה אֵלַ֖⁠י שֵׁנִ֥ית לֵ⁠אמֹֽר׃","wa⁠yĕhi֧y dĕbar-yĕhwá֛h ʼéla֖⁠y şé̌ni֥yţ lé⁠ʼmòֽr׃"],[13,4,"קַ֧ח אֶת־הָ⁠אֵז֛וֹר אֲשֶׁ֥ר קָנִ֖יתָ אֲשֶׁ֣ר עַל־מָתְנֶ֑י⁠ךָ וְ⁠קוּם֙ לֵ֣ךְ פְּרָ֔תָ⁠ה וְ⁠טָמְנֵ֥⁠הוּ שָׁ֖ם בִּ⁠נְקִ֥יק הַ⁠סָּֽלַע׃","qa֧ẖ ʼeţ-há⁠ʼéz֛wòr ʼàşě֥r qáni֖yţá ʼàşě֣r ʻal-máţĕne֑y⁠ká wĕ⁠qẇm֙ lé֣kĕ pĕ̇rá֔ţá⁠h wĕ⁠támĕné֥⁠hẇ şá֖̌m bi̇⁠nĕqi֥yq ha⁠sáֽ̇laʻ׃"],[13,5,"וָ⁠אֵלֵ֕ךְ וָ⁠אֶטְמְנֵ֖⁠הוּ בִּ⁠פְרָ֑ת כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אוֹתִֽ⁠י׃","wá⁠ʼélé֕kĕ wá⁠ʼetĕmĕné֖⁠hẇ bi̇⁠pĕrá֑ţ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼwòţiֽ⁠y׃"],[13,6,"וַ⁠יְהִ֕י מִ⁠קֵּ֖ץ יָמִ֣ים רַבִּ֑ים וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י ק֚וּם לֵ֣ךְ פְּרָ֔תָ⁠ה וְ⁠קַ֤ח מִ⁠שָּׁם֙ אֶת־הָ֣⁠אֵז֔וֹר אֲשֶׁ֥ר צִוִּיתִ֖י⁠ךָ לְ⁠טָמְנ⁠וֹ־שָֽׁם׃","wa⁠yĕhi֕y mi⁠qé֖̇ẕ yámi֣ym rabi֑̇ym wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y q֚ẇm lé֣kĕ pĕ̇rá֔ţá⁠h wĕ⁠qa֤ẖ mi⁠şá̇̌m֙ ʼeţ-há֣⁠ʼéz֔wòr ʼàşě֥r ẕiwi̇yţi֖y⁠ká lĕ⁠támĕn⁠wò-şáֽ̌m׃"],[13,7,"וָ⁠אֵלֵ֣ךְ פְּרָ֔תָ⁠ה וָ⁠אֶחְפֹּ֗ר וָֽ⁠אֶקַּח֙ אֶת־הָ֣⁠אֵז֔וֹר מִן־הַ⁠מָּק֖וֹם אֲשֶׁר־טְמַנְתִּ֣י⁠ו שָׁ֑מָּ⁠ה וְ⁠הִנֵּה֙ נִשְׁחַ֣ת הָ⁠אֵז֔וֹר לֹ֥א יִצְלַ֖ח לַ⁠כֹּֽל׃פ","wá⁠ʼélé֣kĕ pĕ̇rá֔ţá⁠h wá⁠ʼeẖĕpò̇֗r wáֽ⁠ʼeqȧẖ֙ ʼeţ-há֣⁠ʼéz֔wòr min-ha⁠má̇q֖wòm ʼàşěr-tĕmanĕţi֣̇y⁠w şá֑̌má̇⁠h wĕ⁠hiné̇h֙ nişĕ̌ẖa֣ţ há⁠ʼéz֔wòr lò֥ʼ yiẕĕla֖ẖ la⁠kòֽ̇l׃p"],[13,8,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[13,9,"כֹּ֖ה אָמַ֣ר יְהוָ֑ה כָּ֠כָה אַשְׁחִ֞ית אֶת־גְּא֧וֹן יְהוּדָ֛ה וְ⁠אֶת־גְּא֥וֹן יְרוּשָׁלִַ֖ם הָ⁠רָֽב׃","kò֖̇h ʼáma֣r yĕhwá֑h ká̇֠káh ʼaşĕ̌ẖi֞yţ ʼeţ-gĕ̇ʼ֧wòn yĕhẇdá֛h wĕ⁠ʼeţ-gĕ̇ʼ֥wòn yĕrẇşá̌lia֖m há⁠ráֽb׃"],[13,10,"הָ⁠עָם֩ הַ⁠זֶּ֨ה הָ⁠רָ֜ע הַֽ⁠מֵּאֲנִ֣ים ׀ לִ⁠שְׁמ֣וֹעַ אֶת־דְּבָרַ֗⁠י הַ⁠הֹֽלְכִים֙ בִּ⁠שְׁרִר֣וּת לִבָּ֔⁠ם וַ⁠יֵּלְכ֗וּ אַֽחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים לְ⁠עָבְדָ֖⁠ם וּ⁠לְ⁠הִשְׁתַּחֲוֺ֣ת לָ⁠הֶ֑ם וִ⁠יהִי֙ כָּ⁠אֵז֣וֹר הַ⁠זֶּ֔ה אֲשֶׁ֥ר לֹא־יִצְלַ֖ח לַ⁠כֹּֽל׃","há⁠ʻám֩ ha⁠zė֨h há⁠rá֜ʻ haֽ⁠mé̇ʼàni֣ym ׀ li⁠şĕ̌m֣wòʻa ʼeţ-dĕ̇bára֗⁠y ha⁠hòֽlĕkiym֙ bi̇⁠şĕ̌rir֣ẇţ libá̇֔⁠m wa⁠yé̇lĕk֗ẇ ʼaֽẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym lĕ⁠ʻábĕdá֖⁠m ẇ⁠lĕ⁠hişĕ̌ţȧẖàwֺ֣ţ lá⁠he֑m wi⁠yhiy֙ ká̇⁠ʼéz֣wòr ha⁠zė֔h ʼàşě֥r lòʼ-yiẕĕla֖ẖ la⁠kòֽ̇l׃"],[13,11,"כִּ֡י כַּ⁠אֲשֶׁר֩ יִדְבַּ֨ק הָ⁠אֵז֜וֹר אֶל־מָתְנֵי־אִ֗ישׁ כֵּ֣ן הִדְבַּ֣קְתִּי אֵ֠לַ⁠י אֶת־כָּל־בֵּ֨ית יִשְׂרָאֵ֜ל וְ⁠אֶת־כָּל־בֵּ֤ית יְהוּדָה֙ נְאֻם־יְהוָ֔ה לִֽ⁠הְי֥וֹת לִ⁠י֙ לְ⁠עָ֔ם וּ⁠לְ⁠שֵׁ֥ם וְ⁠לִ⁠תְהִלָּ֖ה וּ⁠לְ⁠תִפְאָ֑רֶת וְ⁠לֹ֖א שָׁמֵֽעוּ׃","ki̇֡y kȧ⁠ʼàşěr֩ yidĕbȧ֨q há⁠ʼéz֜wòr ʼel-máţĕnéy-ʼi֗yş̌ ké֣̇n hidĕbȧ֣qĕţi̇y ʼé֠la⁠y ʼeţ-ká̇l-bé̇֨yţ yişĕ̂ráʼé֜l wĕ⁠ʼeţ-ká̇l-bé֤̇yţ yĕhẇdáh֙ nĕʼum-yĕhwá֔h liֽ⁠hĕy֥wòţ li⁠y֙ lĕ⁠ʻá֔m ẇ⁠lĕ⁠şé֥̌m wĕ⁠li⁠ţĕhilá֖̇h ẇ⁠lĕ⁠ţipĕʼá֑reţ wĕ⁠lò֖ʼ şá̌méֽʻẇ׃"],[13,12,"וְ⁠אָמַרְתָּ֨ אֲלֵי⁠הֶ֜ם אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה ס כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כָּל־נֵ֖בֶל יִמָּ֣לֵא יָ֑יִן וְ⁠אָמְר֣וּ אֵלֶ֔י⁠ךָ הֲ⁠יָדֹ֨עַ֙ לֹ֣א נֵדַ֔ע כִּ֥י כָל־נֵ֖בֶל יִמָּ֥לֵא יָֽיִן׃","wĕ⁠ʼámarĕţá̇֨ ʼàléy⁠he֜m ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h s kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ká̇l-né֖bel yimá֣̇léʼ yá֑yin wĕ⁠ʼámĕr֣ẇ ʼéle֔y⁠ká hà⁠yádò֨ʻa֙ lò֣ʼ néda֔ʻ ki֥̇y kál-né֖bel yimá֥̇léʼ yáֽyin׃"],[13,13,"וְ⁠אָמַרְתָּ֨ אֲלֵי⁠הֶ֜ם כֹּֽה־אָמַ֣ר יְהוָ֗ה הִנְ⁠נִ֣י מְמַלֵּ֣א אֶת־כָּל־יֹשְׁבֵ֣י הָ⁠אָ֪רֶץ הַ⁠זֹּ֟את וְ⁠אֶת־הַ⁠מְּלָכִ֣ים הַ⁠יֹּשְׁבִים֩ לְ⁠דָוִ֨ד עַל־כִּסְא֜⁠וֹ וְ⁠אֶת־הַ⁠כֹּהֲנִ֣ים וְ⁠אֶת־הַ⁠נְּבִיאִ֗ים וְ⁠אֵ֛ת כָּל־יֹשְׁבֵ֥י יְרוּשָׁלִָ֖ם שִׁכָּרֽוֹן׃","wĕ⁠ʼámarĕţá̇֨ ʼàléy⁠he֜m kòֽ̇h-ʼáma֣r yĕhwá֗h hinĕ⁠ni֣y mĕmalé֣̇ʼ ʼeţ-ká̇l-yòşĕ̌bé֣y há⁠ʼá֪reẕ ha⁠zò̇֟ʼţ wĕ⁠ʼeţ-ha⁠mĕ̇láki֣ym ha⁠yò̇şĕ̌biym֩ lĕ⁠dáwi֨d ʻal-ki̇sĕʼ֜⁠wò wĕ⁠ʼeţ-ha⁠kò̇hàni֣ym wĕ⁠ʼeţ-ha⁠nĕ̇biyʼi֗ym wĕ⁠ʼé֛ţ ká̇l-yòşĕ̌bé֥y yĕrẇşá̌liá֖m şǐká̇rֽwòn׃"],[13,14,"וְ⁠נִפַּצְתִּי⁠ם֩ אִ֨ישׁ אֶל־אָחִ֜י⁠ו וְ⁠הָ⁠אָב֧וֹת וְ⁠הַ⁠בָּנִ֛ים יַחְדָּ֖ו נְאֻם־יְהוָ֑ה לֹֽא־אֶחְמ֧וֹל וְ⁠לֹֽא־אָח֛וּס וְ⁠לֹ֥א אֲרַחֵ֖ם מֵ⁠הַשְׁחִיתָֽ⁠ם׃ס","wĕ⁠nipȧẕĕţi̇y⁠m֩ ʼi֨yş̌ ʼel-ʼáẖi֜y⁠w wĕ⁠há⁠ʼáb֧wòţ wĕ⁠ha⁠bá̇ni֛ym yaẖĕdá֖̇w nĕʼum-yĕhwá֑h lòֽʼ-ʼeẖĕm֧wòl wĕ⁠lòֽʼ-ʼáẖ֛ẇs wĕ⁠lò֥ʼ ʼàraẖé֖m mé⁠haşĕ̌ẖiyţáֽ⁠m׃s"],[13,15,"שִׁמְע֥וּ וְ⁠הַאֲזִ֖ינוּ אַל־תִּגְבָּ֑הוּ כִּ֥י יְהוָ֖ה דִּבֵּֽר׃","şǐmĕʻ֥ẇ wĕ⁠haʼàzi֖ynẇ ʼal-ţi̇gĕbá֑̇hẇ ki֥̇y yĕhwá֖h di̇béֽ̇r׃"],[13,16,"תְּנוּ֩ לַ⁠יהוָ֨ה אֱלֹהֵי⁠כֶ֤ם כָּבוֹד֙ בְּ⁠טֶ֣רֶם יַחְשִׁ֔ךְ וּ⁠בְ⁠טֶ֛רֶם יִֽתְנַגְּפ֥וּ רַגְלֵי⁠כֶ֖ם עַל־הָ֣רֵי נָ֑שֶׁף וְ⁠קִוִּיתֶ֤ם לְ⁠אוֹר֙ וְ⁠שָׂמָ֣⁠הּ לְ⁠צַלְמָ֔וֶת ישית לַ⁠עֲרָפֶֽל׃","ţĕ̇nẇ֩ la⁠yhwá֨h ʼèlòhéy⁠ke֤m ká̇bwòd֙ bĕ̇⁠te֣rem yaẖĕşǐ֔kĕ ẇ⁠bĕ⁠te֛rem yiֽţĕnagĕ̇p֥ẇ ragĕléy⁠ke֖m ʻal-há֣réy ná֑şěp wĕ⁠qiwi̇yţe֤m lĕ⁠ʼwòr֙ wĕ⁠şá̂má֣⁠ḣ lĕ⁠ẕalĕmá֔weţ yşyţ la⁠ʻàrápeֽl׃"],[13,17,"וְ⁠אִם֙ לֹ֣א תִשְׁמָע֔וּ⁠הָ בְּ⁠מִסְתָּרִ֥ים תִּבְכֶּֽה־נַפְשִׁ֖⁠י מִ⁠פְּנֵ֣י גֵוָ֑ה וְ⁠דָמֹ֨עַ תִּדְמַ֜ע וְ⁠תֵרַ֤ד עֵינִ⁠י֙ דִּמְעָ֔ה כִּ֥י נִשְׁבָּ֖ה עֵ֥דֶר יְהוָֽה׃ס","wĕ⁠ʼim֙ lò֣ʼ ţişĕ̌máʻ֔ẇ⁠há bĕ̇⁠misĕţá̇ri֥ym ţi̇bĕkėֽh-napĕşǐ֖⁠y mi⁠pĕ̇né֣y géwá֑h wĕ⁠dámò֨ʻa ţi̇dĕma֜ʻ wĕ⁠ţéra֤d ʻéyni⁠y֙ di̇mĕʻá֔h ki֥̇y nişĕ̌bá֖̇h ʻé֥der yĕhwáֽh׃s"],[13,18,"אֱמֹ֥ר לַ⁠מֶּ֛לֶךְ וְ⁠לַ⁠גְּבִירָ֖ה הַשְׁפִּ֣ילוּ שֵׁ֑בוּ כִּ֤י יָרַד֙ מַרְאֲשׁ֣וֹתֵי⁠כֶ֔ם עֲטֶ֖רֶת תִּֽפְאַרְתְּ⁠כֶֽם׃","ʼèmò֥r la⁠mė֛lekĕ wĕ⁠la⁠gĕ̇biyrá֖h haşĕ̌pi֣̇ylẇ şé֑̌bẇ ki֤̇y yárad֙ marĕʼàş֣̌wòţéy⁠ke֔m ʻàte֖reţ ţiֽ̇pĕʼarĕţĕ̇⁠keֽm׃"],[13,19,"עָרֵ֥י הַ⁠נֶּ֛גֶב סֻגְּר֖וּ וְ⁠אֵ֣ין פֹּתֵ֑חַ הָגְלָ֧ת יְהוּדָ֛ה כֻּלָּ֖⁠הּ הָגְלָ֥ת שְׁלוֹמִֽים׃ס","ʻáré֥y ha⁠nė֛geb sugĕ̇r֖ẇ wĕ⁠ʼé֣yn pò̇ţé֑ẖa hágĕlá֧ţ yĕhẇdá֛h ku̇lá֖̇⁠ḣ hágĕlá֥ţ şĕ̌lwòmiֽym׃s"],[13,20,"שאי עֵֽינֵי⁠כֶם֙ ו⁠ראי הַ⁠בָּאִ֖ים מִ⁠צָּפ֑וֹן אַיֵּ֗ה הָ⁠עֵ֨דֶר֙ נִתַּן־לָ֔⁠ךְ צֹ֖אן תִּפְאַרְתֵּֽ⁠ךְ׃","şʼy ʻéֽynéy⁠kem֙ w⁠rʼy ha⁠bá̇ʼi֖ym mi⁠ẕá̇p֑wòn ʼayé̇֗h há⁠ʻé֨der֙ niţȧn-lá֔⁠kĕ ẕò֖ʼn ţi̇pĕʼarĕţéֽ̇⁠kĕ׃"],[13,21,"מַה־תֹּֽאמְרִי֙ כִּֽי־יִפְקֹ֣ד עָלַ֔יִ⁠ךְ וְ֠⁠אַתְּ לִמַּ֨דְתְּ אֹתָ֥⁠ם עָלַ֛יִ⁠ךְ אַלֻּפִ֖ים לְ⁠רֹ֑אשׁ הֲ⁠ל֤וֹא חֲבָלִים֙ יֹאחֱז֔וּ⁠ךְ כְּמ֖וֹ אֵ֥שֶׁת לֵדָֽה׃","mah-ţòֽ̇ʼmĕriy֙ kiֽ̇y-yipĕqò֣d ʻála֔yi⁠kĕ wĕ֠⁠ʼaţĕ̇ limȧ֨dĕţĕ̇ ʼòţá֥⁠m ʻála֛yi⁠kĕ ʼalu̇pi֖ym lĕ⁠rò֑ʼş̌ hà⁠l֤wòʼ ẖàbáliym֙ yòʼẖèz֔ẇ⁠kĕ kĕ̇m֖wò ʼé֥şěţ lédáֽh׃"],[13,22,"וְ⁠כִ֤י תֹאמְרִי֙ בִּ⁠לְבָבֵ֔⁠ךְ מַדּ֖וּעַ קְרָאֻ֣⁠נִי אֵ֑לֶּה בְּ⁠רֹ֧ב עֲוֺנֵ֛⁠ךְ נִגְל֥וּ שׁוּלַ֖יִ⁠ךְ נֶחְמְס֥וּ עֲקֵבָֽיִ⁠ךְ׃","wĕ⁠ki֤y ţòʼmĕriy֙ bi̇⁠lĕbábé֔⁠kĕ maḋ֖ẇʻa qĕráʼu֣⁠niy ʼé֑lėh bĕ̇⁠rò֧b ʻàwֺné֛⁠kĕ nigĕl֥ẇ ş̌ẇla֖yi⁠kĕ neẖĕmĕs֥ẇ ʻàqébáֽyi⁠kĕ׃"],[13,23,"הֲ⁠יַהֲפֹ֤ךְ כּוּשִׁי֙ עוֹר֔⁠וֹ וְ⁠נָמֵ֖ר חֲבַרְבֻּרֹתָ֑י⁠ו גַּם־אַתֶּם֙ תּוּכְל֣וּ לְ⁠הֵיטִ֔יב לִמֻּדֵ֖י הָרֵֽעַ׃","hà⁠yahàpò֤kĕ k̇ẇşǐy֙ ʻwòr֔⁠wò wĕ⁠námé֖r ẖàbarĕbu̇ròţá֑y⁠w gȧm-ʼaţėm֙ ţ̇ẇkĕl֣ẇ lĕ⁠héyti֔yb limu̇dé֖y háréֽʻa׃"],[13,24,"וַ⁠אֲפִיצֵ֖⁠ם כְּ⁠קַשׁ־עוֹבֵ֑ר לְ⁠ר֖וּחַ מִדְבָּֽר׃","wa⁠ʼàpiyẕé֖⁠m kĕ̇⁠qaş̌-ʻwòbé֑r lĕ⁠r֖ẇẖa midĕbáֽ̇r׃"],[13,25,"זֶ֣ה גוֹרָלֵ֧⁠ךְ מְנָת־מִדַּ֛יִ⁠ךְ מֵֽ⁠אִתִּ֖⁠י נְאֻם־יְהוָ֑ה אֲשֶׁר֙ שָׁכַ֣חַתְּ אוֹתִ֔⁠י וַֽ⁠תִּבְטְחִ֖י בַּ⁠שָּֽׁקֶר׃","ze֣h gwòrálé֧⁠kĕ mĕnáţ-midȧ֛yi⁠kĕ méֽ⁠ʼiţi֖̇⁠y nĕʼum-yĕhwá֑h ʼàşěr֙ şá̌ka֣ẖaţĕ̇ ʼwòţi֔⁠y waֽ⁠ţi̇bĕtĕẖi֖y bȧ⁠şáֽ̇̌qer׃"],[13,26,"וְ⁠גַם־אֲנִ֛י חָשַׂ֥פְתִּי שׁוּלַ֖יִ⁠ךְ עַל־פָּנָ֑יִ⁠ךְ וְ⁠נִרְאָ֖ה קְלוֹנֵֽ⁠ךְ׃","wĕ⁠gam-ʼàni֛y ẖáşâ֥pĕţi̇y ş̌ẇla֖yi⁠kĕ ʻal-pá̇ná֑yi⁠kĕ wĕ⁠nirĕʼá֖h qĕlwònéֽ⁠kĕ׃"],[13,27,"נִֽאֻפַ֤יִ⁠ךְ וּ⁠מִצְהֲלוֹתַ֨יִ⁠ךְ֙ זִמַּ֣ת זְנוּתֵ֔⁠ךְ עַל־גְּבָעוֹת֙ בַּ⁠שָּׂדֶ֔ה רָאִ֖יתִי שִׁקּוּצָ֑יִ⁠ךְ א֥וֹי לָ⁠ךְ֙ יְר֣וּשָׁלִַ֔ם לֹ֣א תִטְהֲרִ֔י אַחֲרֵ֥י מָתַ֖י עֹֽד׃פ","niֽʼupa֤yi⁠kĕ ẇ⁠miẕĕhàlwòţa֨yi⁠kĕ֙ zimȧ֣ţ zĕnẇţé֔⁠kĕ ʻal-gĕ̇báʻwòţ֙ bȧ⁠şá̇̂de֔h ráʼi֖yţiy şǐq̇ẇẕá֑yi⁠kĕ ʼ֥wòy lá⁠kĕ֙ yĕr֣ẇşá̌lia֔m lò֣ʼ ţitĕhàri֔y ʼaẖàré֥y máţa֖y ʻòֽd׃p"],[14,1,"אֲשֶׁ֨ר הָיָ֤ה דְבַר־יְהוָה֙ אֶֽל־יִרְמְיָ֔הוּ עַל־דִּבְרֵ֖י הַ⁠בַּצָּרֽוֹת׃","ʼàşě֨r háyá֤h dĕbar-yĕhwáh֙ ʼeֽl-yirĕmĕyá֔hẇ ʻal-di̇bĕré֖y ha⁠bȧẕá̇rֽwòţ׃"],[14,2,"אָבְלָ֣ה יְהוּדָ֔ה וּ⁠שְׁעָרֶ֥י⁠הָ אֻמְלְל֖וּ קָדְר֣וּ לָ⁠אָ֑רֶץ וְ⁠צִוְחַ֥ת יְרוּשָׁלִַ֖ם עָלָֽתָה׃","ʼábĕlá֣h yĕhẇdá֔h ẇ⁠şĕ̌ʻáre֥y⁠há ʼumĕlĕl֖ẇ qádĕr֣ẇ lá⁠ʼá֑reẕ wĕ⁠ẕiwĕẖa֥ţ yĕrẇşá̌lia֖m ʻáláֽţáh׃"],[14,3,"וְ⁠אַדִּ֣רֵי⁠הֶ֔ם שָׁלְח֥וּ צעורי⁠הם לַ⁠מָּ֑יִם בָּ֣אוּ עַל־גֵּבִ֞ים לֹא־מָ֣צְאוּ מַ֗יִם שָׁ֤בוּ כְלֵי⁠הֶם֙ רֵיקָ֔ם בֹּ֥שׁוּ וְ⁠הָכְלְמ֖וּ וְ⁠חָפ֥וּ רֹאשָֽׁ⁠ם׃","wĕ⁠ʼadi֣̇réy⁠he֔m şá̌lĕẖ֥ẇ ẕʻwry⁠hm la⁠má֑̇yim bá֣̇ʼẇ ʻal-gé̇bi֞ym lòʼ-má֣ẕĕʼẇ ma֗yim şá֤̌bẇ kĕléy⁠hem֙ réyqá֔m bò֥̇ş̌ẇ wĕ⁠hákĕlĕm֖ẇ wĕ⁠ẖáp֥ẇ ròʼşáֽ̌⁠m׃"],[14,4,"בַּ⁠עֲב֤וּר הָ⁠אֲדָמָה֙ חַ֔תָּה כִּ֛י לֹא־הָיָ֥ה גֶ֖שֶׁם בָּ⁠אָ֑רֶץ בֹּ֥שׁוּ אִכָּרִ֖ים חָפ֥וּ רֹאשָֽׁ⁠ם׃","bȧ⁠ʻàb֤ẇr há⁠ʼàdámáh֙ ẖa֔ţá̇h ki֛̇y lòʼ-háyá֥h ge֖şěm bá̇⁠ʼá֑reẕ bò֥̇ş̌ẇ ʼiká̇ri֖ym ẖáp֥ẇ ròʼşáֽ̌⁠m׃"],[14,5,"כִּ֤י גַם־אַיֶּ֨לֶת֙ בַּ⁠שָּׂדֶ֔ה יָלְדָ֖ה וְ⁠עָז֑וֹב כִּ֥י לֹֽא־הָיָ֖ה דֶּֽשֶׁא׃","ki֤̇y gam-ʼayė֨leţ֙ bȧ⁠şá̇̂de֔h yálĕdá֖h wĕ⁠ʻáz֑wòb ki֥̇y lòֽʼ-háyá֖h dėֽşěʼ׃"],[14,6,"וּ⁠פְרָאִים֙ עָמְד֣וּ עַל־שְׁפָיִ֔ם שָׁאֲפ֥וּ ר֖וּחַ כַּ⁠תַּנִּ֑ים כָּל֥וּ עֵינֵי⁠הֶ֖ם כִּי־אֵ֥ין עֵֽשֶׂב׃","ẇ⁠pĕráʼiym֙ ʻámĕd֣ẇ ʻal-şĕ̌páyi֔m şá̌ʼàp֥ẇ r֖ẇẖa kȧ⁠ţȧni֑̇ym ká̇l֥ẇ ʻéynéy⁠he֖m ki̇y-ʼé֥yn ʻéֽşêb׃"],[14,7,"אִם־עֲוֺנֵ֨י⁠נוּ֙ עָ֣נוּ בָ֔⁠נוּ יְהוָ֕ה עֲשֵׂ֖ה לְמַ֣עַן שְׁמֶ֑⁠ךָ כִּֽי־רַבּ֥וּ מְשׁוּבֹתֵ֖י⁠נוּ לְ⁠ךָ֥ חָטָֽאנוּ׃","ʼim-ʻàwֺné֨y⁠nẇ֙ ʻá֣nẇ bá֔⁠nẇ yĕhwá֕h ʻàşé֖̂h lĕma֣ʻan şĕ̌me֑⁠ká kiֽ̇y-raḃ֥ẇ mĕş̌ẇbòţé֖y⁠nẇ lĕ⁠ká֥ ẖátáֽʼnẇ׃"],[14,8,"מִקְוֵה֙ יִשְׂרָאֵ֔ל מֽוֹשִׁיע֖⁠וֹ בְּ⁠עֵ֣ת צָרָ֑ה לָ֤⁠מָּה תִֽהְיֶה֙ כְּ⁠גֵ֣ר בָּ⁠אָ֔רֶץ וּ⁠כְ⁠אֹרֵ֖חַ נָטָ֥ה לָ⁠לֽוּן׃","miqĕwéh֙ yişĕ̂ráʼé֔l mֽwòşǐyʻ֖⁠wò bĕ̇⁠ʻé֣ţ ẕárá֑h lá֤⁠má̇h ţiֽhĕyeh֙ kĕ̇⁠gé֣r bá̇⁠ʼá֔reẕ ẇ⁠kĕ⁠ʼòré֖ẖa nátá֥h lá⁠lֽẇn׃"],[14,9,"לָ֤⁠מָּה תִֽהְיֶה֙ כְּ⁠אִ֣ישׁ נִדְהָ֔ם כְּ⁠גִבּ֖וֹר לֹא־יוּכַ֣ל לְ⁠הוֹשִׁ֑יעַ וְ⁠אַתָּ֧ה בְ⁠קִרְבֵּ֣⁠נוּ יְהוָ֗ה וְ⁠שִׁמְ⁠ךָ֛ עָלֵ֥י⁠נוּ נִקְרָ֖א אַל־תַּנִּחֵֽ⁠נוּ׃ס","lá֤⁠má̇h ţiֽhĕyeh֙ kĕ̇⁠ʼi֣yş̌ nidĕhá֔m kĕ̇⁠giḃ֖wòr lòʼ-yẇka֣l lĕ⁠hwòşǐ֑yʻa wĕ⁠ʼaţá֧̇h bĕ⁠qirĕbé֣̇⁠nẇ yĕhwá֗h wĕ⁠şǐmĕ⁠ká֛ ʻálé֥y⁠nẇ niqĕrá֖ʼ ʼal-ţȧni̇ẖéֽ⁠nẇ׃s"],[14,10,"כֹּֽה־אָמַ֨ר יְהוָ֜ה לָ⁠עָ֣ם הַ⁠זֶּ֗ה כֵּ֤ן אָֽהֲבוּ֙ לָ⁠נ֔וּעַ רַגְלֵי⁠הֶ֖ם לֹ֣א חָשָׂ֑כוּ וַ⁠יהוָה֙ לֹ֣א רָצָ֔⁠ם עַתָּה֙ יִזְכֹּ֣ר עֲוֺנָ֔⁠ם וְ⁠יִפְקֹ֖ד חַטֹּאתָֽ⁠ם׃ס","kòֽ̇h-ʼáma֨r yĕhwá֜h lá⁠ʻá֣m ha⁠zė֗h ké֤̇n ʼáֽhàbẇ֙ lá⁠n֔ẇʻa ragĕléy⁠he֖m lò֣ʼ ẖáşá֑̂kẇ wa⁠yhwáh֙ lò֣ʼ ráẕá֔⁠m ʻaţá̇h֙ yizĕkò֣̇r ʻàwֺná֔⁠m wĕ⁠yipĕqò֖d ẖatò̇ʼţáֽ⁠m׃s"],[14,11,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י אַל־תִּתְפַּלֵּ֛ל בְּעַד־הָ⁠עָ֥ם הַ⁠זֶּ֖ה לְ⁠טוֹבָֽה׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y ʼal-ţi̇ţĕpȧlé֛̇l bĕ̇ʻad-há⁠ʻá֥m ha⁠zė֖h lĕ⁠twòbáֽh׃"],[14,12,"כִּ֣י יָצֻ֗מוּ אֵינֶ֤⁠נִּי שֹׁמֵ֨עַ֙ אֶל־רִנָּתָ֔⁠ם וְ⁠כִ֧י יַעֲל֛וּ עֹלָ֥ה וּ⁠מִנְחָ֖ה אֵינֶ֣⁠נִּי רֹצָ֑⁠ם כִּ֗י בַּ⁠חֶ֨רֶב֙ וּ⁠בָ⁠רָעָ֣ב וּ⁠בַ⁠דֶּ֔בֶר אָנֹכִ֖י מְכַלֶּ֥ה אוֹתָֽ⁠ם׃ס","ki֣̇y yáẕu֗mẇ ʼéyne֤⁠ni̇y şò̌mé֨ʻa֙ ʼel-riná̇ţá֔⁠m wĕ⁠ki֧y yaʻàl֛ẇ ʻòlá֥h ẇ⁠minĕẖá֖h ʼéyne֣⁠ni̇y ròẕá֑⁠m ki̇֗y bȧ⁠ẖe֨reb֙ ẇ⁠bá⁠ráʻá֣b ẇ⁠ba⁠dė֔ber ʼánòki֖y mĕkalė֥h ʼwòţáֽ⁠m׃s"],[14,13,"וָ⁠אֹמַ֞ר אֲהָ֣הּ ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הִנֵּ֨ה הַ⁠נְּבִאִ֜ים אֹמְרִ֤ים לָ⁠הֶם֙ לֹֽא־תִרְא֣וּ חֶ֔רֶב וְ⁠רָעָ֖ב לֹֽא־יִהְיֶ֣ה לָ⁠כֶ֑ם כִּֽי־שְׁל֤וֹם אֱמֶת֙ אֶתֵּ֣ן לָ⁠כֶ֔ם בַּ⁠מָּק֖וֹם הַ⁠זֶּֽה׃ס","wá⁠ʼòma֞r ʼàhá֣ḣ ׀ ʼàdòná֣⁠y yĕhwi֗h hiné̇֨h ha⁠nĕ̇biʼi֜ym ʼòmĕri֤ym lá⁠hem֙ lòֽʼ-ţirĕʼ֣ẇ ẖe֔reb wĕ⁠ráʻá֖b lòֽʼ-yihĕye֣h lá⁠ke֑m kiֽ̇y-şĕ̌l֤wòm ʼèmeţ֙ ʼeţé֣̇n lá⁠ke֔m bȧ⁠má̇q֖wòm ha⁠zėֽh׃s"],[14,14,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י שֶׁ֚קֶר הַ⁠נְּבִאִים֙ נִבְּאִ֣ים בִּ⁠שְׁמִ֔⁠י לֹ֤א שְׁלַחְתִּי⁠ם֙ וְ⁠לֹ֣א צִוִּיתִ֔י⁠ם וְ⁠לֹ֥א דִבַּ֖רְתִּי אֲלֵי⁠הֶ֑ם חֲז֨וֹן שֶׁ֜קֶר וְ⁠קֶ֤סֶם ו⁠אלול ו⁠תרמות לִבָּ֔⁠ם הֵ֖מָּה מִֽתְנַבְּאִ֥ים לָ⁠כֶֽם׃ס","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y şě֚qer ha⁠nĕ̇biʼiym֙ nibĕ̇ʼi֣ym bi̇⁠şĕ̌mi֔⁠y lò֤ʼ şĕ̌laẖĕţi̇y⁠m֙ wĕ⁠lò֣ʼ ẕiwi̇yţi֔y⁠m wĕ⁠lò֥ʼ dibȧ֖rĕţi̇y ʼàléy⁠he֑m ẖàz֨wòn şě֜qer wĕ⁠qe֤sem w⁠ʼlwl w⁠ţrmwţ libá̇֔⁠m hé֖má̇h miֽţĕnabĕ̇ʼi֥ym lá⁠keֽm׃s"],[14,15,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה עַֽל־הַ⁠נְּבִאִ֞ים הַ⁠נִּבְּאִ֣ים בִּ⁠שְׁמִ⁠י֮ וַ⁠אֲנִ֣י לֹֽא־שְׁלַחְתִּי⁠ם֒ וְ⁠הֵ֨מָּה֙ אֹֽמְרִ֔ים חֶ֣רֶב וְ⁠רָעָ֔ב לֹ֥א יִהְיֶ֖ה בָּ⁠אָ֣רֶץ הַ⁠זֹּ֑את בַּ⁠חֶ֤רֶב וּ⁠בָֽ⁠רָעָב֙ יִתַּ֔מּוּ הַ⁠נְּבִאִ֖ים הָ⁠הֵֽמָּה׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h ʻaֽl-ha⁠nĕ̇biʼi֞ym ha⁠ni̇bĕ̇ʼi֣ym bi̇⁠şĕ̌mi⁠y֮ wa⁠ʼàni֣y lòֽʼ-şĕ̌laẖĕţi̇y⁠m֒ wĕ⁠hé֨má̇h֙ ʼòֽmĕri֔ym ẖe֣reb wĕ⁠ráʻá֔b lò֥ʼ yihĕye֖h bá̇⁠ʼá֣reẕ ha⁠zò֑̇ʼţ bȧ⁠ẖe֤reb ẇ⁠báֽ⁠ráʻáb֙ yiţȧ֔ṁẇ ha⁠nĕ̇biʼi֖ym há⁠héֽmá̇h׃"],[14,16,"וְ⁠הָ⁠עָ֣ם אֲשֶׁר־הֵ֣מָּה נִבְּאִ֣ים לָ⁠הֶ֡ם יִֽהְי֣וּ מֻשְׁלָכִים֩ בְּ⁠חֻצ֨וֹת יְרוּשָׁלִַ֜ם מִ⁠פְּנֵ֣י ׀ הָ⁠רָעָ֣ב וְ⁠הַ⁠חֶ֗רֶב וְ⁠אֵ֤ין מְקַבֵּר֙ לָ⁠הֵ֔מָּה הֵ֣מָּה נְשֵׁי⁠הֶ֔ם וּ⁠בְנֵי⁠הֶ֖ם וּ⁠בְנֹֽתֵי⁠הֶ֑ם וְ⁠שָׁפַכְתִּ֥י עֲלֵי⁠הֶ֖ם אֶת־רָעָתָֽ⁠ם׃","wĕ⁠há⁠ʻá֣m ʼàşěr-hé֣má̇h nibĕ̇ʼi֣ym lá⁠he֡m yiֽhĕy֣ẇ muşĕ̌lákiym֩ bĕ̇⁠ẖuẕ֨wòţ yĕrẇşá̌lia֜m mi⁠pĕ̇né֣y ׀ há⁠ráʻá֣b wĕ⁠ha⁠ẖe֗reb wĕ⁠ʼé֤yn mĕqabé̇r֙ lá⁠hé֔má̇h hé֣má̇h nĕşé̌y⁠he֔m ẇ⁠bĕnéy⁠he֖m ẇ⁠bĕnòֽţéy⁠he֑m wĕ⁠şá̌pakĕţi֥̇y ʻàléy⁠he֖m ʼeţ-ráʻáţáֽ⁠m׃"],[14,17,"וְ⁠אָמַרְתָּ֤ אֲלֵי⁠הֶם֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה תֵּרַ֨דְנָה עֵינַ֥⁠י דִּמְעָ֛ה לַ֥יְלָה וְ⁠יוֹמָ֖ם וְ⁠אַל־תִּדְמֶ֑ינָה כִּי֩ שֶׁ֨בֶר גָּד֜וֹל נִשְׁבְּרָ֗ה בְּתוּלַת֙ בַּת־עַמִּ֔⁠י מַכָּ֖ה נַחְלָ֥ה מְאֹֽד׃","wĕ⁠ʼámarĕţá֤̇ ʼàléy⁠hem֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h ţé̇ra֨dĕnáh ʻéyna֥⁠y di̇mĕʻá֛h la֥yĕláh wĕ⁠ywòmá֖m wĕ⁠ʼal-ţi̇dĕme֑ynáh ki̇y֩ şě֨ber gá̇d֜wòl nişĕ̌bĕ̇rá֗h bĕ̇ţẇlaţ֙ bȧţ-ʻami̇֔⁠y maká֖̇h naẖĕlá֥h mĕʼòֽd׃"],[14,18,"אִם־יָצָ֣אתִי הַ⁠שָּׂדֶ֗ה וְ⁠הִנֵּה֙ חַלְלֵי־חֶ֔רֶב וְ⁠אִם֙ בָּ֣אתִי הָ⁠עִ֔יר וְ⁠הִנֵּ֖ה תַּחֲלוּאֵ֣י רָעָ֑ב כִּֽי־גַם־נָבִ֧יא גַם־כֹּהֵ֛ן סָחֲר֥וּ אֶל־אֶ֖רֶץ וְ⁠לֹ֥א יָדָֽעוּ׃ס","ʼim-yáẕá֣ʼţiy ha⁠şá̇̂de֗h wĕ⁠hiné̇h֙ ẖalĕléy-ẖe֔reb wĕ⁠ʼim֙ bá֣̇ʼţiy há⁠ʻi֔yr wĕ⁠hiné֖̇h ţȧẖàlẇʼé֣y ráʻá֑b kiֽ̇y-gam-nábi֧yʼ gam-kò̇hé֛n sáẖàr֥ẇ ʼel-ʼe֖reẕ wĕ⁠lò֥ʼ yádáֽʻẇ׃s"],[14,19,"הֲ⁠מָאֹ֨ס מָאַ֜סְתָּ אֶת־יְהוּדָ֗ה אִם־בְּ⁠צִיּוֹן֙ גָּעֲלָ֣ה נַפְשֶׁ֔⁠ךָ מַדּ֨וּעַ֙ הִכִּיתָ֔⁠נוּ וְ⁠אֵ֥ין לָ֖⁠נוּ מַרְפֵּ֑א קַוֵּ֤ה לְ⁠שָׁלוֹם֙ וְ⁠אֵ֣ין ט֔וֹב וּ⁠לְ⁠עֵ֥ת מַרְפֵּ֖א וְ⁠הִנֵּ֥ה בְעָתָֽה׃","hà⁠máʼò֨s máʼa֜sĕţá̇ ʼeţ-yĕhẇdá֗h ʼim-bĕ̇⁠ẕiẏwòn֙ gá̇ʻàlá֣h napĕşě֔⁠ká maḋ֨ẇʻa֙ hiki̇yţá֔⁠nẇ wĕ⁠ʼé֥yn lá֖⁠nẇ marĕpé֑̇ʼ qawé֤̇h lĕ⁠şá̌lwòm֙ wĕ⁠ʼé֣yn t֔wòb ẇ⁠lĕ⁠ʻé֥ţ marĕpé֖̇ʼ wĕ⁠hiné֥̇h bĕʻáţáֽh׃"],[14,20,"יָדַ֧עְנוּ יְהוָ֛ה רִשְׁעֵ֖⁠נוּ עֲוֺ֣ן אֲבוֹתֵ֑י⁠נוּ כִּ֥י חָטָ֖אנוּ לָֽ⁠ךְ׃","yáda֧ʻĕnẇ yĕhwá֛h rişĕ̌ʻé֖⁠nẇ ʻàwֺ֣n ʼàbwòţé֑y⁠nẇ ki֥̇y ẖátá֖ʼnẇ láֽ⁠kĕ׃"],[14,21,"אַל־תִּנְאַץ֙ לְמַ֣עַן שִׁמְ⁠ךָ֔ אַל־תְּנַבֵּ֖ל כִּסֵּ֣א כְבוֹדֶ֑⁠ךָ זְכֹ֕ר אַל־תָּפֵ֥ר בְּרִֽיתְ⁠ךָ֖ אִתָּֽ⁠נוּ׃","ʼal-ţi̇nĕʼaẕ֙ lĕma֣ʻan şǐmĕ⁠ká֔ ʼal-ţĕ̇nabé֖̇l ki̇sé֣̇ʼ kĕbwòde֑⁠ká zĕkò֕r ʼal-ţá̇pé֥r bĕ̇riֽyţĕ⁠ká֖ ʼiţáֽ̇⁠nẇ׃"],[14,22,"הֲ⁠יֵ֨שׁ בְּ⁠הַבְלֵ֤י הַ⁠גּוֹיִם֙ מַגְשִׁמִ֔ים וְ⁠אִם־הַ⁠שָּׁמַ֖יִם יִתְּנ֣וּ רְבִבִ֑ים הֲ⁠לֹ֨א אַתָּה־ה֜וּא יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ וּ֨⁠נְקַוֶּה־לָּ֔⁠ךְ כִּֽי־אַתָּ֥ה עָשִׂ֖יתָ אֶת־כָּל־אֵֽלֶּה׃פ","hà⁠yé֨ş̌ bĕ̇⁠habĕlé֤y ha⁠ġwòyim֙ magĕşǐmi֔ym wĕ⁠ʼim-ha⁠şá̇̌ma֖yim yiţĕ̇n֣ẇ rĕbibi֑ym hà⁠lò֨ʼ ʼaţá̇h-h֜ẇʼ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ ẇ֨⁠nĕqawėh-lá̇֔⁠kĕ kiֽ̇y-ʼaţá֥̇h ʻáşî֖yţá ʼeţ-ká̇l-ʼéֽlėh׃p"],[15,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י אִם־יַעֲמֹ֨ד מֹשֶׁ֤ה וּ⁠שְׁמוּאֵל֙ לְ⁠פָנַ֔⁠י אֵ֥ין נַפְשִׁ֖⁠י אֶל־הָ⁠עָ֣ם הַ⁠זֶּ֑ה שַׁלַּ֥ח מֵֽ⁠עַל־פָּנַ֖⁠י וְ⁠יֵצֵֽאוּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y ʼim-yaʻàmò֨d mòşě֤h ẇ⁠şĕ̌mẇʼél֙ lĕ⁠pána֔⁠y ʼé֥yn napĕşǐ֖⁠y ʼel-há⁠ʻá֣m ha⁠zė֑h şǎlȧ֥ẖ méֽ⁠ʻal-pá̇na֖⁠y wĕ⁠yéẕéֽʼẇ׃"],[15,2,"וְ⁠הָיָ֛ה כִּֽי־יֹאמְר֥וּ אֵלֶ֖י⁠ךָ אָ֣נָה נֵצֵ֑א וְ⁠אָמַרְתָּ֨ אֲלֵי⁠הֶ֜ם כֹּֽה־אָמַ֣ר יְהוָ֗ה אֲשֶׁ֨ר לַ⁠מָּ֤וֶת לַ⁠מָּ֨וֶת֙ וַ⁠אֲשֶׁ֤ר לַ⁠חֶ֨רֶב֙ לַ⁠חֶ֔רֶב וַ⁠אֲשֶׁ֤ר לָֽ⁠רָעָב֙ לָֽ⁠רָעָ֔ב וַ⁠אֲשֶׁ֥ר לַ⁠שְּׁבִ֖י לַ⁠שֶּֽׁבִי׃","wĕ⁠háyá֛h kiֽ̇y-yòʼmĕr֥ẇ ʼéle֖y⁠ká ʼá֣náh néẕé֑ʼ wĕ⁠ʼámarĕţá̇֨ ʼàléy⁠he֜m kòֽ̇h-ʼáma֣r yĕhwá֗h ʼàşě֨r la⁠má֤̇weţ la⁠má̇֨weţ֙ wa⁠ʼàşě֤r la⁠ẖe֨reb֙ la⁠ẖe֔reb wa⁠ʼàşě֤r láֽ⁠ráʻáb֙ láֽ⁠ráʻá֔b wa⁠ʼàşě֥r la⁠şĕ̇̌bi֖y la⁠şėֽ̌biy׃"],[15,3,"וּ⁠פָקַדְתִּ֨י עֲלֵי⁠הֶ֜ם אַרְבַּ֤ע מִשְׁפָּחוֹת֙ נְאֻם־יְהוָ֔ה אֶת־הַ⁠חֶ֣רֶב לַֽ⁠הֲרֹ֔ג וְ⁠אֶת־הַ⁠כְּלָבִ֖ים לִ⁠סְחֹ֑ב וְ⁠אֶת־ע֧וֹף הַ⁠שָּׁמַ֛יִם וְ⁠אֶת־בֶּהֱמַ֥ת הָ⁠אָ֖רֶץ לֶ⁠אֱכֹ֥ל וּ⁠לְ⁠הַשְׁחִֽית׃","ẇ⁠páqadĕţi̇֨y ʻàléy⁠he֜m ʼarĕbȧ֤ʻ mişĕ̌pá̇ẖwòţ֙ nĕʼum-yĕhwá֔h ʼeţ-ha⁠ẖe֣reb laֽ⁠hàrò֔g wĕ⁠ʼeţ-ha⁠kĕ̇lábi֖ym li⁠sĕẖò֑b wĕ⁠ʼeţ-ʻ֧wòp ha⁠şá̇̌ma֛yim wĕ⁠ʼeţ-bėhèma֥ţ há⁠ʼá֖reẕ le⁠ʼèkò֥l ẇ⁠lĕ⁠haşĕ̌ẖiֽyţ׃"],[15,4,"וּ⁠נְתַתִּ֣י⁠ם ל⁠זועה לְ⁠כֹ֖ל מַמְלְכ֣וֹת הָ⁠אָ֑רֶץ בִּ֠⁠גְלַל מְנַשֶּׁ֤ה בֶן־יְחִזְקִיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה עַ֥ל אֲשֶׁר־עָשָׂ֖ה בִּ⁠ירוּשָׁלִָֽם׃","ẇ⁠nĕţaţi֣̇y⁠m l⁠zwʻh lĕ⁠kò֖l mamĕlĕk֣wòţ há⁠ʼá֑reẕ bi̇֠⁠gĕlal mĕnaşė֤̌h ben-yĕẖizĕqiyá̇֨hẇ֙ me֣lekĕ yĕhẇdá֔h ʻa֥l ʼàşěr-ʻáşá֖̂h bi̇⁠yrẇşá̌liáֽm׃"],[15,5,"כִּ֠י מִֽי־יַחְמֹ֤ל עָלַ֨יִ⁠ךְ֙ יְר֣וּשָׁלִַ֔ם וּ⁠מִ֖י יָנ֣וּד לָ֑⁠ךְ וּ⁠מִ֣י יָס֔וּר לִ⁠שְׁאֹ֥ל לְ⁠שָׁלֹ֖ם לָֽ⁠ךְ׃","ki̇֠y miֽy-yaẖĕmò֤l ʻála֨yi⁠kĕ֙ yĕr֣ẇşá̌lia֔m ẇ⁠mi֖y yán֣ẇd lá֑⁠kĕ ẇ⁠mi֣y yás֔ẇr li⁠şĕ̌ʼò֥l lĕ⁠şá̌lò֖m láֽ⁠kĕ׃"],[15,6,"אַ֣תְּ נָטַ֥שְׁתְּ אֹתִ֛⁠י נְאֻם־יְהוָ֖ה אָח֣וֹר תֵּלֵ֑כִי וָ⁠אַ֨ט אֶת־יָדִ֤⁠י עָלַ֨יִ⁠ךְ֙ וָֽ⁠אַשְׁחִיתֵ֔⁠ךְ נִלְאֵ֖יתִי הִנָּחֵֽם׃","ʼa֣ţĕ̇ náta֥şĕ̌ţĕ̇ ʼòţi֛⁠y nĕʼum-yĕhwá֖h ʼáẖ֣wòr ţé̇lé֑kiy wá⁠ʼa֨t ʼeţ-yádi֤⁠y ʻála֨yi⁠kĕ֙ wáֽ⁠ʼaşĕ̌ẖiyţé֔⁠kĕ nilĕʼé֖yţiy hiná̇ẖéֽm׃"],[15,7,"וָ⁠אֶזְרֵ֥⁠ם בְּ⁠מִזְרֶ֖ה בְּ⁠שַׁעֲרֵ֣י הָ⁠אָ֑רֶץ שִׁכַּ֤לְתִּי אִבַּ֨דְתִּי֙ אֶת־עַמִּ֔⁠י מִ⁠דַּרְכֵי⁠הֶ֖ם לוֹא־שָֽׁבוּ׃","wá⁠ʼezĕré֥⁠m bĕ̇⁠mizĕre֖h bĕ̇⁠şǎʻàré֣y há⁠ʼá֑reẕ şǐkȧ֤lĕţi̇y ʼibȧ֨dĕţi̇y֙ ʼeţ-ʻami̇֔⁠y mi⁠dȧrĕkéy⁠he֖m lwòʼ-şáֽ̌bẇ׃"],[15,8,"עָֽצְמוּ־לִ֤⁠י אַלְמְנֹתָ⁠ו֙ מֵ⁠ח֣וֹל יַמִּ֔ים הֵבֵ֨אתִי לָ⁠הֶ֥ם עַל־אֵ֛ם בָּח֖וּר שֹׁדֵ֣ד בַּֽ⁠צָּהֳרָ֑יִם הִפַּ֤לְתִּי עָלֶ֨י⁠הָ֙ פִּתְאֹ֔ם עִ֖יר וּ⁠בֶהָלֽוֹת׃","ʻáֽẕĕmẇ-li֤⁠y ʼalĕmĕnòţá⁠w֙ mé⁠ẖ֣wòl yami̇֔ym hébé֨ʼţiy lá⁠he֥m ʻal-ʼé֛m bá̇ẖ֖ẇr şò̌dé֣d bȧֽ⁠ẕá̇horá֑yim hipȧ֤lĕţi̇y ʻále֨y⁠há֙ pi̇ţĕʼò֔m ʻi֖yr ẇ⁠behálֽwòţ׃"],[15,9,"אֻמְלְלָ֞ה יֹלֶ֣דֶת הַ⁠שִּׁבְעָ֗ה נָפְחָ֥ה נַפְשָׁ֛⁠הּ באה שִׁמְשָׁ֛⁠הּ בְּ⁠עֹ֥ד יוֹמָ֖ם בּ֣וֹשָׁה וְ⁠חָפֵ֑רָה וּ⁠שְׁאֵֽרִיתָ֗⁠ם לַ⁠חֶ֧רֶב אֶתֵּ֛ן לִ⁠פְנֵ֥י אֹיְבֵי⁠הֶ֖ם נְאֻם־יְהוָֽה׃ס","ʼumĕlĕlá֞h yòle֣deţ ha⁠şi̇̌bĕʻá֗h nápĕẖá֥h napĕşá֛̌⁠ḣ bʼh şǐmĕşá֛̌⁠ḣ bĕ̇⁠ʻò֥d ywòmá֖m ḃ֣wòşá̌h wĕ⁠ẖápé֑ráh ẇ⁠şĕ̌ʼéֽriyţá֗⁠m la⁠ẖe֧reb ʼeţé֛̇n li⁠pĕné֥y ʼòyĕbéy⁠he֖m nĕʼum-yĕhwáֽh׃s"],[15,10,"אֽוֹי־לִ֣⁠י אִמִּ֔⁠י כִּ֣י יְלִדְתִּ֗⁠נִי אִ֥ישׁ רִ֛יב וְ⁠אִ֥ישׁ מָד֖וֹן לְ⁠כָל־הָ⁠אָ֑רֶץ לֹֽא־נָשִׁ֥יתִי וְ⁠לֹא־נָֽשׁוּ־בִ֖⁠י כֻּלֹּ֥⁠ה מְקַלְלַֽו⁠נִי׃ס","ʼֽwòy-li֣⁠y ʼimi̇֔⁠y ki֣̇y yĕlidĕţi̇֗⁠niy ʼi֥yş̌ ri֛yb wĕ⁠ʼi֥yş̌ mád֖wòn lĕ⁠kál-há⁠ʼá֑reẕ lòֽʼ-náşǐ֥yţiy wĕ⁠lòʼ-náֽş̌ẇ-bi֖⁠y ku̇lò֥̇⁠h mĕqalĕlaֽw⁠niy׃s"],[15,11,"אָמַ֣ר יְהוָ֔ה אִם־לֹ֥א שרות⁠ך לְ⁠ט֑וֹב אִם־ל֣וֹא ׀ הִפְגַּ֣עְתִּֽי בְ⁠ךָ֗ בְּ⁠עֵ֥ת־רָעָ֛ה וּ⁠בְ⁠עֵ֥ת צָרָ֖ה אֶת־הָ⁠אֹיֵֽב׃","ʼáma֣r yĕhwá֔h ʼim-lò֥ʼ şrwţ⁠k lĕ⁠t֑wòb ʼim-l֣wòʼ ׀ hipĕgȧ֣ʻĕţiֽ̇y bĕ⁠ká֗ bĕ̇⁠ʻé֥ţ-ráʻá֛h ẇ⁠bĕ⁠ʻé֥ţ ẕárá֖h ʼeţ-há⁠ʼòyéֽb׃"],[15,12,"הֲ⁠יָרֹ֨עַ בַּרְזֶ֧ל ׀ בַּרְזֶ֛ל מִ⁠צָּפ֖וֹן וּ⁠נְחֹֽשֶׁת׃","hà⁠yárò֨ʻa bȧrĕze֧l ׀ bȧrĕze֛l mi⁠ẕá̇p֖wòn ẇ⁠nĕẖòֽşěţ׃"],[15,13,"חֵילְ⁠ךָ֧ וְ⁠אוֹצְרוֹתֶ֛י⁠ךָ לָ⁠בַ֥ז אֶתֵּ֖ן לֹ֣א בִ⁠מְחִ֑יר וּ⁠בְ⁠כָל־חַטֹּאותֶ֖י⁠ךָ וּ⁠בְ⁠כָל־גְּבוּלֶֽי⁠ךָ׃","ẖéylĕ⁠ká֧ wĕ⁠ʼwòẕĕrwòţe֛y⁠ká lá⁠ba֥z ʼeţé֖̇n lò֣ʼ bi⁠mĕẖi֑yr ẇ⁠bĕ⁠kál-ẖatò̇ʼwţe֖y⁠ká ẇ⁠bĕ⁠kál-gĕ̇bẇleֽy⁠ká׃"],[15,14,"וְ⁠הַֽעֲבַרְתִּי֙ אֶת־אֹ֣יְבֶ֔י⁠ךָ בְּ⁠אֶ֖רֶץ לֹ֣א יָדָ֑עְתָּ כִּֽי־אֵ֛שׁ קָדְחָ֥ה בְ⁠אַפִּ֖⁠י עֲלֵי⁠כֶ֥ם תּוּקָֽד׃ס","wĕ⁠haֽʻàbarĕţi̇y֙ ʼeţ-ʼò֣yĕbe֔y⁠ká bĕ̇⁠ʼe֖reẕ lò֣ʼ yádá֑ʻĕţá̇ kiֽ̇y-ʼé֛ş̌ qádĕẖá֥h bĕ⁠ʼapi֖̇⁠y ʻàléy⁠ke֥m ţ̇ẇqáֽd׃s"],[15,15,"אַתָּ֧ה יָדַ֣עְתָּ יְהוָ֗ה זָכְרֵ֤⁠נִי וּ⁠פָקְדֵ֨⁠נִי֙ וְ⁠הִנָּ֤קֶם לִ⁠י֙ מֵ⁠רֹ֣דְפַ֔⁠י אַל־לְ⁠אֶ֥רֶךְ אַפְּ⁠ךָ֖ תִּקָּחֵ֑⁠נִי דַּ֕ע שְׂאֵתִ֥⁠י עָלֶ֖י⁠ךָ חֶרְפָּֽה׃","ʼaţá֧̇h yáda֣ʻĕţá̇ yĕhwá֗h zákĕré֤⁠niy ẇ⁠páqĕdé֨⁠niy֙ wĕ⁠hiná֤̇qem li⁠y֙ mé⁠rò֣dĕpa֔⁠y ʼal-lĕ⁠ʼe֥rekĕ ʼapĕ̇⁠ká֖ ţi̇qá̇ẖé֑⁠niy dȧ֕ʻ şĕ̂ʼéţi֥⁠y ʻále֖y⁠ká ẖerĕpáֽ̇h׃"],[15,16,"נִמְצְא֤וּ דְבָרֶ֨י⁠ךָ֙ וָ⁠אֹ֣כְלֵ֔⁠ם וַ⁠יְהִ֤י דברי⁠ך לִ֔⁠י לְ⁠שָׂשׂ֖וֹן וּ⁠לְ⁠שִׂמְחַ֣ת לְבָבִ֑⁠י כִּֽי־נִקְרָ֤א שִׁמְ⁠ךָ֙ עָלַ֔⁠י יְהוָ֖ה אֱלֹהֵ֥י צְבָאֽוֹת׃ס","nimĕẕĕʼ֤ẇ dĕbáre֨y⁠ká֙ wá⁠ʼò֣kĕlé֔⁠m wa⁠yĕhi֤y dbry⁠k li֔⁠y lĕ⁠şá̂ş֖̂wòn ẇ⁠lĕ⁠şîmĕẖa֣ţ lĕbábi֑⁠y kiֽ̇y-niqĕrá֤ʼ şǐmĕ⁠ká֙ ʻála֔⁠y yĕhwá֖h ʼèlòhé֥y ẕĕbáʼֽwòţ׃s"],[15,17,"לֹֽא־יָשַׁ֥בְתִּי בְ⁠סוֹד־מְשַׂחֲקִ֖ים וָֽ⁠אֶעְלֹ֑ז מִ⁠פְּנֵ֤י יָֽדְ⁠ךָ֙ בָּדָ֣ד יָשַׁ֔בְתִּי כִּֽי־זַ֖עַם מִלֵּאתָֽ⁠נִי׃ס","lòֽʼ-yáşǎ֥bĕţi̇y bĕ⁠swòd-mĕşâẖàqi֖ym wáֽ⁠ʼeʻĕlò֑z mi⁠pĕ̇né֤y yáֽdĕ⁠ká֙ bá̇dá֣d yáşǎ֔bĕţi̇y kiֽ̇y-za֖ʻam milé̇ʼţáֽ⁠niy׃s"],[15,18,"לָ֣⁠מָּה הָיָ֤ה כְאֵבִ⁠י֙ נֶ֔צַח וּ⁠מַכָּתִ֖⁠י אֲנוּשָׁ֑ה֙ מֵֽאֲנָה֙ הֵֽרָפֵ֔א הָי֨וֹ תִֽהְיֶ֥ה לִ⁠י֙ כְּמ֣וֹ אַכְזָ֔ב מַ֖יִם לֹ֥א נֶאֱמָֽנוּ׃ס","lá֣⁠má̇h háyá֤h kĕʼébi⁠y֙ ne֔ẕaẖ ẇ⁠maká̇ţi֖⁠y ʼànẇşá֑̌h֙ méֽʼànáh֙ héֽrápé֔ʼ háy֨wò ţiֽhĕye֥h li⁠y֙ kĕ̇m֣wò ʼakĕzá֔b ma֖yim lò֥ʼ neʼèmáֽnẇ׃s"],[15,19,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה אִם־תָּשׁ֤וּב וַ⁠אֲשִֽׁיבְ⁠ךָ֙ לְ⁠פָנַ֣⁠י תַּֽעֲמֹ֔ד וְ⁠אִם־תּוֹצִ֥יא יָקָ֛ר מִ⁠זּוֹלֵ֖ל כְּ⁠פִ֣⁠י תִֽהְיֶ֑ה יָשֻׁ֤בוּ הֵ֨מָּה֙ אֵלֶ֔י⁠ךָ וְ⁠אַתָּ֖ה לֹֽא־תָשׁ֥וּב אֲלֵי⁠הֶֽם׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h ʼim-ţá̇ş֤̌ẇb wa⁠ʼàşǐֽybĕ⁠ká֙ lĕ⁠pána֣⁠y ţȧֽʻàmò֔d wĕ⁠ʼim-ţ̇wòẕi֥yʼ yáqá֛r mi⁠żwòlé֖l kĕ̇⁠pi֣⁠y ţiֽhĕye֑h yáşǔ֤bẇ hé֨má̇h֙ ʼéle֔y⁠ká wĕ⁠ʼaţá֖̇h lòֽʼ-ţáş֥̌ẇb ʼàléy⁠heֽm׃"],[15,20,"וּ⁠נְתַתִּ֜י⁠ךָ לָ⁠עָ֣ם הַ⁠זֶּ֗ה לְ⁠חוֹמַ֤ת נְחֹ֨שֶׁת֙ בְּצוּרָ֔ה וְ⁠נִלְחֲמ֥וּ אֵלֶ֖י⁠ךָ וְ⁠לֹא־י֣וּכְלוּ לָ֑⁠ךְ כִּֽי־אִתְּ⁠ךָ֥ אֲנִ֛י לְ⁠הוֹשִֽׁיעֲ⁠ךָ֥ וּ⁠לְ⁠הַצִּילֶ֖⁠ךָ נְאֻם־יְהוָֽה׃","ẇ⁠nĕţaţi̇֜y⁠ká lá⁠ʻá֣m ha⁠zė֗h lĕ⁠ẖwòma֤ţ nĕẖò֨şěţ֙ bĕ̇ẕẇrá֔h wĕ⁠nilĕẖàm֥ẇ ʼéle֖y⁠ká wĕ⁠lòʼ-y֣ẇkĕlẇ lá֑⁠kĕ kiֽ̇y-ʼiţĕ̇⁠ká֥ ʼàni֛y lĕ⁠hwòşǐֽyʻà⁠ká֥ ẇ⁠lĕ⁠haẕi̇yle֖⁠ká nĕʼum-yĕhwáֽh׃"],[15,21,"וְ⁠הִצַּלְתִּ֖י⁠ךָ מִ⁠יַּ֣ד רָעִ֑ים וּ⁠פְדִתִ֖י⁠ךָ מִ⁠כַּ֥ף עָרִצִֽים׃פ","wĕ⁠hiẕȧlĕţi֖̇y⁠ká mi⁠yȧ֣d ráʻi֑ym ẇ⁠pĕdiţi֖y⁠ká mi⁠kȧ֥p ʻáriẕiֽym׃p"],[16,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[16,2,"לֹֽא־תִקַּ֥ח לְ⁠ךָ֖ אִשָּׁ֑ה וְ⁠לֹֽא־יִהְי֤וּ לְ⁠ךָ֙ בָּנִ֣ים וּ⁠בָנ֔וֹת בַּ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","lòֽʼ-ţiqȧ֥ẖ lĕ⁠ká֖ ʼişá֑̇̌h wĕ⁠lòֽʼ-yihĕy֤ẇ lĕ⁠ká֙ bá̇ni֣ym ẇ⁠bán֔wòţ bȧ⁠má̇q֖wòm ha⁠zėֽh׃"],[16,3,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה עַל־הַ⁠בָּנִים֙ וְ⁠עַל־הַ⁠בָּנ֔וֹת הַ⁠יִּלּוֹדִ֖ים בַּ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וְ⁠עַֽל־אִמֹּתָ֞⁠ם הַ⁠יֹּלְד֣וֹת אוֹתָ֗⁠ם וְ⁠עַל־אֲבוֹתָ֛⁠ם הַ⁠מּוֹלִדִ֥ים אוֹתָ֖⁠ם בָּ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ʻal-ha⁠bá̇niym֙ wĕ⁠ʻal-ha⁠bá̇n֔wòţ ha⁠yi̇l̇wòdi֖ym bȧ⁠má̇q֣wòm ha⁠zė֑h wĕ⁠ʻaֽl-ʼimò̇ţá֞⁠m ha⁠yò̇lĕd֣wòţ ʼwòţá֗⁠m wĕ⁠ʻal-ʼàbwòţá֛⁠m ha⁠ṁwòlidi֥ym ʼwòţá֖⁠m bá̇⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃"],[16,4,"מְמוֹתֵ֨י תַחֲלֻאִ֜ים יָמֻ֗תוּ לֹ֤א יִסָּֽפְדוּ֙ וְ⁠לֹ֣א יִקָּבֵ֔רוּ לְ⁠דֹ֛מֶן עַל־פְּנֵ֥י הָ⁠אֲדָמָ֖ה יִֽהְי֑וּ וּ⁠בַ⁠חֶ֤רֶב וּ⁠בָֽ⁠רָעָב֙ יִכְל֔וּ וְ⁠הָיְתָ֤ה נִבְלָתָ⁠ם֙ לְ⁠מַאֲכָ֔ל לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֥ת הָ⁠אָֽרֶץ׃ס","mĕmwòţé֨y ţaẖàluʼi֜ym yámu֗ţẇ lò֤ʼ yisáֽ̇pĕdẇ֙ wĕ⁠lò֣ʼ yiqá̇bé֔rẇ lĕ⁠dò֛men ʻal-pĕ̇né֥y há⁠ʼàdámá֖h yiֽhĕy֑ẇ ẇ⁠ba⁠ẖe֤reb ẇ⁠báֽ⁠ráʻáb֙ yikĕl֔ẇ wĕ⁠háyĕţá֤h nibĕláţá⁠m֙ lĕ⁠maʼàká֔l lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֥ţ há⁠ʼáֽreẕ׃s"],[16,5,"כִּֽי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה אַל־תָּבוֹא֙ בֵּ֣ית מַרְזֵ֔חַ וְ⁠אַל־תֵּלֵ֣ךְ לִ⁠סְפּ֔וֹד וְ⁠אַל־תָּנֹ֖ד לָ⁠הֶ֑ם כִּֽי־אָסַ֨פְתִּי אֶת־שְׁלוֹמִ֜⁠י מֵ⁠אֵ֨ת הָ⁠עָ֤ם־הַ⁠זֶּה֙ נְאֻם־יְהוָ֔ה אֶת־הַ⁠חֶ֖סֶד וְ⁠אֶת־הָֽ⁠רַחֲמִֽים׃","kiֽ̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ʼal-ţá̇bwòʼ֙ bé֣̇yţ marĕzé֔ẖa wĕ⁠ʼal-ţé̇lé֣kĕ li⁠sĕṗ֔wòd wĕ⁠ʼal-ţá̇nò֖d lá⁠he֑m kiֽ̇y-ʼása֨pĕţi̇y ʼeţ-şĕ̌lwòmi֜⁠y mé⁠ʼé֨ţ há⁠ʻá֤m-ha⁠zėh֙ nĕʼum-yĕhwá֔h ʼeţ-ha⁠ẖe֖sed wĕ⁠ʼeţ-háֽ⁠raẖàmiֽym׃"],[16,6,"וּ⁠מֵ֨תוּ גְדֹלִ֧ים וּ⁠קְטַנִּ֛ים בָּ⁠אָ֥רֶץ הַ⁠זֹּ֖את לֹ֣א יִקָּבֵ֑רוּ וְ⁠לֹֽא־יִסְפְּד֣וּ לָ⁠הֶ֔ם וְ⁠לֹ֣א יִתְגֹּדַ֔ד וְ⁠לֹ֥א יִקָּרֵ֖חַ לָ⁠הֶֽם׃","ẇ⁠mé֨ţẇ gĕdòli֧ym ẇ⁠qĕtani֛̇ym bá̇⁠ʼá֥reẕ ha⁠zò֖̇ʼţ lò֣ʼ yiqá̇bé֑rẇ wĕ⁠lòֽʼ-yisĕpĕ̇d֣ẇ lá⁠he֔m wĕ⁠lò֣ʼ yiţĕgò̇da֔d wĕ⁠lò֥ʼ yiqá̇ré֖ẖa lá⁠heֽm׃"],[16,7,"וְ⁠לֹֽא־יִפְרְס֥וּ לָ⁠הֶ֛ם עַל־אֵ֖בֶל לְ⁠נַחֲמ֣⁠וֹ עַל־מֵ֑ת וְ⁠לֹֽא־יַשְׁק֤וּ אוֹתָ⁠ם֙ כּ֣וֹס תַּנְחוּמִ֔ים עַל־אָבִ֖י⁠ו וְ⁠עַל־אִמּֽ⁠וֹ׃","wĕ⁠lòֽʼ-yipĕrĕs֥ẇ lá⁠he֛m ʻal-ʼé֖bel lĕ⁠naẖàm֣⁠wò ʻal-mé֑ţ wĕ⁠lòֽʼ-yaşĕ̌q֤ẇ ʼwòţá⁠m֙ k֣̇wòs ţȧnĕẖẇmi֔ym ʻal-ʼábi֖y⁠w wĕ⁠ʻal-ʼiṁֽ⁠wò׃"],[16,8,"וּ⁠בֵית־מִשְׁתֶּ֥ה לֹא־תָב֖וֹא לָ⁠שֶׁ֣בֶת אוֹתָ֑⁠ם לֶ⁠אֱכֹ֖ל וְ⁠לִ⁠שְׁתּֽוֹת׃ס","ẇ⁠béyţ-mişĕ̌ţė֥h lòʼ-ţáb֖wòʼ lá⁠şě֣beţ ʼwòţá֑⁠m le⁠ʼèkò֖l wĕ⁠li⁠şĕ̌ţֽ̇wòţ׃s"],[16,9,"כִּי֩ כֹ֨ה אָמַ֜ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֨י מַשְׁבִּ֜ית מִן־הַ⁠מָּק֥וֹם הַ⁠זֶּ֛ה לְ⁠עֵינֵי⁠כֶ֖ם וּ⁠בִֽ⁠ימֵי⁠כֶ֑ם ק֤וֹל שָׂשׂוֹן֙ וְ⁠ק֣וֹל שִׂמְחָ֔ה ק֥וֹל חָתָ֖ן וְ⁠ק֥וֹל כַּלָּֽה׃","ki̇y֩ kò֨h ʼáma֜r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֨y maşĕ̌bi̇֜yţ min-ha⁠má̇q֥wòm ha⁠zė֛h lĕ⁠ʻéynéy⁠ke֖m ẇ⁠biֽ⁠yméy⁠ke֑m q֤wòl şá̂ş̂wòn֙ wĕ⁠q֣wòl şîmĕẖá֔h q֥wòl ẖáţá֖n wĕ⁠q֥wòl kȧláֽ̇h׃"],[16,10,"וְ⁠הָיָ֗ה כִּ֤י תַגִּיד֙ לָ⁠עָ֣ם הַ⁠זֶּ֔ה אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וְ⁠אָמְר֣וּ אֵלֶ֗י⁠ךָ עַל־מֶה֩ דִבֶּ֨ר יְהוָ֤ה עָלֵ֨י⁠נוּ֙ אֵ֣ת כָּל־הָ⁠רָעָ֤ה הַ⁠גְּדוֹלָה֙ הַ⁠זֹּ֔את וּ⁠מֶ֤ה עֲוֺנֵ֨⁠נוּ֙ וּ⁠מֶ֣ה חַטָּאתֵ֔⁠נוּ אֲשֶׁ֥ר חָטָ֖אנוּ לַֽ⁠יהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wĕ⁠háyá֗h ki֤̇y ţagi̇yd֙ lá⁠ʻá֣m ha⁠zė֔h ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wĕ⁠ʼámĕr֣ẇ ʼéle֗y⁠ká ʻal-meh֩ dibė֨r yĕhwá֤h ʻálé֨y⁠nẇ֙ ʼé֣ţ ká̇l-há⁠ráʻá֤h ha⁠gĕ̇dwòláh֙ ha⁠zò̇֔ʼţ ẇ⁠me֤h ʻàwֺné֨⁠nẇ֙ ẇ⁠me֣h ẖatá̇ʼţé֔⁠nẇ ʼàşě֥r ẖátá֖ʼnẇ laֽ⁠yhwá֥h ʼèlòhéֽy⁠nẇ׃"],[16,11,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם עַל֩ אֲשֶׁר־עָזְב֨וּ אֲבוֹתֵי⁠כֶ֤ם אוֹתִ⁠י֙ נְאֻם־יְהוָ֔ה וַ⁠יֵּלְכ֗וּ אַֽחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יַּעַבְד֖וּ⁠ם וַ⁠יִּשְׁתַּחֲו֣וּ לָ⁠הֶ֑ם וְ⁠אֹתִ֣⁠י עָזָ֔בוּ וְ⁠אֶת־תּוֹרָתִ֖⁠י לֹ֥א שָׁמָֽרוּ׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m ʻal֩ ʼàşěr-ʻázĕb֨ẇ ʼàbwòţéy⁠ke֤m ʼwòţi⁠y֙ nĕʼum-yĕhwá֔h wa⁠yé̇lĕk֗ẇ ʼaֽẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym wa⁠yȧʻabĕd֖ẇ⁠m wa⁠yi̇şĕ̌ţȧẖàw֣ẇ lá⁠he֑m wĕ⁠ʼòţi֣⁠y ʻázá֔bẇ wĕ⁠ʼeţ-ţ̇wòráţi֖⁠y lò֥ʼ şá̌máֽrẇ׃"],[16,12,"וְ⁠אַתֶּ֛ם הֲרֵעֹתֶ֥ם לַ⁠עֲשׂ֖וֹת מֵ⁠אֲבֽוֹתֵי⁠כֶ֑ם וְ⁠הִנְּ⁠כֶ֣ם הֹלְכִ֗ים אִ֚ישׁ אַֽחֲרֵי֙ שְׁרִר֣וּת לִבּֽ⁠וֹ־הָ⁠רָ֔ע לְ⁠בִלְתִּ֖י שְׁמֹ֥עַ אֵלָֽ⁠י׃","wĕ⁠ʼaţė֛m hàréʻòţe֥m la⁠ʻàş֖̂wòţ mé⁠ʼàbֽwòţéy⁠ke֑m wĕ⁠hinĕ̇⁠ke֣m hòlĕki֗ym ʼi֚yş̌ ʼaֽẖàréy֙ şĕ̌rir֣ẇţ liḃֽ⁠wò-há⁠rá֔ʻ lĕ⁠bilĕţi֖̇y şĕ̌mò֥ʻa ʼéláֽ⁠y׃"],[16,13,"וְ⁠הֵטַלְתִּ֣י אֶתְ⁠כֶ֗ם מֵ⁠עַל֙ הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את עַל־הָ⁠אָ֕רֶץ אֲשֶׁר֙ לֹ֣א יְדַעְתֶּ֔ם אַתֶּ֖ם וַ⁠אֲבֽוֹתֵי⁠כֶ֑ם וַ⁠עֲבַדְתֶּם־שָׁ֞ם אֶת־אֱלֹהִ֤ים אֲחֵרִים֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה אֲשֶׁ֛ר לֹֽא־אֶתֵּ֥ן לָ⁠כֶ֖ם חֲנִינָֽה׃ס","wĕ⁠hétalĕţi֣̇y ʼeţĕ⁠ke֗m mé⁠ʻal֙ há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ʻal-há⁠ʼá֕reẕ ʼàşěr֙ lò֣ʼ yĕdaʻĕţė֔m ʼaţė֖m wa⁠ʼàbֽwòţéy⁠ke֑m wa⁠ʻàbadĕţėm-şá̌֞m ʼeţ-ʼèlòhi֤ym ʼàẖériym֙ ywòmá֣m wá⁠la֔yĕláh ʼàşě֛r lòֽʼ-ʼeţé֥̇n lá⁠ke֖m ẖàniynáֽh׃s"],[16,14,"לָ⁠כֵ֛ן הִנֵּֽה־יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וְ⁠לֹֽא־יֵאָמֵ֥ר עוֹד֙ חַי־יְהוָ֔ה אֲשֶׁ֧ר הֶעֱלָ֛ה אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","lá⁠ké֛n hinéֽ̇h-yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h wĕ⁠lòֽʼ-yéʼámé֥r ʻwòd֙ ẖay-yĕhwá֔h ʼàşě֧r heʻèlá֛h ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[16,15,"כִּ֣י אִם־חַי־יְהוָ֗ה אֲשֶׁ֨ר הֶעֱלָ֜ה אֶת־בְּנֵ֤י יִשְׂרָאֵל֙ מֵ⁠אֶ֣רֶץ צָפ֔וֹן וּ⁠מִ⁠כֹּל֙ הָֽ⁠אֲרָצ֔וֹת אֲשֶׁ֥ר הִדִּיחָ֖⁠ם שָׁ֑מָּ⁠ה וַ⁠הֲשִֽׁבֹתִי⁠ם֙ עַל־אַדְמָתָ֔⁠ם אֲשֶׁ֥ר נָתַ֖תִּי לַ⁠אֲבוֹתָֽ⁠ם׃ס","ki֣̇y ʼim-ẖay-yĕhwá֗h ʼàşě֨r heʻèlá֜h ʼeţ-bĕ̇né֤y yişĕ̂ráʼél֙ mé⁠ʼe֣reẕ ẕáp֔wòn ẇ⁠mi⁠kò̇l֙ háֽ⁠ʼàráẕ֔wòţ ʼàşě֥r hidi̇yẖá֖⁠m şá֑̌má̇⁠h wa⁠hàşǐֽbòţiy⁠m֙ ʻal-ʼadĕmáţá֔⁠m ʼàşě֥r náţa֖ţi̇y la⁠ʼàbwòţáֽ⁠m׃s"],[16,16,"הִנְ⁠נִ֨י שֹׁלֵ֜חַ ל⁠דוגים רַבִּ֛ים נְאֻם־יְהוָ֖ה וְ⁠דִיג֑וּ⁠ם וְ⁠אַֽחֲרֵי־כֵ֗ן אֶשְׁלַח֙ לְ⁠רַבִּ֣ים צַיָּדִ֔ים וְ⁠צָד֞וּ⁠ם מֵ⁠עַ֤ל כָּל־הַר֙ וּ⁠מֵ⁠עַ֣ל כָּל־גִּבְעָ֔ה וּ⁠מִ⁠נְּקִיקֵ֖י הַ⁠סְּלָעִֽים׃","hinĕ⁠ni֨y şò̌lé֜ẖa l⁠dwgym rabi֛̇ym nĕʼum-yĕhwá֖h wĕ⁠diyg֑ẇ⁠m wĕ⁠ʼaֽẖàréy-ké֗n ʼeşĕ̌laẖ֙ lĕ⁠rabi֣̇ym ẕayá̇di֔ym wĕ⁠ẕád֞ẇ⁠m mé⁠ʻa֤l ká̇l-har֙ ẇ⁠mé⁠ʻa֣l ká̇l-gi̇bĕʻá֔h ẇ⁠mi⁠nĕ̇qiyqé֖y ha⁠sĕ̇láʻiֽym׃"],[16,17,"כִּ֤י עֵינַ⁠י֙ עַל־כָּל־דַּרְכֵי⁠הֶ֔ם לֹ֥א נִסְתְּר֖וּ מִ⁠לְּ⁠פָנָ֑⁠י וְ⁠לֹֽא־נִצְפַּ֥ן עֲוֺנָ֖⁠ם מִ⁠נֶּ֥גֶד עֵינָֽ⁠י׃","ki֤̇y ʻéyna⁠y֙ ʻal-ká̇l-dȧrĕkéy⁠he֔m lò֥ʼ nisĕţĕ̇r֖ẇ mi⁠lĕ̇⁠páná֑⁠y wĕ⁠lòֽʼ-niẕĕpȧ֥n ʻàwֺná֖⁠m mi⁠nė֥ged ʻéynáֽ⁠y׃"],[16,18,"וְ⁠שִׁלַּמְתִּ֣י רִֽאשׁוֹנָ֗ה מִשְׁנֵ֤ה עֲוֺנָ⁠ם֙ וְ⁠חַטָּאתָ֔⁠ם עַ֖ל חַלְּלָ֣⁠ם אֶת־אַרְצִ֑⁠י בְּ⁠נִבְלַ֤ת שִׁקּֽוּצֵי⁠הֶם֙ וְ⁠תוֹעֲב֣וֹתֵי⁠הֶ֔ם מָלְא֖וּ אֶת־נַחֲלָתִֽ⁠י׃ס","wĕ⁠şǐlȧmĕţi֣̇y riֽʼş̌wòná֗h mişĕ̌né֤h ʻàwֺná⁠m֙ wĕ⁠ẖatá̇ʼţá֔⁠m ʻa֖l ẖalĕ̇lá֣⁠m ʼeţ-ʼarĕẕi֑⁠y bĕ̇⁠nibĕla֤ţ şǐqֽ̇ẇẕéy⁠hem֙ wĕ⁠ţwòʻàb֣wòţéy⁠he֔m málĕʼ֖ẇ ʼeţ-naẖàláţiֽ⁠y׃s"],[16,19,"יְהוָ֞ה עֻזִּ֧⁠י וּ⁠מָעֻזִּ֛⁠י וּ⁠מְנוּסִ֖⁠י בְּ⁠י֣וֹם צָרָ֑ה אֵלֶ֗י⁠ךָ גּוֹיִ֤ם יָבֹ֨אוּ֙ מֵֽ⁠אַפְסֵי־אָ֔רֶץ וְ⁠יֹאמְר֗וּ אַךְ־שֶׁ֨קֶר֙ נָחֲל֣וּ אֲבוֹתֵ֔י⁠נוּ הֶ֖בֶל וְ⁠אֵֽין־בָּ֥⁠ם מוֹעִֽיל׃","yĕhwá֞h ʻuzi֧̇⁠y ẇ⁠máʻuzi֛̇⁠y ẇ⁠mĕnẇsi֖⁠y bĕ̇⁠y֣wòm ẕárá֑h ʼéle֗y⁠ká ġwòyi֤m yábò֨ʼẇ֙ méֽ⁠ʼapĕséy-ʼá֔reẕ wĕ⁠yòʼmĕr֗ẇ ʼakĕ-şě֨qer֙ náẖàl֣ẇ ʼàbwòţé֔y⁠nẇ he֖bel wĕ⁠ʼéֽyn-bá֥̇⁠m mwòʻiֽyl׃"],[16,20,"הֲ⁠יַעֲשֶׂה־לּ֥⁠וֹ אָדָ֖ם אֱלֹהִ֑ים וְ⁠הֵ֖מָּה לֹ֥א אֱלֹהִֽים׃","hà⁠yaʻàşêh-l֥̇⁠wò ʼádá֖m ʼèlòhi֑ym wĕ⁠hé֖má̇h lò֥ʼ ʼèlòhiֽym׃"],[16,21,"לָ⁠כֵן֙ הִנְ⁠נִ֣י מֽוֹדִיעָ֔⁠ם בַּ⁠פַּ֣עַם הַ⁠זֹּ֔את אוֹדִיעֵ֥⁠ם אֶת־יָדִ֖⁠י וְ⁠אֶת־גְּבֽוּרָתִ֑⁠י וְ⁠יָדְע֖וּ כִּֽי־שְׁמִ֥⁠י יְהוָֽה׃ס","lá⁠kén֙ hinĕ⁠ni֣y mֽwòdiyʻá֔⁠m bȧ⁠pȧ֣ʻam ha⁠zò̇֔ʼţ ʼwòdiyʻé֥⁠m ʼeţ-yádi֖⁠y wĕ⁠ʼeţ-gĕ̇bֽẇráţi֑⁠y wĕ⁠yádĕʻ֖ẇ kiֽ̇y-şĕ̌mi֥⁠y yĕhwáֽh׃s"],[17,1,"חַטַּ֣את יְהוּדָ֗ה כְּתוּבָ֛ה בְּ⁠עֵ֥ט בַּרְזֶ֖ל בְּ⁠צִפֹּ֣רֶן שָׁמִ֑יר חֲרוּשָׁה֙ עַל־ל֣וּחַ לִבָּ֔⁠ם וּ⁠לְ⁠קַרְנ֖וֹת מִזְבְּחוֹתֵי⁠כֶֽם׃","ẖatȧ֣ʼţ yĕhẇdá֗h kĕ̇ţẇbá֛h bĕ̇⁠ʻé֥t bȧrĕze֖l bĕ̇⁠ẕipò֣̇ren şá̌mi֑yr ẖàrẇşá̌h֙ ʻal-l֣ẇẖa libá̇֔⁠m ẇ⁠lĕ⁠qarĕn֖wòţ mizĕbĕ̇ẖwòţéy⁠keֽm׃"],[17,2,"כִּ⁠זְכֹּ֤ר בְּנֵי⁠הֶם֙ מִזְבְּחוֹתָ֔⁠ם וַ⁠אֲשֵׁרֵי⁠הֶ֖ם עַל־עֵ֣ץ רַֽעֲנָ֑ן עַ֖ל גְּבָע֥וֹת הַ⁠גְּבֹהֽוֹת׃","ki̇⁠zĕkò֤̇r bĕ̇néy⁠hem֙ mizĕbĕ̇ẖwòţá֔⁠m wa⁠ʼàşé̌réy⁠he֖m ʻal-ʻé֣ẕ raֽʻàná֑n ʻa֖l gĕ̇báʻ֥wòţ ha⁠gĕ̇bòhֽwòţ׃"],[17,3,"הֲרָרִ⁠י֙ בַּ⁠שָּׂדֶ֔ה חֵילְ⁠ךָ֥ כָל־אוֹצְרוֹתֶ֖י⁠ךָ לָ⁠בַ֣ז אֶתֵּ֑ן בָּמֹתֶ֕י⁠ךָ בְּ⁠חַטָּ֖את בְּ⁠כָל־גְּבוּלֶֽי⁠ךָ׃","hàrári⁠y֙ bȧ⁠şá̇̂de֔h ẖéylĕ⁠ká֥ kál-ʼwòẕĕrwòţe֖y⁠ká lá⁠ba֣z ʼeţé֑̇n bá̇mòţe֕y⁠ká bĕ̇⁠ẖatá֖̇ʼţ bĕ̇⁠kál-gĕ̇bẇleֽy⁠ká׃"],[17,4,"וְ⁠שָׁמַטְתָּ֗ה וּ⁠בְ⁠ךָ֙ מִ⁠נַּחֲלָֽתְ⁠ךָ֙ אֲשֶׁ֣ר נָתַ֣תִּי לָ֔⁠ךְ וְ⁠הַעֲבַדְתִּ֨י⁠ךָ֙ אֶת־אֹ֣יְבֶ֔י⁠ךָ בָּ⁠אָ֖רֶץ אֲשֶׁ֣ר לֹֽא־יָדָ֑עְתָּ כִּֽי־אֵ֛שׁ קְדַחְתֶּ֥ם בְּ⁠אַפִּ֖⁠י עַד־עוֹלָ֥ם תּוּקָֽד׃ס","wĕ⁠şá̌matĕţá̇֗h ẇ⁠bĕ⁠ká֙ mi⁠nȧẖàláֽţĕ⁠ká֙ ʼàşě֣r náţa֣ţi̇y lá֔⁠kĕ wĕ⁠haʻàbadĕţi̇֨y⁠ká֙ ʼeţ-ʼò֣yĕbe֔y⁠ká bá̇⁠ʼá֖reẕ ʼàşě֣r lòֽʼ-yádá֑ʻĕţá̇ kiֽ̇y-ʼé֛ş̌ qĕdaẖĕţė֥m bĕ̇⁠ʼapi֖̇⁠y ʻad-ʻwòlá֥m ţ̇ẇqáֽd׃s"],[17,5,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אָר֤וּר הַ⁠גֶּ֨בֶר֙ אֲשֶׁ֣ר יִבְטַ֣ח בָּֽ⁠אָדָ֔ם וְ⁠שָׂ֥ם בָּשָׂ֖ר זְרֹע֑⁠וֹ וּ⁠מִן־יְהוָ֖ה יָס֥וּר לִבּֽ⁠וֹ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼár֤ẇr ha⁠gė֨ber֙ ʼàşě֣r yibĕta֣ẖ báֽ̇⁠ʼádá֔m wĕ⁠şá֥̂m bá̇şá֖̂r zĕròʻ֑⁠wò ẇ⁠min-yĕhwá֖h yás֥ẇr liḃֽ⁠wò׃"],[17,6,"וְ⁠הָיָה֙ כְּ⁠עַרְעָ֣ר בָּֽ⁠עֲרָבָ֔ה וְ⁠לֹ֥א יִרְאֶ֖ה כִּי־יָב֣וֹא ט֑וֹב וְ⁠שָׁכַ֤ן חֲרֵרִים֙ בַּ⁠מִּדְבָּ֔ר אֶ֥רֶץ מְלֵחָ֖ה וְ⁠לֹ֥א תֵשֵֽׁב׃ס","wĕ⁠háyáh֙ kĕ̇⁠ʻarĕʻá֣r báֽ̇⁠ʻàrábá֔h wĕ⁠lò֥ʼ yirĕʼe֖h ki̇y-yáb֣wòʼ t֑wòb wĕ⁠şá̌ka֤n ẖàrériym֙ bȧ⁠mi̇dĕbá̇֔r ʼe֥reẕ mĕléẖá֖h wĕ⁠lò֥ʼ ţéşéֽ̌b׃s"],[17,7,"בָּר֣וּךְ הַ⁠גֶּ֔בֶר אֲשֶׁ֥ר יִבְטַ֖ח בַּֽ⁠יהוָ֑ה וְ⁠הָיָ֥ה יְהוָ֖ה מִבְטַחֽ⁠וֹ׃","bá̇r֣ẇkĕ ha⁠gė֔ber ʼàşě֥r yibĕta֖ẖ bȧֽ⁠yhwá֑h wĕ⁠háyá֥h yĕhwá֖h mibĕtaẖֽ⁠wò׃"],[17,8,"וְ⁠הָיָ֞ה כְּ⁠עֵ֣ץ ׀ שָׁת֣וּל עַל־מַ֗יִם וְ⁠עַל־יוּבַל֙ יְשַׁלַּ֣ח שָֽׁרָשָׁ֔י⁠ו וְ⁠לֹ֤א ירא כִּֽי־יָבֹ֣א חֹ֔ם וְ⁠הָיָ֥ה עָלֵ֖⁠הוּ רַֽעֲנָ֑ן וּ⁠בִ⁠שְׁנַ֤ת בַּצֹּ֨רֶת֙ לֹ֣א יִדְאָ֔ג וְ⁠לֹ֥א יָמִ֖ישׁ מֵ⁠עֲשׂ֥וֹת פֶּֽרִי׃","wĕ⁠háyá֞h kĕ̇⁠ʻé֣ẕ ׀ şá̌ţ֣ẇl ʻal-ma֗yim wĕ⁠ʻal-yẇbal֙ yĕşǎlȧ֣ẖ şáֽ̌ráşá̌֔y⁠w wĕ⁠lò֤ʼ yrʼ kiֽ̇y-yábò֣ʼ ẖò֔m wĕ⁠háyá֥h ʻálé֖⁠hẇ raֽʻàná֑n ẇ⁠bi⁠şĕ̌na֤ţ bȧẕò̇֨reţ֙ lò֣ʼ yidĕʼá֔g wĕ⁠lò֥ʼ yámi֖yş̌ mé⁠ʻàş֥̂wòţ pėֽriy׃"],[17,9,"עָקֹ֥ב הַ⁠לֵּ֛ב מִ⁠כֹּ֖ל וְ⁠אָנֻ֣שׁ ה֑וּא מִ֖י יֵדָעֶֽ⁠נּוּ׃","ʻáqò֥b ha⁠lé֛̇b mi⁠kò֖̇l wĕ⁠ʼánu֣ş̌ h֑ẇʼ mi֖y yédáʻeֽ⁠ṅẇ׃"],[17,10,"אֲנִ֧י יְהוָ֛ה חֹקֵ֥ר לֵ֖ב בֹּחֵ֣ן כְּלָי֑וֹת וְ⁠לָ⁠תֵ֤ת לְ⁠אִישׁ֙ כ⁠דרכ⁠ו כִּ⁠פְרִ֖י מַעֲלָלָֽי⁠ו׃ס","ʼàni֧y yĕhwá֛h ẖòqé֥r lé֖b bò̇ẖé֣n kĕ̇láy֑wòţ wĕ⁠lá⁠ţé֤ţ lĕ⁠ʼiyş̌֙ k⁠drk⁠w ki̇⁠pĕri֖y maʻàláláֽy⁠w׃s"],[17,11,"קֹרֵ֤א דָגַר֙ וְ⁠לֹ֣א יָלָ֔ד עֹ֥שֶׂה עֹ֖שֶׁר וְ⁠לֹ֣א בְ⁠מִשְׁפָּ֑ט בַּ⁠חֲצִ֤י ימ⁠ו יַעַזְבֶ֔⁠נּוּ וּ⁠בְ⁠אַחֲרִית֖⁠וֹ יִהְיֶ֥ה נָבָֽל׃","qòré֤ʼ dágar֙ wĕ⁠lò֣ʼ yálá֔d ʻò֥şêh ʻò֖şěr wĕ⁠lò֣ʼ bĕ⁠mişĕ̌pá֑̇t bȧ⁠ẖàẕi֤y ym⁠w yaʻazĕbe֔⁠ṅẇ ẇ⁠bĕ⁠ʼaẖàriyţ֖⁠wò yihĕye֥h nábáֽl׃"],[17,12,"כִּסֵּ֣א כָב֔וֹד מָר֖וֹם מֵֽ⁠רִאשׁ֑וֹן מְק֖וֹם מִקְדָּשֵֽׁ⁠נוּ׃","ki̇sé֣̇ʼ káb֔wòd már֖wòm méֽ⁠riʼş֑̌wòn mĕq֖wòm miqĕdá̇şéֽ̌⁠nẇ׃"],[17,13,"מִקְוֵ֤ה יִשְׂרָאֵל֙ יְהוָ֔ה כָּל־עֹזְבֶ֖י⁠ךָ יֵבֹ֑שׁוּ יסור⁠י בָּ⁠אָ֣רֶץ יִכָּתֵ֔בוּ כִּ֥י עָזְב֛וּ מְק֥וֹר מַֽיִם־חַיִּ֖ים אֶת־יְהוָֽה׃ס","miqĕwé֤h yişĕ̂ráʼél֙ yĕhwá֔h ká̇l-ʻòzĕbe֖y⁠ká yébò֑ş̌ẇ yswr⁠y bá̇⁠ʼá֣reẕ yiká̇ţé֔bẇ ki֥̇y ʻázĕb֛ẇ mĕq֥wòr maֽyim-ẖayi֖̇ym ʼeţ-yĕhwáֽh׃s"],[17,14,"רְפָאֵ֤⁠נִי יְהוָה֙ וְ⁠אֵ֣רָפֵ֔א הוֹשִׁיעֵ֖⁠נִי וְ⁠אִוָּשֵׁ֑עָה כִּ֥י תְהִלָּתִ֖⁠י אָֽתָּה׃","rĕpáʼé֤⁠niy yĕhwáh֙ wĕ⁠ʼé֣rápé֔ʼ hwòşǐyʻé֖⁠niy wĕ⁠ʼiwá̇şé֑̌ʻáh ki֥̇y ţĕhilá̇ţi֖⁠y ʼáֽţá̇h׃"],[17,15,"הִנֵּה־הֵ֕מָּה אֹמְרִ֖ים אֵלָ֑⁠י אַיֵּ֥ה דְבַר־יְהוָ֖ה יָ֥בוֹא נָֽא׃","hiné̇h-hé֕má̇h ʼòmĕri֖ym ʼélá֑⁠y ʼayé֥̇h dĕbar-yĕhwá֖h yá֥bwòʼ náֽʼ׃"],[17,16,"וַ⁠אֲנִ֞י לֹא־אַ֣צְתִּי ׀ מֵ⁠רֹעֶ֣ה אַחֲרֶ֗י⁠ךָ וְ⁠י֥וֹם אָנ֛וּשׁ לֹ֥א הִתְאַוֵּ֖יתִי אַתָּ֣ה יָדָ֑עְתָּ מוֹצָ֣א שְׂפָתַ֔⁠י נֹ֥כַח פָּנֶ֖י⁠ךָ הָיָֽה׃","wa⁠ʼàni֞y lòʼ-ʼa֣ẕĕţi̇y ׀ mé⁠ròʻe֣h ʼaẖàre֗y⁠ká wĕ⁠y֥wòm ʼán֛ẇş̌ lò֥ʼ hiţĕʼawé֖̇yţiy ʼaţá֣̇h yádá֑ʻĕţá̇ mwòẕá֣ʼ şĕ̂páţa֔⁠y nò֥kaẖ pá̇ne֖y⁠ká háyáֽh׃"],[17,17,"אַל־תִּֽהְיֵה־לִ֖⁠י לִ⁠מְחִתָּ֑ה מַֽחֲסִ⁠י־אַ֖תָּה בְּ⁠י֥וֹם רָעָֽה׃","ʼal-ţiֽ̇hĕyéh-li֖⁠y li⁠mĕẖiţá֑̇h mֽaẖàsi⁠y-ʼa֖ţá̇h bĕ̇⁠y֥wòm ráʻáֽh׃"],[17,18,"יֵבֹ֤שׁוּ רֹדְפַ⁠י֙ וְ⁠אַל־אֵבֹ֣שָׁה אָ֔נִי יֵחַ֣תּוּ הֵ֔מָּה וְ⁠אַל־אֵחַ֖תָּה אָ֑נִי הָבִ֤יא עֲלֵי⁠הֶם֙ י֣וֹם רָעָ֔ה וּ⁠מִשְׁנֶ֥ה שִׁבָּר֖וֹן שָׁבְרֵֽ⁠ם׃ס","yébò֤ş̌ẇ ròdĕpa⁠y֙ wĕ⁠ʼal-ʼébò֣şá̌h ʼá֔niy yéẖa֣ţ̇ẇ hé֔má̇h wĕ⁠ʼal-ʼéẖa֖ţá̇h ʼá֑niy hábi֤yʼ ʻàléy⁠hem֙ y֣wòm ráʻá֔h ẇ⁠mişĕ̌ne֥h şǐbá̇r֖wòn şá̌bĕréֽ⁠m׃s"],[17,19,"כֹּה־אָמַ֨ר יְהוָ֜ה אֵלַ֗⁠י הָלֹ֤ךְ וְ⁠עָֽמַדְתָּ֙ בְּ⁠שַׁ֣עַר בְּנֵֽי־עם אֲשֶׁ֨ר יָבֹ֤אוּ ב⁠וֹ֙ מַלְכֵ֣י יְהוּדָ֔ה וַ⁠אֲשֶׁ֖ר יֵ֣צְאוּ ב֑⁠וֹ וּ⁠בְ⁠כֹ֖ל שַׁעֲרֵ֥י יְרוּשָׁלִָֽם׃","kò̇h-ʼáma֨r yĕhwá֜h ʼéla֗⁠y hálò֤kĕ wĕ⁠ʻáֽmadĕţá̇֙ bĕ̇⁠şǎ֣ʻar bĕ̇néֽy-ʻm ʼàşě֨r yábò֤ʼẇ b⁠wò֙ malĕké֣y yĕhẇdá֔h wa⁠ʼàşě֖r yé֣ẕĕʼẇ b֑⁠wò ẇ⁠bĕ⁠kò֖l şǎʻàré֥y yĕrẇşá̌liáֽm׃"],[17,20,"וְ⁠אָמַרְתָּ֣ אֲ֠לֵי⁠הֶם שִׁמְע֨וּ דְבַר־יְהוָ֜ה מַלְכֵ֤י יְהוּדָה֙ וְ⁠כָל־יְהוּדָ֔ה וְ⁠כֹ֖ל יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם הַ⁠בָּאִ֖ים בַּ⁠שְּׁעָרִ֥ים הָ⁠אֵֽלֶּה׃ס","wĕ⁠ʼámarĕţá֣̇ ʼà֠léy⁠hem şǐmĕʻ֨ẇ dĕbar-yĕhwá֜h malĕké֤y yĕhẇdáh֙ wĕ⁠kál-yĕhẇdá֔h wĕ⁠kò֖l yòşĕ̌bé֣y yĕrẇşá̌liá֑m ha⁠bá̇ʼi֖ym bȧ⁠şĕ̇̌ʻári֥ym há⁠ʼéֽlėh׃s"],[17,21,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִשָּׁמְר֖וּ בְּ⁠נַפְשֽׁוֹתֵי⁠כֶ֑ם וְ⁠אַל־תִּשְׂא֤וּ מַשָּׂא֙ בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֔ת וַ⁠הֲבֵאתֶ֖ם בְּ⁠שַׁעֲרֵ֥י יְרוּשָׁלִָֽם׃","kò֚̇h ʼáma֣r yĕhwá֔h hişá̇̌mĕr֖ẇ bĕ̇⁠napĕşֽ̌wòţéy⁠ke֑m wĕ⁠ʼal-ţi̇şĕ̂ʼ֤ẇ maşá̇̂ʼ֙ bĕ̇⁠y֣wòm ha⁠şȧ̌bá̇֔ţ wa⁠hàbéʼţe֖m bĕ̇⁠şǎʻàré֥y yĕrẇşá̌liáֽm׃"],[17,22,"וְ⁠לֹא־תוֹצִ֨יאוּ מַשָּׂ֤א מִ⁠בָּֽתֵּי⁠כֶם֙ בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֔ת וְ⁠כָל־מְלָאכָ֖ה לֹ֣א תַֽעֲשׂ֑וּ וְ⁠קִדַּשְׁתֶּם֙ אֶת־י֣וֹם הַ⁠שַּׁבָּ֔ת כַּ⁠אֲשֶׁ֥ר צִוִּ֖יתִי אֶת־אֲבוֹתֵי⁠כֶֽם׃","wĕ⁠lòʼ-ţwòẕi֨yʼẇ maşá֤̇̂ʼ mi⁠báֽ̇ţé̇y⁠kem֙ bĕ̇⁠y֣wòm ha⁠şȧ̌bá̇֔ţ wĕ⁠kál-mĕláʼká֖h lò֣ʼ ţaֽʻàş֑̂ẇ wĕ⁠qidȧşĕ̌ţėm֙ ʼeţ-y֣wòm ha⁠şȧ̌bá̇֔ţ kȧ⁠ʼàşě֥r ẕiwi֖̇yţiy ʼeţ-ʼàbwòţéy⁠keֽm׃"],[17,23,"וְ⁠לֹ֣א שָֽׁמְע֔וּ וְ⁠לֹ֥א הִטּ֖וּ אֶת־אָזְנָ֑⁠ם וַ⁠יַּקְשׁוּ֙ אֶת־עָרְפָּ֔⁠ם לְ⁠בִלְתִּ֣י שומע וּ⁠לְ⁠בִלְתִּ֖י קַ֥חַת מוּסָֽר׃","wĕ⁠lò֣ʼ şáֽ̌mĕʻ֔ẇ wĕ⁠lò֥ʼ hiṫ֖ẇ ʼeţ-ʼázĕná֑⁠m wa⁠yȧqĕş̌ẇ֙ ʼeţ-ʻárĕpá̇֔⁠m lĕ⁠bilĕţi֣̇y şwmʻ ẇ⁠lĕ⁠bilĕţi֖̇y qa֥ẖaţ mẇsáֽr׃"],[17,24,"וְ֠⁠הָיָה אִם־שָׁמֹ֨עַ תִּשְׁמְע֤וּ⁠ן אֵלַ⁠י֙ נְאֻם־יְהוָ֔ה לְ⁠בִלְתִּ֣י ׀ הָבִ֣יא מַשָּׂ֗א בְּ⁠שַׁעֲרֵ֛י הָ⁠עִ֥יר הַ⁠זֹּ֖את בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֑ת וּ⁠לְ⁠קַדֵּשׁ֙ אֶת־י֣וֹם הַ⁠שַּׁבָּ֔ת לְ⁠בִלְתִּ֥י עֲשֽׂוֹת־ב⁠ה כָּל־מְלָאכָֽה׃","wĕ֠⁠háyáh ʼim-şá̌mò֨ʻa ţi̇şĕ̌mĕʻ֤ẇ⁠n ʼéla⁠y֙ nĕʼum-yĕhwá֔h lĕ⁠bilĕţi֣̇y ׀ hábi֣yʼ maşá̇̂֗ʼ bĕ̇⁠şǎʻàré֛y há⁠ʻi֥yr ha⁠zò֖̇ʼţ bĕ̇⁠y֣wòm ha⁠şȧ̌bá֑̇ţ ẇ⁠lĕ⁠qadé̇ş̌֙ ʼeţ-y֣wòm ha⁠şȧ̌bá̇֔ţ lĕ⁠bilĕţi֥̇y ʻàşֽ̂wòţ-b⁠h ká̇l-mĕláʼkáֽh׃"],[17,25,"וּ⁠בָ֣אוּ בְ⁠שַׁעֲרֵ֣י הָ⁠עִ֣יר הַ⁠זֹּ֡את מְלָכִ֣ים ׀ וְ⁠שָׂרִ֡ים יֹשְׁבִים֩ עַל־כִּסֵּ֨א דָוִ֜ד רֹכְבִ֣ים ׀ בָּ⁠רֶ֣כֶב וּ⁠בַ⁠סּוּסִ֗ים הֵ֚מָּה וְ⁠שָׂ֣רֵי⁠הֶ֔ם אִ֥ישׁ יְהוּדָ֖ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וְ⁠יָשְׁבָ֥ה הָֽ⁠עִיר־הַ⁠זֹּ֖את לְ⁠עוֹלָֽם׃","ẇ⁠bá֣ʼẇ bĕ⁠şǎʻàré֣y há⁠ʻi֣yr ha⁠zò̇֡ʼţ mĕláki֣ym ׀ wĕ⁠şá̂ri֡ym yòşĕ̌biym֩ ʻal-ki̇sé̇֨ʼ dáwi֜d ròkĕbi֣ym ׀ bá̇⁠re֣keb ẇ⁠ba⁠ṡẇsi֗ym hé֚má̇h wĕ⁠şá֣̂réy⁠he֔m ʼi֥yş̌ yĕhẇdá֖h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌liá֑m wĕ⁠yáşĕ̌bá֥h háֽ⁠ʻiyr-ha⁠zò֖̇ʼţ lĕ⁠ʻwòláֽm׃"],[17,26,"וּ⁠בָ֣אוּ מֵ⁠עָרֵֽי־יְ֠הוּדָה וּ⁠מִ⁠סְּבִיב֨וֹת יְרוּשָׁלִַ֜ם וּ⁠מֵ⁠אֶ֣רֶץ בִּנְיָמִ֗ן וּ⁠מִן־הַ⁠שְּׁפֵלָ֤ה וּ⁠מִן־הָ⁠הָר֙ וּ⁠מִן־הַ⁠נֶּ֔גֶב מְבִאִ֛ים עוֹלָ֥ה וְ⁠זֶ֖בַח וּ⁠מִנְחָ֣ה וּ⁠לְבוֹנָ֑ה וּ⁠מְבִאֵ֥י תוֹדָ֖ה בֵּ֥ית יְהוָֽה׃","ẇ⁠bá֣ʼẇ mé⁠ʻáréֽy-yĕ֠hẇdáh ẇ⁠mi⁠sĕ̇biyb֨wòţ yĕrẇşá̌lia֜m ẇ⁠mé⁠ʼe֣reẕ bi̇nĕyámi֗n ẇ⁠min-ha⁠şĕ̇̌pélá֤h ẇ⁠min-há⁠hár֙ ẇ⁠min-ha⁠nė֔geb mĕbiʼi֛ym ʻwòlá֥h wĕ⁠ze֖baẖ ẇ⁠minĕẖá֣h ẇ⁠lĕbwòná֑h ẇ⁠mĕbiʼé֥y ţwòdá֖h bé֥̇yţ yĕhwáֽh׃"],[17,27,"וְ⁠אִם־לֹ֨א תִשְׁמְע֜וּ אֵלַ֗⁠י לְ⁠קַדֵּשׁ֙ אֶת־י֣וֹם הַ⁠שַּׁבָּ֔ת וּ⁠לְ⁠בִלְתִּ֣י ׀ שְׂאֵ֣ת מַשָּׂ֗א וּ⁠בֹ֛א בְּ⁠שַׁעֲרֵ֥י יְרוּשָׁלִַ֖ם בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֑ת וְ⁠הִצַּ֧תִּי אֵ֣שׁ בִּ⁠שְׁעָרֶ֗י⁠הָ וְ⁠אָֽכְלָ֛ה אַרְמְנ֥וֹת יְרוּשָׁלִַ֖ם וְ⁠לֹ֥א תִכְבֶּֽה׃פ","wĕ⁠ʼim-lò֨ʼ ţişĕ̌mĕʻ֜ẇ ʼéla֗⁠y lĕ⁠qadé̇ş̌֙ ʼeţ-y֣wòm ha⁠şȧ̌bá̇֔ţ ẇ⁠lĕ⁠bilĕţi֣̇y ׀ şĕ̂ʼé֣ţ maşá̇̂֗ʼ ẇ⁠bò֛ʼ bĕ̇⁠şǎʻàré֥y yĕrẇşá̌lia֖m bĕ̇⁠y֣wòm ha⁠şȧ̌bá֑̇ţ wĕ⁠hiẕȧ֧ţi̇y ʼé֣ş̌ bi̇⁠şĕ̌ʻáre֗y⁠há wĕ⁠ʼáֽkĕlá֛h ʼarĕmĕn֥wòţ yĕrẇşá̌lia֖m wĕ⁠lò֥ʼ ţikĕbėֽh׃p"],[18,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר הָיָ֣ה אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","ha⁠dá̇bár֙ ʼàşě֣r háyá֣h ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[18,2,"ק֥וּם וְ⁠יָרַדְתָּ֖ בֵּ֣ית הַ⁠יּוֹצֵ֑ר וְ⁠שָׁ֖מָּ⁠ה אַשְׁמִֽיעֲ⁠ךָ֥ אֶת־דְּבָרָֽ⁠י׃","q֥ẇm wĕ⁠yáradĕţá֖̇ bé֣̇yţ ha⁠ẏwòẕé֑r wĕ⁠şá֖̌má̇⁠h ʼaşĕ̌miֽyʻà⁠ká֥ ʼeţ-dĕ̇báráֽ⁠y׃"],[18,3,"וָ⁠אֵרֵ֖ד בֵּ֣ית הַ⁠יּוֹצֵ֑ר ו⁠הנ⁠הו עֹשֶׂ֥ה מְלָאכָ֖ה עַל־הָ⁠אָבְנָֽיִם׃","wá⁠ʼéré֖d bé֣̇yţ ha⁠ẏwòẕé֑r w⁠hn⁠hw ʻòşê֥h mĕláʼká֖h ʻal-há⁠ʼábĕnáֽyim׃"],[18,4,"וְ⁠נִשְׁחַ֣ת הַ⁠כְּלִ֗י אֲשֶׁ֨ר ה֥וּא עֹשֶׂ֛ה בַּ⁠חֹ֖מֶר בְּ⁠יַ֣ד הַ⁠יּוֹצֵ֑ר וְ⁠שָׁ֗ב וַֽ⁠יַּעֲשֵׂ֨⁠הוּ֙ כְּלִ֣י אַחֵ֔ר כַּ⁠אֲשֶׁ֥ר יָשַׁ֛ר בְּ⁠עֵינֵ֥י הַ⁠יּוֹצֵ֖ר לַ⁠עֲשֽׂוֹת׃פ","wĕ⁠nişĕ̌ẖa֣ţ ha⁠kĕ̇li֗y ʼàşě֨r h֥ẇʼ ʻòşê֛h bȧ⁠ẖò֖mer bĕ̇⁠ya֣d ha⁠ẏwòẕé֑r wĕ⁠şá̌֗b waֽ⁠yȧʻàşé̂֨⁠hẇ֙ kĕ̇li֣y ʼaẖé֔r kȧ⁠ʼàşě֥r yáşǎ֛r bĕ̇⁠ʻéyné֥y ha⁠ẏwòẕé֖r la⁠ʻàşֽ̂wòţ׃p"],[18,5,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֽוֹר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmֽwòr׃"],[18,6,"הֲ⁠כַ⁠יּוֹצֵ֨ר הַ⁠זֶּ֜ה לֹא־אוּכַ֨ל לַ⁠עֲשׂ֥וֹת לָ⁠כֶ֛ם בֵּ֥ית יִשְׂרָאֵ֖ל נְאֻם־יְהוָ֑ה הִנֵּ֤ה כַ⁠חֹ֨מֶר֙ בְּ⁠יַ֣ד הַ⁠יּוֹצֵ֔ר כֵּן־אַתֶּ֥ם בְּ⁠יָדִ֖⁠י בֵּ֥ית יִשְׂרָאֵֽל׃ס","hà⁠ka⁠ẏwòẕé֨r ha⁠zė֜h lòʼ-ʼẇka֨l la⁠ʻàş֥̂wòţ lá⁠ke֛m bé֥̇yţ yişĕ̂ráʼé֖l nĕʼum-yĕhwá֑h hiné֤̇h ka⁠ẖò֨mer֙ bĕ̇⁠ya֣d ha⁠ẏwòẕé֔r ké̇n-ʼaţė֥m bĕ̇⁠yádi֖⁠y bé֥̇yţ yişĕ̂ráʼéֽl׃s"],[18,7,"רֶ֣גַע אֲדַבֵּ֔ר עַל־גּ֖וֹי וְ⁠עַל־מַמְלָכָ֑ה לִ⁠נְת֥וֹשׁ וְ⁠לִ⁠נְת֖וֹץ וּֽ⁠לְ⁠הַאֲבִֽיד׃","re֣gaʻ ʼàdabé̇֔r ʻal-ġ֖wòy wĕ⁠ʻal-mamĕláká֑h li⁠nĕţ֥wòş̌ wĕ⁠li⁠nĕţ֖wòẕ ẇֽ⁠lĕ⁠haʼàbiֽyd׃"],[18,8,"וְ⁠שָׁב֙ הַ⁠גּ֣וֹי הַ⁠ה֔וּא מֵ⁠רָ֣עָת֔⁠וֹ אֲשֶׁ֥ר דִּבַּ֖רְתִּי עָלָ֑י⁠ו וְ⁠נִֽחַמְתִּי֙ עַל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר חָשַׁ֖בְתִּי לַ⁠עֲשׂ֥וֹת לֽ⁠וֹ׃ס","wĕ⁠şá̌b֙ ha⁠ġ֣wòy ha⁠h֔ẇʼ mé⁠rá֣ʻáţ֔⁠wò ʼàşě֥r di̇bȧ֖rĕţi̇y ʻálá֑y⁠w wĕ⁠niֽẖamĕţi̇y֙ ʻal-há֣⁠ráʻá֔h ʼàşě֥r ẖáşǎ֖bĕţi̇y la⁠ʻàş֥̂wòţ lֽ⁠wò׃s"],[18,9,"וְ⁠רֶ֣גַע אֲדַבֵּ֔ר עַל־גּ֖וֹי וְ⁠עַל־מַמְלָכָ֑ה לִ⁠בְנֹ֖ת וְ⁠לִ⁠נְטֹֽעַ׃","wĕ⁠re֣gaʻ ʼàdabé̇֔r ʻal-ġ֖wòy wĕ⁠ʻal-mamĕláká֑h li⁠bĕnò֖ţ wĕ⁠li⁠nĕtòֽʻa׃"],[18,10,"וְ⁠עָשָׂ֤ה ה⁠רעה בְּ⁠עֵינַ֔⁠י לְ⁠בִלְתִּ֖י שְׁמֹ֣עַ בְּ⁠קוֹלִ֑⁠י וְ⁠נִֽחַמְתִּי֙ עַל־הַ⁠טּוֹבָ֔ה אֲשֶׁ֥ר אָמַ֖רְתִּי לְ⁠הֵיטִ֥יב אוֹתֽ⁠וֹ׃ס","wĕ⁠ʻáşá֤̂h h⁠rʻh bĕ̇⁠ʻéyna֔⁠y lĕ⁠bilĕţi֖̇y şĕ̌mò֣ʻa bĕ̇⁠qwòli֑⁠y wĕ⁠niֽẖamĕţi̇y֙ ʻal-ha⁠ṫwòbá֔h ʼàşě֥r ʼáma֖rĕţi̇y lĕ⁠héyti֥yb ʼwòţֽ⁠wò׃s"],[18,11,"וְ⁠עַתָּ֡ה אֱמָר־נָ֣א אֶל־אִישׁ־יְהוּדָה֩ וְ⁠עַל־יוֹשְׁבֵ֨י יְרוּשָׁלִַ֜ם לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנֵּ֨ה אָנֹכִ֜י יוֹצֵ֤ר עֲלֵי⁠כֶם֙ רָעָ֔ה וְ⁠חֹשֵׁ֥ב עֲלֵי⁠כֶ֖ם מַֽחֲשָׁבָ֑ה שׁ֣וּבוּ נָ֗א אִ֚ישׁ מִ⁠דַּרְכּ֣⁠וֹ הָֽ⁠רָעָ֔ה וְ⁠הֵיטִ֥יבוּ דַרְכֵי⁠כֶ֖ם וּ⁠מַעַלְלֵי⁠כֶֽם׃","wĕ⁠ʻaţá̇֡h ʼèmár-ná֣ʼ ʼel-ʼiyş̌-yĕhẇdáh֩ wĕ⁠ʻal-ywòşĕ̌bé֨y yĕrẇşá̌lia֜m lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h hiné̇֨h ʼánòki֜y ywòẕé֤r ʻàléy⁠kem֙ ráʻá֔h wĕ⁠ẖòşé֥̌b ʻàléy⁠ke֖m maֽẖàşá̌bá֑h ş֣̌ẇbẇ ná֗ʼ ʼi֚yş̌ mi⁠dȧrĕk֣̇⁠wò háֽ⁠ráʻá֔h wĕ⁠héyti֥ybẇ darĕkéy⁠ke֖m ẇ⁠maʻalĕléy⁠keֽm׃"],[18,12,"וְ⁠אָמְר֖וּ נוֹאָ֑שׁ כִּֽי־אַחֲרֵ֤י מַחְשְׁבוֹתֵ֨י⁠נוּ֙ נֵלֵ֔ךְ וְ⁠אִ֛ישׁ שְׁרִר֥וּת לִבּֽ⁠וֹ־הָ⁠רָ֖ע נַעֲשֶֽׂה׃ס","wĕ⁠ʼámĕr֖ẇ nwòʼá֑ş̌ kiֽ̇y-ʼaẖàré֤y maẖĕşĕ̌bwòţé֨y⁠nẇ֙ nélé֔kĕ wĕ⁠ʼi֛yş̌ şĕ̌rir֥ẇţ liḃֽ⁠wò-há⁠rá֖ʻ naʻàşêֽh׃s"],[18,13,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה שַֽׁאֲלוּ־נָא֙ בַּ⁠גּוֹיִ֔ם מִ֥י שָׁמַ֖ע כָּ⁠אֵ֑לֶּה שַֽׁעֲרֻרִת֙ עָשְׂתָ֣ה מְאֹ֔ד בְּתוּלַ֖ת יִשְׂרָאֵֽל׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h şǎֽʼàlẇ-náʼ֙ bȧ⁠ġwòyi֔m mi֥y şá̌ma֖ʻ ká̇⁠ʼé֑lėh şǎֽʻàruriţ֙ ʻáşĕ̂ţá֣h mĕʼò֔d bĕ̇ţẇla֖ţ yişĕ̂ráʼéֽl׃"],[18,14,"הֲ⁠יַעֲזֹ֥ב מִ⁠צּ֛וּר שָׂדַ֖י שֶׁ֣לֶג לְבָנ֑וֹן אִם־יִנָּתְשׁ֗וּ מַ֛יִם זָרִ֥ים קָרִ֖ים נוֹזְלִֽים׃","hà⁠yaʻàzò֥b mi⁠ẕ֛̇ẇr şá̂da֖y şě֣leg lĕbán֑wòn ʼim-yiná̇ţĕş̌֗ẇ ma֛yim zári֥ym qári֖ym nwòzĕliֽym׃"],[18,15,"כִּֽי־שְׁכֵחֻ֥⁠נִי עַמִּ֖⁠י לַ⁠שָּׁ֣וְא יְקַטֵּ֑רוּ וַ⁠יַּכְשִׁל֤וּ⁠ם בְּ⁠דַרְכֵי⁠הֶם֙ שְׁבִילֵ֣י עוֹלָ֔ם לָ⁠לֶ֣כֶת נְתִיב֔וֹת דֶּ֖רֶךְ לֹ֥א סְלוּלָֽה׃","kiֽ̇y-şĕ̌kéẖu֥⁠niy ʻami֖̇⁠y la⁠şá֣̇̌wĕʼ yĕqaté֑̇rẇ wa⁠yȧkĕşǐl֤ẇ⁠m bĕ̇⁠darĕkéy⁠hem֙ şĕ̌biylé֣y ʻwòlá֔m lá⁠le֣keţ nĕţiyb֔wòţ dė֖rekĕ lò֥ʼ sĕlẇláֽh׃"],[18,16,"לָ⁠שׂ֥וּם אַרְצָ֛⁠ם לְ⁠שַׁמָּ֖ה שרוקת עוֹלָ֑ם כֹּ֚ל עוֹבֵ֣ר עָלֶ֔י⁠הָ יִשֹּׁ֖ם וְ⁠יָנִ֥יד בְּ⁠רֹאשֽׁ⁠וֹ׃","lá⁠ş֥̂ẇm ʼarĕẕá֛⁠m lĕ⁠şǎmá֖̇h şrwqţ ʻwòlá֑m kò֚̇l ʻwòbé֣r ʻále֔y⁠há yişò֖̇̌m wĕ⁠yáni֥yd bĕ̇⁠ròʼşֽ̌⁠wò׃"],[18,17,"כְּ⁠רֽוּחַ־קָדִ֥ים אֲפִיצֵ֖⁠ם לִ⁠פְנֵ֣י אוֹיֵ֑ב עֹ֧רֶף וְ⁠לֹֽא־פָנִ֛ים אֶרְאֵ֖⁠ם בְּ⁠י֥וֹם אֵידָֽ⁠ם׃ס","kĕ̇⁠rֽẇẖa-qádi֥ym ʼàpiyẕé֖⁠m li⁠pĕné֣y ʼwòyé֑b ʻò֧rep wĕ⁠lòֽʼ-páni֛ym ʼerĕʼé֖⁠m bĕ̇⁠y֥wòm ʼéydáֽ⁠m׃s"],[18,18,"וַ⁠יֹּאמְר֗וּ לְכ֨וּ וְ⁠נַחְשְׁבָ֣ה עַֽל־יִרְמְיָהוּ֮ מַחֲשָׁבוֹת֒ כִּי֩ לֹא־תֹאבַ֨ד תּוֹרָ֜ה מִ⁠כֹּהֵ֗ן וְ⁠עֵצָה֙ מֵֽ⁠חָכָ֔ם וְ⁠דָבָ֖ר מִ⁠נָּבִ֑יא לְכוּ֙ וְ⁠נַכֵּ֣⁠הוּ בַ⁠לָּשׁ֔וֹן וְ⁠אַל־נַקְשִׁ֖יבָה אֶל־כָּל־דְּבָרָֽי⁠ו׃","wa⁠yò̇ʼmĕr֗ẇ lĕk֨ẇ wĕ⁠naẖĕşĕ̌bá֣h ʻaֽl-yirĕmĕyáhẇ֮ maẖàşá̌bwòţ֒ ki̇y֩ lòʼ-ţòʼba֨d ţ̇wòrá֜h mi⁠kò̇hé֗n wĕ⁠ʻéẕáh֙ méֽ⁠ẖáká֔m wĕ⁠dábá֖r mi⁠ná̇bi֑yʼ lĕkẇ֙ wĕ⁠naké֣̇⁠hẇ ba⁠lá̇ş̌֔wòn wĕ⁠ʼal-naqĕşǐ֖ybáh ʼel-ká̇l-dĕ̇báráֽy⁠w׃"],[18,19,"הַקְשִׁ֥יבָ⁠ה יְהוָ֖ה אֵלָ֑⁠י וּ⁠שְׁמַ֖ע לְ⁠ק֥וֹל יְרִיבָֽ⁠י׃","haqĕşǐ֥ybá⁠h yĕhwá֖h ʼélá֑⁠y ẇ⁠şĕ̌ma֖ʻ lĕ⁠q֥wòl yĕriybáֽ⁠y׃"],[18,20,"הַ⁠יְשֻׁלַּ֤ם תַּֽחַת־טוֹבָה֙ רָעָ֔ה כִּֽי־כָר֥וּ שׁוּחָ֖ה לְ⁠נַפְשִׁ֑⁠י זְכֹ֣ר ׀ עָמְדִ֣⁠י לְ⁠פָנֶ֗י⁠ךָ לְ⁠דַבֵּ֤ר עֲלֵי⁠הֶם֙ טוֹבָ֔ה לְ⁠הָשִׁ֥יב אֶת־חֲמָתְ⁠ךָ֖ מֵ⁠הֶֽם׃","ha⁠yĕşǔlȧ֤m ţȧֽẖaţ-twòbáh֙ ráʻá֔h kiֽ̇y-kár֥ẇ ş̌ẇẖá֖h lĕ⁠napĕşǐ֑⁠y zĕkò֣r ׀ ʻámĕdi֣⁠y lĕ⁠páne֗y⁠ká lĕ⁠dabé֤̇r ʻàléy⁠hem֙ twòbá֔h lĕ⁠háşǐ֥yb ʼeţ-ẖàmáţĕ⁠ká֖ mé⁠heֽm׃"],[18,21,"לָ⁠כֵן֩ תֵּ֨ן אֶת־בְּנֵי⁠הֶ֜ם לָ⁠רָעָ֗ב וְ⁠הַגִּרֵ⁠ם֮ עַל־יְדֵי־חֶרֶב֒ וְ⁠תִֽהְיֶ֨נָה נְשֵׁי⁠הֶ֤ם שַׁכֻּלוֹת֙ וְ⁠אַלְמָנ֔וֹת וְ⁠אַ֨נְשֵׁי⁠הֶ֔ם יִֽהְי֖וּ הֲרֻ֣גֵי מָ֑וֶת בַּח֣וּרֵי⁠הֶ֔ם מֻכֵּי־חֶ֖רֶב בַּ⁠מִּלְחָמָֽה׃","lá⁠kén֩ ţé̇֨n ʼeţ-bĕ̇néy⁠he֜m lá⁠ráʻá֗b wĕ⁠hagi̇ré⁠m֮ ʻal-yĕdéy-ẖereb֒ wĕ⁠ţiֽhĕye֨náh nĕşé̌y⁠he֤m şǎku̇lwòţ֙ wĕ⁠ʼalĕmán֔wòţ wĕ⁠ʼa֨nĕşé̌y⁠he֔m yiֽhĕy֖ẇ hàru֣géy má֑weţ bȧẖ֣ẇréy⁠he֔m muké̇y-ẖe֖reb bȧ⁠mi̇lĕẖámáֽh׃"],[18,22,"תִּשָּׁמַ֤ע זְעָקָה֙ מִ⁠בָּ֣תֵּי⁠הֶ֔ם כִּֽי־תָבִ֧יא עֲלֵי⁠הֶ֛ם גְּד֖וּד פִּתְאֹ֑ם כִּֽי־כָר֤וּ שיחה לְ⁠לָכְדֵ֔⁠נִי וּ⁠פַחִ֖ים טָמְנ֥וּ לְ⁠רַגְלָֽ⁠י׃","ţi̇şá̇̌ma֤ʻ zĕʻáqáh֙ mi⁠bá֣̇ţé̇y⁠he֔m kiֽ̇y-ţábi֧yʼ ʻàléy⁠he֛m gĕ̇d֖ẇd pi̇ţĕʼò֑m kiֽ̇y-kár֤ẇ şyẖh lĕ⁠lákĕdé֔⁠niy ẇ⁠paẖi֖ym támĕn֥ẇ lĕ⁠ragĕláֽ⁠y׃"],[18,23,"וְ⁠אַתָּ֣ה יְ֠הוָה יָדַ֜עְתָּ אֶֽת־כָּל־עֲצָתָ֤⁠ם עָלַ⁠י֙ לַ⁠מָּ֔וֶת אַל־תְּכַפֵּר֙ עַל־עֲוֺנָ֔⁠ם וְ⁠חַטָּאתָ֖⁠ם מִ⁠לְּ⁠פָנֶ֣י⁠ךָ אַל־תֶּ֑מְחִי ו⁠היו מֻכְשָׁלִים֙ לְ⁠פָנֶ֔י⁠ךָ בְּ⁠עֵ֥ת אַפְּ⁠ךָ֖ עֲשֵׂ֥ה בָ⁠הֶֽם׃ס","wĕ⁠ʼaţá֣̇h yĕ֠hwáh yáda֜ʻĕţá̇ ʼeֽţ-ká̇l-ʻàẕáţá֤⁠m ʻála⁠y֙ la⁠má̇֔weţ ʼal-ţĕ̇kapé̇r֙ ʻal-ʻàwֺná֔⁠m wĕ⁠ẖatá̇ʼţá֖⁠m mi⁠lĕ̇⁠páne֣y⁠ká ʼal-ţė֑mĕẖiy w⁠hyw mukĕşá̌liym֙ lĕ⁠páne֔y⁠ká bĕ̇⁠ʻé֥ţ ʼapĕ̇⁠ká֖ ʻàşé֥̂h bá⁠heֽm׃s"],[19,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הָל֛וֹךְ וְ⁠קָנִ֥יתָ בַקְבֻּ֖ק יוֹצֵ֣ר חָ֑רֶשׂ וּ⁠מִ⁠זִּקְנֵ֣י הָ⁠עָ֔ם וּ⁠מִ⁠זִּקְנֵ֖י הַ⁠כֹּהֲנִֽים׃","kò֚̇h ʼáma֣r yĕhwá֔h hál֛wòkĕ wĕ⁠qáni֥yţá baqĕbu֖̇q ywòẕé֣r ẖá֑reş̂ ẇ⁠mi⁠zi̇qĕné֣y há⁠ʻá֔m ẇ⁠mi⁠zi̇qĕné֖y ha⁠kò̇hàniֽym׃"],[19,2,"וְ⁠יָצָ֨אתָ֙ אֶל־גֵּ֣יא בֶן־הִנֹּ֔ם אֲשֶׁ֕ר פֶּ֖תַח שַׁ֣עַר ה⁠חרסות וְ⁠קָרָ֣אתָ שָּׁ֔ם אֶת־הַ⁠דְּבָרִ֖ים אֲשֶׁר־אֲדַבֵּ֥ר אֵלֶֽי⁠ךָ׃","wĕ⁠yáẕá֨ʼţá֙ ʼel-gé֣̇yʼ ben-hinò̇֔m ʼàşě֕r pė֖ţaẖ şǎ֣ʻar h⁠ẖrswţ wĕ⁠qárá֣ʼţá şá̇̌֔m ʼeţ-ha⁠dĕ̇bári֖ym ʼàşěr-ʼàdabé֥̇r ʼéleֽy⁠ká׃"],[19,3,"וְ⁠אָֽמַרְתָּ֙ שִׁמְע֣וּ דְבַר־יְהוָ֔ה מַלְכֵ֣י יְהוּדָ֔ה וְ⁠יֹשְׁבֵ֖י יְרֽוּשָׁלִָ֑ם כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הִנְ⁠נִ֨י מֵבִ֤יא רָעָה֙ עַל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה אֲשֶׁ֥ר כָּל־שֹׁמְעָ֖⁠הּ תִּצַּ֥לְנָה אָזְנָֽי⁠ו׃","wĕ⁠ʼáֽmarĕţá̇֙ şǐmĕʻ֣ẇ dĕbar-yĕhwá֔h malĕké֣y yĕhẇdá֔h wĕ⁠yòşĕ̌bé֖y yĕrֽẇşá̌liá֑m kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l hinĕ⁠ni֨y mébi֤yʼ ráʻáh֙ ʻal-ha⁠má̇q֣wòm ha⁠zė֔h ʼàşě֥r ká̇l-şò̌mĕʻá֖⁠ḣ ţi̇ẕȧ֥lĕnáh ʼázĕnáֽy⁠w׃"],[19,4,"יַ֣עַן ׀ אֲשֶׁ֣ר עֲזָבֻ֗⁠נִי וַֽ⁠יְנַכְּר֞וּ אֶת־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ וַ⁠יְקַטְּרוּ־ב⁠וֹ֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים אֲשֶׁ֧ר לֹֽא־יְדָע֛וּ⁠ם הֵ֥מָּה וַ⁠אֲבֽוֹתֵי⁠הֶ֖ם וּ⁠מַלְכֵ֣י יְהוּדָ֑ה וּ⁠מָֽלְא֛וּ אֶת־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה דַּ֥ם נְקִיִּֽם׃","ya֣ʻan ׀ ʼàşě֣r ʻàzábu֗⁠niy waֽ⁠yĕnakĕ̇r֞ẇ ʼeţ-ha⁠má̇q֤wòm ha⁠zėh֙ wa⁠yĕqatĕ̇rẇ-b⁠wò֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym ʼàşě֧r lòֽʼ-yĕdáʻ֛ẇ⁠m hé֥má̇h wa⁠ʼàbֽwòţéy⁠he֖m ẇ⁠malĕké֣y yĕhẇdá֑h ẇ⁠máֽlĕʼ֛ẇ ʼeţ-ha⁠má̇q֥wòm ha⁠zė֖h dȧ֥m nĕqiyiֽ̇m׃"],[19,5,"וּ⁠בָנ֞וּ אֶת־בָּמ֣וֹת הַ⁠בַּ֗עַל לִ⁠שְׂרֹ֧ף אֶת־בְּנֵי⁠הֶ֛ם בָּ⁠אֵ֖שׁ עֹל֣וֹת לַ⁠בָּ֑עַל אֲשֶׁ֤ר לֹֽא־צִוִּ֨יתִי֙ וְ⁠לֹ֣א דִבַּ֔רְתִּי וְ⁠לֹ֥א עָלְתָ֖ה עַל־לִבִּֽ⁠י׃פ","ẇ⁠bán֞ẇ ʼeţ-bá̇m֣wòţ ha⁠bȧ֗ʻal li⁠şĕ̂rò֧p ʼeţ-bĕ̇néy⁠he֛m bá̇⁠ʼé֖ş̌ ʻòl֣wòţ la⁠bá֑̇ʻal ʼàşě֤r lòֽʼ-ẕiwi̇֨yţiy֙ wĕ⁠lò֣ʼ dibȧ֔rĕţi̇y wĕ⁠lò֥ʼ ʻálĕţá֖h ʻal-libiֽ̇⁠y׃p"],[19,6,"לָ⁠כֵ֞ן הִנֵּֽה־יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וְ⁠לֹא־יִקָּרֵא֩ לַ⁠מָּק֨וֹם הַ⁠זֶּ֥ה ע֛וֹד הַ⁠תֹּ֖פֶת וְ⁠גֵ֣יא בֶן־הִנֹּ֑ם כִּ֖י אִם־גֵּ֥יא הַ⁠הֲרֵגָֽה׃","lá⁠ké֞n hinéֽ̇h-yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wĕ⁠lòʼ-yiqá̇réʼ֩ la⁠má̇q֨wòm ha⁠zė֥h ʻ֛wòd ha⁠ţò֖̇peţ wĕ⁠gé֣yʼ ben-hinò֑̇m ki֖̇y ʼim-gé֥̇yʼ ha⁠hàrégáֽh׃"],[19,7,"וּ֠⁠בַקֹּתִי אֶת־עֲצַ֨ת יְהוּדָ֤ה וִ⁠ירוּשָׁלִַ֨ם֙ בַּ⁠מָּק֣וֹם הַ⁠זֶּ֔ה וְ⁠הִפַּלְתִּ֤י⁠ם בַּ⁠חֶ֨רֶב֙ לִ⁠פְנֵ֣י אֹֽיְבֵי⁠הֶ֔ם וּ⁠בְ⁠יַ֖ד מְבַקְשֵׁ֣י נַפְשָׁ֑⁠ם וְ⁠נָתַתִּ֤י אֶת־נִבְלָתָ⁠ם֙ לְ⁠מַֽאֲכָ֔ל לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֥ת הָ⁠אָֽרֶץ׃","ẇ֠⁠baqò̇ţiy ʼeţ-ʻàẕa֨ţ yĕhẇdá֤h wi⁠yrẇşá̌lia֨m֙ bȧ⁠má̇q֣wòm ha⁠zė֔h wĕ⁠hipȧlĕţi֤̇y⁠m bȧ⁠ẖe֨reb֙ li⁠pĕné֣y ʼòֽyĕbéy⁠he֔m ẇ⁠bĕ⁠ya֖d mĕbaqĕşé֣̌y napĕşá֑̌⁠m wĕ⁠náţaţi֤̇y ʼeţ-nibĕláţá⁠m֙ lĕ⁠maֽʼàká֔l lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֥ţ há⁠ʼáֽreẕ׃"],[19,8,"וְ⁠שַׂמְתִּי֙ אֶת־הָ⁠עִ֣יר הַ⁠זֹּ֔את לְ⁠שַׁמָּ֖ה וְ⁠לִ⁠שְׁרֵקָ֑ה כֹּ֚ל עֹבֵ֣ר עָלֶ֔י⁠הָ יִשֹּׁ֥ם וְ⁠יִשְׁרֹ֖ק עַל־כָּל־מַכֹּתֶֽ⁠הָ׃","wĕ⁠şâmĕţi̇y֙ ʼeţ-há⁠ʻi֣yr ha⁠zò̇֔ʼţ lĕ⁠şǎmá֖̇h wĕ⁠li⁠şĕ̌réqá֑h kò֚̇l ʻòbé֣r ʻále֔y⁠há yişò֥̇̌m wĕ⁠yişĕ̌rò֖q ʻal-ká̇l-makò̇ţeֽ⁠há׃"],[19,9,"וְ⁠הַֽאֲכַלְתִּ֞י⁠ם אֶת־בְּשַׂ֣ר בְּנֵי⁠הֶ֗ם וְ⁠אֵת֙ בְּשַׂ֣ר בְּנֹתֵי⁠הֶ֔ם וְ⁠אִ֥ישׁ בְּשַׂר־רֵעֵ֖⁠הוּ יֹאכֵ֑לוּ בְּ⁠מָצוֹר֙ וּ⁠בְ⁠מָצ֔וֹק אֲשֶׁ֨ר יָצִ֧יקוּ לָ⁠הֶ֛ם אֹיְבֵי⁠הֶ֖ם וּ⁠מְבַקְשֵׁ֥י נַפְשָֽׁ⁠ם׃","wĕ⁠haֽʼàkalĕţi̇֞y⁠m ʼeţ-bĕ̇şâ֣r bĕ̇néy⁠he֗m wĕ⁠ʼéţ֙ bĕ̇şâ֣r bĕ̇nòţéy⁠he֔m wĕ⁠ʼi֥yş̌ bĕ̇şâr-réʻé֖⁠hẇ yòʼké֑lẇ bĕ̇⁠máẕwòr֙ ẇ⁠bĕ⁠máẕ֔wòq ʼàşě֨r yáẕi֧yqẇ lá⁠he֛m ʼòyĕbéy⁠he֖m ẇ⁠mĕbaqĕşé֥̌y napĕşáֽ̌⁠m׃"],[19,10,"וְ⁠שָׁבַרְתָּ֖ הַ⁠בַּקְבֻּ֑ק לְ⁠עֵינֵי֙ הָֽ⁠אֲנָשִׁ֔ים הַ⁠הֹלְכִ֖ים אוֹתָֽ⁠ךְ׃","wĕ⁠şá̌barĕţá֖̇ ha⁠bȧqĕbu֑̇q lĕ⁠ʻéynéy֙ háֽ⁠ʼànáşǐ֔ym ha⁠hòlĕki֖ym ʼwòţáֽ⁠kĕ׃"],[19,11,"וְ⁠אָמַרְתָּ֨ אֲלֵי⁠הֶ֜ם כֹּה־אָמַ֣ר ׀ יְהוָ֣ה צְבָא֗וֹת כָּ֣כָה אֶשְׁבֹּ֞ר אֶת־הָ⁠עָ֤ם הַ⁠זֶּה֙ וְ⁠אֶת־הָ⁠עִ֣יר הַ⁠זֹּ֔את כַּ⁠אֲשֶׁ֤ר יִשְׁבֹּר֙ אֶת־כְּלִ֣י הַ⁠יּוֹצֵ֔ר אֲשֶׁ֛ר לֹֽא־יוּכַ֥ל לְ⁠הֵרָפֵ֖ה ע֑וֹד וּ⁠בְ⁠תֹ֣פֶת יִקְבְּר֔וּ מֵ⁠אֵ֥ין מָק֖וֹם לִ⁠קְבּֽוֹר׃","wĕ⁠ʼámarĕţá̇֨ ʼàléy⁠he֜m kò̇h-ʼáma֣r ׀ yĕhwá֣h ẕĕbáʼ֗wòţ ká֣̇káh ʼeşĕ̌bò̇֞r ʼeţ-há⁠ʻá֤m ha⁠zėh֙ wĕ⁠ʼeţ-há⁠ʻi֣yr ha⁠zò̇֔ʼţ kȧ⁠ʼàşě֤r yişĕ̌bò̇r֙ ʼeţ-kĕ̇li֣y ha⁠ẏwòẕé֔r ʼàşě֛r lòֽʼ-yẇka֥l lĕ⁠hérápé֖h ʻ֑wòd ẇ⁠bĕ⁠ţò֣peţ yiqĕbĕ̇r֔ẇ mé⁠ʼé֥yn máq֖wòm li⁠qĕḃֽwòr׃"],[19,12,"כֵּֽן־אֶעֱשֶׂ֞ה לַ⁠מָּק֥וֹם הַ⁠זֶּ֛ה נְאֻם־יְהוָ֖ה וּ⁠לְ⁠יֽוֹשְׁבָ֑י⁠ו וְ⁠לָ⁠תֵ֛ת אֶת־הָ⁠עִ֥יר הַ⁠זֹּ֖את כְּ⁠תֹֽפֶת׃","kéֽ̇n-ʼeʻèşê֞h la⁠má̇q֥wòm ha⁠zė֛h nĕʼum-yĕhwá֖h ẇ⁠lĕ⁠yֽwòşĕ̌bá֑y⁠w wĕ⁠lá⁠ţé֛ţ ʼeţ-há⁠ʻi֥yr ha⁠zò֖̇ʼţ kĕ̇⁠ţòֽpeţ׃"],[19,13,"וְ⁠הָי֞וּ בָּתֵּ֣י יְרוּשָׁלִַ֗ם וּ⁠בָתֵּי֙ מַלְכֵ֣י יְהוּדָ֔ה כִּ⁠מְק֥וֹם הַ⁠תֹּ֖פֶת הַ⁠טְּמֵאִ֑ים לְ⁠כֹ֣ל הַ⁠בָּתִּ֗ים אֲשֶׁ֨ר קִטְּר֜וּ עַל־גַּגֹּֽתֵי⁠הֶם֙ לְ⁠כֹל֙ צְבָ֣א הַ⁠שָּׁמַ֔יִם וְ⁠הַסֵּ֥ךְ נְסָכִ֖ים לֵ⁠אלֹהִ֥ים אֲחֵרִֽים׃פ","wĕ⁠háy֞ẇ bá̇ţé֣̇y yĕrẇşá̌lia֗m ẇ⁠báţé̇y֙ malĕké֣y yĕhẇdá֔h ki̇⁠mĕq֥wòm ha⁠ţò֖̇peţ ha⁠tĕ̇méʼi֑ym lĕ⁠kò֣l ha⁠bá̇ţi̇֗ym ʼàşě֨r qitĕ̇r֜ẇ ʻal-gȧgòֽ̇ţéy⁠hem֙ lĕ⁠kòl֙ ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim wĕ⁠hasé֥̇kĕ nĕsáki֖ym lé⁠ʼlòhi֥ym ʼàẖériֽym׃p"],[19,14,"וַ⁠יָּבֹ֤א יִרְמְיָ֨הוּ֙ מֵֽ⁠הַ⁠תֹּ֔פֶת אֲשֶׁ֨ר שְׁלָח֧⁠וֹ יְהוָ֛ה שָׁ֖ם לְ⁠הִנָּבֵ֑א וַֽ⁠יַּעֲמֹד֙ בַּ⁠חֲצַ֣ר בֵּית־יְהוָ֔ה וַ⁠יֹּ֖אמֶר אֶל־כָּל־הָ⁠עָֽם׃ס","wa⁠yá̇bò֤ʼ yirĕmĕyá֨hẇ֙ méֽ⁠ha⁠ţò̇֔peţ ʼàşě֨r şĕ̌láẖ֧⁠wò yĕhwá֛h şá֖̌m lĕ⁠hiná̇bé֑ʼ waֽ⁠yȧʻàmòd֙ bȧ⁠ẖàẕa֣r bé̇yţ-yĕhwá֔h wa⁠yò֖̇ʼmer ʼel-ká̇l-há⁠ʻáֽm׃s"],[19,15,"כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֨י מבי אֶל־הָ⁠עִ֤יר הַ⁠זֹּאת֙ וְ⁠עַל־כָּל־עָרֶ֔י⁠הָ אֵ֚ת כָּל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר דִּבַּ֖רְתִּי עָלֶ֑י⁠הָ כִּ֤י הִקְשׁוּ֙ אֶת־עָרְפָּ֔⁠ם לְ⁠בִלְתִּ֖י שְׁמ֥וֹעַ אֶת־דְּבָרָֽ⁠י׃","kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֨y mby ʼel-há⁠ʻi֤yr ha⁠zò̇ʼţ֙ wĕ⁠ʻal-ká̇l-ʻáre֔y⁠há ʼé֚ţ ká̇l-há֣⁠ráʻá֔h ʼàşě֥r di̇bȧ֖rĕţi̇y ʻále֑y⁠há ki֤̇y hiqĕş̌ẇ֙ ʼeţ-ʻárĕpá̇֔⁠m lĕ⁠bilĕţi֖̇y şĕ̌m֥wòʻa ʼeţ-dĕ̇báráֽ⁠y׃"],[20,1,"וַ⁠יִּשְׁמַ֤ע פַּשְׁחוּר֙ בֶּן־אִמֵּ֣ר הַ⁠כֹּהֵ֔ן וְ⁠הֽוּא־פָקִ֥יד נָגִ֖יד בְּ⁠בֵ֣ית יְהוָ֑ה אֶֽת־יִרְמְיָ֔הוּ נִבָּ֖א אֶת־הַ⁠דְּבָרִ֥ים הָ⁠אֵֽלֶּה׃","wa⁠yi̇şĕ̌ma֤ʻ pȧşĕ̌ẖẇr֙ bėn-ʼimé֣̇r ha⁠kò̇hé֔n wĕ⁠hֽẇʼ-páqi֥yd nági֖yd bĕ̇⁠bé֣yţ yĕhwá֑h ʼeֽţ-yirĕmĕyá֔hẇ nibá֖̇ʼ ʼeţ-ha⁠dĕ̇bári֥ym há⁠ʼéֽlėh׃"],[20,2,"וַ⁠יַּכֶּ֣ה פַשְׁח֔וּר אֵ֖ת יִרְמְיָ֣הוּ הַ⁠נָּבִ֑יא וַ⁠יִּתֵּ֨ן אֹת֜⁠וֹ עַל־הַ⁠מַּהְפֶּ֗כֶת אֲשֶׁ֨ר בְּ⁠שַׁ֤עַר בִּנְיָמִן֙ הָֽ⁠עֶלְי֔וֹן אֲשֶׁ֖ר בְּ⁠בֵ֥ית יְהוָֽה׃","wa⁠yȧkė֣h paşĕ̌ẖ֔ẇr ʼé֖ţ yirĕmĕyá֣hẇ ha⁠ná̇bi֑yʼ wa⁠yi̇ţé̇֨n ʼòţ֜⁠wò ʻal-ha⁠mȧhĕpė֗keţ ʼàşě֨r bĕ̇⁠şǎ֤ʻar bi̇nĕyámin֙ háֽ⁠ʻelĕy֔wòn ʼàşě֖r bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[20,3,"וַֽ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יֹּצֵ֥א פַשְׁח֛וּר אֶֽת־יִרְמְיָ֖הוּ מִן־הַ⁠מַּהְפָּ֑כֶת וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו יִרְמְיָ֗הוּ לֹ֤א פַשְׁחוּר֙ קָרָ֤א יְהוָה֙ שְׁמֶ֔⁠ךָ כִּ֖י אִם־מָג֥וֹר מִ⁠סָּבִֽיב׃פ","waֽ⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yò̇ẕé֥ʼ paşĕ̌ẖ֛ẇr ʼeֽţ-yirĕmĕyá֖hẇ min-ha⁠mȧhĕpá֑̇keţ wa⁠yò̇֨ʼmer ʼélá֜y⁠w yirĕmĕyá֗hẇ lò֤ʼ paşĕ̌ẖẇr֙ qárá֤ʼ yĕhwáh֙ şĕ̌me֔⁠ká ki֖̇y ʼim-mág֥wòr mi⁠sá̇biֽyb׃p"],[20,4,"כִּ֣י כֹ֣ה אָמַ֣ר יְהוָ֡ה הִנְ⁠נִי֩ נֹתֶנְ⁠ךָ֨ לְ⁠מָג֜וֹר לְ⁠ךָ֣ וּ⁠לְ⁠כָל־אֹהֲבֶ֗י⁠ךָ וְ⁠נָֽפְל֛וּ בְּ⁠חֶ֥רֶב אֹיְבֵי⁠הֶ֖ם וְ⁠עֵינֶ֣י⁠ךָ רֹא֑וֹת וְ⁠אֶת־כָּל־יְהוּדָ֗ה אֶתֵּן֙ בְּ⁠יַ֣ד מֶֽלֶךְ־בָּבֶ֔ל וְ⁠הִגְלָ֥⁠ם בָּבֶ֖לָ⁠ה וְ⁠הִכָּ֥⁠ם בֶּ⁠חָֽרֶב׃","ki֣̇y kò֣h ʼáma֣r yĕhwá֡h hinĕ⁠niy֩ nòţenĕ⁠ká֨ lĕ⁠mág֜wòr lĕ⁠ká֣ ẇ⁠lĕ⁠kál-ʼòhàbe֗y⁠ká wĕ⁠náֽpĕl֛ẇ bĕ̇⁠ẖe֥reb ʼòyĕbéy⁠he֖m wĕ⁠ʻéyne֣y⁠ká ròʼ֑wòţ wĕ⁠ʼeţ-ká̇l-yĕhẇdá֗h ʼeţé̇n֙ bĕ̇⁠ya֣d meֽlekĕ-bá̇be֔l wĕ⁠higĕlá֥⁠m bá̇be֖lá⁠h wĕ⁠hiká֥̇⁠m bė⁠ẖáֽreb׃"],[20,5,"וְ⁠נָתַתִּ֗י אֶת־כָּל־חֹ֨סֶן֙ הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠אֶת־כָּל־יְגִיעָ֖⁠הּ וְ⁠אֶת־כָּל־יְקָרָ֑⁠הּ וְ⁠אֵ֨ת כָּל־אוֹצְר֜וֹת מַלְכֵ֣י יְהוּדָ֗ה אֶתֵּן֙ בְּ⁠יַ֣ד אֹֽיְבֵי⁠הֶ֔ם וּ⁠בְזָזוּ⁠ם֙ וּ⁠לְקָח֔וּ⁠ם וֶ⁠הֱבִיא֖וּ⁠ם בָּבֶֽלָ⁠ה׃","wĕ⁠náţaţi̇֗y ʼeţ-ká̇l-ẖò֨sen֙ há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠ʼeţ-ká̇l-yĕgiyʻá֖⁠ḣ wĕ⁠ʼeţ-ká̇l-yĕqárá֑⁠ḣ wĕ⁠ʼé֨ţ ká̇l-ʼwòẕĕr֜wòţ malĕké֣y yĕhẇdá֗h ʼeţé̇n֙ bĕ̇⁠ya֣d ʼòֽyĕbéy⁠he֔m ẇ⁠bĕzázẇ⁠m֙ ẇ⁠lĕqáẖ֔ẇ⁠m we⁠hèbiyʼ֖ẇ⁠m bá̇beֽlá⁠h׃"],[20,6,"וְ⁠אַתָּ֣ה פַשְׁח֗וּר וְ⁠כֹל֙ יֹשְׁבֵ֣י בֵיתֶ֔⁠ךָ תֵּלְכ֖וּ בַּ⁠שֶּׁ֑בִי וּ⁠בָבֶ֣ל תָּב֗וֹא וְ⁠שָׁ֤ם תָּמוּת֙ וְ⁠שָׁ֣ם תִּקָּבֵ֔ר אַתָּה֙ וְ⁠כָל־אֹ֣הֲבֶ֔י⁠ךָ אֲשֶׁר־נִבֵּ֥אתָ לָ⁠הֶ֖ם בַּ⁠שָּֽׁקֶר׃ס","wĕ⁠ʼaţá֣̇h paşĕ̌ẖ֗ẇr wĕ⁠kòl֙ yòşĕ̌bé֣y béyţe֔⁠ká ţé̇lĕk֖ẇ bȧ⁠şė֑̌biy ẇ⁠bábe֣l ţá̇b֗wòʼ wĕ⁠şá֤̌m ţá̇mẇţ֙ wĕ⁠şá֣̌m ţi̇qá̇bé֔r ʼaţá̇h֙ wĕ⁠kál-ʼò֣hàbe֔y⁠ká ʼàşěr-nibé֥̇ʼţá lá⁠he֖m bȧ⁠şáֽ̇̌qer׃s"],[20,7,"פִּתִּיתַ֤⁠נִי יְהוָה֙ וָֽ⁠אֶפָּ֔ת חֲזַקְתַּ֖⁠נִי וַ⁠תּוּכָ֑ל הָיִ֤יתִי לִ⁠שְׂחוֹק֙ כָּל־הַ⁠יּ֔וֹם כֻּלֹּ֖⁠ה לֹעֵ֥ג לִֽ⁠י׃","pi̇ţi̇yţa֤⁠niy yĕhwáh֙ wֽá⁠ʼepá̇֔ţ ẖàzaqĕţȧ֖⁠niy wa⁠ţ̇ẇká֑l háyi֤yţiy li⁠şĕ̂ẖwòq֙ ká̇l-ha⁠ẏ֔wòm ku̇lò֖̇⁠h lòʻé֥g liֽ⁠y׃"],[20,8,"כִּֽי־מִ⁠דֵּ֤י אֲדַבֵּר֙ אֶזְעָ֔ק חָמָ֥ס וָ⁠שֹׁ֖ד אֶקְרָ֑א כִּֽי־הָיָ֨ה דְבַר־יְהוָ֥ה לִ֛⁠י לְ⁠חֶרְפָּ֥ה וּ⁠לְ⁠קֶ֖לֶס כָּל־הַ⁠יּֽוֹם׃","kiֽ̇y-mi⁠dé֤̇y ʼàdabé̇r֙ ʼezĕʻá֔q ẖámá֥s wá⁠şò֖̌d ʼeqĕrá֑ʼ kiֽ̇y-háyá֨h dĕbar-yĕhwá֥h li֛⁠y lĕ⁠ẖerĕpá֥̇h ẇ⁠lĕ⁠qe֖les ká̇l-ha⁠ẏֽwòm׃"],[20,9,"וְ⁠אָמַרְתִּ֣י לֹֽא־אֶזְכְּרֶ֗⁠נּוּ וְ⁠לֹֽא־אֲדַבֵּ֥ר עוֹד֙ בִּ⁠שְׁמ֔⁠וֹ וְ⁠הָיָ֤ה בְ⁠לִבִּ⁠י֙ כְּ⁠אֵ֣שׁ בֹּעֶ֔רֶת עָצֻ֖ר בְּ⁠עַצְמֹתָ֑⁠י וְ⁠נִלְאֵ֥יתִי כַּֽלְכֵ֖ל וְ⁠לֹ֥א אוּכָֽל׃","wĕ⁠ʼámarĕţi֣̇y lòֽʼ-ʼezĕkĕ̇re֗⁠ṅẇ wĕ⁠lòֽʼ-ʼàdabé֥̇r ʻwòd֙ bi̇⁠şĕ̌m֔⁠wò wĕ⁠háyá֤h bĕ⁠libi̇⁠y֙ kĕ̇⁠ʼé֣ş̌ bò̇ʻe֔reţ ʻáẕu֖r bĕ̇⁠ʻaẕĕmòţá֑⁠y wĕ⁠nilĕʼé֥yţiy kȧֽlĕké֖l wĕ⁠lò֥ʼ ʼẇkáֽl׃"],[20,10,"כִּ֣י שָׁמַ֜עְתִּי דִּבַּ֣ת רַבִּים֮ מָג֣וֹר מִ⁠סָּבִיב֒ הַגִּ֨ידוּ֙ וְ⁠נַגִּידֶ֔⁠נּוּ כֹּ֚ל אֱנ֣וֹשׁ שְׁלוֹמִ֔⁠י שֹׁמְרֵ֖י צַלְעִ֑⁠י אוּלַ֤י יְפֻתֶּה֙ וְ⁠נ֣וּכְלָה ל֔⁠וֹ וְ⁠נִקְחָ֥ה נִקְמָתֵ֖⁠נוּ מִמֶּֽ⁠נּוּ׃","ki֣̇y şá̌ma֜ʻĕţi̇y di̇bȧ֣ţ rabi̇ym֮ mág֣wòr mi⁠sá̇biyb֒ hagi̇֨ydẇ֙ wĕ⁠nagi̇yde֔⁠ṅẇ kò֚̇l ʼèn֣wòş̌ şĕ̌lwòmi֔⁠y şò̌mĕré֖y ẕalĕʻi֑⁠y ʼẇla֤y yĕpuţėh֙ wĕ⁠n֣ẇkĕláh l֔⁠wò wĕ⁠niqĕẖá֥h niqĕmáţé֖⁠nẇ mimėֽ⁠ṅẇ׃"],[20,11,"וַֽ⁠יהוָ֤ה אוֹתִ⁠י֙ כְּ⁠גִבּ֣וֹר עָרִ֔יץ עַל־כֵּ֛ן רֹדְפַ֥⁠י יִכָּשְׁל֖וּ וְ⁠לֹ֣א יֻכָ֑לוּ בֹּ֤שׁוּ מְאֹד֙ כִּֽי־לֹ֣א הִשְׂכִּ֔ילוּ כְּלִמַּ֥ת עוֹלָ֖ם לֹ֥א תִשָּׁכֵֽחַ׃","waֽ⁠yhwá֤h ʼwòţi⁠y֙ kĕ̇⁠giḃ֣wòr ʻári֔yẕ ʻal-ké֛̇n ròdĕpa֥⁠y yiká̇şĕ̌l֖ẇ wĕ⁠lò֣ʼ yuká֑lẇ bò֤̇ş̌ẇ mĕʼòd֙ kiֽ̇y-lò֣ʼ hişĕ̂ki̇֔ylẇ kĕ̇limȧ֥ţ ʻwòlá֖m lò֥ʼ ţişá̇̌kéֽẖa׃"],[20,12,"וַ⁠יהוָ֤ה צְבָאוֹת֙ בֹּחֵ֣ן צַדִּ֔יק רֹאֶ֥ה כְלָי֖וֹת וָ⁠לֵ֑ב אֶרְאֶ֤ה נִקְמָֽתְ⁠ךָ֙ מֵ⁠הֶ֔ם כִּ֥י אֵלֶ֖י⁠ךָ גִּלִּ֥יתִי אֶת־רִיבִֽ⁠י׃ס","wa⁠yhwá֤h ẕĕbáʼwòţ֙ bò̇ẖé֣n ẕadi̇֔yq ròʼe֥h kĕláy֖wòţ wá⁠lé֑b ʼerĕʼe֤h niqĕmáֽţĕ⁠ká֙ mé⁠he֔m ki֥̇y ʼéle֖y⁠ká gi̇li֥̇yţiy ʼeţ-riybiֽ⁠y׃s"],[20,13,"שִׁ֚ירוּ לַֽ⁠יהוָ֔ה הַֽלְל֖וּ אֶת־יְהוָ֑ה כִּ֥י הִצִּ֛יל אֶת־נֶ֥פֶשׁ אֶבְי֖וֹן מִ⁠יַּ֥ד מְרֵעִֽים׃ס","şǐ֚yrẇ laֽ⁠yhwá֔h haֽlĕl֖ẇ ʼeţ-yĕhwá֑h ki֥̇y hiẕi֛̇yl ʼeţ-ne֥peş̌ ʼebĕy֖wòn mi⁠yȧ֥d mĕréʻiֽym׃s"],[20,14,"אָר֣וּר הַ⁠יּ֔וֹם אֲשֶׁ֥ר יֻלַּ֖דְתִּי בּ֑⁠וֹ י֛וֹם אֲשֶׁר־יְלָדַ֥תְ⁠נִי אִמִּ֖⁠י אַל־יְהִ֥י בָרֽוּךְ׃","ʼár֣ẇr ha⁠ẏ֔wòm ʼàşě֥r yulȧ֖dĕţi̇y ḃ֑⁠wò y֛wòm ʼàşěr-yĕláda֥ţĕ⁠niy ʼimi֖̇⁠y ʼal-yĕhi֥y bárֽẇkĕ׃"],[20,15,"אָר֣וּר הָ⁠אִ֗ישׁ אֲשֶׁ֨ר בִּשַּׂ֤ר אֶת־אָבִ⁠י֙ לֵ⁠אמֹ֔ר יֻֽלַּד־לְ⁠ךָ֖ בֵּ֣ן זָכָ֑ר שַׂמֵּ֖חַ שִׂמֳּחָֽ⁠הוּ׃","ʼár֣ẇr há⁠ʼi֗yş̌ ʼàşě֨r bi̇şȧ֤̂r ʼeţ-ʼábi⁠y֙ lé⁠ʼmò֔r yuֽlȧd-lĕ⁠ká֖ bé֣̇n záká֑r şâmé֖̇ẖa şîmȯẖáֽ⁠hẇ׃"],[20,16,"וְ⁠הָיָה֙ הָ⁠אִ֣ישׁ הַ⁠ה֔וּא כֶּֽ⁠עָרִ֛ים אֲשֶׁר־הָפַ֥ךְ יְהוָ֖ה וְ⁠לֹ֣א נִחָ֑ם וְ⁠שָׁמַ֤ע זְעָקָה֙ בַּ⁠בֹּ֔קֶר וּ⁠תְרוּעָ֖ה בְּ⁠עֵ֥ת צָהֳרָֽיִם׃","wĕ⁠háyáh֙ há⁠ʼi֣yş̌ ha⁠h֔ẇʼ kėֽ⁠ʻári֛ym ʼàşěr-hápa֥kĕ yĕhwá֖h wĕ⁠lò֣ʼ niẖá֑m wĕ⁠şá̌ma֤ʻ zĕʻáqáh֙ bȧ⁠bò̇֔qer ẇ⁠ţĕrẇʻá֖h bĕ̇⁠ʻé֥ţ ẕáhoráֽyim׃"],[20,17,"אֲשֶׁ֥ר לֹא־מוֹתְתַ֖⁠נִי מֵ⁠רָ֑חֶם וַ⁠תְּהִי־לִ֤⁠י אִמִּ⁠י֙ קִבְרִ֔⁠י וְ⁠רַחְמָ֖⁠הֿ הֲרַ֥ת עוֹלָֽם׃","ʼàşě֥r lòʼ-mwòţĕţa֖⁠niy mé⁠rá֑ẖem wa⁠ţĕ̇hiy-li֤⁠y ʼimi̇⁠y֙ qibĕri֔⁠y wĕ⁠raẖĕmá֖⁠h̄ hàra֥ţ ʻwòláֽm׃"],[20,18,"לָ֤⁠מָּה זֶּה֙ מֵ⁠רֶ֣חֶם יָצָ֔אתִי לִ⁠רְא֥וֹת עָמָ֖ל וְ⁠יָג֑וֹן וַ⁠יִּכְל֥וּ בְּ⁠בֹ֖שֶׁת יָמָֽ⁠י׃פ","lá֤⁠má̇h zėh֙ mé⁠re֣ẖem yáẕá֔ʼţiy li⁠rĕʼ֥wòţ ʻámá֖l wĕ⁠yág֑wòn wa⁠yi̇kĕl֥ẇ bĕ̇⁠bò֖şěţ yámáֽ⁠y׃p"],[21,1,"הַ⁠דָּבָ֛ר אֲשֶׁר־הָיָ֥ה אֶֽל־יִרְמְיָ֖הוּ מֵ⁠אֵ֣ת יְהוָ֑ה בִּ⁠שְׁלֹ֨חַ אֵלָ֜י⁠ו הַ⁠מֶּ֣לֶךְ צִדְקִיָּ֗הוּ אֶת־פַּשְׁחוּר֙ בֶּן־מַלְכִּיָּ֔ה וְ⁠אֶת־צְפַנְיָ֧ה בֶן־מַעֲשֵׂיָ֛ה הַ⁠כֹּהֵ֖ן לֵ⁠אמֹֽר׃","ha⁠dá̇bá֛r ʼàşěr-háyá֥h ʼeֽl-yirĕmĕyá֖hẇ mé⁠ʼé֣ţ yĕhwá֑h bi̇⁠şĕ̌lò֨ẖa ʼélá֜y⁠w ha⁠mė֣lekĕ ẕidĕqiyá̇֗hẇ ʼeţ-pȧşĕ̌ẖẇr֙ bėn-malĕki̇yá̇֔h wĕ⁠ʼeţ-ẕĕpanĕyá֧h ben-maʻàşé̂yá֛h ha⁠kò̇hé֖n lé⁠ʼmòֽr׃"],[21,2,"דְּרָשׁ־נָ֤א בַעֲדֵ֨⁠נוּ֙ אֶת־יְהוָ֔ה כִּ֛י נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל נִלְחָ֣ם עָלֵ֑י⁠נוּ אוּלַי֩ יַעֲשֶׂ֨ה יְהוָ֤ה אוֹתָ֨⁠נוּ֙ כְּ⁠כָל־נִפְלְאֹתָ֔י⁠ו וְ⁠יַעֲלֶ֖ה מֵ⁠עָלֵֽי⁠נוּ׃ס","dĕ̇ráş̌-ná֤ʼ baʻàdé֨⁠nẇ֙ ʼeţ-yĕhwá֔h ki֛̇y nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l nilĕẖá֣m ʻálé֑y⁠nẇ ʼẇlay֩ yaʻàşê֨h yĕhwá֤h ʼwòţá֨⁠nẇ֙ kĕ̇⁠kál-nipĕlĕʼòţá֔y⁠w wĕ⁠yaʻàle֖h mé⁠ʻáléֽy⁠nẇ׃s"],[21,3,"וַ⁠יֹּ֥אמֶר יִרְמְיָ֖הוּ אֲלֵי⁠הֶ֑ם כֹּ֥ה תֹאמְרֻ֖⁠ן אֶל־צִדְקִיָּֽהוּ׃","wa⁠yò֥̇ʼmer yirĕmĕyá֖hẇ ʼàléy⁠he֑m kò֥̇h ţòʼmĕru֖⁠n ʼel-ẕidĕqiyáֽ̇hẇ׃"],[21,4,"כֹּֽה־אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הִנְ⁠נִ֣י מֵסֵב֮ אֶת־כְּלֵ֣י הַ⁠מִּלְחָמָה֮ אֲשֶׁ֣ר בְּ⁠יֶדְ⁠כֶם֒ אֲשֶׁ֨ר אַתֶּ֜ם נִלְחָמִ֣ים בָּ֗⁠ם אֶת־מֶ֤לֶךְ בָּבֶל֙ וְ⁠אֶת־הַ⁠כַּשְׂדִּ֔ים הַ⁠צָּרִ֣ים עֲלֵי⁠כֶ֔ם מִ⁠ח֖וּץ לַֽ⁠חוֹמָ֑ה וְ⁠אָסַפְתִּ֣י אוֹתָ֔⁠ם אֶל־תּ֖וֹךְ הָ⁠עִ֥יר הַ⁠זֹּֽאת׃","kòֽ̇h-ʼáma֨r yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l hinĕ⁠ni֣y méséb֮ ʼeţ-kĕ̇lé֣y ha⁠mi̇lĕẖámáh֮ ʼàşě֣r bĕ̇⁠yedĕ⁠kem֒ ʼàşě֨r ʼaţė֜m nilĕẖámi֣ym bá̇֗⁠m ʼeţ-me֤lekĕ bá̇bel֙ wĕ⁠ʼeţ-ha⁠kȧşĕ̂di̇֔ym ha⁠ẕá̇ri֣ym ʻàléy⁠ke֔m mi⁠ẖ֖ẇẕ laֽ⁠ẖwòmá֑h wĕ⁠ʼásapĕţi֣̇y ʼwòţá֔⁠m ʼel-ţ֖̇wòkĕ há⁠ʻi֥yr ha⁠zòֽ̇ʼţ׃"],[21,5,"וְ⁠נִלְחַמְתִּ֤י אֲנִי֙ אִתְּ⁠כֶ֔ם בְּ⁠יָ֥ד נְטוּיָ֖ה וּ⁠בִ⁠זְר֣וֹעַ חֲזָקָ֑ה וּ⁠בְ⁠אַ֥ף וּ⁠בְ⁠חֵמָ֖ה וּ⁠בְ⁠קֶ֥צֶף גָּדֽוֹל׃","wĕ⁠nilĕẖamĕţi֤̇y ʼàniy֙ ʼiţĕ̇⁠ke֔m bĕ̇⁠yá֥d nĕtẇyá֖h ẇ⁠bi⁠zĕr֣wòʻa ẖàzáqá֑h ẇ⁠bĕ⁠ʼa֥p ẇ⁠bĕ⁠ẖémá֖h ẇ⁠bĕ⁠qe֥ẕep gá̇dֽwòl׃"],[21,6,"וְ⁠הִכֵּיתִ֗י אֶת־יֽוֹשְׁבֵי֙ הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠אֶת־הָ⁠אָדָ֖ם וְ⁠אֶת־הַ⁠בְּהֵמָ֑ה בְּ⁠דֶ֥בֶר גָּד֖וֹל יָמֻֽתוּ׃","wĕ⁠hiké̇yţi֗y ʼeţ-yֽwòşĕ̌béy֙ há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠ʼeţ-há⁠ʼádá֖m wĕ⁠ʼeţ-ha⁠bĕ̇hémá֑h bĕ̇⁠de֥ber gá̇d֖wòl yámuֽţẇ׃"],[21,7,"וְ⁠אַחֲרֵי־כֵ֣ן נְאֻם־יְהוָ֡ה אֶתֵּ֣ן אֶת־צִדְקִיָּ֣הוּ מֶֽלֶךְ־יְהוּדָ֣ה וְ⁠אֶת־עֲבָדָ֣י⁠ו ׀ וְ⁠אֶת־הָ⁠עָ֡ם וְ⁠אֶת־הַ⁠נִּשְׁאָרִים֩ בָּ⁠עִ֨יר הַ⁠זֹּ֜את מִן־הַ⁠דֶּ֣בֶר ׀ מִן־הַ⁠חֶ֣רֶב וּ⁠מִן־הָ⁠רָעָ֗ב בְּ⁠יַד֙ נְבוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֔ל וּ⁠בְ⁠יַד֙ אֹֽיְבֵי⁠הֶ֔ם וּ⁠בְ⁠יַ֖ד מְבַקְשֵׁ֣י נַפְשָׁ֑⁠ם וְ⁠הִכָּ֣⁠ם לְ⁠פִי־חֶ֔רֶב לֹֽא־יָח֣וּס עֲלֵי⁠הֶ֔ם וְ⁠לֹ֥א יַחְמֹ֖ל וְ⁠לֹ֥א יְרַחֵֽם׃","wĕ⁠ʼaẖàréy-ké֣n nĕʼum-yĕhwá֡h ʼeţé֣̇n ʼeţ-ẕidĕqiyá֣̇hẇ meֽlekĕ-yĕhẇdá֣h wĕ⁠ʼeţ-ʻàbádá֣y⁠w ׀ wĕ⁠ʼeţ-há⁠ʻá֡m wĕ⁠ʼeţ-ha⁠ni̇şĕ̌ʼáriym֩ bá̇⁠ʻi֨yr ha⁠zò̇֜ʼţ min-ha⁠dė֣ber ׀ min-ha⁠ẖe֣reb ẇ⁠min-há⁠ráʻá֗b bĕ̇⁠yad֙ nĕbẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇be֔l ẇ⁠bĕ⁠yad֙ ʼòֽyĕbéy⁠he֔m ẇ⁠bĕ⁠ya֖d mĕbaqĕşé֣̌y napĕşá֑̌⁠m wĕ⁠hiká֣̇⁠m lĕ⁠piy-ẖe֔reb lòֽʼ-yáẖ֣ẇs ʻàléy⁠he֔m wĕ⁠lò֥ʼ yaẖĕmò֖l wĕ⁠lò֥ʼ yĕraẖéֽm׃"],[21,8,"וְ⁠אֶל־הָ⁠עָ֤ם הַ⁠זֶּה֙ תֹּאמַ֔ר כֹּ֖ה אָמַ֣ר יְהוָ֑ה הִנְ⁠נִ֤י נֹתֵן֙ לִ⁠פְנֵי⁠כֶ֔ם אֶת־דֶּ֥רֶךְ הַ⁠חַיִּ֖ים וְ⁠אֶת־דֶּ֥רֶךְ הַ⁠מָּֽוֶת׃","wĕ⁠ʼel-há⁠ʻá֤m ha⁠zėh֙ ţò̇ʼma֔r kò֖̇h ʼáma֣r yĕhwá֑h hinĕ⁠ni֤y nòţén֙ li⁠pĕnéy⁠ke֔m ʼeţ-dė֥rekĕ ha⁠ẖayi֖̇ym wĕ⁠ʼeţ-dė֥rekĕ ha⁠máֽ̇weţ׃"],[21,9,"הַ⁠יֹּשֵׁב֙ בָּ⁠עִ֣יר הַ⁠זֹּ֔את יָמ֕וּת בַּ⁠חֶ֖רֶב וּ⁠בָ⁠רָעָ֣ב וּ⁠בַ⁠דָּ֑בֶר וְ⁠הַ⁠יּוֹצֵא֩ וְ⁠נָפַ֨ל עַל־הַ⁠כַּשְׂדִּ֜ים הַ⁠צָּרִ֤ים עֲלֵי⁠כֶם֙ יחיה וְ⁠הָֽיְתָה־לּ֥⁠וֹ נַפְשׁ֖⁠וֹ לְ⁠שָׁלָֽל׃","ha⁠yò̇şé̌b֙ bá̇⁠ʻi֣yr ha⁠zò̇֔ʼţ yám֕ẇţ bȧ⁠ẖe֖reb ẇ⁠bá⁠ráʻá֣b ẇ⁠ba⁠dá֑̇ber wĕ⁠ha⁠ẏwòẕéʼ֩ wĕ⁠nápa֨l ʻal-ha⁠kȧşĕ̂di̇֜ym ha⁠ẕá̇ri֤ym ʻàléy⁠kem֙ yẖyh wĕ⁠háֽyĕţáh-l֥̇⁠wò napĕş֖̌⁠wò lĕ⁠şá̌láֽl׃"],[21,10,"כִּ֣י שַׂ֣מְתִּי פָ֠נַ⁠י בָּ⁠עִ֨יר הַ⁠זֹּ֧את לְ⁠רָעָ֛ה וְ⁠לֹ֥א לְ⁠טוֹבָ֖ה נְאֻם־יְהוָ֑ה בְּ⁠יַד־מֶ֤לֶךְ בָּבֶל֙ תִּנָּתֵ֔ן וּ⁠שְׂרָפָ֖⁠הּ בָּ⁠אֵֽשׁ׃ס","ki֣̇y şâ֣mĕţi̇y pá֠na⁠y bá̇⁠ʻi֨yr ha⁠zò֧̇ʼţ lĕ⁠ráʻá֛h wĕ⁠lò֥ʼ lĕ⁠twòbá֖h nĕʼum-yĕhwá֑h bĕ̇⁠yad-me֤lekĕ bá̇bel֙ ţi̇ná̇ţé֔n ẇ⁠şĕ̂rápá֖⁠ḣ bá̇⁠ʼéֽş̌׃s"],[21,11,"וּ⁠לְ⁠בֵית֙ מֶ֣לֶךְ יְהוּדָ֔ה שִׁמְע֖וּ דְּבַר־יְהוָֽה׃","ẇ⁠lĕ⁠béyţ֙ me֣lekĕ yĕhẇdá֔h şǐmĕʻ֖ẇ dĕ̇bar-yĕhwáֽh׃"],[21,12,"בֵּ֣ית דָּוִ֗ד כֹּ֚ה אָמַ֣ר יְהוָ֔ה דִּ֤ינוּ לַ⁠בֹּ֨קֶר֙ מִשְׁפָּ֔ט וְ⁠הַצִּ֥ילוּ גָז֖וּל מִ⁠יַּ֣ד עוֹשֵׁ֑ק פֶּן־תֵּצֵ֨א כָ⁠אֵ֜שׁ חֲמָתִ֗⁠י וּ⁠בָעֲרָה֙ וְ⁠אֵ֣ין מְכַבֶּ֔ה מִ⁠פְּנֵ֖י רֹ֥עַ מעללי⁠הם׃","bé֣̇yţ dá̇wi֗d kò֚̇h ʼáma֣r yĕhwá֔h di֤̇ynẇ la⁠bò̇֨qer֙ mişĕ̌pá̇֔t wĕ⁠haẕi֥̇ylẇ gáz֖ẇl mi⁠yȧ֣d ʻwòşé֑̌q pėn-ţé̇ẕé֨ʼ ká⁠ʼé֜ş̌ ẖàmáţi֗⁠y ẇ⁠báʻàráh֙ wĕ⁠ʼé֣yn mĕkabė֔h mi⁠pĕ̇né֖y rò֥ʻa mʻlly⁠hm׃"],[21,13,"הִנְ⁠נִ֨י אֵלַ֜יִ⁠ךְ יֹשֶׁ֧בֶת הָ⁠עֵ֛מֶק צ֥וּר הַ⁠מִּישֹׁ֖ר נְאֻם־יְהוָ֑ה הָ⁠אֹֽמְרִים֙ מִֽי־יֵחַ֣ת עָלֵ֔י⁠נוּ וּ⁠מִ֥י יָב֖וֹא בִּ⁠מְעוֹנוֹתֵֽי⁠נוּ׃","hinĕ⁠ni֨y ʼéla֜yi⁠kĕ yòşě֧beţ há⁠ʻé֛meq ẕ֥ẇr ha⁠mi̇yşò֖̌r nĕʼum-yĕhwá֑h há⁠ʼòֽmĕriym֙ miֽy-yéẖa֣ţ ʻálé֔y⁠nẇ ẇ⁠mi֥y yáb֖wòʼ bi̇⁠mĕʻwònwòţéֽy⁠nẇ׃"],[21,14,"וּ⁠פָקַדְתִּ֧י עֲלֵי⁠כֶ֛ם כִּ⁠פְרִ֥י מַעַלְלֵי⁠כֶ֖ם נְאֻם־יְהוָ֑ה וְ⁠הִצַּ֤תִּי אֵשׁ֙ בְּ⁠יַעְרָ֔⁠הּ וְ⁠אָכְלָ֖ה כָּל־סְבִיבֶֽי⁠הָ׃ס","ẇ⁠páqadĕţi֧̇y ʻàléy⁠ke֛m ki̇⁠pĕri֥y maʻalĕléy⁠ke֖m nĕʼum-yĕhwá֑h wĕ⁠hiẕȧ֤ţi̇y ʼéş̌֙ bĕ̇⁠yaʻĕrá֔⁠ḣ wĕ⁠ʼákĕlá֖h ká̇l-sĕbiybeֽy⁠há׃s"],[22,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה רֵ֖ד בֵּֽית־מֶ֣לֶךְ יְהוּדָ֑ה וְ⁠דִבַּרְתָּ֣ שָׁ֔ם אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h ré֖d béֽ̇yţ-me֣lekĕ yĕhẇdá֑h wĕ⁠dibȧrĕţá֣̇ şá̌֔m ʼeţ-ha⁠dá̇bá֖r ha⁠zėֽh׃"],[22,2,"וְ⁠אָֽמַרְתָּ֙ שְׁמַ֣ע דְּבַר־יְהוָ֔ה מֶ֣לֶךְ יְהוּדָ֔ה הַ⁠יֹּשֵׁ֖ב עַל־כִּסֵּ֣א דָוִ֑ד אַתָּ֤ה וַ⁠עֲבָדֶ֨י⁠ךָ֙ וְ⁠עַמְּ⁠ךָ֔ הַ⁠בָּאִ֖ים בַּ⁠שְּׁעָרִ֥ים הָ⁠אֵֽלֶּה׃ס","wĕ⁠ʼáֽmarĕţá̇֙ şĕ̌ma֣ʻ dĕ̇bar-yĕhwá֔h me֣lekĕ yĕhẇdá֔h ha⁠yò̇şé֖̌b ʻal-ki̇sé֣̇ʼ dáwi֑d ʼaţá֤̇h wa⁠ʻàbáde֨y⁠ká֙ wĕ⁠ʻamĕ̇⁠ká֔ ha⁠bá̇ʼi֖ym bȧ⁠şĕ̇̌ʻári֥ym há⁠ʼéֽlėh׃s"],[22,3,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה עֲשׂ֤וּ מִשְׁפָּט֙ וּ⁠צְדָקָ֔ה וְ⁠הַצִּ֥ילוּ גָז֖וּל מִ⁠יַּ֣ד עָשׁ֑וֹק וְ⁠גֵר֩ יָת֨וֹם וְ⁠אַלְמָנָ֤ה אַל־תֹּנוּ֙ אַל־תַּחְמֹ֔סוּ וְ⁠דָ֣ם נָקִ֔י אַֽל־תִּשְׁפְּכ֖וּ בַּ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʻàş֤̂ẇ mişĕ̌pá̇t֙ ẇ⁠ẕĕdáqá֔h wĕ⁠haẕi֥̇ylẇ gáz֖ẇl mi⁠yȧ֣d ʻáş֑̌wòq wĕ⁠gér֩ yáţ֨wòm wĕ⁠ʼalĕmáná֤h ʼal-ţò̇nẇ֙ ʼal-ţȧẖĕmò֔sẇ wĕ⁠dá֣m náqi֔y ʼaֽl-ţi̇şĕ̌pĕ̇k֖ẇ bȧ⁠má̇q֥wòm ha⁠zėֽh׃"],[22,4,"כִּ֤י אִם־עָשׂוֹ֙ תַּֽעֲשׂ֔וּ אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה וּ⁠בָ֣אוּ בְ⁠שַׁעֲרֵ֣י הַ⁠בַּ֣יִת הַ⁠זֶּ֡ה מְלָכִים֩ יֹשְׁבִ֨ים לְ⁠דָוִ֜ד עַל־כִּסְא֗⁠וֹ רֹֽכְבִים֙ בָּ⁠רֶ֣כֶב וּ⁠בַ⁠סּוּסִ֔ים ה֥וּא ו⁠עבד⁠ו וְ⁠עַמּֽ⁠וֹ׃","ki֤̇y ʼim-ʻáş̂wò֙ ţȧֽʻàş̂֔ẇ ʼeţ-ha⁠dá̇bá֖r ha⁠zė֑h ẇ⁠bá֣ʼẇ bĕ⁠şǎʻàré֣y ha⁠bȧ֣yiţ ha⁠zė֡h mĕlákiym֩ yòşĕ̌bi֨ym lĕ⁠dáwi֜d ʻal-ki̇sĕʼ֗⁠wò ròֽkĕbiym֙ bá̇⁠re֣keb ẇ⁠ba⁠ṡẇsi֔ym h֥ẇʼ w⁠ʻbd⁠w wĕ⁠ʻaṁֽ⁠wò׃"],[22,5,"וְ⁠אִם֙ לֹ֣א תִשְׁמְע֔וּ אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה בִּ֤⁠י נִשְׁבַּ֨עְתִּי֙ נְאֻם־יְהוָ֔ה כִּי־לְ⁠חָרְבָּ֥ה יִֽהְיֶ֖ה הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃ס","wĕ⁠ʼim֙ lò֣ʼ ţişĕ̌mĕʻ֔ẇ ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh bi֤̇⁠y nişĕ̌bȧ֨ʻĕţi̇y֙ nĕʼum-yĕhwá֔h ki̇y-lĕ⁠ẖárĕbá֥̇h yiֽhĕye֖h ha⁠bȧ֥yiţ ha⁠zėֽh׃s"],[22,6,"כִּֽי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה עַל־בֵּית֙ מֶ֣לֶךְ יְהוּדָ֔ה גִּלְעָ֥ד אַתָּ֛ה לִ֖⁠י רֹ֣אשׁ הַ⁠לְּבָנ֑וֹן אִם־לֹ֤א אֲשִֽׁיתְ⁠ךָ֙ מִדְבָּ֔ר עָרִ֖ים לֹ֥א נושבה׃","kiֽ̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ʻal-bé̇yţ֙ me֣lekĕ yĕhẇdá֔h gi̇lĕʻá֥d ʼaţá֛̇h li֖⁠y rò֣ʼş̌ ha⁠lĕ̇bán֑wòn ʼim-lò֤ʼ ʼàşǐֽyţĕ⁠ká֙ midĕbá̇֔r ʻári֖ym lò֥ʼ nwşbh׃"],[22,7,"וְ⁠קִדַּשְׁתִּ֥י עָלֶ֛י⁠ךָ מַשְׁחִתִ֖ים אִ֣ישׁ וְ⁠כֵלָ֑י⁠ו וְ⁠כָֽרְתוּ֙ מִבְחַ֣ר אֲרָזֶ֔י⁠ךָ וְ⁠הִפִּ֖ילוּ עַל־הָ⁠אֵֽשׁ׃","wĕ⁠qidȧşĕ̌ţi֥̇y ʻále֛y⁠ká maşĕ̌ẖiţi֖ym ʼi֣yş̌ wĕ⁠kélá֑y⁠w wĕ⁠káֽrĕţẇ֙ mibĕẖa֣r ʼàráze֔y⁠ká wĕ⁠hipi֖̇ylẇ ʻal-há⁠ʼéֽş̌׃"],[22,8,"וְ⁠עָֽבְרוּ֙ גּוֹיִ֣ם רַבִּ֔ים עַ֖ל הָ⁠עִ֣יר הַ⁠זֹּ֑את וְ⁠אָֽמְרוּ֙ אִ֣ישׁ אֶל־רֵעֵ֔⁠הוּ עַל־מֶ֨ה עָשָׂ֤ה יְהוָה֙ כָּ֔כָה לָ⁠עִ֥יר הַ⁠גְּדוֹלָ֖ה הַ⁠זֹּֽאת׃","wĕ⁠ʻáֽbĕrẇ֙ ġwòyi֣m rabi̇֔ym ʻa֖l há⁠ʻi֣yr ha⁠zò֑̇ʼţ wĕ⁠ʼáֽmĕrẇ֙ ʼi֣yş̌ ʼel-réʻé֔⁠hẇ ʻal-me֨h ʻáşá֤̂h yĕhwáh֙ ká̇֔káh lá⁠ʻi֥yr ha⁠gĕ̇dwòlá֖h ha⁠zòֽ̇ʼţ׃"],[22,9,"וְ⁠אָ֣מְר֔וּ עַ֚ל אֲשֶׁ֣ר עָֽזְב֔וּ אֶת־בְּרִ֥ית יְהוָ֖ה אֱלֹֽהֵי⁠הֶ֑ם וַ⁠יִּֽשְׁתַּחֲו֛וּ לֵ⁠אלֹהִ֥ים אֲחֵרִ֖ים וַ⁠יַּעַבְדֽוּ⁠ם׃ס","wĕ⁠ʼá֣mĕr֔ẇ ʻa֚l ʼàşě֣r ʻáֽzĕb֔ẇ ʼeţ-bĕ̇ri֥yţ yĕhwá֖h ʼèlòֽhéy⁠he֑m wa⁠yiֽ̇şĕ̌ţȧẖàw֛ẇ lé⁠ʼlòhi֥ym ʼàẖéri֖ym wa⁠yȧʻabĕdֽẇ⁠m׃s"],[22,10,"אַל־תִּבְכּ֣וּ לְ⁠מֵ֔ת וְ⁠אַל־תָּנֻ֖דוּ ל֑⁠וֹ בְּכ֤וּ בָכוֹ֙ לַֽ⁠הֹלֵ֔ךְ כִּ֣י לֹ֤א יָשׁוּב֙ ע֔וֹד וְ⁠רָאָ֖ה אֶת־אֶ֥רֶץ מוֹלַדְתּֽ⁠וֹ׃ס","ʼal-ţi̇bĕk֣̇ẇ lĕ⁠mé֔ţ wĕ⁠ʼal-ţá̇nu֖dẇ l֑⁠wò bĕ̇k֤ẇ bákwò֙ laֽ⁠hòlé֔kĕ ki֣̇y lò֤ʼ yáş̌ẇb֙ ʻ֔wòd wĕ⁠ráʼá֖h ʼeţ-ʼe֥reẕ mwòladĕţֽ̇⁠wò׃s"],[22,11,"כִּ֣י כֹ֣ה אָֽמַר־יְ֠הוָה אֶל־שַׁלֻּ֨ם בֶּן־יֹאשִׁיָּ֜הוּ מֶ֣לֶךְ יְהוּדָ֗ה הַ⁠מֹּלֵךְ֙ תַּ֚חַת יֹאשִׁיָּ֣הוּ אָבִ֔י⁠ו אֲשֶׁ֥ר יָצָ֖א מִן־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה לֹֽא־יָשׁ֥וּב שָׁ֖ם עֽוֹד׃","ki֣̇y kò֣h ʼáֽmar-yĕ֠hwáh ʼel-şǎlu̇֨m bėn-yòʼşǐyá̇֜hẇ me֣lekĕ yĕhẇdá֗h ha⁠mò̇lékĕ֙ ţȧ֚ẖaţ yòʼşǐyá֣̇hẇ ʼábi֔y⁠w ʼàşě֥r yáẕá֖ʼ min-ha⁠má̇q֣wòm ha⁠zė֑h lòֽʼ-yáş֥̌ẇb şá֖̌m ʻֽwòd׃"],[22,12,"כִּ֗י בִּ⁠מְק֛וֹם אֲשֶׁר־הִגְל֥וּ אֹת֖⁠וֹ שָׁ֣ם יָמ֑וּת וְ⁠אֶת־הָ⁠אָ֥רֶץ הַ⁠זֹּ֖את לֹֽא־יִרְאֶ֥ה עֽוֹד׃ס","ki̇֗y bi̇⁠mĕq֛wòm ʼàşěr-higĕl֥ẇ ʼòţ֖⁠wò şá֣̌m yám֑ẇţ wĕ⁠ʼeţ-há⁠ʼá֥reẕ ha⁠zò֖̇ʼţ lòֽʼ-yirĕʼe֥h ʻֽwòd׃s"],[22,13,"ה֣וֹי בֹּנֶ֤ה בֵית⁠וֹ֙ בְּֽ⁠לֹא־צֶ֔דֶק וַ⁠עֲלִיּוֹתָ֖י⁠ו בְּ⁠לֹ֣א מִשְׁפָּ֑ט בְּ⁠רֵעֵ֨⁠הוּ֙ יַעֲבֹ֣ד חִנָּ֔ם וּ⁠פֹעֲל֖⁠וֹ לֹ֥א יִתֶּן־לֽ⁠וֹ׃","h֣wòy bò̇ne֤h béyţ⁠wò֙ bĕֽ̇⁠lòʼ-ẕe֔deq wa⁠ʻàliẏwòţá֖y⁠w bĕ̇⁠lò֣ʼ mişĕ̌pá֑̇t bĕ̇⁠réʻé֨⁠hẇ֙ yaʻàbò֣d ẖiná̇֔m ẇ⁠pòʻàl֖⁠wò lò֥ʼ yiţėn-lֽ⁠wò׃"],[22,14,"הָ⁠אֹמֵ֗ר אֶבְנֶה־לִּ⁠י֙ בֵּ֣ית מִדּ֔וֹת וַ⁠עֲלִיּ֖וֹת מְרֻוָּחִ֑ים וְ⁠קָ֤רַֽע ל⁠וֹ֙ חַלּוֹנָ֔⁠י וְ⁠סָפ֣וּן בָּ⁠אָ֔רֶז וּ⁠מָשׁ֖וֹחַ בַּ⁠שָּׁשַֽׁר׃","há⁠ʼòmé֗r ʼebĕneh-li̇⁠y֙ bé֣̇yţ miḋ֔wòţ wa⁠ʻàliẏ֖wòţ mĕruwá̇ẖi֑ym wĕ⁠qá֤raֽʻ l⁠wò֙ ẖal̇wòná֔⁠y wĕ⁠sáp֣ẇn bá̇⁠ʼá֔rez ẇ⁠máş֖̌wòẖa bȧ⁠şá̇̌şǎֽr׃"],[22,15,"הֲ⁠תִֽמְלֹ֔ךְ כִּ֥י אַתָּ֖ה מְתַחֲרֶ֣ה בָ⁠אָ֑רֶז אָבִ֜י⁠ךָ הֲ⁠ל֧וֹא אָכַ֣ל וְ⁠שָׁתָ֗ה וְ⁠עָשָׂ֤ה מִשְׁפָּט֙ וּ⁠צְדָקָ֔ה אָ֖ז ט֥וֹב לֽ⁠וֹ׃","hà⁠ţiֽmĕlò֔kĕ ki֥̇y ʼaţá֖̇h mĕţaẖàre֣h bá⁠ʼá֑rez ʼábi֜y⁠ká hà⁠l֧wòʼ ʼáka֣l wĕ⁠şá̌ţá֗h wĕ⁠ʻáşá֤̂h mişĕ̌pá̇t֙ ẇ⁠ẕĕdáqá֔h ʼá֖z t֥wòb lֽ⁠wò׃"],[22,16,"דָּ֛ן דִּין־עָנִ֥י וְ⁠אֶבְי֖וֹן אָ֣ז ט֑וֹב הֲ⁠לוֹא־הִ֛יא הַ⁠דַּ֥עַת אֹתִ֖⁠י נְאֻם־יְהוָֽה׃","dá֛̇n di̇yn-ʻáni֥y wĕ⁠ʼebĕy֖wòn ʼá֣z t֑wòb hà⁠lwòʼ-hi֛yʼ ha⁠dȧ֥ʻaţ ʼòţi֖⁠y nĕʼum-yĕhwáֽh׃"],[22,17,"כִּ֣י אֵ֤ין עֵינֶ֨י⁠ךָ֙ וְ⁠לִבְּ⁠ךָ֔ כִּ֖י אִם־עַל־בִּצְעֶ֑⁠ךָ וְ⁠עַ֤ל דַּֽם־הַ⁠נָּקִי֙ לִ⁠שְׁפּ֔וֹךְ וְ⁠עַל־הָ⁠עֹ֥שֶׁק וְ⁠עַל־הַ⁠מְּרוּצָ֖ה לַ⁠עֲשֽׂוֹת׃ס","ki֣̇y ʼé֤yn ʻéyne֨y⁠ká֙ wĕ⁠libĕ̇⁠ká֔ ki֖̇y ʼim-ʻal-bi̇ẕĕʻe֑⁠ká wĕ⁠ʻa֤l dȧֽm-ha⁠ná̇qiy֙ li⁠şĕ̌ṗ֔wòkĕ wĕ⁠ʻal-há⁠ʻò֥şěq wĕ⁠ʻal-ha⁠mĕ̇rẇẕá֖h la⁠ʻàşֽ̂wòţ׃s"],[22,18,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה אֶל־יְהוֹיָקִ֤ים בֶּן־יֹאשִׁיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה לֹא־יִסְפְּד֣וּ ל֔⁠וֹ ה֥וֹי אָחִ֖⁠י וְ⁠ה֣וֹי אָח֑וֹת לֹא־יִסְפְּד֣וּ ל֔⁠וֹ ה֥וֹי אָד֖וֹן וְ⁠ה֥וֹי הֹדֹֽ⁠ה׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h ʼel-yĕhwòyáqi֤ym bėn-yòʼşǐyá̇֨hẇ֙ me֣lekĕ yĕhẇdá֔h lòʼ-yisĕpĕ̇d֣ẇ l֔⁠wò h֥wòy ʼáẖi֖⁠y wĕ⁠h֣wòy ʼáẖ֑wòţ lòʼ-yisĕpĕ̇d֣ẇ l֔⁠wò h֥wòy ʼád֖wòn wĕ⁠h֥wòy hòdòֽ⁠h׃"],[22,19,"קְבוּרַ֥ת חֲמ֖וֹר יִקָּבֵ֑ר סָח֣וֹב וְ⁠הַשְׁלֵ֔ךְ מֵ⁠הָ֖לְאָה לְ⁠שַׁעֲרֵ֥י יְרוּשָׁלִָֽם׃ס","qĕbẇra֥ţ ẖàm֖wòr yiqá̇bé֑r sáẖ֣wòb wĕ⁠haşĕ̌lé֔kĕ mé⁠há֖lĕʼáh lĕ⁠şǎʻàré֥y yĕrẇşá̌liáֽm׃s"],[22,20,"עֲלִ֤י הַ⁠לְּבָנוֹן֙ וּֽ⁠צְעָ֔קִי וּ⁠בַ⁠בָּשָׁ֖ן תְּנִ֣י קוֹלֵ֑⁠ךְ וְ⁠צַֽעֲקִי֙ מֵֽ⁠עֲבָרִ֔ים כִּ֥י נִשְׁבְּר֖וּ כָּל־מְאַהֲבָֽיִ⁠ךְ׃","ʻàli֤y ha⁠lĕ̇bánwòn֙ ẇֽ⁠ẕĕʻá֔qiy ẇ⁠ba⁠bá̇şá֖̌n ţĕ̇ni֣y qwòlé֑⁠kĕ wĕ⁠ẕaֽʻàqiy֙ méֽ⁠ʻàbári֔ym ki֥̇y nişĕ̌bĕ̇r֖ẇ ká̇l-mĕʼahàbáֽyi⁠kĕ׃"],[22,21,"דִּבַּ֤רְתִּי אֵלַ֨יִ⁠ךְ֙ בְּ⁠שַׁלְוֺתַ֔יִ⁠ךְ אָמַ֖רְתְּ לֹ֣א אֶשְׁמָ֑ע זֶ֤ה דַרְכֵּ⁠ךְ֙ מִ⁠נְּעוּרַ֔יִ⁠ךְ כִּ֥י לֹֽא־שָׁמַ֖עַתְּ בְּ⁠קוֹלִֽ⁠י׃","di̇bȧ֤rĕţi̇y ʼéla֨yi⁠kĕ֙ bĕ̇⁠şǎlĕwֺţa֔yi⁠kĕ ʼáma֖rĕţĕ̇ lò֣ʼ ʼeşĕ̌má֑ʻ ze֤h darĕké̇⁠kĕ֙ mi⁠nĕ̇ʻẇra֔yi⁠kĕ ki֥̇y lòֽʼ-şá̌ma֖ʻaţĕ̇ bĕ̇⁠qwòliֽ⁠y׃"],[22,22,"כָּל־רֹעַ֨יִ⁠ךְ֙ תִּרְעֶה־ר֔וּחַ וּֽ⁠מְאַהֲבַ֖יִ⁠ךְ בַּ⁠שְּׁבִ֣י יֵלֵ֑כוּ כִּ֣י אָ֤ז תֵּבֹ֨שִׁי֙ וְ⁠נִכְלַ֔מְתְּ מִ⁠כֹּ֖ל רָעָתֵֽ⁠ךְ׃","ká̇l-ròʻa֨yi⁠kĕ֙ ţi̇rĕʻeh-r֔ẇẖa ẇֽ⁠mĕʼahàba֖yi⁠kĕ bȧ⁠şĕ̇̌bi֣y yélé֑kẇ ki֣̇y ʼá֤z ţé̇bò֨şǐy֙ wĕ⁠nikĕla֔mĕţĕ̇ mi⁠kò֖̇l ráʻáţéֽ⁠kĕ׃"],[22,23,"ישבתי בַּ⁠לְּבָנ֔וֹן מקננתי בָּֽ⁠אֲרָזִ֑ים מַה־נֵּחַנְתְּ֙ בְּ⁠בֹא־לָ֣⁠ךְ חֲבָלִ֔ים חִ֖יל כַּ⁠יֹּלֵדָֽה׃","yşbţy bȧ⁠lĕ̇bán֔wòn mqnnţy báֽ̇⁠ʼàrázi֑ym mah-né̇ẖanĕţĕ̇֙ bĕ̇⁠bòʼ-lá֣⁠kĕ ẖàbáli֔ym ẖi֖yl kȧ⁠yò̇lédáֽh׃"],[22,24,"חַי־אָנִי֮ נְאֻם־יְהוָה֒ כִּ֣י אִם־יִהְיֶ֞ה כָּנְיָ֤הוּ בֶן־יְהֽוֹיָקִים֙ מֶ֣לֶךְ יְהוּדָ֔ה חוֹתָ֖ם עַל־יַ֣ד יְמִינִ֑⁠י כִּ֥י מִ⁠שָּׁ֖ם אֶתְּקֶֽ⁠נְךָּ׃","ẖay-ʼániy֮ nĕʼum-yĕhwáh֒ ki֣̇y ʼim-yihĕye֞h ká̇nĕyá֤hẇ ben-yĕhֽwòyáqiym֙ me֣lekĕ yĕhẇdá֔h ẖwòţá֖m ʻal-ya֣d yĕmiyni֑⁠y ki֥̇y mi⁠şá֖̇̌m ʼeţĕ̇qeֽ⁠nĕká̇׃"],[22,25,"וּ⁠נְתַתִּ֗י⁠ךָ בְּ⁠יַד֙ מְבַקְשֵׁ֣י נַפְשֶׁ֔⁠ךָ וּ⁠בְ⁠יַ֛ד אֲשֶׁר־אַתָּ֥ה יָג֖וֹר מִ⁠פְּנֵי⁠הֶ֑ם וּ⁠בְ⁠יַ֛ד נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל וּ⁠בְ⁠יַ֥ד הַ⁠כַּשְׂדִּֽים׃","ẇ⁠nĕţaţi̇֗y⁠ká bĕ̇⁠yad֙ mĕbaqĕşé֣̌y napĕşě֔⁠ká ẇ⁠bĕ⁠ya֛d ʼàşěr-ʼaţá֥̇h yág֖wòr mi⁠pĕ̇néy⁠he֑m ẇ⁠bĕ⁠ya֛d nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l ẇ⁠bĕ⁠ya֥d ha⁠kȧşĕ̂diֽ̇ym׃"],[22,26,"וְ⁠הֵֽטַלְתִּ֣י אֹתְ⁠ךָ֗ וְ⁠אֶֽת־אִמְּ⁠ךָ֙ אֲשֶׁ֣ר יְלָדַ֔תְ⁠ךָ עַ֚ל הָ⁠אָ֣רֶץ אַחֶ֔רֶת אֲשֶׁ֥ר לֹֽא־יֻלַּדְתֶּ֖ם שָׁ֑ם וְ⁠שָׁ֖ם תָּמֽוּתוּ׃","wĕ⁠héֽtalĕţi֣̇y ʼòţĕ⁠ká֗ wĕ⁠ʼeֽţ-ʼimĕ̇⁠ká֙ ʼàşě֣r yĕláda֔ţĕ⁠ká ʻa֚l há⁠ʼá֣reẕ ʼaẖe֔reţ ʼàşě֥r lòֽʼ-yulȧdĕţė֖m şá֑̌m wĕ⁠şá֖̌m ţá̇mֽẇţẇ׃"],[22,27,"וְ⁠עַל־הָ⁠אָ֗רֶץ אֲשֶׁר־הֵ֛ם מְנַשְּׂאִ֥ים אֶת־נַפְשָׁ֖⁠ם לָ⁠שׁ֣וּב שָׁ֑ם שָׁ֖מָּ⁠ה לֹ֥א יָשֽׁוּבוּ׃ס","wĕ⁠ʻal-há⁠ʼá֗reẕ ʼàşěr-hé֛m mĕnaşĕ̇̂ʼi֥ym ʼeţ-napĕşá֖̌⁠m lá⁠ş֣̌ẇb şá֑̌m şá֖̌má̇⁠h lò֥ʼ yáşֽ̌ẇbẇ׃s"],[22,28,"הַ⁠עֶ֨צֶב נִבְזֶ֜ה נָפ֗וּץ הָ⁠אִ֤ישׁ הַ⁠זֶּה֙ כָּנְיָ֔הוּ אִ֨ם־כְּלִ֔י אֵ֥ין חֵ֖פֶץ בּ֑⁠וֹ מַדּ֤וּעַ הֽוּטֲלוּ֙ ה֣וּא וְ⁠זַרְע֔⁠וֹ וְ⁠הֻ֨שְׁלְכ֔וּ עַל־הָ⁠אָ֖רֶץ אֲשֶׁ֥ר לֹא־יָדָֽעוּ׃","ha⁠ʻe֨ẕeb nibĕze֜h náp֗ẇẕ há⁠ʼi֤yş̌ ha⁠zėh֙ ká̇nĕyá֔hẇ ʼi֨m-kĕ̇li֔y ʼé֥yn ẖé֖peẕ ḃ֑⁠wò maḋ֤ẇʻa hֽẇtàlẇ֙ h֣ẇʼ wĕ⁠zarĕʻ֔⁠wò wĕ⁠hu֨şĕ̌lĕk֔ẇ ʻal-há⁠ʼá֖reẕ ʼàşě֥r lòʼ-yádáֽʻẇ׃"],[22,29,"אֶ֥רֶץ אֶ֖רֶץ אָ֑רֶץ שִׁמְעִ֖י דְּבַר־יְהוָֽה׃ס","ʼe֥reẕ ʼe֖reẕ ʼá֑reẕ şǐmĕʻi֖y dĕ̇bar-yĕhwáֽh׃s"],[22,30,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה כִּתְב֞וּ אֶת־הָ⁠אִ֤ישׁ הַ⁠זֶּה֙ עֲרִירִ֔י גֶּ֖בֶר לֹא־יִצְלַ֣ח בְּ⁠יָמָ֑י⁠ו כִּי֩ לֹ֨א יִצְלַ֜ח מִ⁠זַּרְע֗⁠וֹ אִ֚ישׁ יֹשֵׁב֙ עַל־כִּסֵּ֣א דָוִ֔ד וּ⁠מֹשֵׁ֥ל ע֖וֹד בִּ⁠יהוּדָֽה׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ki̇ţĕb֞ẇ ʼeţ-há⁠ʼi֤yş̌ ha⁠zėh֙ ʻàriyri֔y gė֖ber lòʼ-yiẕĕla֣ẖ bĕ̇⁠yámá֑y⁠w ki̇y֩ lò֨ʼ yiẕĕla֜ẖ mi⁠zȧrĕʻ֗⁠wò ʼi֚yş̌ yòşé̌b֙ ʻal-ki̇sé֣̇ʼ dáwi֔d ẇ⁠mòşé֥̌l ʻ֖wòd bi̇⁠yhẇdáֽh׃"],[23,1,"ה֣וֹי רֹעִ֗ים מְאַבְּדִ֧ים וּ⁠מְפִצִ֛ים אֶת־צֹ֥אן מַרְעִיתִ֖⁠י נְאֻם־יְהוָֽה׃","h֣wòy ròʻi֗ym mĕʼabĕ̇di֧ym ẇ⁠mĕpiẕi֛ym ʼeţ-ẕò֥ʼn marĕʻiyţi֖⁠y nĕʼum-yĕhwáֽh׃"],[23,2,"לָ֠⁠כֵן כֹּֽה־אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל עַֽל־הָ⁠רֹעִים֮ הָ⁠רֹעִ֣ים אֶת־עַמִּ⁠י֒ אַתֶּ֞ם הֲפִצֹתֶ֤ם אֶת־צֹאנִ⁠י֙ וַ⁠תַּדִּח֔וּ⁠ם וְ⁠לֹ֥א פְקַדְתֶּ֖ם אֹתָ֑⁠ם הִנְ⁠נִ֨י פֹקֵ֧ד עֲלֵי⁠כֶ֛ם אֶת־רֹ֥עַ מַעַלְלֵי⁠כֶ֖ם נְאֻם־יְהוָֽה׃","lá֠⁠kén kòֽ̇h-ʼáma֨r yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l ʻaֽl-há⁠ròʻiym֮ há⁠ròʻi֣ym ʼeţ-ʻami̇⁠y֒ ʼaţė֞m hàpiẕòţe֤m ʼeţ-ẕòʼni⁠y֙ wa⁠ţȧdi̇ẖ֔ẇ⁠m wĕ⁠lò֥ʼ pĕqadĕţė֖m ʼòţá֑⁠m hinĕ⁠ni֨y pòqé֧d ʻàléy⁠ke֛m ʼeţ-rò֥ʻa maʻalĕléy⁠ke֖m nĕʼum-yĕhwáֽh׃"],[23,3,"וַ⁠אֲנִ֗י אֲקַבֵּץ֙ אֶת־שְׁאֵרִ֣ית צֹאנִ֔⁠י מִ⁠כֹּל֙ הָ⁠אֲרָצ֔וֹת אֲשֶׁר־הִדַּ֥חְתִּי אֹתָ֖⁠ם שָׁ֑ם וַ⁠הֲשִׁבֹתִ֥י אֶתְ⁠הֶ֛ן עַל־נְוֵ⁠הֶ֖ן וּ⁠פָר֥וּ וְ⁠רָבֽוּ׃","wa⁠ʼàni֗y ʼàqabé̇ẕ֙ ʼeţ-şĕ̌ʼéri֣yţ ẕòʼni֔⁠y mi⁠kò̇l֙ há⁠ʼàráẕ֔wòţ ʼàşěr-hidȧ֥ẖĕţi̇y ʼòţá֖⁠m şá֑̌m wa⁠hàşǐbòţi֥y ʼeţĕ⁠he֛n ʻal-nĕwé⁠he֖n ẇ⁠pár֥ẇ wĕ⁠rábֽẇ׃"],[23,4,"וַ⁠הֲקִמֹתִ֧י עֲלֵי⁠הֶ֛ם רֹעִ֖ים וְ⁠רָע֑וּ⁠ם וְ⁠לֹא־יִֽירְא֨וּ ע֧וֹד וְ⁠לֹא־יֵחַ֛תּוּ וְ⁠לֹ֥א יִפָּקֵ֖דוּ נְאֻם־יְהוָֽה׃ס","wa⁠hàqimòţi֧y ʻàléy⁠he֛m ròʻi֖ym wĕ⁠ráʻ֑ẇ⁠m wĕ⁠lòʼ-yiֽyrĕʼ֨ẇ ʻ֧wòd wĕ⁠lòʼ-yéẖa֛ţ̇ẇ wĕ⁠lò֥ʼ yipá̇qé֖dẇ nĕʼum-yĕhwáֽh׃s"],[23,5,"הִנֵּ֨ה יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וַ⁠הֲקִמֹתִ֥י לְ⁠דָוִ֖ד צֶ֣מַח צַדִּ֑יק וּ⁠מָ֤לַךְ מֶ֨לֶךְ֙ וְ⁠הִשְׂכִּ֔יל וְ⁠עָשָׂ֛ה מִשְׁפָּ֥ט וּ⁠צְדָקָ֖ה בָּ⁠אָֽרֶץ׃","hiné̇֨h yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wa⁠hàqimòţi֥y lĕ⁠dáwi֖d ẕe֣maẖ ẕadi֑̇yq ẇ⁠má֤lakĕ me֨lekĕ֙ wĕ⁠hişĕ̂ki̇֔yl wĕ⁠ʻáşá֛̂h mişĕ̌pá֥̇t ẇ⁠ẕĕdáqá֖h bá̇⁠ʼáֽreẕ׃"],[23,6,"בְּ⁠יָמָי⁠ו֙ תִּוָּשַׁ֣ע יְהוּדָ֔ה וְ⁠יִשְׂרָאֵ֖ל יִשְׁכֹּ֣ן לָ⁠בֶ֑טַח וְ⁠זֶה־שְּׁמ֥⁠וֹ אֲֽשֶׁר־יִקְרְא֖⁠וֹ יְהוָ֥ה ׀ צִדְקֵֽ⁠נוּ׃ס","bĕ̇⁠yámáy⁠w֙ ţi̇wá̇şǎ֣ʻ yĕhẇdá֔h wĕ⁠yişĕ̂ráʼé֖l yişĕ̌kò֣̇n lá⁠be֑taẖ wĕ⁠zeh-şĕ̇̌m֥⁠wò ʼàֽşěr-yiqĕrĕʼ֖⁠wò yĕhwá֥h ׀ ẕidĕqéֽ⁠nẇ׃s"],[23,7,"לָ⁠כֵ֛ן הִנֵּֽה־יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וְ⁠לֹא־יֹ֤אמְרוּ עוֹד֙ חַי־יְהוָ֔ה אֲשֶׁ֧ר הֶעֱלָ֛ה אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","lá⁠ké֛n hinéֽ̇h-yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h wĕ⁠lòʼ-yò֤ʼmĕrẇ ʻwòd֙ ẖay-yĕhwá֔h ʼàşě֧r heʻèlá֛h ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[23,8,"כִּ֣י אִם־חַי־יְהוָ֗ה אֲשֶׁ֣ר הֶעֱלָה֩ וַ⁠אֲשֶׁ֨ר הֵבִ֜יא אֶת־זֶ֨רַע בֵּ֤ית יִשְׂרָאֵל֙ מֵ⁠אֶ֣רֶץ צָפ֔וֹנָ⁠ה וּ⁠מִ⁠כֹּל֙ הָֽ⁠אֲרָצ֔וֹת אֲשֶׁ֥ר הִדַּחְתִּ֖י⁠ם שָׁ֑ם וְ⁠יָשְׁב֖וּ עַל־אַדְמָתָֽ⁠ם׃ס","ki֣̇y ʼim-ẖay-yĕhwá֗h ʼàşě֣r heʻèláh֩ wa⁠ʼàşě֨r hébi֜yʼ ʼeţ-ze֨raʻ bé֤̇yţ yişĕ̂ráʼél֙ mé⁠ʼe֣reẕ ẕáp֔wòná⁠h ẇ⁠mi⁠kò̇l֙ háֽ⁠ʼàráẕ֔wòţ ʼàşě֥r hidȧẖĕţi֖̇y⁠m şá֑̌m wĕ⁠yáşĕ̌b֖ẇ ʻal-ʼadĕmáţáֽ⁠m׃s"],[23,9,"לַ⁠נְּבִאִ֞ים נִשְׁבַּ֧ר לִבִּ֣⁠י בְ⁠קִרְבִּ֗⁠י רָֽחֲפוּ֙ כָּל־עַצְמוֹתַ֔⁠י הָיִ֨יתִי֙ כְּ⁠אִ֣ישׁ שִׁכּ֔וֹר וּ⁠כְ⁠גֶ֖בֶר עֲבָ֣ר⁠וֹ יָ֑יִן מִ⁠פְּנֵ֣י יְהוָ֔ה וּ⁠מִ⁠פְּנֵ֖י דִּבְרֵ֥י קָדְשֽׁ⁠וֹ׃","la⁠nĕ̇biʼi֞ym nişĕ̌bȧ֧r libi֣̇⁠y bĕ⁠qirĕbi̇֗⁠y ráֽẖàpẇ֙ ká̇l-ʻaẕĕmwòţa֔⁠y háyi֨yţiy֙ kĕ̇⁠ʼi֣yş̌ şǐk̇֔wòr ẇ⁠kĕ⁠ge֖ber ʻàbá֣r⁠wò yá֑yin mi⁠pĕ̇né֣y yĕhwá֔h ẇ⁠mi⁠pĕ̇né֖y di̇bĕré֥y qádĕşֽ̌⁠wò׃"],[23,10,"כִּ֤י מְנָֽאֲפִים֙ מָלְאָ֣ה הָ⁠אָ֔רֶץ כִּֽי־מִ⁠פְּנֵ֤י אָלָה֙ אָבְלָ֣ה הָ⁠אָ֔רֶץ יָבְשׁ֖וּ נְא֣וֹת מִדְבָּ֑ר וַ⁠תְּהִ֤י מְרֽוּצָתָ⁠ם֙ רָעָ֔ה וּ⁠גְבוּרָתָ֖⁠ם לֹא־כֵֽן׃","ki֤̇y mĕnáֽʼàpiym֙ málĕʼá֣h há⁠ʼá֔reẕ kiֽ̇y-mi⁠pĕ̇né֤y ʼáláh֙ ʼábĕlá֣h há⁠ʼá֔reẕ yábĕş֖̌ẇ nĕʼ֣wòţ midĕbá֑̇r wa⁠ţĕ̇hi֤y mĕrֽẇẕáţá⁠m֙ ráʻá֔h ẇ⁠gĕbẇráţá֖⁠m lòʼ-kéֽn׃"],[23,11,"כִּֽי־גַם־נָבִ֥יא גַם־כֹּהֵ֖ן חָנֵ֑פוּ גַּם־בְּ⁠בֵיתִ֛⁠י מָצָ֥אתִי רָעָתָ֖⁠ם נְאֻם־יְהוָֽה׃","kiֽ̇y-gam-nábi֥yʼ gam-kò̇hé֖n ẖáné֑pẇ gȧm-bĕ̇⁠béyţi֛⁠y máẕá֥ʼţiy ráʻáţá֖⁠m nĕʼum-yĕhwáֽh׃"],[23,12,"לָ⁠כֵן֩ יִֽהְיֶ֨ה דַרְכָּ֜⁠ם לָ⁠הֶ֗ם כַּ⁠חֲלַקְלַקּוֹת֙ בָּֽ⁠אֲפֵלָ֔ה יִדַּ֖חוּ וְ⁠נָ֣פְלוּ בָ֑⁠הּ כִּֽי־אָבִ֨יא עֲלֵי⁠הֶ֥ם רָעָ֛ה שְׁנַ֥ת פְּקֻדָּתָ֖⁠ם נְאֻם־יְהוָֽה׃","lá⁠kén֩ yiֽhĕye֨h darĕká̇֜⁠m lá⁠he֗m kȧ⁠ẖàlaqĕlaq̇wòţ֙ báֽ̇⁠ʼàpélá֔h yidȧ֖ẖẇ wĕ⁠ná֣pĕlẇ bá֑⁠ḣ kiֽ̇y-ʼábi֨yʼ ʻàléy⁠he֥m ráʻá֛h şĕ̌na֥ţ pĕ̇qudá̇ţá֖⁠m nĕʼum-yĕhwáֽh׃"],[23,13,"וּ⁠בִ⁠נְבִיאֵ֥י שֹׁמְר֖וֹן רָאִ֣יתִי תִפְלָ֑ה הִנַּבְּא֣וּ בַ⁠בַּ֔עַל וַ⁠יַּתְע֥וּ אֶת־עַמִּ֖⁠י אֶת־יִשְׂרָאֵֽל׃ס","ẇ⁠bi⁠nĕbiyʼé֥y şò̌mĕr֖wòn ráʼi֣yţiy ţipĕlá֑h hinȧbĕ̇ʼ֣ẇ ba⁠bȧ֔ʻal wa⁠yȧţĕʻ֥ẇ ʼeţ-ʻami֖̇⁠y ʼeţ-yişĕ̂ráʼéֽl׃s"],[23,14,"וּ⁠בִ⁠נְבִאֵ֨י יְרוּשָׁלִַ֜ם רָאִ֣יתִי שַׁעֲרוּרָ֗ה נָא֞וֹף וְ⁠הָלֹ֤ךְ בַּ⁠שֶּׁ֨קֶר֙ וְ⁠חִזְּקוּ֙ יְדֵ֣י מְרֵעִ֔ים לְ⁠בִ֨לְתִּי־שָׁ֔בוּ אִ֖ישׁ מֵ⁠רָֽעָת֑⁠וֹ הָֽיוּ־לִ֤⁠י כֻלָּ⁠ם֙ כִּ⁠סְדֹ֔ם וְ⁠יֹשְׁבֶ֖י⁠הָ כַּ⁠עֲמֹרָֽה׃ס","ẇ⁠bi⁠nĕbiʼé֨y yĕrẇşá̌lia֜m ráʼi֣yţiy şǎʻàrẇrá֗h náʼ֞wòp wĕ⁠hálò֤kĕ bȧ⁠şė̌֨qer֙ wĕ⁠ẖizĕ̇qẇ֙ yĕdé֣y mĕréʻi֔ym lĕ⁠bi֨lĕţi̇y-şá̌֔bẇ ʼi֖yş̌ mé⁠ráֽʻáţ֑⁠wò háֽyẇ-li֤⁠y kulá̇⁠m֙ ki̇⁠sĕdò֔m wĕ⁠yòşĕ̌be֖y⁠há kȧ⁠ʻàmòráֽh׃s"],[23,15,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֨ר יְהוָ֤ה צְבָאוֹת֙ עַל־הַ⁠נְּבִאִ֔ים הִנְ⁠נִ֨י מַאֲכִ֤יל אוֹתָ⁠ם֙ לַֽעֲנָ֔ה וְ⁠הִשְׁקִתִ֖י⁠ם מֵי־רֹ֑אשׁ כִּ֗י מֵ⁠אֵת֙ נְבִיאֵ֣י יְרוּשָׁלִַ֔ם יָצְאָ֥ה חֲנֻפָּ֖ה לְ⁠כָל־הָ⁠אָֽרֶץ׃פ","lá⁠ké֞n kòֽ̇h-ʼáma֨r yĕhwá֤h ẕĕbáʼwòţ֙ ʻal-ha⁠nĕ̇biʼi֔ym hinĕ⁠ni֨y maʼàki֤yl ʼwòţá⁠m֙ laֽʻàná֔h wĕ⁠hişĕ̌qiţi֖y⁠m méy-rò֑ʼş̌ ki̇֗y mé⁠ʼéţ֙ nĕbiyʼé֣y yĕrẇşá̌lia֔m yáẕĕʼá֥h ẖànupá֖̇h lĕ⁠kál-há⁠ʼáֽreẕ׃p"],[23,16,"כֹּֽה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת אַֽל־תִּשְׁמְע֞וּ עַל־דִּבְרֵ֤י הַ⁠נְּבִאִים֙ הַ⁠נִּבְּאִ֣ים לָ⁠כֶ֔ם מַהְבִּלִ֥ים הֵ֖מָּה אֶתְ⁠כֶ֑ם חֲז֤וֹן לִבָּ⁠ם֙ יְדַבֵּ֔רוּ לֹ֖א מִ⁠פִּ֥י יְהוָֽה׃","kòֽ̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ʼaֽl-ţi̇şĕ̌mĕʻ֞ẇ ʻal-di̇bĕré֤y ha⁠nĕ̇biʼiym֙ ha⁠ni̇bĕ̇ʼi֣ym lá⁠ke֔m mahĕbi̇li֥ym hé֖má̇h ʼeţĕ⁠ke֑m ẖàz֤wòn libá̇⁠m֙ yĕdabé̇֔rẇ lò֖ʼ mi⁠pi֥̇y yĕhwáֽh׃"],[23,17,"אֹמְרִ֤ים אָמוֹר֙ לִֽ⁠מְנַאֲצַ֔⁠י דִּבֶּ֣ר יְהוָ֔ה שָׁל֖וֹם יִֽהְיֶ֣ה לָ⁠כֶ֑ם וְ֠⁠כֹל הֹלֵ֞ךְ בִּ⁠שְׁרִר֤וּת לִבּ⁠וֹ֙ אָֽמְר֔וּ לֹֽא־תָב֥וֹא עֲלֵי⁠כֶ֖ם רָעָֽה׃","ʼòmĕri֤ym ʼámwòr֙ liֽ⁠mĕnaʼàẕa֔⁠y di̇bė֣r yĕhwá֔h şá̌l֖wòm yiֽhĕye֣h lá⁠ke֑m wĕ֠⁠kòl hòlé֞kĕ bi̇⁠şĕ̌rir֤ẇţ liḃ⁠wò֙ ʼáֽmĕr֔ẇ lòֽʼ-ţáb֥wòʼ ʻàléy⁠ke֖m ráʻáֽh׃"],[23,18,"כִּ֣י מִ֤י עָמַד֙ בְּ⁠ס֣וֹד יְהוָ֔ה וְ⁠יֵ֖רֶא וְ⁠יִשְׁמַ֣ע אֶת־דְּבָר֑⁠וֹ מִֽי־הִקְשִׁ֥יב דבר⁠י וַ⁠יִּשְׁמָֽע׃ס","ki֣̇y mi֤y ʻámad֙ bĕ̇⁠s֣wòd yĕhwá֔h wĕ⁠yé֖reʼ wĕ⁠yişĕ̌ma֣ʻ ʼeţ-dĕ̇bár֑⁠wò miֽy-hiqĕşǐ֥yb dbr⁠y wa⁠yi̇şĕ̌máֽʻ׃s"],[23,19,"הִנֵּ֣ה ׀ סַעֲרַ֣ת יְהוָ֗ה חֵמָה֙ יָֽצְאָ֔ה וְ⁠סַ֖עַר מִתְחוֹלֵ֑ל עַ֛ל רֹ֥אשׁ רְשָׁעִ֖ים יָחֽוּל׃","hiné֣̇h ׀ saʻàra֣ţ yĕhwá֗h ẖémáh֙ yáֽẕĕʼá֔h wĕ⁠sa֖ʻar miţĕẖwòlé֑l ʻa֛l rò֥ʼş̌ rĕşá̌ʻi֖ym yáẖֽẇl׃"],[23,20,"לֹ֤א יָשׁוּב֙ אַף־יְהוָ֔ה עַד־עֲשֹׂת֥⁠וֹ וְ⁠עַד־הֲקִימ֖⁠וֹ מְזִמּ֣וֹת לִבּ֑⁠וֹ בְּ⁠אַֽחֲרִית֙ הַ⁠יָּמִ֔ים תִּתְבּ֥וֹנְנוּ בָ֖⁠הּ בִּינָֽה׃","lò֤ʼ yáş̌ẇb֙ ʼap-yĕhwá֔h ʻad-ʻàşò̂ţ֥⁠wò wĕ⁠ʻad-hàqiym֖⁠wò mĕziṁ֣wòţ liḃ֑⁠wò bĕ̇⁠ʼaֽẖàriyţ֙ ha⁠yá̇mi֔ym ţi̇ţĕḃ֥wònĕnẇ bá֖⁠ḣ bi̇ynáֽh׃"],[23,21,"לֹא־שָׁלַ֥חְתִּי אֶת־הַ⁠נְּבִאִ֖ים וְ⁠הֵ֣ם רָ֑צוּ לֹא־דִבַּ֥רְתִּי אֲלֵי⁠הֶ֖ם וְ⁠הֵ֥ם נִבָּֽאוּ׃","lòʼ-şá̌la֥ẖĕţi̇y ʼeţ-ha⁠nĕ̇biʼi֖ym wĕ⁠hé֣m rá֑ẕẇ lòʼ-dibȧ֥rĕţi̇y ʼàléy⁠he֖m wĕ⁠hé֥m nibáֽ̇ʼẇ׃"],[23,22,"וְ⁠אִֽם־עָמְד֖וּ בְּ⁠סוֹדִ֑⁠י וְ⁠יַשְׁמִ֤עוּ דְבָרַ⁠י֙ אֶת־עַמִּ֔⁠י וִֽ⁠ישִׁבוּ⁠ם֙ מִ⁠דַּרְכָּ֣⁠ם הָ⁠רָ֔ע וּ⁠מֵ⁠רֹ֖עַ מַֽעַלְלֵי⁠הֶֽם׃ס","wĕ⁠ʼiֽm-ʻámĕd֖ẇ bĕ̇⁠swòdi֑⁠y wĕ⁠yaşĕ̌mi֤ʻẇ dĕbára⁠y֙ ʼeţ-ʻami̇֔⁠y wiֽ⁠yşǐbẇ⁠m֙ mi⁠dȧrĕká֣̇⁠m há⁠rá֔ʻ ẇ⁠mé⁠rò֖ʻa maֽʻalĕléy⁠heֽm׃s"],[23,23,"הַ⁠אֱלֹהֵ֧י מִ⁠קָּרֹ֛ב אָ֖נִי נְאֻם־יְהוָ֑ה וְ⁠לֹ֥א אֱלֹהֵ֖י מֵ⁠רָחֹֽק׃","ha⁠ʼèlòhé֧y mi⁠qá̇rò֛b ʼá֖niy nĕʼum-yĕhwá֑h wĕ⁠lò֥ʼ ʼèlòhé֖y mé⁠ráẖòֽq׃"],[23,24,"אִם־יִסָּתֵ֨ר אִ֧ישׁ בַּ⁠מִּסְתָּרִ֛ים וַ⁠אֲנִ֥י לֹֽא־אֶרְאֶ֖⁠נּוּ נְאֻם־יְהוָ֑ה הֲ⁠ל֨וֹא אֶת־הַ⁠שָּׁמַ֧יִם וְ⁠אֶת־הָ⁠אָ֛רֶץ אֲנִ֥י מָלֵ֖א נְאֻם־יְהוָֽה׃","ʼim-yisá̇ţé֨r ʼi֧yş̌ bȧ⁠mi̇sĕţá̇ri֛ym wa⁠ʼàni֥y lòֽʼ-ʼerĕʼe֖⁠ṅẇ nĕʼum-yĕhwá֑h hà⁠l֨wòʼ ʼeţ-ha⁠şá̇̌ma֧yim wĕ⁠ʼeţ-há⁠ʼá֛reẕ ʼàni֥y málé֖ʼ nĕʼum-yĕhwáֽh׃"],[23,25,"שָׁמַ֗עְתִּי אֵ֤ת אֲשֶׁר־אָֽמְרוּ֙ הַ⁠נְּבִאִ֔ים הַֽ⁠נִּבְּאִ֥ים בִּ⁠שְׁמִ֛⁠י שֶׁ֖קֶר לֵ⁠אמֹ֑ר חָלַ֖מְתִּי חָלָֽמְתִּי׃","şá̌ma֗ʻĕţi̇y ʼé֤ţ ʼàşěr-ʼáֽmĕrẇ֙ ha⁠nĕ̇biʼi֔ym haֽ⁠ni̇bĕ̇ʼi֥ym bi̇⁠şĕ̌mi֛⁠y şě֖qer lé⁠ʼmò֑r ẖála֖mĕţi̇y ẖáláֽmĕţi̇y׃"],[23,26,"עַד־מָתַ֗י הֲ⁠יֵ֛שׁ בְּ⁠לֵ֥ב הַ⁠נְּבִאִ֖ים נִבְּאֵ֣י הַ⁠שָּׁ֑קֶר וּ⁠נְבִיאֵ֖י תַּרְמִ֥ת לִבָּֽ⁠ם׃","ʻad-máţa֗y hà⁠yé֛ş̌ bĕ̇⁠lé֥b ha⁠nĕ̇biʼi֖ym nibĕ̇ʼé֣y ha⁠şá֑̇̌qer ẇ⁠nĕbiyʼé֖y ţȧrĕmi֥ţ libáֽ̇⁠m׃"],[23,27,"הַ⁠חֹשְׁבִ֗ים לְ⁠הַשְׁכִּ֤יחַ אֶת־עַמִּ⁠י֙ שְׁמִ֔⁠י בַּ⁠חֲל֣וֹמֹתָ֔⁠ם אֲשֶׁ֥ר יְסַפְּר֖וּ אִ֣ישׁ לְ⁠רֵעֵ֑⁠הוּ כַּ⁠אֲשֶׁ֨ר שָׁכְח֧וּ אֲבוֹתָ֛⁠ם אֶת־שְׁמִ֖⁠י בַּ⁠בָּֽעַל׃","ha⁠ẖòşĕ̌bi֗ym lĕ⁠haşĕ̌ki֤̇yẖa ʼeţ-ʻami̇⁠y֙ şĕ̌mi֔⁠y bȧ⁠ẖàl֣wòmòţá֔⁠m ʼàşě֥r yĕsapĕ̇r֖ẇ ʼi֣yş̌ lĕ⁠réʻé֑⁠hẇ kȧ⁠ʼàşě֨r şá̌kĕẖ֧ẇ ʼàbwòţá֛⁠m ʼeţ-şĕ̌mi֖⁠y bȧ⁠báֽ̇ʻal׃"],[23,28,"הַ⁠נָּבִ֞יא אֲשֶׁר־אִתּ֤⁠וֹ חֲלוֹם֙ יְסַפֵּ֣ר חֲל֔וֹם וַ⁠אֲשֶׁ֤ר דְּבָרִ⁠י֙ אִתּ֔⁠וֹ יְדַבֵּ֥ר דְּבָרִ֖⁠י אֱמֶ֑ת מַה־לַ⁠תֶּ֥בֶן אֶת־הַ⁠בָּ֖ר נְאֻם־יְהוָֽה׃","ha⁠ná̇bi֞yʼ ʼàşěr-ʼiţ֤̇⁠wò ẖàlwòm֙ yĕsapé֣̇r ẖàl֔wòm wa⁠ʼàşě֤r dĕ̇bári⁠y֙ ʼiţ̇֔⁠wò yĕdabé֥̇r dĕ̇bári֖⁠y ʼème֑ţ mah-la⁠ţė֥ben ʼeţ-ha⁠bá֖̇r nĕʼum-yĕhwáֽh׃"],[23,29,"הֲ⁠ל֨וֹא כֹ֧ה דְבָרִ֛⁠י כָּ⁠אֵ֖שׁ נְאֻם־יְהוָ֑ה וּ⁠כְ⁠פַטִּ֖ישׁ יְפֹ֥צֵֽץ סָֽלַע׃ס","hà⁠l֨wòʼ kò֧h dĕbári֛⁠y ká̇⁠ʼé֖ş̌ nĕʼum-yĕhwá֑h ẇ⁠kĕ⁠pati֖̇yş̌ yĕpò֥ẕéֽẕ sáֽlaʻ׃s"],[23,30,"לָ⁠כֵ֛ן הִנְ⁠נִ֥י עַל־הַ⁠נְּבִאִ֖ים נְאֻם־יְהוָ֑ה מְגַנְּבֵ֣י דְבָרַ֔⁠י אִ֖ישׁ מֵ⁠אֵ֥ת רֵעֵֽ⁠הוּ׃","lá⁠ké֛n hinĕ⁠ni֥y ʻal-ha⁠nĕ̇biʼi֖ym nĕʼum-yĕhwá֑h mĕganĕ̇bé֣y dĕbára֔⁠y ʼi֖yş̌ mé⁠ʼé֥ţ réʻéֽ⁠hẇ׃"],[23,31,"הִנְ⁠נִ֥י עַל־הַ⁠נְּבִיאִ֖ם נְאֻם־יְהוָ֑ה הַ⁠לֹּקְחִ֣ים לְשׁוֹנָ֔⁠ם וַֽ⁠יִּנְאֲמ֖וּ נְאֻֽם׃","hinĕ⁠ni֥y ʻal-ha⁠nĕ̇biyʼi֖m nĕʼum-yĕhwá֑h ha⁠lò̇qĕẖi֣ym lĕş̌wòná֔⁠m waֽ⁠yi̇nĕʼàm֖ẇ nĕʼuֽm׃"],[23,32,"הִ֠נְ⁠נִי עַֽל־נִבְּאֵ֞י חֲלֹמ֥וֹת שֶׁ֨קֶר֙ נְאֻם־יְהוָ֔ה וַֽ⁠יְסַפְּרוּ⁠ם֙ וַ⁠יַּתְע֣וּ אֶת־עַמִּ֔⁠י בְּ⁠שִׁקְרֵי⁠הֶ֖ם וּ⁠בְ⁠פַחֲזוּתָ֑⁠ם וְ⁠אָנֹכִ֨י לֹֽא־שְׁלַחְתִּ֜י⁠ם וְ⁠לֹ֣א צִוִּיתִ֗י⁠ם וְ⁠הוֹעֵ֛יל לֹֽא־יוֹעִ֥ילוּ לָֽ⁠עָם־הַ⁠זֶּ֖ה נְאֻם־יְהוָֽה׃","hi֠nĕ⁠niy ʻaֽl-nibĕ̇ʼé֞y ẖàlòm֥wòţ şě֨qer֙ nĕʼum-yĕhwá֔h waֽ⁠yĕsapĕ̇rẇ⁠m֙ wa⁠yȧţĕʻ֣ẇ ʼeţ-ʻami̇֔⁠y bĕ̇⁠şǐqĕréy⁠he֖m ẇ⁠bĕ⁠paẖàzẇţá֑⁠m wĕ⁠ʼánòki֨y lòֽʼ-şĕ̌laẖĕţi̇֜y⁠m wĕ⁠lò֣ʼ ẕiwi̇yţi֗y⁠m wĕ⁠hwòʻé֛yl lòֽʼ-ywòʻi֥ylẇ láֽ⁠ʻám-ha⁠zė֖h nĕʼum-yĕhwáֽh׃"],[23,33,"וְ⁠כִי־יִשְׁאָלְ⁠ךָ֩ הָ⁠עָ֨ם הַ⁠זֶּ֜ה אֽוֹ־הַ⁠נָּבִ֤יא אֽוֹ־כֹהֵן֙ לֵ⁠אמֹ֔ר מַה־מַשָּׂ֖א יְהוָ֑ה וְ⁠אָמַרְתָּ֤ אֲלֵי⁠הֶם֙ אֶת־מַה־מַשָּׂ֔א וְ⁠נָטַשְׁתִּ֥י אֶתְ⁠כֶ֖ם נְאֻם־יְהוָֽה׃","wĕ⁠kiy-yişĕ̌ʼálĕ⁠ká֩ há⁠ʻá֨m ha⁠zė֜h ʼֽwò-ha⁠ná̇bi֤yʼ ʼֽwò-kòhén֙ lé⁠ʼmò֔r mah-maşá֖̇̂ʼ yĕhwá֑h wĕ⁠ʼámarĕţá֤̇ ʼàléy⁠hem֙ ʼeţ-mah-maşá̇̂֔ʼ wĕ⁠nátaşĕ̌ţi֥̇y ʼeţĕ⁠ke֖m nĕʼum-yĕhwáֽh׃"],[23,34,"וְ⁠הַ⁠נָּבִ֤יא וְ⁠הַ⁠כֹּהֵן֙ וְ⁠הָ⁠עָ֔ם אֲשֶׁ֥ר יֹאמַ֖ר מַשָּׂ֣א יְהוָ֑ה וּ⁠פָקַדְתִּ֛י עַל־הָ⁠אִ֥ישׁ הַ⁠ה֖וּא וְ⁠עַל־בֵּיתֽ⁠וֹ׃","wĕ⁠ha⁠ná̇bi֤yʼ wĕ⁠ha⁠kò̇hén֙ wĕ⁠há⁠ʻá֔m ʼàşě֥r yòʼma֖r maşá֣̇̂ʼ yĕhwá֑h ẇ⁠páqadĕţi֛̇y ʻal-há⁠ʼi֥yş̌ ha⁠h֖ẇʼ wĕ⁠ʻal-bé̇yţֽ⁠wò׃"],[23,35,"כֹּ֥ה תֹאמְר֛וּ אִ֥ישׁ עַל־רֵעֵ֖⁠הוּ וְ⁠אִ֣ישׁ אֶל־אָחִ֑י⁠ו מֶה־עָנָ֣ה יְהוָ֔ה וּ⁠מַה־דִּבֶּ֖ר יְהוָֽה׃","kò֥̇h ţòʼmĕr֛ẇ ʼi֥yş̌ ʻal-réʻé֖⁠hẇ wĕ⁠ʼi֣yş̌ ʼel-ʼáẖi֑y⁠w meh-ʻáná֣h yĕhwá֔h ẇ⁠mah-di̇bė֖r yĕhwáֽh׃"],[23,36,"וּ⁠מַשָּׂ֥א יְהוָ֖ה לֹ֣א תִזְכְּרוּ־ע֑וֹד כִּ֣י הַ⁠מַּשָּׂ֗א יִֽהְיֶה֙ לְ⁠אִ֣ישׁ דְּבָר֔⁠וֹ וַ⁠הֲפַכְתֶּ֗ם אֶת־דִּבְרֵי֙ אֱלֹהִ֣ים חַיִּ֔ים יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵֽי⁠נוּ׃","ẇ⁠maşá֥̇̂ʼ yĕhwá֖h lò֣ʼ ţizĕkĕ̇rẇ-ʻ֑wòd ki֣̇y ha⁠mȧşá̇̂֗ʼ yiֽhĕyeh֙ lĕ⁠ʼi֣yş̌ dĕ̇bár֔⁠wò wa⁠hàpakĕţė֗m ʼeţ-di̇bĕréy֙ ʼèlòhi֣ym ẖayi̇֔ym yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhéֽy⁠nẇ׃"],[23,37,"כֹּ֥ה תֹאמַ֖ר אֶל־הַ⁠נָּבִ֑יא מֶה־עָנָ֣⁠ךְ יְהוָ֔ה וּ⁠מַה־דִּבֶּ֖ר יְהוָֽה׃","kò֥̇h ţòʼma֖r ʼel-ha⁠ná̇bi֑yʼ meh-ʻáná֣⁠kĕ yĕhwá֔h ẇ⁠mah-di̇bė֖r yĕhwáֽh׃"],[23,38,"וְ⁠אִם־מַשָּׂ֣א יְהוָה֮ תֹּאמֵרוּ֒ לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה יַ֧עַן אֲמָרְ⁠כֶ֛ם אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה מַשָּׂ֣א יְהוָ֑ה וָ⁠אֶשְׁלַ֤ח אֲלֵי⁠כֶם֙ לֵ⁠אמֹ֔ר לֹ֥א תֹאמְר֖וּ מַשָּׂ֥א יְהוָֽה׃","wĕ⁠ʼim-maşá֣̇̂ʼ yĕhwáh֮ ţò̇ʼmérẇ֒ lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h ya֧ʻan ʼàmárĕ⁠ke֛m ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h maşá֣̇̂ʼ yĕhwá֑h wá⁠ʼeşĕ̌la֤ẖ ʼàléy⁠kem֙ lé⁠ʼmò֔r lò֥ʼ ţòʼmĕr֖ẇ maşá֥̇̂ʼ yĕhwáֽh׃"],[23,39,"לָ⁠כֵ֣ן הִנְ⁠נִ֔י וְ⁠נָשִׁ֥יתִי אֶתְ⁠כֶ֖ם נָשֹׁ֑א וְ⁠נָטַשְׁתִּ֣י אֶתְ⁠כֶ֗ם וְ⁠אֶת־הָ⁠עִיר֙ אֲשֶׁ֨ר נָתַ֧תִּי לָ⁠כֶ֛ם וְ⁠לַ⁠אֲבוֹתֵי⁠כֶ֖ם מֵ⁠עַ֥ל פָּנָֽ⁠י׃","lá⁠ké֣n hinĕ⁠ni֔y wĕ⁠náşǐ֥yţiy ʼeţĕ⁠ke֖m náşò֑̌ʼ wĕ⁠nátaşĕ̌ţi֣̇y ʼeţĕ⁠ke֗m wĕ⁠ʼeţ-há⁠ʻiyr֙ ʼàşě֨r náţa֧ţi̇y lá⁠ke֛m wĕ⁠la⁠ʼàbwòţéy⁠ke֖m mé⁠ʻa֥l pá̇náֽ⁠y׃"],[23,40,"וְ⁠נָתַתִּ֥י עֲלֵי⁠כֶ֖ם חֶרְפַּ֣ת עוֹלָ֑ם וּ⁠כְלִמּ֣וּת עוֹלָ֔ם אֲשֶׁ֖ר לֹ֥א תִשָּׁכֵֽחַ׃ס","wĕ⁠náţaţi֥̇y ʻàléy⁠ke֖m ẖerĕpȧ֣ţ ʻwòlá֑m ẇ⁠kĕliṁ֣ẇţ ʻwòlá֔m ʼàşě֖r lò֥ʼ ţişá̇̌kéֽẖa׃s"],[24,1,"הִרְאַ⁠נִי֮ יְהוָה֒ וְ⁠הִנֵּ֗ה שְׁנֵי֙ דּוּדָאֵ֣י תְאֵנִ֔ים מוּעָדִ֕ים לִ⁠פְנֵ֖י הֵיכַ֣ל יְהוָ֑ה אַחֲרֵ֣י הַגְל֣וֹת נְבוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֡ל אֶת־יְכָנְיָ֣הוּ בֶן־יְהוֹיָקִ֣ים מֶֽלֶךְ־יְהוּדָה֩ וְ⁠אֶת־שָׂרֵ֨י יְהוּדָ֜ה וְ⁠אֶת־הֶ⁠חָרָ֤שׁ וְ⁠אֶת־הַ⁠מַּסְגֵּר֙ מִ⁠יר֣וּשָׁלִַ֔ם וַ⁠יְבִאֵ֖⁠ם בָּבֶֽל׃","hirĕʼa⁠niy֮ yĕhwáh֒ wĕ⁠hiné̇֗h şĕ̌néy֙ ḋẇdáʼé֣y ţĕʼéni֔ym mẇʻádi֕ym li⁠pĕné֖y héyka֣l yĕhwá֑h ʼaẖàré֣y hagĕl֣wòţ nĕbẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇be֡l ʼeţ-yĕkánĕyá֣hẇ ben-yĕhwòyáqi֣ym meֽlekĕ-yĕhẇdáh֩ wĕ⁠ʼeţ-şá̂ré֨y yĕhẇdá֜h wĕ⁠ʼeţ-he⁠ẖárá֤ş̌ wĕ⁠ʼeţ-ha⁠mȧsĕgé̇r֙ mi⁠yr֣ẇşá̌lia֔m wa⁠yĕbiʼé֖⁠m bá̇beֽl׃"],[24,2,"הַ⁠דּ֣וּד אֶחָ֗ד תְּאֵנִים֙ טֹב֣וֹת מְאֹ֔ד כִּ⁠תְאֵנֵ֖י הַ⁠בַּכֻּר֑וֹת וְ⁠הַ⁠דּ֣וּד אֶחָ֗ד תְּאֵנִים֙ רָע֣וֹת מְאֹ֔ד אֲשֶׁ֥ר לֹא־תֵֽאָכַ֖לְנָה מֵ⁠רֹֽעַ׃ס","ha⁠ḋ֣ẇd ʼeẖá֗d ţĕ̇ʼéniym֙ tòb֣wòţ mĕʼò֔d ki̇⁠ţĕʼéné֖y ha⁠bȧku̇r֑wòţ wĕ⁠ha⁠ḋ֣ẇd ʼeẖá֗d ţĕ̇ʼéniym֙ ráʻ֣wòţ mĕʼò֔d ʼàşě֥r lòʼ-ţéֽʼáka֖lĕnáh mé⁠ròֽʻa׃s"],[24,3,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י מָֽה־אַתָּ֤ה רֹאֶה֙ יִרְמְיָ֔הוּ וָ⁠אֹמַ֖ר תְּאֵנִ֑ים הַ⁠תְּאֵנִ֤ים הַ⁠טֹּבוֹת֙ טֹב֣וֹת מְאֹ֔ד וְ⁠הָֽ⁠רָעוֹת֙ רָע֣וֹת מְאֹ֔ד אֲשֶׁ֥ר לֹא־תֵאָכַ֖לְנָה מֵ⁠רֹֽעַ׃פ","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y máֽh-ʼaţá֤̇h ròʼeh֙ yirĕmĕyá֔hẇ wá⁠ʼòma֖r ţĕ̇ʼéni֑ym ha⁠ţĕ̇ʼéni֤ym ha⁠tò̇bwòţ֙ tòb֣wòţ mĕʼò֔d wĕ⁠háֽ⁠ráʻwòţ֙ ráʻ֣wòţ mĕʼò֔d ʼàşě֥r lòʼ-ţéʼáka֖lĕnáh mé⁠ròֽʻa׃p"],[24,4,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[24,5,"כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כַּ⁠תְּאֵנִ֥ים הַ⁠טֹּב֖וֹת הָ⁠אֵ֑לֶּה כֵּֽן־אַכִּ֞יר אֶת־גָּל֣וּת יְהוּדָ֗ה אֲשֶׁ֨ר שִׁלַּ֜חְתִּי מִן־הַ⁠מָּק֥וֹם הַ⁠זֶּ֛ה אֶ֥רֶץ כַּשְׂדִּ֖ים לְ⁠טוֹבָֽה׃","kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kȧ⁠ţĕ̇ʼéni֥ym ha⁠tò̇b֖wòţ há⁠ʼé֑lėh kéֽ̇n-ʼaki̇֞yr ʼeţ-gá̇l֣ẇţ yĕhẇdá֗h ʼàşě֨r şǐlȧ֜ẖĕţi̇y min-ha⁠má̇q֥wòm ha⁠zė֛h ʼe֥reẕ kȧşĕ̂di֖̇ym lĕ⁠twòbáֽh׃"],[24,6,"וְ⁠שַׂמְתִּ֨י עֵינִ֤⁠י עֲלֵי⁠הֶם֙ לְ⁠טוֹבָ֔ה וַ⁠הֲשִׁבֹתִ֖י⁠ם עַל־הָ⁠אָ֣רֶץ הַ⁠זֹּ֑את וּ⁠בְנִיתִי⁠ם֙ וְ⁠לֹ֣א אֶהֱרֹ֔ס וּ⁠נְטַעְתִּ֖י⁠ם וְ⁠לֹ֥א אֶתּֽוֹשׁ׃","wĕ⁠şâmĕţi̇֨y ʻéyni֤⁠y ʻàléy⁠hem֙ lĕ⁠twòbá֔h wa⁠hàşǐbòţi֖y⁠m ʻal-há⁠ʼá֣reẕ ha⁠zò֑̇ʼţ ẇ⁠bĕniyţiy⁠m֙ wĕ⁠lò֣ʼ ʼehèrò֔s ẇ⁠nĕtaʻĕţi֖̇y⁠m wĕ⁠lò֥ʼ ʼeţֽ̇wòş̌׃"],[24,7,"וְ⁠נָתַתִּי֩ לָ⁠הֶ֨ם לֵ֜ב לָ⁠דַ֣עַת אֹתִ֗⁠י כִּ֚י אֲנִ֣י יְהוָ֔ה וְ⁠הָיוּ־לִ֣⁠י לְ⁠עָ֔ם וְ⁠אָ֣נֹכִ֔י אֶהְיֶ֥ה לָ⁠הֶ֖ם לֵ⁠אלֹהִ֑ים כִּֽי־יָשֻׁ֥בוּ אֵלַ֖⁠י בְּ⁠כָל־לִבָּֽ⁠ם׃ס","wĕ⁠náţaţi̇y֩ lá⁠he֨m lé֜b lá⁠da֣ʻaţ ʼòţi֗⁠y ki֚̇y ʼàni֣y yĕhwá֔h wĕ⁠háyẇ-li֣⁠y lĕ⁠ʻá֔m wĕ⁠ʼá֣nòki֔y ʼehĕye֥h lá⁠he֖m lé⁠ʼlòhi֑ym kiֽ̇y-yáşǔ֥bẇ ʼéla֖⁠y bĕ̇⁠kál-libáֽ̇⁠m׃s"],[24,8,"וְ⁠כַ⁠תְּאֵנִים֙ הָֽ⁠רָע֔וֹת אֲשֶׁ֥ר לֹא־תֵאָכַ֖לְנָה מֵ⁠רֹ֑עַ כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה כֵּ֣ן אֶ֠תֵּן אֶת־צִדְקִיָּ֨הוּ מֶֽלֶךְ־יְהוּדָ֤ה וְ⁠אֶת־שָׂרָי⁠ו֙ וְ⁠אֵ֣ת ׀ שְׁאֵרִ֣ית יְרוּשָׁלִַ֗ם הַ⁠נִּשְׁאָרִים֙ בָּ⁠אָ֣רֶץ הַ⁠זֹּ֔את וְ⁠הַ⁠יֹּשְׁבִ֖ים בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ka⁠ţĕ̇ʼéniym֙ háֽ⁠ráʻ֔wòţ ʼàşě֥r lòʼ-ţéʼáka֖lĕnáh mé⁠rò֑ʻa ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ké֣̇n ʼe֠ţé̇n ʼeţ-ẕidĕqiyá̇֨hẇ meֽlekĕ-yĕhẇdá֤h wĕ⁠ʼeţ-şá̂ráy⁠w֙ wĕ⁠ʼé֣ţ ׀ şĕ̌ʼéri֣yţ yĕrẇşá̌lia֗m ha⁠ni̇şĕ̌ʼáriym֙ bá̇⁠ʼá֣reẕ ha⁠zò̇֔ʼţ wĕ⁠ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[24,9,"וּ⁠נְתַתִּי⁠ם֙ ל⁠זועה לְ⁠רָעָ֔ה לְ⁠כֹ֖ל מַמְלְכ֣וֹת הָ⁠אָ֑רֶץ לְ⁠חֶרְפָּ֤ה וּ⁠לְ⁠מָשָׁל֙ לִ⁠שְׁנִינָ֣ה וְ⁠לִ⁠קְלָלָ֔ה בְּ⁠כָל־הַ⁠מְּקֹמ֖וֹת אֲשֶֽׁר־אַדִּיחֵ֥⁠ם שָֽׁם׃","ẇ⁠nĕţaţi̇y⁠m֙ l⁠zwʻh lĕ⁠ráʻá֔h lĕ⁠kò֖l mamĕlĕk֣wòţ há⁠ʼá֑reẕ lĕ⁠ẖerĕpá֤̇h ẇ⁠lĕ⁠máşá̌l֙ li⁠şĕ̌niyná֣h wĕ⁠li⁠qĕlálá֔h bĕ̇⁠kál-ha⁠mĕ̇qòm֖wòţ ʼàşěֽr-ʼadi̇yẖé֥⁠m şáֽ̌m׃"],[24,10,"וְ⁠שִׁלַּ֣חְתִּי בָ֔⁠ם אֶת־הַ⁠חֶ֖רֶב אֶת־הָ⁠רָעָ֣ב וְ⁠אֶת־הַ⁠דָּ֑בֶר עַד־תֻּמָּ⁠ם֙ מֵ⁠עַ֣ל הָ⁠אֲדָמָ֔ה אֲשֶׁר־נָתַ֥תִּי לָ⁠הֶ֖ם וְ⁠לַ⁠אֲבוֹתֵי⁠הֶֽם׃פ","wĕ⁠şǐlȧ֣ẖĕţi̇y bá֔⁠m ʼeţ-ha⁠ẖe֖reb ʼeţ-há⁠ráʻá֣b wĕ⁠ʼeţ-ha⁠dá֑̇ber ʻad-ţu̇má̇⁠m֙ mé⁠ʻa֣l há⁠ʼàdámá֔h ʼàşěr-náţa֥ţi̇y lá⁠he֖m wĕ⁠la⁠ʼàbwòţéy⁠heֽm׃p"],[25,1,"הַ⁠דָּבָ֞ר אֲשֶׁר־הָיָ֤ה עַֽל־יִרְמְיָ֨הוּ֙ עַל־כָּל־עַ֣ם יְהוּדָ֔ה בַּ⁠שָּׁנָה֙ הָֽ⁠רְבִעִ֔ית לִ⁠יהוֹיָקִ֥ים בֶּן־יֹאשִׁיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה הִ֗יא הַ⁠שָּׁנָה֙ הָ⁠רִ֣אשֹׁנִ֔ית לִ⁠נְבֽוּכַדְרֶאצַּ֖ר מֶ֥לֶךְ בָּבֶֽל׃","ha⁠dá̇bá֞r ʼàşěr-háyá֤h ʻaֽl-yirĕmĕyá֨hẇ֙ ʻal-ká̇l-ʻa֣m yĕhẇdá֔h bȧ⁠şá̇̌náh֙ háֽ⁠rĕbiʻi֔yţ li⁠yhwòyáqi֥ym bėn-yòʼşǐyá֖̇hẇ me֣lekĕ yĕhẇdá֑h hi֗yʼ ha⁠şá̇̌náh֙ há⁠ri֣ʼşò̌ni֔yţ li⁠nĕbֽẇkadĕreʼẕȧ֖r me֥lekĕ bá̇beֽl׃"],[25,2,"אֲשֶׁ֨ר דִּבֶּ֜ר יִרְמְיָ֤הוּ הַ⁠נָּבִיא֙ עַל־כָּל־עַ֣ם יְהוּדָ֔ה וְ⁠אֶ֛ל כָּל־יֹשְׁבֵ֥י יְרוּשָׁלִַ֖ם לֵ⁠אמֹֽר׃","ʼàşě֨r di̇bė֜r yirĕmĕyá֤hẇ ha⁠ná̇biyʼ֙ ʻal-ká̇l-ʻa֣m yĕhẇdá֔h wĕ⁠ʼe֛l ká̇l-yòşĕ̌bé֥y yĕrẇşá̌lia֖m lé⁠ʼmòֽr׃"],[25,3,"מִן־שְׁלֹ֣שׁ עֶשְׂרֵ֣ה שָׁנָ֡ה לְ⁠יֹאשִׁיָּ֣הוּ בֶן־אָמוֹן֩ מֶ֨לֶךְ יְהוּדָ֜ה וְ⁠עַ֣ד ׀ הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה זֶ֚ה שָׁלֹ֤שׁ וְ⁠עֶשְׂרִים֙ שָׁנָ֔ה הָיָ֥ה דְבַר־יְהוָ֖ה אֵלָ֑⁠י וָ⁠אֲדַבֵּ֧ר אֲלֵי⁠כֶ֛ם אַשְׁכֵּ֥ים וְ⁠דַבֵּ֖ר וְ⁠לֹ֥א שְׁמַעְתֶּֽם׃","min-şĕ̌lò֣ş̌ ʻeşĕ̂ré֣h şá̌ná֡h lĕ⁠yòʼşǐyá֣̇hẇ ben-ʼámwòn֩ me֨lekĕ yĕhẇdá֜h wĕ⁠ʻa֣d ׀ ha⁠ẏ֣wòm ha⁠zė֗h ze֚h şá̌lò֤ş̌ wĕ⁠ʻeşĕ̂riym֙ şá̌ná֔h háyá֥h dĕbar-yĕhwá֖h ʼélá֑⁠y wá⁠ʼàdabé֧̇r ʼàléy⁠ke֛m ʼaşĕ̌ké֥̇ym wĕ⁠dabé֖̇r wĕ⁠lò֥ʼ şĕ̌maʻĕţėֽm׃"],[25,4,"וְ⁠שָׁלַח֩ יְהוָ֨ה אֲלֵי⁠כֶ֜ם אֶֽת־כָּל־עֲבָדָ֧י⁠ו הַ⁠נְּבִאִ֛ים הַשְׁכֵּ֥ם וְ⁠שָׁלֹ֖חַ וְ⁠לֹ֣א שְׁמַעְתֶּ֑ם וְ⁠לֹֽא־הִטִּיתֶ֥ם אֶֽת־אָזְנְ⁠כֶ֖ם לִ⁠שְׁמֹֽעַ׃","wĕ⁠şá̌laẖ֩ yĕhwá֨h ʼàléy⁠ke֜m ʼeֽţ-ká̇l-ʻàbádá֧y⁠w ha⁠nĕ̇biʼi֛ym haşĕ̌ké֥̇m wĕ⁠şá̌lò֖ẖa wĕ⁠lò֣ʼ şĕ̌maʻĕţė֑m wĕ⁠lòֽʼ-hiti̇yţe֥m ʼeֽţ-ʼázĕnĕ⁠ke֖m li⁠şĕ̌mòֽʻa׃"],[25,5,"לֵ⁠אמֹ֗ר שֽׁוּבוּ־נָ֞א אִ֣ישׁ מִ⁠דַּרְכּ֤⁠וֹ הָֽ⁠רָעָה֙ וּ⁠מֵ⁠רֹ֣עַ מַעַלְלֵי⁠כֶ֔ם וּ⁠שְׁבוּ֙ עַל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֨ר נָתַ֧ן יְהוָ֛ה לָ⁠כֶ֖ם וְ⁠לַ⁠אֲבֽוֹתֵי⁠כֶ֑ם לְ⁠מִן־עוֹלָ֖ם וְ⁠עַד־עוֹלָֽם׃","lé⁠ʼmò֗r şֽ̌ẇbẇ-ná֞ʼ ʼi֣yş̌ mi⁠dȧrĕk֤̇⁠wò háֽ⁠ráʻáh֙ ẇ⁠mé⁠rò֣ʻa maʻalĕléy⁠ke֔m ẇ⁠şĕ̌bẇ֙ ʻal-há֣⁠ʼàdámá֔h ʼàşě֨r náţa֧n yĕhwá֛h lá⁠ke֖m wĕ⁠la⁠ʼàbֽwòţéy⁠ke֑m lĕ⁠min-ʻwòlá֖m wĕ⁠ʻad-ʻwòláֽm׃"],[25,6,"וְ⁠אַל־תֵּלְכ֗וּ אַֽחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים לְ⁠עָבְדָ֖⁠ם וּ⁠לְ⁠הִשְׁתַּחֲוֺ֣ת לָ⁠הֶ֑ם וְ⁠לֹֽא־תַכְעִ֤יסוּ אוֹתִ⁠י֙ בְּ⁠מַעֲשֵׂ֣ה יְדֵי⁠כֶ֔ם וְ⁠לֹ֥א אָרַ֖ע לָ⁠כֶֽם׃","wĕ⁠ʼal-ţé̇lĕk֗ẇ ʼaֽẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym lĕ⁠ʻábĕdá֖⁠m ẇ⁠lĕ⁠hişĕ̌ţȧẖàwֺ֣ţ lá⁠he֑m wĕ⁠lòֽʼ-ţakĕʻi֤ysẇ ʼwòţi⁠y֙ bĕ̇⁠maʻàşé֣̂h yĕdéy⁠ke֔m wĕ⁠lò֥ʼ ʼára֖ʻ lá⁠keֽm׃"],[25,7,"וְ⁠לֹֽא־שְׁמַעְתֶּ֥ם אֵלַ֖⁠י נְאֻם־יְהוָ֑ה לְמַ֧עַן הכעסו⁠ני בְּ⁠מַעֲשֵׂ֥ה יְדֵי⁠כֶ֖ם לְ⁠רַ֥ע לָ⁠כֶֽם׃ס","wĕ⁠lòֽʼ-şĕ̌maʻĕţė֥m ʼéla֖⁠y nĕʼum-yĕhwá֑h lĕma֧ʻan hkʻsw⁠ny bĕ̇⁠maʻàşé֥̂h yĕdéy⁠ke֖m lĕ⁠ra֥ʻ lá⁠keֽm׃s"],[25,8,"לָ⁠כֵ֕ן כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת יַ֕עַן אֲשֶׁ֥ר לֹֽא־שְׁמַעְתֶּ֖ם אֶת־דְּבָרָֽ⁠י׃","lá⁠ké֕n kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ ya֕ʻan ʼàşě֥r lòֽʼ-şĕ̌maʻĕţė֖m ʼeţ-dĕ̇báráֽ⁠y׃"],[25,9,"הִנְ⁠נִ֣י שֹׁלֵ֡חַ וְ⁠לָקַחְתִּי֩ אֶת־כָּל־מִשְׁפְּח֨וֹת צָפ֜וֹן נְאֻם־יְהוָ֗ה וְ⁠אֶל־נְבֽוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶל֮ עַבְדִּ⁠י֒ וַ⁠הֲבִ֨אֹתִ֜י⁠ם עַל־הָ⁠אָ֤רֶץ הַ⁠זֹּאת֙ וְ⁠עַל־יֹ֣שְׁבֶ֔י⁠הָ וְ⁠עַ֛ל כָּל־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֖לֶּה סָבִ֑יב וְ⁠הַ֣חֲרַמְתִּ֔י⁠ם וְ⁠שַׂמְתִּי⁠ם֙ לְ⁠שַׁמָּ֣ה וְ⁠לִ⁠שְׁרֵקָ֔ה וּ⁠לְ⁠חָרְב֖וֹת עוֹלָֽם׃","hinĕ⁠ni֣y şò̌lé֡ẖa wĕ⁠láqaẖĕţi̇y֩ ʼeţ-ká̇l-mişĕ̌pĕ̇ẖ֨wòţ ẕáp֜wòn nĕʼum-yĕhwá֗h wĕ⁠ʼel-nĕbֽẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇bel֮ ʻabĕdi̇⁠y֒ wa⁠hàbi֨ʼòţi֜y⁠m ʻal-há⁠ʼá֤reẕ ha⁠zò̇ʼţ֙ wĕ⁠ʻal-yò֣şĕ̌be֔y⁠há wĕ⁠ʻa֛l ká̇l-ha⁠ġwòyi֥m há⁠ʼé֖lėh sábi֑yb wĕ⁠ha֣ẖàramĕţi̇֔y⁠m wĕ⁠şâmĕţi̇y⁠m֙ lĕ⁠şǎmá֣̇h wĕ⁠li⁠şĕ̌réqá֔h ẇ⁠lĕ⁠ẖárĕb֖wòţ ʻwòláֽm׃"],[25,10,"וְ⁠הַאֲבַדְתִּ֣י מֵ⁠הֶ֗ם ק֤וֹל שָׂשׂוֹן֙ וְ⁠ק֣וֹל שִׂמְחָ֔ה ק֥וֹל חָתָ֖ן וְ⁠ק֣וֹל כַּלָּ֑ה ק֥וֹל רֵחַ֖יִם וְ⁠א֥וֹר נֵֽר׃","wĕ⁠haʼàbadĕţi֣̇y mé⁠he֗m q֤wòl şá̂ş̂wòn֙ wĕ⁠q֣wòl şîmĕẖá֔h q֥wòl ẖáţá֖n wĕ⁠q֣wòl kȧlá֑̇h q֥wòl réẖa֖yim wĕ⁠ʼ֥wòr néֽr׃"],[25,11,"וְ⁠הָֽיְתָה֙ כָּל־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את לְ⁠חָרְבָּ֖ה לְ⁠שַׁמָּ֑ה וְ⁠עָ֨בְד֜וּ הַ⁠גּוֹיִ֥ם הָ⁠אֵ֛לֶּה אֶת־מֶ֥לֶךְ בָּבֶ֖ל שִׁבְעִ֥ים שָׁנָֽה׃","wĕ⁠háֽyĕţáh֙ ká̇l-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ lĕ⁠ẖárĕbá֖̇h lĕ⁠şǎmá֑̇h wĕ⁠ʻá֨bĕd֜ẇ ha⁠ġwòyi֥m há⁠ʼé֛lėh ʼeţ-me֥lekĕ bá̇be֖l şǐbĕʻi֥ym şá̌náֽh׃"],[25,12,"וְ⁠הָיָ֣ה כִ⁠מְלֹ֣אות שִׁבְעִ֣ים שָׁנָ֡ה אֶפְקֹ֣ד עַל־מֶֽלֶךְ־בָּבֶל֩ וְ⁠עַל־הַ⁠גּ֨וֹי הַ⁠ה֧וּא נְאֻם־יְהוָ֛ה אֶת־עֲוֺנָ֖⁠ם וְ⁠עַל־אֶ֣רֶץ כַּשְׂדִּ֑ים וְ⁠שַׂמְתִּ֥י אֹת֖⁠וֹ לְ⁠שִֽׁמְמ֥וֹת עוֹלָֽם׃","wĕ⁠háyá֣h ki⁠mĕlò֣ʼwţ şǐbĕʻi֣ym şá̌ná֡h ʼepĕqò֣d ʻal-meֽlekĕ-bá̇bel֩ wĕ⁠ʻal-ha⁠ġ֨wòy ha⁠h֧ẇʼ nĕʼum-yĕhwá֛h ʼeţ-ʻàwֺná֖⁠m wĕ⁠ʻal-ʼe֣reẕ kȧşĕ̂di֑̇ym wĕ⁠şâmĕţi֥̇y ʼòţ֖⁠wò lĕ⁠şǐֽmĕm֥wòţ ʻwòláֽm׃"],[25,13,"ו⁠הבאיתי עַל־הָ⁠אָ֣רֶץ הַ⁠הִ֔יא אֶת־כָּל־דְּבָרַ֖⁠י אֲשֶׁר־דִּבַּ֣רְתִּי עָלֶ֑י⁠הָ אֵ֤ת כָּל־הַ⁠כָּתוּב֙ בַּ⁠סֵּ֣פֶר הַ⁠זֶּ֔ה אֲשֶׁר־נִבָּ֥א יִרְמְיָ֖הוּ עַל־כָּל־הַ⁠גּוֹיִֽם׃","w⁠hbʼyţy ʻal-há⁠ʼá֣reẕ ha⁠hi֔yʼ ʼeţ-ká̇l-dĕ̇bára֖⁠y ʼàşěr-di̇bȧ֣rĕţi̇y ʻále֑y⁠há ʼé֤ţ ká̇l-ha⁠ká̇ţẇb֙ bȧ⁠sé֣̇per ha⁠zė֔h ʼàşěr-nibá֥̇ʼ yirĕmĕyá֖hẇ ʻal-ká̇l-ha⁠ġwòyiֽm׃"],[25,14,"כִּ֣י עָֽבְדוּ־בָ֤⁠ם גַּם־הֵ֨מָּה֙ גּוֹיִ֣ם רַבִּ֔ים וּ⁠מְלָכִ֖ים גְּדוֹלִ֑ים וְ⁠שִׁלַּמְתִּ֥י לָ⁠הֶ֛ם כְּ⁠פָעֳלָ֖⁠ם וּ⁠כְ⁠מַעֲשֵׂ֥ה יְדֵי⁠הֶֽם׃ס","ki֣̇y ʻáֽbĕdẇ-bá֤⁠m gȧm-hé֨má̇h֙ ġwòyi֣m rabi̇֔ym ẇ⁠mĕláki֖ym gĕ̇dwòli֑ym wĕ⁠şǐlȧmĕţi֥̇y lá⁠he֛m kĕ̇⁠páʻolá֖⁠m ẇ⁠kĕ⁠maʻàşé֥̂h yĕdéy⁠heֽm׃s"],[25,15,"כִּ֣י כֹה֩ אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ אֵלַ֔⁠י קַ֠ח אֶת־כּ֨וֹס הַ⁠יַּ֧יִן הַ⁠חֵמָ֛ה הַ⁠זֹּ֖את מִ⁠יָּדִ֑⁠י וְ⁠הִשְׁקִיתָ֤ה אֹת⁠וֹ֙ אֶת־כָּל־הַ⁠גּוֹיִ֔ם אֲשֶׁ֧ר אָנֹכִ֛י שֹׁלֵ֥חַ אוֹתְ⁠ךָ֖ אֲלֵי⁠הֶֽם׃","ki֣̇y kòh֩ ʼáma֨r yĕhwá֜h ʼèlòhé֤y yişĕ̂ráʼél֙ ʼéla֔⁠y qa֠ẖ ʼeţ-k̇֨wòs ha⁠yȧ֧yin ha⁠ẖémá֛h ha⁠zò֖̇ʼţ mi⁠yá̇di֑⁠y wĕ⁠hişĕ̌qiyţá֤h ʼòţ⁠wò֙ ʼeţ-ká̇l-ha⁠ġwòyi֔m ʼàşě֧r ʼánòki֛y şò̌lé֥ẖa ʼwòţĕ⁠ká֖ ʼàléy⁠heֽm׃"],[25,16,"וְ⁠שָׁת֕וּ וְ⁠הִֽתְגֹּֽעֲשׁ֖וּ וְ⁠הִתְהֹלָ֑לוּ מִ⁠פְּנֵ֣י הַ⁠חֶ֔רֶב אֲשֶׁ֛ר אָנֹכִ֥י שֹׁלֵ֖חַ בֵּינֹתָֽ⁠ם׃","wĕ⁠şá̌ţ֕ẇ wĕ⁠hiֽţĕgòֽ̇ʻàş֖̌ẇ wĕ⁠hiţĕhòlá֑lẇ mi⁠pĕ̇né֣y ha⁠ẖe֔reb ʼàşě֛r ʼánòki֥y şò̌lé֖ẖa bé̇ynòţáֽ⁠m׃"],[25,17,"וָ⁠אֶקַּ֥ח אֶת־הַ⁠כּ֖וֹס מִ⁠יַּ֣ד יְהוָ֑ה וָֽ⁠אַשְׁקֶה֙ אֶת־כָּל־הַ⁠גּוֹיִ֔ם אֲשֶׁר־שְׁלָחַ֥⁠נִי יְהוָ֖ה אֲלֵי⁠הֶֽם׃","wá⁠ʼeqȧ֥ẖ ʼeţ-ha⁠k֖̇wòs mi⁠yȧ֣d yĕhwá֑h wáֽ⁠ʼaşĕ̌qeh֙ ʼeţ-ká̇l-ha⁠ġwòyi֔m ʼàşěr-şĕ̌láẖa֥⁠niy yĕhwá֖h ʼàléy⁠heֽm׃"],[25,18,"אֶת־יְרוּשָׁלִַ֨ם֙ וְ⁠אֶת־עָרֵ֣י יְהוּדָ֔ה וְ⁠אֶת־מְלָכֶ֖י⁠הָ אֶת־שָׂרֶ֑י⁠הָ לָ⁠תֵ֨ת אֹתָ֜⁠ם לְ⁠חָרְבָּ֧ה לְ⁠שַׁמָּ֛ה לִ⁠שְׁרֵקָ֥ה וְ⁠לִ⁠קְלָלָ֖ה כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ʼeţ-yĕrẇşá̌lia֨m֙ wĕ⁠ʼeţ-ʻáré֣y yĕhẇdá֔h wĕ⁠ʼeţ-mĕláke֖y⁠há ʼeţ-şá̂re֑y⁠há lá⁠ţé֨ţ ʼòţá֜⁠m lĕ⁠ẖárĕbá֧̇h lĕ⁠şǎmá֛̇h li⁠şĕ̌réqá֥h wĕ⁠li⁠qĕlálá֖h kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[25,19,"אֶת־פַּרְעֹ֧ה מֶֽלֶךְ־מִצְרַ֛יִם וְ⁠אֶת־עֲבָדָ֥י⁠ו וְ⁠אֶת־שָׂרָ֖י⁠ו וְ⁠אֶת־כָּל־עַמּֽ⁠וֹ׃","ʼeţ-pȧrĕʻò֧h meֽlekĕ-miẕĕra֛yim wĕ⁠ʼeţ-ʻàbádá֥y⁠w wĕ⁠ʼeţ-şá̂rá֖y⁠w wĕ⁠ʼeţ-ká̇l-ʻaṁֽ⁠wò׃"],[25,20,"וְ⁠אֵת֙ כָּל־הָ⁠עֶ֔רֶב וְ⁠אֵ֕ת כָּל־מַלְכֵ֖י אֶ֣רֶץ הָ⁠ע֑וּץ וְ⁠אֵ֗ת כָּל־מַלְכֵי֙ אֶ֣רֶץ פְּלִשְׁתִּ֔ים וְ⁠אֶת־אַשְׁקְל֤וֹן וְ⁠אֶת־עַזָּה֙ וְ⁠אֶת־עֶקְר֔וֹן וְ⁠אֵ֖ת שְׁאֵרִ֥ית אַשְׁדּֽוֹד׃","wĕ⁠ʼéţ֙ ká̇l-há⁠ʻe֔reb wĕ⁠ʼé֕ţ ká̇l-malĕké֖y ʼe֣reẕ há⁠ʻ֑ẇẕ wĕ⁠ʼé֗ţ ká̇l-malĕkéy֙ ʼe֣reẕ pĕ̇lişĕ̌ţi̇֔ym wĕ⁠ʼeţ-ʼaşĕ̌qĕl֤wòn wĕ⁠ʼeţ-ʻazá̇h֙ wĕ⁠ʼeţ-ʻeqĕr֔wòn wĕ⁠ʼé֖ţ şĕ̌ʼéri֥yţ ʼaşĕ̌ḋֽwòd׃"],[25,21,"אֶת־אֱד֥וֹם וְ⁠אֶת־מוֹאָ֖ב וְ⁠אֶת־בְּנֵ֥י עַמּֽוֹן׃","ʼeţ-ʼèd֥wòm wĕ⁠ʼeţ-mwòʼá֖b wĕ⁠ʼeţ-bĕ̇né֥y ʻaṁֽwòn׃"],[25,22,"וְ⁠אֵת֙ כָּל־מַלְכֵי־צֹ֔ר וְ⁠אֵ֖ת כָּל־מַלְכֵ֣י צִיד֑וֹן וְ⁠אֵת֙ מַלְכֵ֣י הָ⁠אִ֔י אֲשֶׁ֖ר בְּ⁠עֵ֥בֶר הַ⁠יָּֽם׃","wĕ⁠ʼéţ֙ ká̇l-malĕkéy-ẕò֔r wĕ⁠ʼé֖ţ ká̇l-malĕké֣y ẕiyd֑wòn wĕ⁠ʼéţ֙ malĕké֣y há⁠ʼi֔y ʼàşě֖r bĕ̇⁠ʻé֥ber ha⁠yáֽ̇m׃"],[25,23,"וְ⁠אֶת־דְּדָ֤ן וְ⁠אֶת־תֵּימָא֙ וְ⁠אֶת־בּ֔וּז וְ⁠אֵ֖ת כָּל־קְצוּצֵ֥י פֵאָֽה׃","wĕ⁠ʼeţ-dĕ̇dá֤n wĕ⁠ʼeţ-ţé̇ymáʼ֙ wĕ⁠ʼeţ-ḃ֔ẇz wĕ⁠ʼé֖ţ ká̇l-qĕẕẇẕé֥y péʼáֽh׃"],[25,24,"וְ⁠אֵ֖ת כָּל־מַלְכֵ֣י עֲרָ֑ב וְ⁠אֵת֙ כָּל־מַלְכֵ֣י הָ⁠עֶ֔רֶב הַ⁠שֹּׁכְנִ֖ים בַּ⁠מִּדְבָּֽר׃","wĕ⁠ʼé֖ţ ká̇l-malĕké֣y ʻàrá֑b wĕ⁠ʼéţ֙ ká̇l-malĕké֣y há⁠ʻe֔reb ha⁠şò̇̌kĕni֖ym bȧ⁠mi̇dĕbáֽ̇r׃"],[25,25,"וְ⁠אֵ֣ת ׀ כָּל־מַלְכֵ֣י זִמְרִ֗י וְ⁠אֵת֙ כָּל־מַלְכֵ֣י עֵילָ֔ם וְ⁠אֵ֖ת כָּל־מַלְכֵ֥י מָדָֽי׃","wĕ⁠ʼé֣ţ ׀ ká̇l-malĕké֣y zimĕri֗y wĕ⁠ʼéţ֙ ká̇l-malĕké֣y ʻéylá֔m wĕ⁠ʼé֖ţ ká̇l-malĕké֥y mádáֽy׃"],[25,26,"וְ⁠אֵ֣ת ׀ כָּל־מַלְכֵ֣י הַ⁠צָּפ֗וֹן הַ⁠קְּרֹבִ֤ים וְ⁠הָֽ⁠רְחֹקִים֙ אִ֣ישׁ אֶל־אָחִ֔י⁠ו וְ⁠אֵת֙ כָּל־הַ⁠מַּמְלְכ֣וֹת הָ⁠אָ֔רֶץ אֲשֶׁ֖ר עַל־פְּנֵ֣י הָ⁠אֲדָמָ֑ה וּ⁠מֶ֥לֶךְ שֵׁשַׁ֖ךְ יִשְׁתֶּ֥ה אַחֲרֵי⁠הֶֽם׃","wĕ⁠ʼé֣ţ ׀ ká̇l-malĕké֣y ha⁠ẕá̇p֗wòn ha⁠qĕ̇ròbi֤ym wĕ⁠háֽ⁠rĕẖòqiym֙ ʼi֣yş̌ ʼel-ʼáẖi֔y⁠w wĕ⁠ʼéţ֙ ká̇l-ha⁠mȧmĕlĕk֣wòţ há⁠ʼá֔reẕ ʼàşě֖r ʻal-pĕ̇né֣y há⁠ʼàdámá֑h ẇ⁠me֥lekĕ şé̌şǎ֖kĕ yişĕ̌ţė֥h ʼaẖàréy⁠heֽm׃"],[25,27,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֡ם ס כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל שְׁת֤וּ וְ⁠שִׁכְרוּ֙ וּ⁠קְי֔וּ וְ⁠נִפְל֖וּ וְ⁠לֹ֣א תָק֑וּמוּ מִ⁠פְּנֵ֣י הַ⁠חֶ֔רֶב אֲשֶׁ֛ר אָנֹכִ֥י שֹׁלֵ֖חַ בֵּינֵי⁠כֶֽם׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֡m s kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l şĕ̌ţ֤ẇ wĕ⁠şǐkĕrẇ֙ ẇ⁠qĕy֔ẇ wĕ⁠nipĕl֖ẇ wĕ⁠lò֣ʼ ţáq֑ẇmẇ mi⁠pĕ̇né֣y ha⁠ẖe֔reb ʼàşě֛r ʼánòki֥y şò̌lé֖ẖa bé̇ynéy⁠keֽm׃"],[25,28,"וְ⁠הָיָ֗ה כִּ֧י יְמָאֲנ֛וּ לָ⁠קַֽחַת־הַ⁠כּ֥וֹס מִ⁠יָּדְ⁠ךָ֖ לִ⁠שְׁתּ֑וֹת וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת שָׁת֥וֹ תִשְׁתּֽוּ׃","wĕ⁠háyá֗h ki֧̇y yĕmáʼàn֛ẇ lá⁠qaֽẖaţ-ha⁠k֥̇wòs mi⁠yá̇dĕ⁠ká֖ li⁠şĕ̌ţ֑̇wòţ wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ şá̌ţ֥wò ţişĕ̌ţֽ̇ẇ׃"],[25,29,"כִּי֩ הִנֵּ֨ה בָ⁠עִ֜יר אֲשֶׁ֧ר נִֽקְרָא־שְׁמִ֣⁠י עָלֶ֗י⁠הָ אָֽנֹכִי֙ מֵחֵ֣ל לְ⁠הָרַ֔ע וְ⁠אַתֶּ֖ם הִנָּקֵ֣ה תִנָּק֑וּ לֹ֣א תִנָּק֔וּ כִּ֣י חֶ֗רֶב אֲנִ֤י קֹרֵא֙ עַל־כָּל־יֹשְׁבֵ֣י הָ⁠אָ֔רֶץ נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","ki̇y֩ hiné̇֨h bá⁠ʻi֜yr ʼàşě֧r niֽqĕráʼ-şĕ̌mi֣⁠y ʻále֗y⁠há ʼáֽnòkiy֙ méẖé֣l lĕ⁠hára֔ʻ wĕ⁠ʼaţė֖m hiná̇qé֣h ţiná̇q֑ẇ lò֣ʼ ţiná̇q֔ẇ ki֣̇y ẖe֗reb ʼàni֤y qòréʼ֙ ʻal-ká̇l-yòşĕ̌bé֣y há⁠ʼá֔reẕ nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[25,30,"וְ⁠אַתָּה֙ תִּנָּבֵ֣א אֲלֵי⁠הֶ֔ם אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם יְהוָ֞ה מִ⁠מָּר֤וֹם יִשְׁאָג֙ וּ⁠מִ⁠מְּע֤וֹן קָדְשׁ⁠וֹ֙ יִתֵּ֣ן קוֹל֔⁠וֹ שָׁאֹ֤ג יִשְׁאַג֙ עַל־נָוֵ֔⁠הוּ הֵידָד֙ כְּ⁠דֹרְכִ֣ים יַֽעֲנֶ֔ה אֶ֥ל כָּל־יֹשְׁבֵ֖י הָ⁠אָֽרֶץ׃","wĕ⁠ʼaţá̇h֙ ţi̇ná̇bé֣ʼ ʼàléy⁠he֔m ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m yĕhwá֞h mi⁠má̇r֤wòm yişĕ̌ʼág֙ ẇ⁠mi⁠mĕ̇ʻ֤wòn qádĕş̌⁠wò֙ yiţé֣̇n qwòl֔⁠wò şá̌ʼò֤g yişĕ̌ʼag֙ ʻal-náwé֔⁠hẇ héydád֙ kĕ̇⁠dòrĕki֣ym yaֽʻàne֔h ʼe֥l ká̇l-yòşĕ̌bé֖y há⁠ʼáֽreẕ׃"],[25,31,"בָּ֤א שָׁאוֹן֙ עַד־קְצֵ֣ה הָ⁠אָ֔רֶץ כִּ֣י רִ֤יב לַֽ⁠יהוָה֙ בַּ⁠גּוֹיִ֔ם נִשְׁפָּ֥ט ה֖וּא לְ⁠כָל־בָּשָׂ֑ר הָ⁠רְשָׁעִ֛ים נְתָנָ֥⁠ם לַ⁠חֶ֖רֶב נְאֻם־יְהוָֽה׃ס","bá֤̇ʼ şá̌ʼwòn֙ ʻad-qĕẕé֣h há⁠ʼá֔reẕ ki֣̇y ri֤yb laֽ⁠yhwáh֙ bȧ⁠ġwòyi֔m nişĕ̌pá֥̇t h֖ẇʼ lĕ⁠kál-bá̇şá֑̂r há⁠rĕşá̌ʻi֛ym nĕţáná֥⁠m la⁠ẖe֖reb nĕʼum-yĕhwáֽh׃s"],[25,32,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנֵּ֥ה רָעָ֛ה יֹצֵ֖את מִ⁠גּ֣וֹי אֶל־גּ֑וֹי וְ⁠סַ֣עַר גָּד֔וֹל יֵע֖וֹר מִ⁠יַּרְכְּתֵי־אָֽרֶץ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hiné֥̇h ráʻá֛h yòẕé֖ʼţ mi⁠ġ֣wòy ʼel-ġ֑wòy wĕ⁠sa֣ʻar gá̇d֔wòl yéʻ֖wòr mi⁠yȧrĕkĕ̇ţéy-ʼáֽreẕ׃"],[25,33,"וְ⁠הָי֞וּ חַֽלְלֵ֤י יְהוָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא מִ⁠קְצֵ֥ה הָ⁠אָ֖רֶץ וְ⁠עַד־קְצֵ֣ה הָ⁠אָ֑רֶץ לֹ֣א יִסָּפְד֗וּ וְ⁠לֹ֤א יֵאָֽסְפוּ֙ וְ⁠לֹ֣א יִקָּבֵ֔רוּ לְ⁠דֹ֛מֶן עַל־פְּנֵ֥י הָ⁠אֲדָמָ֖ה יִֽהְיֽוּ׃","wĕ⁠háy֞ẇ ẖaֽlĕlé֤y yĕhwáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ mi⁠qĕẕé֥h há⁠ʼá֖reẕ wĕ⁠ʻad-qĕẕé֣h há⁠ʼá֑reẕ lò֣ʼ yisá̇pĕd֗ẇ wĕ⁠lò֤ʼ yéʼáֽsĕpẇ֙ wĕ⁠lò֣ʼ yiqá̇bé֔rẇ lĕ⁠dò֛men ʻal-pĕ̇né֥y há⁠ʼàdámá֖h yiֽhĕyֽẇ׃"],[25,34,"הֵילִ֨ילוּ הָ⁠רֹעִ֜ים וְ⁠זַעֲק֗וּ וְ⁠הִֽתְפַּלְּשׁוּ֙ אַדִּירֵ֣י הַ⁠צֹּ֔אן כִּֽי־מָלְא֥וּ יְמֵי⁠כֶ֖ם לִ⁠טְב֑וֹחַ וּ⁠תְפוֹצ֣וֹתִי⁠כֶ֔ם וּ⁠נְפַלְתֶּ֖ם כִּ⁠כְלִ֥י חֶמְדָּֽה׃","héyli֨ylẇ há⁠ròʻi֜ym wĕ⁠zaʻàq֗ẇ wĕ⁠hiֽţĕpȧlĕ̇ş̌ẇ֙ ʼadi̇yré֣y ha⁠ẕò̇֔ʼn kiֽ̇y-málĕʼ֥ẇ yĕméy⁠ke֖m li⁠tĕb֑wòẖa ẇ⁠ţĕpwòẕ֣wòţiy⁠ke֔m ẇ⁠nĕpalĕţė֖m ki̇⁠kĕli֥y ẖemĕdáֽ̇h׃"],[25,35,"וְ⁠אָבַ֥ד מָנ֖וֹס מִן־הָֽ⁠רֹעִ֑ים וּ⁠פְלֵיטָ֖ה מֵ⁠אַדִּירֵ֥י הַ⁠צֹּֽאן׃","wĕ⁠ʼába֥d mán֖wòs min-hֽá⁠ròʻi֑ym ẇ⁠pĕléytá֖h mé⁠ʼadi̇yré֥y ha⁠ẕòֽ̇ʼn׃"],[25,36,"ק֚וֹל צַעֲקַ֣ת הָֽ⁠רֹעִ֔ים וִֽ⁠ילְלַ֖ת אַדִּירֵ֣י הַ⁠צֹּ֑אן כִּֽי־שֹׁדֵ֥ד יְהוָ֖ה אֶת־מַרְעִיתָֽ⁠ם׃","q֚wòl ẕaʻàqa֣ţ háֽ⁠ròʻi֔ym wiֽ⁠ylĕla֖ţ ʼadi̇yré֣y ha⁠ẕò֑̇ʼn kiֽ̇y-şò̌dé֥d yĕhwá֖h ʼeţ-marĕʻiyţáֽ⁠m׃"],[25,37,"וְ⁠נָדַ֖מּוּ נְא֣וֹת הַ⁠שָּׁל֑וֹם מִ⁠פְּנֵ֖י חֲר֥וֹן אַף־יְהוָֽה׃","wĕ⁠náda֖ṁẇ nĕʼ֣wòţ ha⁠şá̇̌l֑wòm mi⁠pĕ̇né֖y ẖàr֥wòn ʼap-yĕhwáֽh׃"],[25,38,"עָזַ֥ב כַּ⁠כְּפִ֖יר סֻכּ֑⁠וֹ כִּֽי־הָיְתָ֤ה אַרְצָ⁠ם֙ לְ⁠שַׁמָּ֔ה מִ⁠פְּנֵי֙ חֲר֣וֹן הַ⁠יּוֹנָ֔ה וּ⁠מִ⁠פְּנֵ֖י חֲר֥וֹן אַפּֽ⁠וֹ׃פ","ʻáza֥b kȧ⁠kĕ̇pi֖yr suk֑̇⁠wò kiֽ̇y-háyĕţá֤h ʼarĕẕá⁠m֙ lĕ⁠şǎmá̇֔h mi⁠pĕ̇néy֙ ẖàr֣wòn ha⁠ẏwòná֔h ẇ⁠mi⁠pĕ̇né֖y ẖàr֥wòn ʼaṗֽ⁠wò׃p"],[26,1,"בְּ⁠רֵאשִׁ֗ית מַמְלְכ֛וּת יְהוֹיָקִ֥ים בֶּן־יֹאשִׁיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה הָיָה֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","bĕ̇⁠réʼşǐ֗yţ mamĕlĕk֛ẇţ yĕhwòyáqi֥ym bėn-yòʼşǐyá֖̇hẇ me֣lekĕ yĕhẇdá֑h háyáh֙ ha⁠dá̇bá֣r ha⁠zė֔h mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[26,2,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה עֲמֹד֮ בַּ⁠חֲצַ֣ר בֵּית־יְהוָה֒ וְ⁠דִבַּרְתָּ֞ עַל־כָּל־עָרֵ֣י יְהוּדָ֗ה הַ⁠בָּאִים֙ לְ⁠הִשְׁתַּחֲוֺ֣ת בֵּית־יְהוָ֔ה אֵ֚ת כָּל־הַ⁠דְּבָרִ֔ים אֲשֶׁ֥ר צִוִּיתִ֖י⁠ךָ לְ⁠דַבֵּ֣ר אֲלֵי⁠הֶ֑ם אַל־תִּגְרַ֖ע דָּבָֽר׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʻàmòd֮ bȧ⁠ẖàẕa֣r bé̇yţ-yĕhwáh֒ wĕ⁠dibȧrĕţá̇֞ ʻal-ká̇l-ʻáré֣y yĕhẇdá֗h ha⁠bá̇ʼiym֙ lĕ⁠hişĕ̌ţȧẖàwֺ֣ţ bé̇yţ-yĕhwá֔h ʼé֚ţ ká̇l-ha⁠dĕ̇bári֔ym ʼàşě֥r ẕiwi̇yţi֖y⁠ká lĕ⁠dabé֣̇r ʼàléy⁠he֑m ʼal-ţi̇gĕra֖ʻ dá̇báֽr׃"],[26,3,"אוּלַ֣י יִשְׁמְע֔וּ וְ⁠יָשֻׁ֕בוּ אִ֖ישׁ מִ⁠דַּרְכּ֣⁠וֹ הָ⁠רָעָ֑ה וְ⁠נִחַמְתִּ֣י אֶל־הָ⁠רָעָ֗ה אֲשֶׁ֨ר אָנֹכִ֤י חֹשֵׁב֙ לַ⁠עֲשׂ֣וֹת לָ⁠הֶ֔ם מִ⁠פְּנֵ֖י רֹ֥עַ מַעַלְלֵי⁠הֶֽם׃","ʼẇla֣y yişĕ̌mĕʻ֔ẇ wĕ⁠yáşǔ֕bẇ ʼi֖yş̌ mi⁠dȧrĕk֣̇⁠wò há⁠ráʻá֑h wĕ⁠niẖamĕţi֣̇y ʼel-há⁠ráʻá֗h ʼàşě֨r ʼánòki֤y ẖòşé̌b֙ la⁠ʻàş֣̂wòţ lá⁠he֔m mi⁠pĕ̇né֖y rò֥ʻa maʻalĕléy⁠heֽm׃"],[26,4,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֖ה אָמַ֣ר יְהוָ֑ה אִם־לֹ֤א תִשְׁמְעוּ֙ אֵלַ֔⁠י לָ⁠לֶ֨כֶת֙ בְּ⁠ת֣וֹרָתִ֔⁠י אֲשֶׁ֥ר נָתַ֖תִּי לִ⁠פְנֵי⁠כֶֽם׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֖̇h ʼáma֣r yĕhwá֑h ʼim-lò֤ʼ ţişĕ̌mĕʻẇ֙ ʼéla֔⁠y lá⁠le֨keţ֙ bĕ̇⁠ţ֣wòráţi֔⁠y ʼàşě֥r náţa֖ţi̇y li⁠pĕnéy⁠keֽm׃"],[26,5,"לִ⁠שְׁמֹ֗עַ עַל־דִּבְרֵ֨י עֲבָדַ֣⁠י הַ⁠נְּבִאִ֔ים אֲשֶׁ֥ר אָנֹכִ֖י שֹׁלֵ֣חַ אֲלֵי⁠כֶ֑ם וְ⁠הַשְׁכֵּ֥ם וְ⁠שָׁלֹ֖חַ וְ⁠לֹ֥א שְׁמַעְתֶּֽם׃","li⁠şĕ̌mò֗ʻa ʻal-di̇bĕré֨y ʻàbáda֣⁠y ha⁠nĕ̇biʼi֔ym ʼàşě֥r ʼánòki֖y şò̌lé֣ẖa ʼàléy⁠ke֑m wĕ⁠haşĕ̌ké֥̇m wĕ⁠şá̌lò֖ẖa wĕ⁠lò֥ʼ şĕ̌maʻĕţėֽm׃"],[26,6,"וְ⁠נָתַתִּ֛י אֶת־הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה כְּ⁠שִׁלֹ֑ה וְ⁠אֶת־הָ⁠עִ֤יר ה⁠זאתה אֶתֵּ֣ן לִ⁠קְלָלָ֔ה לְ⁠כֹ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃ס","wĕ⁠náţaţi֛̇y ʼeţ-ha⁠bȧ֥yiţ ha⁠zė֖h kĕ̇⁠şǐlò֑h wĕ⁠ʼeţ-há⁠ʻi֤yr h⁠zʼţh ʼeţé֣̇n li⁠qĕlálá֔h lĕ⁠kò֖l ġwòyé֥y há⁠ʼáֽreẕ׃s"],[26,7,"וַֽ⁠יִּשְׁמְע֛וּ הַ⁠כֹּהֲנִ֥ים וְ⁠הַ⁠נְּבִאִ֖ים וְ⁠כָל־הָ⁠עָ֑ם אֶֽת־יִרְמְיָ֔הוּ מְדַבֵּ֛ר אֶת־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה בְּ⁠בֵ֥ית יְהוָֽה׃","waֽ⁠yi̇şĕ̌mĕʻ֛ẇ ha⁠kò̇hàni֥ym wĕ⁠ha⁠nĕ̇biʼi֖ym wĕ⁠kál-há⁠ʻá֑m ʼeֽţ-yirĕmĕyá֔hẇ mĕdabé֛̇r ʼeţ-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[26,8,"וַ⁠יְהִ֣י ׀ כְּ⁠כַלּ֣וֹת יִרְמְיָ֗הוּ לְ⁠דַבֵּר֙ אֵ֣ת כָּל־אֲשֶׁר־צִוָּ֣ה יְהוָ֔ה לְ⁠דַבֵּ֖ר אֶל־כָּל־הָ⁠עָ֑ם וַ⁠יִּתְפְּשׂ֨וּ אֹת֜⁠וֹ הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠נְּבִאִ֛ים וְ⁠כָל־הָ⁠עָ֥ם לֵ⁠אמֹ֖ר מ֥וֹת תָּמֽוּת׃","wa⁠yĕhi֣y ׀ kĕ̇⁠kal֣̇wòţ yirĕmĕyá֗hẇ lĕ⁠dabé̇r֙ ʼé֣ţ ká̇l-ʼàşěr-ẕiwá֣̇h yĕhwá֔h lĕ⁠dabé֖̇r ʼel-ká̇l-há⁠ʻá֑m wa⁠yi̇ţĕpĕ̇ş̂֨ẇ ʼòţ֜⁠wò ha⁠kò̇hàni֧ym wĕ⁠ha⁠nĕ̇biʼi֛ym wĕ⁠kál-há⁠ʻá֥m lé⁠ʼmò֖r m֥wòţ ţá̇mֽẇţ׃"],[26,9,"מַדּוּעַ֩ נִבֵּ֨יתָ בְ⁠שֵׁם־יְהוָ֜ה לֵ⁠אמֹ֗ר כְּ⁠שִׁלוֹ֙ יִֽהְיֶה֙ הַ⁠בַּ֣יִת הַ⁠זֶּ֔ה וְ⁠הָ⁠עִ֥יר הַ⁠זֹּ֛את תֶּחֱרַ֖ב מֵ⁠אֵ֣ין יוֹשֵׁ֑ב וַ⁠יִּקָּהֵ֧ל כָּל־הָ⁠עָ֛ם אֶֽל־יִרְמְיָ֖הוּ בְּ⁠בֵ֥ית יְהוָֽה׃","maḋẇʻa֩ nibé̇֨yţá bĕ⁠şé̌m-yĕhwá֜h lé⁠ʼmò֗r kĕ̇⁠şǐlwò֙ yiֽhĕyeh֙ ha⁠bȧ֣yiţ ha⁠zė֔h wĕ⁠há⁠ʻi֥yr ha⁠zò֛̇ʼţ ţėẖèra֖b mé⁠ʼé֣yn ywòşé֑̌b wa⁠yi̇qá̇hé֧l ká̇l-há⁠ʻá֛m ʼeֽl-yirĕmĕyá֖hẇ bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[26,10,"וַֽ⁠יִּשְׁמְע֣וּ ׀ שָׂרֵ֣י יְהוּדָ֗ה אֵ֚ת הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠יַּעֲל֥וּ מִ⁠בֵּית־הַ⁠מֶּ֖לֶךְ בֵּ֣ית יְהוָ֑ה וַ⁠יֵּֽשְׁב֛וּ בְּ⁠פֶ֥תַח שַֽׁעַר־יְהוָ֖ה הֶ⁠חָדָֽשׁ׃ס","waֽ⁠yi̇şĕ̌mĕʻ֣ẇ ׀ şá̂ré֣y yĕhẇdá֗h ʼé֚ţ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠yȧʻàl֥ẇ mi⁠bé̇yţ-ha⁠mė֖lekĕ bé֣̇yţ yĕhwá֑h wa⁠yéֽ̇şĕ̌b֛ẇ bĕ̇⁠pe֥ţaẖ şǎֽʻar-yĕhwá֖h he⁠ẖádáֽş̌׃s"],[26,11,"וַ⁠יֹּ֨אמְר֜וּ הַ⁠כֹּהֲנִ֤ים וְ⁠הַ⁠נְּבִאִים֙ אֶל־הַ⁠שָּׂרִ֔ים וְ⁠אֶל־כָּל־הָ⁠עָ֖ם לֵ⁠אמֹ֑ר מִשְׁפַּט־מָ֨וֶת֙ לָ⁠אִ֣ישׁ הַ⁠זֶּ֔ה כִּ֤י נִבָּא֙ אֶל־הָ⁠עִ֣יר הַ⁠זֹּ֔את כַּ⁠אֲשֶׁ֥ר שְׁמַעְתֶּ֖ם בְּ⁠אָזְנֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmĕr֜ẇ ha⁠kò̇hàni֤ym wĕ⁠ha⁠nĕ̇biʼiym֙ ʼel-ha⁠şá̇̂ri֔ym wĕ⁠ʼel-ká̇l-há⁠ʻá֖m lé⁠ʼmò֑r mişĕ̌pȧt-má֨weţ֙ lá⁠ʼi֣yş̌ ha⁠zė֔h ki֤̇y nibá̇ʼ֙ ʼel-há⁠ʻi֣yr ha⁠zò̇֔ʼţ kȧ⁠ʼàşě֥r şĕ̌maʻĕţė֖m bĕ̇⁠ʼázĕnéy⁠keֽm׃"],[26,12,"וַ⁠יֹּ֤אמֶר יִרְמְיָ֨הוּ֙ אֶל־כָּל־הַ⁠שָּׂרִ֔ים וְ⁠אֶל־כָּל־הָ⁠עָ֖ם לֵ⁠אמֹ֑ר יְהוָ֣ה שְׁלָחַ֗⁠נִי לְ⁠הִנָּבֵ֞א אֶל־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ וְ⁠אֶל־הָ⁠עִ֣יר הַ⁠זֹּ֔את אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים אֲשֶׁ֥ר שְׁמַעְתֶּֽם׃","wa⁠yò֤̇ʼmer yirĕmĕyá֨hẇ֙ ʼel-ká̇l-ha⁠şá̇̂ri֔ym wĕ⁠ʼel-ká̇l-há⁠ʻá֖m lé⁠ʼmò֑r yĕhwá֣h şĕ̌láẖa֗⁠niy lĕ⁠hiná̇bé֞ʼ ʼel-ha⁠bȧ֤yiţ ha⁠zėh֙ wĕ⁠ʼel-há⁠ʻi֣yr ha⁠zò̇֔ʼţ ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym ʼàşě֥r şĕ̌maʻĕţėֽm׃"],[26,13,"וְ⁠עַתָּ֗ה הֵיטִ֤יבוּ דַרְכֵי⁠כֶם֙ וּ⁠מַ֣עַלְלֵי⁠כֶ֔ם וְ⁠שִׁמְע֕וּ בְּ⁠ק֖וֹל יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם וְ⁠יִנָּחֵ֣ם יְהוָ֔ה אֶל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר דִּבֶּ֖ר עֲלֵי⁠כֶֽם׃","wĕ⁠ʻaţá̇֗h héyti֤ybẇ darĕkéy⁠kem֙ ẇ⁠ma֣ʻalĕléy⁠ke֔m wĕ⁠şǐmĕʻ֕ẇ bĕ̇⁠q֖wòl yĕhwá֣h ʼèlòhéy⁠ke֑m wĕ⁠yiná̇ẖé֣m yĕhwá֔h ʼel-há֣⁠ráʻá֔h ʼàşě֥r di̇bė֖r ʻàléy⁠keֽm׃"],[26,14,"וַ⁠אֲנִ֖י הִנְ⁠נִ֣י בְ⁠יֶדְ⁠כֶ֑ם עֲשׂוּ־לִ֛⁠י כַּ⁠טּ֥וֹב וְ⁠כַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵי⁠כֶֽם׃","wa⁠ʼàni֖y hinĕ⁠ni֣y bĕ⁠yedĕ⁠ke֑m ʻàş̂ẇ-li֛⁠y kȧ⁠ṫ֥wòb wĕ⁠ka⁠yá̇şá֖̌r bĕ̇⁠ʻéynéy⁠keֽm׃"],[26,15,"אַ֣ךְ ׀ יָדֹ֣עַ תֵּדְע֗וּ כִּ֣י אִם־מְמִתִ֣ים אַתֶּם֮ אֹתִ⁠י֒ כִּי־דָ֣ם נָקִ֗י אַתֶּם֙ נֹתְנִ֣ים עֲלֵי⁠כֶ֔ם וְ⁠אֶל־הָ⁠עִ֥יר הַ⁠זֹּ֖את וְ⁠אֶל־יֹשְׁבֶ֑י⁠הָ כִּ֣י בֶ⁠אֱמֶ֗ת שְׁלָחַ֤⁠נִי יְהוָה֙ עֲלֵי⁠כֶ֔ם לְ⁠דַבֵּר֙ בְּ⁠אָזְנֵי⁠כֶ֔ם אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃ס","ʼa֣kĕ ׀ yádò֣ʻa ţé̇dĕʻ֗ẇ ki֣̇y ʼim-mĕmiţi֣ym ʼaţėm֮ ʼòţi⁠y֒ ki̇y-dá֣m náqi֗y ʼaţėm֙ nòţĕni֣ym ʻàléy⁠ke֔m wĕ⁠ʼel-há⁠ʻi֥yr ha⁠zò֖̇ʼţ wĕ⁠ʼel-yòşĕ̌be֑y⁠há ki֣̇y be⁠ʼème֗ţ şĕ̌láẖa֤⁠niy yĕhwáh֙ ʻàléy⁠ke֔m lĕ⁠dabé̇r֙ bĕ̇⁠ʼázĕnéy⁠ke֔m ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃s"],[26,16,"וַ⁠יֹּאמְר֤וּ הַ⁠שָּׂרִים֙ וְ⁠כָל־הָ⁠עָ֔ם אֶל־הַ⁠כֹּהֲנִ֖ים וְ⁠אֶל־הַ⁠נְּבִיאִ֑ים אֵין־לָ⁠אִ֤ישׁ הַ⁠זֶּה֙ מִשְׁפַּט־מָ֔וֶת כִּ֗י בְּ⁠שֵׁ֛ם יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ דִּבֶּ֥ר אֵלֵֽי⁠נוּ׃","wa⁠yò̇ʼmĕr֤ẇ ha⁠şá̇̂riym֙ wĕ⁠kál-há⁠ʻá֔m ʼel-ha⁠kò̇hàni֖ym wĕ⁠ʼel-ha⁠nĕ̇biyʼi֑ym ʼéyn-lá⁠ʼi֤yş̌ ha⁠zėh֙ mişĕ̌pȧt-má֔weţ ki̇֗y bĕ̇⁠şé֛̌m yĕhwá֥h ʼèlòhé֖y⁠nẇ di̇bė֥r ʼéléֽy⁠nẇ׃"],[26,17,"וַ⁠יָּקֻ֣מוּ אֲנָשִׁ֔ים מִ⁠זִּקְנֵ֖י הָ⁠אָ֑רֶץ וַ⁠יֹּ֣אמְר֔וּ אֶל־כָּל־קְהַ֥ל הָ⁠עָ֖ם לֵ⁠אמֹֽר׃","wa⁠yá̇qu֣mẇ ʼànáşǐ֔ym mi⁠zi̇qĕné֖y há⁠ʼá֑reẕ wa⁠yò֣̇ʼmĕr֔ẇ ʼel-ká̇l-qĕha֥l há⁠ʻá֖m lé⁠ʼmòֽr׃"],[26,18,"מיכיה הַ⁠מּ֣וֹרַשְׁתִּ֔י הָיָ֣ה נִבָּ֔א בִּ⁠ימֵ֖י חִזְקִיָּ֣הוּ מֶֽלֶךְ־יְהוּדָ֑ה וַ⁠יֹּ֣אמֶר אֶל־כָּל־עַם֩ יְהוּדָ֨ה לֵ⁠אמֹ֜ר כֹּֽה־אָמַ֣ר ׀ יְהוָ֣ה צְבָא֗וֹת צִיּ֞וֹן שָׂדֶ֤ה תֵֽחָרֵשׁ֙ וִ⁠ירוּשָׁלַ֨יִם֙ עִיִּ֣ים תִּֽהְיֶ֔ה וְ⁠הַ֥ר הַ⁠בַּ֖יִת לְ⁠בָמ֥וֹת יָֽעַר׃","mykyh ha⁠ṁ֣wòraşĕ̌ţi̇֔y háyá֣h nibá̇֔ʼ bi̇⁠ymé֖y ẖizĕqiyá֣̇hẇ meֽlekĕ-yĕhẇdá֑h wa⁠yò֣̇ʼmer ʼel-ká̇l-ʻam֩ yĕhẇdá֨h lé⁠ʼmò֜r kòֽ̇h-ʼáma֣r ׀ yĕhwá֣h ẕĕbáʼ֗wòţ ẕiẏ֞wòn şá̂de֤h ţéֽẖáréş̌֙ wi⁠yrẇşá̌la֨yim֙ ʻiyi֣̇ym ţiֽ̇hĕye֔h wĕ⁠ha֥r ha⁠bȧ֖yiţ lĕ⁠bám֥wòţ yáֽʻar׃"],[26,19,"הֶ⁠הָמֵ֣ת הֱ֠מִתֻ⁠הוּ חִזְקִיָּ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה וְ⁠כָל־יְהוּדָ֗ה הֲ⁠לֹא֮ יָרֵ֣א אֶת־יְהוָה֒ וַ⁠יְחַל֙ אֶת־פְּנֵ֣י יְהוָ֔ה וַ⁠יִּנָּ֣חֶם יְהוָ֔ה אֶל־הָ⁠רָעָ֖ה אֲשֶׁר־דִּבֶּ֣ר עֲלֵי⁠הֶ֑ם וַ⁠אֲנַ֗חְנוּ עֹשִׂ֛ים רָעָ֥ה גְדוֹלָ֖ה עַל־נַפְשׁוֹתֵֽי⁠נוּ׃","he⁠hámé֣ţ hè֠miţu⁠hẇ ẖizĕqiyá̇֨hẇ meֽlekĕ-yĕhẇdá֜h wĕ⁠kál-yĕhẇdá֗h hà⁠lòʼ֮ yáré֣ʼ ʼeţ-yĕhwáh֒ wa⁠yĕẖal֙ ʼeţ-pĕ̇né֣y yĕhwá֔h wa⁠yi̇ná֣̇ẖem yĕhwá֔h ʼel-há⁠ráʻá֖h ʼàşěr-di̇bė֣r ʻàléy⁠he֑m wa⁠ʼàna֗ẖĕnẇ ʻòşî֛ym ráʻá֥h gĕdwòlá֖h ʻal-napĕş̌wòţéֽy⁠nẇ׃"],[26,20,"וְ⁠גַם־אִ֗ישׁ הָיָ֤ה מִתְנַבֵּא֙ בְּ⁠שֵׁ֣ם יְהוָ֔ה אֽוּרִיָּ֨הוּ֙ בֶּֽן־שְׁמַעְיָ֔הוּ מִ⁠קִּרְיַ֖ת הַיְּעָרִ֑ים וַ⁠יִּנָּבֵ֞א עַל־הָ⁠עִ֤יר הַ⁠זֹּאת֙ וְ⁠עַל־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את כְּ⁠כֹ֖ל דִּבְרֵ֥י יִרְמְיָֽהוּ׃","wĕ⁠gam-ʼi֗yş̌ háyá֤h miţĕnabé̇ʼ֙ bĕ̇⁠şé֣̌m yĕhwá֔h ʼֽẇriyá̇֨hẇ֙ bėֽn-şĕ̌maʻĕyá֔hẇ mi⁠qi̇rĕya֖ţ hayĕ̇ʻári֑ym wa⁠yi̇ná̇bé֞ʼ ʻal-há⁠ʻi֤yr ha⁠zò̇ʼţ֙ wĕ⁠ʻal-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ kĕ̇⁠kò֖l di̇bĕré֥y yirĕmĕyáֽhẇ׃"],[26,21,"וַ⁠יִּשְׁמַ֣ע הַ⁠מֶּֽלֶךְ־יְ֠הוֹיָקִים וְ⁠כָל־גִּבּוֹרָ֤י⁠ו וְ⁠כָל־הַ⁠שָּׂרִים֙ אֶת־דְּבָרָ֔י⁠ו וַ⁠יְבַקֵּ֥שׁ הַ⁠מֶּ֖לֶךְ הֲמִית֑⁠וֹ וַ⁠יִּשְׁמַ֤ע אוּרִיָּ֨הוּ֙ וַ⁠יִּרָ֔א וַ⁠יִּבְרַ֖ח וַ⁠יָּבֹ֥א מִצְרָֽיִם׃","wa⁠yi̇şĕ̌ma֣ʻ ha⁠mėֽlekĕ-yĕ֠hwòyáqiym wĕ⁠kál-gi̇ḃwòrá֤y⁠w wĕ⁠kál-ha⁠şá̇̂riym֙ ʼeţ-dĕ̇bárá֔y⁠w wa⁠yĕbaqé֥̇ş̌ ha⁠mė֖lekĕ hàmiyţ֑⁠wò wa⁠yi̇şĕ̌ma֤ʻ ʼẇriyá̇֨hẇ֙ wa⁠yi̇rá֔ʼ wa⁠yi̇bĕra֖ẖ wa⁠yá̇bò֥ʼ miẕĕráֽyim׃"],[26,22,"וַ⁠יִּשְׁלַ֞ח הַ⁠מֶּ֧לֶךְ יְהוֹיָקִ֛ים אֲנָשִׁ֖ים מִצְרָ֑יִם אֵ֣ת אֶלְנָתָ֧ן בֶּן־עַכְבּ֛וֹר וַ⁠אֲנָשִׁ֥ים אִתּ֖⁠וֹ אֶל־מִצְרָֽיִם׃","wa⁠yi̇şĕ̌la֞ẖ ha⁠mė֧lekĕ yĕhwòyáqi֛ym ʼànáşǐ֖ym miẕĕrá֑yim ʼé֣ţ ʼelĕnáţá֧n bėn-ʻakĕḃ֛wòr wa⁠ʼànáşǐ֥ym ʼiţ֖̇⁠wò ʼel-miẕĕráֽyim׃"],[26,23,"וַ⁠יּוֹצִ֨יאוּ אֶת־אוּרִיָּ֜הוּ מִ⁠מִּצְרַ֗יִם וַ⁠יְבִאֻ֨⁠הוּ֙ אֶל־הַ⁠מֶּ֣לֶךְ יְהוֹיָקִ֔ים וַ⁠יַּכֵּ֖⁠הוּ בֶּ⁠חָ֑רֶב וַ⁠יַּשְׁלֵךְ֙ אֶת־נִבְלָת֔⁠וֹ אֶל־קִבְרֵ֖י בְּנֵ֥י הָ⁠עָֽם׃","wa⁠ẏwòẕi֨yʼẇ ʼeţ-ʼẇriyá̇֜hẇ mi⁠mi̇ẕĕra֗yim wa⁠yĕbiʼu֨⁠hẇ֙ ʼel-ha⁠mė֣lekĕ yĕhwòyáqi֔ym wa⁠yȧké֖̇⁠hẇ bė⁠ẖá֑reb wa⁠yȧşĕ̌lékĕ֙ ʼeţ-nibĕláţ֔⁠wò ʼel-qibĕré֖y bĕ̇né֥y há⁠ʻáֽm׃"],[26,24,"אַ֗ךְ יַ֚ד אֲחִיקָ֣ם בֶּן־שָׁפָ֔ן הָיְתָ֖ה אֶֽת־יִרְמְיָ֑הוּ לְ⁠בִלְתִּ֛י תֵּת־אֹת֥⁠וֹ בְ⁠יַד־הָ⁠עָ֖ם לַ⁠הֲמִיתֽ⁠וֹ׃פ","ʼa֗kĕ ya֚d ʼàẖiyqá֣m bėn-şá̌pá֔n háyĕţá֖h ʼeֽţ-yirĕmĕyá֑hẇ lĕ⁠bilĕţi֛̇y ţé̇ţ-ʼòţ֥⁠wò bĕ⁠yad-há⁠ʻá֖m la⁠hàmiyţֽ⁠wò׃p"],[27,1,"בְּ⁠רֵאשִׁ֗ית מַמְלֶ֛כֶת יְהוֹיָקִ֥ם בֶּן־יֹאושִׁיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה הָיָ֞ה הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ אֶֽל־יִרְמְיָ֔ה מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","bĕ̇⁠réʼşǐ֗yţ mamĕle֛keţ yĕhwòyáqi֥m bėn-yòʼwşǐyá֖̇hẇ me֣lekĕ yĕhẇdá֑h háyá֞h ha⁠dá̇bá֤r ha⁠zėh֙ ʼeֽl-yirĕmĕyá֔h mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[27,2,"כֹּֽה־אָמַ֤ר יְהוָה֙ אֵלַ֔⁠י עֲשֵׂ֣ה לְ⁠ךָ֔ מוֹסֵר֖וֹת וּ⁠מֹט֑וֹת וּ⁠נְתַתָּ֖⁠ם עַל־צַוָּארֶֽ⁠ךָ׃","kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼéla֔⁠y ʻàşé֣̂h lĕ⁠ká֔ mwòsér֖wòţ ẇ⁠mòt֑wòţ ẇ⁠nĕţaţá֖̇⁠m ʻal-ẕawá̇ʼreֽ⁠ká׃"],[27,3,"וְ⁠שִׁלַּחְתָּ⁠ם֩ אֶל־מֶ֨לֶךְ אֱד֜וֹם וְ⁠אֶל־מֶ֣לֶךְ מוֹאָ֗ב וְ⁠אֶל־מֶ֨לֶךְ֙ בְּנֵ֣י עַמּ֔וֹן וְ⁠אֶל־מֶ֥לֶךְ צֹ֖ר וְ⁠אֶל־מֶ֣לֶךְ צִיד֑וֹן בְּ⁠יַ֤ד מַלְאָכִים֙ הַ⁠בָּאִ֣ים יְרוּשָׁלִַ֔ם אֶל־צִדְקִיָּ֖הוּ מֶ֥לֶךְ יְהוּדָֽה׃","wĕ⁠şǐlȧẖĕţá̇⁠m֩ ʼel-me֨lekĕ ʼèd֜wòm wĕ⁠ʼel-me֣lekĕ mwòʼá֗b wĕ⁠ʼel-me֨lekĕ֙ bĕ̇né֣y ʻaṁ֔wòn wĕ⁠ʼel-me֥lekĕ ẕò֖r wĕ⁠ʼel-me֣lekĕ ẕiyd֑wòn bĕ̇⁠ya֤d malĕʼákiym֙ ha⁠bá̇ʼi֣ym yĕrẇşá̌lia֔m ʼel-ẕidĕqiyá֖̇hẇ me֥lekĕ yĕhẇdáֽh׃"],[27,4,"וְ⁠צִוִּיתָ֣ אֹתָ֔⁠ם אֶל־אֲדֹֽנֵי⁠הֶ֖ם לֵ⁠אמֹ֑ר כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כֹּ֥ה תֹֽאמְר֖וּ אֶל־אֲדֹֽנֵי⁠כֶֽם׃","wĕ⁠ẕiwi̇yţá֣ ʼòţá֔⁠m ʼel-ʼàdòֽnéy⁠he֖m lé⁠ʼmò֑r kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kò֥̇h ţòֽʼmĕr֖ẇ ʼel-ʼàdòֽnéy⁠keֽm׃"],[27,5,"אָנֹכִ֞י עָשִׂ֣יתִי אֶת־הָ⁠אָ֗רֶץ אֶת־הָ⁠אָדָ֤ם וְ⁠אֶת־הַ⁠בְּהֵמָה֙ אֲשֶׁר֙ עַל־פְּנֵ֣י הָ⁠אָ֔רֶץ בְּ⁠כֹחִ⁠י֙ הַ⁠גָּד֔וֹל וּ⁠בִ⁠זְרוֹעִ֖⁠י הַ⁠נְּטוּיָ֑ה וּ⁠נְתַתִּ֕י⁠הָ לַ⁠אֲשֶׁ֖ר יָשַׁ֥ר בְּ⁠עֵינָֽ⁠י׃","ʼánòki֞y ʻáşî֣yţiy ʼeţ-há⁠ʼá֗reẕ ʼeţ-há⁠ʼádá֤m wĕ⁠ʼeţ-ha⁠bĕ̇hémáh֙ ʼàşěr֙ ʻal-pĕ̇né֣y há⁠ʼá֔reẕ bĕ̇⁠kòẖi⁠y֙ ha⁠gá̇d֔wòl ẇ⁠bi⁠zĕrwòʻi֖⁠y ha⁠nĕ̇tẇyá֑h ẇ⁠nĕţaţi̇֕y⁠há la⁠ʼàşě֖r yáşǎ֥r bĕ̇⁠ʻéynáֽ⁠y׃"],[27,6,"וְ⁠עַתָּ֗ה אָֽנֹכִי֙ נָתַ֨תִּי֙ אֶת־כָּל־הָ⁠אֲרָצ֣וֹת הָ⁠אֵ֔לֶּה בְּ⁠יַ֛ד נְבוּכַדְנֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל עַבְדִּ֑⁠י וְ⁠גַם֙ אֶת־חַיַּ֣ת הַ⁠שָּׂדֶ֔ה נָתַ֥תִּי ל֖⁠וֹ לְ⁠עָבְדֽ⁠וֹ׃","wĕ⁠ʻaţá̇֗h ʼáֽnòkiy֙ náţa֨ţi̇y֙ ʼeţ-ká̇l-há⁠ʼàráẕ֣wòţ há⁠ʼé֔lėh bĕ̇⁠ya֛d nĕbẇkadĕneʼẕȧ֥r meֽlekĕ-bá̇be֖l ʻabĕdi֑̇⁠y wĕ⁠gam֙ ʼeţ-ẖayȧ֣ţ ha⁠şá̇̂de֔h náţa֥ţi̇y l֖⁠wò lĕ⁠ʻábĕdֽ⁠wò׃"],[27,7,"וְ⁠עָבְד֤וּ אֹת⁠וֹ֙ כָּל־הַ⁠גּוֹיִ֔ם וְ⁠אֶת־בְּנ֖⁠וֹ וְ⁠אֶֽת־בֶּן־בְּנ֑⁠וֹ עַ֣ד בֹּא־עֵ֤ת אַרְצ⁠וֹ֙ גַּם־ה֔וּא וְ⁠עָ֤בְדוּ ב⁠וֹ֙ גּוֹיִ֣ם רַבִּ֔ים וּ⁠מְלָכִ֖ים גְּדֹלִֽים׃","wĕ⁠ʻábĕd֤ẇ ʼòţ⁠wò֙ ká̇l-ha⁠ġwòyi֔m wĕ⁠ʼeţ-bĕ̇n֖⁠wò wĕ⁠ʼeֽţ-bėn-bĕ̇n֑⁠wò ʻa֣d bò̇ʼ-ʻé֤ţ ʼarĕẕ⁠wò֙ gȧm-h֔ẇʼ wĕ⁠ʻá֤bĕdẇ b⁠wò֙ ġwòyi֣m rabi̇֔ym ẇ⁠mĕláki֖ym gĕ̇dòliֽym׃"],[27,8,"וְ⁠הָיָ֨ה הַ⁠גּ֜וֹי וְ⁠הַ⁠מַּמְלָכָ֗ה אֲשֶׁ֨ר לֹֽא־יַעַבְד֤וּ אֹת⁠וֹ֙ אֶת־נְבוּכַדְנֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֔ל וְ⁠אֵ֨ת אֲשֶׁ֤ר לֹֽא־יִתֵּן֙ אֶת־צַוָּאר֔⁠וֹ בְּ⁠עֹ֖ל מֶ֣לֶךְ בָּבֶ֑ל בַּ⁠חֶרֶב֩ וּ⁠בָ⁠רָעָ֨ב וּ⁠בַ⁠דֶּ֜בֶר אֶפְקֹ֨ד עַל־הַ⁠גּ֤וֹי הַ⁠הוּא֙ נְאֻם־יְהוָ֔ה עַד־תֻּמִּ֥⁠י אֹתָ֖⁠ם בְּ⁠יָדֽ⁠וֹ׃","wĕ⁠háyá֨h ha⁠ġ֜wòy wĕ⁠ha⁠mȧmĕláká֗h ʼàşě֨r lòֽʼ-yaʻabĕd֤ẇ ʼòţ⁠wò֙ ʼeţ-nĕbẇkadĕneʼẕȧ֣r meֽlekĕ-bá̇be֔l wĕ⁠ʼé֨ţ ʼàşě֤r lòֽʼ-yiţé̇n֙ ʼeţ-ẕawá̇ʼr֔⁠wò bĕ̇⁠ʻò֖l me֣lekĕ bá̇be֑l bȧ⁠ẖereb֩ ẇ⁠bá⁠ráʻá֨b ẇ⁠ba⁠dė֜ber ʼepĕqò֨d ʻal-ha⁠ġ֤wòy ha⁠hẇʼ֙ nĕʼum-yĕhwá֔h ʻad-ţu̇mi֥̇⁠y ʼòţá֖⁠m bĕ̇⁠yádֽ⁠wò׃"],[27,9,"וְ֠⁠אַתֶּם אַל־תִּשְׁמְע֨וּ אֶל־נְבִיאֵי⁠כֶ֜ם וְ⁠אֶל־קֹֽסְמֵי⁠כֶ֗ם וְ⁠אֶל֙ חֲלֹמֹ֣תֵי⁠כֶ֔ם וְ⁠אֶל־עֹֽנְנֵי⁠כֶ֖ם וְ⁠אֶל־כַּשָּׁפֵי⁠כֶ֑ם אֲשֶׁר־הֵ֞ם אֹמְרִ֤ים אֲלֵי⁠כֶם֙ לֵ⁠אמֹ֔ר לֹ֥א תַעַבְד֖וּ אֶת־מֶ֥לֶךְ בָּבֶֽל׃","wĕ֠⁠ʼaţėm ʼal-ţi̇şĕ̌mĕʻ֨ẇ ʼel-nĕbiyʼéy⁠ke֜m wĕ⁠ʼel-qòֽsĕméy⁠ke֗m wĕ⁠ʼel֙ ẖàlòmò֣ţéy⁠ke֔m wĕ⁠ʼel-ʻòֽnĕnéy⁠ke֖m wĕ⁠ʼel-kȧşá̇̌péy⁠ke֑m ʼàşěr-hé֞m ʼòmĕri֤ym ʼàléy⁠kem֙ lé⁠ʼmò֔r lò֥ʼ ţaʻabĕd֖ẇ ʼeţ-me֥lekĕ bá̇beֽl׃"],[27,10,"כִּ֣י שֶׁ֔קֶר הֵ֖ם נִבְּאִ֣ים לָ⁠כֶ֑ם לְמַ֨עַן הַרְחִ֤יק אֶתְ⁠כֶם֙ מֵ⁠עַ֣ל אַדְמַתְ⁠כֶ֔ם וְ⁠הִדַּחְתִּ֥י אֶתְ⁠כֶ֖ם וַ⁠אֲבַדְתֶּֽם׃","ki֣̇y şě֔qer hé֖m nibĕ̇ʼi֣ym lá⁠ke֑m lĕma֨ʻan harĕẖi֤yq ʼeţĕ⁠kem֙ mé⁠ʻa֣l ʼadĕmaţĕ⁠ke֔m wĕ⁠hidȧẖĕţi֥̇y ʼeţĕ⁠ke֖m wa⁠ʼàbadĕţėֽm׃"],[27,11,"וְ⁠הַ⁠גּ֗וֹי אֲשֶׁ֨ר יָבִ֧יא אֶת־צַוָּאר֛⁠וֹ בְּ⁠עֹ֥ל מֶֽלֶךְ־בָּבֶ֖ל וַֽ⁠עֲבָד֑⁠וֹ וְ⁠הִנַּחְתִּ֤י⁠ו עַל־אַדְמָת⁠וֹ֙ נְאֻם־יְהוָ֔ה וַֽ⁠עֲבָדָ֖⁠הּ וְ⁠יָ֥שַׁב בָּֽ⁠הּ׃","wĕ⁠ha⁠ġ֗wòy ʼàşě֨r yábi֧yʼ ʼeţ-ẕawá̇ʼr֛⁠wò bĕ̇⁠ʻò֥l meֽlekĕ-bá̇be֖l waֽ⁠ʻàbád֑⁠wò wĕ⁠hinȧẖĕţi֤̇y⁠w ʻal-ʼadĕmáţ⁠wò֙ nĕʼum-yĕhwá֔h waֽ⁠ʻàbádá֖⁠ḣ wĕ⁠yá֥şǎb báֽ̇⁠ḣ׃"],[27,12,"וְ⁠אֶל־צִדְקִיָּ֤ה מֶֽלֶךְ־יְהוּדָה֙ דִּבַּ֔רְתִּי כְּ⁠כָל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה לֵ⁠אמֹ֑ר הָבִ֨יאוּ אֶת־צַוְּארֵי⁠כֶ֜ם בְּ⁠עֹ֣ל מֶֽלֶךְ־בָּבֶ֗ל וְ⁠עִבְד֥וּ אֹת֛⁠וֹ וְ⁠עַמּ֖⁠וֹ וִֽ⁠חְיֽוּ׃","wĕ⁠ʼel-ẕidĕqiyá֤̇h meֽlekĕ-yĕhẇdáh֙ di̇bȧ֔rĕţi̇y kĕ̇⁠kál-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh lé⁠ʼmò֑r hábi֨yʼẇ ʼeţ-ẕawĕ̇ʼréy⁠ke֜m bĕ̇⁠ʻò֣l meֽlekĕ-bá̇be֗l wĕ⁠ʻibĕd֥ẇ ʼòţ֛⁠wò wĕ⁠ʻaṁ֖⁠wò wiֽ⁠ẖĕyֽẇ׃"],[27,13,"לָ֤⁠מָּה תָמ֨וּתוּ֙ אַתָּ֣ה וְ⁠עַמֶּ֔⁠ךָ בַּ⁠חֶ֖רֶב בָּ⁠רָעָ֣ב וּ⁠בַ⁠דָּ֑בֶר֙ כַּֽ⁠אֲשֶׁר֙ דִּבֶּ֣ר יְהוָ֔ה אֶל־הַ⁠גּ֕וֹי אֲשֶׁ֥ר לֹֽא־יַעֲבֹ֖ד אֶת־מֶ֥לֶךְ בָּבֶֽל׃","lá֤⁠má̇h ţám֨ẇţẇ֙ ʼaţá֣̇h wĕ⁠ʻamė֔⁠ká bȧ⁠ẖe֖reb bá̇⁠ráʻá֣b ẇ⁠ba⁠dá֑̇ber֙ kȧֽ⁠ʼàşěr֙ di̇bė֣r yĕhwá֔h ʼel-ha⁠ġ֕wòy ʼàşě֥r lòֽʼ-yaʻàbò֖d ʼeţ-me֥lekĕ bá̇beֽl׃"],[27,14,"וְ⁠אַֽל־תִּשְׁמְע֞וּ אֶל־דִּבְרֵ֣י הַ⁠נְּבִאִ֗ים הָ⁠אֹמְרִ֤ים אֲלֵי⁠כֶם֙ לֵ⁠אמֹ֔ר לֹ֥א תַעַבְד֖וּ אֶת־מֶ֣לֶךְ בָּבֶ֑ל כִּ֣י שֶׁ֔קֶר הֵ֖ם נִבְּאִ֥ים לָ⁠כֶֽם׃","wĕ⁠ʼaֽl-ţi̇şĕ̌mĕʻ֞ẇ ʼel-di̇bĕré֣y ha⁠nĕ̇biʼi֗ym há⁠ʼòmĕri֤ym ʼàléy⁠kem֙ lé⁠ʼmò֔r lò֥ʼ ţaʻabĕd֖ẇ ʼeţ-me֣lekĕ bá̇be֑l ki֣̇y şě֔qer hé֖m nibĕ̇ʼi֥ym lá⁠keֽm׃"],[27,15,"כִּ֣י לֹ֤א שְׁלַחְתִּי⁠ם֙ נְאֻם־יְהוָ֔ה וְ⁠הֵ֛ם נִבְּאִ֥ים בִּ⁠שְׁמִ֖⁠י לַ⁠שָּׁ֑קֶר לְמַ֨עַן הַדִּיחִ֤⁠י אֶתְ⁠כֶם֙ וַ⁠אֲבַדְתֶּ֔ם אַתֶּ֕ם וְ⁠הַ⁠נְּבִאִ֖ים הַֽ⁠נִּבְּאִ֥ים לָ⁠כֶֽם׃","ki֣̇y lò֤ʼ şĕ̌laẖĕţi̇y⁠m֙ nĕʼum-yĕhwá֔h wĕ⁠hé֛m nibĕ̇ʼi֥ym bi̇⁠şĕ̌mi֖⁠y la⁠şá֑̇̌qer lĕma֨ʻan hadi̇yẖi֤⁠y ʼeţĕ⁠kem֙ wa⁠ʼàbadĕţė֔m ʼaţė֕m wĕ⁠ha⁠nĕ̇biʼi֖ym hֽa⁠ni̇bĕ̇ʼi֥ym lá⁠keֽm׃"],[27,16,"וְ⁠אֶל־הַ⁠כֹּהֲנִים֩ וְ⁠אֶל־כָּל־הָ⁠עָ֨ם הַ⁠זֶּ֜ה דִּבַּ֣רְתִּי לֵ⁠אמֹ֗ר כֹּה֮ אָמַ֣ר יְהוָה֒ אַֽל־תִּשְׁמְע֞וּ אֶל־דִּבְרֵ֣י נְבִֽיאֵי⁠כֶ֗ם הַֽ⁠נִּבְּאִ֤ים לָ⁠כֶם֙ לֵ⁠אמֹ֔ר הִנֵּ֨ה כְלֵ֧י בֵית־יְהוָ֛ה מוּשָׁבִ֥ים מִ⁠בָּבֶ֖לָ⁠ה עַתָּ֣ה מְהֵרָ֑ה כִּ֣י שֶׁ֔קֶר הֵ֖מָּה נִבְּאִ֥ים לָ⁠כֶֽם׃","wĕ⁠ʼel-ha⁠kò̇hàniym֩ wĕ⁠ʼel-ká̇l-há⁠ʻá֨m ha⁠zė֜h di̇bȧ֣rĕţi̇y lé⁠ʼmò֗r kò̇h֮ ʼáma֣r yĕhwáh֒ ʼaֽl-ţi̇şĕ̌mĕʻ֞ẇ ʼel-di̇bĕré֣y nĕbiֽyʼéy⁠ke֗m haֽ⁠ni̇bĕ̇ʼi֤ym lá⁠kem֙ lé⁠ʼmò֔r hiné̇֨h kĕlé֧y béyţ-yĕhwá֛h mẇşá̌bi֥ym mi⁠bá̇be֖lá⁠h ʻaţá֣̇h mĕhérá֑h ki֣̇y şě֔qer hé֖má̇h nibĕ̇ʼi֥ym lá⁠keֽm׃"],[27,17,"אַל־תִּשְׁמְע֣וּ אֲלֵי⁠הֶ֔ם עִבְד֥וּ אֶת־מֶֽלֶךְ־בָּבֶ֖ל וִֽ⁠חְי֑וּ לָ֧⁠מָּה תִֽהְיֶ֛ה הָ⁠עִ֥יר הַ⁠זֹּ֖את חָרְבָּֽה׃","ʼal-ţi̇şĕ̌mĕʻ֣ẇ ʼàléy⁠he֔m ʻibĕd֥ẇ ʼeţ-meֽlekĕ-bá̇be֖l wiֽ⁠ẖĕy֑ẇ lá֧⁠má̇h ţiֽhĕye֛h há⁠ʻi֥yr ha⁠zò֖̇ʼţ ẖárĕbáֽ̇h׃"],[27,18,"וְ⁠אִם־נְבִאִ֣ים הֵ֔ם וְ⁠אִם־יֵ֥שׁ דְּבַר־יְהוָ֖ה אִתָּ֑⁠ם יִפְגְּעוּ־נָא֙ בַּֽ⁠יהוָ֣ה צְבָא֔וֹת לְ⁠בִלְתִּי־בֹ֜אוּ הַ⁠כֵּלִ֣ים ׀ הַ⁠נּוֹתָרִ֣ים בְּ⁠בֵית־יְהוָ֗ה וּ⁠בֵ֨ית מֶ֧לֶךְ יְהוּדָ֛ה וּ⁠בִ⁠ירוּשָׁלִַ֖ם בָּבֶֽלָ⁠ה׃פ","wĕ⁠ʼim-nĕbiʼi֣ym hé֔m wĕ⁠ʼim-yé֥ş̌ dĕ̇bar-yĕhwá֖h ʼiţá֑̇⁠m yipĕgĕ̇ʻẇ-náʼ֙ bȧֽ⁠yhwá֣h ẕĕbáʼ֔wòţ lĕ⁠bilĕţi̇y-bò֜ʼẇ ha⁠ké̇li֣ym ׀ ha⁠ṅwòţári֣ym bĕ̇⁠béyţ-yĕhwá֗h ẇ⁠bé֨yţ me֧lekĕ yĕhẇdá֛h ẇ⁠bi⁠yrẇşá̌lia֖m bá̇beֽlá⁠h׃p"],[27,19,"כִּ֣י כֹ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת אֶל־הָֽ⁠עַמֻּדִ֔ים וְ⁠עַל־הַ⁠יָּ֖ם וְ⁠עַל־הַ⁠מְּכֹנ֑וֹת וְ⁠עַל֙ יֶ֣תֶר הַ⁠כֵּלִ֔ים הַ⁠נּוֹתָרִ֖ים בָּ⁠עִ֥יר הַ⁠זֹּֽאת׃","ki֣̇y kò֤h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼel-háֽ⁠ʻamu̇di֔ym wĕ⁠ʻal-ha⁠yá֖̇m wĕ⁠ʻal-ha⁠mĕ̇kòn֑wòţ wĕ⁠ʻal֙ ye֣ţer ha⁠ké̇li֔ym ha⁠ṅwòţári֖ym bá̇⁠ʻi֥yr ha⁠zòֽ̇ʼţ׃"],[27,20,"אֲשֶׁ֣ר לֹֽא־לְקָחָ֗⁠ם נְבֽוּכַדְנֶאצַּר֙ מֶ֣לֶךְ בָּבֶ֔ל בַּ֠⁠גְלוֹת⁠וֹ אֶת־יְכָונְיָ֨ה בֶן־יְהוֹיָקִ֧ים מֶֽלֶךְ־יְהוּדָ֛ה מִ⁠ירֽוּשָׁלִַ֖ם בָּבֶ֑לָ⁠ה וְ⁠אֵ֛ת כָּל־חֹרֵ֥י יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃ס","ʼàşě֣r lòֽʼ-lĕqáẖá֗⁠m nĕbֽẇkadĕneʼẕȧr֙ me֣lekĕ bá̇be֔l bȧ֠⁠gĕlwòţ⁠wò ʼeţ-yĕkáwnĕyá֨h ben-yĕhwòyáqi֧ym meֽlekĕ-yĕhẇdá֛h mi⁠yrֽẇşá̌lia֖m bá̇be֑lá⁠h wĕ⁠ʼé֛ţ ká̇l-ẖòré֥y yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃s"],[27,21,"כִּ֣י כֹ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל עַל־הַ⁠כֵּלִ֗ים הַ⁠נּֽוֹתָרִים֙ בֵּ֣ית יְהוָ֔ה וּ⁠בֵ֥ית מֶֽלֶךְ־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃","ki֣̇y kò֥h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhé֣y yişĕ̂ráʼé֑l ʻal-ha⁠ké̇li֗ym ha⁠ṅֽwòţáriym֙ bé֣̇yţ yĕhwá֔h ẇ⁠bé֥yţ meֽlekĕ-yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃"],[27,22,"בָּבֶ֥לָ⁠ה יוּבָ֖אוּ וְ⁠שָׁ֣מָּ⁠ה יִֽהְי֑וּ עַ֠ד י֣וֹם פָּקְדִ֤⁠י אֹתָ⁠ם֙ נְאֻם־יְהוָ֔ה וְ⁠הַֽעֲלִיתִי⁠ם֙ וַ⁠הֲשִׁ֣יבֹתִ֔י⁠ם אֶל־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃פ","bá̇be֥lá⁠h yẇbá֖ʼẇ wĕ⁠şá֣̌má̇⁠h yiֽhĕy֑ẇ ʻa֠d y֣wòm pá̇qĕdi֤⁠y ʼòţá⁠m֙ nĕʼum-yĕhwá֔h wĕ⁠haֽʻàliyţiy⁠m֙ wa⁠hàşǐ֣ybòţi֔y⁠m ʼel-ha⁠má̇q֖wòm ha⁠zėֽh׃p"],[28,1,"וַ⁠יְהִ֣י ׀ בַּ⁠שָּׁנָ֣ה הַ⁠הִ֗יא בְּ⁠רֵאשִׁית֙ מַמְלֶ֨כֶת֙ צִדְקִיָּ֣ה מֶֽלֶךְ־יְהוּדָ֔ה ב⁠שנת הָֽ⁠רְבִעִ֔ית בַּ⁠חֹ֖דֶשׁ הַ⁠חֲמִישִׁ֑י אָמַ֣ר אֵלַ֡⁠י חֲנַנְיָה֩ בֶן־עַזּ֨וּר הַ⁠נָּבִ֜יא אֲשֶׁ֤ר מִ⁠גִּבְעוֹן֙ בְּ⁠בֵ֣ית יְהוָ֔ה לְ⁠עֵינֵ֧י הַ⁠כֹּהֲנִ֛ים וְ⁠כָל־הָ⁠עָ֖ם לֵ⁠אמֹֽר׃","wa⁠yĕhi֣y ׀ bȧ⁠şá̇̌ná֣h ha⁠hi֗yʼ bĕ̇⁠réʼşǐyţ֙ mamĕle֨keţ֙ ẕidĕqiyá֣̇h meֽlekĕ-yĕhẇdá֔h b⁠şnţ háֽ⁠rĕbiʻi֔yţ bȧ⁠ẖò֖deş̌ ha⁠ẖàmiyşǐ֑y ʼáma֣r ʼéla֡⁠y ẖànanĕyáh֩ ben-ʻaż֨ẇr ha⁠ná̇bi֜yʼ ʼàşě֤r mi⁠gi̇bĕʻwòn֙ bĕ̇⁠bé֣yţ yĕhwá֔h lĕ⁠ʻéyné֧y ha⁠kò̇hàni֛ym wĕ⁠kál-há⁠ʻá֖m lé⁠ʼmòֽr׃"],[28,2,"כֹּֽה־אָמַ֞ר יְהוָ֧ה צְבָא֛וֹת אֱלֹהֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר שָׁבַ֞רְתִּי אֶת־עֹ֖ל מֶ֥לֶךְ בָּבֶֽל׃","kòֽ̇h-ʼáma֞r yĕhwá֧h ẕĕbáʼ֛wòţ ʼèlòhé֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r şá̌ba֞rĕţi̇y ʼeţ-ʻò֖l me֥lekĕ bá̇beֽl׃"],[28,3,"בְּ⁠ע֣וֹד ׀ שְׁנָתַ֣יִם יָמִ֗ים אֲנִ֤י מֵשִׁיב֙ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה אֶֽת־כָּל־כְּלֵ֖י בֵּ֣ית יְהוָ֑ה אֲשֶׁ֨ר לָקַ֜ח נְבוּכַדנֶאצַּ֤ר מֶֽלֶךְ־בָּבֶל֙ מִן־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה וַ⁠יְבִיאֵ֖⁠ם בָּבֶֽל׃","bĕ̇⁠ʻ֣wòd ׀ şĕ̌náţa֣yim yámi֗ym ʼàni֤y méşǐyb֙ ʼel-ha⁠má̇q֣wòm ha⁠zė֔h ʼeֽţ-ká̇l-kĕ̇lé֖y bé֣̇yţ yĕhwá֑h ʼàşě֨r láqa֜ẖ nĕbẇkadneʼẕȧ֤r meֽlekĕ-bá̇bel֙ min-ha⁠má̇q֣wòm ha⁠zė֔h wa⁠yĕbiyʼé֖⁠m bá̇beֽl׃"],[28,4,"וְ⁠אֶת־יְכָנְיָ֣ה בֶן־יְהוֹיָקִ֣ים מֶֽלֶךְ־יְ֠הוּדָה וְ⁠אֶת־כָּל־גָּל֨וּת יְהוּדָ֜ה הַ⁠בָּאִ֣ים בָּבֶ֗לָ⁠ה אֲנִ֥י מֵשִׁ֛יב אֶל־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה נְאֻם־יְהוָ֑ה כִּ֣י אֶשְׁבֹּ֔ר אֶת־עֹ֖ל מֶ֥לֶךְ בָּבֶֽל׃","wĕ⁠ʼeţ-yĕkánĕyá֣h ben-yĕhwòyáqi֣ym meֽlekĕ-yĕ֠hẇdáh wĕ⁠ʼeţ-ká̇l-gá̇l֨ẇţ yĕhẇdá֜h ha⁠bá̇ʼi֣ym bá̇be֗lá⁠h ʼàni֥y méşǐ֛yb ʼel-ha⁠má̇q֥wòm ha⁠zė֖h nĕʼum-yĕhwá֑h ki֣̇y ʼeşĕ̌bò̇֔r ʼeţ-ʻò֖l me֥lekĕ bá̇beֽl׃"],[28,5,"וַ⁠יֹּ֨אמֶר֙ יִרְמְיָ֣ה הַ⁠נָּבִ֔יא אֶל־חֲנַנְיָ֖ה הַ⁠נָּבִ֑יא לְ⁠עֵינֵ֤י הַ⁠כֹּֽהֲנִים֙ וּ⁠לְ⁠עֵינֵ֣י כָל־הָ⁠עָ֔ם הָ⁠עֹמְדִ֖ים בְּ⁠בֵ֥ית יְהוָֽה׃","wa⁠yò̇֨ʼmer֙ yirĕmĕyá֣h ha⁠ná̇bi֔yʼ ʼel-ẖànanĕyá֖h ha⁠ná̇bi֑yʼ lĕ⁠ʻéyné֤y ha⁠kòֽ̇hàniym֙ ẇ⁠lĕ⁠ʻéyné֣y kál-há⁠ʻá֔m há⁠ʻòmĕdi֖ym bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[28,6,"וַ⁠יֹּ֨אמֶר֙ יִרְמְיָ֣ה הַ⁠נָּבִ֔יא אָמֵ֕ן כֵּ֖ן יַעֲשֶׂ֣ה יְהוָ֑ה יָקֵ֤ם יְהוָה֙ אֶת־דְּבָרֶ֔י⁠ךָ אֲשֶׁ֣ר נִבֵּ֗אתָ לְ⁠הָשִׁ֞יב כְּלֵ֤י בֵית־יְהוָה֙ וְ⁠כָל־הַ⁠גּוֹלָ֔ה מִ⁠בָּבֶ֖ל אֶל־הַ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","wa⁠yò̇֨ʼmer֙ yirĕmĕyá֣h ha⁠ná̇bi֔yʼ ʼámé֕n ké֖̇n yaʻàşê֣h yĕhwá֑h yáqé֤m yĕhwáh֙ ʼeţ-dĕ̇báre֔y⁠ká ʼàşě֣r nibé̇֗ʼţá lĕ⁠háşǐ֞yb kĕ̇lé֤y béyţ-yĕhwáh֙ wĕ⁠kál-ha⁠ġwòlá֔h mi⁠bá̇be֖l ʼel-ha⁠má̇q֥wòm ha⁠zėֽh׃"],[28,7,"אַךְ־שְׁמַֽע־נָא֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה אֲשֶׁ֥ר אָנֹכִ֖י דֹּבֵ֣ר בְּ⁠אָזְנֶ֑י⁠ךָ וּ⁠בְ⁠אָזְנֵ֖י כָּל־הָ⁠עָֽם׃","ʼakĕ-şĕ̌maֽʻ-náʼ֙ ha⁠dá̇bá֣r ha⁠zė֔h ʼàşě֥r ʼánòki֖y dò̇bé֣r bĕ̇⁠ʼázĕne֑y⁠ká ẇ⁠bĕ⁠ʼázĕné֖y ká̇l-há⁠ʻáֽm׃"],[28,8,"הַ⁠נְּבִיאִ֗ים אֲשֶׁ֨ר הָי֧וּ לְ⁠פָנַ֛⁠י וּ⁠לְ⁠פָנֶ֖י⁠ךָ מִן־הָֽ⁠עוֹלָ֑ם וַ⁠יִּנָּ֨בְא֜וּ אֶל־אֲרָצ֤וֹת רַבּוֹת֙ וְ⁠עַל־מַמְלָכ֣וֹת גְּדֹל֔וֹת לְ⁠מִלְחָמָ֖ה וּ⁠לְ⁠רָעָ֥ה וּ⁠לְ⁠דָֽבֶר׃","ha⁠nĕ̇biyʼi֗ym ʼàşě֨r háy֧ẇ lĕ⁠pána֛⁠y ẇ⁠lĕ⁠páne֖y⁠ká min-háֽ⁠ʻwòlá֑m wa⁠yi̇ná̇֨bĕʼ֜ẇ ʼel-ʼàráẕ֤wòţ raḃwòţ֙ wĕ⁠ʻal-mamĕlák֣wòţ gĕ̇dòl֔wòţ lĕ⁠milĕẖámá֖h ẇ⁠lĕ⁠ráʻá֥h ẇ⁠lĕ⁠dáֽber׃"],[28,9,"הַ⁠נָּבִ֕יא אֲשֶׁ֥ר יִנָּבֵ֖א לְ⁠שָׁל֑וֹם בְּ⁠בֹא֙ דְּבַ֣ר הַ⁠נָּבִ֗יא יִוָּדַע֙ הַ⁠נָּבִ֔יא אֲשֶׁר־שְׁלָח֥⁠וֹ יְהוָ֖ה בֶּ⁠אֱמֶֽת׃","ha⁠ná̇bi֕yʼ ʼàşě֥r yiná̇bé֖ʼ lĕ⁠şá̌l֑wòm bĕ̇⁠bòʼ֙ dĕ̇ba֣r ha⁠ná̇bi֗yʼ yiwá̇daʻ֙ ha⁠ná̇bi֔yʼ ʼàşěr-şĕ̌láẖ֥⁠wò yĕhwá֖h bė⁠ʼèmeֽţ׃"],[28,10,"וַ⁠יִּקַּ֞ח חֲנַנְיָ֤ה הַ⁠נָּבִיא֙ אֶת־הַ⁠מּוֹטָ֔ה מֵ⁠עַ֕ל צַוַּ֖אר יִרְמְיָ֣ה הַ⁠נָּבִ֑יא וַֽ⁠יִּשְׁבְּרֵֽ⁠הוּ׃","wa⁠yi̇qȧ֞ẖ ẖànanĕyá֤h ha⁠ná̇biyʼ֙ ʼeţ-ha⁠ṁwòtá֔h mé⁠ʻa֕l ẕawȧ֖ʼr yirĕmĕyá֣h ha⁠ná̇bi֑yʼ waֽ⁠yi̇şĕ̌bĕ̇réֽ⁠hẇ׃"],[28,11,"וַ⁠יֹּ֣אמֶר חֲנַנְיָה֩ לְ⁠עֵינֵ֨י כָל־הָ⁠עָ֜ם לֵ⁠אמֹ֗ר כֹּה֮ אָמַ֣ר יְהוָה֒ כָּ֣כָה אֶשְׁבֹּ֞ר אֶת־עֹ֣ל ׀ נְבֻֽכַדְנֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֗ל בְּ⁠עוֹד֙ שְׁנָתַ֣יִם יָמִ֔ים מֵ⁠עַ֕ל צַוַּ֖אר כָּל־הַ⁠גּוֹיִ֑ם וַ⁠יֵּ֛לֶךְ יִרְמְיָ֥ה הַ⁠נָּבִ֖יא לְ⁠דַרְכּֽ⁠וֹ׃פ","wa⁠yò֣̇ʼmer ẖànanĕyáh֩ lĕ⁠ʻéyné֨y kál-há⁠ʻá֜m lé⁠ʼmò֗r kò̇h֮ ʼáma֣r yĕhwáh֒ ká֣̇káh ʼeşĕ̌bò̇֞r ʼeţ-ʻò֣l ׀ nĕbuֽkadĕneʼẕȧ֣r meֽlekĕ-bá̇be֗l bĕ̇⁠ʻwòd֙ şĕ̌náţa֣yim yámi֔ym mé⁠ʻa֕l ẕawȧ֖ʼr ká̇l-ha⁠ġwòyi֑m wa⁠yé֛̇lekĕ yirĕmĕyá֥h ha⁠ná̇bi֖yʼ lĕ⁠darĕkֽ̇⁠wò׃p"],[28,12,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֶֽל־יִרְמְיָ֑ה אַ֠חֲרֵי שְׁב֞וֹר חֲנַנְיָ֤ה הַ⁠נָּבִיא֙ אֶת־הַ⁠מּוֹטָ֔ה מֵ⁠עַ֗ל צַוַּ֛אר יִרְמְיָ֥ה הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼeֽl-yirĕmĕyá֑h ʼa֠ẖàréy şĕ̌b֞wòr ẖànanĕyá֤h ha⁠ná̇biyʼ֙ ʼeţ-ha⁠ṁwòtá֔h mé⁠ʻa֗l ẕawȧ֛ʼr yirĕmĕyá֥h ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[28,13,"הָלוֹךְ֩ וְ⁠אָמַרְתָּ֨ אֶל־חֲנַנְיָ֜ה לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה מוֹטֹ֥ת עֵ֖ץ שָׁבָ֑רְתָּ וְ⁠עָשִׂ֥יתָ תַחְתֵּי⁠הֶ֖ן מֹט֥וֹת בַּרְזֶֽל׃","hálwòkĕ֩ wĕ⁠ʼámarĕţá̇֨ ʼel-ẖànanĕyá֜h lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h mwòtò֥ţ ʻé֖ẕ şá̌bá֑rĕţá̇ wĕ⁠ʻáşî֥yţá ţaẖĕţé̇y⁠he֖n mòt֥wòţ bȧrĕzeֽl׃"],[28,14,"כִּ֣י כֹֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל עֹ֣ל בַּרְזֶ֡ל נָתַ֜תִּי עַל־צַוַּ֣אר ׀ כָּל־הַ⁠גּוֹיִ֣ם הָ⁠אֵ֗לֶּה לַ⁠עֲבֹ֛ד אֶת־נְבֻכַדְנֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל וַ⁠עֲבָדֻ֑⁠הוּ וְ⁠גַ֛ם אֶת־חַיַּ֥ת הַ⁠שָּׂדֶ֖ה נָתַ֥תִּי לֽ⁠וֹ׃","ki֣̇y kòֽh-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l ʻò֣l bȧrĕze֡l náţa֜ţi̇y ʻal-ẕawȧ֣ʼr ׀ ká̇l-ha⁠ġwòyi֣m há⁠ʼé֗lėh la⁠ʻàbò֛d ʼeţ-nĕbukadĕneʼẕȧ֥r meֽlekĕ-bá̇be֖l wa⁠ʻàbádu֑⁠hẇ wĕ⁠ga֛m ʼeţ-ẖayȧ֥ţ ha⁠şá̇̂de֖h náţa֥ţi̇y lֽ⁠wò׃"],[28,15,"וַ⁠יֹּ֨אמֶר יִרְמְיָ֧ה הַ⁠נָּבִ֛יא אֶל־חֲנַנְיָ֥ה הַ⁠נָּבִ֖יא שְׁמַֽע־נָ֣א חֲנַנְיָ֑ה לֹֽא־שְׁלָחֲ⁠ךָ֣ יְהוָ֔ה וְ⁠אַתָּ֗ה הִבְטַ֛חְתָּ אֶת־הָ⁠עָ֥ם הַ⁠זֶּ֖ה עַל־שָֽׁקֶר׃","wa⁠yò̇֨ʼmer yirĕmĕyá֧h ha⁠ná̇bi֛yʼ ʼel-ẖànanĕyá֥h ha⁠ná̇bi֖yʼ şĕ̌maֽʻ-ná֣ʼ ẖànanĕyá֑h lòֽʼ-şĕ̌láẖà⁠ká֣ yĕhwá֔h wĕ⁠ʼaţá̇֗h hibĕta֛ẖĕţá̇ ʼeţ-há⁠ʻá֥m ha⁠zė֖h ʻal-şáֽ̌qer׃"],[28,16,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִי֙ מְשַֽׁלֵּֽחֲ⁠ךָ֔ מֵ⁠עַ֖ל פְּנֵ֣י הָ⁠אֲדָמָ֑ה הַ⁠שָּׁנָה֙ אַתָּ֣ה מֵ֔ת כִּֽי־סָרָ֥ה דִבַּ֖רְתָּ אֶל־יְהוָֽה׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠niy֙ mĕşǎֽléֽ̇ẖà⁠ká֔ mé⁠ʻa֖l pĕ̇né֣y há⁠ʼàdámá֑h ha⁠şá̇̌náh֙ ʼaţá֣̇h mé֔ţ kiֽ̇y-sárá֥h dibȧ֖rĕţá̇ ʼel-yĕhwáֽh׃"],[28,17,"וַ⁠יָּ֛מָת חֲנַנְיָ֥ה הַ⁠נָּבִ֖יא בַּ⁠שָּׁנָ֣ה הַ⁠הִ֑יא בַּ⁠חֹ֖דֶשׁ הַ⁠שְּׁבִיעִֽי׃פ","wa⁠yá֛̇máţ ẖànanĕyá֥h ha⁠ná̇bi֖yʼ bȧ⁠şá̇̌ná֣h ha⁠hi֑yʼ bȧ⁠ẖò֖deş̌ ha⁠şĕ̇̌biyʻiֽy׃p"],[29,1,"וְ⁠אֵ֨לֶּה֙ דִּבְרֵ֣י הַ⁠סֵּ֔פֶר אֲשֶׁ֥ר שָׁלַ֛ח יִרְמְיָ֥ה הַ⁠נָּבִ֖יא מִ⁠ירוּשָׁלִָ֑ם אֶל־יֶ֜תֶר זִקְנֵ֣י הַ⁠גּוֹלָ֗ה וְ⁠אֶל־הַ⁠כֹּהֲנִ֤ים וְ⁠אֶל־הַ⁠נְּבִיאִים֙ וְ⁠אֶל־כָּל־הָ⁠עָ֔ם אֲשֶׁ֨ר הֶגְלָ֧ה נְבֽוּכַדְנֶאצַּ֛ר מִ⁠ירוּשָׁלִַ֖ם בָּבֶֽלָ⁠ה׃","wĕ⁠ʼé֨lėh֙ di̇bĕré֣y ha⁠sé̇֔per ʼàşě֥r şá̌la֛ẖ yirĕmĕyá֥h ha⁠ná̇bi֖yʼ mi⁠yrẇşá̌liá֑m ʼel-ye֜ţer ziqĕné֣y ha⁠ġwòlá֗h wĕ⁠ʼel-ha⁠kò̇hàni֤ym wĕ⁠ʼel-ha⁠nĕ̇biyʼiym֙ wĕ⁠ʼel-ká̇l-há⁠ʻá֔m ʼàşě֨r hegĕlá֧h nĕbֽẇkadĕneʼẕȧ֛r mi⁠yrẇşá̌lia֖m bá̇beֽlá⁠h׃"],[29,2,"אַחֲרֵ֣י צֵ֣את יְכָנְיָֽה־הַ֠⁠מֶּלֶךְ וְ⁠הַ⁠גְּבִירָ֨ה וְ⁠הַ⁠סָּרִיסִ֜ים שָׂרֵ֨י יְהוּדָ֧ה וִ⁠ירוּשָׁלִַ֛ם וְ⁠הֶ⁠חָרָ֥שׁ וְ⁠הַ⁠מַּסְגֵּ֖ר מִ⁠ירוּשָׁלִָֽם׃","ʼaẖàré֣y ẕé֣ʼţ yĕkánĕyáֽh-ha֠⁠mėlekĕ wĕ⁠ha⁠gĕ̇biyrá֨h wĕ⁠ha⁠sá̇riysi֜ym şá̂ré֨y yĕhẇdá֧h wi⁠yrẇşá̌lia֛m wĕ⁠he⁠ẖárá֥ş̌ wĕ⁠ha⁠mȧsĕgé֖̇r mi⁠yrẇşá̌liáֽm׃"],[29,3,"בְּ⁠יַד֙ אֶלְעָשָׂ֣ה בֶן־שָׁפָ֔ן וּ⁠גְמַרְיָ֖ה בֶּן־חִלְקִיָּ֑ה אֲשֶׁ֨ר שָׁלַ֜ח צִדְקִיָּ֣ה מֶֽלֶךְ־יְהוּדָ֗ה אֶל־נְבוּכַדְנֶאצַּ֛ר מֶ֥לֶךְ בָּבֶ֖ל בָּבֶ֥לָ⁠ה לֵ⁠אמֹֽר׃ס","bĕ̇⁠yad֙ ʼelĕʻáşá֣̂h ben-şá̌pá֔n ẇ⁠gĕmarĕyá֖h bėn-ẖilĕqiyá֑̇h ʼàşě֨r şá̌la֜ẖ ẕidĕqiyá֣̇h meֽlekĕ-yĕhẇdá֗h ʼel-nĕbẇkadĕneʼẕȧ֛r me֥lekĕ bá̇be֖l bá̇be֥lá⁠h lé⁠ʼmòֽr׃s"],[29,4,"כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל לְ⁠כָל־הַ֨⁠גּוֹלָ֔ה אֲשֶׁר־הִגְלֵ֥יתִי מִ⁠ירוּשָׁלִַ֖ם בָּבֶֽלָ⁠ה׃","kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhé֣y yişĕ̂ráʼé֑l lĕ⁠kál-ha֨⁠ġwòlá֔h ʼàşěr-higĕlé֥yţiy mi⁠yrẇşá̌lia֖m bá̇beֽlá⁠h׃"],[29,5,"בְּנ֥וּ בָתִּ֖ים וְ⁠שֵׁ֑בוּ וְ⁠נִטְע֣וּ גַנּ֔וֹת וְ⁠אִכְל֖וּ אֶת־פִּרְיָֽ⁠ן׃","bĕ̇n֥ẇ báţi֖̇ym wĕ⁠şé֑̌bẇ wĕ⁠nitĕʻ֣ẇ gaṅ֔wòţ wĕ⁠ʼikĕl֖ẇ ʼeţ-pi̇rĕyáֽ⁠n׃"],[29,6,"קְח֣וּ נָשִׁ֗ים וְ⁠הוֹלִידוּ֮ בָּנִ֣ים וּ⁠בָנוֹת֒ וּ⁠קְח֨וּ לִ⁠בְנֵי⁠כֶ֜ם נָשִׁ֗ים וְ⁠אֶת־בְּנֽוֹתֵי⁠כֶם֙ תְּנ֣וּ לַֽ⁠אֲנָשִׁ֔ים וְ⁠תֵלַ֖דְנָה בָּנִ֣ים וּ⁠בָנ֑וֹת וּ⁠רְבוּ־שָׁ֖ם וְ⁠אַל־תִּמְעָֽטוּ׃","qĕẖ֣ẇ náşǐ֗ym wĕ⁠hwòliydẇ֮ bá̇ni֣ym ẇ⁠bánwòţ֒ ẇ⁠qĕẖ֨ẇ li⁠bĕnéy⁠ke֜m náşǐ֗ym wĕ⁠ʼeţ-bĕ̇nֽwòţéy⁠kem֙ ţĕ̇n֣ẇ laֽ⁠ʼànáşǐ֔ym wĕ⁠ţéla֖dĕnáh bá̇ni֣ym ẇ⁠bán֑wòţ ẇ⁠rĕbẇ-şá֖̌m wĕ⁠ʼal-ţi̇mĕʻáֽtẇ׃"],[29,7,"וְ⁠דִרְשׁ֞וּ אֶת־שְׁל֣וֹם הָ⁠עִ֗יר אֲשֶׁ֨ר הִגְלֵ֤יתִי אֶתְ⁠כֶם֙ שָׁ֔מָּ⁠ה וְ⁠הִתְפַּֽלְל֥וּ בַעֲדָ֖⁠הּ אֶל־יְהוָ֑ה כִּ֣י בִ⁠שְׁלוֹמָ֔⁠הּ יִהְיֶ֥ה לָ⁠כֶ֖ם שָׁלֽוֹם׃פ","wĕ⁠dirĕş̌֞ẇ ʼeţ-şĕ̌l֣wòm há⁠ʻi֗yr ʼàşě֨r higĕlé֤yţiy ʼeţĕ⁠kem֙ şá̌֔má̇⁠h wĕ⁠hiţĕpȧֽlĕl֥ẇ baʻàdá֖⁠ḣ ʼel-yĕhwá֑h ki֣̇y bi⁠şĕ̌lwòmá֔⁠ḣ yihĕye֥h lá⁠ke֖m şá̌lֽwòm׃p"],[29,8,"כִּי֩ כֹ֨ה אָמַ֜ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אַל־יַשִּׁ֧יאוּ לָ⁠כֶ֛ם נְבִֽיאֵי⁠כֶ֥ם אֲשֶׁר־בְּ⁠קִרְבְּ⁠כֶ֖ם וְ⁠קֹֽסְמֵי⁠כֶ֑ם וְ⁠אַֽל־תִּשְׁמְעוּ֙ אֶל־חֲלֹמֹ֣תֵי⁠כֶ֔ם אֲשֶׁ֥ר אַתֶּ֖ם מַחְלְמִֽים׃","ki̇y֩ kò֨h ʼáma֜r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼal-yaşi֧̇̌yʼẇ lá⁠ke֛m nĕbiֽyʼéy⁠ke֥m ʼàşěr-bĕ̇⁠qirĕbĕ̇⁠ke֖m wĕ⁠qòֽsĕméy⁠ke֑m wĕ⁠ʼaֽl-ţi̇şĕ̌mĕʻẇ֙ ʼel-ẖàlòmò֣ţéy⁠ke֔m ʼàşě֥r ʼaţė֖m maẖĕlĕmiֽym׃"],[29,9,"כִּ֣י בְ⁠שֶׁ֔קֶר הֵ֛ם נִבְּאִ֥ים לָ⁠כֶ֖ם בִּ⁠שְׁמִ֑⁠י לֹ֥א שְׁלַחְתִּ֖י⁠ם נְאֻם־יְהוָֽה׃ס","ki֣̇y bĕ⁠şě֔qer hé֛m nibĕ̇ʼi֥ym lá⁠ke֖m bi̇⁠şĕ̌mi֑⁠y lò֥ʼ şĕ̌laẖĕţi֖̇y⁠m nĕʼum-yĕhwáֽh׃s"],[29,10,"כִּֽי־כֹה֙ אָמַ֣ר יְהוָ֔ה כִּ֠י לְ⁠פִ֞י מְלֹ֧את לְ⁠בָבֶ֛ל שִׁבְעִ֥ים שָׁנָ֖ה אֶפְקֹ֣ד אֶתְ⁠כֶ֑ם וַ⁠הֲקִמֹתִ֤י עֲלֵי⁠כֶם֙ אֶת־דְּבָרִ֣⁠י הַ⁠טּ֔וֹב לְ⁠הָשִׁ֣יב אֶתְ⁠כֶ֔ם אֶל־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","kiֽ̇y-kòh֙ ʼáma֣r yĕhwá֔h ki̇֠y lĕ⁠pi֞y mĕlò֧ʼţ lĕ⁠bábe֛l şǐbĕʻi֥ym şá̌ná֖h ʼepĕqò֣d ʼeţĕ⁠ke֑m wa⁠hàqimòţi֤y ʻàléy⁠kem֙ ʼeţ-dĕ̇bári֣⁠y ha⁠ṫ֔wòb lĕ⁠háşǐ֣yb ʼeţĕ⁠ke֔m ʼel-ha⁠má̇q֖wòm ha⁠zėֽh׃"],[29,11,"כִּי֩ אָנֹכִ֨י יָדַ֜עְתִּי אֶת־הַ⁠מַּחֲשָׁבֹ֗ת אֲשֶׁ֧ר אָנֹכִ֛י חֹשֵׁ֥ב עֲלֵי⁠כֶ֖ם נְאֻם־יְהוָ֑ה מַחְשְׁב֤וֹת שָׁלוֹם֙ וְ⁠לֹ֣א לְ⁠רָעָ֔ה לָ⁠תֵ֥ת לָ⁠כֶ֖ם אַחֲרִ֥ית וְ⁠תִקְוָֽה׃","ki̇y֩ ʼánòki֨y yáda֜ʻĕţi̇y ʼeţ-ha⁠mȧẖàşá̌bò֗ţ ʼàşě֧r ʼánòki֛y ẖòşé֥̌b ʻàléy⁠ke֖m nĕʼum-yĕhwá֑h maẖĕşĕ̌b֤wòţ şá̌lwòm֙ wĕ⁠lò֣ʼ lĕ⁠ráʻá֔h lá⁠ţé֥ţ lá⁠ke֖m ʼaẖàri֥yţ wĕ⁠ţiqĕwáֽh׃"],[29,12,"וּ⁠קְרָאתֶ֤ם אֹתִ⁠י֙ וַֽ⁠הֲלַכְתֶּ֔ם וְ⁠הִתְפַּלַּלְתֶּ֖ם אֵלָ֑⁠י וְ⁠שָׁמַעְתִּ֖י אֲלֵי⁠כֶֽם׃","ẇ⁠qĕráʼţe֤m ʼòţi⁠y֙ waֽ⁠hàlakĕţė֔m wĕ⁠hiţĕpȧlȧlĕţė֖m ʼélá֑⁠y wĕ⁠şá̌maʻĕţi֖̇y ʼàléy⁠keֽm׃"],[29,13,"וּ⁠בִקַּשְׁתֶּ֥ם אֹתִ֖⁠י וּ⁠מְצָאתֶ֑ם כִּ֥י תִדְרְשֻׁ֖⁠נִי בְּ⁠כָל־לְבַבְ⁠כֶֽם׃","ẇ⁠biqȧşĕ̌ţė֥m ʼòţi֖⁠y ẇ⁠mĕẕáʼţe֑m ki֥̇y ţidĕrĕşǔ֖⁠niy bĕ̇⁠kál-lĕbabĕ⁠keֽm׃"],[29,14,"וְ⁠נִמְצֵ֣אתִי לָ⁠כֶם֮ נְאֻם־יְהוָה֒ וְ⁠שַׁבְתִּ֣י אֶת־שבית⁠כם וְ⁠קִבַּצְתִּ֣י אֶ֠תְ⁠כֶם מִֽ⁠כָּל־הַ⁠גּוֹיִ֞ם וּ⁠מִ⁠כָּל־הַ⁠מְּקוֹמ֗וֹת אֲשֶׁ֨ר הִדַּ֧חְתִּי אֶתְ⁠כֶ֛ם שָׁ֖ם נְאֻם־יְהוָ֑ה וַ⁠הֲשִׁבֹתִ֣י אֶתְ⁠כֶ֔ם אֶל־הַ֨⁠מָּק֔וֹם אֲשֶׁר־הִגְלֵ֥יתִי אֶתְ⁠כֶ֖ם מִ⁠שָּֽׁם׃","wĕ⁠nimĕẕé֣ʼţiy lá⁠kem֮ nĕʼum-yĕhwáh֒ wĕ⁠şǎbĕţi֣̇y ʼeţ-şbyţ⁠km wĕ⁠qibȧẕĕţi֣̇y ʼe֠ţĕ⁠kem miֽ⁠ká̇l-ha⁠ġwòyi֞m ẇ⁠mi⁠ká̇l-ha⁠mĕ̇qwòm֗wòţ ʼàşě֨r hidȧ֧ẖĕţi̇y ʼeţĕ⁠ke֛m şá֖̌m nĕʼum-yĕhwá֑h wa⁠hàşǐbòţi֣y ʼeţĕ⁠ke֔m ʼel-ha֨⁠má̇q֔wòm ʼàşěr-higĕlé֥yţiy ʼeţĕ⁠ke֖m mi⁠şáֽ̇̌m׃"],[29,15,"כִּ֖י אֲמַרְתֶּ֑ם הֵקִ֨ים לָ֧⁠נוּ יְהוָ֛ה נְבִאִ֖ים בָּבֶֽלָ⁠ה׃ס","ki֖̇y ʼàmarĕţė֑m héqi֨ym lá֧⁠nẇ yĕhwá֛h nĕbiʼi֖ym bá̇beֽlá⁠h׃s"],[29,16,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה אֶל־הַ⁠מֶּ֨לֶךְ֙ הַ⁠יּוֹשֵׁב֙ אֶל־כִּסֵּ֣א דָוִ֔ד וְ⁠אֶל־כָּל־הָ⁠עָ֔ם הַ⁠יּוֹשֵׁ֖ב בָּ⁠עִ֣יר הַ⁠זֹּ֑את אֲחֵי⁠כֶ֕ם אֲשֶׁ֛ר לֹֽא־יָצְא֥וּ אִתְּ⁠כֶ֖ם בַּ⁠גּוֹלָֽה׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ʼel-ha⁠mė֨lekĕ֙ ha⁠ẏwòşé̌b֙ ʼel-ki̇sé֣̇ʼ dáwi֔d wĕ⁠ʼel-ká̇l-há⁠ʻá֔m ha⁠ẏwòşé֖̌b bá̇⁠ʻi֣yr ha⁠zò֑̇ʼţ ʼàẖéy⁠ke֕m ʼàşě֛r lòֽʼ-yáẕĕʼ֥ẇ ʼiţĕ̇⁠ke֖m bȧ⁠ġwòláֽh׃"],[29,17,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִי֙ מְשַׁלֵּ֣חַ בָּ֔⁠ם אֶת־הַ⁠חֶ֖רֶב אֶת־הָ⁠רָעָ֣ב וְ⁠אֶת־הַ⁠דָּ֑בֶר וְ⁠נָתַתִּ֣י אוֹתָ֗⁠ם כַּ⁠תְּאֵנִים֙ הַ⁠שֹּׁ֣עָרִ֔ים אֲשֶׁ֥ר לֹא־תֵאָכַ֖לְנָה מֵ⁠רֹֽעַ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠niy֙ mĕşǎlé֣̇ẖa bá̇֔⁠m ʼeţ-ha⁠ẖe֖reb ʼeţ-há⁠ráʻá֣b wĕ⁠ʼeţ-ha⁠dá֑̇ber wĕ⁠náţaţi֣̇y ʼwòţá֗⁠m kȧ⁠ţĕ̇ʼéniym֙ ha⁠şò֣̇̌ʻári֔ym ʼàşě֥r lòʼ-ţéʼáka֖lĕnáh mé⁠ròֽʻa׃"],[29,18,"וְ⁠רָֽדַפְתִּי֙ אַֽחֲרֵי⁠הֶ֔ם בַּ⁠חֶ֖רֶב בָּ⁠רָעָ֣ב וּ⁠בַ⁠דָּ֑בֶר וּ⁠נְתַתִּ֨י⁠ם ל⁠זועה לְ⁠כֹ֣ל ׀ מַמְלְכ֣וֹת הָ⁠אָ֗רֶץ לְ⁠אָלָ֤ה וּ⁠לְ⁠שַׁמָּה֙ וְ⁠לִ⁠שְׁרֵקָ֣ה וּ⁠לְ⁠חֶרְפָּ֔ה בְּ⁠כָל־הַ⁠גּוֹיִ֖ם אֲשֶׁר־הִדַּחְתִּ֥י⁠ם שָֽׁם׃","wĕ⁠ráֽdapĕţi̇y֙ ʼaֽẖàréy⁠he֔m bȧ⁠ẖe֖reb bá̇⁠ráʻá֣b ẇ⁠ba⁠dá֑̇ber ẇ⁠nĕţaţi̇֨y⁠m l⁠zwʻh lĕ⁠kò֣l ׀ mamĕlĕk֣wòţ há⁠ʼá֗reẕ lĕ⁠ʼálá֤h ẇ⁠lĕ⁠şǎmá̇h֙ wĕ⁠li⁠şĕ̌réqá֣h ẇ⁠lĕ⁠ẖerĕpá̇֔h bĕ̇⁠kál-ha⁠ġwòyi֖m ʼàşěr-hidȧẖĕţi֥̇y⁠m şáֽ̌m׃"],[29,19,"תַּ֛חַת אֲשֶֽׁר־לֹא־שָׁמְע֥וּ אֶל־דְּבָרַ֖⁠י נְאֻם־יְהוָ֑ה אֲשֶׁר֩ שָׁלַ֨חְתִּי אֲלֵי⁠הֶ֜ם אֶת־עֲבָדַ֤⁠י הַ⁠נְּבִאִים֙ הַשְׁכֵּ֣ם וְ⁠שָׁלֹ֔חַ וְ⁠לֹ֥א שְׁמַעְתֶּ֖ם נְאֻם־יְהוָֽה׃","ţȧ֛ẖaţ ʼàşěֽr-lòʼ-şá̌mĕʻ֥ẇ ʼel-dĕ̇bára֖⁠y nĕʼum-yĕhwá֑h ʼàşěr֩ şá̌la֨ẖĕţi̇y ʼàléy⁠he֜m ʼeţ-ʻàbáda֤⁠y ha⁠nĕ̇biʼiym֙ haşĕ̌ké֣̇m wĕ⁠şá̌lò֔ẖa wĕ⁠lò֥ʼ şĕ̌maʻĕţė֖m nĕʼum-yĕhwáֽh׃"],[29,20,"וְ⁠אַתֶּ֖ם שִׁמְע֣וּ דְבַר־יְהוָ֑ה כָּל־הַ֨⁠גּוֹלָ֔ה אֲשֶׁר־שִׁלַּ֥חְתִּי מִ⁠ירוּשָׁלִַ֖ם בָּבֶֽלָ⁠ה׃ס","wĕ⁠ʼaţė֖m şǐmĕʻ֣ẇ dĕbar-yĕhwá֑h ká̇l-ha֨⁠ġwòlá֔h ʼàşěr-şǐlȧ֥ẖĕţi̇y mi⁠yrẇşá̌lia֖m bá̇beֽlá⁠h׃s"],[29,21,"כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל אֶל־אַחְאָ֤ב בֶּן־קֽוֹלָיָה֙ וְ⁠אֶל־צִדְקִיָּ֣הוּ בֶן־מַֽעֲשֵׂיָ֔ה הַֽ⁠נִּבְּאִ֥ים לָ⁠כֶ֛ם בִּ⁠שְׁמִ֖⁠י שָׁ֑קֶר הִנְ⁠נִ֣י ׀ נֹתֵ֣ן אֹתָ֗⁠ם בְּ⁠יַד֙ נְבֽוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֔ל וְ⁠הִכָּ֖⁠ם לְ⁠עֵינֵי⁠כֶֽם׃","kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l ʼel-ʼaẖĕʼá֤b bėn-qֽwòláyáh֙ wĕ⁠ʼel-ẕidĕqiyá֣̇hẇ ben-maֽʻàşé̂yá֔h haֽ⁠ni̇bĕ̇ʼi֥ym lá⁠ke֛m bi̇⁠şĕ̌mi֖⁠y şá֑̌qer hinĕ⁠ni֣y ׀ nòţé֣n ʼòţá֗⁠m bĕ̇⁠yad֙ nĕbֽẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇be֔l wĕ⁠hiká֖̇⁠m lĕ⁠ʻéynéy⁠keֽm׃"],[29,22,"וְ⁠לֻקַּ֤ח מֵ⁠הֶם֙ קְלָלָ֔ה לְ⁠כֹל֙ גָּל֣וּת יְהוּדָ֔ה אֲשֶׁ֥ר בְּ⁠בָבֶ֖ל לֵ⁠אמֹ֑ר יְשִֽׂמְ⁠ךָ֤ יְהוָה֙ כְּ⁠צִדְקִיָּ֣הוּ וּ⁠כְ⁠אֶחָ֔ב אֲשֶׁר־קָלָ֥⁠ם מֶֽלֶךְ־בָּבֶ֖ל בָּ⁠אֵֽשׁ׃","wĕ⁠luqȧ֤ẖ mé⁠hem֙ qĕlálá֔h lĕ⁠kòl֙ gá̇l֣ẇţ yĕhẇdá֔h ʼàşě֥r bĕ̇⁠bábe֖l lé⁠ʼmò֑r yĕşîֽmĕ⁠ká֤ yĕhwáh֙ kĕ̇⁠ẕidĕqiyá֣̇hẇ ẇ⁠kĕ⁠ʼeẖá֔b ʼàşěr-qálá֥⁠m meֽlekĕ-bá̇be֖l bá̇⁠ʼéֽş̌׃"],[29,23,"יַ֡עַן אֲשֶׁר֩ עָשׂ֨וּ נְבָלָ֜ה בְּ⁠יִשְׂרָאֵ֗ל וַ⁠יְנַֽאֲפוּ֙ אֶת־נְשֵׁ֣י רֵֽעֵי⁠הֶ֔ם וַ⁠יְדַבְּר֨וּ דָבָ֤ר בִּ⁠שְׁמִ⁠י֙ שֶׁ֔קֶר אֲשֶׁ֖ר ל֣וֹא צִוִּיתִ֑⁠ם וְ⁠אָנֹכִ֛י הו ידע וָ⁠עֵ֖ד נְאֻם־יְהוָֽה׃ס","ya֡ʻan ʼàşěr֩ ʻáş̂֨ẇ nĕbálá֜h bĕ̇⁠yişĕ̂ráʼé֗l wa⁠yĕnaֽʼàpẇ֙ ʼeţ-nĕşé֣̌y réֽʻéy⁠he֔m wa⁠yĕdabĕ̇r֨ẇ dábá֤r bi̇⁠şĕ̌mi⁠y֙ şě֔qer ʼàşě֖r l֣wòʼ ẕiwi̇yţi֑⁠m wĕ⁠ʼánòki֛y hw ydʻ wá⁠ʻé֖d nĕʼum-yĕhwáֽh׃s"],[29,24,"וְ⁠אֶל־שְׁמַעְיָ֥הוּ הַ⁠נֶּחֱלָמִ֖י תֹּאמַ֥ר לֵ⁠אמֹֽר׃","wĕ⁠ʼel-şĕ̌maʻĕyá֥hẇ ha⁠nėẖèlámi֖y ţò̇ʼma֥r lé⁠ʼmòֽr׃"],[29,25,"כֹּֽה־אָמַ֞ר יְהוָ֧ה צְבָא֛וֹת אֱלֹהֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר יַ֡עַן אֲשֶׁ֣ר אַתָּה֩ שָׁלַ֨חְתָּ בְ⁠שִׁמְ⁠כָ֜ה סְפָרִ֗ים אֶל־כָּל־הָ⁠עָם֙ אֲשֶׁ֣ר בִּ⁠ירוּשָׁלִַ֔ם וְ⁠אֶל־צְפַנְיָ֤ה בֶן־מַֽעֲשֵׂיָה֙ הַ⁠כֹּהֵ֔ן וְ⁠אֶ֥ל כָּל־הַ⁠כֹּהֲנִ֖ים לֵ⁠אמֹֽר׃","kòֽ̇h-ʼáma֞r yĕhwá֧h ẕĕbáʼ֛wòţ ʼèlòhé֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r ya֡ʻan ʼàşě֣r ʼaţá̇h֩ şá̌la֨ẖĕţá̇ bĕ⁠şǐmĕ⁠ká֜h sĕpári֗ym ʼel-ká̇l-há⁠ʻám֙ ʼàşě֣r bi̇⁠yrẇşá̌lia֔m wĕ⁠ʼel-ẕĕpanĕyá֤h ben-maֽʻàşé̂yáh֙ ha⁠kò̇hé֔n wĕ⁠ʼe֥l ká̇l-ha⁠kò̇hàni֖ym lé⁠ʼmòֽr׃"],[29,26,"יְהוָ֞ה נְתָנְ⁠ךָ֣ כֹהֵ֗ן תַּ֚חַת יְהוֹיָדָ֣ע הַ⁠כֹּהֵ֔ן לִֽ⁠הְי֤וֹת פְּקִדִים֙ בֵּ֣ית יְהוָ֔ה לְ⁠כָל־אִ֥ישׁ מְשֻׁגָּ֖ע וּ⁠מִתְנַבֵּ֑א וְ⁠נָתַתָּ֥ה אֹת֛⁠וֹ אֶל־הַ⁠מַּהְפֶּ֖כֶת וְ⁠אֶל־הַ⁠צִּינֹֽק׃","yĕhwá֞h nĕţánĕ⁠ká֣ kòhé֗n ţȧ֚ẖaţ yĕhwòyádá֣ʻ ha⁠kò̇hé֔n liֽ⁠hĕy֤wòţ pĕ̇qidiym֙ bé֣̇yţ yĕhwá֔h lĕ⁠kál-ʼi֥yş̌ mĕşǔgá֖̇ʻ ẇ⁠miţĕnabé֑̇ʼ wĕ⁠náţaţá֥̇h ʼòţ֛⁠wò ʼel-ha⁠mȧhĕpė֖keţ wĕ⁠ʼel-ha⁠ẕi̇ynòֽq׃"],[29,27,"וְ⁠עַתָּ֗ה לָ֚⁠מָּה לֹ֣א גָעַ֔רְתָּ בְּ⁠יִרְמְיָ֖הוּ הָֽ⁠עֲנְּתֹתִ֑י הַ⁠מִּתְנַבֵּ֖א לָ⁠כֶֽם׃","wĕ⁠ʻaţá̇֗h lá֚⁠má̇h lò֣ʼ gáʻa֔rĕţá̇ bĕ̇⁠yirĕmĕyá֖hẇ háֽ⁠ʻànĕ̇ţòţi֑y ha⁠mi̇ţĕnabé֖̇ʼ lá⁠keֽm׃"],[29,28,"כִּ֣י עַל־כֵּ֞ן שָׁלַ֥ח אֵלֵ֛י⁠נוּ בָּבֶ֥ל לֵ⁠אמֹ֖ר אֲרֻכָּ֣ה הִ֑יא בְּנ֤וּ בָתִּים֙ וְ⁠שֵׁ֔בוּ וְ⁠נִטְע֣וּ גַנּ֔וֹת וְ⁠אִכְל֖וּ אֶת־פְּרִי⁠הֶֽן׃","ki֣̇y ʻal-ké̇֞n şá̌la֥ẖ ʼélé֛y⁠nẇ bá̇be֥l lé⁠ʼmò֖r ʼàruká֣̇h hi֑yʼ bĕ̇n֤ẇ báţi̇ym֙ wĕ⁠şé̌֔bẇ wĕ⁠nitĕʻ֣ẇ gaṅ֔wòţ wĕ⁠ʼikĕl֖ẇ ʼeţ-pĕ̇riy⁠heֽn׃"],[29,29,"וַ⁠יִּקְרָ֛א צְפַנְיָ֥ה הַ⁠כֹּהֵ֖ן אֶת־הַ⁠סֵּ֣פֶר הַ⁠זֶּ֑ה בְּ⁠אָזְנֵ֖י יִרְמְיָ֥הוּ הַ⁠נָּבִֽיא׃פ","wa⁠yi̇qĕrá֛ʼ ẕĕpanĕyá֥h ha⁠kò̇hé֖n ʼeţ-ha⁠sé֣̇per ha⁠zė֑h bĕ̇⁠ʼázĕné֖y yirĕmĕyá֥hẇ ha⁠ná̇biֽyʼ׃p"],[29,30,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ lé⁠ʼmòֽr׃"],[29,31,"שְׁלַ֤ח עַל־כָּל־הַ⁠גּוֹלָה֙ לֵ⁠אמֹ֔ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה אֶל־שְׁמַעְיָ֖ה הַ⁠נֶּחֱלָמִ֑י יַ֡עַן אֲשֶׁר֩ נִבָּ֨א לָ⁠כֶ֜ם שְׁמַעְיָ֗ה וַֽ⁠אֲנִי֙ לֹ֣א שְׁלַחְתִּ֔י⁠ו וַ⁠יַּבְטַ֥ח אֶתְ⁠כֶ֖ם עַל־שָֽׁקֶר׃","şĕ̌la֤ẖ ʻal-ká̇l-ha⁠ġwòláh֙ lé⁠ʼmò֔r kò֚̇h ʼáma֣r yĕhwá֔h ʼel-şĕ̌maʻĕyá֖h ha⁠nėẖèlámi֑y ya֡ʻan ʼàşěr֩ nibá̇֨ʼ lá⁠ke֜m şĕ̌maʻĕyá֗h waֽ⁠ʼàniy֙ lò֣ʼ şĕ̌laẖĕţi̇֔y⁠w wa⁠yȧbĕta֥ẖ ʼeţĕ⁠ke֖m ʻal-şáֽ̌qer׃"],[29,32,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה הִנְ⁠נִ֨י פֹקֵ֜ד עַל־שְׁמַעְיָ֣ה הַ⁠נֶּחֱלָמִי֮ וְ⁠עַל־זַרְע⁠וֹ֒ לֹא־יִהְיֶ֨ה ל֜⁠וֹ אִ֣ישׁ ׀ יוֹשֵׁ֣ב ׀ בְּ⁠תוֹךְ־הָ⁠עָ֣ם הַ⁠זֶּ֗ה וְ⁠לֹֽא־יִרְאֶ֥ה בַ⁠טּ֛וֹב אֲשֶׁר־אֲנִ֥י עֹשֶֽׂה־לְ⁠עַמִּ֖⁠י נְאֻם־יְהוָ֑ה כִּֽי־סָרָ֥ה דִבֶּ֖ר עַל־יְהוָֽה׃ס","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h hinĕ⁠ni֨y pòqé֜d ʻal-şĕ̌maʻĕyá֣h ha⁠nėẖèlámiy֮ wĕ⁠ʻal-zarĕʻ⁠wò֒ lòʼ-yihĕye֨h l֜⁠wò ʼi֣yş̌ ׀ ywòşé֣̌b ׀ bĕ̇⁠ţwòkĕ-há⁠ʻá֣m ha⁠zė֗h wĕ⁠lòֽʼ-yirĕʼe֥h ba⁠ṫ֛wòb ʼàşěr-ʼàni֥y ʻòşêֽh-lĕ⁠ʻami֖̇⁠y nĕʼum-yĕhwá֑h kiֽ̇y-sárá֥h dibė֖r ʻal-yĕhwáֽh׃s"],[30,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר הָיָ֣ה אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","ha⁠dá̇bár֙ ʼàşě֣r háyá֣h ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[30,2,"כֹּֽה־אָמַ֧ר יְהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר כְּתָב־לְ⁠ךָ֗ אֵ֧ת כָּל־הַ⁠דְּבָרִ֛ים אֲשֶׁר־דִּבַּ֥רְתִּי אֵלֶ֖י⁠ךָ אֶל־סֵֽפֶר׃","kòֽ̇h-ʼáma֧r yĕhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r kĕ̇ţáb-lĕ⁠ká֗ ʼé֧ţ ká̇l-ha⁠dĕ̇bári֛ym ʼàşěr-di̇bȧ֥rĕţi̇y ʼéle֖y⁠ká ʼel-séֽper׃"],[30,3,"כִּ֠י הִנֵּ֨ה יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וְ֠⁠שַׁבְתִּי אֶת־שְׁב֨וּת עַמִּ֧⁠י יִשְׂרָאֵ֛ל וִֽ⁠יהוּדָ֖ה אָמַ֣ר יְהוָ֑ה וַ⁠הֲשִׁבֹתִ֗י⁠ם אֶל־הָ⁠אָ֛רֶץ אֲשֶׁר־נָתַ֥תִּי לַ⁠אֲבוֹתָ֖⁠ם וִֽ⁠ירֵשֽׁוּ⁠הָ׃פ","ki̇֠y hiné̇֨h yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wĕ֠⁠şǎbĕţi̇y ʼeţ-şĕ̌b֨ẇţ ʻami֧̇⁠y yişĕ̂ráʼé֛l wiֽ⁠yhẇdá֖h ʼáma֣r yĕhwá֑h wa⁠hàşǐbòţi֗y⁠m ʼel-há⁠ʼá֛reẕ ʼàşěr-náţa֥ţi̇y la⁠ʼàbwòţá֖⁠m wiֽ⁠yréşֽ̌ẇ⁠há׃p"],[30,4,"וְ⁠אֵ֣לֶּה הַ⁠דְּבָרִ֗ים אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אֶל־יִשְׂרָאֵ֖ל וְ⁠אֶל־יְהוּדָֽה׃","wĕ⁠ʼé֣lėh ha⁠dĕ̇bári֗ym ʼàşě֨r di̇bė֧r yĕhwá֛h ʼel-yişĕ̂ráʼé֖l wĕ⁠ʼel-yĕhẇdáֽh׃"],[30,5,"כִּי־כֹה֙ אָמַ֣ר יְהוָ֔ה ק֥וֹל חֲרָדָ֖ה שָׁמָ֑עְנוּ פַּ֖חַד וְ⁠אֵ֥ין שָׁלֽוֹם׃","ki̇y-kòh֙ ʼáma֣r yĕhwá֔h q֥wòl ẖàrádá֖h şá̌má֑ʻĕnẇ pȧ֖ẖad wĕ⁠ʼé֥yn şá̌lֽwòm׃"],[30,6,"שַׁאֲלוּ־נָ֣א וּ⁠רְא֔וּ אִם־יֹלֵ֖ד זָכָ֑ר מַדּוּעַ֩ רָאִ֨יתִי כָל־גֶּ֜בֶר יָדָ֤י⁠ו עַל־חֲלָצָי⁠ו֙ כַּ⁠יּ֣וֹלֵדָ֔ה וְ⁠נֶהֶפְכ֥וּ כָל־פָּנִ֖ים לְ⁠יֵרָקֽוֹן׃","şǎʼàlẇ-ná֣ʼ ẇ⁠rĕʼ֔ẇ ʼim-yòlé֖d záká֑r maḋẇʻa֩ ráʼi֨yţiy kál-gė֜ber yádá֤y⁠w ʻal-ẖàláẕáy⁠w֙ kȧ⁠ẏ֣wòlédá֔h wĕ⁠nehepĕk֥ẇ kál-pá̇ni֖ym lĕ⁠yéráqֽwòn׃"],[30,7,"ה֗וֹי כִּ֥י גָד֛וֹל הַ⁠יּ֥וֹם הַ⁠ה֖וּא מֵ⁠אַ֣יִן כָּמֹ֑⁠הוּ וְ⁠עֵֽת־צָרָ֥ה הִיא֙ לְ⁠יַֽעֲקֹ֔ב וּ⁠מִמֶּ֖⁠נָּה יִוָּשֵֽׁעַ׃","h֗wòy ki֥̇y gád֛wòl ha⁠ẏ֥wòm ha⁠h֖ẇʼ mé⁠ʼa֣yin ká̇mò֑⁠hẇ wĕ⁠ʻéֽţ-ẕárá֥h hiyʼ֙ lĕ⁠yaֽʻàqò֔b ẇ⁠mimė֖⁠ná̇h yiwá̇şéֽ̌ʻa׃"],[30,8,"וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻ֣ם ׀ יְהוָ֣ה צְבָא֗וֹת אֶשְׁבֹּ֤ר עֻלּ⁠וֹ֙ מֵ⁠עַ֣ל צַוָּארֶ֔⁠ךָ וּ⁠מוֹסְרוֹתֶ֖י⁠ךָ אֲנַתֵּ֑ק וְ⁠לֹא־יַעַבְדוּ־ב֥⁠וֹ ע֖וֹד זָרִֽים׃","wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼu֣m ׀ yĕhwá֣h ẕĕbáʼ֗wòţ ʼeşĕ̌bò֤̇r ʻul̇⁠wò֙ mé⁠ʻa֣l ẕawá̇ʼre֔⁠ká ẇ⁠mwòsĕrwòţe֖y⁠ká ʼànaţé֑̇q wĕ⁠lòʼ-yaʻabĕdẇ-b֥⁠wò ʻ֖wòd záriֽym׃"],[30,9,"וְ⁠עָ֣בְד֔וּ אֵ֖ת יְהוָ֣ה אֱלֹֽהֵי⁠הֶ֑ם וְ⁠אֵת֙ דָּוִ֣ד מַלְכָּ֔⁠ם אֲשֶׁ֥ר אָקִ֖ים לָ⁠הֶֽם׃ס","wĕ⁠ʻá֣bĕd֔ẇ ʼé֖ţ yĕhwá֣h ʼèlòֽhéy⁠he֑m wĕ⁠ʼéţ֙ dá̇wi֣d malĕká̇֔⁠m ʼàşě֥r ʼáqi֖ym lá⁠heֽm׃s"],[30,10,"וְ⁠אַתָּ֡ה אַל־תִּירָא֩ עַבְדִּ֨⁠י יַעֲקֹ֤ב נְאֻם־יְהֹוָה֙ וְ⁠אַל־תֵּחַ֣ת יִשְׂרָאֵ֔ל כִּ֠י הִנְ⁠נִ֤י מוֹשִֽׁיעֲ⁠ךָ֙ מֵֽ⁠רָח֔וֹק וְ⁠אֶֽת־זַרְעֲ⁠ךָ֖ מֵ⁠אֶ֣רֶץ שִׁבְיָ֑⁠ם וְ⁠שָׁ֧ב יַעֲקֹ֛ב וְ⁠שָׁקַ֥ט וְ⁠שַׁאֲנַ֖ן וְ⁠אֵ֥ין מַחֲרִֽיד׃","wĕ⁠ʼaţá̇֡h ʼal-ţi̇yráʼ֩ ʻabĕdi̇֨⁠y yaʻàqò֤b nĕʼum-yĕhòwáh֙ wĕ⁠ʼal-ţé̇ẖa֣ţ yişĕ̂ráʼé֔l ki̇֠y hinĕ⁠ni֤y mwòşǐֽyʻà⁠ká֙ méֽ⁠ráẖ֔wòq wĕ⁠ʼeֽţ-zarĕʻà⁠ká֖ mé⁠ʼe֣reẕ şǐbĕyá֑⁠m wĕ⁠şá֧̌b yaʻàqò֛b wĕ⁠şá̌qa֥t wĕ⁠şǎʼàna֖n wĕ⁠ʼé֥yn maẖàriֽyd׃"],[30,11,"כִּֽי־אִתְּ⁠ךָ֥ אֲנִ֛י נְאֻם־יְהוָ֖ה לְ⁠הֽוֹשִׁיעֶ֑⁠ךָ כִּי֩ אֶעֱשֶׂ֨ה כָלָ֜ה בְּ⁠כָֽל־הַ⁠גּוֹיִ֣ם ׀ אֲשֶׁ֧ר הֲפִצוֹתִ֣י⁠ךָ שָּׁ֗ם אַ֤ךְ אֹֽתְ⁠ךָ֙ לֹֽא־אֶעֱשֶׂ֣ה כָלָ֔ה וְ⁠יִסַּרְתִּ֨י⁠ךָ֙ לַ⁠מִּשְׁפָּ֔ט וְ⁠נַקֵּ֖ה לֹ֥א אֲנַקֶּֽ⁠ךָּ׃פ","kiֽ̇y-ʼiţĕ̇⁠ká֥ ʼàni֛y nĕʼum-yĕhwá֖h lĕ⁠hֽwòşǐyʻe֑⁠ká ki̇y֩ ʼeʻèşê֨h kálá֜h bĕ̇⁠káֽl-ha⁠ġwòyi֣m ׀ ʼàşě֧r hàpiẕwòţi֣y⁠ká şá̇̌֗m ʼa֤kĕ ʼòֽţĕ⁠ká֙ lòֽʼ-ʼeʻèşê֣h kálá֔h wĕ⁠yisȧrĕţi̇֨y⁠ká֙ la⁠mi̇şĕ̌pá̇֔t wĕ⁠naqé֖̇h lò֥ʼ ʼànaqėֽ⁠ká̇׃p"],[30,12,"כִּ֣י כֹ֥ה אָמַ֛ר יְהוָ֖ה אָנ֣וּשׁ לְ⁠שִׁבְרֵ֑⁠ךְ נַחְלָ֖ה מַכָּתֵֽ⁠ךְ׃","ki֣̇y kò֥h ʼáma֛r yĕhwá֖h ʼán֣ẇş̌ lĕ⁠şǐbĕré֑⁠kĕ naẖĕlá֖h maká̇ţéֽ⁠kĕ׃"],[30,13,"אֵֽין־דָּ֥ן דִּינֵ֖⁠ךְ לְ⁠מָז֑וֹר רְפֻא֥וֹת תְּעָלָ֖ה אֵ֥ין לָֽ⁠ךְ׃","ʼéֽyn-dá֥̇n di̇yné֖⁠kĕ lĕ⁠máz֑wòr rĕpuʼ֥wòţ ţĕ̇ʻálá֖h ʼé֥yn láֽ⁠kĕ׃"],[30,14,"כָּל־מְאַהֲבַ֣יִ⁠ךְ שְׁכֵח֔וּ⁠ךְ אוֹתָ֖⁠ךְ לֹ֣א יִדְרֹ֑שׁוּ כִּי֩ מַכַּ֨ת אוֹיֵ֤ב הִכִּיתִי⁠ךְ֙ מוּסַ֣ר אַכְזָרִ֔י עַ֚ל רֹ֣ב עֲוֺנֵ֔⁠ךְ עָצְמ֖וּ חַטֹּאתָֽיִ⁠ךְ׃","ká̇l-mĕʼahàba֣yi⁠kĕ şĕ̌kéẖ֔ẇ⁠kĕ ʼwòţá֖⁠kĕ lò֣ʼ yidĕrò֑ş̌ẇ ki̇y֩ makȧ֨ţ ʼwòyé֤b hiki̇yţiy⁠kĕ֙ mẇsa֣r ʼakĕzári֔y ʻa֚l rò֣b ʻàwֺné֔⁠kĕ ʻáẕĕm֖ẇ ẖatò̇ʼţáֽyi⁠kĕ׃"],[30,15,"מַה־תִּזְעַק֙ עַל־שִׁבְרֵ֔⁠ךְ אָנ֖וּשׁ מַכְאֹבֵ֑⁠ךְ עַ֣ל ׀ רֹ֣ב עֲוֺנֵ֗⁠ךְ עָֽצְמוּ֙ חַטֹּאתַ֔יִ⁠ךְ עָשִׂ֥יתִי אֵ֖לֶּה לָֽ⁠ךְ׃","mah-ţi̇zĕʻaq֙ ʻal-şǐbĕré֔⁠kĕ ʼán֖ẇş̌ makĕʼòbé֑⁠kĕ ʻa֣l ׀ rò֣b ʻàwֺné֗⁠kĕ ʻáֽẕĕmẇ֙ ẖatò̇ʼţa֔yi⁠kĕ ʻáşî֥yţiy ʼé֖lėh láֽ⁠kĕ׃"],[30,16,"לָ⁠כֵ֞ן כָּל־אֹכְלַ֨יִ⁠ךְ֙ יֵאָכֵ֔לוּ וְ⁠כָל־צָרַ֥יִ⁠ךְ כֻּלָּ֖⁠ם בַּ⁠שְּׁבִ֣י יֵלֵ֑כוּ וְ⁠הָי֤וּ שֹׁאסַ֨יִ⁠ךְ֙ לִ⁠מְשִׁסָּ֔ה וְ⁠כָל־בֹּזְזַ֖יִ⁠ךְ אֶתֵּ֥ן לָ⁠בַֽז׃","lá⁠ké֞n ká̇l-ʼòkĕla֨yi⁠kĕ֙ yéʼáké֔lẇ wĕ⁠kál-ẕára֥yi⁠kĕ ku̇lá֖̇⁠m bȧ⁠şĕ̇̌bi֣y yélé֑kẇ wĕ⁠háy֤ẇ şò̌ʼsa֨yi⁠kĕ֙ li⁠mĕşǐsá̇֔h wĕ⁠kál-bò̇zĕza֖yi⁠kĕ ʼeţé֥̇n lá⁠baֽz׃"],[30,17,"כִּי֩ אַעֲלֶ֨ה אֲרֻכָ֥ה לָ֛⁠ךְ וּ⁠מִ⁠מַּכּוֹתַ֥יִ⁠ךְ אֶרְפָּאֵ֖⁠ךְ נְאֻם־יְהוָ֑ה כִּ֤י נִדָּחָה֙ קָ֣רְאוּ לָ֔⁠ךְ צִיּ֣וֹן הִ֔יא דֹּרֵ֖שׁ אֵ֥ין לָֽ⁠הּ׃ס","ki̇y֩ ʼaʻàle֨h ʼàruká֥h lá֛⁠kĕ ẇ⁠mi⁠mȧk̇wòţa֥yi⁠kĕ ʼerĕpá̇ʼé֖⁠kĕ nĕʼum-yĕhwá֑h ki֤̇y nidá̇ẖáh֙ qá֣rĕʼẇ lá֔⁠kĕ ẕiẏ֣wòn hi֔yʼ dò̇ré֖ş̌ ʼé֥yn láֽ⁠ḣ׃s"],[30,18,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה הִנְ⁠נִי־שָׁב֙ שְׁבוּת֙ אָהֳלֵ֣י יַֽעֲק֔וֹב וּ⁠מִשְׁכְּנֹתָ֖י⁠ו אֲרַחֵ֑ם וְ⁠נִבְנְתָ֥ה עִיר֙ עַל־תִּלָּ֔⁠הּ וְ⁠אַרְמ֖וֹן עַל־מִשְׁפָּט֥⁠וֹ יֵשֵֽׁב׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h hinĕ⁠niy-şá̌b֙ şĕ̌bẇţ֙ ʼáholé֣y yaֽʻàq֔wòb ẇ⁠mişĕ̌kĕ̇nòţá֖y⁠w ʼàraẖé֑m wĕ⁠nibĕnĕţá֥h ʻiyr֙ ʻal-ţi̇lá̇֔⁠ḣ wĕ⁠ʼarĕm֖wòn ʻal-mişĕ̌pá̇t֥⁠wò yéşéֽ̌b׃"],[30,19,"וְ⁠יָצָ֥א מֵ⁠הֶ֛ם תּוֹדָ֖ה וְ⁠ק֣וֹל מְשַׂחֲקִ֑ים וְ⁠הִרְבִּתִי⁠ם֙ וְ⁠לֹ֣א יִמְעָ֔טוּ וְ⁠הִכְבַּדְתִּ֖י⁠ם וְ⁠לֹ֥א יִצְעָֽרוּ׃","wĕ⁠yáẕá֥ʼ mé⁠he֛m ţ̇wòdá֖h wĕ⁠q֣wòl mĕşâẖàqi֑ym wĕ⁠hirĕbi̇ţiy⁠m֙ wĕ⁠lò֣ʼ yimĕʻá֔tẇ wĕ⁠hikĕbȧdĕţi֖̇y⁠m wĕ⁠lò֥ʼ yiẕĕʻáֽrẇ׃"],[30,20,"וְ⁠הָי֤וּ בָנָי⁠ו֙ כְּ⁠קֶ֔דֶם וַ⁠עֲדָת֖⁠וֹ לְ⁠פָנַ֣⁠י תִּכּ֑וֹן וּ⁠פָ֣קַדְתִּ֔י עַ֖ל כָּל־לֹחֲצָֽי⁠ו׃","wĕ⁠háy֤ẇ bánáy⁠w֙ kĕ̇⁠qe֔dem wa⁠ʻàdáţ֖⁠wò lĕ⁠pána֣⁠y ţi̇k֑̇wòn ẇ⁠pá֣qadĕţi̇֔y ʻa֖l ká̇l-lòẖàẕáֽy⁠w׃"],[30,21,"וְ⁠הָיָ֨ה אַדִּיר֜⁠וֹ מִמֶּ֗⁠נּוּ וּ⁠מֹֽשְׁל⁠וֹ֙ מִ⁠קִּרְבּ֣⁠וֹ יֵצֵ֔א וְ⁠הִקְרַבְתִּ֖י⁠ו וְ⁠נִגַּ֣שׁ אֵלָ֑⁠י כִּי֩ מִ֨י הוּא־זֶ֜ה עָרַ֧ב אֶת־לִבּ֛⁠וֹ לָ⁠גֶ֥שֶׁת אֵלַ֖⁠י נְאֻם־יְהוָֽה׃","wĕ⁠háyá֨h ʼadi̇yr֜⁠wò mimė֗⁠ṅẇ ẇ⁠mòֽşĕ̌l⁠wò֙ mi⁠qi̇rĕḃ֣⁠wò yéẕé֔ʼ wĕ⁠hiqĕrabĕţi֖̇y⁠w wĕ⁠nigȧ֣ş̌ ʼélá֑⁠y ki̇y֩ mi֨y hẇʼ-ze֜h ʻára֧b ʼeţ-liḃ֛⁠wò lá⁠ge֥şěţ ʼéla֖⁠y nĕʼum-yĕhwáֽh׃"],[30,22,"וִ⁠הְיִ֥יתֶם לִ֖⁠י לְ⁠עָ֑ם וְ⁠אָ֣נֹכִ֔י אֶהְיֶ֥ה לָ⁠כֶ֖ם לֵ⁠אלֹהִֽים׃ס","wi⁠hĕyi֥yţem li֖⁠y lĕ⁠ʻá֑m wĕ⁠ʼá֣nòki֔y ʼehĕye֥h lá⁠ke֖m lé⁠ʼlòhiֽym׃s"],[30,23,"הִנֵּ֣ה ׀ סַעֲרַ֣ת יְהוָ֗ה חֵמָה֙ יָֽצְאָ֔ה סַ֖עַר מִתְגּוֹרֵ֑ר עַ֛ל רֹ֥אשׁ רְשָׁעִ֖ים יָחֽוּל׃","hiné֣̇h ׀ saʻàra֣ţ yĕhwá֗h ẖémáh֙ yáֽẕĕʼá֔h sa֖ʻar miţĕġwòré֑r ʻa֛l rò֥ʼş̌ rĕşá̌ʻi֖ym yáẖֽẇl׃"],[30,24,"לֹ֣א יָשׁ֗וּב חֲרוֹן֙ אַף־יְהוָ֔ה עַד־עֲשֹׂת֥⁠וֹ וְ⁠עַד־הֲקִימ֖⁠וֹ מְזִמּ֣וֹת לִבּ֑⁠וֹ בְּ⁠אַחֲרִ֥ית הַ⁠יָּמִ֖ים תִּתְבּ֥וֹנְנוּ בָֽ⁠הּ׃","lò֣ʼ yáş̌֗ẇb ẖàrwòn֙ ʼap-yĕhwá֔h ʻad-ʻàşò̂ţ֥⁠wò wĕ⁠ʻad-hàqiym֖⁠wò mĕziṁ֣wòţ liḃ֑⁠wò bĕ̇⁠ʼaẖàri֥yţ ha⁠yá̇mi֖ym ţi̇ţĕḃ֥wònĕnẇ báֽ⁠ḣ׃"],[31,1,"בָּ⁠עֵ֤ת הַ⁠הִיא֙ נְאֻם־יְהוָ֔ה אֶֽהְיֶה֙ לֵֽ⁠אלֹהִ֔ים לְ⁠כֹ֖ל מִשְׁפְּח֣וֹת יִשְׂרָאֵ֑ל וְ⁠הֵ֖מָּה יִֽהְיוּ־לִ֥⁠י לְ⁠עָֽם׃ס","bá̇⁠ʻé֤ţ ha⁠hiyʼ֙ nĕʼum-yĕhwá֔h ʼeֽhĕyeh֙ léֽ⁠ʼlòhi֔ym lĕ⁠kò֖l mişĕ̌pĕ̇ẖ֣wòţ yişĕ̂ráʼé֑l wĕ⁠hé֖má̇h yiֽhĕyẇ-li֥⁠y lĕ⁠ʻáֽm׃s"],[31,2,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה מָצָ֥א חֵן֙ בַּ⁠מִּדְבָּ֔ר עַ֖ם שְׂרִ֣ידֵי חָ֑רֶב הָל֥וֹךְ לְ⁠הַרְגִּיע֖⁠וֹ יִשְׂרָאֵֽל׃","kò֚̇h ʼáma֣r yĕhwá֔h máẕá֥ʼ ẖén֙ bȧ⁠mi̇dĕbá̇֔r ʻa֖m şĕ̂ri֣ydéy ẖá֑reb hál֥wòkĕ lĕ⁠harĕgi̇yʻ֖⁠wò yişĕ̂ráʼéֽl׃"],[31,3,"מֵ⁠רָח֕וֹק יְהוָ֖ה נִרְאָ֣ה לִ֑⁠י וְ⁠אַהֲבַ֤ת עוֹלָם֙ אֲהַבְתִּ֔י⁠ךְ עַל־כֵּ֖ן מְשַׁכְתִּ֥י⁠ךְ חָֽסֶד׃","mé⁠ráẖ֕wòq yĕhwá֖h nirĕʼá֣h li֑⁠y wĕ⁠ʼahàba֤ţ ʻwòlám֙ ʼàhabĕţi̇֔y⁠kĕ ʻal-ké֖̇n mĕşǎkĕţi֥̇y⁠kĕ ẖáֽsed׃"],[31,4,"ע֤וֹד אֶבְנֵ⁠ךְ֙ וְֽ⁠נִבְנֵ֔ית בְּתוּלַ֖ת יִשְׂרָאֵ֑ל ע֚וֹד תַּעְדִּ֣י תֻפַּ֔יִ⁠ךְ וְ⁠יָצָ֖את בִּ⁠מְח֥וֹל מְשַׂחֲקִֽים׃","ʻ֤wòd ʼebĕné⁠kĕ֙ wĕֽ⁠nibĕné֔yţ bĕ̇ţẇla֖ţ yişĕ̂ráʼé֑l ʻ֚wòd ţȧʻĕdi֣̇y ţupȧ֔yi⁠kĕ wĕ⁠yáẕá֖ʼţ bi̇⁠mĕẖ֥wòl mĕşâẖàqiֽym׃"],[31,5,"ע֚וֹד תִּטְּעִ֣י כְרָמִ֔ים בְּ⁠הָרֵ֖י שֹֽׁמְר֑וֹן נָטְע֥וּ נֹטְעִ֖ים וְ⁠חִלֵּֽלוּ׃","ʻ֚wòd ţi̇tĕ̇ʻi֣y kĕrámi֔ym bĕ̇⁠háré֖y şòֽ̌mĕr֑wòn nátĕʻ֥ẇ nòtĕʻi֖ym wĕ⁠ẖiléֽ̇lẇ׃"],[31,6,"כִּ֣י יֶשׁ־י֔וֹם קָרְא֥וּ נֹצְרִ֖ים בְּ⁠הַ֣ר אֶפְרָ֑יִם ק֚וּמוּ וְ⁠נַעֲלֶ֣ה צִיּ֔וֹן אֶל־יְהוָ֖ה אֱלֹהֵֽי⁠נוּ׃פ","ki֣̇y yeş̌-y֔wòm qárĕʼ֥ẇ nòẕĕri֖ym bĕ̇⁠ha֣r ʼepĕrá֑yim q֚ẇmẇ wĕ⁠naʻàle֣h ẕiẏ֔wòn ʼel-yĕhwá֖h ʼèlòhéֽy⁠nẇ׃p"],[31,7,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה רָנּ֤וּ לְ⁠יַֽעֲקֹב֙ שִׂמְחָ֔ה וְ⁠צַהֲל֖וּ בְּ⁠רֹ֣אשׁ הַ⁠גּוֹיִ֑ם הַשְׁמִ֤יעוּ הַֽלְלוּ֙ וְ⁠אִמְר֔וּ הוֹשַׁ֤ע יְהוָה֙ אֶֽת־עַמְּ⁠ךָ֔ אֵ֖ת שְׁאֵרִ֥ית יִשְׂרָאֵֽל׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h ráṅ֤ẇ lĕ⁠yaֽʻàqòb֙ şîmĕẖá֔h wĕ⁠ẕahàl֖ẇ bĕ̇⁠rò֣ʼş̌ ha⁠ġwòyi֑m haşĕ̌mi֤yʻẇ haֽlĕlẇ֙ wĕ⁠ʼimĕr֔ẇ hwòşǎ֤ʻ yĕhwáh֙ ʼeֽţ-ʻamĕ̇⁠ká֔ ʼé֖ţ şĕ̌ʼéri֥yţ yişĕ̂ráʼéֽl׃"],[31,8,"הִנְ⁠נִי֩ מֵבִ֨יא אוֹתָ֜⁠ם מֵ⁠אֶ֣רֶץ צָפ֗וֹן וְ⁠קִבַּצְתִּי⁠ם֮ מִ⁠יַּרְכְּתֵי־אָרֶץ֒ בָּ֚⁠ם עִוֵּ֣ר וּ⁠פִסֵּ֔חַ הָרָ֥ה וְ⁠יֹלֶ֖דֶת יַחְדָּ֑ו קָהָ֥ל גָּד֖וֹל יָשׁ֥וּבוּ הֵֽנָּה׃","hinĕ⁠niy֩ mébi֨yʼ ʼwòţá֜⁠m mé⁠ʼe֣reẕ ẕáp֗wòn wĕ⁠qibȧẕĕţi̇y⁠m֮ mi⁠yȧrĕkĕ̇ţéy-ʼáreẕ֒ bá֚̇⁠m ʻiwé֣̇r ẇ⁠pisé̇֔ẖa hárá֥h wĕ⁠yòle֖deţ yaẖĕdá֑̇w qáhá֥l gá̇d֖wòl yáş֥̌ẇbẇ héֽná̇h׃"],[31,9,"בִּ⁠בְכִ֣י יָבֹ֗אוּ וּֽ⁠בְ⁠תַחֲנוּנִים֮ אֽוֹבִילֵ⁠ם֒ אֽוֹלִיכֵ⁠ם֙ אֶל־נַ֣חֲלֵי מַ֔יִם בְּ⁠דֶ֣רֶךְ יָשָׁ֔ר לֹ֥א יִכָּשְׁל֖וּ בָּ֑⁠הּ כִּֽי־הָיִ֤יתִי לְ⁠יִשְׂרָאֵל֙ לְ⁠אָ֔ב וְ⁠אֶפְרַ֖יִם בְּכֹ֥רִ⁠י הֽוּא׃ס","bi̇⁠bĕki֣y yábò֗ʼẇ ẇֽ⁠bĕ⁠ţaẖànẇniym֮ ʼֽwòbiylé⁠m֒ ʼֽwòliyké⁠m֙ ʼel-na֣ẖàléy ma֔yim bĕ̇⁠de֣rekĕ yáşá̌֔r lò֥ʼ yiká̇şĕ̌l֖ẇ bá֑̇⁠ḣ kiֽ̇y-háyi֤yţiy lĕ⁠yişĕ̂ráʼél֙ lĕ⁠ʼá֔b wĕ⁠ʼepĕra֖yim bĕ̇kò֥ri⁠y hֽẇʼ׃s"],[31,10,"שִׁמְע֤וּ דְבַר־יְהוָה֙ גּוֹיִ֔ם וְ⁠הַגִּ֥ידוּ בָ⁠אִיִּ֖ים מִ⁠מֶּרְחָ֑ק וְ⁠אִמְר֗וּ מְזָרֵ֤ה יִשְׂרָאֵל֙ יְקַבְּצֶ֔⁠נּוּ וּ⁠שְׁמָר֖⁠וֹ כְּ⁠רֹעֶ֥ה עֶדְרֽ⁠וֹ׃","şǐmĕʻ֤ẇ dĕbar-yĕhwáh֙ ġwòyi֔m wĕ⁠hagi֥̇ydẇ bá⁠ʼiyi֖̇ym mi⁠mėrĕẖá֑q wĕ⁠ʼimĕr֗ẇ mĕzáré֤h yişĕ̂ráʼél֙ yĕqabĕ̇ẕe֔⁠ṅẇ ẇ⁠şĕ̌már֖⁠wò kĕ̇⁠ròʻe֥h ʻedĕrֽ⁠wò׃"],[31,11,"כִּֽי־פָדָ֥ה יְהוָ֖ה אֶֽת־יַעֲקֹ֑ב וּ⁠גְאָל֕⁠וֹ מִ⁠יַּ֖ד חָזָ֥ק מִמֶּֽ⁠נּוּ׃","kiֽ̇y-pádá֥h yĕhwá֖h ʼeֽţ-yaʻàqò֑b ẇ⁠gĕʼál֕⁠wò mi⁠yȧ֖d ẖázá֥q mimėֽ⁠ṅẇ׃"],[31,12,"וּ⁠בָאוּ֮ וְ⁠רִנְּנ֣וּ בִ⁠מְרוֹם־צִיּוֹן֒ וְ⁠נָהֲר֞וּ אֶל־ט֣וּב יְהוָ֗ה עַל־דָּגָן֙ וְ⁠עַל־תִּירֹ֣שׁ וְ⁠עַל־יִצְהָ֔ר וְ⁠עַל־בְּנֵי־צֹ֖אן וּ⁠בָקָ֑ר וְ⁠הָיְתָ֤ה נַפְשָׁ⁠ם֙ כְּ⁠גַ֣ן רָוֶ֔ה וְ⁠לֹא־יוֹסִ֥יפוּ לְ⁠דַאֲבָ֖ה עֽוֹד׃","ẇ⁠báʼẇ֮ wĕ⁠rinĕ̇n֣ẇ bi⁠mĕrwòm-ẕiẏwòn֒ wĕ⁠náhàr֞ẇ ʼel-t֣ẇb yĕhwá֗h ʻal-dá̇gán֙ wĕ⁠ʻal-ţi̇yrò֣ş̌ wĕ⁠ʻal-yiẕĕhá֔r wĕ⁠ʻal-bĕ̇néy-ẕò֖ʼn ẇ⁠báqá֑r wĕ⁠háyĕţá֤h napĕşá̌⁠m֙ kĕ̇⁠ga֣n ráwe֔h wĕ⁠lòʼ-ywòsi֥ypẇ lĕ⁠daʼàbá֖h ʻֽwòd׃"],[31,13,"אָ֣ז תִּשְׂמַ֤ח בְּתוּלָה֙ בְּ⁠מָח֔וֹל וּ⁠בַחֻרִ֥ים וּ⁠זְקֵנִ֖ים יַחְדָּ֑ו וְ⁠הָפַכְתִּ֨י אֶבְלָ֤⁠ם לְ⁠שָׂשׂוֹן֙ וְ⁠נִ֣חַמְתִּ֔י⁠ם וְ⁠שִׂמַּחְתִּ֖י⁠ם מִ⁠יגוֹנָֽ⁠ם׃","ʼá֣z ţi̇şĕ̂ma֤ẖ bĕ̇ţẇláh֙ bĕ̇⁠máẖ֔wòl ẇ⁠baẖuri֥ym ẇ⁠zĕqéni֖ym yaẖĕdá֑̇w wĕ⁠hápakĕţi̇֨y ʼebĕlá֤⁠m lĕ⁠şá̂ş̂wòn֙ wĕ⁠ni֣ẖamĕţi̇֔y⁠m wĕ⁠şîmȧẖĕţi֖̇y⁠m mi⁠ygwònáֽ⁠m׃"],[31,14,"וְ⁠רִוֵּיתִ֛י נֶ֥פֶשׁ הַ⁠כֹּהֲנִ֖ים דָּ֑שֶׁן וְ⁠עַמִּ֛⁠י אֶת־טוּבִ֥⁠י יִשְׂבָּ֖עוּ נְאֻם־יְהוָֽה׃ס","wĕ⁠riwé̇yţi֛y ne֥peş̌ ha⁠kò̇hàni֖ym dá֑̇şěn wĕ⁠ʻami֛̇⁠y ʼeţ-tẇbi֥⁠y yişĕ̂bá֖̇ʻẇ nĕʼum-yĕhwáֽh׃s"],[31,15,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה ק֣וֹל בְּ⁠רָמָ֤ה נִשְׁמָע֙ נְהִי֙ בְּכִ֣י תַמְרוּרִ֔ים רָחֵ֖ל מְבַכָּ֣ה עַל־בָּנֶ֑י⁠הָ מֵאֲנָ֛ה לְ⁠הִנָּחֵ֥ם עַל־בָּנֶ֖י⁠הָ כִּ֥י אֵינֶֽ⁠נּוּ׃ס","kò֣̇h ׀ ʼáma֣r yĕhwá֗h q֣wòl bĕ̇⁠rámá֤h nişĕ̌máʻ֙ nĕhiy֙ bĕ̇ki֣y ţamĕrẇri֔ym ráẖé֖l mĕbaká֣̇h ʻal-bá̇ne֑y⁠há méʼàná֛h lĕ⁠hiná̇ẖé֥m ʻal-bá̇ne֖y⁠há ki֥̇y ʼéyneֽ⁠ṅẇ׃s"],[31,16,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה מִנְעִ֤י קוֹלֵ⁠ךְ֙ מִ⁠בֶּ֔כִי וְ⁠עֵינַ֖יִ⁠ךְ מִ⁠דִּמְעָ֑ה כִּי֩ יֵ֨שׁ שָׂכָ֤ר לִ⁠פְעֻלָּתֵ⁠ךְ֙ נְאֻם־יְהוָ֔ה וְ⁠שָׁ֖בוּ מֵ⁠אֶ֥רֶץ אוֹיֵֽב׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h minĕʻi֤y qwòlé⁠kĕ֙ mi⁠bė֔kiy wĕ⁠ʻéyna֖yi⁠kĕ mi⁠di̇mĕʻá֑h ki̇y֩ yé֨ş̌ şá̂ká֤r li⁠pĕʻulá̇ţé⁠kĕ֙ nĕʼum-yĕhwá֔h wĕ⁠şá֖̌bẇ mé⁠ʼe֥reẕ ʼwòyéֽb׃"],[31,17,"וְ⁠יֵשׁ־תִּקְוָ֥ה לְ⁠אַחֲרִיתֵ֖⁠ךְ נְאֻם־יְהוָ֑ה וְ⁠שָׁ֥בוּ בָנִ֖ים לִ⁠גְבוּלָֽ⁠ם׃ס","wĕ⁠yéş̌-ţi̇qĕwá֥h lĕ⁠ʼaẖàriyţé֖⁠kĕ nĕʼum-yĕhwá֑h wĕ⁠şá֥̌bẇ báni֖ym li⁠gĕbẇláֽ⁠m׃s"],[31,18,"שָׁמ֣וֹעַ שָׁמַ֗עְתִּי אֶפְרַ֨יִם֙ מִתְנוֹדֵ֔ד יִסַּרְתַּ֨⁠נִי֙ וָֽ⁠אִוָּסֵ֔ר כְּ⁠עֵ֖גֶל לֹ֣א לֻמָּ֑ד הֲשִׁיבֵ֣⁠נִי וְ⁠אָשׁ֔וּבָה כִּ֥י אַתָּ֖ה יְהוָ֥ה אֱלֹהָֽ⁠י׃","şá̌m֣wòʻa şá̌ma֗ʻĕţi̇y ʼepĕra֨yim֙ miţĕnwòdé֔d yisȧrĕţȧ֨⁠niy֙ wáֽ⁠ʼiwá̇sé֔r kĕ̇⁠ʻé֖gel lò֣ʼ lumá֑̇d hàşǐybé֣⁠niy wĕ⁠ʼáş̌֔ẇbáh ki֥̇y ʼaţá֖̇h yĕhwá֥h ʼèlòháֽ⁠y׃"],[31,19,"כִּֽי־אַחֲרֵ֤י שׁוּבִ⁠י֙ נִחַ֔מְתִּי וְ⁠אַֽחֲרֵי֙ הִוָּ֣דְעִ֔⁠י סָפַ֖קְתִּי עַל־יָרֵ֑ךְ בֹּ֚שְׁתִּי וְ⁠גַם־נִכְלַ֔מְתִּי כִּ֥י נָשָׂ֖אתִי חֶרְפַּ֥ת נְעוּרָֽ⁠י׃","kiֽ̇y-ʼaẖàré֤y ş̌ẇbi⁠y֙ niẖa֔mĕţi̇y wĕ⁠ʼaֽẖàréy֙ hiwá֣̇dĕʻi֔⁠y sápa֖qĕţi̇y ʻal-yáré֑kĕ bò֚̇şĕ̌ţi̇y wĕ⁠gam-nikĕla֔mĕţi̇y ki֥̇y náşá֖̂ʼţiy ẖerĕpȧ֥ţ nĕʻẇráֽ⁠y׃"],[31,20,"הֲ⁠בֵן֩ יַקִּ֨יר לִ֜⁠י אֶפְרַ֗יִם אִ֚ם יֶ֣לֶד שַׁעֲשֻׁעִ֔ים כִּֽי־מִ⁠דֵּ֤י דַבְּרִ⁠י֙ בּ֔⁠וֹ זָכֹ֥ר אֶזְכְּרֶ֖⁠נּוּ ע֑וֹד עַל־כֵּ֗ן הָמ֤וּ מֵעַ⁠י֙ ל֔⁠וֹ רַחֵ֥ם אֲֽרַחֲמֶ֖⁠נּוּ נְאֻם־יְהוָֽה׃ס","hà⁠bén֩ yaqi̇֨yr li֜⁠y ʼepĕra֗yim ʼi֚m ye֣led şǎʻàşǔʻi֔ym kiֽ̇y-mi⁠dé֤̇y dabĕ̇ri⁠y֙ ḃ֔⁠wò zákò֥r ʼezĕkĕ̇re֖⁠ṅẇ ʻ֑wòd ʻal-ké̇֗n hám֤ẇ méʻa⁠y֙ l֔⁠wò raẖé֥m ʼàֽraẖàme֖⁠ṅẇ nĕʼum-yĕhwáֽh׃s"],[31,21,"הַצִּ֧יבִי לָ֣⁠ךְ צִיֻּנִ֗ים שִׂ֤מִי לָ⁠ךְ֙ תַּמְרוּרִ֔ים שִׁ֣תִי לִבֵּ֔⁠ךְ לַֽ⁠מְסִלָּ֖ה דֶּ֣רֶךְ הלכתי שׁ֚וּבִי בְּתוּלַ֣ת יִשְׂרָאֵ֔ל שֻׁ֖בִי אֶל־עָרַ֥יִ⁠ךְ אֵֽלֶּה׃","haẕi֧̇ybiy lá֣⁠kĕ ẕiyu̇ni֗ym şî֤miy lá⁠kĕ֙ ţȧmĕrẇri֔ym şǐ֣ţiy libé̇֔⁠kĕ laֽ⁠mĕsilá֖̇h dė֣rekĕ hlkţy ş֚̌ẇbiy bĕ̇ţẇla֣ţ yişĕ̂ráʼé֔l şǔ֖biy ʼel-ʻára֥yi⁠kĕ ʼéֽlėh׃"],[31,22,"עַד־מָתַי֙ תִּתְחַמָּקִ֔י⁠ן הַ⁠בַּ֖ת הַ⁠שּֽׁוֹבֵבָ֑ה כִּֽי־בָרָ֨א יְהוָ֤ה חֲדָשָׁה֙ בָּ⁠אָ֔רֶץ נְקֵבָ֖ה תְּס֥וֹבֵֽב גָּֽבֶר׃ס","ʻad-máţay֙ ţi̇ţĕẖamá̇qi֔y⁠n ha⁠bȧ֖ţ ha⁠şֽ̇̌wòbébá֑h kiֽ̇y-bárá֨ʼ yĕhwá֤h ẖàdáşá̌h֙ bá̇⁠ʼá֔reẕ nĕqébá֖h ţĕ̇s֥wòbéֽb gáֽ̇ber׃s"],[31,23,"כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל ע֣וֹד יֹאמְר֞וּ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה בְּ⁠אֶ֤רֶץ יְהוּדָה֙ וּ⁠בְ⁠עָרָ֔י⁠ו בְּ⁠שׁוּבִ֖⁠י אֶת־שְׁבוּתָ֑⁠ם יְבָרֶכְ⁠ךָ֧ יְהוָ֛ה נְוֵה־צֶ֖דֶק הַ֥ר הַ⁠קֹּֽדֶשׁ׃","kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʻ֣wòd yòʼmĕr֞ẇ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h bĕ̇⁠ʼe֤reẕ yĕhẇdáh֙ ẇ⁠bĕ⁠ʻárá֔y⁠w bĕ̇⁠ş̌ẇbi֖⁠y ʼeţ-şĕ̌bẇţá֑⁠m yĕbárekĕ⁠ká֧ yĕhwá֛h nĕwéh-ẕe֖deq ha֥r ha⁠qòֽ̇deş̌׃"],[31,24,"וְ⁠יָ֥שְׁבוּ בָ֛⁠הּ יְהוּדָ֥ה וְ⁠כָל־עָרָ֖י⁠ו יַחְדָּ֑ו אִכָּרִ֕ים וְ⁠נָסְע֖וּ בַּ⁠עֵֽדֶר׃","wĕ⁠yá֥şĕ̌bẇ bá֛⁠ḣ yĕhẇdá֥h wĕ⁠kál-ʻárá֖y⁠w yaẖĕdá֑̇w ʼiká̇ri֕ym wĕ⁠násĕʻ֖ẇ bȧ⁠ʻéֽder׃"],[31,25,"כִּ֥י הִרְוֵ֖יתִי נֶ֣פֶשׁ עֲיֵפָ֑ה וְ⁠כָל־נֶ֥פֶשׁ דָּאֲבָ֖ה מִלֵּֽאתִי׃","ki֥̇y hirĕwé֖yţiy ne֣peş̌ ʻàyépá֑h wĕ⁠kál-ne֥peş̌ dá̇ʼàbá֖h miléֽ̇ʼţiy׃"],[31,26,"עַל־זֹ֖את הֱקִיצֹ֣תִי וָ⁠אֶרְאֶ֑ה וּ⁠שְׁנָתִ֖⁠י עָ֥רְבָה לִּֽ⁠י׃ס","ʻal-zò֖ʼţ hèqiyẕò֣ţiy wá⁠ʼerĕʼe֑h ẇ⁠şĕ̌náţi֖⁠y ʻá֥rĕbáh liֽ̇⁠y׃s"],[31,27,"הִנֵּ֛ה יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וְ⁠זָרַעְתִּ֗י אֶת־בֵּ֤ית יִשְׂרָאֵל֙ וְ⁠אֶת־בֵּ֣ית יְהוּדָ֔ה זֶ֥רַע אָדָ֖ם וְ⁠זֶ֥רַע בְּהֵמָֽה׃","hiné֛̇h yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h wĕ⁠záraʻĕţi̇֗y ʼeţ-bé֤̇yţ yişĕ̂ráʼél֙ wĕ⁠ʼeţ-bé֣̇yţ yĕhẇdá֔h ze֥raʻ ʼádá֖m wĕ⁠ze֥raʻ bĕ̇hémáֽh׃"],[31,28,"וְ⁠הָיָ֞ה כַּ⁠אֲשֶׁ֧ר שָׁקַ֣דְתִּי עֲלֵי⁠הֶ֗ם לִ⁠נְת֧וֹשׁ וְ⁠לִ⁠נְת֛וֹץ וְ⁠לַ⁠הֲרֹ֖ס וּ⁠לְ⁠הַאֲבִ֣יד וּ⁠לְ⁠הָרֵ֑עַ כֵּ֣ן אֶשְׁקֹ֧ד עֲלֵי⁠הֶ֛ם לִ⁠בְנ֥וֹת וְ⁠לִ⁠נְט֖וֹעַ נְאֻם־יְהוָֽה׃","wĕ⁠háyá֞h kȧ⁠ʼàşě֧r şá̌qa֣dĕţi̇y ʻàléy⁠he֗m li⁠nĕţ֧wòş̌ wĕ⁠li⁠nĕţ֛wòẕ wĕ⁠la⁠hàrò֖s ẇ⁠lĕ⁠haʼàbi֣yd ẇ⁠lĕ⁠háré֑ʻa ké֣̇n ʼeşĕ̌qò֧d ʻàléy⁠he֛m li⁠bĕn֥wòţ wĕ⁠li⁠nĕt֖wòʻa nĕʼum-yĕhwáֽh׃"],[31,29,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם לֹא־יֹאמְר֣וּ ע֔וֹד אָב֖וֹת אָ֣כְלוּ בֹ֑סֶר וְ⁠שִׁנֵּ֥י בָנִ֖ים תִּקְהֶֽינָה׃","bȧ⁠yá̇mi֣ym há⁠hé֔m lòʼ-yòʼmĕr֣ẇ ʻ֔wòd ʼáb֖wòţ ʼá֣kĕlẇ bò֑ser wĕ⁠şǐné֥̇y báni֖ym ţi̇qĕheֽynáh׃"],[31,30,"כִּ֛י אִם־אִ֥ישׁ בַּ⁠עֲוֺנ֖⁠וֹ יָמ֑וּת כָּל־הָֽ⁠אָדָ֛ם הָ⁠אֹכֵ֥ל הַ⁠בֹּ֖סֶר תִּקְהֶ֥ינָה שִׁנָּֽי⁠ו׃ס","ki֛̇y ʼim-ʼi֥yş̌ bȧ⁠ʻàwֺn֖⁠wò yám֑ẇţ ká̇l-háֽ⁠ʼádá֛m há⁠ʼòké֥l ha⁠bò֖̇ser ţi̇qĕhe֥ynáh şǐnáֽ̇y⁠w׃s"],[31,31,"הִנֵּ֛ה יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וְ⁠כָרַתִּ֗י אֶת־בֵּ֧ית יִשְׂרָאֵ֛ל וְ⁠אֶת־בֵּ֥ית יְהוּדָ֖ה בְּרִ֥ית חֲדָשָֽׁה׃","hiné֛̇h yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h wĕ⁠káraţi̇֗y ʼeţ-bé֧̇yţ yişĕ̂ráʼé֛l wĕ⁠ʼeţ-bé֥̇yţ yĕhẇdá֖h bĕ̇ri֥yţ ẖàdáşáֽ̌h׃"],[31,32,"לֹ֣א כַ⁠בְּרִ֗ית אֲשֶׁ֤ר כָּרַ֨תִּי֙ אֶת־אֲבוֹתָ֔⁠ם בְּ⁠יוֹם֙ הֶחֱזִיקִ֣⁠י בְ⁠יָדָ֔⁠ם לְ⁠הוֹצִיאָ֖⁠ם מֵ⁠אֶ֖רֶץ מִצְרָ֑יִם אֲשֶׁר־הֵ֜מָּה הֵפֵ֣רוּ אֶת־בְּרִיתִ֗⁠י וְ⁠אָנֹכִ֛י בָּעַ֥לְתִּי בָ֖⁠ם נְאֻם־יְהוָֽה׃","lò֣ʼ ka⁠bĕ̇ri֗yţ ʼàşě֤r ká̇ra֨ţi̇y֙ ʼeţ-ʼàbwòţá֔⁠m bĕ̇⁠ywòm֙ heẖèziyqi֣⁠y bĕ⁠yádá֔⁠m lĕ⁠hwòẕiyʼá֖⁠m mé⁠ʼe֖reẕ miẕĕrá֑yim ʼàşěr-hé֜má̇h hépé֣rẇ ʼeţ-bĕ̇riyţi֗⁠y wĕ⁠ʼánòki֛y bá̇ʻa֥lĕţi̇y bá֖⁠m nĕʼum-yĕhwáֽh׃"],[31,33,"כִּ֣י זֹ֣את הַ⁠בְּרִ֡ית אֲשֶׁ֣ר אֶכְרֹת֩ אֶת־בֵּ֨ית יִשְׂרָאֵ֜ל אַחֲרֵ֨י הַ⁠יָּמִ֤ים הָ⁠הֵם֙ נְאֻם־יְהוָ֔ה נָתַ֤תִּי אֶת־תּֽוֹרָתִ⁠י֙ בְּ⁠קִרְבָּ֔⁠ם וְ⁠עַל־לִבָּ֖⁠ם אֶכְתֲּבֶ֑⁠נָּה וְ⁠הָיִ֤יתִי לָ⁠הֶם֙ לֵֽ⁠אלֹהִ֔ים וְ⁠הֵ֖מָּה יִֽהְיוּ־לִ֥⁠י לְ⁠עָֽם׃","ki֣̇y zò֣ʼţ ha⁠bĕ̇ri֡yţ ʼàşě֣r ʼekĕròţ֩ ʼeţ-bé̇֨yţ yişĕ̂ráʼé֜l ʼaẖàré֨y ha⁠yá̇mi֤ym há⁠hém֙ nĕʼum-yĕhwá֔h náţa֤ţi̇y ʼeţ-ţֽ̇wòráţi⁠y֙ bĕ̇⁠qirĕbá̇֔⁠m wĕ⁠ʻal-libá֖̇⁠m ʼekĕţà̇be֑⁠ná̇h wĕ⁠háyi֤yţiy lá⁠hem֙ léֽ⁠ʼlòhi֔ym wĕ⁠hé֖má̇h yiֽhĕyẇ-li֥⁠y lĕ⁠ʻáֽm׃"],[31,34,"וְ⁠לֹ֧א יְלַמְּד֣וּ ע֗וֹד אִ֣ישׁ אֶת־רֵעֵ֜⁠הוּ וְ⁠אִ֤ישׁ אֶת־אָחִי⁠ו֙ לֵ⁠אמֹ֔ר דְּע֖וּ אֶת־יְהוָ֑ה כִּֽי־כוּלָּ⁠ם֩ יֵדְע֨וּ אוֹתִ֜⁠י לְ⁠מִ⁠קְטַנָּ֤⁠ם וְ⁠עַד־גְּדוֹלָ⁠ם֙ נְאֻם־יְהוָ֔ה כִּ֤י אֶסְלַח֙ לַֽ⁠עֲוֺנָ֔⁠ם וּ⁠לְ⁠חַטָּאתָ֖⁠ם לֹ֥א אֶזְכָּר־עֽוֹד׃ס","wĕ⁠lò֧ʼ yĕlamĕ̇d֣ẇ ʻ֗wòd ʼi֣yş̌ ʼeţ-réʻé֜⁠hẇ wĕ⁠ʼi֤yş̌ ʼeţ-ʼáẖiy⁠w֙ lé⁠ʼmò֔r dĕ̇ʻ֖ẇ ʼeţ-yĕhwá֑h kiֽ̇y-kẇlá̇⁠m֩ yédĕʻ֨ẇ ʼwòţi֜⁠y lĕ⁠mi⁠qĕtaná֤̇⁠m wĕ⁠ʻad-gĕ̇dwòlá⁠m֙ nĕʼum-yĕhwá֔h ki֤̇y ʼesĕlaẖ֙ laֽ⁠ʻàwֺná֔⁠m ẇ⁠lĕ⁠ẖatá̇ʼţá֖⁠m lò֥ʼ ʼezĕká̇r-ʻֽwòd׃s"],[31,35,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה נֹתֵ֥ן שֶׁ֨מֶשׁ֙ לְ⁠א֣וֹר יוֹמָ֔ם חֻקֹּ֛ת יָרֵ֥חַ וְ⁠כוֹכָבִ֖ים לְ⁠א֣וֹר לָ֑יְלָה רֹגַ֤ע הַ⁠יָּם֙ וַ⁠יֶּהֱמ֣וּ גַלָּ֔י⁠ו יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h nòţé֥n şě֨meş̌֙ lĕ⁠ʼ֣wòr ywòmá֔m ẖuqò֛̇ţ yáré֥ẖa wĕ⁠kwòkábi֖ym lĕ⁠ʼ֣wòr lá֑yĕláh ròga֤ʻ ha⁠yá̇m֙ wa⁠yėhèm֣ẇ galá̇֔y⁠w yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃"],[31,36,"אִם־יָמֻ֜שׁוּ הַ⁠חֻקִּ֥ים הָ⁠אֵ֛לֶּה מִ⁠לְּ⁠פָנַ֖⁠י נְאֻם־יְהוָ֑ה גַּם֩ זֶ֨רַע יִשְׂרָאֵ֜ל יִשְׁבְּת֗וּ מִֽ⁠הְי֥וֹת גּ֛וֹי לְ⁠פָנַ֖⁠י כָּל־הַ⁠יָּמִֽים׃ס","ʼim-yámu֜ş̌ẇ ha⁠ẖuqi֥̇ym há⁠ʼé֛lėh mi⁠lĕ̇⁠pána֖⁠y nĕʼum-yĕhwá֑h gȧm֩ ze֨raʻ yişĕ̂ráʼé֜l yişĕ̌bĕ̇ţ֗ẇ miֽ⁠hĕy֥wòţ ġ֛wòy lĕ⁠pána֖⁠y ká̇l-ha⁠yá̇miֽym׃s"],[31,37,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אִם־יִמַּ֤דּוּ שָׁמַ֨יִם֙ מִ⁠לְ⁠מַ֔עְלָ⁠ה וְ⁠יֵחָקְר֥וּ מֽוֹסְדֵי־אֶ֖רֶץ לְ⁠מָ֑טָּה גַּם־אֲנִ֞י אֶמְאַ֨ס בְּ⁠כָל־זֶ֧רַע יִשְׂרָאֵ֛ל עַֽל־כָּל־אֲשֶׁ֥ר עָשׂ֖וּ נְאֻם־יְהוָֽה׃ס","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼim-yimȧ֤ḋẇ şá̌ma֨yim֙ mi⁠lĕ⁠ma֔ʻĕlá⁠h wĕ⁠yéẖáqĕr֥ẇ mֽwòsĕdéy-ʼe֖reẕ lĕ⁠má֑tá̇h gȧm-ʼàni֞y ʼemĕʼa֨s bĕ̇⁠kál-ze֧raʻ yişĕ̂ráʼé֛l ʻaֽl-ká̇l-ʼàşě֥r ʻáş֖̂ẇ nĕʼum-yĕhwáֽh׃s"],[31,38,"הִנֵּ֛ה יָמִ֥ים נְאֻם־יְהוָ֑ה וְ⁠נִבְנְתָ֤ה הָ⁠עִיר֙ לַֽ⁠יהוָ֔ה מִ⁠מִּגְדַּ֥ל חֲנַנְאֵ֖ל שַׁ֥עַר הַ⁠פִּנָּֽה׃","hiné֛̇h yámi֥ym nĕʼum-yĕhwá֑h wĕ⁠nibĕnĕţá֤h há⁠ʻiyr֙ laֽ⁠yhwá֔h mi⁠mi̇gĕdȧ֥l ẖànanĕʼé֖l şǎ֥ʻar ha⁠pi̇náֽ̇h׃"],[31,39,"וְ⁠יָצָ֨א ע֜וֹד קוה הַ⁠מִּדָּה֙ נֶגְדּ֔⁠וֹ עַ֖ל גִּבְעַ֣ת גָּרֵ֑ב וְ⁠נָסַ֖ב גֹּעָֽתָ⁠ה׃","wĕ⁠yáẕá֨ʼ ʻ֜wòd qwh ha⁠mi̇dá̇h֙ negĕḋ֔⁠wò ʻa֖l gi̇bĕʻa֣ţ gá̇ré֑b wĕ⁠nása֖b gò̇ʻáֽţá⁠h׃"],[31,40,"וְ⁠כָל־הָ⁠עֵ֣מֶק הַ⁠פְּגָרִ֣ים ׀ וְ⁠הַ⁠דֶּ֡שֶׁן וְ⁠כָֽל־ה⁠שרמות עַד־נַ֨חַל קִדְר֜וֹן עַד־פִּנַּ֨ת שַׁ֤עַר הַ⁠סּוּסִים֙ מִזְרָ֔חָ⁠ה קֹ֖דֶשׁ לַֽ⁠יהוָ֑ה לֹֽא־יִנָּתֵ֧שׁ וְֽ⁠לֹא־יֵהָרֵ֛ס ע֖וֹד לְ⁠עוֹלָֽם׃ס","wĕ⁠kál-há⁠ʻé֣meq ha⁠pĕ̇gári֣ym ׀ wĕ⁠ha⁠dė֡şěn wĕ⁠káֽl-h⁠şrmwţ ʻad-na֨ẖal qidĕr֜wòn ʻad-pi̇nȧ֨ţ şǎ֤ʻar ha⁠ṡẇsiym֙ mizĕrá֔ẖá⁠h qò֖deş̌ laֽ⁠yhwá֑h lòֽʼ-yiná̇ţé֧ş̌ wĕֽ⁠lòʼ-yéháré֛s ʻ֖wòd lĕ⁠ʻwòláֽm׃s"],[32,1,"הַ⁠דָּבָ֞ר אֲשֶׁר־הָיָ֤ה אֶֽל־יִרְמְיָ֨הוּ֙ מֵ⁠אֵ֣ת יְהוָ֔ה ב⁠שנת הָ⁠עֲשִׂרִ֔ית לְ⁠צִדְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה הִ֧יא הַ⁠שָּׁנָ֛ה שְׁמֹנֶֽה־עֶשְׂרֵ֥ה שָׁנָ֖ה לִ⁠נְבֽוּכַדְרֶאצַּֽר׃","ha⁠dá̇bá֞r ʼàşěr-háyá֤h ʼeֽl-yirĕmĕyá֨hẇ֙ mé⁠ʼé֣ţ yĕhwá֔h b⁠şnţ há⁠ʻàşîri֔yţ lĕ⁠ẕidĕqiyá֖̇hẇ me֣lekĕ yĕhẇdá֑h hi֧yʼ ha⁠şá̇̌ná֛h şĕ̌mòneֽh-ʻeşĕ̂ré֥h şá̌ná֖h li⁠nĕbֽẇkadĕreʼẕȧֽr׃"],[32,2,"וְ⁠אָ֗ז חֵ֚יל מֶ֣לֶךְ בָּבֶ֔ל צָרִ֖ים עַל־יְרוּשָׁלִָ֑ם וְ⁠יִרְמְיָ֣הוּ הַ⁠נָּבִ֗יא הָיָ֤ה כָלוּא֙ בַּ⁠חֲצַ֣ר הַ⁠מַּטָּרָ֔ה אֲשֶׁ֖ר בֵּֽית־מֶ֥לֶךְ יְהוּדָֽה׃","wĕ⁠ʼá֗z ẖé֚yl me֣lekĕ bá̇be֔l ẕári֖ym ʻal-yĕrẇşá̌liá֑m wĕ⁠yirĕmĕyá֣hẇ ha⁠ná̇bi֗yʼ háyá֤h kálẇʼ֙ bȧ⁠ẖàẕa֣r ha⁠mȧtá̇rá֔h ʼàşě֖r béֽ̇yţ-me֥lekĕ yĕhẇdáֽh׃"],[32,3,"אֲשֶׁ֣ר כְּלָא֔⁠וֹ צִדְקִיָּ֥הוּ מֶֽלֶךְ־יְהוּדָ֖ה לֵ⁠אמֹ֑ר מַדּוּעַ֩ אַתָּ֨ה נִבָּ֜א לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֨י נֹתֵ֜ן אֶת־הָ⁠עִ֥יר הַ⁠זֹּ֛את בְּ⁠יַ֥ד מֶֽלֶךְ־בָּבֶ֖ל וּ⁠לְכָדָֽ⁠הּ׃","ʼàşě֣r kĕ̇láʼ֔⁠wò ẕidĕqiyá֥̇hẇ meֽlekĕ-yĕhẇdá֖h lé⁠ʼmò֑r maḋẇʻa֩ ʼaţá̇֨h nibá̇֜ʼ lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֨y nòţé֜n ʼeţ-há⁠ʻi֥yr ha⁠zò֛̇ʼţ bĕ̇⁠ya֥d meֽlekĕ-bá̇be֖l ẇ⁠lĕkádáֽ⁠ḣ׃"],[32,4,"וְ⁠צִדְקִיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה לֹ֥א יִמָּלֵ֖ט מִ⁠יַּ֣ד הַ⁠כַּשְׂדִּ֑ים כִּ֣י הִנָּתֹ֤ן יִנָּתֵן֙ בְּ⁠יַ֣ד מֶֽלֶךְ־בָּבֶ֔ל וְ⁠דִבֶּר־פִּ֣י⁠ו עִם־פִּ֔י⁠ו וְ⁠עֵינָ֖י⁠ו אֶת־עינ⁠ו תִּרְאֶֽינָה׃","wĕ⁠ẕidĕqiyá̇֨hẇ֙ me֣lekĕ yĕhẇdá֔h lò֥ʼ yimá̇lé֖t mi⁠yȧ֣d ha⁠kȧşĕ̂di֑̇ym ki֣̇y hiná̇ţò֤n yiná̇ţén֙ bĕ̇⁠ya֣d meֽlekĕ-bá̇be֔l wĕ⁠dibėr-pi֣̇y⁠w ʻim-pi̇֔y⁠w wĕ⁠ʻéyná֖y⁠w ʼeţ-ʻyn⁠w ţi̇rĕʼeֽynáh׃"],[32,5,"וּ⁠בָבֶ֞ל יוֹלִ֤ךְ אֶת־צִדְקִיָּ֨הוּ֙ וְ⁠שָׁ֣ם יִֽהְיֶ֔ה עַד־פָּקְדִ֥⁠י אֹת֖⁠וֹ נְאֻם־יְהוָ֑ה כִּ֧י תִֽלָּחֲמ֛וּ אֶת־הַ⁠כַּשְׂדִּ֖ים לֹ֥א תַצְלִֽיחוּ׃פ","ẇ⁠bábe֞l ywòli֤kĕ ʼeţ-ẕidĕqiyá̇֨hẇ֙ wĕ⁠şá֣̌m yiֽhĕye֔h ʻad-pá̇qĕdi֥⁠y ʼòţ֖⁠wò nĕʼum-yĕhwá֑h ki֧̇y ţiֽlá̇ẖàm֛ẇ ʼeţ-ha⁠kȧşĕ̂di֖̇ym lò֥ʼ ţaẕĕliֽyẖẇ׃p"],[32,6,"וַ⁠יֹּ֖אמֶר יִרְמְיָ֑הוּ הָיָ֥ה דְּבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yò֖̇ʼmer yirĕmĕyá֑hẇ háyá֥h dĕ̇bar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[32,7,"הִנֵּ֣ה חֲנַמְאֵ֗ל בֶּן־שַׁלֻּם֙ דֹּֽדְ⁠ךָ֔ בָּ֥א אֵלֶ֖י⁠ךָ לֵ⁠אמֹ֑ר קְנֵ֣ה לְ⁠ךָ֗ אֶת־שָׂדִ⁠י֙ אֲשֶׁ֣ר בַּ⁠עֲנָת֔וֹת כִּ֥י לְ⁠ךָ֛ מִשְׁפַּ֥ט הַ⁠גְּאֻלָּ֖ה לִ⁠קְנֽוֹת׃","hiné֣̇h ẖànamĕʼé֗l bėn-şǎlu̇m֙ dòֽ̇dĕ⁠ká֔ bá֥̇ʼ ʼéle֖y⁠ká lé⁠ʼmò֑r qĕné֣h lĕ⁠ká֗ ʼeţ-şá̂di⁠y֙ ʼàşě֣r bȧ⁠ʻànáţ֔wòţ ki֥̇y lĕ⁠ká֛ mişĕ̌pȧ֥t ha⁠gĕ̇ʼulá֖̇h li⁠qĕnֽwòţ׃"],[32,8,"וַ⁠יָּבֹ֣א אֵ֠לַ⁠י חֲנַמְאֵ֨ל בֶּן־דֹּדִ֜⁠י כִּ⁠דְבַ֣ר יְהוָה֮ אֶל־חֲצַ֣ר הַ⁠מַּטָּרָה֒ וַ⁠יֹּ֣אמֶר אֵלַ֡⁠י קְנֵ֣ה נָ֠א אֶת־שָׂדִ֨⁠י אֲשֶׁר־בַּ⁠עֲנָת֜וֹת אֲשֶׁ֣ר ׀ בְּ⁠אֶ֣רֶץ בִּנְיָמִ֗ין כִּֽי־לְ⁠ךָ֞ מִשְׁפַּ֧ט הַ⁠יְרֻשָּׁ֛ה וּ⁠לְ⁠ךָ֥ הַ⁠גְּאֻלָּ֖ה קְנֵה־לָ֑⁠ךְ וָ⁠אֵדַ֕ע כִּ֥י דְבַר־יְהוָ֖ה הֽוּא׃","wa⁠yá̇bò֣ʼ ʼé֠la⁠y ẖànamĕʼé֨l bėn-dò̇di֜⁠y ki̇⁠dĕba֣r yĕhwáh֮ ʼel-ẖàẕa֣r ha⁠mȧtá̇ráh֒ wa⁠yò֣̇ʼmer ʼéla֡⁠y qĕné֣h ná֠ʼ ʼeţ-şá̂di֨⁠y ʼàşěr-bȧ⁠ʻànáţ֜wòţ ʼàşě֣r ׀ bĕ̇⁠ʼe֣reẕ bi̇nĕyámi֗yn kiֽ̇y-lĕ⁠ká֞ mişĕ̌pȧ֧t ha⁠yĕruşá֛̇̌h ẇ⁠lĕ⁠ká֥ ha⁠gĕ̇ʼulá֖̇h qĕnéh-lá֑⁠kĕ wá⁠ʼéda֕ʻ ki֥̇y dĕbar-yĕhwá֖h hֽẇʼ׃"],[32,9,"וָֽ⁠אֶקְנֶה֙ אֶת־הַ⁠שָּׂדֶ֔ה מֵ⁠אֵ֛ת חֲנַמְאֵ֥ל בֶּן־דֹּדִ֖⁠י אֲשֶׁ֣ר בַּ⁠עֲנָת֑וֹת וָֽ⁠אֶשְׁקֲלָ⁠ה־לּ⁠וֹ֙ אֶת־הַ⁠כֶּ֔סֶף שִׁבְעָ֥ה שְׁקָלִ֖ים וַ⁠עֲשָׂרָ֥ה הַ⁠כָּֽסֶף׃","wáֽ⁠ʼeqĕneh֙ ʼeţ-ha⁠şá̇̂de֔h mé⁠ʼé֛ţ ẖànamĕʼé֥l bėn-dò̇di֖⁠y ʼàşě֣r bȧ⁠ʻànáţ֑wòţ wáֽ⁠ʼeşĕ̌qàlá⁠h-l̇⁠wò֙ ʼeţ-ha⁠kė֔sep şǐbĕʻá֥h şĕ̌qáli֖ym wa⁠ʻàşá̂rá֥h ha⁠káֽ̇sep׃"],[32,10,"וָ⁠אֶכְתֹּ֤ב בַּ⁠סֵּ֨פֶר֙ וָֽ⁠אֶחְתֹּ֔ם וָ⁠אָעֵ֖ד עֵדִ֑ים וָ⁠אֶשְׁקֹ֥ל הַ⁠כֶּ֖סֶף בְּ⁠מֹאזְנָֽיִם׃","wá⁠ʼekĕţò֤̇b bȧ⁠sé̇֨per֙ wáֽ⁠ʼeẖĕţò̇֔m wá⁠ʼáʻé֖d ʻédi֑ym wá⁠ʼeşĕ̌qò֥l ha⁠kė֖sep bĕ̇⁠mòʼzĕnáֽyim׃"],[32,11,"וָ⁠אֶקַּ֖ח אֶת־סֵ֣פֶר הַ⁠מִּקְנָ֑ה אֶת־הֶֽ⁠חָת֛וּם הַ⁠מִּצְוָ֥ה וְ⁠הַ⁠חֻקִּ֖ים וְ⁠אֶת־הַ⁠גָּלֽוּי׃","wá⁠ʼeqȧ֖ẖ ʼeţ-sé֣per ha⁠mi̇qĕná֑h ʼeţ-heֽ⁠ẖáţ֛ẇm ha⁠mi̇ẕĕwá֥h wĕ⁠ha⁠ẖuqi֖̇ym wĕ⁠ʼeţ-ha⁠gá̇lֽẇy׃"],[32,12,"וָ⁠אֶתֵּ֞ן אֶת־הַ⁠סֵּ֣פֶר הַ⁠מִּקְנָ֗ה אֶל־בָּר֣וּךְ בֶּן־נֵרִיָּה֮ בֶּן־מַחְסֵיָה֒ לְ⁠עֵינֵי֙ חֲנַמְאֵ֣ל דֹּדִ֔⁠י וּ⁠לְ⁠עֵינֵי֙ הָֽ⁠עֵדִ֔ים הַ⁠כֹּתְבִ֖ים בְּ⁠סֵ֣פֶר הַ⁠מִּקְנָ֑ה לְ⁠עֵינֵי֙ כָּל־הַ⁠יְּהוּדִ֔ים הַ⁠יֹּשְׁבִ֖ים בַּ⁠חֲצַ֥ר הַ⁠מַּטָּרָֽה׃","wá⁠ʼeţé̇֞n ʼeţ-ha⁠sé֣̇per ha⁠mi̇qĕná֗h ʼel-bá̇r֣ẇkĕ bėn-nériyá̇h֮ bėn-maẖĕséyáh֒ lĕ⁠ʻéynéy֙ ẖànamĕʼé֣l dò̇di֔⁠y ẇ⁠lĕ⁠ʻéynéy֙ háֽ⁠ʻédi֔ym ha⁠kò̇ţĕbi֖ym bĕ̇⁠sé֣per ha⁠mi̇qĕná֑h lĕ⁠ʻéynéy֙ ká̇l-ha⁠yĕ̇hẇdi֔ym ha⁠yò̇şĕ̌bi֖ym bȧ⁠ẖàẕa֥r ha⁠mȧtá̇ráֽh׃"],[32,13,"וָֽ⁠אֲצַוֶּה֙ אֶת בָּר֔וּךְ לְ⁠עֵינֵי⁠הֶ֖ם לֵ⁠אמֹֽר׃","wֽá⁠ʼàẕawėh֙ ʼeţ bá̇r֔ẇkĕ lĕ⁠ʻéynéy⁠he֖m lé⁠ʼmòֽr׃"],[32,14,"כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל לָק֣וֹחַ אֶת־הַ⁠סְּפָרִ֣ים הָ⁠אֵ֡לֶּה אֵ֣ת סֵפֶר֩ הַ⁠מִּקְנָ֨ה הַ⁠זֶּ֜ה וְ⁠אֵ֣ת הֶ⁠חָת֗וּם וְ⁠אֵ֨ת סֵ֤פֶר הַ⁠גָּלוּי֙ הַ⁠זֶּ֔ה וּ⁠נְתַתָּ֖⁠ם בִּ⁠כְלִי־חָ֑רֶשׂ לְמַ֥עַן יַעַמְד֖וּ יָמִ֥ים רַבִּֽים׃ס","kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l láq֣wòẖa ʼeţ-ha⁠sĕ̇pári֣ym há⁠ʼé֡lėh ʼé֣ţ séper֩ ha⁠mi̇qĕná֨h ha⁠zė֜h wĕ⁠ʼé֣ţ he⁠ẖáţ֗ẇm wĕ⁠ʼé֨ţ sé֤per ha⁠gá̇lẇy֙ ha⁠zė֔h ẇ⁠nĕţaţá֖̇⁠m bi̇⁠kĕliy-ẖá֑reş̂ lĕma֥ʻan yaʻamĕd֖ẇ yámi֥ym rabiֽ̇ym׃s"],[32,15,"כִּ֣י כֹ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל ע֣וֹד יִקָּנ֥וּ בָתִּ֛ים וְ⁠שָׂד֥וֹת וּ⁠כְרָמִ֖ים בָּ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃פ","ki֣̇y kò֥h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhé֣y yişĕ̂ráʼé֑l ʻ֣wòd yiqá̇n֥ẇ báţi֛̇ym wĕ⁠şá̂d֥wòţ ẇ⁠kĕrámi֖ym bá̇⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃p"],[32,16,"וָ⁠אֶתְפַּלֵּ֖ל אֶל־יְהוָ֑ה אַחֲרֵ֤י תִתִּ⁠י֙ אֶת־סֵ֣פֶר הַ⁠מִּקְנָ֔ה אֶל־בָּר֥וּךְ בֶּן־נֵרִיָּ֖ה לֵ⁠אמֹֽר׃","wá⁠ʼeţĕpȧlé֖̇l ʼel-yĕhwá֑h ʼaẖàré֤y ţiţi̇⁠y֙ ʼeţ-sé֣per ha⁠mi̇qĕná֔h ʼel-bá̇r֥ẇkĕ bėn-nériyá֖̇h lé⁠ʼmòֽr׃"],[32,17,"אֲהָהּ֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנֵּ֣ה ׀ אַתָּ֣ה עָשִׂ֗יתָ אֶת־הַ⁠שָּׁמַ֨יִם֙ וְ⁠אֶת־הָ⁠אָ֔רֶץ בְּ⁠כֹֽחֲ⁠ךָ֙ הַ⁠גָּד֔וֹל וּ⁠בִֽ⁠זְרֹעֲ⁠ךָ֖ הַ⁠נְּטוּיָ֑ה לֹֽא־יִפָּלֵ֥א מִמְּ⁠ךָ֖ כָּל־דָּבָֽר׃","ʼàháḣ֮ ʼàdòná֣⁠y yĕhwih֒ hiné֣̇h ׀ ʼaţá֣̇h ʻáşî֗yţá ʼeţ-ha⁠şá̇̌ma֨yim֙ wĕ⁠ʼeţ-há⁠ʼá֔reẕ bĕ̇⁠kòֽẖà⁠ká֙ ha⁠gá̇d֔wòl ẇ⁠biֽ⁠zĕròʻà⁠ká֖ ha⁠nĕ̇tẇyá֑h lòֽʼ-yipá̇lé֥ʼ mimĕ̇⁠ká֖ ká̇l-dá̇báֽr׃"],[32,18,"עֹ֤שֶׂה חֶ֨סֶד֙ לַֽ⁠אֲלָפִ֔ים וּ⁠מְשַׁלֵּם֙ עֲוֺ֣ן אָב֔וֹת אֶל־חֵ֥יק בְּנֵי⁠הֶ֖ם אַחֲרֵי⁠הֶ֑ם הָ⁠אֵ֤ל הַ⁠גָּדוֹל֙ הַ⁠גִּבּ֔וֹר יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃","ʻò֤şêh ẖe֨sed֙ laֽ⁠ʼàlápi֔ym ẇ⁠mĕşǎlé̇m֙ ʻàwֺ֣n ʼáb֔wòţ ʼel-ẖé֥yq bĕ̇néy⁠he֖m ʼaẖàréy⁠he֑m há⁠ʼé֤l ha⁠gá̇dwòl֙ ha⁠gi̇ḃ֔wòr yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃"],[32,19,"גְּדֹל֙ הָֽ⁠עֵצָ֔ה וְ⁠רַ֖ב הָ⁠עֲלִֽילִיָּ֑ה אֲשֶׁר־עֵינֶ֣י⁠ךָ פְקֻח֗וֹת עַל־כָּל־דַּרְכֵי֙ בְּנֵ֣י אָדָ֔ם לָ⁠תֵ֤ת לְ⁠אִישׁ֙ כִּ⁠דְרָכָ֔י⁠ו וְ⁠כִ⁠פְרִ֖י מַעֲלָלָֽי⁠ו׃","gĕ̇dòl֙ háֽ⁠ʻéẕá֔h wĕ⁠ra֖b há⁠ʻàliֽyliyá֑̇h ʼàşěr-ʻéyne֣y⁠ká pĕquẖ֗wòţ ʻal-ká̇l-dȧrĕkéy֙ bĕ̇né֣y ʼádá֔m lá⁠ţé֤ţ lĕ⁠ʼiyş̌֙ ki̇⁠dĕráká֔y⁠w wĕ⁠ki⁠pĕri֖y maʻàláláֽy⁠w׃"],[32,20,"אֲשֶׁר־שַׂ֠מְתָּ אֹת֨וֹת וּ⁠מֹפְתִ֤ים בְּ⁠אֶֽרֶץ־מִצְרַ֨יִם֙ עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וּ⁠בְ⁠יִשְׂרָאֵ֖ל וּ⁠בָֽ⁠אָדָ֑ם וַ⁠תַּעֲשֶׂה־לְּ⁠ךָ֥ שֵׁ֖ם כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ʼàşěr-şâ֠mĕţá̇ ʼòţ֨wòţ ẇ⁠mòpĕţi֤ym bĕ̇⁠ʼeֽreẕ-miẕĕra֨yim֙ ʻad-ha⁠ẏ֣wòm ha⁠zė֔h ẇ⁠bĕ⁠yişĕ̂ráʼé֖l ẇ⁠báֽ⁠ʼádá֑m wa⁠ţȧʻàşêh-lĕ̇⁠ká֥ şé֖̌m kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[32,21,"וַ⁠תֹּצֵ֛א אֶת־עַמְּ⁠ךָ֥ אֶת־יִשְׂרָאֵ֖ל מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם בְּ⁠אֹת֣וֹת וּ⁠בְ⁠מוֹפְתִ֗ים וּ⁠בְ⁠יָ֤ד חֲזָקָה֙ וּ⁠בְ⁠אֶזְר֣וֹעַ נְטוּיָ֔ה וּ⁠בְ⁠מוֹרָ֖א גָּדֽוֹל׃","wa⁠ţò̇ẕé֛ʼ ʼeţ-ʻamĕ̇⁠ká֥ ʼeţ-yişĕ̂ráʼé֖l mé⁠ʼe֣reẕ miẕĕrá֑yim bĕ̇⁠ʼòţ֣wòţ ẇ⁠bĕ⁠mwòpĕţi֗ym ẇ⁠bĕ⁠yá֤d ẖàzáqáh֙ ẇ⁠bĕ⁠ʼezĕr֣wòʻa nĕtẇyá֔h ẇ⁠bĕ⁠mwòrá֖ʼ gá̇dֽwòl׃"],[32,22,"וַ⁠תִּתֵּ֤ן לָ⁠הֶם֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את אֲשֶׁר־נִשְׁבַּ֥עְתָּ לַ⁠אֲבוֹתָ֖⁠ם לָ⁠תֵ֣ת לָ⁠הֶ֑ם אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃","wa⁠ţi̇ţé֤̇n lá⁠hem֙ ʼeţ-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ʼàşěr-nişĕ̌bȧ֥ʻĕţá̇ la⁠ʼàbwòţá֖⁠m lá⁠ţé֣ţ lá⁠he֑m ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃"],[32,23,"וַ⁠יָּבֹ֜אוּ וַ⁠יִּֽרְשׁ֣וּ אֹתָ֗⁠הּ וְ⁠לֹֽא־שָׁמְע֤וּ בְ⁠קוֹלֶ֨⁠ךָ֙ ו⁠ב⁠תרות⁠ך לֹא־הָלָ֔כוּ אֵת֩ כָּל־אֲשֶׁ֨ר צִוִּ֧יתָה לָ⁠הֶ֛ם לַ⁠עֲשׂ֖וֹת לֹ֣א עָשׂ֑וּ וַ⁠תַּקְרֵ֣א אֹתָ֔⁠ם אֵ֥ת כָּל־הָ⁠רָעָ֖ה הַ⁠זֹּֽאת׃","wa⁠yá̇bò֜ʼẇ wa⁠yiֽ̇rĕş֣̌ẇ ʼòţá֗⁠ḣ wĕ⁠lòֽʼ-şá̌mĕʻ֤ẇ bĕ⁠qwòle֨⁠ká֙ w⁠b⁠ţrwţ⁠k lòʼ-hálá֔kẇ ʼéţ֩ ká̇l-ʼàşě֨r ẕiwi֧̇yţáh lá⁠he֛m la⁠ʻàş֖̂wòţ lò֣ʼ ʻáş֑̂ẇ wa⁠ţȧqĕré֣ʼ ʼòţá֔⁠m ʼé֥ţ ká̇l-há⁠ráʻá֖h ha⁠zòֽ̇ʼţ׃"],[32,24,"הִנֵּ֣ה הַ⁠סֹּלְל֗וֹת בָּ֣אוּ הָ⁠עִיר֮ לְ⁠לָכְדָ⁠הּ֒ וְ⁠הָ⁠עִ֣יר נִתְּנָ֗ה בְּ⁠יַ֤ד הַ⁠כַּשְׂדִּים֙ הַ⁠נִּלְחָמִ֣ים עָלֶ֔י⁠הָ מִ⁠פְּנֵ֛י הַ⁠חֶ֥רֶב וְ⁠הָ⁠רָעָ֖ב וְ⁠הַ⁠דָּ֑בֶר וַ⁠אֲשֶׁ֥ר דִּבַּ֛רְתָּ הָיָ֖ה וְ⁠הִנְּ⁠ךָ֥ רֹאֶֽה׃","hiné֣̇h ha⁠sò̇lĕl֗wòţ bá֣̇ʼẇ há⁠ʻiyr֮ lĕ⁠lákĕdá⁠ḣ֒ wĕ⁠há⁠ʻi֣yr niţĕ̇ná֗h bĕ̇⁠ya֤d ha⁠kȧşĕ̂di̇ym֙ ha⁠ni̇lĕẖámi֣ym ʻále֔y⁠há mi⁠pĕ̇né֛y ha⁠ẖe֥reb wĕ⁠há⁠ráʻá֖b wĕ⁠ha⁠dá֑̇ber wa⁠ʼàşě֥r di̇bȧ֛rĕţá̇ háyá֖h wĕ⁠hinĕ̇⁠ká֥ ròʼeֽh׃"],[32,25,"וְ⁠אַתָּ֞ה אָמַ֤רְתָּ אֵלַ⁠י֙ אֲדֹנָ֣⁠י יְהוִ֔ה קְנֵֽה־לְ⁠ךָ֧ הַ⁠שָּׂדֶ֛ה בַּ⁠כֶּ֖סֶף וְ⁠הָעֵ֣ד עֵדִ֑ים וְ⁠הָ⁠עִ֥יר נִתְּנָ֖ה בְּ⁠יַ֥ד הַ⁠כַּשְׂדִּֽים׃","wĕ⁠ʼaţá̇֞h ʼáma֤rĕţá̇ ʼéla⁠y֙ ʼàdòná֣⁠y yĕhwi֔h qĕnéֽh-lĕ⁠ká֧ ha⁠şá̇̂de֛h bȧ⁠kė֖sep wĕ⁠háʻé֣d ʻédi֑ym wĕ⁠há⁠ʻi֥yr niţĕ̇ná֖h bĕ̇⁠ya֥d ha⁠kȧşĕ̂diֽ̇ym׃"],[32,26,"וַ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ לֵ⁠אמֹֽר׃","wa⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ lé⁠ʼmòֽr׃"],[32,27,"הִנֵּה֙ אֲנִ֣י יְהוָ֔ה אֱלֹהֵ֖י כָּל־בָּשָׂ֑ר הֲֽ⁠מִמֶּ֔⁠נִּי יִפָּלֵ֖א כָּל־דָּבָֽר׃","hiné̇h֙ ʼàni֣y yĕhwá֔h ʼèlòhé֖y ká̇l-bá̇şá֑̂r hàֽ⁠mimė֔⁠ni̇y yipá̇lé֖ʼ ká̇l-dá̇báֽr׃"],[32,28,"לָ⁠כֵ֕ן כֹּ֖ה אָמַ֣ר יְהוָ֑ה הִנְ⁠נִ֣י נֹתֵן֩ אֶת־הָ⁠עִ֨יר הַ⁠זֹּ֜את בְּ⁠יַ֣ד הַ⁠כַּשְׂדִּ֗ים וּ⁠בְ⁠יַ֛ד נְבֽוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל וּ⁠לְכָדָֽ⁠הּ׃","lá⁠ké֕n kò֖̇h ʼáma֣r yĕhwá֑h hinĕ⁠ni֣y nòţén֩ ʼeţ-há⁠ʻi֨yr ha⁠zò̇֜ʼţ bĕ̇⁠ya֣d ha⁠kȧşĕ̂di̇֗ym ẇ⁠bĕ⁠ya֛d nĕbֽẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l ẇ⁠lĕkádáֽ⁠ḣ׃"],[32,29,"וּ⁠בָ֣אוּ הַ⁠כַּשְׂדִּ֗ים הַ⁠נִּלְחָמִים֙ עַל־הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠הִצִּ֜יתוּ אֶת־הָ⁠עִ֥יר הַ⁠זֹּ֛את בָּ⁠אֵ֖שׁ וּ⁠שְׂרָפ֑וּ⁠הָ וְ⁠אֵ֣ת הַ⁠בָּתִּ֡ים אֲשֶׁר֩ קִטְּר֨וּ עַל־גַּגּֽוֹתֵי⁠הֶ֜ם לַ⁠בַּ֗עַל וְ⁠הִסִּ֤כוּ נְסָכִים֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים לְמַ֖עַן הַכְעִסֵֽ⁠נִי׃","ẇ⁠bá֣ʼẇ ha⁠kȧşĕ̂di̇֗ym ha⁠ni̇lĕẖámiym֙ ʻal-há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠hiẕi̇֜yţẇ ʼeţ-há⁠ʻi֥yr ha⁠zò֛̇ʼţ bá̇⁠ʼé֖ş̌ ẇ⁠şĕ̂ráp֑ẇ⁠há wĕ⁠ʼé֣ţ ha⁠bá̇ţi̇֡ym ʼàşěr֩ qitĕ̇r֨ẇ ʻal-gȧġֽwòţéy⁠he֜m la⁠bȧ֗ʻal wĕ⁠hisi֤̇kẇ nĕsákiym֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym lĕma֖ʻan hakĕʻiséֽ⁠niy׃"],[32,30,"כִּֽי־הָי֨וּ בְנֵֽי־יִשְׂרָאֵ֜ל וּ⁠בְנֵ֣י יְהוּדָ֗ה אַ֣ךְ עֹשִׂ֥ים הָ⁠רַ֛ע בְּ⁠עֵינַ֖⁠י מִ⁠נְּעֻרֹֽתֵי⁠הֶ֑ם כִּ֣י בְנֵֽי־יִשְׂרָאֵ֗ל אַ֣ךְ מַכְעִסִ֥ים אֹתִ֛⁠י בְּ⁠מַעֲשֵׂ֥ה יְדֵי⁠הֶ֖ם נְאֻם־יְהוָֽה׃","kiֽ̇y-háy֨ẇ bĕnéֽy-yişĕ̂ráʼé֜l ẇ⁠bĕné֣y yĕhẇdá֗h ʼa֣kĕ ʻòşî֥ym há⁠ra֛ʻ bĕ̇⁠ʻéyna֖⁠y mi⁠nĕ̇ʻuròֽţéy⁠he֑m ki֣̇y bĕnéֽy-yişĕ̂ráʼé֗l ʼa֣kĕ makĕʻisi֥ym ʼòţi֛⁠y bĕ̇⁠maʻàşé֥̂h yĕdéy⁠he֖m nĕʼum-yĕhwáֽh׃"],[32,31,"כִּ֧י עַל־אַפִּ֣⁠י וְ⁠עַל־חֲמָתִ֗⁠י הָ֤יְתָה לִּ⁠י֙ הָ⁠עִ֣יר הַ⁠זֹּ֔את לְ⁠מִן־הַ⁠יּוֹם֙ אֲשֶׁ֣ר בָּנ֣וּ אוֹתָ֔⁠הּ וְ⁠עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה לַ⁠הֲסִירָ֖⁠הּ מֵ⁠עַ֥ל פָּנָֽ⁠י׃","ki֧̇y ʻal-ʼapi֣̇⁠y wĕ⁠ʻal-ẖàmáţi֗⁠y há֤yĕţáh li̇⁠y֙ há⁠ʻi֣yr ha⁠zò̇֔ʼţ lĕ⁠min-ha⁠ẏwòm֙ ʼàşě֣r bá̇n֣ẇ ʼwòţá֔⁠ḣ wĕ⁠ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h la⁠hàsiyrá֖⁠ḣ mé⁠ʻa֥l pá̇náֽ⁠y׃"],[32,32,"עַל֩ כָּל־רָעַ֨ת בְּנֵֽי־יִשְׂרָאֵ֜ל וּ⁠בְנֵ֣י יְהוּדָ֗ה אֲשֶׁ֤ר עָשׂוּ֙ לְ⁠הַכְעִסֵ֔⁠נִי הֵ֤מָּה מַלְכֵי⁠הֶם֙ שָֽׂרֵי⁠הֶ֔ם כֹּהֲנֵי⁠הֶ֖ם וּ⁠נְבִֽיאֵי⁠הֶ֑ם וְ⁠אִ֣ישׁ יְהוּדָ֔ה וְ⁠יֹשְׁבֵ֖י יְרוּשָׁלִָֽם׃","ʻal֩ ká̇l-ráʻa֨ţ bĕ̇néֽy-yişĕ̂ráʼé֜l ẇ⁠bĕné֣y yĕhẇdá֗h ʼàşě֤r ʻáş̂ẇ֙ lĕ⁠hakĕʻisé֔⁠niy hé֤má̇h malĕkéy⁠hem֙ şáֽ̂réy⁠he֔m kò̇hànéy⁠he֖m ẇ⁠nĕbiֽyʼéy⁠he֑m wĕ⁠ʼi֣yş̌ yĕhẇdá֔h wĕ⁠yòşĕ̌bé֖y yĕrẇşá̌liáֽm׃"],[32,33,"וַ⁠יִּפְנ֥וּ אֵלַ֛⁠י עֹ֖רֶף וְ⁠לֹ֣א פָנִ֑ים וְ⁠לַמֵּ֤ד אֹתָ⁠ם֙ הַשְׁכֵּ֣ם וְ⁠לַמֵּ֔ד וְ⁠אֵינָ֥⁠ם שֹׁמְעִ֖ים לָ⁠קַ֥חַת מוּסָֽר׃","wa⁠yi̇pĕn֥ẇ ʼéla֛⁠y ʻò֖rep wĕ⁠lò֣ʼ páni֑ym wĕ⁠lamé֤̇d ʼòţá⁠m֙ haşĕ̌ké֣̇m wĕ⁠lamé̇֔d wĕ⁠ʼéyná֥⁠m şò̌mĕʻi֖ym lá⁠qa֥ẖaţ mẇsáֽr׃"],[32,34,"וַ⁠יָּשִׂ֣ימוּ שִׁקּֽוּצֵי⁠הֶ֗ם בַּ⁠בַּ֛יִת אֲשֶׁר־נִקְרָֽא־שְׁמִ֥⁠י עָלָ֖י⁠ו לְ⁠טַמְּאֽ⁠וֹ׃","wa⁠yá̇şî֣ymẇ şǐqֽ̇ẇẕéy⁠he֗m bȧ⁠bȧ֛yiţ ʼàşěr-niqĕráֽʼ-şĕ̌mi֥⁠y ʻálá֖y⁠w lĕ⁠tamĕ̇ʼֽ⁠wò׃"],[32,35,"וַ⁠יִּבְנוּ֩ אֶת־בָּמ֨וֹת הַ⁠בַּ֜עַל אֲשֶׁ֣ר ׀ בְּ⁠גֵ֣יא בֶן־הִנֹּ֗ם לְ֠⁠הַעֲבִיר אֶת־בְּנֵי⁠הֶ֣ם וְ⁠אֶת־בְּנוֹתֵי⁠הֶם֮ לַ⁠מֹּלֶךְ֒ אֲשֶׁ֣ר לֹֽא־צִוִּיתִ֗י⁠ם וְ⁠לֹ֤א עָֽלְתָה֙ עַל־לִבִּ֔⁠י לַ⁠עֲשׂ֖וֹת הַ⁠תּוֹעֵבָ֣ה הַ⁠זֹּ֑את לְמַ֖עַן החטי אֶת־יְהוּדָֽה׃ס","wa⁠yi̇bĕnẇ֩ ʼeţ-bá̇m֨wòţ ha⁠bȧ֜ʻal ʼàşě֣r ׀ bĕ̇⁠gé֣yʼ ben-hinò̇֗m lĕ֠⁠haʻàbiyr ʼeţ-bĕ̇néy⁠he֣m wĕ⁠ʼeţ-bĕ̇nwòţéy⁠hem֮ la⁠mò̇lekĕ֒ ʼàşě֣r lòֽʼ-ẕiwi̇yţi֗y⁠m wĕ⁠lò֤ʼ ʻáֽlĕţáh֙ ʻal-libi̇֔⁠y la⁠ʻàş֖̂wòţ ha⁠ţ̇wòʻébá֣h ha⁠zò֑̇ʼţ lĕma֖ʻan hẖty ʼeţ-yĕhẇdáֽh׃s"],[32,36,"וְ⁠עַתָּ֕ה לָ⁠כֵ֛ן כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אֶל־הָ⁠עִ֨יר הַ⁠זֹּ֜את אֲשֶׁ֣ר ׀ אַתֶּ֣ם אֹמְרִ֗ים נִתְּנָה֙ בְּ⁠יַ֣ד מֶֽלֶךְ־בָּבֶ֔ל בַּ⁠חֶ֖רֶב וּ⁠בָ⁠רָעָ֥ב וּ⁠בַ⁠דָּֽבֶר׃","wĕ⁠ʻaţá̇֕h lá⁠ké֛n kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼel-há⁠ʻi֨yr ha⁠zò̇֜ʼţ ʼàşě֣r ׀ ʼaţė֣m ʼòmĕri֗ym niţĕ̇náh֙ bĕ̇⁠ya֣d meֽlekĕ-bá̇be֔l bȧ⁠ẖe֖reb ẇ⁠bá⁠ráʻá֥b ẇ⁠ba⁠dáֽ̇ber׃"],[32,37,"הִנְ⁠נִ֤י מְקַבְּצָ⁠ם֙ מִ⁠כָּל־הָ֣⁠אֲרָצ֔וֹת אֲשֶׁ֨ר הִדַּחְתִּ֥י⁠ם שָׁ֛ם בְּ⁠אַפִּ֥⁠י וּ⁠בַ⁠חֲמָתִ֖⁠י וּ⁠בְ⁠קֶ֣צֶף גָּד֑וֹל וַ⁠הֲשִֽׁבֹתִי⁠ם֙ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה וְ⁠הֹשַׁבְתִּ֖י⁠ם לָ⁠בֶֽטַח׃","hinĕ⁠ni֤y mĕqabĕ̇ẕá⁠m֙ mi⁠ká̇l-há֣⁠ʼàráẕ֔wòţ ʼàşě֨r hidȧẖĕţi֥̇y⁠m şá֛̌m bĕ̇⁠ʼapi֥̇⁠y ẇ⁠ba⁠ẖàmáţi֖⁠y ẇ⁠bĕ⁠qe֣ẕep gá̇d֑wòl wa⁠hàşǐֽbòţiy⁠m֙ ʼel-ha⁠má̇q֣wòm ha⁠zė֔h wĕ⁠hòşǎbĕţi֖̇y⁠m lá⁠beֽtaẖ׃"],[32,38,"וְ⁠הָ֥יוּ לִ֖⁠י לְ⁠עָ֑ם וַ⁠אֲנִ֕י אֶהְיֶ֥ה לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","wĕ⁠há֥yẇ li֖⁠y lĕ⁠ʻá֑m wa⁠ʼàni֕y ʼehĕye֥h lá⁠he֖m lé⁠ʼlòhiֽym׃"],[32,39,"וְ⁠נָתַתִּ֨י לָ⁠הֶ֜ם לֵ֤ב אֶחָד֙ וְ⁠דֶ֣רֶךְ אֶחָ֔ד לְ⁠יִרְאָ֥ה אוֹתִ֖⁠י כָּל־הַ⁠יָּמִ֑ים לְ⁠ט֣וֹב לָ⁠הֶ֔ם וְ⁠לִ⁠בְנֵי⁠הֶ֖ם אַחֲרֵי⁠הֶֽם׃","wĕ⁠náţaţi̇֨y lá⁠he֜m lé֤b ʼeẖád֙ wĕ⁠de֣rekĕ ʼeẖá֔d lĕ⁠yirĕʼá֥h ʼwòţi֖⁠y ká̇l-ha⁠yá̇mi֑ym lĕ⁠t֣wòb lá⁠he֔m wĕ⁠li⁠bĕnéy⁠he֖m ʼaẖàréy⁠heֽm׃"],[32,40,"וְ⁠כָרַתִּ֤י לָ⁠הֶם֙ בְּרִ֣ית עוֹלָ֔ם אֲשֶׁ֤ר לֹֽא־אָשׁוּב֙ מֵ⁠אַ֣חֲרֵי⁠הֶ֔ם לְ⁠הֵיטִיבִ֖⁠י אוֹתָ֑⁠ם וְ⁠אֶת־יִרְאָתִ⁠י֙ אֶתֵּ֣ן בִּ⁠לְבָבָ֔⁠ם לְ⁠בִלְתִּ֖י ס֥וּר מֵ⁠עָלָֽ⁠י׃","wĕ⁠káraţi֤̇y lá⁠hem֙ bĕ̇ri֣yţ ʻwòlá֔m ʼàşě֤r lòֽʼ-ʼáş̌ẇb֙ mé⁠ʼa֣ẖàréy⁠he֔m lĕ⁠héytiybi֖⁠y ʼwòţá֑⁠m wĕ⁠ʼeţ-yirĕʼáţi⁠y֙ ʼeţé֣̇n bi̇⁠lĕbábá֔⁠m lĕ⁠bilĕţi֖̇y s֥ẇr mé⁠ʻáláֽ⁠y׃"],[32,41,"וְ⁠שַׂשְׂתִּ֥י עֲלֵי⁠הֶ֖ם לְ⁠הֵטִ֣יב אוֹתָ֑⁠ם וּ⁠נְטַעְתִּ֞י⁠ם בָּ⁠אָ֤רֶץ הַ⁠זֹּאת֙ בֶּ⁠אֱמֶ֔ת בְּ⁠כָל־לִבִּ֖⁠י וּ⁠בְ⁠כָל־נַפְשִֽׁ⁠י׃ס","wĕ⁠şâşĕ̂ţi֥̇y ʻàléy⁠he֖m lĕ⁠héti֣yb ʼwòţá֑⁠m ẇ⁠nĕtaʻĕţi̇֞y⁠m bá̇⁠ʼá֤reẕ ha⁠zò̇ʼţ֙ bė⁠ʼème֔ţ bĕ̇⁠kál-libi֖̇⁠y ẇ⁠bĕ⁠kál-napĕşǐֽ⁠y׃s"],[32,42,"כִּֽי־כֹה֙ אָמַ֣ר יְהוָ֔ה כַּ⁠אֲשֶׁ֤ר הֵבֵ֨אתִי֙ אֶל־הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֵ֛ת כָּל־הָ⁠רָעָ֥ה הַ⁠גְּדוֹלָ֖ה הַ⁠זֹּ֑את כֵּ֣ן אָנֹכִ֞י מֵבִ֤יא עֲלֵי⁠הֶם֙ אֶת־כָּל־הַ⁠טּוֹבָ֔ה אֲשֶׁ֥ר אָנֹכִ֖י דֹּבֵ֥ר עֲלֵי⁠הֶֽם׃","kiֽ̇y-kòh֙ ʼáma֣r yĕhwá֔h kȧ⁠ʼàşě֤r hébé֨ʼţiy֙ ʼel-há⁠ʻá֣m ha⁠zė֔h ʼé֛ţ ká̇l-há⁠ráʻá֥h ha⁠gĕ̇dwòlá֖h ha⁠zò֑̇ʼţ ké֣̇n ʼánòki֞y mébi֤yʼ ʻàléy⁠hem֙ ʼeţ-ká̇l-ha⁠ṫwòbá֔h ʼàşě֥r ʼánòki֖y dò̇bé֥r ʻàléy⁠heֽm׃"],[32,43,"וְ⁠נִקְנָ֥ה הַ⁠שָּׂדֶ֖ה בָּ⁠אָ֣רֶץ הַ⁠זֹּ֑את אֲשֶׁ֣ר ׀ אַתֶּ֣ם אֹמְרִ֗ים שְׁמָמָ֥ה הִיא֙ מֵ⁠אֵ֤ין אָדָם֙ וּ⁠בְהֵמָ֔ה נִתְּנָ֖ה בְּ⁠יַ֥ד הַ⁠כַּשְׂדִּֽים׃","wĕ⁠niqĕná֥h ha⁠şá̇̂de֖h bá̇⁠ʼá֣reẕ ha⁠zò֑̇ʼţ ʼàşě֣r ׀ ʼaţė֣m ʼòmĕri֗ym şĕ̌mámá֥h hiyʼ֙ mé⁠ʼé֤yn ʼádám֙ ẇ⁠bĕhémá֔h niţĕ̇ná֖h bĕ̇⁠ya֥d ha⁠kȧşĕ̂diֽ̇ym׃"],[32,44,"שָׂד֞וֹת בַּ⁠כֶּ֣סֶף יִקְנ֗וּ וְ⁠כָת֨וֹב בַּ⁠סֵּ֥פֶר ׀ וְ⁠חָתוֹם֮ וְ⁠הָעֵ֣ד עֵדִים֒ בְּ⁠אֶ֨רֶץ בִּנְיָמִ֜ן וּ⁠בִ⁠סְבִיבֵ֣י יְרוּשָׁלִַ֗ם וּ⁠בְ⁠עָרֵ֤י יְהוּדָה֙ וּ⁠בְ⁠עָרֵ֣י הָ⁠הָ֔ר וּ⁠בְ⁠עָרֵ֥י הַ⁠שְּׁפֵלָ֖ה וּ⁠בְ⁠עָרֵ֣י הַ⁠נֶּ֑גֶב כִּֽי־אָשִׁ֥יב אֶת־שְׁבוּתָ֖⁠ם נְאֻם־יְהוָֽה׃פ","şá̂d֞wòţ bȧ⁠kė֣sep yiqĕn֗ẇ wĕ⁠káţ֨wòb bȧ⁠sé֥̇per ׀ wĕ⁠ẖáţwòm֮ wĕ⁠háʻé֣d ʻédiym֒ bĕ̇⁠ʼe֨reẕ bi̇nĕyámi֜n ẇ⁠bi⁠sĕbiybé֣y yĕrẇşá̌lia֗m ẇ⁠bĕ⁠ʻáré֤y yĕhẇdáh֙ ẇ⁠bĕ⁠ʻáré֣y há⁠há֔r ẇ⁠bĕ⁠ʻáré֥y ha⁠şĕ̇̌pélá֖h ẇ⁠bĕ⁠ʻáré֣y ha⁠nė֑geb kiֽ̇y-ʼáşǐ֥yb ʼeţ-şĕ̌bẇţá֖⁠m nĕʼum-yĕhwáֽh׃p"],[33,1,"וַ⁠יְהִ֧י דְבַר־יְהוָ֛ה אֶֽל־יִרְמְיָ֖הוּ שֵׁנִ֑ית וְ⁠הוּא֙ עוֹדֶ֣⁠נּוּ עָצ֔וּר בַּ⁠חֲצַ֥ר הַ⁠מַּטָּרָ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕhi֧y dĕbar-yĕhwá֛h ʼeֽl-yirĕmĕyá֖hẇ şé̌ni֑yţ wĕ⁠hẇʼ֙ ʻwòde֣⁠ṅẇ ʻáẕ֔ẇr bȧ⁠ẖàẕa֥r ha⁠mȧtá̇rá֖h lé⁠ʼmòֽr׃"],[33,2,"כֹּֽה־אָמַ֥ר יְהוָ֖ה עֹשָׂ֑⁠הּ יְהוָ֗ה יוֹצֵ֥ר אוֹתָ֛⁠הּ לַ⁠הֲכִינָ֖⁠הּ יְהוָ֥ה שְׁמֽ⁠וֹ׃","kòֽ̇h-ʼáma֥r yĕhwá֖h ʻòşá֑̂⁠ḣ yĕhwá֗h ywòẕé֥r ʼwòţá֛⁠ḣ la⁠hàkiyná֖⁠ḣ yĕhwá֥h şĕ̌mֽ⁠wò׃"],[33,3,"קְרָ֥א אֵלַ֖⁠י וְ⁠אֶעֱנֶ֑⁠ךָּ וְ⁠אַגִּ֧ידָה לְּ⁠ךָ֛ גְּדֹל֥וֹת וּ⁠בְצֻר֖וֹת לֹ֥א יְדַעְתָּֽ⁠ם׃ס","qĕrá֥ʼ ʼéla֖⁠y wĕ⁠ʼeʻène֑⁠ká̇ wĕ⁠ʼagi֧̇ydáh lĕ̇⁠ká֛ gĕ̇dòl֥wòţ ẇ⁠bĕẕur֖wòţ lò֥ʼ yĕdaʻĕţáֽ̇⁠m׃s"],[33,4,"כִּי֩ כֹ֨ה אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל עַל־בָּתֵּי֙ הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠עַל־בָּתֵּ֖י מַלְכֵ֣י יְהוּדָ֑ה הַ⁠נְּתֻצִ֕ים אֶל־הַ⁠סֹּלְל֖וֹת וְ⁠אֶל־הֶ⁠חָֽרֶב׃","ki̇y֩ kò֨h ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʻal-bá̇ţé̇y֙ há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠ʻal-bá̇ţé֖̇y malĕké֣y yĕhẇdá֑h ha⁠nĕ̇ţuẕi֕ym ʼel-ha⁠sò̇lĕl֖wòţ wĕ⁠ʼel-he⁠ẖáֽreb׃"],[33,5,"בָּאִ֗ים לְ⁠הִלָּחֵם֙ אֶת־הַ⁠כַּשְׂדִּ֔ים וּ⁠לְ⁠מַלְאָ⁠ם֙ אֶת־פִּגְרֵ֣י הָ⁠אָדָ֔ם אֲשֶׁר־הִכֵּ֥יתִי בְ⁠אַפִּ֖⁠י וּ⁠בַ⁠חֲמָתִ֑⁠י וַ⁠אֲשֶׁ֨ר הִסְתַּ֤רְתִּי פָנַ⁠י֙ מֵ⁠הָ⁠עִ֣יר הַ⁠זֹּ֔את עַ֖ל כָּל־רָעָתָֽ⁠ם׃","bá̇ʼi֗ym lĕ⁠hilá̇ẖém֙ ʼeţ-ha⁠kȧşĕ̂di̇֔ym ẇ⁠lĕ⁠malĕʼá⁠m֙ ʼeţ-pi̇gĕré֣y há⁠ʼádá֔m ʼàşěr-hiké֥̇yţiy bĕ⁠ʼapi֖̇⁠y ẇ⁠ba⁠ẖàmáţi֑⁠y wa⁠ʼàşě֨r hisĕţȧ֤rĕţi̇y pána⁠y֙ mé⁠há⁠ʻi֣yr ha⁠zò̇֔ʼţ ʻa֖l ká̇l-ráʻáţáֽ⁠m׃"],[33,6,"הִנְ⁠נִ֧י מַעֲלֶה־לָּ֛⁠הּ אֲרֻכָ֥ה וּ⁠מַרְפֵּ֖א וּ⁠רְפָאתִ֑י⁠ם וְ⁠גִלֵּיתִ֣י לָ⁠הֶ֔ם עֲתֶ֥רֶת שָׁל֖וֹם וֶ⁠אֱמֶֽת׃","hinĕ⁠ni֧y maʻàleh-lá֛̇⁠ḣ ʼàruká֥h ẇ⁠marĕpé֖̇ʼ ẇ⁠rĕpáʼţi֑y⁠m wĕ⁠gilé̇yţi֣y lá⁠he֔m ʻàţe֥reţ şá̌l֖wòm we⁠ʼèmeֽţ׃"],[33,7,"וַ⁠הֲשִֽׁבֹתִי֙ אֶת־שְׁב֣וּת יְהוּדָ֔ה וְ⁠אֵ֖ת שְׁב֣וּת יִשְׂרָאֵ֑ל וּ⁠בְנִתִ֖י⁠ם כְּ⁠בָ⁠רִֽאשֹׁנָֽה׃","wa⁠hàşǐֽbòţiy֙ ʼeţ-şĕ̌b֣ẇţ yĕhẇdá֔h wĕ⁠ʼé֖ţ şĕ̌b֣ẇţ yişĕ̂ráʼé֑l ẇ⁠bĕniţi֖y⁠m kĕ̇⁠bá⁠riֽʼşò̌náֽh׃"],[33,8,"וְ⁠טִ֣הַרְתִּ֔י⁠ם מִ⁠כָּל־עֲוֺנָ֖⁠ם אֲשֶׁ֣ר חָֽטְאוּ־לִ֑⁠י וְ⁠סָלַחְתִּ֗י ל⁠כול־עֲוֺנֽוֹתֵי⁠הֶם֙ אֲשֶׁ֣ר חָֽטְאוּ־לִ֔⁠י וַ⁠אֲשֶׁ֖ר פָּ֥שְׁעוּ בִֽ⁠י׃","wĕ⁠ti֣harĕţi̇֔y⁠m mi⁠ká̇l-ʻàwֺná֖⁠m ʼàşě֣r ẖáֽtĕʼẇ-li֑⁠y wĕ⁠sálaẖĕţi̇֗y l⁠kwl-ʻàwֺnֽwòţéy⁠hem֙ ʼàşě֣r ẖáֽtĕʼẇ-li֔⁠y wa⁠ʼàşě֖r pá֥̇şĕ̌ʻẇ biֽ⁠y׃"],[33,9,"וְ⁠הָ֣יְתָה לִּ֗⁠י לְ⁠שֵׁ֤ם שָׂשׂוֹן֙ לִ⁠תְהִלָּ֣ה וּ⁠לְ⁠תִפְאֶ֔רֶת לְ⁠כֹ֖ל גּוֹיֵ֣י הָ⁠אָ֑רֶץ אֲשֶׁ֨ר יִשְׁמְע֜וּ אֶת־כָּל־הַ⁠טּוֹבָ֗ה אֲשֶׁ֤ר אָֽנֹכִי֙ עֹשֶׂ֣ה אֹתָ֔⁠ם וּ⁠פָחֲד֣וּ וְ⁠רָֽגְז֗וּ עַ֤ל כָּל־הַ⁠טּוֹבָה֙ וְ⁠עַ֣ל כָּל־הַ⁠שָּׁל֔וֹם אֲשֶׁ֥ר אָֽנֹכִ֖י עֹ֥שֶׂה לָּֽ⁠הּ׃ס","wĕ⁠há֣yĕţáh li̇֗⁠y lĕ⁠şé֤̌m şá̂ş̂wòn֙ li⁠ţĕhilá֣̇h ẇ⁠lĕ⁠ţipĕʼe֔reţ lĕ⁠kò֖l ġwòyé֣y há⁠ʼá֑reẕ ʼàşě֨r yişĕ̌mĕʻ֜ẇ ʼeţ-ká̇l-ha⁠ṫwòbá֗h ʼàşě֤r ʼáֽnòkiy֙ ʻòşê֣h ʼòţá֔⁠m ẇ⁠páẖàd֣ẇ wĕ⁠ráֽgĕz֗ẇ ʻa֤l ká̇l-ha⁠ṫwòbáh֙ wĕ⁠ʻa֣l ká̇l-ha⁠şá̇̌l֔wòm ʼàşě֥r ʼáֽnòki֖y ʻò֥şêh láֽ̇⁠ḣ׃s"],[33,10,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה עוֹד֮ יִשָּׁמַ֣ע בַּ⁠מָּקוֹם־הַ⁠זֶּה֒ אֲשֶׁר֙ אַתֶּ֣ם אֹֽמְרִ֔ים חָרֵ֣ב ה֔וּא מֵ⁠אֵ֥ין אָדָ֖ם וּ⁠מֵ⁠אֵ֣ין בְּהֵמָ֑ה בְּ⁠עָרֵ֤י יְהוּדָה֙ וּ⁠בְ⁠חֻצ֣וֹת יְרוּשָׁלִַ֔ם הַֽ⁠נְשַׁמּ֗וֹת מֵ⁠אֵ֥ין אָדָ֛ם וּ⁠מֵ⁠אֵ֥ין יוֹשֵׁ֖ב וּ⁠מֵ⁠אֵ֥ין בְּהֵמָֽה׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʻwòd֮ yişá̇̌ma֣ʻ bȧ⁠má̇qwòm-ha⁠zėh֒ ʼàşěr֙ ʼaţė֣m ʼòֽmĕri֔ym ẖáré֣b h֔ẇʼ mé⁠ʼé֥yn ʼádá֖m ẇ⁠mé⁠ʼé֣yn bĕ̇hémá֑h bĕ̇⁠ʻáré֤y yĕhẇdáh֙ ẇ⁠bĕ⁠ẖuẕ֣wòţ yĕrẇşá̌lia֔m haֽ⁠nĕşǎṁ֗wòţ mé⁠ʼé֥yn ʼádá֛m ẇ⁠mé⁠ʼé֥yn ywòşé֖̌b ẇ⁠mé⁠ʼé֥yn bĕ̇hémáֽh׃"],[33,11,"ק֣וֹל שָׂשׂ֞וֹן וְ⁠ק֣וֹל שִׂמְחָ֗ה ק֣וֹל חָתָן֮ וְ⁠ק֣וֹל כַּלָּה֒ ק֣וֹל אֹמְרִ֡ים הוֹדוּ֩ אֶת־יְהוָ֨ה צְבָא֜וֹת כִּֽי־ט֤וֹב יְהוָה֙ כִּֽי־לְ⁠עוֹלָ֣ם חַסְדּ֔⁠וֹ מְבִאִ֥ים תּוֹדָ֖ה בֵּ֣ית יְהוָ֑ה כִּֽי־אָשִׁ֧יב אֶת־שְׁבוּת־הָ⁠אָ֛רֶץ כְּ⁠בָ⁠רִאשֹׁנָ֖ה אָמַ֥ר יְהוָֽה׃ס","q֣wòl şá̂ş̂֞wòn wĕ⁠q֣wòl şîmĕẖá֗h q֣wòl ẖáţán֮ wĕ⁠q֣wòl kȧlá̇h֒ q֣wòl ʼòmĕri֡ym hwòdẇ֩ ʼeţ-yĕhwá֨h ẕĕbáʼ֜wòţ kiֽ̇y-t֤wòb yĕhwáh֙ kiֽ̇y-lĕ⁠ʻwòlá֣m ẖasĕḋ֔⁠wò mĕbiʼi֥ym ţ̇wòdá֖h bé֣̇yţ yĕhwá֑h kiֽ̇y-ʼáşǐ֧yb ʼeţ-şĕ̌bẇţ-há⁠ʼá֛reẕ kĕ̇⁠bá⁠riʼşò̌ná֖h ʼáma֥r yĕhwáֽh׃s"],[33,12,"כֹּֽה־אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ ע֞וֹד יִֽהְיֶ֣ה ׀ בַּ⁠מָּק֣וֹם הַ⁠זֶּ֗ה הֶ⁠חָרֵ֛ב מֵֽ⁠אֵין־אָדָ֥ם וְ⁠עַד־בְּהֵמָ֖ה וּ⁠בְ⁠כָל־עָרָ֑י⁠ו נְוֵ֣ה רֹעִ֔ים מַרְבִּצִ֖ים צֹֽאן׃","kòֽ̇h-ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ ʻ֞wòd yiֽhĕye֣h ׀ bȧ⁠má̇q֣wòm ha⁠zė֗h he⁠ẖáré֛b méֽ⁠ʼéyn-ʼádá֥m wĕ⁠ʻad-bĕ̇hémá֖h ẇ⁠bĕ⁠kál-ʻárá֑y⁠w nĕwé֣h ròʻi֔ym marĕbi̇ẕi֖ym ẕòֽʼn׃"],[33,13,"בְּ⁠עָרֵ֨י הָ⁠הָ֜ר בְּ⁠עָרֵ֤י הַ⁠שְּׁפֵלָה֙ וּ⁠בְ⁠עָרֵ֣י הַ⁠נֶּ֔גֶב וּ⁠בְ⁠אֶ֧רֶץ בִּנְיָמִ֛ן וּ⁠בִ⁠סְבִיבֵ֥י יְרוּשָׁלִַ֖ם וּ⁠בְ⁠עָרֵ֣י יְהוּדָ֑ה עֹ֣ד תַּעֲבֹ֧רְנָה הַ⁠צֹּ֛אן עַל־יְדֵ֥י מוֹנֶ֖ה אָמַ֥ר יְהוָֽה׃ס","bĕ̇⁠ʻáré֨y há⁠há֜r bĕ̇⁠ʻáré֤y ha⁠şĕ̇̌péláh֙ ẇ⁠bĕ⁠ʻáré֣y ha⁠nė֔geb ẇ⁠bĕ⁠ʼe֧reẕ bi̇nĕyámi֛n ẇ⁠bi⁠sĕbiybé֥y yĕrẇşá̌lia֖m ẇ⁠bĕ⁠ʻáré֣y yĕhẇdá֑h ʻò֣d ţȧʻàbò֧rĕnáh ha⁠ẕò֛̇ʼn ʻal-yĕdé֥y mwòne֖h ʼáma֥r yĕhwáֽh׃s"],[33,14,"הִנֵּ֛ה יָמִ֥ים בָּאִ֖ים נְאֻם־יְהוָ֑ה וַ⁠הֲקִֽמֹתִי֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠טּ֔וֹב אֲשֶׁ֥ר דִּבַּ֛רְתִּי אֶל־בֵּ֥ית יִשְׂרָאֵ֖ל וְ⁠עַל־בֵּ֥ית יְהוּדָֽה׃","hiné֛̇h yámi֥ym bá̇ʼi֖ym nĕʼum-yĕhwá֑h wa⁠hàqֽimòţiy֙ ʼeţ-ha⁠dá̇bá֣r ha⁠ṫ֔wòb ʼàşě֥r di̇bȧ֛rĕţi̇y ʼel-bé֥̇yţ yişĕ̂ráʼé֖l wĕ⁠ʻal-bé֥̇yţ yĕhẇdáֽh׃"],[33,15,"בַּ⁠יָּמִ֤ים הָ⁠הֵם֙ וּ⁠בָ⁠עֵ֣ת הַ⁠הִ֔יא אַצְמִ֥יחַ לְ⁠דָוִ֖ד צֶ֣מַח צְדָקָ֑ה וְ⁠עָשָׂ֛ה מִשְׁפָּ֥ט וּ⁠צְדָקָ֖ה בָּ⁠אָֽרֶץ׃","bȧ⁠yá̇mi֤ym há⁠hém֙ ẇ⁠bá⁠ʻé֣ţ ha⁠hi֔yʼ ʼaẕĕmi֥yẖa lĕ⁠dáwi֖d ẕe֣maẖ ẕĕdáqá֑h wĕ⁠ʻáşá֛̂h mişĕ̌pá֥̇t ẇ⁠ẕĕdáqá֖h bá̇⁠ʼáֽreẕ׃"],[33,16,"בַּ⁠יָּמִ֤ים הָ⁠הֵם֙ תִּוָּשַׁ֣ע יְהוּדָ֔ה וִ⁠ירוּשָׁלִַ֖ם תִּשְׁכּ֣וֹן לָ⁠בֶ֑טַח וְ⁠זֶ֥ה אֲשֶׁר־יִקְרָא־לָ֖⁠הּ יְהוָ֥ה ׀ צִדְקֵֽ⁠נוּ׃ס","bȧ⁠yá̇mi֤ym há⁠hém֙ ţi̇wá̇şǎ֣ʻ yĕhẇdá֔h wi⁠yrẇşá̌lia֖m ţi̇şĕ̌k֣̇wòn lá⁠be֑taẖ wĕ⁠ze֥h ʼàşěr-yiqĕráʼ-lá֖⁠ḣ yĕhwá֥h ׀ ẕidĕqéֽ⁠nẇ׃s"],[33,17,"כִּי־כֹ֖ה אָמַ֣ר יְהוָ֑ה לֹֽא־יִכָּרֵ֣ת לְ⁠דָוִ֔ד אִ֕ישׁ יֹשֵׁ֖ב עַל־כִּסֵּ֥א בֵֽית־יִשְׂרָאֵֽל׃","ki̇y-kò֖h ʼáma֣r yĕhwá֑h lòֽʼ-yiká̇ré֣ţ lĕ⁠dáwi֔d ʼi֕yş̌ yòşé֖̌b ʻal-ki̇sé֥̇ʼ béֽyţ-yişĕ̂ráʼéֽl׃"],[33,18,"וְ⁠לַ⁠כֹּהֲנִים֙ הַ⁠לְוִיִּ֔ם לֹֽא־יִכָּרֵ֥ת אִ֖ישׁ מִ⁠לְּ⁠פָנָ֑⁠י מַעֲלֶ֨ה עוֹלָ֜ה וּ⁠מַקְטִ֥יר מִנְחָ֛ה וְ⁠עֹ֥שֶׂה־זֶּ֖בַח כָּל־הַ⁠יָּמִֽים׃ס","wĕ⁠la⁠kò̇hàniym֙ ha⁠lĕwiyi̇֔m lòֽʼ-yiká̇ré֥ţ ʼi֖yş̌ mi⁠lĕ̇⁠páná֑⁠y maʻàle֨h ʻwòlá֜h ẇ⁠maqĕti֥yr minĕẖá֛h wĕ⁠ʻò֥şêh-zė֖baẖ ká̇l-ha⁠yá̇miֽym׃s"],[33,19,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ לֵ⁠אמֽוֹר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ lé⁠ʼmֽwòr׃"],[33,20,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה אִם־תָּפֵ֨רוּ֙ אֶת־בְּרִיתִ֣⁠י הַ⁠יּ֔וֹם וְ⁠אֶת־בְּרִיתִ֖⁠י הַ⁠לָּ֑יְלָה וּ⁠לְ⁠בִלְתִּ֛י הֱי֥וֹת יֽוֹמָם־וָ⁠לַ֖יְלָה בְּ⁠עִתָּֽ⁠ם׃","kò֚̇h ʼáma֣r yĕhwá֔h ʼim-ţá̇pé֨rẇ֙ ʼeţ-bĕ̇riyţi֣⁠y ha⁠ẏ֔wòm wĕ⁠ʼeţ-bĕ̇riyţi֖⁠y ha⁠lá֑̇yĕláh ẇ⁠lĕ⁠bilĕţi֛̇y hèy֥wòţ yֽwòmám-wá⁠la֖yĕláh bĕ̇⁠ʻiţáֽ̇⁠m׃"],[33,21,"גַּם־בְּרִיתִ֤⁠י תֻפַר֙ אֶת־דָּוִ֣ד עַבְדִּ֔⁠י מִ⁠הְיֽוֹת־ל֥⁠וֹ בֵ֖ן מֹלֵ֣ךְ עַל־כִּסְא֑⁠וֹ וְ⁠אֶת־הַ⁠לְוִיִּ֥ם הַ⁠כֹּהֲנִ֖ים מְשָׁרְתָֽ⁠י׃","gȧm-bĕ̇riyţi֤⁠y ţupar֙ ʼeţ-dá̇wi֣d ʻabĕdi̇֔⁠y mi⁠hĕyֽwòţ-l֥⁠wò bé֖n mòlé֣kĕ ʻal-ki̇sĕʼ֑⁠wò wĕ⁠ʼeţ-ha⁠lĕwiyi֥̇m ha⁠kò̇hàni֖ym mĕşá̌rĕţáֽ⁠y׃"],[33,22,"אֲשֶׁ֤ר לֹֽא־יִסָּפֵר֙ צְבָ֣א הַ⁠שָּׁמַ֔יִם וְ⁠לֹ֥א יִמַּ֖ד ח֣וֹל הַ⁠יָּ֑ם כֵּ֣ן אַרְבֶּ֗ה אֶת־זֶ֨רַע֙ דָּוִ֣ד עַבְדִּ֔⁠י וְ⁠אֶת־הַ⁠לְוִיִּ֖ם מְשָׁרְתֵ֥י אֹתִֽ⁠י׃ס","ʼàşě֤r lòֽʼ-yisá̇pér֙ ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim wĕ⁠lò֥ʼ yimȧ֖d ẖ֣wòl ha⁠yá֑̇m ké֣̇n ʼarĕbė֗h ʼeţ-ze֨raʻ֙ dá̇wi֣d ʻabĕdi̇֔⁠y wĕ⁠ʼeţ-ha⁠lĕwiyi֖̇m mĕşá̌rĕţé֥y ʼòţiֽ⁠y׃s"],[33,23,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ lé⁠ʼmòֽr׃"],[33,24,"הֲ⁠ל֣וֹא רָאִ֗יתָ מָֽה־הָ⁠עָ֤ם הַ⁠זֶּה֙ דִּבְּר֣וּ לֵ⁠אמֹ֔ר שְׁתֵּ֣י הַ⁠מִּשְׁפָּח֗וֹת אֲשֶׁ֨ר בָּחַ֧ר יְהוָ֛ה בָּ⁠הֶ֖ם וַ⁠יִּמְאָסֵ֑⁠ם וְ⁠אֶת־עַמִּ⁠י֙ יִנְאָצ֔וּ⁠ן מִֽ⁠הְי֥וֹת ע֖וֹד גּ֥וֹי לִ⁠פְנֵי⁠הֶֽם׃ס","hà⁠l֣wòʼ ráʼi֗yţá máֽh-há⁠ʻá֤m ha⁠zėh֙ di̇bĕ̇r֣ẇ lé⁠ʼmò֔r şĕ̌ţé֣̇y ha⁠mi̇şĕ̌pá̇ẖ֗wòţ ʼàşě֨r bá̇ẖa֧r yĕhwá֛h bá̇⁠he֖m wa⁠yi̇mĕʼásé֑⁠m wĕ⁠ʼeţ-ʻami̇⁠y֙ yinĕʼáẕ֔ẇ⁠n miֽ⁠hĕy֥wòţ ʻ֖wòd ġ֥wòy li⁠pĕnéy⁠heֽm׃s"],[33,25,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה אִם־לֹ֥א בְרִיתִ֖⁠י יוֹמָ֣ם וָ⁠לָ֑יְלָה חֻקּ֛וֹת שָׁמַ֥יִם וָ⁠אָ֖רֶץ לֹא־שָֽׂמְתִּי׃","kò֚̇h ʼáma֣r yĕhwá֔h ʼim-lò֥ʼ bĕriyţi֖⁠y ywòmá֣m wá⁠lá֑yĕláh ẖuq֛̇wòţ şá̌ma֥yim wá⁠ʼá֖reẕ lòʼ-şáֽ̂mĕţi̇y׃"],[33,26,"גַּם־זֶ֣רַע יַעֲקוֹב֩ וְ⁠דָוִ֨ד עַבְדִּ֜⁠י אֶמְאַ֗ס מִ⁠קַּ֤חַת מִ⁠זַּרְע⁠וֹ֙ מֹֽשְׁלִ֔ים אֶל־זֶ֥רַע אַבְרָהָ֖ם יִשְׂחָ֣ק וְ⁠יַעֲקֹ֑ב כִּֽי־אשוב אֶת־שְׁבוּתָ֖⁠ם וְ⁠רִחַמְתִּֽי⁠ם׃ס","gȧm-ze֣raʻ yaʻàqwòb֩ wĕ⁠dáwi֨d ʻabĕdi̇֜⁠y ʼemĕʼa֗s mi⁠qȧ֤ẖaţ mi⁠zȧrĕʻ⁠wò֙ mòֽşĕ̌li֔ym ʼel-ze֥raʻ ʼabĕráhá֖m yişĕ̂ẖá֣q wĕ⁠yaʻàqò֑b kiֽ̇y-ʼşwb ʼeţ-şĕ̌bẇţá֖⁠m wĕ⁠riẖamĕţiֽ̇y⁠m׃s"],[34,1,"הַ⁠דָּבָ֛ר אֲשֶׁר־הָיָ֥ה אֶֽל־יִרְמְיָ֖הוּ מֵ⁠אֵ֣ת יְהוָ֑ה וּ⁠נְבוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֣ל ׀ וְ⁠כָל־חֵיל֡⁠וֹ וְ⁠כָל־מַמְלְכ֣וֹת אֶרֶץ֩ מֶמְשֶׁ֨לֶת יָד֜⁠וֹ וְ⁠כָל־הָ⁠עַמִּ֗ים נִלְחָמִ֧ים עַל־יְרוּשָׁלִַ֛ם וְ⁠עַל־כָּל־עָרֶ֖י⁠הָ לֵ⁠אמֹֽר׃","ha⁠dá̇bá֛r ʼàşěr-háyá֥h ʼeֽl-yirĕmĕyá֖hẇ mé⁠ʼé֣ţ yĕhwá֑h ẇ⁠nĕbẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇be֣l ׀ wĕ⁠kál-ẖéyl֡⁠wò wĕ⁠kál-mamĕlĕk֣wòţ ʼereẕ֩ memĕşě֨leţ yád֜⁠wò wĕ⁠kál-há⁠ʻami̇֗ym nilĕẖámi֧ym ʻal-yĕrẇşá̌lia֛m wĕ⁠ʻal-ká̇l-ʻáre֖y⁠há lé⁠ʼmòֽr׃"],[34,2,"כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הָלֹךְ֙ וְ⁠אָ֣מַרְתָּ֔ אֶל־צִדְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֨י נֹתֵ֜ן אֶת־הָ⁠עִ֤יר הַ⁠זֹּאת֙ בְּ⁠יַ֣ד מֶֽלֶךְ־בָּבֶ֔ל וּ⁠שְׂרָפָ֖⁠הּ בָּ⁠אֵֽשׁ׃","kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hálòkĕ֙ wĕ⁠ʼá֣marĕţá̇֔ ʼel-ẕidĕqiyá֖̇hẇ me֣lekĕ yĕhẇdá֑h wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֨y nòţé֜n ʼeţ-há⁠ʻi֤yr ha⁠zò̇ʼţ֙ bĕ̇⁠ya֣d meֽlekĕ-bá̇be֔l ẇ⁠şĕ̂rápá֖⁠ḣ bá̇⁠ʼéֽş̌׃"],[34,3,"וְ⁠אַתָּ֗ה לֹ֚א תִמָּלֵט֙ מִ⁠יָּד֔⁠וֹ כִּ֚י תָּפֹ֣שׂ תִּתָּפֵ֔שׂ וּ⁠בְ⁠יָד֖⁠וֹ תִּנָּתֵ֑ן וְֽ֠⁠עֵינֶי⁠ךָ אֶת־עֵינֵ֨י מֶֽלֶךְ־בָּבֶ֜ל תִּרְאֶ֗ינָה וּ⁠פִ֛י⁠הוּ אֶת־פִּ֥י⁠ךָ יְדַבֵּ֖ר וּ⁠בָבֶ֥ל תָּבֽוֹא׃","wĕ⁠ʼaţá̇֗h lò֚ʼ ţimá̇lét֙ mi⁠yá̇d֔⁠wò ki֚̇y ţá̇pò֣ş̂ ţi̇ţá̇pé֔ş̂ ẇ⁠bĕ⁠yád֖⁠wò ţi̇ná̇ţé֑n wĕֽ֠⁠ʻéyney⁠ká ʼeţ-ʻéyné֨y meֽlekĕ-bá̇be֜l ţi̇rĕʼe֗ynáh ẇ⁠pi֛y⁠hẇ ʼeţ-pi֥̇y⁠ká yĕdabé֖̇r ẇ⁠bábe֥l ţá̇bֽwòʼ׃"],[34,4,"אַ֚ךְ שְׁמַ֣ע דְּבַר־יְהוָ֔ה צִדְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה כֹּֽה־אָמַ֤ר יְהוָה֙ עָלֶ֔י⁠ךָ לֹ֥א תָמ֖וּת בֶּ⁠חָֽרֶב׃","ʼa֚kĕ şĕ̌ma֣ʻ dĕ̇bar-yĕhwá֔h ẕidĕqiyá֖̇hẇ me֣lekĕ yĕhẇdá֑h kòֽ̇h-ʼáma֤r yĕhwáh֙ ʻále֔y⁠ká lò֥ʼ ţám֖ẇţ bė⁠ẖáֽreb׃"],[34,5,"בְּ⁠שָׁל֣וֹם תָּמ֗וּת וּֽ⁠כְ⁠מִשְׂרְפ֣וֹת אֲ֠בוֹתֶי⁠ךָ הַ⁠מְּלָכִ֨ים הָ⁠רִֽאשֹׁנִ֜ים אֲשֶׁר־הָי֣וּ לְ⁠פָנֶ֗י⁠ךָ כֵּ֚ן יִשְׂרְפוּ־לָ֔⁠ךְ וְ⁠ה֥וֹי אָד֖וֹן יִסְפְּדוּ־לָ֑⁠ךְ כִּֽי־דָבָ֥ר אֲנִֽי־דִבַּ֖רְתִּי נְאֻם־יְהוָֽה׃ס","bĕ̇⁠şá̌l֣wòm ţá̇m֗ẇţ ẇֽ⁠kĕ⁠mişĕ̂rĕp֣wòţ ʼà֠bwòţey⁠ká ha⁠mĕ̇láki֨ym há⁠riֽʼşò̌ni֜ym ʼàşěr-háy֣ẇ lĕ⁠páne֗y⁠ká ké֚̇n yişĕ̂rĕpẇ-lá֔⁠kĕ wĕ⁠h֥wòy ʼád֖wòn yisĕpĕ̇dẇ-lá֑⁠kĕ kiֽ̇y-dábá֥r ʼàniֽy-dibȧ֖rĕţi̇y nĕʼum-yĕhwáֽh׃s"],[34,6,"וַ⁠יְדַבֵּר֙ יִרְמְיָ֣הוּ הַ⁠נָּבִ֔יא אֶל־צִדְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה אֵ֛ת כָּל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yĕdabé̇r֙ yirĕmĕyá֣hẇ ha⁠ná̇bi֔yʼ ʼel-ẕidĕqiyá֖̇hẇ me֣lekĕ yĕhẇdá֑h ʼé֛ţ ká̇l-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh bi̇⁠yrẇşá̌liáֽm׃"],[34,7,"וְ⁠חֵ֣יל מֶֽלֶךְ־בָּבֶ֗ל נִלְחָמִים֙ עַל־יְר֣וּשָׁלִַ֔ם וְ⁠עַ֛ל כָּל־עָרֵ֥י יְהוּדָ֖ה הַ⁠נּֽוֹתָר֑וֹת אֶל־לָכִישׁ֙ וְ⁠אֶל־עֲזֵקָ֔ה כִּ֣י הֵ֗נָּה נִשְׁאֲר֛וּ בְּ⁠עָרֵ֥י יְהוּדָ֖ה עָרֵ֥י מִבְצָֽר׃פ","wĕ⁠ẖé֣yl meֽlekĕ-bá̇be֗l nilĕẖámiym֙ ʻal-yĕr֣ẇşá̌lia֔m wĕ⁠ʻa֛l ká̇l-ʻáré֥y yĕhẇdá֖h ha⁠ṅֽwòţár֑wòţ ʼel-lákiyş̌֙ wĕ⁠ʼel-ʻàzéqá֔h ki֣̇y hé֗ná̇h nişĕ̌ʼàr֛ẇ bĕ̇⁠ʻáré֥y yĕhẇdá֖h ʻáré֥y mibĕẕáֽr׃p"],[34,8,"הַ⁠דָּבָ֛ר אֲשֶׁר־הָיָ֥ה אֶֽל־יִרְמְיָ֖הוּ מֵ⁠אֵ֣ת יְהוָ֑ה אַחֲרֵ֡י כְּרֹת֩ הַ⁠מֶּ֨לֶךְ צִדְקִיָּ֜הוּ בְּרִ֗ית אֶת־כָּל־הָ⁠עָם֙ אֲשֶׁ֣ר בִּ⁠ירֽוּשָׁלִַ֔ם לִ⁠קְרֹ֥א לָ⁠הֶ֖ם דְּרֽוֹר׃","ha⁠dá̇bá֛r ʼàşěr-háyá֥h ʼeֽl-yirĕmĕyá֖hẇ mé⁠ʼé֣ţ yĕhwá֑h ʼaẖàré֡y kĕ̇ròţ֩ ha⁠mė֨lekĕ ẕidĕqiyá̇֜hẇ bĕ̇ri֗yţ ʼeţ-ká̇l-há⁠ʻám֙ ʼàşě֣r bi̇⁠yrֽẇşá̌lia֔m li⁠qĕrò֥ʼ lá⁠he֖m dĕ̇rֽwòr׃"],[34,9,"לְ֠⁠שַׁלַּח אִ֣ישׁ אֶת־עַבְדּ֞⁠וֹ וְ⁠אִ֧ישׁ אֶת־שִׁפְחָת֛⁠וֹ הָ⁠עִבְרִ֥י וְ⁠הָ⁠עִבְרִיָּ֖ה חָפְשִׁ֑ים לְ⁠בִלְתִּ֧י עֲבָד־בָּ֛⁠ם בִּ⁠יהוּדִ֥י אָחִ֖י⁠הוּ אִֽישׁ׃","lĕ֠⁠şǎlȧẖ ʼi֣yş̌ ʼeţ-ʻabĕḋ֞⁠wò wĕ⁠ʼi֧yş̌ ʼeţ-şǐpĕẖáţ֛⁠wò há⁠ʻibĕri֥y wĕ⁠há⁠ʻibĕriyá֖̇h ẖápĕşǐ֑ym lĕ⁠bilĕţi֧̇y ʻàbád-bá֛̇⁠m bi̇⁠yhẇdi֥y ʼáẖi֖y⁠hẇ ʼiֽyş̌׃"],[34,10,"וַ⁠יִּשְׁמְעוּ֩ כָל־הַ⁠שָּׂרִ֨ים וְ⁠כָל־הָ⁠עָ֜ם אֲשֶׁר־בָּ֣אוּ בַ⁠בְּרִ֗ית לְ֠⁠שַׁלַּח אִ֣ישׁ אֶת־עַבְדּ֞⁠וֹ וְ⁠אִ֤ישׁ אֶת־שִׁפְחָת⁠וֹ֙ חָפְשִׁ֔ים לְ⁠בִלְתִּ֥י עֲבָד־בָּ֖⁠ם ע֑וֹד וַֽ⁠יִּשְׁמְע֖וּ וַ⁠יְשַׁלֵּֽחוּ׃","wa⁠yi̇şĕ̌mĕʻẇ֩ kál-ha⁠şá̇̂ri֨ym wĕ⁠kál-há⁠ʻá֜m ʼàşěr-bá֣̇ʼẇ ba⁠bĕ̇ri֗yţ lĕ֠⁠şǎlȧẖ ʼi֣yş̌ ʼeţ-ʻabĕḋ֞⁠wò wĕ⁠ʼi֤yş̌ ʼeţ-şǐpĕẖáţ⁠wò֙ ẖápĕşǐ֔ym lĕ⁠bilĕţi֥̇y ʻàbád-bá֖̇⁠m ʻ֑wòd waֽ⁠yi̇şĕ̌mĕʻ֖ẇ wa⁠yĕşǎléֽ̇ẖẇ׃"],[34,11,"וַ⁠יָּשׁ֨וּבוּ֙ אַחֲרֵי־כֵ֔ן וַ⁠יָּשִׁ֗בוּ אֶת־הָֽ⁠עֲבָדִים֙ וְ⁠אֶת־הַ⁠שְּׁפָח֔וֹת אֲשֶׁ֥ר שִׁלְּח֖וּ חָפְשִׁ֑ים ו⁠יכבישו⁠ם לַ⁠עֲבָדִ֖ים וְ⁠לִ⁠שְׁפָחֽוֹת׃ס","wa⁠yá̇ş̌֨ẇbẇ֙ ʼaẖàréy-ké֔n wa⁠yá̇şǐ֗bẇ ʼeţ-háֽ⁠ʻàbádiym֙ wĕ⁠ʼeţ-ha⁠şĕ̇̌páẖ֔wòţ ʼàşě֥r şǐlĕ̇ẖ֖ẇ ẖápĕşǐ֑ym w⁠ykbyşw⁠m la⁠ʻàbádi֖ym wĕ⁠li⁠şĕ̌páẖֽwòţ׃s"],[34,12,"וַ⁠יְהִ֤י דְבַר־יְהוָה֙ אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕhi֤y dĕbar-yĕhwáh֙ ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[34,13,"כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אָנֹכִ֗י כָּרַ֤תִּֽי בְרִית֙ אֶת־אֲב֣וֹתֵי⁠כֶ֔ם בְּ⁠י֨וֹם הוֹצִאִ֤⁠י אוֹתָ⁠ם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם מִ⁠בֵּ֥ית עֲבָדִ֖ים לֵ⁠אמֹֽר׃","kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼánòki֗y ká̇ra֤ţiֽ̇y bĕriyţ֙ ʼeţ-ʼàb֣wòţéy⁠ke֔m bĕ̇⁠y֨wòm hwòẕiʼi֤⁠y ʼwòţá⁠m֙ mé⁠ʼe֣reẕ miẕĕra֔yim mi⁠bé֥̇yţ ʻàbádi֖ym lé⁠ʼmòֽr׃"],[34,14,"מִ⁠קֵּ֣ץ שֶׁ֣בַע שָׁנִ֡ים תְּֽשַׁלְּח֡וּ אִישׁ֩ אֶת־אָחִ֨י⁠ו הָ⁠עִבְרִ֜י אֲשֶֽׁר־יִמָּכֵ֣ר לְ⁠ךָ֗ וַ⁠עֲבָֽדְ⁠ךָ֙ שֵׁ֣שׁ שָׁנִ֔ים וְ⁠שִׁלַּחְתּ֥⁠וֹ חָפְשִׁ֖י מֵֽ⁠עִמָּ֑⁠ךְ וְ⁠לֹֽא־שָׁמְע֤וּ אֲבֽוֹתֵי⁠כֶם֙ אֵלַ֔⁠י וְ⁠לֹ֥א הִטּ֖וּ אֶת־אָזְנָֽ⁠ם׃","mi⁠qé֣̇ẕ şě֣baʻ şá̌ni֡ym ţĕֽ̇şǎlĕ̇ẖ֡ẇ ʼiyş̌֩ ʼeţ-ʼáẖi֨y⁠w há⁠ʻibĕri֜y ʼàşěֽr-yimá̇ké֣r lĕ⁠ká֗ wa⁠ʻàbáֽdĕ⁠ká֙ şé֣̌ş̌ şá̌ni֔ym wĕ⁠şǐlȧẖĕţ֥̇⁠wò ẖápĕşǐ֖y méֽ⁠ʻimá֑̇⁠kĕ wĕ⁠lòֽʼ-şá̌mĕʻ֤ẇ ʼàbֽwòţéy⁠kem֙ ʼéla֔⁠y wĕ⁠lò֥ʼ hiṫ֖ẇ ʼeţ-ʼázĕnáֽ⁠m׃"],[34,15,"וַ⁠תָּשֻׁ֨בוּ אַתֶּ֜ם הַ⁠יּ֗וֹם וַ⁠תַּעֲשׂ֤וּ אֶת־הַ⁠יָּשָׁר֙ בְּ⁠עֵינַ֔⁠י לִ⁠קְרֹ֥א דְר֖וֹר אִ֣ישׁ לְ⁠רֵעֵ֑⁠הוּ וַ⁠תִּכְרְת֤וּ בְרִית֙ לְ⁠פָנַ֔⁠י בַּ⁠בַּ֕יִת אֲשֶׁר־נִקְרָ֥א שְׁמִ֖⁠י עָלָֽי⁠ו׃","wa⁠ţá̇şǔ֨bẇ ʼaţė֜m ha⁠ẏ֗wòm wa⁠ţȧʻàş֤̂ẇ ʼeţ-ha⁠yá̇şá̌r֙ bĕ̇⁠ʻéyna֔⁠y li⁠qĕrò֥ʼ dĕr֖wòr ʼi֣yş̌ lĕ⁠réʻé֑⁠hẇ wa⁠ţi̇kĕrĕţ֤ẇ bĕriyţ֙ lĕ⁠pána֔⁠y bȧ⁠bȧ֕yiţ ʼàşěr-niqĕrá֥ʼ şĕ̌mi֖⁠y ʻáláֽy⁠w׃"],[34,16,"וַ⁠תָּשֻׁ֨בוּ֙ וַ⁠תְּחַלְּל֣וּ אֶת־שְׁמִ֔⁠י וַ⁠תָּשִׁ֗בוּ אִ֤ישׁ אֶת־עַבְדּ⁠וֹ֙ וְ⁠אִ֣ישׁ אֶת־שִׁפְחָת֔⁠וֹ אֲשֶׁר־שִׁלַּחְתֶּ֥ם חָפְשִׁ֖ים לְ⁠נַפְשָׁ֑⁠ם וַ⁠תִּכְבְּשׁ֣וּ אֹתָ֔⁠ם לִֽ⁠הְי֣וֹת לָ⁠כֶ֔ם לַ⁠עֲבָדִ֖ים וְ⁠לִ⁠שְׁפָחֽוֹת׃ס","wa⁠ţá̇şǔ֨bẇ֙ wa⁠ţĕ̇ẖalĕ̇l֣ẇ ʼeţ-şĕ̌mi֔⁠y wa⁠ţá̇şǐ֗bẇ ʼi֤yş̌ ʼeţ-ʻabĕḋ⁠wò֙ wĕ⁠ʼi֣yş̌ ʼeţ-şǐpĕẖáţ֔⁠wò ʼàşěr-şǐlȧẖĕţė֥m ẖápĕşǐ֖ym lĕ⁠napĕşá֑̌⁠m wa⁠ţi̇kĕbĕ̇ş֣̌ẇ ʼòţá֔⁠m liֽ⁠hĕy֣wòţ lá⁠ke֔m la⁠ʻàbádi֖ym wĕ⁠li⁠şĕ̌páẖֽwòţ׃s"],[34,17,"לָ⁠כֵן֮ כֹּה־אָמַ֣ר יְהוָה֒ אַתֶּם֙ לֹֽא־שְׁמַעְתֶּ֣ם אֵלַ֔⁠י לִ⁠קְרֹ֣א דְר֔וֹר אִ֥ישׁ לְ⁠אָחִ֖י⁠ו וְ⁠אִ֣ישׁ לְ⁠רֵעֵ֑⁠הוּ הִנְ⁠נִ֣י קֹרֵא֩ לָ⁠כֶ֨ם דְּר֜וֹר נְאֻם־יְהוָ֗ה אֶל־הַ⁠חֶ֨רֶב֙ אֶל־הַ⁠דֶּ֣בֶר וְ⁠אֶל־הָ⁠רָעָ֔ב וְ⁠נָתַתִּ֤י אֶתְ⁠כֶם֙ ל⁠זועה לְ⁠כֹ֖ל מַמְלְכ֥וֹת הָ⁠אָֽרֶץ׃","lá⁠kén֮ kò̇h-ʼáma֣r yĕhwáh֒ ʼaţėm֙ lòֽʼ-şĕ̌maʻĕţė֣m ʼéla֔⁠y li⁠qĕrò֣ʼ dĕr֔wòr ʼi֥yş̌ lĕ⁠ʼáẖi֖y⁠w wĕ⁠ʼi֣yş̌ lĕ⁠réʻé֑⁠hẇ hinĕ⁠ni֣y qòréʼ֩ lá⁠ke֨m dĕ̇r֜wòr nĕʼum-yĕhwá֗h ʼel-ha⁠ẖe֨reb֙ ʼel-ha⁠dė֣ber wĕ⁠ʼel-há⁠ráʻá֔b wĕ⁠náţaţi֤̇y ʼeţĕ⁠kem֙ l⁠zwʻh lĕ⁠kò֖l mamĕlĕk֥wòţ há⁠ʼáֽreẕ׃"],[34,18,"וְ⁠נָתַתִּ֣י אֶת־הָ⁠אֲנָשִׁ֗ים הָ⁠עֹֽבְרִים֙ אֶת־בְּרִתִ֔⁠י אֲשֶׁ֤ר לֹֽא־הֵקִ֨ימוּ֙ אֶת־דִּבְרֵ֣י הַ⁠בְּרִ֔ית אֲשֶׁ֥ר כָּרְת֖וּ לְ⁠פָנָ֑⁠י הָ⁠עֵ֨גֶל֙ אֲשֶׁ֣ר כָּרְת֣וּ לִ⁠שְׁנַ֔יִם וַ⁠יַּעַבְר֖וּ בֵּ֥ין בְּתָרָֽי⁠ו׃","wĕ⁠náţaţi֣̇y ʼeţ-há⁠ʼànáşǐ֗ym há⁠ʻòֽbĕriym֙ ʼeţ-bĕ̇riţi֔⁠y ʼàşě֤r lòֽʼ-héqi֨ymẇ֙ ʼeţ-di̇bĕré֣y ha⁠bĕ̇ri֔yţ ʼàşě֥r ká̇rĕţ֖ẇ lĕ⁠páná֑⁠y há⁠ʻé֨gel֙ ʼàşě֣r ká̇rĕţ֣ẇ li⁠şĕ̌na֔yim wa⁠yȧʻabĕr֖ẇ bé֥̇yn bĕ̇ţáráֽy⁠w׃"],[34,19,"שָׂרֵ֨י יְהוּדָ֜ה וְ⁠שָׂרֵ֣י יְרוּשָׁלִַ֗ם הַ⁠סָּֽרִסִים֙ וְ⁠הַ⁠כֹּ֣הֲנִ֔ים וְ⁠כֹ֖ל עַ֣ם הָ⁠אָ֑רֶץ הָ⁠עֹ֣בְרִ֔ים בֵּ֖ין בִּתְרֵ֥י הָ⁠עֵֽגֶל׃","şá̂ré֨y yĕhẇdá֜h wĕ⁠şá̂ré֣y yĕrẇşá̌lia֗m ha⁠sáֽ̇risiym֙ wĕ⁠ha⁠kò֣̇hàni֔ym wĕ⁠kò֖l ʻa֣m há⁠ʼá֑reẕ há⁠ʻò֣bĕri֔ym bé֖̇yn bi̇ţĕré֥y há⁠ʻéֽgel׃"],[34,20,"וְ⁠נָתַתִּ֤י אוֹתָ⁠ם֙ בְּ⁠יַ֣ד אֹֽיְבֵי⁠הֶ֔ם וּ⁠בְ⁠יַ֖ד מְבַקְשֵׁ֣י נַפְשָׁ֑⁠ם וְ⁠הָיְתָ֤ה נִבְלָתָ⁠ם֙ לְ⁠מַֽאֲכָ֔ל לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֥ת הָ⁠אָֽרֶץ׃","wĕ⁠náţaţi֤̇y ʼwòţá⁠m֙ bĕ̇⁠ya֣d ʼòֽyĕbéy⁠he֔m ẇ⁠bĕ⁠ya֖d mĕbaqĕşé֣̌y napĕşá֑̌⁠m wĕ⁠háyĕţá֤h nibĕláţá⁠m֙ lĕ⁠maֽʼàká֔l lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֥ţ há⁠ʼáֽreẕ׃"],[34,21,"וְ⁠אֶת־צִדְקִיָּ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה וְ⁠אֶת־שָׂרָ֗י⁠ו אֶתֵּן֙ בְּ⁠יַ֣ד אֹֽיְבֵי⁠הֶ֔ם וּ⁠בְ⁠יַ֖ד מְבַקְשֵׁ֣י נַפְשָׁ֑⁠ם וּ⁠בְ⁠יַד חֵ֚יל מֶ֣לֶךְ בָּבֶ֔ל הָ⁠עֹלִ֖ים מֵ⁠עֲלֵי⁠כֶֽם׃","wĕ⁠ʼeţ-ẕidĕqiyá̇֨hẇ meֽlekĕ-yĕhẇdá֜h wĕ⁠ʼeţ-şá̂rá֗y⁠w ʼeţé̇n֙ bĕ̇⁠ya֣d ʼòֽyĕbéy⁠he֔m ẇ⁠bĕ⁠ya֖d mĕbaqĕşé֣̌y napĕşá֑̌⁠m ẇ⁠bĕ⁠yad ẖé֚yl me֣lekĕ bá̇be֔l há⁠ʻòli֖ym mé⁠ʻàléy⁠keֽm׃"],[34,22,"הִנְ⁠נִ֨י מְצַוֶּ֜ה נְאֻם־יְהוָ֗ה וַ⁠הֲשִׁ֨בֹתִ֜י⁠ם אֶל־הָ⁠עִ֤יר הַ⁠זֹּאת֙ וְ⁠נִלְחֲמ֣וּ עָלֶ֔י⁠הָ וּ⁠לְכָד֖וּ⁠הָ וּ⁠שְׂרָפֻ֣⁠הָ בָ⁠אֵ֑שׁ וְ⁠אֶת־עָרֵ֧י יְהוּדָ֛ה אֶתֵּ֥ן שְׁמָמָ֖ה מֵ⁠אֵ֥ין יֹשֵֽׁב׃פ","hinĕ⁠ni֨y mĕẕawė֜h nĕʼum-yĕhwá֗h wa⁠hàşǐ֨bòţi֜y⁠m ʼel-há⁠ʻi֤yr ha⁠zò̇ʼţ֙ wĕ⁠nilĕẖàm֣ẇ ʻále֔y⁠há ẇ⁠lĕkád֖ẇ⁠há ẇ⁠şĕ̂rápu֣⁠há bá⁠ʼé֑ş̌ wĕ⁠ʼeţ-ʻáré֧y yĕhẇdá֛h ʼeţé֥̇n şĕ̌mámá֖h mé⁠ʼé֥yn yòşéֽ̌b׃p"],[35,1,"הַ⁠דָּבָ֛ר אֲשֶׁר־הָיָ֥ה אֶֽל־יִרְמְיָ֖הוּ מֵ⁠אֵ֣ת יְהוָ֑ה בִּ⁠ימֵ֨י יְהוֹיָקִ֧ים בֶּן־יֹאשִׁיָּ֛הוּ מֶ֥לֶךְ יְהוּדָ֖ה לֵ⁠אמֹֽר׃","ha⁠dá̇bá֛r ʼàşěr-háyá֥h ʼeֽl-yirĕmĕyá֖hẇ mé⁠ʼé֣ţ yĕhwá֑h bi̇⁠ymé֨y yĕhwòyáqi֧ym bėn-yòʼşǐyá֛̇hẇ me֥lekĕ yĕhẇdá֖h lé⁠ʼmòֽr׃"],[35,2,"הָלוֹךְ֮ אֶל־בֵּ֣ית הָ⁠רֵכָבִים֒ וְ⁠דִבַּרְתָּ֣ אוֹתָ֔⁠ם וַ⁠הֲבִֽאוֹתָ⁠ם֙ בֵּ֣ית יְהוָ֔ה אֶל־אַחַ֖ת הַ⁠לְּשָׁכ֑וֹת וְ⁠הִשְׁקִיתָ֥ אוֹתָ֖⁠ם יָֽיִן׃","hálwòkĕ֮ ʼel-bé֣̇yţ há⁠rékábiym֒ wĕ⁠dibȧrĕţá֣̇ ʼwòţá֔⁠m wa⁠hàbiֽʼwòţá⁠m֙ bé֣̇yţ yĕhwá֔h ʼel-ʼaẖa֖ţ ha⁠lĕ̇şá̌k֑wòţ wĕ⁠hişĕ̌qiyţá֥ ʼwòţá֖⁠m yáֽyin׃"],[35,3,"וָ⁠אֶקַּ֞ח אֶת־יַאֲזַנְיָ֤ה בֶֽן־יִרְמְיָ֨הוּ֙ בֶּן־חֲבַצִּנְיָ֔ה וְ⁠אֶת־אֶחָ֖י⁠ו וְ⁠אֶת־כָּל־בָּנָ֑י⁠ו וְ⁠אֵ֖ת כָּל־בֵּ֥ית הָ⁠רֵכָבִֽים׃","wá⁠ʼeqȧ֞ẖ ʼeţ-yaʼàzanĕyá֤h beֽn-yirĕmĕyá֨hẇ֙ bėn-ẖàbaẕi̇nĕyá֔h wĕ⁠ʼeţ-ʼeẖá֖y⁠w wĕ⁠ʼeţ-ká̇l-bá̇ná֑y⁠w wĕ⁠ʼé֖ţ ká̇l-bé֥̇yţ há⁠rékábiֽym׃"],[35,4,"וָ⁠אָבִ֤א אֹתָ⁠ם֙ בֵּ֣ית יְהוָ֔ה אֶל־לִשְׁכַּ֗ת בְּנֵ֛י חָנָ֥ן בֶּן־יִגְדַּלְיָ֖הוּ אִ֣ישׁ הָ⁠אֱלֹהִ֑ים אֲשֶׁר־אֵ֨צֶל֙ לִשְׁכַּ֣ת הַ⁠שָּׂרִ֔ים אֲשֶׁ֣ר מִ⁠מַּ֗עַל לְ⁠לִשְׁכַּ֛ת מַעֲשֵׂיָ֥הוּ בֶן־שַׁלֻּ֖ם שֹׁמֵ֥ר הַ⁠סַּֽף׃","wá⁠ʼábi֤ʼ ʼòţá⁠m֙ bé֣̇yţ yĕhwá֔h ʼel-lişĕ̌kȧ֗ţ bĕ̇né֛y ẖáná֥n bėn-yigĕdȧlĕyá֖hẇ ʼi֣yş̌ há⁠ʼèlòhi֑ym ʼàşěr-ʼé֨ẕel֙ lişĕ̌kȧ֣ţ ha⁠şá̇̂ri֔ym ʼàşě֣r mi⁠mȧ֗ʻal lĕ⁠lişĕ̌kȧ֛ţ maʻàşé̂yá֥hẇ ben-şǎlu֖̇m şò̌mé֥r ha⁠sȧֽp׃"],[35,5,"וָ⁠אֶתֵּ֞ן לִ⁠פְנֵ֣י ׀ בְּנֵ֣י בֵית־הָ⁠רֵכָבִ֗ים גְּבִעִ֛ים מְלֵאִ֥ים יַ֖יִן וְ⁠כֹס֑וֹת וָ⁠אֹמַ֥ר אֲלֵי⁠הֶ֖ם שְׁתוּ־יָֽיִן׃","wá⁠ʼeţé̇֞n li⁠pĕné֣y ׀ bĕ̇né֣y béyţ-há⁠rékábi֗ym gĕ̇biʻi֛ym mĕléʼi֥ym ya֖yin wĕ⁠kòs֑wòţ wá⁠ʼòma֥r ʼàléy⁠he֖m şĕ̌ţẇ-yáֽyin׃"],[35,6,"וַ⁠יֹּאמְר֖וּ לֹ֣א נִשְׁתֶּה־יָּ֑יִן כִּי֩ יוֹנָדָ֨ב בֶּן־רֵכָ֜ב אָבִ֗י⁠נוּ צִוָּ֤ה עָלֵ֨י⁠נוּ֙ לֵ⁠אמֹ֔ר לֹ֧א תִשְׁתּוּ־יַ֛יִן אַתֶּ֥ם וּ⁠בְנֵי⁠כֶ֖ם עַד־עוֹלָֽם׃","wa⁠yò̇ʼmĕr֖ẇ lò֣ʼ nişĕ̌ţėh-yá֑̇yin ki̇y֩ ywònádá֨b bėn-réká֜b ʼábi֗y⁠nẇ ẕiwá֤̇h ʻálé֨y⁠nẇ֙ lé⁠ʼmò֔r lò֧ʼ ţişĕ̌ţ̇ẇ-ya֛yin ʼaţė֥m ẇ⁠bĕnéy⁠ke֖m ʻad-ʻwòláֽm׃"],[35,7,"וּ⁠בַ֣יִת לֹֽא־תִבְנ֗וּ וְ⁠זֶ֤רַע לֹֽא־תִזְרָ֨עוּ֙ וְ⁠כֶ֣רֶם לֹֽא־תִטָּ֔עוּ וְ⁠לֹ֥א יִֽהְיֶ֖ה לָ⁠כֶ֑ם כִּ֠י בָּ⁠אֳהָלִ֤ים תֵּֽשְׁבוּ֙ כָּל־יְמֵי⁠כֶ֔ם לְמַ֨עַן תִּֽחְי֜וּ יָמִ֤ים רַבִּים֙ עַל־פְּנֵ֣י הָ⁠אֲדָמָ֔ה אֲשֶׁ֥ר אַתֶּ֖ם גָּרִ֥ים שָֽׁם׃","ẇ⁠ba֣yiţ lòֽʼ-ţibĕn֗ẇ wĕ⁠ze֤raʻ lòֽʼ-ţizĕrá֨ʻẇ֙ wĕ⁠ke֣rem lòֽʼ-ţitá̇֔ʻẇ wĕ⁠lò֥ʼ yiֽhĕye֖h lá⁠ke֑m ki̇֠y bá̇⁠ʼoháli֤ym ţéֽ̇şĕ̌bẇ֙ ká̇l-yĕméy⁠ke֔m lĕma֨ʻan ţiֽ̇ẖĕy֜ẇ yámi֤ym rabi̇ym֙ ʻal-pĕ̇né֣y há⁠ʼàdámá֔h ʼàşě֥r ʼaţė֖m gá̇ri֥ym şáֽ̌m׃"],[35,8,"וַ⁠נִּשְׁמַ֗ע בְּ⁠ק֨וֹל יְהוֹנָדָ֤ב בֶּן־רֵכָב֙ אָבִ֔י⁠נוּ לְ⁠כֹ֖ל אֲשֶׁ֣ר צִוָּ֑⁠נוּ לְ⁠בִלְתִּ֤י שְׁתֽוֹת־יַ֨יִן֙ כָּל־יָמֵ֔י⁠נוּ אֲנַ֣חְנוּ נָשֵׁ֔י⁠נוּ בָּנֵ֖י⁠נוּ וּ⁠בְנֹתֵֽי⁠נוּ׃","wa⁠ni̇şĕ̌ma֗ʻ bĕ̇⁠q֨wòl yĕhwònádá֤b bėn-rékáb֙ ʼábi֔y⁠nẇ lĕ⁠kò֖l ʼàşě֣r ẕiwá֑̇⁠nẇ lĕ⁠bilĕţi֤̇y şĕ̌ţֽwòţ-ya֨yin֙ ká̇l-yámé֔y⁠nẇ ʼàna֣ẖĕnẇ náşé̌֔y⁠nẇ bá̇né֖y⁠nẇ ẇ⁠bĕnòţéֽy⁠nẇ׃"],[35,9,"וּ⁠לְ⁠בִלְתִּ֛י בְּנ֥וֹת בָּתִּ֖ים לְ⁠שִׁבְתֵּ֑⁠נוּ וְ⁠כֶ֧רֶם וְ⁠שָׂדֶ֛ה וָ⁠זֶ֖רַע לֹ֥א יִֽהְיֶה־לָּֽ⁠נוּ׃","ẇ⁠lĕ⁠bilĕţi֛̇y bĕ̇n֥wòţ bá̇ţi֖̇ym lĕ⁠şǐbĕţé֑̇⁠nẇ wĕ⁠ke֧rem wĕ⁠şá̂de֛h wá⁠ze֖raʻ lò֥ʼ yiֽhĕyeh-láֽ̇⁠nẇ׃"],[35,10,"וַ⁠נֵּ֖שֶׁב בָּֽ⁠אֳהָלִ֑ים וַ⁠נִּשְׁמַ֣ע וַ⁠נַּ֔עַשׂ כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖⁠נוּ יוֹנָדָ֥ב אָבִֽי⁠נוּ׃","wa⁠né֖̇şěb báֽ̇⁠ʼoháli֑ym wa⁠ni̇şĕ̌ma֣ʻ wa⁠nȧ֔ʻaş̂ kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇⁠nẇ ywònádá֥b ʼábiֽy⁠nẇ׃"],[35,11,"וַ⁠יְהִ֗י בַּ⁠עֲל֨וֹת נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶל֮ אֶל־הָ⁠אָרֶץ֒ וַ⁠נֹּ֗אמֶר בֹּ֚אוּ וְ⁠נָב֣וֹא יְרוּשָׁלִַ֔ם מִ⁠פְּנֵי֙ חֵ֣יל הַ⁠כַּשְׂדִּ֔ים וּ⁠מִ⁠פְּנֵ֖י חֵ֣יל אֲרָ֑ם וַ⁠נֵּ֖שֶׁב בִּ⁠ירוּשָׁלִָֽם׃פ","wa⁠yĕhi֗y bȧ⁠ʻàl֨wòţ nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇bel֮ ʼel-há⁠ʼáreẕ֒ wa⁠nò̇֗ʼmer bò֚̇ʼẇ wĕ⁠náb֣wòʼ yĕrẇşá̌lia֔m mi⁠pĕ̇néy֙ ẖé֣yl ha⁠kȧşĕ̂di̇֔ym ẇ⁠mi⁠pĕ̇né֖y ẖé֣yl ʼàrá֑m wa⁠né֖̇şěb bi̇⁠yrẇşá̌liáֽm׃p"],[35,12,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ lé⁠ʼmòֽr׃"],[35,13,"כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הָלֹ֤ךְ וְ⁠אָֽמַרְתָּ֙ לְ⁠אִ֣ישׁ יְהוּדָ֔ה וּ⁠לְ⁠יֽוֹשְׁבֵ֖י יְרֽוּשָׁלִָ֑ם הֲ⁠ל֨וֹא תִקְח֥וּ מוּסָ֛ר לִ⁠שְׁמֹ֥עַ אֶל־דְּבָרַ֖⁠י נְאֻם־יְהוָֽה׃","kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hálò֤kĕ wĕ⁠ʼáֽmarĕţá̇֙ lĕ⁠ʼi֣yş̌ yĕhẇdá֔h ẇ⁠lĕ⁠yֽwòşĕ̌bé֖y yĕrֽẇşá̌liá֑m hà⁠l֨wòʼ ţiqĕẖ֥ẇ mẇsá֛r li⁠şĕ̌mò֥ʻa ʼel-dĕ̇bára֖⁠y nĕʼum-yĕhwáֽh׃"],[35,14,"הוּקַ֡ם אֶת־דִּבְרֵ֣י יְהוֹנָדָ֣ב בֶּן־רֵ֠כָב אֲשֶׁר־צִוָּ֨ה אֶת־בָּנָ֜י⁠ו לְ⁠בִלְתִּ֣י שְׁתֽוֹת־יַ֗יִן וְ⁠לֹ֤א שָׁתוּ֙ עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה כִּ֣י שָֽׁמְע֔וּ אֵ֖ת מִצְוַ֣ת אֲבִי⁠הֶ֑ם וְ⁠אָ֨נֹכִ֜י דִּבַּ֤רְתִּי אֲלֵי⁠כֶם֙ הַשְׁכֵּ֣ם וְ⁠דַבֵּ֔ר וְ⁠לֹ֥א שְׁמַעְתֶּ֖ם אֵלָֽ⁠י׃","hẇqa֡m ʼeţ-di̇bĕré֣y yĕhwònádá֣b bėn-ré֠káb ʼàşěr-ẕiwá̇֨h ʼeţ-bá̇ná֜y⁠w lĕ⁠bilĕţi֣̇y şĕ̌ţֽwòţ-ya֗yin wĕ⁠lò֤ʼ şá̌ţẇ֙ ʻad-ha⁠ẏ֣wòm ha⁠zė֔h ki֣̇y şáֽ̌mĕʻ֔ẇ ʼé֖ţ miẕĕwa֣ţ ʼàbiy⁠he֑m wĕ⁠ʼá֨nòki֜y di̇bȧ֤rĕţi̇y ʼàléy⁠kem֙ haşĕ̌ké֣̇m wĕ⁠dabé̇֔r wĕ⁠lò֥ʼ şĕ̌maʻĕţė֖m ʼéláֽ⁠y׃"],[35,15,"וָ⁠אֶשְׁלַ֣ח אֲלֵי⁠כֶ֣ם אֶת־כָּל־עֲבָדַ֣⁠י הַ⁠נְּבִאִ֣ים ׀ הַשְׁכֵּ֣ים וְ⁠שָׁלֹ֣חַ ׀ לֵ⁠אמֹ֡ר שֻׁבוּ־נָ֡א אִישׁ֩ מִ⁠דַּרְכּ֨⁠וֹ הָ⁠רָעָ֜ה וְ⁠הֵיטִ֣יבוּ מַֽעַלְלֵי⁠כֶ֗ם וְ⁠אַל־תֵּ֨לְכ֜וּ אַחֲרֵ֨י אֱלֹהִ֤ים אֲחֵרִים֙ לְ⁠עָבְדָ֔⁠ם וּ⁠שְׁבוּ֙ אֶל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁר־נָתַ֥תִּי לָ⁠כֶ֖ם וְ⁠לַ⁠אֲבֹֽתֵי⁠כֶ֑ם וְ⁠לֹ֤א הִטִּיתֶם֙ אֶֽת־אָזְנְ⁠כֶ֔ם וְ⁠לֹ֥א שְׁמַעְתֶּ֖ם אֵלָֽ⁠י׃","wá⁠ʼeşĕ̌la֣ẖ ʼàléy⁠ke֣m ʼeţ-ká̇l-ʻàbáda֣⁠y ha⁠nĕ̇biʼi֣ym ׀ haşĕ̌ké֣̇ym wĕ⁠şá̌lò֣ẖa ׀ lé⁠ʼmò֡r şǔbẇ-ná֡ʼ ʼiyş̌֩ mi⁠dȧrĕk̇֨⁠wò há⁠ráʻá֜h wĕ⁠héyti֣ybẇ maֽʻalĕléy⁠ke֗m wĕ⁠ʼal-ţé̇֨lĕk֜ẇ ʼaẖàré֨y ʼèlòhi֤ym ʼàẖériym֙ lĕ⁠ʻábĕdá֔⁠m ẇ⁠şĕ̌bẇ֙ ʼel-há֣⁠ʼàdámá֔h ʼàşěr-náţa֥ţi̇y lá⁠ke֖m wĕ⁠la⁠ʼàbòֽţéy⁠ke֑m wĕ⁠lò֤ʼ hiti̇yţem֙ ʼeֽţ-ʼázĕnĕ⁠ke֔m wĕ⁠lò֥ʼ şĕ̌maʻĕţė֖m ʼéláֽ⁠y׃"],[35,16,"כִּ֣י הֵקִ֗ימוּ בְּנֵי֙ יְהוֹנָדָ֣ב בֶּן־רֵכָ֔ב אֶת־מִצְוַ֥ת אֲבִי⁠הֶ֖ם אֲשֶׁ֣ר צִוָּ֑⁠ם וְ⁠הָ⁠עָ֣ם הַ⁠זֶּ֔ה לֹ֥א שָׁמְע֖וּ אֵלָֽ⁠י׃ס","ki֣̇y héqi֗ymẇ bĕ̇néy֙ yĕhwònádá֣b bėn-réká֔b ʼeţ-miẕĕwa֥ţ ʼàbiy⁠he֖m ʼàşě֣r ẕiwá֑̇⁠m wĕ⁠há⁠ʻá֣m ha⁠zė֔h lò֥ʼ şá̌mĕʻ֖ẇ ʼéláֽ⁠y׃s"],[35,17,"לָ֠⁠כֵן כֹּֽה־אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֤י צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֧י מֵבִ֣יא אֶל־יְהוּדָ֗ה וְ⁠אֶ֤ל כָּל־יֽוֹשְׁבֵי֙ יְר֣וּשָׁלִַ֔ם אֵ֚ת כָּל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר דִּבַּ֖רְתִּי עֲלֵי⁠הֶ֑ם יַ֣עַן דִּבַּ֤רְתִּי אֲלֵי⁠הֶם֙ וְ⁠לֹ֣א שָׁמֵ֔עוּ וָ⁠אֶקְרָ֥א לָ⁠הֶ֖ם וְ⁠לֹ֥א עָנֽוּ׃","lá֠⁠kén kòֽ̇h-ʼáma֨r yĕhwá֜h ʼèlòhé֤y ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֧y mébi֣yʼ ʼel-yĕhẇdá֗h wĕ⁠ʼe֤l ká̇l-yֽwòşĕ̌béy֙ yĕr֣ẇşá̌lia֔m ʼé֚ţ ká̇l-há֣⁠ráʻá֔h ʼàşě֥r di̇bȧ֖rĕţi̇y ʻàléy⁠he֑m ya֣ʻan di̇bȧ֤rĕţi̇y ʼàléy⁠hem֙ wĕ⁠lò֣ʼ şá̌mé֔ʻẇ wá⁠ʼeqĕrá֥ʼ lá⁠he֖m wĕ⁠lò֥ʼ ʻánֽẇ׃"],[35,18,"וּ⁠לְ⁠בֵ֨ית הָ⁠רֵכָבִ֜ים אָמַ֣ר יִרְמְיָ֗הוּ כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל יַ֚עַן אֲשֶׁ֣ר שְׁמַעְתֶּ֔ם עַל־מִצְוַ֖ת יְהוֹנָדָ֣ב אֲבִי⁠כֶ֑ם וַֽ⁠תִּשְׁמְרוּ֙ אֶת־כָּל־מִצְוֺתָ֔י⁠ו וַֽ⁠תַּעֲשׂ֔וּ כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖ה אֶתְ⁠כֶֽם׃ס","ẇ⁠lĕ⁠bé֨yţ há⁠rékábi֜ym ʼáma֣r yirĕmĕyá֗hẇ kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ya֚ʻan ʼàşě֣r şĕ̌maʻĕţė֔m ʻal-miẕĕwa֖ţ yĕhwònádá֣b ʼàbiy⁠ke֑m waֽ⁠ţi̇şĕ̌mĕrẇ֙ ʼeţ-ká̇l-miẕĕwֺţá֔y⁠w waֽ⁠ţȧʻàş̂֔ẇ kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇h ʼeţĕ⁠keֽm׃s"],[35,19,"לָ⁠כֵ֗ן כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל לֹֽא־יִכָּרֵ֨ת אִ֜ישׁ לְ⁠יוֹנָדָ֧ב בֶּן־רֵכָ֛ב עֹמֵ֥ד לְ⁠פָנַ֖⁠י כָּל־הַ⁠יָּמִֽים׃פ","lá⁠ké֗n kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhé֣y yişĕ̂ráʼé֑l lòֽʼ-yiká̇ré֨ţ ʼi֜yş̌ lĕ⁠ywònádá֧b bėn-réká֛b ʻòmé֥d lĕ⁠pána֖⁠y ká̇l-ha⁠yá̇miֽym׃p"],[36,1,"וַֽ⁠יְהִי֙ בַּ⁠שָּׁנָ֣ה הָ⁠רְבִיעִ֔ת לִ⁠יהוֹיָקִ֥ים בֶּן־יֹאשִׁיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה הָיָ֞ה הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ אֶֽל־יִרְמְיָ֔הוּ מֵ⁠אֵ֥ת יְהוָ֖ה לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ bȧ⁠şá̇̌ná֣h há⁠rĕbiyʻi֔ţ li⁠yhwòyáqi֥ym bėn-yòʼşǐyá֖̇hẇ me֣lekĕ yĕhẇdá֑h háyá֞h ha⁠dá̇bá֤r ha⁠zėh֙ ʼeֽl-yirĕmĕyá֔hẇ mé⁠ʼé֥ţ yĕhwá֖h lé⁠ʼmòֽr׃"],[36,2,"קַח־לְ⁠ךָ֮ מְגִלַּת־סֵפֶר֒ וְ⁠כָתַבְתָּ֣ אֵלֶ֗י⁠הָ אֵ֣ת כָּל־הַ⁠דְּבָרִ֞ים אֲשֶׁר־דִּבַּ֧רְתִּי אֵלֶ֛י⁠ךָ עַל־יִשְׂרָאֵ֥ל וְ⁠עַל־יְהוּדָ֖ה וְ⁠עַל־כָּל־הַ⁠גּוֹיִ֑ם מִ⁠יּ֞וֹם דִּבַּ֤רְתִּי אֵלֶ֨י⁠ךָ֙ מִ⁠ימֵ֣י יֹאשִׁיָּ֔הוּ וְ⁠עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","qaẖ-lĕ⁠ká֮ mĕgilȧţ-séper֒ wĕ⁠káţabĕţá֣̇ ʼéle֗y⁠há ʼé֣ţ ká̇l-ha⁠dĕ̇bári֞ym ʼàşěr-di̇bȧ֧rĕţi̇y ʼéle֛y⁠ká ʻal-yişĕ̂ráʼé֥l wĕ⁠ʻal-yĕhẇdá֖h wĕ⁠ʻal-ká̇l-ha⁠ġwòyi֑m mi⁠ẏ֞wòm di̇bȧ֤rĕţi̇y ʼéle֨y⁠ká֙ mi⁠ymé֣y yòʼşǐyá̇֔hẇ wĕ⁠ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[36,3,"אוּלַ֤י יִשְׁמְעוּ֙ בֵּ֣ית יְהוּדָ֔ה אֵ֚ת כָּל־הָ֣⁠רָעָ֔ה אֲשֶׁ֛ר אָנֹכִ֥י חֹשֵׁ֖ב לַ⁠עֲשׂ֣וֹת לָ⁠הֶ֑ם לְמַ֣עַן יָשׁ֗וּבוּ אִ֚ישׁ מִ⁠דַּרְכּ֣⁠וֹ הָ⁠רָעָ֔ה וְ⁠סָלַחְתִּ֥י לַ⁠עֲוֺנָ֖⁠ם וּ⁠לְ⁠חַטָּאתָֽ⁠ם׃ס","ʼẇla֤y yişĕ̌mĕʻẇ֙ bé֣̇yţ yĕhẇdá֔h ʼé֚ţ ká̇l-há֣⁠ráʻá֔h ʼàşě֛r ʼánòki֥y ẖòşé֖̌b la⁠ʻàş֣̂wòţ lá⁠he֑m lĕma֣ʻan yáş̌֗ẇbẇ ʼi֚yş̌ mi⁠dȧrĕk֣̇⁠wò há⁠ráʻá֔h wĕ⁠sálaẖĕţi֥̇y la⁠ʻàwֺná֖⁠m ẇ⁠lĕ⁠ẖatá̇ʼţáֽ⁠m׃s"],[36,4,"וַ⁠יִּקְרָ֣א יִרְמְיָ֔הוּ אֶת־בָּר֖וּךְ בֶּן־נֵֽרִיָּ֑ה וַ⁠יִּכְתֹּ֨ב בָּר֜וּךְ מִ⁠פִּ֣י יִרְמְיָ֗הוּ אֵ֣ת כָּל־דִּבְרֵ֧י יְהוָ֛ה אֲשֶׁר־דִּבֶּ֥ר אֵלָ֖י⁠ו עַל־מְגִלַּת־סֵֽפֶר׃","wa⁠yi̇qĕrá֣ʼ yirĕmĕyá֔hẇ ʼeţ-bá̇r֖ẇkĕ bėn-néֽriyá֑̇h wa⁠yi̇kĕţò̇֨b bá̇r֜ẇkĕ mi⁠pi֣̇y yirĕmĕyá֗hẇ ʼé֣ţ ká̇l-di̇bĕré֧y yĕhwá֛h ʼàşěr-di̇bė֥r ʼélá֖y⁠w ʻal-mĕgilȧţ-séֽper׃"],[36,5,"וַ⁠יְצַוֶּ֣ה יִרְמְיָ֔הוּ אֶת־בָּר֖וּךְ לֵ⁠אמֹ֑ר אֲנִ֣י עָצ֔וּר לֹ֣א אוּכַ֔ל לָ⁠ב֖וֹא בֵּ֥ית יְהוָֽה׃","wa⁠yĕẕawė֣h yirĕmĕyá֔hẇ ʼeţ-bá̇r֖ẇkĕ lé⁠ʼmò֑r ʼàni֣y ʻáẕ֔ẇr lò֣ʼ ʼẇka֔l lá⁠b֖wòʼ bé֥̇yţ yĕhwáֽh׃"],[36,6,"וּ⁠בָאתָ֣ אַתָּ֡ה וְ⁠קָרָ֣אתָ בַ⁠מְּגִלָּ֣ה אֲשֶׁר־כָּתַֽבְתָּ־מִ⁠פִּ⁠י֩ אֶת־דִּבְרֵ֨י יְהוָ֜ה בְּ⁠אָזְנֵ֥י הָ⁠עָ֛ם בֵּ֥ית יְהוָ֖ה בְּ⁠י֣וֹם צ֑וֹם וְ⁠גַ֨ם בְּ⁠אָזְנֵ֧י כָל־יְהוּדָ֛ה הַ⁠בָּאִ֥ים מֵ⁠עָרֵי⁠הֶ֖ם תִּקְרָאֵֽ⁠ם׃","ẇ⁠báʼţá֣ ʼaţá̇֡h wĕ⁠qárá֣ʼţá ba⁠mĕ̇gilá֣̇h ʼàşěr-ká̇ţaֽbĕţá̇-mi⁠pi̇⁠y֩ ʼeţ-di̇bĕré֨y yĕhwá֜h bĕ̇⁠ʼázĕné֥y há⁠ʻá֛m bé֥̇yţ yĕhwá֖h bĕ̇⁠y֣wòm ẕ֑wòm wĕ⁠ga֨m bĕ̇⁠ʼázĕné֧y kál-yĕhẇdá֛h ha⁠bá̇ʼi֥ym mé⁠ʻáréy⁠he֖m ţi̇qĕráʼéֽ⁠m׃"],[36,7,"אוּלַ֞י תִּפֹּ֤ל תְּחִנָּתָ⁠ם֙ לִ⁠פְנֵ֣י יְהוָ֔ה וְ⁠יָשֻׁ֕בוּ אִ֖ישׁ מִ⁠דַּרְכּ֣⁠וֹ הָ⁠רָעָ֑ה כִּֽי־גָד֤וֹל הָ⁠אַף֙ וְ⁠הַ֣⁠חֵמָ֔ה אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה אֶל־הָ⁠עָ֥ם הַ⁠זֶּֽה׃","ʼẇla֞y ţi̇pò֤̇l ţĕ̇ẖiná̇ţá⁠m֙ li⁠pĕné֣y yĕhwá֔h wĕ⁠yáşǔ֕bẇ ʼi֖yş̌ mi⁠dȧrĕk֣̇⁠wò há⁠ráʻá֑h kiֽ̇y-gád֤wòl há⁠ʼap֙ wĕ⁠ha֣⁠ẖémá֔h ʼàşěr-di̇bė֥r yĕhwá֖h ʼel-há⁠ʻá֥m ha⁠zėֽh׃"],[36,8,"וַ⁠יַּ֗עַשׂ בָּרוּךְ֙ בֶּן־נֵ֣רִיָּ֔ה כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖⁠הוּ יִרְמְיָ֣הוּ הַ⁠נָּבִ֑יא לִ⁠קְרֹ֥א בַ⁠סֵּ֛פֶר דִּבְרֵ֥י יְהוָ֖ה בֵּ֥ית יְהֹוָֽה׃ס","wa⁠yȧ֗ʻaş̂ bá̇rẇkĕ֙ bėn-né֣riyá̇֔h kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇⁠hẇ yirĕmĕyá֣hẇ ha⁠ná̇bi֑yʼ li⁠qĕrò֥ʼ ba⁠sé֛̇per di̇bĕré֥y yĕhwá֖h bé֥̇yţ yĕhòwáֽh׃s"],[36,9,"וַ⁠יְהִ֣י בַ⁠שָּׁנָ֣ה הַ֠⁠חֲמִשִׁית לִ⁠יהוֹיָקִ֨ים בֶּן־יֹאשִׁיָּ֤הוּ מֶֽלֶךְ־יְהוּדָה֙ בַּ⁠חֹ֣דֶשׁ הַ⁠תְּשִׁעִ֔י קָרְא֨וּ צ֜וֹם לִ⁠פְנֵ֧י יְהוָ֛ה כָּל־הָ⁠עָ֖ם בִּ⁠ירֽוּשָׁלִָ֑ם וְ⁠כָל־הָ⁠עָ֗ם הַ⁠בָּאִ֛ים מֵ⁠עָרֵ֥י יְהוּדָ֖ה בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yĕhi֣y ba⁠şá̇̌ná֣h ha֠⁠ẖàmişǐyţ li⁠yhwòyáqi֨ym bėn-yòʼşǐyá֤̇hẇ meֽlekĕ-yĕhẇdáh֙ bȧ⁠ẖò֣deş̌ ha⁠ţĕ̇şǐʻi֔y qárĕʼ֨ẇ ẕ֜wòm li⁠pĕné֧y yĕhwá֛h ká̇l-há⁠ʻá֖m bi̇⁠yrֽẇşá̌liá֑m wĕ⁠kál-há⁠ʻá֗m ha⁠bá̇ʼi֛ym mé⁠ʻáré֥y yĕhẇdá֖h bi̇⁠yrẇşá̌liáֽm׃"],[36,10,"וַ⁠יִּקְרָ֨א בָר֥וּךְ בַּ⁠סֵּ֛פֶר אֶת־דִּבְרֵ֥י יִרְמְיָ֖הוּ בֵּ֣ית יְהוָ֑ה בְּ⁠לִשְׁכַּ֡ת גְּמַרְיָהוּ֩ בֶן־שָׁפָ֨ן הַ⁠סֹּפֵ֜ר בֶּ⁠חָצֵ֣ר הָ⁠עֶלְי֗וֹן פֶּ֣תַח שַׁ֤עַר בֵּית־יְהוָה֙ הֶֽ⁠חָדָ֔שׁ בְּ⁠אָזְנֵ֖י כָּל־הָ⁠עָֽם׃","wa⁠yi̇qĕrá֨ʼ bár֥ẇkĕ bȧ⁠sé֛̇per ʼeţ-di̇bĕré֥y yirĕmĕyá֖hẇ bé֣̇yţ yĕhwá֑h bĕ̇⁠lişĕ̌kȧ֡ţ gĕ̇marĕyáhẇ֩ ben-şá̌pá֨n ha⁠sò̇pé֜r bė⁠ẖáẕé֣r há⁠ʻelĕy֗wòn pė֣ţaẖ şǎ֤ʻar bé̇yţ-yĕhwáh֙ heֽ⁠ẖádá֔ş̌ bĕ̇⁠ʼázĕné֖y ká̇l-há⁠ʻáֽm׃"],[36,11,"וַ֠⁠יִּשְׁמַ֗ע מִכָ֨יְהוּ בֶן־גְּמַרְיָ֧הוּ בֶן־שָׁפָ֛ן אֶת־כָּל־דִּבְרֵ֥י יְהוָ֖ה מֵ⁠עַ֥ל הַ⁠סֵּֽפֶר׃","wa֠⁠yi̇şĕ̌ma֗ʻ miká֨yĕhẇ ben-gĕ̇marĕyá֧hẇ ben-şá̌pá֛n ʼeţ-ká̇l-di̇bĕré֥y yĕhwá֖h mé⁠ʻa֥l ha⁠séֽ̇per׃"],[36,12,"וַ⁠יֵּ֤רֶד בֵּית־הַ⁠מֶּ֨לֶךְ֙ עַל־לִשְׁכַּ֣ת הַ⁠סֹּפֵ֔ר וְ⁠הִ֨נֵּה־שָׁ֔ם כָּל־הַ⁠שָּׂרִ֖ים יֽוֹשְׁבִ֑ים אֱלִישָׁמָ֣ע הַ⁠סֹּפֵ֡ר וּ⁠דְלָיָ֣הוּ בֶן־שְׁ֠מַעְיָהוּ וְ⁠אֶלְנָתָ֨ן בֶּן־עַכְבּ֜וֹר וּ⁠גְמַרְיָ֧הוּ בֶן־שָׁפָ֛ן וְ⁠צִדְקִיָּ֥הוּ בֶן־חֲנַנְיָ֖הוּ וְ⁠כָל־הַ⁠שָּׂרִֽים׃","wa⁠yé֤̇red bé̇yţ-ha⁠mė֨lekĕ֙ ʻal-lişĕ̌kȧ֣ţ ha⁠sò̇pé֔r wĕ⁠hi֨né̇h-şá̌֔m ká̇l-ha⁠şá̇̂ri֖ym yֽwòşĕ̌bi֑ym ʼèliyşá̌má֣ʻ ha⁠sò̇pé֡r ẇ⁠dĕláyá֣hẇ ben-şĕ̌֠maʻĕyáhẇ wĕ⁠ʼelĕnáţá֨n bėn-ʻakĕḃ֜wòr ẇ⁠gĕmarĕyá֧hẇ ben-şá̌pá֛n wĕ⁠ẕidĕqiyá֥̇hẇ ben-ẖànanĕyá֖hẇ wĕ⁠kál-ha⁠şá̇̂riֽym׃"],[36,13,"וַ⁠יַּגֵּ֤ד לָ⁠הֶם֙ מִכָ֔יְהוּ אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים אֲשֶׁ֣ר שָׁמֵ֑עַ בִּ⁠קְרֹ֥א בָר֛וּךְ בַּ⁠סֵּ֖פֶר בְּ⁠אָזְנֵ֥י הָ⁠עָֽם׃","wa⁠yȧgé֤̇d lá⁠hem֙ miká֔yĕhẇ ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym ʼàşě֣r şá̌mé֑ʻa bi̇⁠qĕrò֥ʼ bár֛ẇkĕ bȧ⁠sé֖̇per bĕ̇⁠ʼázĕné֥y há⁠ʻáֽm׃"],[36,14,"וַ⁠יִּשְׁלְח֨וּ כָל־הַ⁠שָּׂרִ֜ים אֶל־בָּר֗וּךְ אֶת־יְהוּדִ֡י בֶּן־נְ֠תַנְיָהוּ בֶּן־שֶׁלֶמְיָ֣הוּ בֶן־כּוּשִׁי֮ לֵ⁠אמֹר֒ הַ⁠מְּגִלָּ֗ה אֲשֶׁ֨ר קָרָ֤אתָ בָּ⁠הּ֙ בְּ⁠אָזְנֵ֣י הָ⁠עָ֔ם קָחֶ֥⁠נָּה בְ⁠יָדְ⁠ךָ֖ וָ⁠לֵ֑ךְ וַ֠⁠יִּקַּח בָּר֨וּךְ בֶּן־נֵרִיָּ֤הוּ אֶת־הַ⁠מְּגִלָּה֙ בְּ⁠יָד֔⁠וֹ וַ⁠יָּבֹ֖א אֲלֵי⁠הֶֽם׃","wa⁠yi̇şĕ̌lĕẖ֨ẇ kál-ha⁠şá̇̂ri֜ym ʼel-bá̇r֗ẇkĕ ʼeţ-yĕhẇdi֡y bėn-nĕ֠ţanĕyáhẇ bėn-şělemĕyá֣hẇ ben-k̇ẇşǐy֮ lé⁠ʼmòr֒ ha⁠mĕ̇gilá̇֗h ʼàşě֨r qárá֤ʼţá bá̇⁠ḣ֙ bĕ̇⁠ʼázĕné֣y há⁠ʻá֔m qáẖe֥⁠ná̇h bĕ⁠yádĕ⁠ká֖ wá⁠lé֑kĕ wa֠⁠yi̇qȧẖ bá̇r֨ẇkĕ bėn-nériyá֤̇hẇ ʼeţ-ha⁠mĕ̇gilá̇h֙ bĕ̇⁠yád֔⁠wò wa⁠yá̇bò֖ʼ ʼàléy⁠heֽm׃"],[36,15,"וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו שֵׁ֣ב נָ֔א וּ⁠קְרָאֶ֖⁠נָּה בְּ⁠אָזְנֵ֑י⁠נוּ וַ⁠יִּקְרָ֥א בָר֖וּךְ בְּ⁠אָזְנֵי⁠הֶֽם׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w şé֣̌b ná֔ʼ ẇ⁠qĕráʼe֖⁠ná̇h bĕ̇⁠ʼázĕné֑y⁠nẇ wa⁠yi̇qĕrá֥ʼ bár֖ẇkĕ bĕ̇⁠ʼázĕnéy⁠heֽm׃"],[36,16,"וַ⁠יְהִ֗י כְּ⁠שָׁמְעָ⁠ם֙ אֶת־כָּל־הַ⁠דְּבָרִ֔ים פָּחֲד֖וּ אִ֣ישׁ אֶל־רֵעֵ֑⁠הוּ וַ⁠יֹּֽאמְרוּ֙ אֶל־בָּר֔וּךְ הַגֵּ֤יד נַגִּיד֙ לַ⁠מֶּ֔לֶךְ אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yĕhi֗y kĕ̇⁠şá̌mĕʻá⁠m֙ ʼeţ-ká̇l-ha⁠dĕ̇bári֔ym pá̇ẖàd֖ẇ ʼi֣yş̌ ʼel-réʻé֑⁠hẇ wa⁠yòֽ̇ʼmĕrẇ֙ ʼel-bá̇r֔ẇkĕ hagé֤̇yd nagi̇yd֙ la⁠mė֔lekĕ ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[36,17,"וְ⁠אֶ֨ת־בָּר֔וּךְ שָׁאֲל֖וּ לֵ⁠אמֹ֑ר הַגֶּד־נָ֣א לָ֔⁠נוּ אֵ֗יךְ כָּתַ֛בְתָּ אֶת־כָּל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה מִ⁠פִּֽי⁠ו׃","wĕ⁠ʼe֨ţ-bá̇r֔ẇkĕ şá̌ʼàl֖ẇ lé⁠ʼmò֑r hagėd-ná֣ʼ lá֔⁠nẇ ʼé֗ykĕ ká̇ţa֛bĕţá̇ ʼeţ-ká̇l-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh mi⁠piֽ̇y⁠w׃"],[36,18,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ בָּר֔וּךְ מִ⁠פִּי⁠ו֙ יִקְרָ֣א אֵלַ֔⁠י אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠אֲנִ֛י כֹּתֵ֥ב עַל־הַ⁠סֵּ֖פֶר בַּ⁠דְּיֽוֹ׃פ","wa⁠yò֤̇ʼmer lá⁠hem֙ bá̇r֔ẇkĕ mi⁠pi̇y⁠w֙ yiqĕrá֣ʼ ʼéla֔⁠y ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠ʼàni֛y kò̇ţé֥b ʻal-ha⁠sé֖̇per bȧ⁠dĕ̇yֽwò׃p"],[36,19,"וַ⁠יֹּאמְר֤וּ הַ⁠שָּׂרִים֙ אֶל־בָּר֔וּךְ לֵ֥ךְ הִסָּתֵ֖ר אַתָּ֣ה וְ⁠יִרְמְיָ֑הוּ וְ⁠אִ֥ישׁ אַל־יֵדַ֖ע אֵיפֹ֥ה אַתֶּֽם׃","wa⁠yò̇ʼmĕr֤ẇ ha⁠şá̇̂riym֙ ʼel-bá̇r֔ẇkĕ lé֥kĕ hisá̇ţé֖r ʼaţá֣̇h wĕ⁠yirĕmĕyá֑hẇ wĕ⁠ʼi֥yş̌ ʼal-yéda֖ʻ ʼéypò֥h ʼaţėֽm׃"],[36,20,"וַ⁠יָּבֹ֤אוּ אֶל־הַ⁠מֶּ֨לֶךְ֙ חָצֵ֔רָ⁠ה וְ⁠אֶת־הַ⁠מְּגִלָּ֣ה הִפְקִ֔דוּ בְּ⁠לִשְׁכַּ֖ת אֱלִישָׁמָ֣ע הַ⁠סֹּפֵ֑ר וַ⁠יַּגִּ֨ידוּ֙ בְּ⁠אָזְנֵ֣י הַ⁠מֶּ֔לֶךְ אֵ֖ת כָּל־הַ⁠דְּבָרִֽים׃","wa⁠yá̇bò֤ʼẇ ʼel-ha⁠mė֨lekĕ֙ ẖáẕé֔rá⁠h wĕ⁠ʼeţ-ha⁠mĕ̇gilá֣̇h hipĕqi֔dẇ bĕ̇⁠lişĕ̌kȧ֖ţ ʼèliyşá̌má֣ʻ ha⁠sò̇pé֑r wa⁠yȧgi̇֨ydẇ֙ bĕ̇⁠ʼázĕné֣y ha⁠mė֔lekĕ ʼé֖ţ ká̇l-ha⁠dĕ̇báriֽym׃"],[36,21,"וַ⁠יִּשְׁלַ֨ח הַ⁠מֶּ֜לֶךְ אֶת־יְהוּדִ֗י לָ⁠קַ֨חַת֙ אֶת־הַ⁠מְּגִלָּ֔ה וַ⁠יִּ֨קָּחֶ֔⁠הָ מִ⁠לִּשְׁכַּ֖ת אֱלִישָׁמָ֣ע הַ⁠סֹּפֵ֑ר וַ⁠יִּקְרָאֶ֤⁠הָ יְהוּדִי֙ בְּ⁠אָזְנֵ֣י הַ⁠מֶּ֔לֶךְ וּ⁠בְ⁠אָזְנֵי֙ כָּל־הַ⁠שָּׂרִ֔ים הָ⁠עֹמְדִ֖ים מֵ⁠עַ֥ל הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇şĕ̌la֨ẖ ha⁠mė֜lekĕ ʼeţ-yĕhẇdi֗y lá⁠qa֨ẖaţ֙ ʼeţ-ha⁠mĕ̇gilá̇֔h wa⁠yi̇֨qá̇ẖe֔⁠há mi⁠li̇şĕ̌kȧ֖ţ ʼèliyşá̌má֣ʻ ha⁠sò̇pé֑r wa⁠yi̇qĕráʼe֤⁠há yĕhẇdiy֙ bĕ̇⁠ʼázĕné֣y ha⁠mė֔lekĕ ẇ⁠bĕ⁠ʼázĕnéy֙ ká̇l-ha⁠şá̇̂ri֔ym há⁠ʻòmĕdi֖ym mé⁠ʻa֥l ha⁠mėֽlekĕ׃"],[36,22,"וְ⁠הַ⁠מֶּ֗לֶךְ יוֹשֵׁב֙ בֵּ֣ית הַ⁠חֹ֔רֶף בַּ⁠חֹ֖דֶשׁ הַ⁠תְּשִׁיעִ֑י וְ⁠אֶת־הָ⁠אָ֖ח לְ⁠פָנָ֥י⁠ו מְבֹעָֽרֶת׃","wĕ⁠ha⁠mė֗lekĕ ywòşé̌b֙ bé֣̇yţ ha⁠ẖò֔rep bȧ⁠ẖò֖deş̌ ha⁠ţĕ̇şǐyʻi֑y wĕ⁠ʼeţ-há⁠ʼá֖ẖ lĕ⁠páná֥y⁠w mĕbòʻáֽreţ׃"],[36,23,"וַ⁠יְהִ֣י ׀ כִּ⁠קְר֣וֹא יְהוּדִ֗י שָׁלֹ֣שׁ דְּלָתוֹת֮ וְ⁠אַרְבָּעָה֒ יִֽקְרָעֶ֨⁠הָ֙ בְּ⁠תַ֣עַר הַ⁠סֹּפֵ֔ר וְ⁠הַשְׁלֵ֕ךְ אֶל־הָ⁠אֵ֖שׁ אֲשֶׁ֣ר אֶל־הָ⁠אָ֑ח עַד־תֹּם֙ כָּל־הַ⁠מְּגִלָּ֔ה עַל־הָ⁠אֵ֖שׁ אֲשֶׁ֥ר עַל־הָ⁠אָֽח׃","wa⁠yĕhi֣y ׀ ki̇⁠qĕr֣wòʼ yĕhẇdi֗y şá̌lò֣ş̌ dĕ̇láţwòţ֮ wĕ⁠ʼarĕbá̇ʻáh֒ yiֽqĕráʻe֨⁠há֙ bĕ̇⁠ţa֣ʻar ha⁠sò̇pé֔r wĕ⁠haşĕ̌lé֕kĕ ʼel-há⁠ʼé֖ş̌ ʼàşě֣r ʼel-há⁠ʼá֑ẖ ʻad-ţò̇m֙ ká̇l-ha⁠mĕ̇gilá̇֔h ʻal-há⁠ʼé֖ş̌ ʼàşě֥r ʻal-há⁠ʼáֽẖ׃"],[36,24,"וְ⁠לֹ֣א פָחֲד֔וּ וְ⁠לֹ֥א קָרְע֖וּ אֶת־בִּגְדֵי⁠הֶ֑ם הַ⁠מֶּ֨לֶךְ֙ וְ⁠כָל־עֲבָדָ֔י⁠ו הַ⁠שֹּׁ֣מְעִ֔ים אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wĕ⁠lò֣ʼ páẖàd֔ẇ wĕ⁠lò֥ʼ qárĕʻ֖ẇ ʼeţ-bi̇gĕdéy⁠he֑m ha⁠mė֨lekĕ֙ wĕ⁠kál-ʻàbádá֔y⁠w ha⁠şò֣̇̌mĕʻi֔ym ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[36,25,"וְ⁠גַם֩ אֶלְנָתָ֨ן וּ⁠דְלָיָ֤הוּ וּ⁠גְמַרְיָ֨הוּ֙ הִפְגִּ֣עוּ בַ⁠מֶּ֔לֶךְ לְ⁠בִלְתִּ֥י שְׂרֹ֖ף אֶת־הַ⁠מְּגִלָּ֑ה וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵי⁠הֶֽם׃","wĕ⁠gam֩ ʼelĕnáţá֨n ẇ⁠dĕláyá֤hẇ ẇ⁠gĕmarĕyá֨hẇ֙ hipĕgi֣̇ʻẇ ba⁠mė֔lekĕ lĕ⁠bilĕţi֥̇y şĕ̂rò֖p ʼeţ-ha⁠mĕ̇gilá֑̇h wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàléy⁠heֽm׃"],[36,26,"וַ⁠יְצַוֶּ֣ה הַ֠⁠מֶּלֶךְ אֶת־יְרַחְמְאֵ֨ל בֶּן־הַ⁠מֶּ֜לֶךְ וְ⁠אֶת־שְׂרָיָ֣הוּ בֶן־עַזְרִיאֵ֗ל וְ⁠אֶת־שֶֽׁלֶמְיָ֨הוּ֙ בֶּֽן־עַבְדְּאֵ֔ל לָ⁠קַ֨חַת֙ אֶת־בָּר֣וּךְ הַ⁠סֹּפֵ֔ר וְ⁠אֵ֖ת יִרְמְיָ֣הוּ הַ⁠נָּבִ֑יא וַ⁠יַּסְתִּרֵ֖⁠ם יְהוָֽה׃ס","wa⁠yĕẕawė֣h ha֠⁠mėlekĕ ʼeţ-yĕraẖĕmĕʼé֨l bėn-ha⁠mė֜lekĕ wĕ⁠ʼeţ-şĕ̂ráyá֣hẇ ben-ʻazĕriyʼé֗l wĕ⁠ʼeţ-şěֽlemĕyá֨hẇ֙ bėֽn-ʻabĕdĕ̇ʼé֔l lá⁠qa֨ẖaţ֙ ʼeţ-bá̇r֣ẇkĕ ha⁠sò̇pé֔r wĕ⁠ʼé֖ţ yirĕmĕyá֣hẇ ha⁠ná̇bi֑yʼ wa⁠yȧsĕţi̇ré֖⁠m yĕhwáֽh׃s"],[36,27,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֶֽל־יִרְמְיָ֑הוּ אַחֲרֵ֣י ׀ שְׂרֹ֣ף הַ⁠מֶּ֗לֶךְ אֶת־הַ⁠מְּגִלָּה֙ וְ⁠אֶת־הַ⁠דְּבָרִ֔ים אֲשֶׁ֨ר כָּתַ֥ב בָּר֛וּךְ מִ⁠פִּ֥י יִרְמְיָ֖הוּ לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼeֽl-yirĕmĕyá֑hẇ ʼaẖàré֣y ׀ şĕ̂rò֣p ha⁠mė֗lekĕ ʼeţ-ha⁠mĕ̇gilá̇h֙ wĕ⁠ʼeţ-ha⁠dĕ̇bári֔ym ʼàşě֨r ká̇ţa֥b bá̇r֛ẇkĕ mi⁠pi֥̇y yirĕmĕyá֖hẇ lé⁠ʼmòֽr׃"],[36,28,"שׁ֥וּב קַח־לְ⁠ךָ֖ מְגִלָּ֣ה אַחֶ֑רֶת וּ⁠כְתֹ֣ב עָלֶ֗י⁠הָ אֵ֤ת כָּל־הַ⁠דְּבָרִים֙ הָ⁠רִ֣אשֹׁנִ֔ים אֲשֶׁ֣ר הָי֗וּ עַל־הַ⁠מְּגִלָּה֙ הָ⁠רִ֣אשֹׁנָ֔ה אֲשֶׁ֥ר שָׂרַ֖ף יְהוֹיָקִ֥ים מֶֽלֶךְ־יְהוּדָֽה׃","ş֥̌ẇb qaẖ-lĕ⁠ká֖ mĕgilá֣̇h ʼaẖe֑reţ ẇ⁠kĕţò֣b ʻále֗y⁠há ʼé֤ţ ká̇l-ha⁠dĕ̇báriym֙ há⁠ri֣ʼşò̌ni֔ym ʼàşě֣r háy֗ẇ ʻal-ha⁠mĕ̇gilá̇h֙ há⁠ri֣ʼşò̌ná֔h ʼàşě֥r şá̂ra֖p yĕhwòyáqi֥ym meֽlekĕ-yĕhẇdáֽh׃"],[36,29,"וְ⁠עַל־יְהוֹיָקִ֤ים מֶֽלֶךְ־יְהוּדָה֙ תֹּאמַ֔ר כֹּ֖ה אָמַ֣ר יְהוָ֑ה אַ֠תָּה שָׂרַ֜פְתָּ אֶת־הַ⁠מְּגִלָּ֤ה הַ⁠זֹּאת֙ לֵ⁠אמֹ֔ר מַדּוּעַ֩ כָּתַ֨בְתָּ עָלֶ֜י⁠הָ לֵ⁠אמֹ֗ר בֹּֽא־יָב֤וֹא מֶֽלֶךְ־בָּבֶל֙ וְ⁠הִשְׁחִית֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את וְ⁠הִשְׁבִּ֥ית מִמֶּ֖⁠נָּה אָדָ֥ם וּ⁠בְהֵמָֽה׃ס","wĕ⁠ʻal-yĕhwòyáqi֤ym meֽlekĕ-yĕhẇdáh֙ ţò̇ʼma֔r kò֖̇h ʼáma֣r yĕhwá֑h ʼa֠ţá̇h şá̂ra֜pĕţá̇ ʼeţ-ha⁠mĕ̇gilá֤̇h ha⁠zò̇ʼţ֙ lé⁠ʼmò֔r maḋẇʻa֩ ká̇ţa֨bĕţá̇ ʻále֜y⁠há lé⁠ʼmò֗r bòֽ̇ʼ-yáb֤wòʼ meֽlekĕ-bá̇bel֙ wĕ⁠hişĕ̌ẖiyţ֙ ʼeţ-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ wĕ⁠hişĕ̌bi֥̇yţ mimė֖⁠ná̇h ʼádá֥m ẇ⁠bĕhémáֽh׃s"],[36,30,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה עַל־יְהֽוֹיָקִים֙ מֶ֣לֶךְ יְהוּדָ֔ה לֹא־יִֽהְיֶה־לּ֥⁠וֹ יוֹשֵׁ֖ב עַל־כִּסֵּ֣א דָוִ֑ד וְ⁠נִבְלָת⁠וֹ֙ תִּֽהְיֶ֣ה מֻשְׁלֶ֔כֶת לַ⁠חֹ֥רֶב בַּ⁠יּ֖וֹם וְ⁠לַ⁠קֶּ֥רַח בַּ⁠לָּֽיְלָה׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h ʻal-yĕhֽwòyáqiym֙ me֣lekĕ yĕhẇdá֔h lòʼ-yiֽhĕyeh-l֥̇⁠wò ywòşé֖̌b ʻal-ki̇sé֣̇ʼ dáwi֑d wĕ⁠nibĕláţ⁠wò֙ ţiֽ̇hĕye֣h muşĕ̌le֔keţ la⁠ẖò֥reb bȧ⁠ẏ֖wòm wĕ⁠la⁠qė֥raẖ bȧ⁠láֽ̇yĕláh׃"],[36,31,"וּ⁠פָקַדְתִּ֨י עָלָ֧י⁠ו וְ⁠עַל־זַרְע֛⁠וֹ וְ⁠עַל־עֲבָדָ֖י⁠ו אֶת־עֲוֺנָ֑⁠ם וְ⁠הֵבֵאתִ֣י עֲ֠לֵי⁠הֶם וְ⁠עַל־יֹשְׁבֵ֨י יְרוּשָׁלִַ֜ם וְ⁠אֶל־אִ֣ישׁ יְהוּדָ֗ה אֵ֧ת כָּל־הָ⁠רָעָ֛ה אֲשֶׁר־דִּבַּ֥רְתִּי אֲלֵי⁠הֶ֖ם וְ⁠לֹ֥א שָׁמֵֽעוּ׃ס","ẇ⁠páqadĕţi̇֨y ʻálá֧y⁠w wĕ⁠ʻal-zarĕʻ֛⁠wò wĕ⁠ʻal-ʻàbádá֖y⁠w ʼeţ-ʻàwֺná֑⁠m wĕ⁠hébéʼţi֣y ʻà֠léy⁠hem wĕ⁠ʻal-yòşĕ̌bé֨y yĕrẇşá̌lia֜m wĕ⁠ʼel-ʼi֣yş̌ yĕhẇdá֗h ʼé֧ţ ká̇l-há⁠ráʻá֛h ʼàşěr-di̇bȧ֥rĕţi̇y ʼàléy⁠he֖m wĕ⁠lò֥ʼ şá̌méֽʻẇ׃s"],[36,32,"וְ⁠יִרְמְיָ֜הוּ לָקַ֣ח ׀ מְגִלָּ֣ה אַחֶ֗רֶת וַֽ⁠יִּתְּנָ⁠הּ֮ אֶל־בָּר֣וּךְ בֶּן־נֵרִיָּהוּ֮ הַ⁠סֹּפֵר֒ וַ⁠יִּכְתֹּ֤ב עָלֶ֨י⁠הָ֙ מִ⁠פִּ֣י יִרְמְיָ֔הוּ אֵ֚ת כָּל־דִּבְרֵ֣י הַ⁠סֵּ֔פֶר אֲשֶׁ֥ר שָׂרַ֛ף יְהוֹיָקִ֥ים מֶֽלֶךְ־יְהוּדָ֖ה בָּ⁠אֵ֑שׁ וְ⁠ע֨וֹד נוֹסַ֧ף עֲלֵי⁠הֶ֛ם דְּבָרִ֥ים רַבִּ֖ים כָּ⁠הֵֽמָּה׃ס","wĕ⁠yirĕmĕyá֜hẇ láqa֣ẖ ׀ mĕgilá֣̇h ʼaẖe֗reţ waֽ⁠yi̇ţĕ̇ná⁠ḣ֮ ʼel-bá̇r֣ẇkĕ bėn-nériyá̇hẇ֮ ha⁠sò̇pér֒ wa⁠yi̇kĕţò֤̇b ʻále֨y⁠há֙ mi⁠pi֣̇y yirĕmĕyá֔hẇ ʼé֚ţ ká̇l-di̇bĕré֣y ha⁠sé̇֔per ʼàşě֥r şá̂ra֛p yĕhwòyáqi֥ym meֽlekĕ-yĕhẇdá֖h bá̇⁠ʼé֑ş̌ wĕ⁠ʻ֨wòd nwòsa֧p ʻàléy⁠he֛m dĕ̇bári֥ym rabi֖̇ym ká̇⁠héֽmá̇h׃s"],[37,1,"וַ⁠יִּ֨מְלָךְ־מֶ֔לֶךְ צִדְקִיָּ֖הוּ בֶּן־יֹֽאשִׁיָּ֑הוּ תַּ֗חַת כָּנְיָ֨הוּ֙ בֶּן־יְה֣וֹיָקִ֔ים אֲשֶׁ֥ר הִמְלִ֛יךְ נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל בְּ⁠אֶ֥רֶץ יְהוּדָֽה׃","wa⁠yi̇֨mĕlákĕ-me֔lekĕ ẕidĕqiyá֖̇hẇ bėn-yòֽʼşǐyá֑̇hẇ ţȧ֗ẖaţ ká̇nĕyá֨hẇ֙ bėn-yĕh֣wòyáqi֔ym ʼàşě֥r himĕli֛ykĕ nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l bĕ̇⁠ʼe֥reẕ yĕhẇdáֽh׃"],[37,2,"וְ⁠לֹ֥א שָׁמַ֛ע ה֥וּא וַ⁠עֲבָדָ֖י⁠ו וְ⁠עַ֣ם הָ⁠אָ֑רֶץ אֶל־דִּבְרֵ֣י יְהוָ֔ה אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד יִרְמְיָ֥הוּ הַ⁠נָּבִֽיא׃","wĕ⁠lò֥ʼ şá̌ma֛ʻ h֥ẇʼ wa⁠ʻàbádá֖y⁠w wĕ⁠ʻa֣m há⁠ʼá֑reẕ ʼel-di̇bĕré֣y yĕhwá֔h ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d yirĕmĕyá֥hẇ ha⁠ná̇biֽyʼ׃"],[37,3,"וַ⁠יִּשְׁלַח֩ הַ⁠מֶּ֨לֶךְ צִדְקִיָּ֜הוּ אֶת־יְהוּכַ֣ל בֶּן־שֶֽׁלֶמְיָ֗ה וְ⁠אֶת־צְפַנְיָ֤הוּ בֶן־מַֽעֲשֵׂיָה֙ הַ⁠כֹּהֵ֔ן אֶל־יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא לֵ⁠אמֹ֑ר הִתְפַּלֶּל־נָ֣א בַעֲדֵ֔⁠נוּ אֶל־יְהוָ֖ה אֱלֹהֵֽי⁠נוּ׃","wa⁠yi̇şĕ̌laẖ֩ ha⁠mė֨lekĕ ẕidĕqiyá̇֜hẇ ʼeţ-yĕhẇka֣l bėn-şěֽlemĕyá֗h wĕ⁠ʼeţ-ẕĕpanĕyá֤hẇ ben-maֽʻàşé̂yáh֙ ha⁠kò̇hé֔n ʼel-yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ lé⁠ʼmò֑r hiţĕpȧlėl-ná֣ʼ baʻàdé֔⁠nẇ ʼel-yĕhwá֖h ʼèlòhéֽy⁠nẇ׃"],[37,4,"וְ⁠יִרְמְיָ֕הוּ בָּ֥א וְ⁠יֹצֵ֖א בְּ⁠ת֣וֹךְ הָ⁠עָ֑ם וְ⁠לֹֽא־נָתְנ֥וּ אֹת֖⁠וֹ בֵּ֥ית ה⁠כליא׃","wĕ⁠yirĕmĕyá֕hẇ bá֥̇ʼ wĕ⁠yòẕé֖ʼ bĕ̇⁠ţ֣wòkĕ há⁠ʻá֑m wĕ⁠lòֽʼ-náţĕn֥ẇ ʼòţ֖⁠wò bé֥̇yţ h⁠klyʼ׃"],[37,5,"וְ⁠חֵ֥יל פַּרְעֹ֖ה יָצָ֣א מִ⁠מִּצְרָ֑יִם וַ⁠יִּשְׁמְע֨וּ הַ⁠כַּשְׂדִּ֜ים הַ⁠צָּרִ֤ים עַל־יְרוּשָׁלִַ֨ם֙ אֶת־שִׁמְעָ֔⁠ם וַ⁠יֵּ֣עָל֔וּ מֵ⁠עַ֖ל יְרוּשָׁלִָֽם׃פ","wĕ⁠ẖé֥yl pȧrĕʻò֖h yáẕá֣ʼ mi⁠mi̇ẕĕrá֑yim wa⁠yi̇şĕ̌mĕʻ֨ẇ ha⁠kȧşĕ̂di̇֜ym ha⁠ẕá̇ri֤ym ʻal-yĕrẇşá̌lia֨m֙ ʼeţ-şǐmĕʻá֔⁠m wa⁠yé֣̇ʻál֔ẇ mé⁠ʻa֖l yĕrẇşá̌liáֽm׃p"],[37,6,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[37,7,"כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כֹּ֤ה תֹֽאמְרוּ֙ אֶל־מֶ֣לֶךְ יְהוּדָ֔ה הַ⁠שֹּׁלֵ֧חַ אֶתְ⁠כֶ֛ם אֵלַ֖⁠י לְ⁠דָרְשֵׁ֑⁠נִי הִנֵּ֣ה ׀ חֵ֣יל פַּרְעֹ֗ה הַ⁠יֹּצֵ֤א לָ⁠כֶם֙ לְ⁠עֶזְרָ֔ה שָׁ֥ב לְ⁠אַרְצ֖⁠וֹ מִצְרָֽיִם׃","kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kò֤̇h ţòֽʼmĕrẇ֙ ʼel-me֣lekĕ yĕhẇdá֔h ha⁠şò̇̌lé֧ẖa ʼeţĕ⁠ke֛m ʼéla֖⁠y lĕ⁠dárĕşé֑̌⁠niy hiné֣̇h ׀ ẖé֣yl pȧrĕʻò֗h ha⁠yò̇ẕé֤ʼ lá⁠kem֙ lĕ⁠ʻezĕrá֔h şá֥̌b lĕ⁠ʼarĕẕ֖⁠wò miẕĕráֽyim׃"],[37,8,"וְ⁠שָׁ֨בוּ֙ הַ⁠כַּשְׂדִּ֔ים וְ⁠נִלְחֲמ֖וּ עַל־הָ⁠עִ֣יר הַ⁠זֹּ֑את וּ⁠לְכָדֻ֖⁠הָ וּ⁠שְׂרָפֻ֥⁠הָ בָ⁠אֵֽשׁ׃ס","wĕ⁠şá̌֨bẇ֙ ha⁠kȧşĕ̂di̇֔ym wĕ⁠nilĕẖàm֖ẇ ʻal-há⁠ʻi֣yr ha⁠zò֑̇ʼţ ẇ⁠lĕkádu֖⁠há ẇ⁠şĕ̂rápu֥⁠há bá⁠ʼéֽş̌׃s"],[37,9,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אַל־תַּשִּׁ֤אוּ נַפְשֹֽׁתֵי⁠כֶם֙ לֵ⁠אמֹ֔ר הָלֹ֛ךְ יֵלְכ֥וּ מֵ⁠עָלֵ֖י⁠נוּ הַ⁠כַּשְׂדִּ֑ים כִּי־לֹ֖א יֵלֵֽכוּ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼal-ţȧşi֤̇̌ʼẇ napĕşòֽ̌ţéy⁠kem֙ lé⁠ʼmò֔r hálò֛kĕ yélĕk֥ẇ mé⁠ʻálé֖y⁠nẇ ha⁠kȧşĕ̂di֑̇ym ki̇y-lò֖ʼ yéléֽkẇ׃"],[37,10,"כִּ֣י אִם־הִכִּיתֶ֞ם כָּל־חֵ֤יל כַּשְׂדִּים֙ הַ⁠נִּלְחָמִ֣ים אִתְּ⁠כֶ֔ם וְ⁠נִ֨שְׁאֲרוּ בָ֔⁠ם אֲנָשִׁ֖ים מְדֻקָּרִ֑ים אִ֤ישׁ בְּ⁠אָהֳל⁠וֹ֙ יָק֔וּמוּ וְ⁠שָֽׂרְפ֛וּ אֶת־הָ⁠עִ֥יר הַ⁠זֹּ֖את בָּ⁠אֵֽשׁ׃","ki֣̇y ʼim-hiki̇yţe֞m ká̇l-ẖé֤yl kȧşĕ̂di̇ym֙ ha⁠ni̇lĕẖámi֣ym ʼiţĕ̇⁠ke֔m wĕ⁠ni֨şĕ̌ʼàrẇ bá֔⁠m ʼànáşǐ֖ym mĕduqá̇ri֑ym ʼi֤yş̌ bĕ̇⁠ʼáhol⁠wò֙ yáq֔ẇmẇ wĕ⁠şáֽ̂rĕp֛ẇ ʼeţ-há⁠ʻi֥yr ha⁠zò֖̇ʼţ bá̇⁠ʼéֽş̌׃"],[37,11,"וְ⁠הָיָ֗ה בְּ⁠הֵֽעָלוֹת֙ חֵ֣יל הַ⁠כַּשְׂדִּ֔ים מֵ⁠עַ֖ל יְרֽוּשָׁלִָ֑ם מִ⁠פְּנֵ֖י חֵ֥יל פַּרְעֹֽה׃ס","wĕ⁠háyá֗h bĕ̇⁠héֽʻálwòţ֙ ẖé֣yl ha⁠kȧşĕ̂di̇֔ym mé⁠ʻa֖l yĕrֽẇşá̌liá֑m mi⁠pĕ̇né֖y ẖé֥yl pȧrĕʻòֽh׃s"],[37,12,"וַ⁠יֵּצֵ֤א יִרְמְיָ֨הוּ֙ מִ⁠יר֣וּשָׁלִַ֔ם לָ⁠לֶ֖כֶת אֶ֣רֶץ בִּנְיָמִ֑ן לַ⁠חֲלִ֥ק מִ⁠שָּׁ֖ם בְּ⁠ת֥וֹךְ הָ⁠עָֽם׃","wa⁠yé̇ẕé֤ʼ yirĕmĕyá֨hẇ֙ mi⁠yr֣ẇşá̌lia֔m lá⁠le֖keţ ʼe֣reẕ bi̇nĕyámi֑n la⁠ẖàli֥q mi⁠şá֖̇̌m bĕ̇⁠ţ֥wòkĕ há⁠ʻáֽm׃"],[37,13,"וַ⁠יְהִי־ה֞וּא בְּ⁠שַׁ֣עַר בִּנְיָמִ֗ן וְ⁠שָׁם֙ בַּ֣עַל פְּקִדֻ֔ת וּ⁠שְׁמ⁠וֹ֙ יִרְאִיָּ֔יה בֶּן־שֶֽׁלֶמְיָ֖ה בֶּן־חֲנַנְיָ֑ה וַ⁠יִּתְפֹּ֞שׂ אֶֽת־יִרְמְיָ֤הוּ הַ⁠נָּבִיא֙ לֵ⁠אמֹ֔ר אֶל־הַ⁠כַּשְׂדִּ֖ים אַתָּ֥ה נֹפֵֽל׃","wa⁠yĕhiy-h֞ẇʼ bĕ̇⁠şǎ֣ʻar bi̇nĕyámi֗n wĕ⁠şá̌m֙ bȧ֣ʻal pĕ̇qidu֔ţ ẇ⁠şĕ̌m⁠wò֙ yirĕʼiyá̇֔yh bėn-şěֽlemĕyá֖h bėn-ẖànanĕyá֑h wa⁠yi̇ţĕpò̇֞ş̂ ʼeֽţ-yirĕmĕyá֤hẇ ha⁠ná̇biyʼ֙ lé⁠ʼmò֔r ʼel-ha⁠kȧşĕ̂di֖̇ym ʼaţá֥̇h nòpéֽl׃"],[37,14,"וַ⁠יֹּ֨אמֶר יִרְמְיָ֜הוּ שֶׁ֗קֶר אֵינֶ֤⁠נִּי נֹפֵל֙ עַל־הַ⁠כַּשְׂדִּ֔ים וְ⁠לֹ֥א שָׁמַ֖ע אֵלָ֑י⁠ו וַ⁠יִּתְפֹּ֤שׂ יִרְאִיָּיה֙ בְּ⁠יִרְמְיָ֔הוּ וַ⁠יְבִאֵ֖⁠הוּ אֶל־הַ⁠שָּׂרִֽים׃","wa⁠yò̇֨ʼmer yirĕmĕyá֜hẇ şě֗qer ʼéyne֤⁠ni̇y nòpél֙ ʻal-ha⁠kȧşĕ̂di̇֔ym wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼélá֑y⁠w wa⁠yi̇ţĕpò֤̇ş̂ yirĕʼiyá̇yh֙ bĕ̇⁠yirĕmĕyá֔hẇ wa⁠yĕbiʼé֖⁠hẇ ʼel-ha⁠şá̇̂riֽym׃"],[37,15,"וַ⁠יִּקְצְפ֧וּ הַ⁠שָּׂרִ֛ים עַֽל־יִרְמְיָ֖הוּ וְ⁠הִכּ֣וּ אֹת֑⁠וֹ וְ⁠נָתְנ֨וּ אוֹת֜⁠וֹ בֵּ֣ית הָ⁠אֵס֗וּר בֵּ֚ית יְהוֹנָתָ֣ן הַ⁠סֹּפֵ֔ר כִּֽי־אֹת֥⁠וֹ עָשׂ֖וּ לְ⁠בֵ֥ית הַ⁠כֶּֽלֶא׃","wa⁠yi̇qĕẕĕp֧ẇ ha⁠şá̇̂ri֛ym ʻaֽl-yirĕmĕyá֖hẇ wĕ⁠hik֣̇ẇ ʼòţ֑⁠wò wĕ⁠náţĕn֨ẇ ʼwòţ֜⁠wò bé֣̇yţ há⁠ʼés֗ẇr bé֚̇yţ yĕhwònáţá֣n ha⁠sò̇pé֔r kiֽ̇y-ʼòţ֥⁠wò ʻáş֖̂ẇ lĕ⁠bé֥yţ ha⁠kėֽleʼ׃"],[37,16,"כִּ֣י בָ֧א יִרְמְיָ֛הוּ אֶל־בֵּ֥ית הַ⁠בּ֖וֹר וְ⁠אֶל־הַֽ⁠חֲנֻ֑יוֹת וַ⁠יֵּֽשֶׁב־שָׁ֥ם יִרְמְיָ֖הוּ יָמִ֥ים רַבִּֽים׃פ","ki֣̇y bá֧ʼ yirĕmĕyá֛hẇ ʼel-bé֥̇yţ ha⁠ḃ֖wòr wĕ⁠ʼel-haֽ⁠ẖànu֑ywòţ wa⁠yéֽ̇şěb-şá֥̌m yirĕmĕyá֖hẇ yámi֥ym rabiֽ̇ym׃p"],[37,17,"וַ⁠יִּשְׁלַח֩ הַ⁠מֶּ֨לֶךְ צִדְקִיָּ֜הוּ וַ⁠יִּקָּחֵ֗⁠הוּ וַ⁠יִּשְׁאָלֵ֨⁠הוּ הַ⁠מֶּ֤לֶךְ בְּ⁠בֵית⁠וֹ֙ בַּ⁠סֵּ֔תֶר וַ⁠יֹּ֕אמֶר הֲ⁠יֵ֥שׁ דָּבָ֖ר מֵ⁠אֵ֣ת יְהוָ֑ה וַ⁠יֹּ֤אמֶר יִרְמְיָ֨הוּ֙ יֵ֔שׁ וַ⁠יֹּ֕אמֶר בְּ⁠יַ֥ד מֶֽלֶךְ־בָּבֶ֖ל תִּנָּתֵֽן׃ס","wa⁠yi̇şĕ̌laẖ֩ ha⁠mė֨lekĕ ẕidĕqiyá̇֜hẇ wa⁠yi̇qá̇ẖé֗⁠hẇ wa⁠yi̇şĕ̌ʼálé֨⁠hẇ ha⁠mė֤lekĕ bĕ̇⁠béyţ⁠wò֙ bȧ⁠sé̇֔ţer wa⁠yò̇֕ʼmer hà⁠yé֥ş̌ dá̇bá֖r mé⁠ʼé֣ţ yĕhwá֑h wa⁠yò֤̇ʼmer yirĕmĕyá֨hẇ֙ yé֔ş̌ wa⁠yò̇֕ʼmer bĕ̇⁠ya֥d meֽlekĕ-bá̇be֖l ţi̇ná̇ţéֽn׃s"],[37,18,"וַ⁠יֹּ֣אמֶר יִרְמְיָ֔הוּ אֶל־הַ⁠מֶּ֖לֶךְ צִדְקִיָּ֑הוּ מֶה֩ חָטָ֨אתִֽי לְ⁠ךָ֤ וְ⁠לַ⁠עֲבָדֶ֨י⁠ךָ֙ וְ⁠לָ⁠עָ֣ם הַ⁠זֶּ֔ה כִּֽי־נְתַתֶּ֥ם אוֹתִ֖⁠י אֶל־בֵּ֥ית הַ⁠כֶּֽלֶא׃","wa⁠yò֣̇ʼmer yirĕmĕyá֔hẇ ʼel-ha⁠mė֖lekĕ ẕidĕqiyá֑̇hẇ meh֩ ẖátá֨ʼţiֽy lĕ⁠ká֤ wĕ⁠la⁠ʻàbáde֨y⁠ká֙ wĕ⁠lá⁠ʻá֣m ha⁠zė֔h kiֽ̇y-nĕţaţė֥m ʼwòţi֖⁠y ʼel-bé֥̇yţ ha⁠kėֽleʼ׃"],[37,19,"ו⁠אי⁠ו נְבִ֣יאֵי⁠כֶ֔ם אֲשֶׁר־נִבְּא֥וּ לָ⁠כֶ֖ם לֵ⁠אמֹ֑ר לֹֽא־יָבֹ֤א מֶֽלֶךְ־בָּבֶל֙ עֲלֵי⁠כֶ֔ם וְ⁠עַ֖ל הָ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃","w⁠ʼy⁠w nĕbi֣yʼéy⁠ke֔m ʼàşěr-nibĕ̇ʼ֥ẇ lá⁠ke֖m lé⁠ʼmò֑r lòֽʼ-yábò֤ʼ meֽlekĕ-bá̇bel֙ ʻàléy⁠ke֔m wĕ⁠ʻa֖l há⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃"],[37,20,"וְ⁠עַתָּ֕ה שְֽׁמַֽע־נָ֖א אֲדֹנִ֣⁠י הַ⁠מֶּ֑לֶךְ תִּפָּל־נָ֤א תְחִנָּתִ⁠י֙ לְ⁠פָנֶ֔י⁠ךָ וְ⁠אַל־תְּשִׁבֵ֗⁠נִי בֵּ֚ית יְהוֹנָתָ֣ן הַ⁠סֹּפֵ֔ר וְ⁠לֹ֥א אָמ֖וּת שָֽׁם׃","wĕ⁠ʻaţá̇֕h şĕֽ̌maֽʻ-ná֖ʼ ʼàdòni֣⁠y ha⁠mė֑lekĕ ţi̇pá̇l-ná֤ʼ ţĕẖiná̇ţi⁠y֙ lĕ⁠páne֔y⁠ká wĕ⁠ʼal-ţĕ̇şǐbé֗⁠niy bé֚̇yţ yĕhwònáţá֣n ha⁠sò̇pé֔r wĕ⁠lò֥ʼ ʼám֖ẇţ şáֽ̌m׃"],[37,21,"וַ⁠יְצַוֶּ֞ה הַ⁠מֶּ֣לֶךְ צִדְקִיָּ֗הוּ וַ⁠יַּפְקִ֣דוּ אֶֽת־יִרְמְיָהוּ֮ בַּ⁠חֲצַ֣ר הַ⁠מַּטָּרָה֒ וְ⁠נָתֹן֩ ל֨⁠וֹ כִכַּר־לֶ֤חֶם לַ⁠יּוֹם֙ מִ⁠ח֣וּץ הָ⁠אֹפִ֔ים עַד־תֹּ֥ם כָּל־הַ⁠לֶּ֖חֶם מִן־הָ⁠עִ֑יר וַ⁠יֵּ֣שֶׁב יִרְמְיָ֔הוּ בַּ⁠חֲצַ֖ר הַ⁠מַּטָּרָֽה׃","wa⁠yĕẕawė֞h ha⁠mė֣lekĕ ẕidĕqiyá̇֗hẇ wa⁠yȧpĕqi֣dẇ ʼeֽţ-yirĕmĕyáhẇ֮ bȧ⁠ẖàẕa֣r ha⁠mȧtá̇ráh֒ wĕ⁠náţòn֩ l֨⁠wò kikȧr-le֤ẖem la⁠ẏwòm֙ mi⁠ẖ֣ẇẕ há⁠ʼòpi֔ym ʻad-ţò֥̇m ká̇l-ha⁠lė֖ẖem min-há⁠ʻi֑yr wa⁠yé֣̇şěb yirĕmĕyá֔hẇ bȧ⁠ẖàẕa֖r ha⁠mȧtá̇ráֽh׃"],[38,1,"וַ⁠יִּשְׁמַ֞ע שְׁפַטְיָ֣ה בֶן־מַתָּ֗ן וּ⁠גְדַלְיָ֨הוּ֙ בֶּן־פַּשְׁח֔וּר וְ⁠יוּכַל֙ בֶּן־שֶׁ֣לֶמְיָ֔הוּ וּ⁠פַשְׁח֖וּר בֶּן־מַלְכִּיָּ֑ה אֶ֨ת־הַ⁠דְּבָרִ֔ים אֲשֶׁ֧ר יִרְמְיָ֛הוּ מְדַבֵּ֥ר אֶל־כָּל־הָ⁠עָ֖ם לֵ⁠אמֹֽר׃ס","wa⁠yi̇şĕ̌ma֞ʻ şĕ̌patĕyá֣h ben-maţá̇֗n ẇ⁠gĕdalĕyá֨hẇ֙ bėn-pȧşĕ̌ẖ֔ẇr wĕ⁠yẇkal֙ bėn-şě֣lemĕyá֔hẇ ẇ⁠paşĕ̌ẖ֖ẇr bėn-malĕki̇yá֑̇h ʼe֨ţ-ha⁠dĕ̇bári֔ym ʼàşě֧r yirĕmĕyá֛hẇ mĕdabé֥̇r ʼel-ká̇l-há⁠ʻá֖m lé⁠ʼmòֽr׃s"],[38,2,"כֹּה֮ אָמַ֣ר יְהוָה֒ הַ⁠יֹּשֵׁב֙ בָּ⁠עִ֣יר הַ⁠זֹּ֔את יָמ֕וּת בַּ⁠חֶ֖רֶב בָּ⁠רָעָ֣ב וּ⁠בַ⁠דָּ֑בֶר וְ⁠הַ⁠יֹּצֵ֤א אֶל־הַ⁠כַּשְׂדִּים֙ יחיה וְ⁠הָיְתָה־לּ֥⁠וֹ נַפְשׁ֛⁠וֹ לְ⁠שָׁלָ֖ל וָ⁠חָֽי׃ס","kò̇h֮ ʼáma֣r yĕhwáh֒ ha⁠yò̇şé̌b֙ bá̇⁠ʻi֣yr ha⁠zò̇֔ʼţ yám֕ẇţ bȧ⁠ẖe֖reb bá̇⁠ráʻá֣b ẇ⁠ba⁠dá֑̇ber wĕ⁠ha⁠yò̇ẕé֤ʼ ʼel-ha⁠kȧşĕ̂di̇ym֙ yẖyh wĕ⁠háyĕţáh-l֥̇⁠wò napĕş֛̌⁠wò lĕ⁠şá̌lá֖l wá⁠ẖáֽy׃s"],[38,3,"כֹּ֖ה אָמַ֣ר יְהוָ֑ה הִנָּתֹ֨ן תִּנָּתֵ֜ן הָ⁠עִ֣יר הַ⁠זֹּ֗את בְּ⁠יַ֛ד חֵ֥יל מֶֽלֶךְ־בָּבֶ֖ל וּ⁠לְכָדָֽ⁠הּ׃","kò֖̇h ʼáma֣r yĕhwá֑h hiná̇ţò֨n ţi̇ná̇ţé֜n há⁠ʻi֣yr ha⁠zò̇֗ʼţ bĕ̇⁠ya֛d ẖé֥yl meֽlekĕ-bá̇be֖l ẇ⁠lĕkádáֽ⁠ḣ׃"],[38,4,"וַ⁠יֹּאמְר֨וּ הַ⁠שָּׂרִ֜ים אֶל־הַ⁠מֶּ֗לֶךְ י֣וּמַת נָא֮ אֶת־הָ⁠אִ֣ישׁ הַ⁠זֶּה֒ כִּֽי־עַל־כֵּ֡ן הֽוּא־מְרַפֵּ֡א אֶת־יְדֵי֩ אַנְשֵׁ֨י הַ⁠מִּלְחָמָ֜ה הַֽ⁠נִּשְׁאָרִ֣ים ׀ בָּ⁠עִ֣יר הַ⁠זֹּ֗את וְ⁠אֵת֙ יְדֵ֣י כָל־הָ⁠עָ֔ם לְ⁠דַבֵּ֣ר אֲלֵי⁠הֶ֔ם כַּ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה כִּ֣י ׀ הָ⁠אִ֣ישׁ הַ⁠זֶּ֗ה אֵינֶ֨⁠נּוּ דֹרֵ֧שׁ לְ⁠שָׁל֛וֹם לָ⁠עָ֥ם הַ⁠זֶּ֖ה כִּ֥י אִם־לְ⁠רָעָֽה׃","wa⁠yò̇ʼmĕr֨ẇ ha⁠şá̇̂ri֜ym ʼel-ha⁠mė֗lekĕ y֣ẇmaţ náʼ֮ ʼeţ-há⁠ʼi֣yş̌ ha⁠zėh֒ kiֽ̇y-ʻal-ké̇֡n hֽẇʼ-mĕrapé̇֡ʼ ʼeţ-yĕdéy֩ ʼanĕşé̌֨y ha⁠mi̇lĕẖámá֜h haֽ⁠ni̇şĕ̌ʼári֣ym ׀ bá̇⁠ʻi֣yr ha⁠zò̇֗ʼţ wĕ⁠ʼéţ֙ yĕdé֣y kál-há⁠ʻá֔m lĕ⁠dabé֣̇r ʼàléy⁠he֔m kȧ⁠dĕ̇bári֖ym há⁠ʼé֑lėh ki֣̇y ׀ há⁠ʼi֣yş̌ ha⁠zė֗h ʼéyne֨⁠ṅẇ dòré֧ş̌ lĕ⁠şá̌l֛wòm lá⁠ʻá֥m ha⁠zė֖h ki֥̇y ʼim-lĕ⁠ráʻáֽh׃"],[38,5,"וַ⁠יֹּ֨אמֶר֙ הַ⁠מֶּ֣לֶךְ צִדְקִיָּ֔הוּ הִנֵּה־ה֖וּא בְּ⁠יֶדְ⁠כֶ֑ם כִּֽי־אֵ֣ין הַ⁠מֶּ֔לֶךְ יוּכַ֥ל אֶתְ⁠כֶ֖ם דָּבָֽר׃","wa⁠yò̇֨ʼmer֙ ha⁠mė֣lekĕ ẕidĕqiyá̇֔hẇ hiné̇h-h֖ẇʼ bĕ̇⁠yedĕ⁠ke֑m kiֽ̇y-ʼé֣yn ha⁠mė֔lekĕ yẇka֥l ʼeţĕ⁠ke֖m dá̇báֽr׃"],[38,6,"וַ⁠יִּקְח֣וּ אֶֽת־יִרְמְיָ֗הוּ וַ⁠יַּשְׁלִ֨כוּ אֹת֜⁠וֹ אֶל־הַ⁠בּ֣וֹר ׀ מַלְכִּיָּ֣הוּ בֶן־הַ⁠מֶּ֗לֶךְ אֲשֶׁר֙ בַּ⁠חֲצַ֣ר הַ⁠מַּטָּרָ֔ה וַ⁠יְשַׁלְּח֥וּ אֶֽת־יִרְמְיָ֖הוּ בַּ⁠חֲבָלִ֑ים וּ⁠בַ⁠בּ֤וֹר אֵֽין־מַ֨יִם֙ כִּ֣י אִם־טִ֔יט וַ⁠יִּטְבַּ֥ע יִרְמְיָ֖הוּ בַּ⁠טִּֽיט׃ס","wa⁠yi̇qĕẖ֣ẇ ʼeֽţ-yirĕmĕyá֗hẇ wa⁠yȧşĕ̌li֨kẇ ʼòţ֜⁠wò ʼel-ha⁠ḃ֣wòr ׀ malĕki̇yá֣̇hẇ ben-ha⁠mė֗lekĕ ʼàşěr֙ bȧ⁠ẖàẕa֣r ha⁠mȧtá̇rá֔h wa⁠yĕşǎlĕ̇ẖ֥ẇ ʼeֽţ-yirĕmĕyá֖hẇ bȧ⁠ẖàbáli֑ym ẇ⁠ba⁠ḃ֤wòr ʼéֽyn-ma֨yim֙ ki֣̇y ʼim-ti֔yt wa⁠yi̇tĕbȧ֥ʻ yirĕmĕyá֖hẇ bȧ⁠tiֽ̇yt׃s"],[38,7,"וַ⁠יִּשְׁמַ֡ע עֶֽבֶד־מֶ֨לֶךְ הַ⁠כּוּשִׁ֜י אִ֣ישׁ סָרִ֗יס וְ⁠הוּא֙ בְּ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ כִּֽי־נָתְנ֥וּ אֶֽת־יִרְמְיָ֖הוּ אֶל־הַ⁠בּ֑וֹר וְ⁠הַ⁠מֶּ֥לֶךְ יוֹשֵׁ֖ב בְּ⁠שַׁ֥עַר בִּנְיָמִֽן׃","wa⁠yi̇şĕ̌ma֡ʻ ʻeֽbed-me֨lekĕ ha⁠k̇ẇşǐ֜y ʼi֣yş̌ sári֗ys wĕ⁠hẇʼ֙ bĕ̇⁠bé֣yţ ha⁠mė֔lekĕ kiֽ̇y-náţĕn֥ẇ ʼeֽţ-yirĕmĕyá֖hẇ ʼel-ha⁠ḃ֑wòr wĕ⁠ha⁠mė֥lekĕ ywòşé֖̌b bĕ̇⁠şǎ֥ʻar bi̇nĕyámiֽn׃"],[38,8,"וַ⁠יֵּצֵ֥א עֶֽבֶד־מֶ֖לֶךְ מִ⁠בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יְדַבֵּ֥ר אֶל־הַ⁠מֶּ֖לֶךְ לֵ⁠אמֹֽר׃","wa⁠yé̇ẕé֥ʼ ʻeֽbed-me֖lekĕ mi⁠bé֣̇yţ ha⁠mė֑lekĕ wa⁠yĕdabé֥̇r ʼel-ha⁠mė֖lekĕ lé⁠ʼmòֽr׃"],[38,9,"אֲדֹנִ֣⁠י הַ⁠מֶּ֗לֶךְ הֵרֵ֜עוּ הָ⁠אֲנָשִׁ֤ים הָ⁠אֵ֨לֶּה֙ אֵ֣ת כָּל־אֲשֶׁ֤ר עָשׂוּ֙ לְ⁠יִרְמְיָ֣הוּ הַ⁠נָּבִ֔יא אֵ֥ת אֲשֶׁר־הִשְׁלִ֖יכוּ אֶל־הַ⁠בּ֑וֹר וַ⁠יָּ֤מָת תַּחְתָּי⁠ו֙ מִ⁠פְּנֵ֣י הָֽ⁠רָעָ֔ב כִּ֣י אֵ֥ין הַ⁠לֶּ֛חֶם ע֖וֹד בָּ⁠עִֽיר׃","ʼàdòni֣⁠y ha⁠mė֗lekĕ héré֜ʻẇ há⁠ʼànáşǐ֤ym há⁠ʼé֨lėh֙ ʼé֣ţ ká̇l-ʼàşě֤r ʻáş̂ẇ֙ lĕ⁠yirĕmĕyá֣hẇ ha⁠ná̇bi֔yʼ ʼé֥ţ ʼàşěr-hişĕ̌li֖ykẇ ʼel-ha⁠ḃ֑wòr wa⁠yá֤̇máţ ţȧẖĕţá̇y⁠w֙ mi⁠pĕ̇né֣y háֽ⁠ráʻá֔b ki֣̇y ʼé֥yn ha⁠lė֛ẖem ʻ֖wòd bá̇⁠ʻiֽyr׃"],[38,10,"וַ⁠יְצַוֶּ֣ה הַ⁠מֶּ֔לֶךְ אֵ֛ת עֶֽבֶד־מֶ֥לֶךְ הַ⁠כּוּשִׁ֖י לֵ⁠אמֹ֑ר קַ֣ח בְּ⁠יָדְ⁠ךָ֤ מִ⁠זֶּה֙ שְׁלֹשִׁ֣ים אֲנָשִׁ֔ים וְֽ⁠הַעֲלִ֜יתָ אֶֽת־יִרְמְיָ֧הוּ הַ⁠נָּבִ֛יא מִן־הַ⁠בּ֖וֹר בְּ⁠טֶ֥רֶם יָמֽוּת׃","wa⁠yĕẕawė֣h ha⁠mė֔lekĕ ʼé֛ţ ʻeֽbed-me֥lekĕ ha⁠k̇ẇşǐ֖y lé⁠ʼmò֑r qa֣ẖ bĕ̇⁠yádĕ⁠ká֤ mi⁠zėh֙ şĕ̌lòşǐ֣ym ʼànáşǐ֔ym wĕֽ⁠haʻàli֜yţá ʼeֽţ-yirĕmĕyá֧hẇ ha⁠ná̇bi֛yʼ min-ha⁠ḃ֖wòr bĕ̇⁠te֥rem yámֽẇţ׃"],[38,11,"וַ⁠יִּקַּ֣ח ׀ עֶֽבֶד־מֶ֨לֶךְ אֶת־הָ⁠אֲנָשִׁ֜ים בְּ⁠יָד֗⁠וֹ וַ⁠יָּבֹ֤א בֵית־הַ⁠מֶּ֨לֶךְ֙ אֶל־תַּ֣חַת הָ⁠אוֹצָ֔ר וַ⁠יִּקַּ֤ח מִ⁠שָּׁם֙ בְּלוֹיֵ֣ ה⁠סחבות וּ⁠בְלוֹיֵ֖ מְלָחִ֑ים וַ⁠יְשַׁלְּחֵ֧⁠ם אֶֽל־יִרְמְיָ֛הוּ אֶל־הַ⁠בּ֖וֹר בַּ⁠חֲבָלִֽים׃","wa⁠yi̇qȧ֣ẖ ׀ ʻeֽbed-me֨lekĕ ʼeţ-há⁠ʼànáşǐ֜ym bĕ̇⁠yád֗⁠wò wa⁠yá̇bò֤ʼ béyţ-ha⁠mė֨lekĕ֙ ʼel-ţȧ֣ẖaţ há⁠ʼwòẕá֔r wa⁠yi̇qȧ֤ẖ mi⁠şá̇̌m֙ bĕ̇lwòyé֣ h⁠sẖbwţ ẇ⁠bĕlwòyé֖ mĕláẖi֑ym wa⁠yĕşǎlĕ̇ẖé֧⁠m ʼeֽl-yirĕmĕyá֛hẇ ʼel-ha⁠ḃ֖wòr bȧ⁠ẖàbáliֽym׃"],[38,12,"וַ⁠יֹּ֡אמֶר עֶבֶד־מֶ֨לֶךְ הַ⁠כּוּשִׁ֜י אֶֽל־יִרְמְיָ֗הוּ שִׂ֣ים נָ֠א בְּלוֹאֵ֨י הַ⁠סְּחָב֤וֹת וְ⁠הַ⁠מְּלָחִים֙ תַּ֚חַת אַצִּל֣וֹת יָדֶ֔י⁠ךָ מִ⁠תַּ֖חַת לַ⁠חֲבָלִ֑ים וַ⁠יַּ֥עַשׂ יִרְמְיָ֖הוּ כֵּֽן׃","wa⁠yò̇֡ʼmer ʻebed-me֨lekĕ ha⁠k̇ẇşǐ֜y ʼeֽl-yirĕmĕyá֗hẇ şî֣ym ná֠ʼ bĕ̇lwòʼé֨y ha⁠sĕ̇ẖáb֤wòţ wĕ⁠ha⁠mĕ̇láẖiym֙ ţȧ֚ẖaţ ʼaẕi̇l֣wòţ yáde֔y⁠ká mi⁠ţȧ֖ẖaţ la⁠ẖàbáli֑ym wa⁠yȧ֥ʻaş̂ yirĕmĕyá֖hẇ kéֽ̇n׃"],[38,13,"וַ⁠יִּמְשְׁכ֤וּ אֶֽת־יִרְמְיָ֨הוּ֙ בַּֽ⁠חֲבָלִ֔ים וַ⁠יַּעֲל֥וּ אֹת֖⁠וֹ מִן־הַ⁠בּ֑וֹר וַ⁠יֵּ֣שֶׁב יִרְמְיָ֔הוּ בַּ⁠חֲצַ֖ר הַ⁠מַּטָּרָֽה׃ס","wa⁠yi̇mĕşĕ̌k֤ẇ ʼeֽţ-yirĕmĕyá֨hẇ֙ bȧֽ⁠ẖàbáli֔ym wa⁠yȧʻàl֥ẇ ʼòţ֖⁠wò min-ha⁠ḃ֑wòr wa⁠yé֣̇şěb yirĕmĕyá֔hẇ bȧ⁠ẖàẕa֖r ha⁠mȧtá̇ráֽh׃s"],[38,14,"וַ⁠יִּשְׁלַ֞ח הַ⁠מֶּ֣לֶךְ צִדְקִיָּ֗הוּ וַ⁠יִּקַּ֞ח אֶֽת־יִרְמְיָ֤הוּ הַ⁠נָּבִיא֙ אֵלָ֔י⁠ו אֶל־מָבוֹא֙ הַ⁠שְּׁלִישִׁ֔י אֲשֶׁ֖ר בְּ⁠בֵ֣ית יְהוָ֑ה וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ אֶֽל־יִרְמְיָ֗הוּ שֹׁאֵ֨ל אֲנִ֤י אֹֽתְ⁠ךָ֙ דָּבָ֔ר אַל־תְּכַחֵ֥ד מִמֶּ֖⁠נִּי דָּבָֽר׃","wa⁠yi̇şĕ̌la֞ẖ ha⁠mė֣lekĕ ẕidĕqiyá̇֗hẇ wa⁠yi̇qȧ֞ẖ ʼeֽţ-yirĕmĕyá֤hẇ ha⁠ná̇biyʼ֙ ʼélá֔y⁠w ʼel-mábwòʼ֙ ha⁠şĕ̇̌liyşǐ֔y ʼàşě֖r bĕ̇⁠bé֣yţ yĕhwá֑h wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ ʼeֽl-yirĕmĕyá֗hẇ şò̌ʼé֨l ʼàni֤y ʼòֽţĕ⁠ká֙ dá̇bá֔r ʼal-ţĕ̇kaẖé֥d mimė֖⁠ni̇y dá̇báֽr׃"],[38,15,"וַ⁠יֹּ֤אמֶר יִרְמְיָ֨הוּ֙ אֶל־צִדְקִיָּ֔הוּ כִּ֚י אַגִּ֣יד לְ⁠ךָ֔ הֲ⁠ל֖וֹא הָמֵ֣ת תְּמִיתֵ֑⁠נִי וְ⁠כִי֙ אִיעָ֣צְ⁠ךָ֔ לֹ֥א תִשְׁמַ֖ע אֵלָֽ⁠י׃","wa⁠yò֤̇ʼmer yirĕmĕyá֨hẇ֙ ʼel-ẕidĕqiyá̇֔hẇ ki֚̇y ʼagi֣̇yd lĕ⁠ká֔ hà⁠l֖wòʼ hámé֣ţ ţĕ̇miyţé֑⁠niy wĕ⁠kiy֙ ʼiyʻá֣ẕĕ⁠ká֔ lò֥ʼ ţişĕ̌ma֖ʻ ʼéláֽ⁠y׃"],[38,16,"וַ⁠יִּשָּׁבַ֞ע הַ⁠מֶּ֧לֶךְ צִדְקִיָּ֛הוּ אֶֽל־יִרְמְיָ֖הוּ בַּ⁠סֵּ֣תֶר לֵ⁠אמֹ֑ר חַי־יְהוָ֞ה את אֲשֶׁר֩ עָשָׂה־לָ֨⁠נוּ אֶת־הַ⁠נֶּ֤פֶשׁ הַ⁠זֹּאת֙ אִם־אֲמִיתֶ֔⁠ךָ וְ⁠אִם־אֶתֶּנְ⁠ךָ֗ בְּ⁠יַד֙ הָ⁠אֲנָשִׁ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר מְבַקְשִׁ֖ים אֶת־נַפְשֶֽׁ⁠ךָ׃ס","wa⁠yi̇şá̇̌ba֞ʻ ha⁠mė֧lekĕ ẕidĕqiyá֛̇hẇ ʼeֽl-yirĕmĕyá֖hẇ bȧ⁠sé֣̇ţer lé⁠ʼmò֑r ẖay-yĕhwá֞h ʼţ ʼàşěr֩ ʻáşá̂h-lá֨⁠nẇ ʼeţ-ha⁠nė֤peş̌ ha⁠zò̇ʼţ֙ ʼim-ʼàmiyţe֔⁠ká wĕ⁠ʼim-ʼeţėnĕ⁠ká֗ bĕ̇⁠yad֙ há⁠ʼànáşǐ֣ym há⁠ʼé֔lėh ʼàşě֥r mĕbaqĕşǐ֖ym ʼeţ-napĕşěֽ⁠ká׃s"],[38,17,"וַ⁠יֹּ֣אמֶר יִרְמְיָ֣הוּ אֶל־צִדְקִיָּ֡הוּ כֹּֽה־אָמַ֣ר יְהוָה֩ אֱלֹהֵ֨י צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל אִם־יָצֹ֨א תֵצֵ֜א אֶל־שָׂרֵ֤י מֶֽלֶךְ־בָּבֶל֙ וְ⁠חָיְתָ֣ה נַפְשֶׁ֔⁠ךָ וְ⁠הָ⁠עִ֣יר הַ⁠זֹּ֔את לֹ֥א תִשָּׂרֵ֖ף בָּ⁠אֵ֑שׁ וְ⁠חָיִ֖תָה אַתָּ֥ה וּ⁠בֵיתֶֽ⁠ךָ׃","wa⁠yò֣̇ʼmer yirĕmĕyá֣hẇ ʼel-ẕidĕqiyá̇֡hẇ kòֽ̇h-ʼáma֣r yĕhwáh֩ ʼèlòhé֨y ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l ʼim-yáẕò֨ʼ ţéẕé֜ʼ ʼel-şá̂ré֤y meֽlekĕ-bá̇bel֙ wĕ⁠ẖáyĕţá֣h napĕşě֔⁠ká wĕ⁠há⁠ʻi֣yr ha⁠zò̇֔ʼţ lò֥ʼ ţişá̇̂ré֖p bá̇⁠ʼé֑ş̌ wĕ⁠ẖáyi֖ţáh ʼaţá֥̇h ẇ⁠béyţeֽ⁠ká׃"],[38,18,"וְ⁠אִ֣ם לֹֽא־תֵצֵ֗א אֶל־שָׂרֵי֙ מֶ֣לֶךְ בָּבֶ֔ל וְ⁠נִתְּנָ֞ה הָ⁠עִ֤יר הַ⁠זֹּאת֙ בְּ⁠יַ֣ד הַ⁠כַּשְׂדִּ֔ים וּ⁠שְׂרָפ֖וּ⁠הָ בָּ⁠אֵ֑שׁ וְ⁠אַתָּ֖ה לֹֽא־תִמָּלֵ֥ט מִ⁠יָּדָֽ⁠ם׃ס","wĕ⁠ʼi֣m lòֽʼ-ţéẕé֗ʼ ʼel-şá̂réy֙ me֣lekĕ bá̇be֔l wĕ⁠niţĕ̇ná֞h há⁠ʻi֤yr ha⁠zò̇ʼţ֙ bĕ̇⁠ya֣d ha⁠kȧşĕ̂di̇֔ym ẇ⁠şĕ̂ráp֖ẇ⁠há bá̇⁠ʼé֑ş̌ wĕ⁠ʼaţá֖̇h lòֽʼ-ţimá̇lé֥t mi⁠yá̇dáֽ⁠m׃s"],[38,19,"וַ⁠יֹּ֛אמֶר הַ⁠מֶּ֥לֶךְ צִדְקִיָּ֖הוּ אֶֽל־יִרְמְיָ֑הוּ אֲנִ֧י דֹאֵ֣ג אֶת־הַ⁠יְּהוּדִ֗ים אֲשֶׁ֤ר נָֽפְלוּ֙ אֶל־הַ⁠כַּשְׂדִּ֔ים פֶּֽן־יִתְּנ֥וּ אֹתִ֛⁠י בְּ⁠יָדָ֖⁠ם וְ⁠הִתְעַלְּלוּ־בִֽ⁠י׃פ","wa⁠yò֛̇ʼmer ha⁠mė֥lekĕ ẕidĕqiyá֖̇hẇ ʼeֽl-yirĕmĕyá֑hẇ ʼàni֧y dòʼé֣g ʼeţ-ha⁠yĕ̇hẇdi֗ym ʼàşě֤r náֽpĕlẇ֙ ʼel-ha⁠kȧşĕ̂di̇֔ym pėֽn-yiţĕ̇n֥ẇ ʼòţi֛⁠y bĕ̇⁠yádá֖⁠m wĕ⁠hiţĕʻalĕ̇lẇ-biֽ⁠y׃p"],[38,20,"וַ⁠יֹּ֥אמֶר יִרְמְיָ֖הוּ לֹ֣א יִתֵּ֑נוּ שְֽׁמַֽע־נָ֣א ׀ בְּ⁠ק֣וֹל יְהוָ֗ה לַ⁠אֲשֶׁ֤ר אֲנִי֙ דֹּבֵ֣ר אֵלֶ֔י⁠ךָ וְ⁠יִ֥יטַב לְ⁠ךָ֖ וּ⁠תְחִ֥י נַפְשֶֽׁ⁠ךָ׃","wa⁠yò֥̇ʼmer yirĕmĕyá֖hẇ lò֣ʼ yiţé֑̇nẇ şĕֽ̌maֽʻ-ná֣ʼ ׀ bĕ̇⁠q֣wòl yĕhwá֗h la⁠ʼàşě֤r ʼàniy֙ dò̇bé֣r ʼéle֔y⁠ká wĕ⁠yi֥ytab lĕ⁠ká֖ ẇ⁠ţĕẖi֥y napĕşěֽ⁠ká׃"],[38,21,"וְ⁠אִם־מָאֵ֥ן אַתָּ֖ה לָ⁠צֵ֑את זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁ֥ר הִרְאַ֖⁠נִי יְהוָֽה׃","wĕ⁠ʼim-máʼé֥n ʼaţá֖̇h lá⁠ẕé֑ʼţ ze֣h ha⁠dá̇bá֔r ʼàşě֥r hirĕʼa֖⁠niy yĕhwáֽh׃"],[38,22,"וְ⁠הִנֵּ֣ה כָל־הַ⁠נָּשִׁ֗ים אֲשֶׁ֤ר נִשְׁאֲרוּ֙ בְּ⁠בֵ֣ית מֶֽלֶךְ־יְהוּדָ֔ה מוּצָא֕וֹת אֶל־שָׂרֵ֖י מֶ֣לֶךְ בָּבֶ֑ל וְ⁠הֵ֣נָּה אֹמְר֗וֹת הִסִּית֜וּ⁠ךָ וְ⁠יָכְל֤וּ לְ⁠ךָ֙ אַנְשֵׁ֣י שְׁלֹמֶ֔⁠ךָ הָטְבְּע֥וּ בַ⁠בֹּ֛ץ רַגְלֶ֖⁠ךָ נָסֹ֥גוּ אָחֽוֹר׃","wĕ⁠hiné֣̇h kál-ha⁠ná̇şǐ֗ym ʼàşě֤r nişĕ̌ʼàrẇ֙ bĕ̇⁠bé֣yţ meֽlekĕ-yĕhẇdá֔h mẇẕáʼ֕wòţ ʼel-şá̂ré֖y me֣lekĕ bá̇be֑l wĕ⁠hé֣ná̇h ʼòmĕr֗wòţ hisi̇yţ֜ẇ⁠ká wĕ⁠yákĕl֤ẇ lĕ⁠ká֙ ʼanĕşé֣̌y şĕ̌lòme֔⁠ká hátĕbĕ̇ʻ֥ẇ ba⁠bò֛̇ẕ ragĕle֖⁠ká násò֥gẇ ʼáẖֽwòr׃"],[38,23,"וְ⁠אֶת־כָּל־נָשֶׁ֣י⁠ךָ וְ⁠אֶת־בָּנֶ֗י⁠ךָ מֽוֹצִאִים֙ אֶל־הַ⁠כַּשְׂדִּ֔ים וְ⁠אַתָּ֖ה לֹא־תִמָּלֵ֣ט מִ⁠יָּדָ֑⁠ם כִּ֣י בְ⁠יַ֤ד מֶֽלֶךְ־בָּבֶל֙ תִּתָּפֵ֔שׂ וְ⁠אֶת־הָ⁠עִ֥יר הַ⁠זֹּ֖את תִּשְׂרֹ֥ף בָּ⁠אֵֽשׁ׃פ","wĕ⁠ʼeţ-ká̇l-náşě֣y⁠ká wĕ⁠ʼeţ-bá̇ne֗y⁠ká mֽwòẕiʼiym֙ ʼel-ha⁠kȧşĕ̂di̇֔ym wĕ⁠ʼaţá֖̇h lòʼ-ţimá̇lé֣t mi⁠yá̇dá֑⁠m ki֣̇y bĕ⁠ya֤d meֽlekĕ-bá̇bel֙ ţi̇ţá̇pé֔ş̂ wĕ⁠ʼeţ-há⁠ʻi֥yr ha⁠zò֖̇ʼţ ţi̇şĕ̂rò֥p bá̇⁠ʼéֽş̌׃p"],[38,24,"וַ⁠יֹּ֨אמֶר צִדְקִיָּ֜הוּ אֶֽל־יִרְמְיָ֗הוּ אִ֛ישׁ אַל־יֵדַ֥ע בַּ⁠דְּבָֽרִים־הָ⁠אֵ֖לֶּה וְ⁠לֹ֥א תָמֽוּת׃","wa⁠yò̇֨ʼmer ẕidĕqiyá̇֜hẇ ʼeֽl-yirĕmĕyá֗hẇ ʼi֛yş̌ ʼal-yéda֥ʻ bȧ⁠dĕ̇báֽriym-há⁠ʼé֖lėh wĕ⁠lò֥ʼ ţámֽẇţ׃"],[38,25,"וְ⁠כִֽי־יִשְׁמְע֣וּ הַ⁠שָּׂרִים֮ כִּֽי־דִבַּ֣רְתִּי אִתָּ⁠ךְ֒ וּ⁠בָ֣אוּ אֵלֶ֣י⁠ךָ וְֽ⁠אָמְר֪וּ אֵלֶ֟י⁠ךָ הַגִּֽידָ⁠ה־נָּ֨א לָ֜⁠נוּ מַה־דִּבַּ֧רְתָּ אֶל־הַ⁠מֶּ֛לֶךְ אַל־תְּכַחֵ֥ד מִמֶּ֖⁠נּוּ וְ⁠לֹ֣א נְמִיתֶ֑⁠ךָ וּ⁠מַה־דִּבֶּ֥ר אֵלֶ֖י⁠ךָ הַ⁠מֶּֽלֶךְ׃","wĕ⁠kiֽy-yişĕ̌mĕʻ֣ẇ ha⁠şá̇̂riym֮ kiֽ̇y-dibȧ֣rĕţi̇y ʼiţá̇⁠kĕ֒ ẇ⁠bá֣ʼẇ ʼéle֣y⁠ká wĕֽ⁠ʼámĕr֪ẇ ʼéle֟y⁠ká hagiֽ̇ydá⁠h-ná̇֨ʼ lá֜⁠nẇ mah-di̇bȧ֧rĕţá̇ ʼel-ha⁠mė֛lekĕ ʼal-ţĕ̇kaẖé֥d mimė֖⁠ṅẇ wĕ⁠lò֣ʼ nĕmiyţe֑⁠ká ẇ⁠mah-di̇bė֥r ʼéle֖y⁠ká ha⁠mėֽlekĕ׃"],[38,26,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם מַפִּיל־אֲנִ֥י תְחִנָּתִ֖⁠י לִ⁠פְנֵ֣י הַ⁠מֶּ֑לֶךְ לְ⁠בִלְתִּ֧י הֲשִׁיבֵ֛⁠נִי בֵּ֥ית יְהוֹנָתָ֖ן לָ⁠מ֥וּת שָֽׁם׃פ","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m mapi̇yl-ʼàni֥y ţĕẖiná̇ţi֖⁠y li⁠pĕné֣y ha⁠mė֑lekĕ lĕ⁠bilĕţi֧̇y hàşǐybé֛⁠niy bé֥̇yţ yĕhwònáţá֖n lá⁠m֥ẇţ şáֽ̌m׃p"],[38,27,"וַ⁠יָּבֹ֨אוּ כָל־הַ⁠שָּׂרִ֤ים אֶֽל־יִרְמְיָ֨הוּ֙ וַ⁠יִּשְׁאֲל֣וּ אֹת֔⁠וֹ וַ⁠יַּגֵּ֤ד לָ⁠הֶם֙ כְּ⁠כָל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר צִוָּ֖ה הַ⁠מֶּ֑לֶךְ וַ⁠יַּחֲרִ֣שׁוּ מִמֶּ֔⁠נּוּ כִּ֥י לֹֽא־נִשְׁמַ֖ע הַ⁠דָּבָֽר׃פ","wa⁠yá̇bò֨ʼẇ kál-ha⁠şá̇̂ri֤ym ʼeֽl-yirĕmĕyá֨hẇ֙ wa⁠yi̇şĕ̌ʼàl֣ẇ ʼòţ֔⁠wò wa⁠yȧgé֤̇d lá⁠hem֙ kĕ̇⁠kál-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʼàşě֥r ẕiwá֖̇h ha⁠mė֑lekĕ wa⁠yȧẖàri֣ş̌ẇ mimė֔⁠ṅẇ ki֥̇y lòֽʼ-nişĕ̌ma֖ʻ ha⁠dá̇báֽr׃p"],[38,28,"וַ⁠יֵּ֤שֶׁב יִרְמְיָ֨הוּ֙ בַּ⁠חֲצַ֣ר הַ⁠מַּטָּרָ֔ה עַד־י֖וֹם אֲשֶׁר־נִלְכְּדָ֣ה יְרוּשָׁלִָ֑ם ס וְ⁠הָיָ֕ה כַּ⁠אֲשֶׁ֥ר נִלְכְּדָ֖ה יְרוּשָׁלִָֽם׃פ","wa⁠yé֤̇şěb yirĕmĕyá֨hẇ֙ bȧ⁠ẖàẕa֣r ha⁠mȧtá̇rá֔h ʻad-y֖wòm ʼàşěr-nilĕkĕ̇dá֣h yĕrẇşá̌liá֑m s wĕ⁠háyá֕h kȧ⁠ʼàşě֥r nilĕkĕ̇dá֖h yĕrẇşá̌liáֽm׃p"],[39,1,"בַּ⁠שָּׁנָ֣ה הַ֠⁠תְּשִׁעִית לְ⁠צִדְקִיָּ֨הוּ מֶלֶךְ־יְהוּדָ֜ה בַּ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂרִ֗י בָּ֠א נְבוּכַדְרֶאצַּ֨ר מֶֽלֶךְ־בָּבֶ֤ל וְ⁠כָל־חֵיל⁠וֹ֙ אֶל־יְר֣וּשָׁלִַ֔ם וַ⁠יָּצֻ֖רוּ עָלֶֽי⁠הָ׃ס","bȧ⁠şá̇̌ná֣h ha֠⁠ţĕ̇şǐʻiyţ lĕ⁠ẕidĕqiyá̇֨hẇ melekĕ-yĕhẇdá֜h bȧ⁠ẖò֣deş̌ há⁠ʻàşîri֗y bá̇֠ʼ nĕbẇkadĕreʼẕȧ֨r meֽlekĕ-bá̇be֤l wĕ⁠kál-ẖéyl⁠wò֙ ʼel-yĕr֣ẇşá̌lia֔m wa⁠yá̇ẕu֖rẇ ʻáleֽy⁠há׃s"],[39,2,"בְּ⁠עַשְׁתֵּֽי־עֶשְׂרֵ֤ה שָׁנָה֙ לְ⁠צִדְקִיָּ֔הוּ בַּ⁠חֹ֥דֶשׁ הָ⁠רְבִיעִ֖י בְּ⁠תִשְׁעָ֣ה לַ⁠חֹ֑דֶשׁ הָבְקְעָ֖ה הָ⁠עִֽיר׃","bĕ̇⁠ʻaşĕ̌ţéֽ̇y-ʻeşĕ̂ré֤h şá̌náh֙ lĕ⁠ẕidĕqiyá̇֔hẇ bȧ⁠ẖò֥deş̌ há⁠rĕbiyʻi֖y bĕ̇⁠ţişĕ̌ʻá֣h la⁠ẖò֑deş̌ hábĕqĕʻá֖h há⁠ʻiֽyr׃"],[39,3,"וַ⁠יָּבֹ֗אוּ כֹּ֚ל שָׂרֵ֣י מֶֽלֶךְ־בָּבֶ֔ל וַ⁠יֵּשְׁב֖וּ בְּ⁠שַׁ֣עַר הַ⁠תָּ֑וֶךְ נֵרְגַ֣ל שַׂר־אֶ֠צֶר סַֽמְגַּר־נְב֞וּ שַׂר־סְכִ֣ים רַב־סָרִ֗יס נֵרְגַ֤ל שַׂר־אֶ֨צֶר֙ רַב־מָ֔ג וְ⁠כָל־שְׁאֵרִ֔ית שָׂרֵ֖י מֶ֥לֶךְ בָּבֶֽל׃","wa⁠yá̇bò֗ʼẇ kò֚̇l şá̂ré֣y meֽlekĕ-bá̇be֔l wa⁠yé̇şĕ̌b֖ẇ bĕ̇⁠şǎ֣ʻar ha⁠ţá֑̇wekĕ nérĕga֣l şâr-ʼe֠ẕer saֽmĕgȧr-nĕb֞ẇ şâr-sĕki֣ym rab-sári֗ys nérĕga֤l şâr-ʼe֨ẕer֙ rab-má֔g wĕ⁠kál-şĕ̌ʼéri֔yţ şá̂ré֖y me֥lekĕ bá̇beֽl׃"],[39,4,"וַ⁠יְהִ֡י כַּ⁠אֲשֶׁ֣ר רָ֠אָ⁠ם צִדְקִיָּ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה וְ⁠כֹ֣ל ׀ אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה וַֽ֠⁠יִּבְרְחוּ וַ⁠יֵּצְא֨וּ לַ֤יְלָה מִן־הָ⁠עִיר֙ דֶּ֚רֶךְ גַּ֣ן הַ⁠מֶּ֔לֶךְ בְּ⁠שַׁ֖עַר בֵּ֣ין הַ⁠חֹמֹתָ֑יִם וַ⁠יֵּצֵ֖א דֶּ֥רֶךְ הָ⁠עֲרָבָֽה׃","wa⁠yĕhi֡y kȧ⁠ʼàşě֣r rá֠ʼá⁠m ẕidĕqiyá̇֨hẇ meֽlekĕ-yĕhẇdá֜h wĕ⁠kò֣l ׀ ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h waֽ֠⁠yi̇bĕrĕẖẇ wa⁠yé̇ẕĕʼ֨ẇ la֤yĕláh min-há⁠ʻiyr֙ dė֚rekĕ gȧ֣n ha⁠mė֔lekĕ bĕ̇⁠şǎ֖ʻar bé֣̇yn ha⁠ẖòmòţá֑yim wa⁠yé̇ẕé֖ʼ dė֥rekĕ há⁠ʻàrábáֽh׃"],[39,5,"וַ⁠יִּרְדְּפ֨וּ חֵיל־כַּשְׂדִּ֜ים אַחֲרֵי⁠הֶ֗ם וַ⁠יַּשִּׂ֣גוּ אֶת־צִדְקִיָּהוּ֮ בְּ⁠עַֽרְב֣וֹת יְרֵחוֹ֒ וַ⁠יִּקְח֣וּ אֹת֗⁠וֹ וַֽ֠⁠יַּעֲלֻ⁠הוּ אֶל־נְבוּכַדְרֶאצַּ֧ר מֶֽלֶךְ־בָּבֶ֛ל רִבְלָ֖תָ⁠ה בְּ⁠אֶ֣רֶץ חֲמָ֑ת וַ⁠יְדַבֵּ֥ר אִתּ֖⁠וֹ מִשְׁפָּטִֽים׃","wa⁠yi̇rĕdĕ̇p֨ẇ ẖéyl-kȧşĕ̂di̇֜ym ʼaẖàréy⁠he֗m wa⁠yȧşi֣̇̂gẇ ʼeţ-ẕidĕqiyá̇hẇ֮ bĕ̇⁠ʻaֽrĕb֣wòţ yĕréẖwò֒ wa⁠yi̇qĕẖ֣ẇ ʼòţ֗⁠wò waֽ֠⁠yȧʻàlu⁠hẇ ʼel-nĕbẇkadĕreʼẕȧ֧r meֽlekĕ-bá̇be֛l ribĕlá֖ţá⁠h bĕ̇⁠ʼe֣reẕ ẖàmá֑ţ wa⁠yĕdabé֥̇r ʼiţ֖̇⁠wò mişĕ̌pá̇tiֽym׃"],[39,6,"וַ⁠יִּשְׁחַט֩ מֶ֨לֶךְ בָּבֶ֜ל אֶת־בְּנֵ֧י צִדְקִיָּ֛הוּ בְּ⁠רִבְלָ֖ה לְ⁠עֵינָ֑י⁠ו וְ⁠אֵת֙ כָּל־חֹרֵ֣י יְהוּדָ֔ה שָׁחַ֖ט מֶ֥לֶךְ בָּבֶֽל׃","wa⁠yi̇şĕ̌ẖat֩ me֨lekĕ bá̇be֜l ʼeţ-bĕ̇né֧y ẕidĕqiyá֛̇hẇ bĕ̇⁠ribĕlá֖h lĕ⁠ʻéyná֑y⁠w wĕ⁠ʼéţ֙ ká̇l-ẖòré֣y yĕhẇdá֔h şá̌ẖa֖t me֥lekĕ bá̇beֽl׃"],[39,7,"וְ⁠אֶת־עֵינֵ֥י צִדְקִיָּ֖הוּ עִוֵּ֑ר וַ⁠יַּאַסְרֵ֨⁠הוּ֙ בַּֽ⁠נְחֻשְׁתַּ֔יִם לָ⁠בִ֥יא אֹת֖⁠וֹ בָּבֶֽלָ⁠ה׃","wĕ⁠ʼeţ-ʻéyné֥y ẕidĕqiyá֖̇hẇ ʻiwé֑̇r wa⁠yȧʼasĕré֨⁠hẇ֙ bȧֽ⁠nĕẖuşĕ̌ţȧ֔yim lá⁠bi֥yʼ ʼòţ֖⁠wò bá̇beֽlá⁠h׃"],[39,8,"וְ⁠אֶת־בֵּ֤ית הַ⁠מֶּ֨לֶךְ֙ וְ⁠אֶת־בֵּ֣ית הָ⁠עָ֔ם שָׂרְפ֥וּ הַ⁠כַּשְׂדִּ֖ים בָּ⁠אֵ֑שׁ וְ⁠אֶת־חֹמ֥וֹת יְרוּשָׁלִַ֖ם נָתָֽצוּ׃","wĕ⁠ʼeţ-bé֤̇yţ ha⁠mė֨lekĕ֙ wĕ⁠ʼeţ-bé֣̇yţ há⁠ʻá֔m şá̂rĕp֥ẇ ha⁠kȧşĕ̂di֖̇ym bá̇⁠ʼé֑ş̌ wĕ⁠ʼeţ-ẖòm֥wòţ yĕrẇşá̌lia֖m náţáֽẕẇ׃"],[39,9,"וְ⁠אֵת֩ יֶ֨תֶר הָ⁠עָ֜ם הַ⁠נִּשְׁאָרִ֣ים בָּ⁠עִ֗יר וְ⁠אֶת־הַ⁠נֹּֽפְלִים֙ אֲשֶׁ֣ר נָפְל֣וּ עָלָ֔י⁠ו וְ⁠אֵ֛ת יֶ֥תֶר הָ⁠עָ֖ם הַ⁠נִּשְׁאָרִ֑ים הֶגְלָ֛ה נְבֽוּזַר־אֲדָ֥ן רַב־טַבָּחִ֖ים בָּבֶֽל׃","wĕ⁠ʼéţ֩ ye֨ţer há⁠ʻá֜m ha⁠ni̇şĕ̌ʼári֣ym bá̇⁠ʻi֗yr wĕ⁠ʼeţ-ha⁠nòֽ̇pĕliym֙ ʼàşě֣r nápĕl֣ẇ ʻálá֔y⁠w wĕ⁠ʼé֛ţ ye֥ţer há⁠ʻá֖m ha⁠ni̇şĕ̌ʼári֑ym hegĕlá֛h nĕbֽẇzar-ʼàdá֥n rab-tabá̇ẖi֖ym bá̇beֽl׃"],[39,10,"וּ⁠מִן־הָ⁠עָ֣ם הַ⁠דַּלִּ֗ים אֲשֶׁ֤ר אֵין־לָ⁠הֶם֙ מְא֔וּמָה הִשְׁאִ֛יר נְבוּזַרְאֲדָ֥ן רַב־טַבָּחִ֖ים בְּ⁠אֶ֣רֶץ יְהוּדָ֑ה וַ⁠יִּתֵּ֥ן לָ⁠הֶ֛ם כְּרָמִ֥ים וִֽ⁠יגֵבִ֖ים בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","ẇ⁠min-há⁠ʻá֣m ha⁠dȧli̇֗ym ʼàşě֤r ʼéyn-lá⁠hem֙ mĕʼ֔ẇmáh hişĕ̌ʼi֛yr nĕbẇzarĕʼàdá֥n rab-tabá̇ẖi֖ym bĕ̇⁠ʼe֣reẕ yĕhẇdá֑h wa⁠yi̇ţé֥̇n lá⁠he֛m kĕ̇rámi֥ym wiֽ⁠ygébi֖ym bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[39,11,"וַ⁠יְצַ֛ו נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל עַֽל־יִרְמְיָ֑הוּ בְּ⁠יַ֛ד נְבוּזַרְאֲדָ֥ן רַב־טַבָּחִ֖ים לֵ⁠אמֹֽר׃","wa⁠yĕẕa֛w nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l ʻaֽl-yirĕmĕyá֑hẇ bĕ̇⁠ya֛d nĕbẇzarĕʼàdá֥n rab-tabá̇ẖi֖ym lé⁠ʼmòֽr׃"],[39,12,"קָחֶ֗⁠נּוּ וְ⁠עֵינֶ֨י⁠ךָ֙ שִׂ֣ים עָלָ֔י⁠ו וְ⁠אַל־תַּ֥עַשׂ ל֖⁠וֹ מְא֣וּמָה רָּ֑ע כִּ֗י אם כַּֽ⁠אֲשֶׁר֙ יְדַבֵּ֣ר אֵלֶ֔י⁠ךָ כֵּ֖ן עֲשֵׂ֥ה עִמּֽ⁠וֹ׃","qáẖe֗⁠ṅẇ wĕ⁠ʻéyne֨y⁠ká֙ şî֣ym ʻálá֔y⁠w wĕ⁠ʼal-ţȧ֥ʻaş̂ l֖⁠wò mĕʼ֣ẇmáh rá֑̇ʻ ki̇֗y ʼm kȧֽ⁠ʼàşěr֙ yĕdabé֣̇r ʼéle֔y⁠ká ké֖̇n ʻàşé֥̂h ʻiṁֽ⁠wò׃"],[39,13,"וַ⁠יִּשְׁלַ֞ח נְבֽוּזַרְאֲדָ֣ן רַב־טַבָּחִ֗ים וּנְבֽוּשַׁזְבָּן֙ רַב־סָרִ֔יס וְ⁠נֵרְגַ֥ל שַׂר־אֶ֖צֶר רַב־מָ֑ג וְ⁠כֹ֖ל רַבֵּ֥י מֶֽלֶךְ־בָּבֶֽל׃","wa⁠yi̇şĕ̌la֞ẖ nĕbֽẇzarĕʼàdá֣n rab-tabá̇ẖi֗ym ẇnĕbֽẇşǎzĕbá̇n֙ rab-sári֔ys wĕ⁠nérĕga֥l şâr-ʼe֖ẕer rab-má֑g wĕ⁠kò֖l rabé֥̇y meֽlekĕ-bá̇beֽl׃"],[39,14,"וַ⁠יִּשְׁלְחוּ֩ וַ⁠יִּקְח֨וּ אֶֽת־יִרְמְיָ֜הוּ מֵ⁠חֲצַ֣ר הַ⁠מַּטָּרָ֗ה וַ⁠יִּתְּנ֤וּ אֹת⁠וֹ֙ אֶל־גְּדַלְיָ֨הוּ֙ בֶּן־אֲחִיקָ֣ם בֶּן־שָׁפָ֔ן לְ⁠הוֹצִאֵ֖⁠הוּ אֶל־הַ⁠בָּ֑יִת וַ⁠יֵּ֖שֶׁב בְּ⁠ת֥וֹךְ הָ⁠עָֽם׃ס","wa⁠yi̇şĕ̌lĕẖẇ֩ wa⁠yi̇qĕẖ֨ẇ ʼeֽţ-yirĕmĕyá֜hẇ mé⁠ẖàẕa֣r ha⁠mȧtá̇rá֗h wa⁠yi̇ţĕ̇n֤ẇ ʼòţ⁠wò֙ ʼel-gĕ̇dalĕyá֨hẇ֙ bėn-ʼàẖiyqá֣m bėn-şá̌pá֔n lĕ⁠hwòẕiʼé֖⁠hẇ ʼel-ha⁠bá֑̇yiţ wa⁠yé֖̇şěb bĕ̇⁠ţ֥wòkĕ há⁠ʻáֽm׃s"],[39,15,"וְ⁠אֶֽל־יִרְמְיָ֖הוּ הָיָ֣ה דְבַר־יְהוָ֑ה בִּֽ⁠הְיֹת֣⁠וֹ עָצ֔וּר בַּ⁠חֲצַ֥ר הַ⁠מַּטָּרָ֖ה לֵ⁠אמֹֽר׃","wĕ⁠ʼeֽl-yirĕmĕyá֖hẇ háyá֣h dĕbar-yĕhwá֑h biֽ̇⁠hĕyòţ֣⁠wò ʻáẕ֔ẇr bȧ⁠ẖàẕa֥r ha⁠mȧtá̇rá֖h lé⁠ʼmòֽr׃"],[39,16,"הָל֣וֹךְ וְ⁠אָמַרְתָּ֡ לְ⁠עֶבֶד־מֶ֨לֶךְ הַ⁠כּוּשִׁ֜י לֵ⁠אמֹ֗ר כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִי֩ מבי אֶת־דְּבָרַ֜⁠י אֶל־הָ⁠עִ֥יר הַ⁠זֹּ֛את לְ⁠רָעָ֖ה וְ⁠לֹ֣א לְ⁠טוֹבָ֑ה וְ⁠הָי֥וּ לְ⁠פָנֶ֖י⁠ךָ בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","hál֣wòkĕ wĕ⁠ʼámarĕţá̇֡ lĕ⁠ʻebed-me֨lekĕ ha⁠k̇ẇşǐ֜y lé⁠ʼmò֗r kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠niy֩ mby ʼeţ-dĕ̇bára֜⁠y ʼel-há⁠ʻi֥yr ha⁠zò֛̇ʼţ lĕ⁠ráʻá֖h wĕ⁠lò֣ʼ lĕ⁠twòbá֑h wĕ⁠háy֥ẇ lĕ⁠páne֖y⁠ká bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[39,17,"וְ⁠הִצַּלְתִּ֥י⁠ךָ בַ⁠יּוֹם־הַ⁠ה֖וּא נְאֻם־יְהוָ֑ה וְ⁠לֹ֤א תִנָּתֵן֙ בְּ⁠יַ֣ד הָֽ⁠אֲנָשִׁ֔ים אֲשֶׁר־אַתָּ֥ה יָג֖וֹר מִ⁠פְּנֵי⁠הֶֽם׃","wĕ⁠hiẕȧlĕţi֥̇y⁠ká ba⁠ẏwòm-ha⁠h֖ẇʼ nĕʼum-yĕhwá֑h wĕ⁠lò֤ʼ ţiná̇ţén֙ bĕ̇⁠ya֣d háֽ⁠ʼànáşǐ֔ym ʼàşěr-ʼaţá֥̇h yág֖wòr mi⁠pĕ̇néy⁠heֽm׃"],[39,18,"כִּ֤י מַלֵּט֙ אֲמַלֶּטְ⁠ךָ֔ וּ⁠בַ⁠חֶ֖רֶב לֹ֣א תִפֹּ֑ל וְ⁠הָיְתָ֨ה לְ⁠ךָ֤ נַפְשְׁ⁠ךָ֙ לְ⁠שָׁלָ֔ל כִּֽי־בָטַ֥חְתָּ בִּ֖⁠י נְאֻם־יְהוָֽה׃ס","ki֤̇y malé̇t֙ ʼàmalėtĕ⁠ká֔ ẇ⁠ba⁠ẖe֖reb lò֣ʼ ţipò֑̇l wĕ⁠háyĕţá֨h lĕ⁠ká֤ napĕşĕ̌⁠ká֙ lĕ⁠şá̌lá֔l kiֽ̇y-báta֥ẖĕţá̇ bi֖̇⁠y nĕʼum-yĕhwáֽh׃s"],[40,1,"הַ⁠דָּבָ֞ר אֲשֶׁר־הָיָ֤ה אֶֽל־יִרְמְיָ֨הוּ֙ מֵ⁠אֵ֣ת יְהוָ֔ה אַחַ֣ר ׀ שַׁלַּ֣ח אֹת֗⁠וֹ נְבוּזַרְאֲדָ֛ן רַב־טַבָּחִ֖ים מִן־הָֽ⁠רָמָ֑ה בְּ⁠קַחְתּ֣⁠וֹ אֹת֗⁠וֹ וְ⁠הֽוּא־אָס֤וּר בָּֽ⁠אזִקִּים֙ בְּ⁠ת֨וֹךְ כָּל־גָּל֤וּת יְרוּשָׁלִַ֨ם֙ וִֽ⁠יהוּדָ֔ה הַ⁠מֻּגְלִ֖ים בָּבֶֽלָ⁠ה׃","ha⁠dá̇bá֞r ʼàşěr-háyá֤h ʼeֽl-yirĕmĕyá֨hẇ֙ mé⁠ʼé֣ţ yĕhwá֔h ʼaẖa֣r ׀ şǎlȧ֣ẖ ʼòţ֗⁠wò nĕbẇzarĕʼàdá֛n rab-tabá̇ẖi֖ym min-háֽ⁠rámá֑h bĕ̇⁠qaẖĕţ֣̇⁠wò ʼòţ֗⁠wò wĕ⁠hֽẇʼ-ʼás֤ẇr báֽ̇⁠ʼziqi̇ym֙ bĕ̇⁠ţ֨wòkĕ ká̇l-gá̇l֤ẇţ yĕrẇşá̌lia֨m֙ wiֽ⁠yhẇdá֔h ha⁠mu̇gĕli֖ym bá̇beֽlá⁠h׃"],[40,2,"וַ⁠יִּקַּ֥ח רַב־טַבָּחִ֖ים לְ⁠יִרְמְיָ֑הוּ וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ דִּבֶּר֙ אֶת־הָ⁠רָעָ֣ה הַ⁠זֹּ֔את אֶל־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","wa⁠yi̇qȧ֥ẖ rab-tabá̇ẖi֖ym lĕ⁠yirĕmĕyá֑hẇ wa⁠yò֣̇ʼmer ʼélá֔y⁠w yĕhwá֣h ʼèlòhe֗y⁠ká di̇bėr֙ ʼeţ-há⁠ráʻá֣h ha⁠zò̇֔ʼţ ʼel-ha⁠má̇q֖wòm ha⁠zėֽh׃"],[40,3,"וַ⁠יָּבֵ֥א וַ⁠יַּ֛עַשׂ יְהוָ֖ה כַּ⁠אֲשֶׁ֣ר דִּבֵּ֑ר כִּֽי־חֲטָאתֶ֤ם לַֽ⁠יהוָה֙ וְ⁠לֹֽא־שְׁמַעְתֶּ֣ם בְּ⁠קוֹל֔⁠וֹ וְ⁠הָיָ֥ה לָ⁠כֶ֖ם דבר הַ⁠זֶּֽה׃","wa⁠yá̇bé֥ʼ wa⁠yȧ֛ʻaş̂ yĕhwá֖h kȧ⁠ʼàşě֣r di̇bé֑̇r kiֽ̇y-ẖàtáʼţe֤m laֽ⁠yhwáh֙ wĕ⁠lòֽʼ-şĕ̌maʻĕţė֣m bĕ̇⁠qwòl֔⁠wò wĕ⁠háyá֥h lá⁠ke֖m dbr ha⁠zėֽh׃"],[40,4,"וְ⁠עַתָּ֞ה הִנֵּ֧ה פִתַּחְתִּ֣י⁠ךָ הַ⁠יּ֗וֹם מִֽן־הָ⁠אזִקִּים֮ אֲשֶׁ֣ר עַל־יָדֶ⁠ךָ֒ אִם־ט֨וֹב בְּ⁠עֵינֶ֜י⁠ךָ לָ⁠ב֧וֹא אִתִּ֣⁠י בָבֶ֗ל בֹּ֚א וְ⁠אָשִׂ֤ים אֶת־עֵינִ⁠י֙ עָלֶ֔י⁠ךָ וְ⁠אִם־רַ֧ע בְּ⁠עֵינֶ֛י⁠ךָ לָ⁠בֽוֹא־אִתִּ֥⁠י בָבֶ֖ל חֲדָ֑ל רְאֵה֙ כָּל־הָ⁠אָ֣רֶץ לְ⁠פָנֶ֔י⁠ךָ אֶל־ט֨וֹב וְ⁠אֶל־הַ⁠יָּשָׁ֧ר בְּ⁠עֵינֶ֛י⁠ךָ לָ⁠לֶ֥כֶת שָׁ֖מָּ⁠ה לֵֽךְ׃","wĕ⁠ʻaţá̇֞h hiné֧̇h piţȧẖĕţi֣̇y⁠ká ha⁠ẏ֗wòm miֽn-há⁠ʼziqi̇ym֮ ʼàşě֣r ʻal-yáde⁠ká֒ ʼim-t֨wòb bĕ̇⁠ʻéyne֜y⁠ká lá⁠b֧wòʼ ʼiţi֣̇⁠y bábe֗l bò֚̇ʼ wĕ⁠ʼáşî֤ym ʼeţ-ʻéyni⁠y֙ ʻále֔y⁠ká wĕ⁠ʼim-ra֧ʻ bĕ̇⁠ʻéyne֛y⁠ká lá⁠bֽwòʼ-ʼiţi֥̇⁠y bábe֖l ẖàdá֑l rĕʼéh֙ ká̇l-há⁠ʼá֣reẕ lĕ⁠páne֔y⁠ká ʼel-t֨wòb wĕ⁠ʼel-ha⁠yá̇şá֧̌r bĕ̇⁠ʻéyne֛y⁠ká lá⁠le֥keţ şá֖̌má̇⁠h léֽkĕ׃"],[40,5,"וְ⁠עוֹדֶ֣⁠נּוּ לֹֽא־יָשׁ֗וּב וְ⁠שֻׁ֡בָ⁠ה אֶל־גְּדַלְיָ֣ה בֶן־אֲחִיקָ֣ם בֶּן־שָׁפָ֡ן אֲשֶׁר֩ הִפְקִ֨יד מֶֽלֶךְ־בָּבֶ֜ל בְּ⁠עָרֵ֣י יְהוּדָ֗ה וְ⁠שֵׁ֤ב אִתּ⁠וֹ֙ בְּ⁠ת֣וֹךְ הָ⁠עָ֔ם א֠וֹ אֶל־כָּל־הַ⁠יָּשָׁ֧ר בְּ⁠עֵינֶ֛י⁠ךָ לָ⁠לֶ֖כֶת לֵ֑ךְ וַ⁠יִּתֶּן־ל֧⁠וֹ רַב־טַבָּחִ֛ים אֲרֻחָ֥ה וּ⁠מַשְׂאֵ֖ת וַֽ⁠יְשַׁלְּחֵֽ⁠הוּ׃","wĕ⁠ʻwòde֣⁠ṅẇ lòֽʼ-yáş̌֗ẇb wĕ⁠şǔ֡bá⁠h ʼel-gĕ̇dalĕyá֣h ben-ʼàẖiyqá֣m bėn-şá̌pá֡n ʼàşěr֩ hipĕqi֨yd meֽlekĕ-bá̇be֜l bĕ̇⁠ʻáré֣y yĕhẇdá֗h wĕ⁠şé֤̌b ʼiţ̇⁠wò֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻá֔m ʼ֠wò ʼel-ká̇l-ha⁠yá̇şá֧̌r bĕ̇⁠ʻéyne֛y⁠ká lá⁠le֖keţ lé֑kĕ wa⁠yi̇ţėn-l֧⁠wò rab-tabá̇ẖi֛ym ʼàruẖá֥h ẇ⁠maşĕ̂ʼé֖ţ waֽ⁠yĕşǎlĕ̇ẖéֽ⁠hẇ׃"],[40,6,"וַ⁠יָּבֹ֧א יִרְמְיָ֛הוּ אֶל־גְּדַלְיָ֥ה בֶן־אֲחִיקָ֖ם הַ⁠מִּצְפָּ֑תָ⁠ה וַ⁠יֵּ֤שֶׁב אִתּ⁠וֹ֙ בְּ⁠ת֣וֹךְ הָ⁠עָ֔ם הַ⁠נִּשְׁאָרִ֖ים בָּ⁠אָֽרֶץ׃ס","wa⁠yá̇bò֧ʼ yirĕmĕyá֛hẇ ʼel-gĕ̇dalĕyá֥h ben-ʼàẖiyqá֖m ha⁠mi̇ẕĕpá֑̇ţá⁠h wa⁠yé֤̇şěb ʼiţ̇⁠wò֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻá֔m ha⁠ni̇şĕ̌ʼári֖ym bá̇⁠ʼáֽreẕ׃s"],[40,7,"וַ⁠יִּשְׁמְעוּ֩ כָל־שָׂרֵ֨י הַ⁠חֲיָלִ֜ים אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֗ה הֵ֚מָּה וְ⁠אַנְשֵׁי⁠הֶ֔ם כִּֽי־הִפְקִ֧יד מֶֽלֶךְ־בָּבֶ֛ל אֶת־גְּדַלְיָ֥הוּ בֶן־אֲחִיקָ֖ם בָּ⁠אָ֑רֶץ וְ⁠כִ֣י ׀ הִפְקִ֣יד אִתּ֗⁠וֹ אֲנָשִׁ֤ים וְ⁠נָשִׁים֙ וָ⁠טָ֔ף וּ⁠מִ⁠דַּלַּ֣ת הָ⁠אָ֔רֶץ מֵ⁠אֲשֶׁ֥ר לֹֽא־הָגְל֖וּ בָּבֶֽלָ⁠ה׃","wa⁠yi̇şĕ̌mĕʻẇ֩ kál-şá̂ré֨y ha⁠ẖàyáli֜ym ʼàşě֣r bȧ⁠şá̇̂de֗h hé֚má̇h wĕ⁠ʼanĕşé̌y⁠he֔m kiֽ̇y-hipĕqi֧yd meֽlekĕ-bá̇be֛l ʼeţ-gĕ̇dalĕyá֥hẇ ben-ʼàẖiyqá֖m bá̇⁠ʼá֑reẕ wĕ⁠ki֣y ׀ hipĕqi֣yd ʼiţ̇֗⁠wò ʼànáşǐ֤ym wĕ⁠náşǐym֙ wá⁠tá֔p ẇ⁠mi⁠dȧlȧ֣ţ há⁠ʼá֔reẕ mé⁠ʼàşě֥r lòֽʼ-hágĕl֖ẇ bá̇beֽlá⁠h׃"],[40,8,"וַ⁠יָּבֹ֥אוּ אֶל־גְּדַלְיָ֖ה הַ⁠מִּצְפָּ֑תָ⁠ה וְ⁠יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֡הוּ וְ⁠יוֹחָנָ֣ן וְ⁠יוֹנָתָ֣ן בְּנֵֽי־קָ֠רֵחַ וּ⁠שְׂרָיָ֨ה בֶן־תַּנְחֻ֜מֶת וּ⁠בְנֵ֣י ׀ עופי הַ⁠נְּטֹפָתִ֗י וִֽ⁠יזַנְיָ֨הוּ֙ בֶּן־הַ⁠מַּ֣עֲכָתִ֔י הֵ֖מָּה וְ⁠אַנְשֵׁי⁠הֶֽם׃","wa⁠yá̇bò֥ʼẇ ʼel-gĕ̇dalĕyá֖h ha⁠mi̇ẕĕpá֑̇ţá⁠h wĕ⁠yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֡hẇ wĕ⁠ywòẖáná֣n wĕ⁠ywònáţá֣n bĕ̇néֽy-qá֠réẖa ẇ⁠şĕ̂ráyá֨h ben-ţȧnĕẖu֜meţ ẇ⁠bĕné֣y ׀ ʻwpy ha⁠nĕ̇tòpáţi֗y wiֽ⁠yzanĕyá֨hẇ֙ bėn-ha⁠mȧ֣ʻàkáţi֔y hé֖má̇h wĕ⁠ʼanĕşé̌y⁠heֽm׃"],[40,9,"וַ⁠יִּשָּׁבַ֨ע לָ⁠הֶ֜ם גְּדַלְיָ֨הוּ בֶן־אֲחִיקָ֤ם בֶּן־שָׁפָן֙ וּ⁠לְ⁠אַנְשֵׁי⁠הֶ֣ם לֵ⁠אמֹ֔ר אַל־תִּֽירְא֖וּ מֵ⁠עֲב֣וֹד הַ⁠כַּשְׂדִּ֑ים שְׁב֣וּ בָ⁠אָ֗רֶץ וְ⁠עִבְד֛וּ אֶת־מֶ֥לֶךְ בָּבֶ֖ל וְ⁠יִיטַ֥ב לָ⁠כֶֽם׃","wa⁠yi̇şá̇̌ba֨ʻ lá⁠he֜m gĕ̇dalĕyá֨hẇ ben-ʼàẖiyqá֤m bėn-şá̌pán֙ ẇ⁠lĕ⁠ʼanĕşé̌y⁠he֣m lé⁠ʼmò֔r ʼal-ţiֽ̇yrĕʼ֖ẇ mé⁠ʻàb֣wòd ha⁠kȧşĕ̂di֑̇ym şĕ̌b֣ẇ bá⁠ʼá֗reẕ wĕ⁠ʻibĕd֛ẇ ʼeţ-me֥lekĕ bá̇be֖l wĕ⁠yiyta֥b lá⁠keֽm׃"],[40,10,"וַ⁠אֲנִ֗י הִנְ⁠נִ֤י יֹשֵׁב֙ בַּ⁠מִּצְפָּ֔ה לַֽ⁠עֲמֹד֙ לִ⁠פְנֵ֣י הַ⁠כַּשְׂדִּ֔ים אֲשֶׁ֥ר יָבֹ֖אוּ אֵלֵ֑י⁠נוּ וְ⁠אַתֶּ֡ם אִסְפוּ֩ יַ֨יִן וְ⁠קַ֜יִץ וְ⁠שֶׁ֗מֶן וְ⁠שִׂ֨מוּ֙ בִּ⁠כְלֵי⁠כֶ֔ם וּ⁠שְׁב֖וּ בְּ⁠עָרֵי⁠כֶ֥ם אֲשֶׁר־תְּפַשְׂתֶּֽם׃","wa⁠ʼàni֗y hinĕ⁠ni֤y yòşé̌b֙ bȧ⁠mi̇ẕĕpá̇֔h laֽ⁠ʻàmòd֙ li⁠pĕné֣y ha⁠kȧşĕ̂di̇֔ym ʼàşě֥r yábò֖ʼẇ ʼélé֑y⁠nẇ wĕ⁠ʼaţė֡m ʼisĕpẇ֩ ya֨yin wĕ⁠qa֜yiẕ wĕ⁠şě֗men wĕ⁠şî֨mẇ֙ bi̇⁠kĕléy⁠ke֔m ẇ⁠şĕ̌b֖ẇ bĕ̇⁠ʻáréy⁠ke֥m ʼàşěr-ţĕ̇paşĕ̂ţėֽm׃"],[40,11,"וְ⁠גַ֣ם כָּֽל־הַ⁠יְּהוּדִ֡ים אֲשֶׁר־בְּ⁠מוֹאָ֣ב ׀ וּ⁠בִ⁠בְנֵֽי־עַמּ֨וֹן וּ⁠בֶ⁠אֱד֜וֹם וַ⁠אֲשֶׁ֤ר בְּ⁠כָל־הָֽ⁠אֲרָצוֹת֙ שָֽׁמְע֔וּ כִּֽי־נָתַ֧ן מֶֽלֶךְ־בָּבֶ֛ל שְׁאֵרִ֖ית לִֽ⁠יהוּדָ֑ה וְ⁠כִי֙ הִפְקִ֣יד עֲלֵי⁠הֶ֔ם אֶת־גְּדַלְיָ֖הוּ בֶּן־אֲחִיקָ֥ם בֶּן־שָׁפָֽן׃","wĕ⁠ga֣m káֽ̇l-ha⁠yĕ̇hẇdi֡ym ʼàşěr-bĕ̇⁠mwòʼá֣b ׀ ẇ⁠bi⁠bĕnéֽy-ʻaṁ֨wòn ẇ⁠be⁠ʼèd֜wòm wa⁠ʼàşě֤r bĕ̇⁠kál-háֽ⁠ʼàráẕwòţ֙ şáֽ̌mĕʻ֔ẇ kiֽ̇y-náţa֧n meֽlekĕ-bá̇be֛l şĕ̌ʼéri֖yţ liֽ⁠yhẇdá֑h wĕ⁠kiy֙ hipĕqi֣yd ʻàléy⁠he֔m ʼeţ-gĕ̇dalĕyá֖hẇ bėn-ʼàẖiyqá֥m bėn-şá̌páֽn׃"],[40,12,"וַ⁠יָּשֻׁ֣בוּ כָל־הַ⁠יְּהוּדִ֗ים מִ⁠כָּל־הַ⁠מְּקֹמוֹת֙ אֲשֶׁ֣ר נִדְּחוּ־שָׁ֔ם וַ⁠יָּבֹ֧אוּ אֶֽרֶץ־יְהוּדָ֛ה אֶל־גְּדַלְיָ֖הוּ הַ⁠מִּצְפָּ֑תָ⁠ה וַ⁠יַּאַסְפ֛וּ יַ֥יִן וָ⁠קַ֖יִץ הַרְבֵּ֥ה מְאֹֽד׃פ","wa⁠yá̇şǔ֣bẇ kál-ha⁠yĕ̇hẇdi֗ym mi⁠ká̇l-ha⁠mĕ̇qòmwòţ֙ ʼàşě֣r nidĕ̇ẖẇ-şá̌֔m wa⁠yá̇bò֧ʼẇ ʼeֽreẕ-yĕhẇdá֛h ʼel-gĕ̇dalĕyá֖hẇ ha⁠mi̇ẕĕpá֑̇ţá⁠h wa⁠yȧʼasĕp֛ẇ ya֥yin wá⁠qa֖yiẕ harĕbé֥̇h mĕʼòֽd׃p"],[40,13,"וְ⁠יֽוֹחָנָן֙ בֶּן־קָרֵ֔חַ וְ⁠כָל־שָׂרֵ֥י הַ⁠חֲיָלִ֖ים אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֑ה בָּ֥אוּ אֶל־גְּדַלְיָ֖הוּ הַ⁠מִּצְפָּֽתָ⁠ה׃","wĕ⁠yֽwòẖánán֙ bėn-qáré֔ẖa wĕ⁠kál-şá̂ré֥y ha⁠ẖàyáli֖ym ʼàşě֣r bȧ⁠şá̇̂de֑h bá֥̇ʼẇ ʼel-gĕ̇dalĕyá֖hẇ ha⁠mi̇ẕĕpáֽ̇ţá⁠h׃"],[40,14,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו הֲ⁠יָדֹ֤עַ תֵּדַע֙ כִּ֞י בַּעֲלִ֣יס ׀ מֶ֣לֶךְ בְּנֵֽי־עַמּ֗וֹן שָׁלַח֙ אֶת־יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֔ה לְ⁠הַכֹּתְ⁠ךָ֖ נָ֑פֶשׁ וְ⁠לֹא־הֶאֱמִ֣ין לָ⁠הֶ֔ם גְּדַלְיָ֖הוּ בֶּן־אֲחִיקָֽם׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w hà⁠yádò֤ʻa ţé̇daʻ֙ ki̇֞y bȧʻàli֣ys ׀ me֣lekĕ bĕ̇néֽy-ʻaṁ֗wòn şá̌laẖ֙ ʼeţ-yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֔h lĕ⁠hakò̇ţĕ⁠ká֖ ná֑peş̌ wĕ⁠lòʼ-heʼèmi֣yn lá⁠he֔m gĕ̇dalĕyá֖hẇ bėn-ʼàẖiyqáֽm׃"],[40,15,"וְ⁠יוֹחָנָ֣ן בֶּן־קָרֵ֡חַ אָמַ֣ר אֶל־גְּדַלְיָהוּ֩ בַ⁠סֵּ֨תֶר בַּ⁠מִּצְפָּ֜ה לֵ⁠אמֹ֗ר אֵ֤לְכָה נָּא֙ וְ⁠אַכֶּה֙ אֶת־יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֔ה וְ⁠אִ֖ישׁ לֹ֣א יֵדָ֑ע לָ֧⁠מָּה יַכֶּ֣⁠כָּה נֶּ֗פֶשׁ וְ⁠נָפֹ֨צוּ֙ כָּל־יְהוּדָ֔ה הַ⁠נִּקְבָּצִ֣ים אֵלֶ֔י⁠ךָ וְ⁠אָבְדָ֖ה שְׁאֵרִ֥ית יְהוּדָֽה׃","wĕ⁠ywòẖáná֣n bėn-qáré֡ẖa ʼáma֣r ʼel-gĕ̇dalĕyáhẇ֩ ba⁠sé̇֨ţer bȧ⁠mi̇ẕĕpá̇֜h lé⁠ʼmò֗r ʼé֤lĕkáh ná̇ʼ֙ wĕ⁠ʼakėh֙ ʼeţ-yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֔h wĕ⁠ʼi֖yş̌ lò֣ʼ yédá֑ʻ lá֧⁠má̇h yakė֣⁠ká̇h nė֗peş̌ wĕ⁠nápò֨ẕẇ֙ ká̇l-yĕhẇdá֔h ha⁠ni̇qĕbá̇ẕi֣ym ʼéle֔y⁠ká wĕ⁠ʼábĕdá֖h şĕ̌ʼéri֥yţ yĕhẇdáֽh׃"],[40,16,"וַ⁠יֹּ֨אמֶר גְּדַלְיָ֤הוּ בֶן־אֲחִיקָם֙ אֶל־יוֹחָנָ֣ן בֶּן־קָרֵ֔חַ אַֽל־תעש אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה כִּֽי־שֶׁ֛קֶר אַתָּ֥ה דֹבֵ֖ר אֶל־יִשְׁמָעֵֽאל׃ס","wa⁠yò̇֨ʼmer gĕ̇dalĕyá֤hẇ ben-ʼàẖiyqám֙ ʼel-ywòẖáná֣n bėn-qáré֔ẖa ʼaֽl-ţʻş ʼeţ-ha⁠dá̇bá֣r ha⁠zė֑h kiֽ̇y-şě֛qer ʼaţá֥̇h dòbé֖r ʼel-yişĕ̌máʻéֽʼl׃s"],[41,1,"וַ⁠יְהִ֣י ׀ בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֗י בָּ֣א יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֣ה בֶן־אֱלִישָׁמָ֣ע מִ⁠זֶּ֣רַע הַ֠⁠מְּלוּכָה וְ⁠רַבֵּ֨י הַ⁠מֶּ֜לֶךְ וַ⁠עֲשָׂרָ֨ה אֲנָשִׁ֥ים אִתּ֛⁠וֹ אֶל־גְּדַלְיָ֥הוּ בֶן־אֲחִיקָ֖ם הַ⁠מִּצְפָּ֑תָ⁠ה וַ⁠יֹּ֨אכְלוּ שָׁ֥ם לֶ֛חֶם יַחְדָּ֖ו בַּ⁠מִּצְפָּֽה׃","wa⁠yĕhi֣y ׀ bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֗y bá֣̇ʼ yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֣h ben-ʼèliyşá̌má֣ʻ mi⁠zė֣raʻ ha֠⁠mĕ̇lẇkáh wĕ⁠rabé̇֨y ha⁠mė֜lekĕ wa⁠ʻàşá̂rá֨h ʼànáşǐ֥ym ʼiţ֛̇⁠wò ʼel-gĕ̇dalĕyá֥hẇ ben-ʼàẖiyqá֖m ha⁠mi̇ẕĕpá֑̇ţá⁠h wa⁠yò̇֨ʼkĕlẇ şá֥̌m le֛ẖem yaẖĕdá֖̇w bȧ⁠mi̇ẕĕpáֽ̇h׃"],[41,2,"וַ⁠יָּקָם֩ יִשְׁמָעֵ֨אל בֶּן־נְתַנְיָ֜ה וַ⁠עֲשֶׂ֥רֶת הָ⁠אֲנָשִׁ֣ים ׀ אֲשֶׁר־הָי֣וּ אִתּ֗⁠וֹ וַ֠⁠יַּכּוּ אֶת־גְּדַלְיָ֨הוּ בֶן־אֲחִיקָ֧ם בֶּן־שָׁפָ֛ן בַּ⁠חֶ֖רֶב וַ⁠יָּ֣מֶת אֹת֑⁠וֹ אֲשֶׁר־הִפְקִ֥יד מֶֽלֶךְ־בָּבֶ֖ל בָּ⁠אָֽרֶץ׃","wa⁠yá̇qám֩ yişĕ̌máʻé֨ʼl bėn-nĕţanĕyá֜h wa⁠ʻàşê֥reţ há⁠ʼànáşǐ֣ym ׀ ʼàşěr-háy֣ẇ ʼiţ̇֗⁠wò wa֠⁠yȧk̇ẇ ʼeţ-gĕ̇dalĕyá֨hẇ ben-ʼàẖiyqá֧m bėn-şá̌pá֛n bȧ⁠ẖe֖reb wa⁠yá֣̇meţ ʼòţ֑⁠wò ʼàşěr-hipĕqi֥yd meֽlekĕ-bá̇be֖l bá̇⁠ʼáֽreẕ׃"],[41,3,"וְ⁠אֵ֣ת כָּל־הַ⁠יְּהוּדִ֗ים אֲשֶׁר־הָי֨וּ אִתּ֤⁠וֹ אֶת־גְּדַלְיָ֨הוּ֙ בַּ⁠מִּצְפָּ֔ה וְ⁠אֶת־הַ⁠כַּשְׂדִּ֖ים אֲשֶׁ֣ר נִמְצְאוּ־שָׁ֑ם אֵ֚ת אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֔ה הִכָּ֖ה יִשְׁמָעֵֽאל׃","wĕ⁠ʼé֣ţ ká̇l-ha⁠yĕ̇hẇdi֗ym ʼàşěr-háy֨ẇ ʼiţ֤̇⁠wò ʼeţ-gĕ̇dalĕyá֨hẇ֙ bȧ⁠mi̇ẕĕpá̇֔h wĕ⁠ʼeţ-ha⁠kȧşĕ̂di֖̇ym ʼàşě֣r nimĕẕĕʼẇ-şá֑̌m ʼé֚ţ ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֔h hiká֖̇h yişĕ̌máʻéֽʼl׃"],[41,4,"וַ⁠יְהִ֛י בַּ⁠יּ֥וֹם הַ⁠שֵּׁנִ֖י לְ⁠הָמִ֣ית אֶת־גְּדַלְיָ֑הוּ וְ⁠אִ֖ישׁ לֹ֥א יָדָֽע׃","wa⁠yĕhi֛y bȧ⁠ẏ֥wòm ha⁠şé̇̌ni֖y lĕ⁠hámi֣yţ ʼeţ-gĕ̇dalĕyá֑hẇ wĕ⁠ʼi֖yş̌ lò֥ʼ yádáֽʻ׃"],[41,5,"וַ⁠יָּבֹ֣אוּ אֲ֠נָשִׁים מִ⁠שְּׁכֶ֞ם מִ⁠שִּׁל֤וֹ וּ⁠מִ⁠שֹּֽׁמְרוֹן֙ שְׁמֹנִ֣ים אִ֔ישׁ מְגֻלְּחֵ֥י זָקָ֛ן וּ⁠קְרֻעֵ֥י בְגָדִ֖ים וּ⁠מִתְגֹּֽדְדִ֑ים וּ⁠מִנְחָ֤ה וּ⁠לְבוֹנָה֙ בְּ⁠יָדָ֔⁠ם לְ⁠הָבִ֖יא בֵּ֥ית יְהוָֽה׃","wa⁠yá̇bò֣ʼẇ ʼà֠náşǐym mi⁠şĕ̇̌ke֞m mi⁠şi̇̌l֤wò ẇ⁠mi⁠şòֽ̇̌mĕrwòn֙ şĕ̌mòni֣ym ʼi֔yş̌ mĕgulĕ̇ẖé֥y záqá֛n ẇ⁠qĕruʻé֥y bĕgádi֖ym ẇ⁠miţĕgòֽ̇dĕdi֑ym ẇ⁠minĕẖá֤h ẇ⁠lĕbwònáh֙ bĕ̇⁠yádá֔⁠m lĕ⁠hábi֖yʼ bé֥̇yţ yĕhwáֽh׃"],[41,6,"וַ֠⁠יֵּצֵא יִשְׁמָעֵ֨אל בֶּן־נְתַנְיָ֤ה לִ⁠קְרָאתָ⁠ם֙ מִן־הַ⁠מִּצְפָּ֔ה הֹלֵ֥ךְ הָלֹ֖ךְ וּ⁠בֹכֶ֑ה וַֽ⁠יְהִי֙ כִּ⁠פְגֹ֣שׁ אֹתָ֔⁠ם וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם בֹּ֖אוּ אֶל־גְּדַלְיָ֥הוּ בֶן־אֲחִיקָֽם׃ס","wa֠⁠yé̇ẕéʼ yişĕ̌máʻé֨ʼl bėn-nĕţanĕyá֤h li⁠qĕráʼţá⁠m֙ min-ha⁠mi̇ẕĕpá̇֔h hòlé֥kĕ hálò֖kĕ ẇ⁠bòke֑h waֽ⁠yĕhiy֙ ki̇⁠pĕgò֣ş̌ ʼòţá֔⁠m wa⁠yò֣̇ʼmer ʼàléy⁠he֔m bò֖̇ʼẇ ʼel-gĕ̇dalĕyá֥hẇ ben-ʼàẖiyqáֽm׃s"],[41,7,"וַ⁠יְהִ֕י כְּ⁠בוֹאָ֖⁠ם אֶל־תּ֣וֹךְ הָ⁠עִ֑יר וַ⁠יִּשְׁחָטֵ֞⁠ם יִשְׁמָעֵ֤אל בֶּן־נְתַנְיָה֙ אֶל־תּ֣וֹךְ הַ⁠בּ֔וֹר ה֖וּא וְ⁠הָ⁠אֲנָשִׁ֥ים אֲשֶׁר־אִתּֽ⁠וֹ׃","wa⁠yĕhi֕y kĕ̇⁠bwòʼá֖⁠m ʼel-ţ֣̇wòkĕ há⁠ʻi֑yr wa⁠yi̇şĕ̌ẖáté֞⁠m yişĕ̌máʻé֤ʼl bėn-nĕţanĕyáh֙ ʼel-ţ֣̇wòkĕ ha⁠ḃ֔wòr h֖ẇʼ wĕ⁠há⁠ʼànáşǐ֥ym ʼàşěr-ʼiţֽ̇⁠wò׃"],[41,8,"וַ⁠עֲשָׂרָ֨ה אֲנָשִׁ֜ים נִמְצְאוּ־בָ֗⁠ם וַ⁠יֹּאמְר֤וּ אֶל־יִשְׁמָעֵאל֙ אַל־תְּמִתֵ֔⁠נוּ כִּֽי־יֶשׁ־לָ֤⁠נוּ מַטְמֹנִים֙ בַּ⁠שָּׂדֶ֔ה חִטִּ֥ים וּ⁠שְׂעֹרִ֖ים וְ⁠שֶׁ֣מֶן וּ⁠דְבָ֑שׁ וַ⁠יֶּחְדַּ֕ל וְ⁠לֹ֥א הֱמִיתָ֖⁠ם בְּ⁠ת֥וֹךְ אֲחֵי⁠הֶֽם׃","wa⁠ʻàşá̂rá֨h ʼànáşǐ֜ym nimĕẕĕʼẇ-bá֗⁠m wa⁠yò̇ʼmĕr֤ẇ ʼel-yişĕ̌máʻéʼl֙ ʼal-ţĕ̇miţé֔⁠nẇ kiֽ̇y-yeş̌-lá֤⁠nẇ matĕmòniym֙ bȧ⁠şá̇̂de֔h ẖiti֥̇ym ẇ⁠şĕ̂ʻòri֖ym wĕ⁠şě֣men ẇ⁠dĕbá֑ş̌ wa⁠yėẖĕdȧ֕l wĕ⁠lò֥ʼ hèmiyţá֖⁠m bĕ̇⁠ţ֥wòkĕ ʼàẖéy⁠heֽm׃"],[41,9,"וְ⁠הַ⁠בּ֗וֹר אֲשֶׁר֩ הִשְׁלִ֨יךְ שָׁ֤ם יִשְׁמָעֵאל֙ אֵ֣ת ׀ כָּל־פִּגְרֵ֣י הָ⁠אֲנָשִׁ֗ים אֲשֶׁ֤ר הִכָּה֙ בְּ⁠יַד־גְּדַלְיָ֔הוּ ה֗וּא אֲשֶׁ֤ר עָשָׂה֙ הַ⁠מֶּ֣לֶךְ אָסָ֔א מִ⁠פְּנֵ֖י בַּעְשָׁ֣א מֶֽלֶךְ־יִשְׂרָאֵ֑ל אֹת֗⁠וֹ מִלֵּ֛א יִשְׁמָעֵ֥אל בֶּן־נְתַנְיָ֖הוּ חֲלָלִֽים׃","wĕ⁠ha⁠ḃ֗wòr ʼàşěr֩ hişĕ̌li֨ykĕ şá֤̌m yişĕ̌máʻéʼl֙ ʼé֣ţ ׀ ká̇l-pi̇gĕré֣y há⁠ʼànáşǐ֗ym ʼàşě֤r hiká̇h֙ bĕ̇⁠yad-gĕ̇dalĕyá֔hẇ h֗ẇʼ ʼàşě֤r ʻáşá̂h֙ ha⁠mė֣lekĕ ʼásá֔ʼ mi⁠pĕ̇né֖y bȧʻĕşá֣̌ʼ meֽlekĕ-yişĕ̂ráʼé֑l ʼòţ֗⁠wò milé֛̇ʼ yişĕ̌máʻé֥ʼl bėn-nĕţanĕyá֖hẇ ẖàláliֽym׃"],[41,10,"וַ⁠יִּ֣שְׁבְּ ׀ יִ֠שְׁמָעֵאל אֶת־כָּל־שְׁאֵרִ֨ית הָ⁠עָ֜ם אֲשֶׁ֣ר בַּ⁠מִּצְפָּ֗ה אֶת־בְּנ֤וֹת הַ⁠מֶּ֨לֶךְ֙ וְ⁠אֶת־כָּל־הָ⁠עָם֙ הַ⁠נִּשְׁאָרִ֣ים בַּ⁠מִּצְפָּ֔ה אֲשֶׁ֣ר הִפְקִ֗יד נְבֽוּזַרְאֲדָן֙ רַב־טַבָּחִ֔ים אֶת־גְּדַלְיָ֖הוּ בֶּן־אֲחִיקָ֑ם וַ⁠יִּשְׁבֵּ⁠ם֙ יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֔ה וַ⁠יֵּ֕לֶךְ לַ⁠עֲבֹ֖ר אֶל־בְּנֵ֥י עַמּֽוֹן׃ס","wa⁠yi֣̇şĕ̌bĕ̇ ׀ yi֠şĕ̌máʻéʼl ʼeţ-ká̇l-şĕ̌ʼéri֨yţ há⁠ʻá֜m ʼàşě֣r bȧ⁠mi̇ẕĕpá̇֗h ʼeţ-bĕ̇n֤wòţ ha⁠mė֨lekĕ֙ wĕ⁠ʼeţ-ká̇l-há⁠ʻám֙ ha⁠ni̇şĕ̌ʼári֣ym bȧ⁠mi̇ẕĕpá̇֔h ʼàşě֣r hipĕqi֗yd nĕbֽẇzarĕʼàdán֙ rab-tabá̇ẖi֔ym ʼeţ-gĕ̇dalĕyá֖hẇ bėn-ʼàẖiyqá֑m wa⁠yi̇şĕ̌bé̇⁠m֙ yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֔h wa⁠yé̇֕lekĕ la⁠ʻàbò֖r ʼel-bĕ̇né֥y ʻaṁֽwòn׃s"],[41,11,"וַ⁠יִּשְׁמַע֙ יוֹחָנָ֣ן בֶּן־קָרֵ֔חַ וְ⁠כָל־שָׂרֵ֥י הַ⁠חֲיָלִ֖ים אֲשֶׁ֣ר אִתּ֑⁠וֹ אֵ֤ת כָּל־הָֽ⁠רָעָה֙ אֲשֶׁ֣ר עָשָׂ֔ה יִשְׁמָעֵ֖אל בֶּן־נְתַנְיָֽה׃","wa⁠yi̇şĕ̌maʻ֙ ywòẖáná֣n bėn-qáré֔ẖa wĕ⁠kál-şá̂ré֥y ha⁠ẖàyáli֖ym ʼàşě֣r ʼiţ֑̇⁠wò ʼé֤ţ ká̇l-háֽ⁠ráʻáh֙ ʼàşě֣r ʻáşá̂֔h yişĕ̌máʻé֖ʼl bėn-nĕţanĕyáֽh׃"],[41,12,"וַ⁠יִּקְחוּ֙ אֶת־כָּל־הָ֣⁠אֲנָשִׁ֔ים וַ⁠יֵּ֣לְכ֔וּ לְ⁠הִלָּחֵ֖ם עִם־יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֑ה וַ⁠יִּמְצְא֣וּ אֹת֔⁠וֹ אֶל־מַ֥יִם רַבִּ֖ים אֲשֶׁ֥ר בְּ⁠גִבְעֽוֹן׃","wa⁠yi̇qĕẖẇ֙ ʼeţ-ká̇l-há֣⁠ʼànáşǐ֔ym wa⁠yé֣̇lĕk֔ẇ lĕ⁠hilá̇ẖé֖m ʻim-yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֑h wa⁠yi̇mĕẕĕʼ֣ẇ ʼòţ֔⁠wò ʼel-ma֥yim rabi֖̇ym ʼàşě֥r bĕ̇⁠gibĕʻֽwòn׃"],[41,13,"וַ⁠יְהִ֗י כִּ⁠רְא֤וֹת כָּל־הָ⁠עָם֙ אֲשֶׁ֣ר אֶת־יִשְׁמָעֵ֔אל אֶת־יֽוֹחָנָן֙ בֶּן־קָרֵ֔חַ וְ⁠אֵ֛ת כָּל־שָׂרֵ֥י הַ⁠חֲיָלִ֖ים אֲשֶׁ֣ר אִתּ֑⁠וֹ וַ⁠יִּשְׂמָֽחוּ׃","wa⁠yĕhi֗y ki̇⁠rĕʼ֤wòţ ká̇l-há⁠ʻám֙ ʼàşě֣r ʼeţ-yişĕ̌máʻé֔ʼl ʼeţ-yֽwòẖánán֙ bėn-qáré֔ẖa wĕ⁠ʼé֛ţ ká̇l-şá̂ré֥y ha⁠ẖàyáli֖ym ʼàşě֣r ʼiţ֑̇⁠wò wa⁠yi̇şĕ̂máֽẖẇ׃"],[41,14,"וַ⁠יָּסֹ֨בּוּ֙ כָּל־הָ⁠עָ֔ם אֲשֶׁר־שָׁבָ֥ה יִשְׁמָעֵ֖אל מִן־הַ⁠מִּצְפָּ֑ה וַ⁠יָּשֻׁ֨בוּ֙ וַ⁠יֵּ֣לְכ֔וּ אֶל־יֽוֹחָנָ֖ן בֶּן־קָרֵֽחַ׃","wa⁠yá̇sò֨ḃẇ֙ ká̇l-há⁠ʻá֔m ʼàşěr-şá̌bá֥h yişĕ̌máʻé֖ʼl min-ha⁠mi̇ẕĕpá֑̇h wa⁠yá̇şǔ֨bẇ֙ wa⁠yé֣̇lĕk֔ẇ ʼel-yֽwòẖáná֖n bėn-qáréֽẖa׃"],[41,15,"וְ⁠יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֗ה נִמְלַט֙ בִּ⁠שְׁמֹנָ֣ה אֲנָשִׁ֔ים מִ⁠פְּנֵ֖י יֽוֹחָנָ֑ן וַ⁠יֵּ֖לֶךְ אֶל־בְּנֵ֥י עַמּֽוֹן׃ס","wĕ⁠yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֗h nimĕlat֙ bi̇⁠şĕ̌mòná֣h ʼànáşǐ֔ym mi⁠pĕ̇né֖y yֽwòẖáná֑n wa⁠yé֖̇lekĕ ʼel-bĕ̇né֥y ʻaṁֽwòn׃s"],[41,16,"וַ⁠יִּקַּח֩ יוֹחָנָ֨ן בֶּן־קָרֵ֜חַ וְ⁠כָל־שָׂרֵ֧י הַ⁠חֲיָלִ֣ים אֲשֶׁר־אִתּ֗⁠וֹ אֵ֣ת כָּל־שְׁאֵרִ֤ית הָ⁠עָם֙ אֲשֶׁ֣ר הֵ֠שִׁיב מֵ⁠אֵ֨ת יִשְׁמָעֵ֤אל בֶּן־נְתַנְיָה֙ מִן־הַ⁠מִּצְפָּ֔ה אַחַ֣ר הִכָּ֔ה אֶת־גְּדַלְיָ֖ה בֶּן־אֲחִיקָ֑ם גְּבָרִ֞ים אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה וְ⁠נָשִׁ֤ים וְ⁠טַף֙ וְ⁠סָ֣רִסִ֔ים אֲשֶׁ֥ר הֵשִׁ֖יב מִ⁠גִּבְעֽוֹן׃","wa⁠yi̇qȧẖ֩ ywòẖáná֨n bėn-qáré֜ẖa wĕ⁠kál-şá̂ré֧y ha⁠ẖàyáli֣ym ʼàşěr-ʼiţ̇֗⁠wò ʼé֣ţ ká̇l-şĕ̌ʼéri֤yţ há⁠ʻám֙ ʼàşě֣r hé֠şǐyb mé⁠ʼé֨ţ yişĕ̌máʻé֤ʼl bėn-nĕţanĕyáh֙ min-ha⁠mi̇ẕĕpá̇֔h ʼaẖa֣r hiká̇֔h ʼeţ-gĕ̇dalĕyá֖h bėn-ʼàẖiyqá֑m gĕ̇bári֞ym ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h wĕ⁠náşǐ֤ym wĕ⁠tap֙ wĕ⁠sá֣risi֔ym ʼàşě֥r héşǐ֖yb mi⁠gi̇bĕʻֽwòn׃"],[41,17,"וַ⁠יֵּלְכ֗וּ וַ⁠יֵּֽשְׁבוּ֙ בְּ⁠גֵר֣וּת כמו⁠הם אֲשֶׁר־אֵ֖צֶל בֵּ֣ית לָ֑חֶם לָ⁠לֶ֖כֶת לָ⁠ב֥וֹא מִצְרָֽיִם׃","wa⁠yé̇lĕk֗ẇ wa⁠yéֽ̇şĕ̌bẇ֙ bĕ̇⁠gér֣ẇţ kmw⁠hm ʼàşěr-ʼé֖ẕel bé֣̇yţ lá֑ẖem lá⁠le֖keţ lá⁠b֥wòʼ miẕĕráֽyim׃"],[41,18,"מִ⁠פְּנֵי֙ הַ⁠כַּשְׂדִּ֔ים כִּ֥י יָרְא֖וּ מִ⁠פְּנֵי⁠הֶ֑ם כִּֽי־הִכָּ֞ה יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֗ה אֶת־גְּדַלְיָ֨הוּ֙ בֶּן־אֲחִיקָ֔ם אֲשֶׁר־הִפְקִ֥יד מֶֽלֶךְ־בָּבֶ֖ל בָּ⁠אָֽרֶץ׃ס","mi⁠pĕ̇néy֙ ha⁠kȧşĕ̂di̇֔ym ki֥̇y yárĕʼ֖ẇ mi⁠pĕ̇néy⁠he֑m kiֽ̇y-hiká̇֞h yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֗h ʼeţ-gĕ̇dalĕyá֨hẇ֙ bėn-ʼàẖiyqá֔m ʼàşěr-hipĕqi֥yd meֽlekĕ-bá̇be֖l bá̇⁠ʼáֽreẕ׃s"],[42,1,"וַֽ⁠יִּגְּשׁוּ֙ כָּל־שָׂרֵ֣י הַ⁠חֲיָלִ֔ים וְ⁠יֽוֹחָנָן֙ בֶּן־קָרֵ֔חַ וִֽ⁠יזַנְיָ֖ה בֶּן־הוֹשַֽׁעְיָ֑ה וְ⁠כָל־הָ⁠עָ֖ם מִ⁠קָּטֹ֥ן וְ⁠עַד־גָּדֽוֹל׃","waֽ⁠yi̇gĕ̇ş̌ẇ֙ ká̇l-şá̂ré֣y ha⁠ẖàyáli֔ym wĕ⁠yֽwòẖánán֙ bėn-qáré֔ẖa wiֽ⁠yzanĕyá֖h bėn-hwòşǎֽʻĕyá֑h wĕ⁠kál-há⁠ʻá֖m mi⁠qá̇tò֥n wĕ⁠ʻad-gá̇dֽwòl׃"],[42,2,"וַ⁠יֹּאמְר֞וּ אֶֽל־יִרְמְיָ֣הוּ הַ⁠נָּבִ֗יא תִּפָּל־נָ֤א תְחִנָּתֵ֨⁠נוּ֙ לְ⁠פָנֶ֔י⁠ךָ וְ⁠הִתְפַּלֵּ֤ל בַּעֲדֵ֨⁠נוּ֙ אֶל־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּעַ֖ד כָּל־הַ⁠שְּׁאֵרִ֣ית הַ⁠זֹּ֑את כִּֽי־נִשְׁאַ֤רְנוּ מְעַט֙ מֵֽ⁠הַרְבֵּ֔ה כַּ⁠אֲשֶׁ֥ר עֵינֶ֖י⁠ךָ רֹא֥וֹת אֹתָֽ⁠נוּ׃","wa⁠yò̇ʼmĕr֞ẇ ʼeֽl-yirĕmĕyá֣hẇ ha⁠ná̇bi֗yʼ ţi̇pá̇l-ná֤ʼ ţĕẖiná̇ţé֨⁠nẇ֙ lĕ⁠páne֔y⁠ká wĕ⁠hiţĕpȧlé֤̇l bȧʻàdé֨⁠nẇ֙ ʼel-yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇ʻa֖d ká̇l-ha⁠şĕ̇̌ʼéri֣yţ ha⁠zò֑̇ʼţ kiֽ̇y-nişĕ̌ʼa֤rĕnẇ mĕʻat֙ méֽ⁠harĕbé̇֔h kȧ⁠ʼàşě֥r ʻéyne֖y⁠ká ròʼ֥wòţ ʼòţáֽ⁠nẇ׃"],[42,3,"וְ⁠יַגֶּד־לָ֨⁠נוּ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֶת־הַ⁠דֶּ֖רֶךְ אֲשֶׁ֣ר נֵֽלֶךְ־בָּ֑⁠הּ וְ⁠אֶת־הַ⁠דָּבָ֖ר אֲשֶׁ֥ר נַעֲשֶֽׂה׃","wĕ⁠yagėd-lá֨⁠nẇ֙ yĕhwá֣h ʼèlòhe֔y⁠ká ʼeţ-ha⁠dė֖rekĕ ʼàşě֣r néֽlekĕ-bá֑̇⁠ḣ wĕ⁠ʼeţ-ha⁠dá̇bá֖r ʼàşě֥r naʻàşêֽh׃"],[42,4,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם יִרְמְיָ֤הוּ הַ⁠נָּבִיא֙ שָׁמַ֔עְתִּי הִנְ⁠נִ֧י מִתְפַּלֵּ֛ל אֶל־יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם כְּ⁠דִבְרֵי⁠כֶ֑ם וְֽ⁠הָיָ֡ה כָּֽל־הַ⁠דָּבָר֩ אֲשֶׁר־יַעֲנֶ֨ה יְהוָ֤ה אֶתְ⁠כֶם֙ אַגִּ֣יד לָ⁠כֶ֔ם לֹֽא־אֶמְנַ֥ע מִ⁠כֶּ֖ם דָּבָֽר׃","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m yirĕmĕyá֤hẇ ha⁠ná̇biyʼ֙ şá̌ma֔ʻĕţi̇y hinĕ⁠ni֧y miţĕpȧlé֛̇l ʼel-yĕhwá֥h ʼèlòhéy⁠ke֖m kĕ̇⁠dibĕréy⁠ke֑m wĕֽ⁠háyá֡h káֽ̇l-ha⁠dá̇bár֩ ʼàşěr-yaʻàne֨h yĕhwá֤h ʼeţĕ⁠kem֙ ʼagi֣̇yd lá⁠ke֔m lòֽʼ-ʼemĕna֥ʻ mi⁠kė֖m dá̇báֽr׃"],[42,5,"וְ⁠הֵ֨מָּה֙ אָמְר֣וּ אֶֽל־יִרְמְיָ֔הוּ יְהִ֤י יְהוָה֙ בָּ֔⁠נוּ לְ⁠עֵ֖ד אֱמֶ֣ת וְ⁠נֶאֱמָ֑ן אִם־לֹ֡א כְּֽ⁠כָל־הַ֠⁠דָּבָר אֲשֶׁ֨ר יִֽשְׁלָחֲ⁠ךָ֜ יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ אֵלֵ֖י⁠נוּ כֵּ֥ן נַעֲשֶֽׂה׃","wĕ⁠hé֨má̇h֙ ʼámĕr֣ẇ ʼeֽl-yirĕmĕyá֔hẇ yĕhi֤y yĕhwáh֙ bá̇֔⁠nẇ lĕ⁠ʻé֖d ʼème֣ţ wĕ⁠neʼèmá֑n ʼim-lò֡ʼ kĕֽ̇⁠kál-ha֠⁠dá̇bár ʼàşě֨r yiֽşĕ̌láẖà⁠ká֜ yĕhwá֧h ʼèlòhe֛y⁠ká ʼélé֖y⁠nẇ ké֥̇n naʻàşêֽh׃"],[42,6,"אִם־ט֣וֹב וְ⁠אִם־רָ֔ע בְּ⁠ק֣וֹל ׀ יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ אֲשֶׁ֨ר אנו שֹׁלְחִ֥ים אֹתְ⁠ךָ֛ אֵלָ֖י⁠ו נִשְׁמָ֑ע לְמַ֨עַן֙ אֲשֶׁ֣ר יִֽיטַב־לָ֔⁠נוּ כִּ֣י נִשְׁמַ֔ע בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃ס","ʼim-t֣wòb wĕ⁠ʼim-rá֔ʻ bĕ̇⁠q֣wòl ׀ yĕhwá֣h ʼèlòhé֗y⁠nẇ ʼàşě֨r ʼnw şò̌lĕẖi֥ym ʼòţĕ⁠ká֛ ʼélá֖y⁠w nişĕ̌má֑ʻ lĕma֨ʻan֙ ʼàşě֣r yiֽytab-lá֔⁠nẇ ki֣̇y nişĕ̌ma֔ʻ bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòhéֽy⁠nẇ׃s"],[42,7,"וַ⁠יְהִ֕י מִ⁠קֵּ֖ץ עֲשֶׂ֣רֶת יָמִ֑ים וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֶֽל־יִרְמְיָֽהוּ׃","wa⁠yĕhi֕y mi⁠qé֖̇ẕ ʻàşê֣reţ yámi֑ym wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼeֽl-yirĕmĕyáֽhẇ׃"],[42,8,"וַ⁠יִּקְרָ֗א אֶל־יֽוֹחָנָן֙ בֶּן־קָרֵ֔חַ וְ⁠אֶ֛ל כָּל־שָׂרֵ֥י הַ⁠חֲיָלִ֖ים אֲשֶׁ֣ר אִתּ֑⁠וֹ וּ⁠לְ⁠כָ֨ל־הָ⁠עָ֔ם לְ⁠מִ⁠קָּטֹ֥ן וְ⁠עַד־גָּדֽוֹל׃","wa⁠yi̇qĕrá֗ʼ ʼel-yֽwòẖánán֙ bėn-qáré֔ẖa wĕ⁠ʼe֛l ká̇l-şá̂ré֥y ha⁠ẖàyáli֖ym ʼàşě֣r ʼiţ֑̇⁠wò ẇ⁠lĕ⁠ká֨l-há⁠ʻá֔m lĕ⁠mi⁠qá̇tò֥n wĕ⁠ʻad-gá̇dֽwòl׃"],[42,9,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אֲשֶׁ֨ר שְׁלַחְתֶּ֤ם אֹתִ⁠י֙ אֵלָ֔י⁠ו לְ⁠הַפִּ֥יל תְּחִנַּתְ⁠כֶ֖ם לְ⁠פָנָֽי⁠ו׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֔m kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼàşě֨r şĕ̌laẖĕţė֤m ʼòţi⁠y֙ ʼélá֔y⁠w lĕ⁠hapi֥̇yl ţĕ̇ẖinȧţĕ⁠ke֖m lĕ⁠pánáֽy⁠w׃"],[42,10,"אִם־שׁ֤וֹב תֵּֽשְׁבוּ֙ בָּ⁠אָ֣רֶץ הַ⁠זֹּ֔את וּ⁠בָנִ֤יתִי אֶתְ⁠כֶם֙ וְ⁠לֹ֣א אֶהֱרֹ֔ס וְ⁠נָטַעְתִּ֥י אֶתְ⁠כֶ֖ם וְ⁠לֹ֣א אֶתּ֑וֹשׁ כִּ֤י נִחַ֨מְתִּי֙ אֶל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר עָשִׂ֖יתִי לָ⁠כֶֽם׃","ʼim-ş֤̌wòb ţéֽ̇şĕ̌bẇ֙ bá̇⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ẇ⁠báni֤yţiy ʼeţĕ⁠kem֙ wĕ⁠lò֣ʼ ʼehèrò֔s wĕ⁠nátaʻĕţi֥̇y ʼeţĕ⁠ke֖m wĕ⁠lò֣ʼ ʼeţ֑̇wòş̌ ki֤̇y niẖa֨mĕţi̇y֙ ʼel-há֣⁠ráʻá֔h ʼàşě֥r ʻáşî֖yţiy lá⁠keֽm׃"],[42,11,"אַל־תִּֽירְא֗וּ מִ⁠פְּנֵי֙ מֶ֣לֶךְ בָּבֶ֔ל אֲשֶׁר־אַתֶּ֥ם יְרֵאִ֖ים מִ⁠פָּנָ֑י⁠ו אַל־תִּֽירְא֤וּ מִמֶּ֨⁠נּוּ֙ נְאֻם־יְהוָ֔ה כִּֽי־אִתְּ⁠כֶ֣ם אָ֔נִי לְ⁠הוֹשִׁ֧יעַ אֶתְ⁠כֶ֛ם וּ⁠לְ⁠הַצִּ֥יל אֶתְ⁠כֶ֖ם מִ⁠יָּדֽ⁠וֹ׃","ʼal-ţiֽ̇yrĕʼ֗ẇ mi⁠pĕ̇néy֙ me֣lekĕ bá̇be֔l ʼàşěr-ʼaţė֥m yĕréʼi֖ym mi⁠pá̇ná֑y⁠w ʼal-ţiֽ̇yrĕʼ֤ẇ mimė֨⁠ṅẇ֙ nĕʼum-yĕhwá֔h kiֽ̇y-ʼiţĕ̇⁠ke֣m ʼá֔niy lĕ⁠hwòşǐ֧yʻa ʼeţĕ⁠ke֛m ẇ⁠lĕ⁠haẕi֥̇yl ʼeţĕ⁠ke֖m mi⁠yá̇dֽ⁠wò׃"],[42,12,"וְ⁠אֶתֵּ֥ן לָ⁠כֶ֛ם רַחֲמִ֖ים וְ⁠רִחַ֣ם אֶתְ⁠כֶ֑ם וְ⁠הֵשִׁ֥יב אֶתְ⁠כֶ֖ם אֶל־אַדְמַתְ⁠כֶֽם׃","wĕ⁠ʼeţé֥̇n lá⁠ke֛m raẖàmi֖ym wĕ⁠riẖa֣m ʼeţĕ⁠ke֑m wĕ⁠héşǐ֥yb ʼeţĕ⁠ke֖m ʼel-ʼadĕmaţĕ⁠keֽm׃"],[42,13,"וְ⁠אִם־אֹמְרִ֣ים אַתֶּ֔ם לֹ֥א נֵשֵׁ֖ב בָּ⁠אָ֣רֶץ הַ⁠זֹּ֑את לְ⁠בִלְתִּ֣י שְׁמֹ֔עַ בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠ʼim-ʼòmĕri֣ym ʼaţė֔m lò֥ʼ néşé֖̌b bá̇⁠ʼá֣reẕ ha⁠zò֑̇ʼţ lĕ⁠bilĕţi֣̇y şĕ̌mò֔ʻa bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[42,14,"לֵ⁠אמֹ֗ר לֹ֚א כִּ֣י אֶ֤רֶץ מִצְרַ֨יִם֙ נָב֔וֹא אֲשֶׁ֤ר לֹֽא־נִרְאֶה֙ מִלְחָמָ֔ה וְ⁠ק֥וֹל שׁוֹפָ֖ר לֹ֣א נִשְׁמָ֑ע וְ⁠לַ⁠לֶּ֥חֶם לֹֽא־נִרְעָ֖ב וְ⁠שָׁ֥ם נֵשֵֽׁב׃","lé⁠ʼmò֗r lò֚ʼ ki֣̇y ʼe֤reẕ miẕĕra֨yim֙ náb֔wòʼ ʼàşě֤r lòֽʼ-nirĕʼeh֙ milĕẖámá֔h wĕ⁠q֥wòl ş̌wòpá֖r lò֣ʼ nişĕ̌má֑ʻ wĕ⁠la⁠lė֥ẖem lòֽʼ-nirĕʻá֖b wĕ⁠şá֥̌m néşéֽ̌b׃"],[42,15,"וְ⁠עַתָּ֕ה לָ⁠כֵ֛ן שִׁמְע֥וּ דְבַר־יְהוָ֖ה שְׁאֵרִ֣ית יְהוּדָ֑ה כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל אִם־אַ֠תֶּם שׂ֣וֹם תְּשִׂמ֤וּ⁠ן פְּנֵי⁠כֶם֙ לָ⁠בֹ֣א מִצְרַ֔יִם וּ⁠בָאתֶ֖ם לָ⁠ג֥וּר שָֽׁם׃","wĕ⁠ʻaţá̇֕h lá⁠ké֛n şǐmĕʻ֥ẇ dĕbar-yĕhwá֖h şĕ̌ʼéri֣yţ yĕhẇdá֑h kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l ʼim-ʼa֠ţėm ş֣̂wòm ţĕ̇şîm֤ẇ⁠n pĕ̇néy⁠kem֙ lá⁠bò֣ʼ miẕĕra֔yim ẇ⁠báʼţe֖m lá⁠g֥ẇr şáֽ̌m׃"],[42,16,"וְ⁠הָיְתָ֣ה הַ⁠חֶ֗רֶב אֲשֶׁ֤ר אַתֶּם֙ יְרֵאִ֣ים מִמֶּ֔⁠נָּה שָׁ֛ם תַּשִּׂ֥יג אֶתְ⁠כֶ֖ם בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠הָ⁠רָעָ֞ב אֲשֶׁר־אַתֶּ֣ם ׀ דֹּאֲגִ֣ים מִמֶּ֗⁠נּוּ שָׁ֣ם יִדְבַּ֧ק אַחֲרֵי⁠כֶ֛ם מִצְרַ֖יִם וְ⁠שָׁ֥ם תָּמֻֽתוּ׃","wĕ⁠háyĕţá֣h ha⁠ẖe֗reb ʼàşě֤r ʼaţėm֙ yĕréʼi֣ym mimė֔⁠ná̇h şá֛̌m ţȧşi֥̇̂yg ʼeţĕ⁠ke֖m bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠há⁠ráʻá֞b ʼàşěr-ʼaţė֣m ׀ dò̇ʼàgi֣ym mimė֗⁠ṅẇ şá֣̌m yidĕbȧ֧q ʼaẖàréy⁠ke֛m miẕĕra֖yim wĕ⁠şá֥̌m ţá̇muֽţẇ׃"],[42,17,"וְ⁠יִֽהְי֣וּ כָל־הָ⁠אֲנָשִׁ֗ים אֲשֶׁר־שָׂ֨מוּ אֶת־פְּנֵי⁠הֶ֜ם לָ⁠ב֤וֹא מִצְרַ֨יִם֙ לָ⁠ג֣וּר שָׁ֔ם יָמ֕וּתוּ בַּ⁠חֶ֖רֶב בָּ⁠רָעָ֣ב וּ⁠בַ⁠דָּ֑בֶר וְ⁠לֹֽא־יִהְיֶ֤ה לָ⁠הֶם֙ שָׂרִ֣יד וּ⁠פָלִ֔יט מִ⁠פְּנֵי֙ הָֽ⁠רָעָ֔ה אֲשֶׁ֥ר אֲנִ֖י מֵבִ֥יא עֲלֵי⁠הֶֽם׃ס","wĕ⁠yiֽhĕy֣ẇ kál-há⁠ʼànáşǐ֗ym ʼàşěr-şá̂֨mẇ ʼeţ-pĕ̇néy⁠he֜m lá⁠b֤wòʼ miẕĕra֨yim֙ lá⁠g֣ẇr şá̌֔m yám֕ẇţẇ bȧ⁠ẖe֖reb bá̇⁠ráʻá֣b ẇ⁠ba⁠dá֑̇ber wĕ⁠lòֽʼ-yihĕye֤h lá⁠hem֙ şá̂ri֣yd ẇ⁠páli֔yt mi⁠pĕ̇néy֙ háֽ⁠ráʻá֔h ʼàşě֥r ʼàni֖y mébi֥yʼ ʻàléy⁠heֽm׃s"],[42,18,"כִּי֩ כֹ֨ה אָמַ֜ר יְהוָ֣ה צְבָאוֹת֮ אֱלֹהֵ֣י יִשְׂרָאֵל֒ כַּ⁠אֲשֶׁר֩ נִתַּ֨ךְ אַפִּ֜⁠י וַ⁠חֲמָתִ֗⁠י עַל־יֹֽשְׁבֵי֙ יְר֣וּשָׁלִַ֔ם כֵּ֣ן תִּתַּ֤ךְ חֲמָתִ⁠י֙ עֲלֵי⁠כֶ֔ם בְּ⁠בֹאֲ⁠כֶ֖ם מִצְרָ֑יִם וִ⁠הְיִיתֶ֞ם לְ⁠אָלָ֤ה וּ⁠לְ⁠שַׁמָּה֙ וְ⁠לִ⁠קְלָלָ֣ה וּ⁠לְ⁠חֶרְפָּ֔ה וְ⁠לֹֽא־תִרְא֣וּ ע֔וֹד אֶת־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","ki̇y֩ kò֨h ʼáma֜r yĕhwá֣h ẕĕbáʼwòţ֮ ʼèlòhé֣y yişĕ̂ráʼél֒ kȧ⁠ʼàşěr֩ niţȧ֨kĕ ʼapi̇֜⁠y wa⁠ẖàmáţi֗⁠y ʻal-yòֽşĕ̌béy֙ yĕr֣ẇşá̌lia֔m ké֣̇n ţi̇ţȧ֤kĕ ẖàmáţi⁠y֙ ʻàléy⁠ke֔m bĕ̇⁠bòʼà⁠ke֖m miẕĕrá֑yim wi⁠hĕyiyţe֞m lĕ⁠ʼálá֤h ẇ⁠lĕ⁠şǎmá̇h֙ wĕ⁠li⁠qĕlálá֣h ẇ⁠lĕ⁠ẖerĕpá̇֔h wĕ⁠lòֽʼ-ţirĕʼ֣ẇ ʻ֔wòd ʼeţ-ha⁠má̇q֖wòm ha⁠zėֽh׃"],[42,19,"דִּבֶּ֨ר יְהוָ֤ה עֲלֵי⁠כֶם֙ שְׁאֵרִ֣ית יְהוּדָ֔ה אַל־תָּבֹ֖אוּ מִצְרָ֑יִם יָדֹ֨עַ֙ תֵּֽדְע֔וּ כִּי־הַעִידֹ֥תִי בָ⁠כֶ֖ם הַ⁠יּֽוֹם׃","di̇bė֨r yĕhwá֤h ʻàléy⁠kem֙ şĕ̌ʼéri֣yţ yĕhẇdá֔h ʼal-ţá̇bò֖ʼẇ miẕĕrá֑yim yádò֨ʻa֙ ţéֽ̇dĕʻ֔ẇ ki̇y-haʻiydò֥ţiy bá⁠ke֖m ha⁠ẏֽwòm׃"],[42,20,"כִּ֣י התעתי⁠ם בְּ⁠נַפְשֽׁוֹתֵי⁠כֶם֒ כִּֽי־אַתֶּ֞ם שְׁלַחְתֶּ֣ם אֹתִ֗⁠י אֶל־יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ לֵ⁠אמֹ֔ר הִתְפַּלֵּ֣ל בַּעֲדֵ֔⁠נוּ אֶל־יְהוָ֖ה אֱלֹהֵ֑י⁠נוּ וּ⁠כְ⁠כֹל֩ אֲשֶׁ֨ר יֹאמַ֜ר יְהוָ֧ה אֱלֹהֵ֛י⁠נוּ כֵּ֥ן הַגֶּד־לָ֖⁠נוּ וְ⁠עָשִֽׂינוּ׃","ki֣̇y hţʻţy⁠m bĕ̇⁠napĕşֽ̌wòţéy⁠kem֒ kiֽ̇y-ʼaţė֞m şĕ̌laẖĕţė֣m ʼòţi֗⁠y ʼel-yĕhwá֤h ʼèlòֽhéy⁠kem֙ lé⁠ʼmò֔r hiţĕpȧlé֣̇l bȧʻàdé֔⁠nẇ ʼel-yĕhwá֖h ʼèlòhé֑y⁠nẇ ẇ⁠kĕ⁠kòl֩ ʼàşě֨r yòʼma֜r yĕhwá֧h ʼèlòhé֛y⁠nẇ ké֥̇n hagėd-lá֖⁠nẇ wĕ⁠ʻáşîֽynẇ׃"],[42,21,"וָ⁠אַגִּ֥ד לָ⁠כֶ֖ם הַ⁠יּ֑וֹם וְ⁠לֹ֣א שְׁמַעְתֶּ֗ם בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וּ⁠לְ⁠כֹ֖ל אֲשֶׁר־שְׁלָחַ֥⁠נִי אֲלֵי⁠כֶֽם׃","wá⁠ʼagi֥̇d lá⁠ke֖m ha⁠ẏ֑wòm wĕ⁠lò֣ʼ şĕ̌maʻĕţė֗m bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ẇ⁠lĕ⁠kò֖l ʼàşěr-şĕ̌láẖa֥⁠niy ʼàléy⁠keֽm׃"],[42,22,"וְ⁠עַתָּה֙ יָדֹ֣עַ תֵּֽדְע֔וּ כִּ֗י בַּ⁠חֶ֛רֶב בָּ⁠רָעָ֥ב וּ⁠בַ⁠דֶּ֖בֶר תָּמ֑וּתוּ בַּ⁠מָּקוֹם֙ אֲשֶׁ֣ר חֲפַצְתֶּ֔ם לָ⁠ב֖וֹא לָ⁠ג֥וּר שָֽׁם׃ס","wĕ⁠ʻaţá̇h֙ yádò֣ʻa ţéֽ̇dĕʻ֔ẇ ki̇֗y bȧ⁠ẖe֛reb bá̇⁠ráʻá֥b ẇ⁠ba⁠dė֖ber ţá̇m֑ẇţẇ bȧ⁠má̇qwòm֙ ʼàşě֣r ẖàpaẕĕţė֔m lá⁠b֖wòʼ lá⁠g֥ẇr şáֽ̌m׃s"],[43,1,"וַ⁠יְהִי֩ כְּ⁠כַלּ֨וֹת יִרְמְיָ֜הוּ לְ⁠דַבֵּ֣ר אֶל־כָּל־הָ⁠עָ֗ם אֶת־כָּל־דִּבְרֵי֙ יְהוָ֣ה אֱלֹהֵי⁠הֶ֔ם אֲשֶׁ֧ר שְׁלָח֛⁠וֹ יְהוָ֥ה אֱלֹהֵי⁠הֶ֖ם אֲלֵי⁠הֶ֑ם אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃ס","wa⁠yĕhiy֩ kĕ̇⁠kal̇֨wòţ yirĕmĕyá֜hẇ lĕ⁠dabé֣̇r ʼel-ká̇l-há⁠ʻá֗m ʼeţ-ká̇l-di̇bĕréy֙ yĕhwá֣h ʼèlòhéy⁠he֔m ʼàşě֧r şĕ̌láẖ֛⁠wò yĕhwá֥h ʼèlòhéy⁠he֖m ʼàléy⁠he֑m ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃s"],[43,2,"וַ⁠יֹּ֨אמֶר עֲזַרְיָ֤ה בֶן־הוֹשַֽׁעְיָה֙ וְ⁠יוֹחָנָ֣ן בֶּן־קָרֵ֔חַ וְ⁠כָל־הָ⁠אֲנָשִׁ֖ים הַ⁠זֵּדִ֑ים אֹמְרִ֣ים אֶֽל־יִרְמְיָ֗הוּ שֶׁ֚קֶר אַתָּ֣ה מְדַבֵּ֔ר לֹ֣א שְׁלָחֲ⁠ךָ֞ יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ לֵ⁠אמֹ֔ר לֹֽא־תָבֹ֥אוּ מִצְרַ֖יִם לָ⁠ג֥וּר שָֽׁם׃","wa⁠yò̇֨ʼmer ʻàzarĕyá֤h ben-hwòşǎֽʻĕyáh֙ wĕ⁠ywòẖáná֣n bėn-qáré֔ẖa wĕ⁠kál-há⁠ʼànáşǐ֖ym ha⁠zé̇di֑ym ʼòmĕri֣ym ʼeֽl-yirĕmĕyá֗hẇ şě֚qer ʼaţá֣̇h mĕdabé̇֔r lò֣ʼ şĕ̌láẖà⁠ká֞ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ lé⁠ʼmò֔r lòֽʼ-ţábò֥ʼẇ miẕĕra֖yim lá⁠g֥ẇr şáֽ̌m׃"],[43,3,"כִּ֗י בָּרוּךְ֙ בֶּן־נֵ֣רִיָּ֔ה מַסִּ֥ית אֹתְ⁠ךָ֖ בָּ֑⁠נוּ לְמַעַן֩ תֵּ֨ת אֹתָ֤⁠נוּ בְ⁠יַֽד־הַ⁠כַּשְׂדִּים֙ לְ⁠הָמִ֣ית אֹתָ֔⁠נוּ וּ⁠לְ⁠הַגְל֥וֹת אֹתָ֖⁠נוּ בָּבֶֽל׃","ki̇֗y bá̇rẇkĕ֙ bėn-né֣riyá̇֔h masi֥̇yţ ʼòţĕ⁠ká֖ bá֑̇⁠nẇ lĕmaʻan֩ ţé̇֨ţ ʼòţá֤⁠nẇ bĕ⁠yaֽd-ha⁠kȧşĕ̂di̇ym֙ lĕ⁠hámi֣yţ ʼòţá֔⁠nẇ ẇ⁠lĕ⁠hagĕl֥wòţ ʼòţá֖⁠nẇ bá̇beֽl׃"],[43,4,"וְ⁠לֹֽא־שָׁמַע֩ יוֹחָנָ֨ן בֶּן־קָרֵ֜חַ וְ⁠כָל־שָׂרֵ֧י הַ⁠חֲיָלִ֛ים וְ⁠כָל־הָ⁠עָ֖ם בְּ⁠ק֣וֹל יְהוָ֑ה לָ⁠שֶׁ֖בֶת בְּ⁠אֶ֥רֶץ יְהוּדָֽה׃","wĕ⁠lòֽʼ-şá̌maʻ֩ ywòẖáná֨n bėn-qáré֜ẖa wĕ⁠kál-şá̂ré֧y ha⁠ẖàyáli֛ym wĕ⁠kál-há⁠ʻá֖m bĕ̇⁠q֣wòl yĕhwá֑h lá⁠şě֖beţ bĕ̇⁠ʼe֥reẕ yĕhẇdáֽh׃"],[43,5,"וַ⁠יִּקַּ֞ח יוֹחָנָ֤ן בֶּן־קָרֵ֨חַ֙ וְ⁠כָל־שָׂרֵ֣י הַ⁠חֲיָלִ֔ים אֵ֖ת כָּל־שְׁאֵרִ֣ית יְהוּדָ֑ה אֲשֶׁר־שָׁ֗בוּ מִ⁠כָּל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר נִדְּחוּ־שָׁ֔ם לָ⁠ג֖וּר בְּ⁠אֶ֥רֶץ יְהוּדָֽה׃","wa⁠yi̇qȧ֞ẖ ywòẖáná֤n bėn-qáré֨ẖa֙ wĕ⁠kál-şá̂ré֣y ha⁠ẖàyáli֔ym ʼé֖ţ ká̇l-şĕ̌ʼéri֣yţ yĕhẇdá֑h ʼàşěr-şá̌֗bẇ mi⁠ká̇l-ha⁠ġwòyim֙ ʼàşě֣r nidĕ̇ẖẇ-şá̌֔m lá⁠g֖ẇr bĕ̇⁠ʼe֥reẕ yĕhẇdáֽh׃"],[43,6,"אֶֽת־הַ֠⁠גְּבָרִים וְ⁠אֶת־הַ⁠נָּשִׁ֣ים וְ⁠אֶת־הַ⁠טַּף֮ וְ⁠אֶת־בְּנ֣וֹת הַ⁠מֶּלֶךְ֒ וְ⁠אֵ֣ת כָּל־הַ⁠נֶּ֗פֶשׁ אֲשֶׁ֤ר הִנִּ֨יחַ֙ נְבוּזַרְאֲדָ֣ן רַב־טַבָּחִ֔ים אֶת־גְּדַלְיָ֖הוּ בֶּן־אֲחִיקָ֣ם בֶּן־שָׁפָ֑ן וְ⁠אֵת֙ יִרְמְיָ֣הוּ הַ⁠נָּבִ֔יא וְ⁠אֶת־בָּר֖וּךְ בֶּן־נֵרִיָּֽהוּ׃","ʼeֽţ-ha֠⁠gĕ̇báriym wĕ⁠ʼeţ-ha⁠ná̇şǐ֣ym wĕ⁠ʼeţ-ha⁠tȧp֮ wĕ⁠ʼeţ-bĕ̇n֣wòţ ha⁠mėlekĕ֒ wĕ⁠ʼé֣ţ ká̇l-ha⁠nė֗peş̌ ʼàşě֤r hini̇֨yẖa֙ nĕbẇzarĕʼàdá֣n rab-tabá̇ẖi֔ym ʼeţ-gĕ̇dalĕyá֖hẇ bėn-ʼàẖiyqá֣m bėn-şá̌pá֑n wĕ⁠ʼéţ֙ yirĕmĕyá֣hẇ ha⁠ná̇bi֔yʼ wĕ⁠ʼeţ-bá̇r֖ẇkĕ bėn-nériyáֽ̇hẇ׃"],[43,7,"וַ⁠יָּבֹ֨אוּ֙ אֶ֣רֶץ מִצְרַ֔יִם כִּ֛י לֹ֥א שָׁמְע֖וּ בְּ⁠ק֣וֹל יְהוָ֑ה וַ⁠יָּבֹ֖אוּ עַד־תַּחְפַּנְחֵֽס׃ס","wa⁠yá̇bò֨ʼẇ֙ ʼe֣reẕ miẕĕra֔yim ki֛̇y lò֥ʼ şá̌mĕʻ֖ẇ bĕ̇⁠q֣wòl yĕhwá֑h wa⁠yá̇bò֖ʼẇ ʻad-ţȧẖĕpȧnĕẖéֽs׃s"],[43,8,"וַ⁠יְהִ֤י דְבַר־יְהוָה֙ אֶֽל־יִרְמְיָ֔הוּ בְּ⁠תַחְפַּנְחֵ֖ס לֵ⁠אמֹֽר׃","wa⁠yĕhi֤y dĕbar-yĕhwáh֙ ʼeֽl-yirĕmĕyá֔hẇ bĕ̇⁠ţaẖĕpȧnĕẖé֖s lé⁠ʼmòֽr׃"],[43,9,"קַ֣ח בְּ⁠יָדְ⁠ךָ֞ אֲבָנִ֣ים גְּדֹל֗וֹת וּ⁠טְמַנְתָּ֤⁠ם בַּ⁠מֶּ֨לֶט֙ בַּ⁠מַּלְבֵּ֔ן אֲשֶׁ֛ר בְּ⁠פֶ֥תַח בֵּית־פַּרְעֹ֖ה בְּ⁠תַחְפַּנְחֵ֑ס לְ⁠עֵינֵ֖י אֲנָשִׁ֥ים יְהוּדִֽים׃","qa֣ẖ bĕ̇⁠yádĕ⁠ká֞ ʼàbáni֣ym gĕ̇dòl֗wòţ ẇ⁠tĕmanĕţá֤̇⁠m bȧ⁠mė֨let֙ bȧ⁠mȧlĕbé̇֔n ʼàşě֛r bĕ̇⁠pe֥ţaẖ bé̇yţ-pȧrĕʻò֖h bĕ̇⁠ţaẖĕpȧnĕẖé֑s lĕ⁠ʻéyné֖y ʼànáşǐ֥ym yĕhẇdiֽym׃"],[43,10,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֡ם כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הִנְ⁠נִ֤י שֹׁלֵ֨חַ֙ וְ֠⁠לָקַחְתִּי אֶת־נְבוּכַדְרֶאצַּ֤ר מֶֽלֶךְ־בָּבֶל֙ עַבְדִּ֔⁠י וְ⁠שַׂמְתִּ֣י כִסְא֔⁠וֹ מִ⁠מַּ֛עַל לָ⁠אֲבָנִ֥ים הָ⁠אֵ֖לֶּה אֲשֶׁ֣ר טָמָ֑נְתִּי וְ⁠נָטָ֥ה אֶת־שפרור⁠ו עֲלֵי⁠הֶֽם׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֡m kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l hinĕ⁠ni֤y şò̌lé֨ẖa֙ wĕ֠⁠láqaẖĕţi̇y ʼeţ-nĕbẇkadĕreʼẕȧ֤r meֽlekĕ-bá̇bel֙ ʻabĕdi̇֔⁠y wĕ⁠şâmĕţi֣̇y kisĕʼ֔⁠wò mi⁠mȧ֛ʻal lá⁠ʼàbáni֥ym há⁠ʼé֖lėh ʼàşě֣r támá֑nĕţi̇y wĕ⁠nátá֥h ʼeţ-şprwr⁠w ʻàléy⁠heֽm׃"],[43,11,"ו⁠בא⁠ה וְ⁠הִכָּ֖ה אֶת־אֶ֣רֶץ מִצְרָ֑יִם אֲשֶׁ֧ר לַ⁠מָּ֣וֶת לַ⁠מָּ֗וֶת וַ⁠אֲשֶׁ֤ר לַ⁠שְּׁבִי֙ לַ⁠שֶּׁ֔בִי וַ⁠אֲשֶׁ֥ר לַ⁠חֶ֖רֶב לֶ⁠חָֽרֶב׃","w⁠bʼ⁠h wĕ⁠hiká֖̇h ʼeţ-ʼe֣reẕ miẕĕrá֑yim ʼàşě֧r la⁠má֣̇weţ la⁠má̇֗weţ wa⁠ʼàşě֤r la⁠şĕ̇̌biy֙ la⁠şė̌֔biy wa⁠ʼàşě֥r la⁠ẖe֖reb le⁠ẖáֽreb׃"],[43,12,"וְ⁠הִצַּ֣תִּי אֵ֗שׁ בְּ⁠בָתֵּי֙ אֱלֹהֵ֣י מִצְרַ֔יִם וּ⁠שְׂרָפָ֖⁠ם וְ⁠שָׁבָ֑⁠ם וְ⁠עָטָה֩ אֶת־אֶ֨רֶץ מִצְרַ֜יִם כַּ⁠אֲשֶׁר־יַעְטֶ֤ה הָֽ⁠רֹעֶה֙ אֶת־בִּגְד֔⁠וֹ וְ⁠יָצָ֥א מִ⁠שָּׁ֖ם בְּ⁠שָׁלֽוֹם׃","wĕ⁠hiẕȧ֣ţi̇y ʼé֗ş̌ bĕ̇⁠báţé̇y֙ ʼèlòhé֣y miẕĕra֔yim ẇ⁠şĕ̂rápá֖⁠m wĕ⁠şá̌bá֑⁠m wĕ⁠ʻátáh֩ ʼeţ-ʼe֨reẕ miẕĕra֜yim kȧ⁠ʼàşěr-yaʻĕte֤h háֽ⁠ròʻeh֙ ʼeţ-bi̇gĕd֔⁠wò wĕ⁠yáẕá֥ʼ mi⁠şá֖̇̌m bĕ̇⁠şá̌lֽwòm׃"],[43,13,"וְ⁠שִׁבַּ֗ר אֶֽת־מַצְּבוֹת֙ בֵּ֣ית שֶׁ֔מֶשׁ אֲשֶׁ֖ר בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠אֶת־בָּתֵּ֥י אֱלֹהֵֽי־מִצְרַ֖יִם יִשְׂרֹ֥ף בָּ⁠אֵֽשׁ׃ס","wĕ⁠şǐbȧ֗r ʼeֽţ-maẕĕ̇bwòţ֙ bé֣̇yţ şě֔meş̌ ʼàşě֖r bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠ʼeţ-bá̇ţé֥̇y ʼèlòhéֽy-miẕĕra֖yim yişĕ̂rò֥p bá̇⁠ʼéֽş̌׃s"],[44,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר הָיָ֣ה אֶֽל־יִרְמְיָ֔הוּ אֶ֚ל כָּל־הַ⁠יְּהוּדִ֔ים הַ⁠יֹּשְׁבִ֖ים בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם הַ⁠יֹּשְׁבִ֤ים בְּ⁠מִגְדֹּל֙ וּ⁠בְ⁠תַחְפַּנְחֵ֣ס וּ⁠בְ⁠נֹ֔ף וּ⁠בְ⁠אֶ֥רֶץ פַּתְר֖וֹס לֵ⁠אמֹֽר׃ס","ha⁠dá̇bár֙ ʼàşě֣r háyá֣h ʼeֽl-yirĕmĕyá֔hẇ ʼe֚l ká̇l-ha⁠yĕ̇hẇdi֔ym ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim ha⁠yò̇şĕ̌bi֤ym bĕ̇⁠migĕdò̇l֙ ẇ⁠bĕ⁠ţaẖĕpȧnĕẖé֣s ẇ⁠bĕ⁠nò֔p ẇ⁠bĕ⁠ʼe֥reẕ pȧţĕr֖wòs lé⁠ʼmòֽr׃s"],[44,2,"כֹּה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אַתֶּ֣ם רְאִיתֶ֗ם אֵ֤ת כָּל־הָֽ⁠רָעָה֙ אֲשֶׁ֤ר הֵבֵ֨אתִי֙ עַל־יְר֣וּשָׁלִַ֔ם וְ⁠עַ֖ל כָּל־עָרֵ֣י יְהוּדָ֑ה וְ⁠הִנָּ֤⁠ם חָרְבָּה֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וְ⁠אֵ֥ין בָּ⁠הֶ֖ם יוֹשֵֽׁב׃","kò̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼaţė֣m rĕʼiyţe֗m ʼé֤ţ ká̇l-háֽ⁠ráʻáh֙ ʼàşě֤r hébé֨ʼţiy֙ ʻal-yĕr֣ẇşá̌lia֔m wĕ⁠ʻa֖l ká̇l-ʻáré֣y yĕhẇdá֑h wĕ⁠hiná֤̇⁠m ẖárĕbá̇h֙ ha⁠ẏ֣wòm ha⁠zė֔h wĕ⁠ʼé֥yn bá̇⁠he֖m ywòşéֽ̌b׃"],[44,3,"מִ⁠פְּנֵ֣י רָעָתָ֗⁠ם אֲשֶׁ֤ר עָשׂוּ֙ לְ⁠הַכְעִסֵ֔⁠נִי לָ⁠לֶ֣כֶת לְ⁠קַטֵּ֔ר לַ⁠עֲבֹ֖ד לֵ⁠אלֹהִ֣ים אֲחֵרִ֑ים אֲשֶׁר֙ לֹ֣א יְדָע֔וּ⁠ם הֵ֖מָּה אַתֶּ֥ם וַ⁠אֲבֹתֵי⁠כֶֽם׃","mi⁠pĕ̇né֣y ráʻáţá֗⁠m ʼàşě֤r ʻáş̂ẇ֙ lĕ⁠hakĕʻisé֔⁠niy lá⁠le֣keţ lĕ⁠qaté̇֔r la⁠ʻàbò֖d lé⁠ʼlòhi֣ym ʼàẖéri֑ym ʼàşěr֙ lò֣ʼ yĕdáʻ֔ẇ⁠m hé֖má̇h ʼaţė֥m wa⁠ʼàbòţéy⁠keֽm׃"],[44,4,"וָ⁠אֶשְׁלַ֤ח אֲלֵי⁠כֶם֙ אֶת־כָּל־עֲבָדַ֣⁠י הַ⁠נְּבִיאִ֔ים הַשְׁכֵּ֥ים וְ⁠שָׁלֹ֖חַ לֵ⁠אמֹ֑ר אַל־נָ֣א תַעֲשׂ֗וּ אֵ֛ת דְּבַֽר־הַ⁠תֹּעֵבָ֥ה הַ⁠זֹּ֖את אֲשֶׁ֥ר שָׂנֵֽאתִי׃","wá⁠ʼeşĕ̌la֤ẖ ʼàléy⁠kem֙ ʼeţ-ká̇l-ʻàbáda֣⁠y ha⁠nĕ̇biyʼi֔ym haşĕ̌ké֥̇ym wĕ⁠şá̌lò֖ẖa lé⁠ʼmò֑r ʼal-ná֣ʼ ţaʻàş̂֗ẇ ʼé֛ţ dĕ̇baֽr-ha⁠ţò̇ʻébá֥h ha⁠zò֖̇ʼţ ʼàşě֥r şá̂néֽʼţiy׃"],[44,5,"וְ⁠לֹ֤א שָֽׁמְעוּ֙ וְ⁠לֹא־הִטּ֣וּ אֶת־אָזְנָ֔⁠ם לָ⁠שׁ֖וּב מֵ⁠רָֽעָתָ֑⁠ם לְ⁠בִלְתִּ֥י קַטֵּ֖ר לֵ⁠אלֹהִ֥ים אֲחֵרִֽים׃","wĕ⁠lò֤ʼ şáֽ̌mĕʻẇ֙ wĕ⁠lòʼ-hiṫ֣ẇ ʼeţ-ʼázĕná֔⁠m lá⁠ş֖̌ẇb mé⁠ráֽʻáţá֑⁠m lĕ⁠bilĕţi֥̇y qaté֖̇r lé⁠ʼlòhi֥ym ʼàẖériֽym׃"],[44,6,"וַ⁠תִּתַּ֤ךְ חֲמָתִ⁠י֙ וְ⁠אַפִּ֔⁠י וַ⁠תִּבְעַר֙ בְּ⁠עָרֵ֣י יְהוּדָ֔ה וּ⁠בְ⁠חֻצ֖וֹת יְרֽוּשָׁלִָ֑ם וַ⁠תִּהְיֶ֛ינָה לְ⁠חָרְבָּ֥ה לִ⁠שְׁמָמָ֖ה כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wa⁠ţi̇ţȧ֤kĕ ẖàmáţi⁠y֙ wĕ⁠ʼapi̇֔⁠y wa⁠ţi̇bĕʻar֙ bĕ̇⁠ʻáré֣y yĕhẇdá֔h ẇ⁠bĕ⁠ẖuẕ֖wòţ yĕrֽẇşá̌liá֑m wa⁠ţi̇hĕye֛ynáh lĕ⁠ẖárĕbá֥̇h li⁠şĕ̌mámá֖h kȧ⁠ẏ֥wòm ha⁠zėֽh׃s"],[44,7,"וְ⁠עַתָּ֡ה כֹּֽה־אָמַ֣ר יְהוָה֩ אֱלֹהֵ֨י צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל לָ⁠מָה֩ אַתֶּ֨ם עֹשִׂ֜ים רָעָ֤ה גְדוֹלָה֙ אֶל־נַפְשֹׁ֣תֵ⁠כֶ֔ם לְ⁠הַכְרִ֨ית לָ⁠כֶ֧ם אִישׁ־וְ⁠אִשָּׁ֛ה עוֹלֵ֥ל וְ⁠יוֹנֵ֖ק מִ⁠תּ֣וֹךְ יְהוּדָ֑ה לְ⁠בִלְתִּ֛י הוֹתִ֥יר לָ⁠כֶ֖ם שְׁאֵרִֽית׃","wĕ⁠ʻaţá̇֡h kòֽ̇h-ʼáma֣r yĕhwáh֩ ʼèlòhé֨y ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l lá⁠máh֩ ʼaţė֨m ʻòşî֜ym ráʻá֤h gĕdwòláh֙ ʼel-napĕşò֣̌ţé⁠ke֔m lĕ⁠hakĕri֨yţ lá⁠ke֧m ʼiyş̌-wĕ⁠ʼişá֛̇̌h ʻwòlé֥l wĕ⁠ywòné֖q mi⁠ţ֣̇wòkĕ yĕhẇdá֑h lĕ⁠bilĕţi֛̇y hwòţi֥yr lá⁠ke֖m şĕ̌ʼériֽyţ׃"],[44,8,"לְ⁠הַכְעִסֵ֨⁠נִי֙ בְּ⁠מַעֲשֵׂ֣י יְדֵי⁠כֶ֔ם לְ⁠קַטֵּ֞ר לֵ⁠אלֹהִ֤ים אֲחֵרִים֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם אֲשֶׁר־אַתֶּ֥ם בָּאִ֖ים לָ⁠ג֣וּר שָׁ֑ם לְמַ֨עַן֙ הַכְרִ֣ית לָ⁠כֶ֔ם וּ⁠לְמַ֤עַן הֱיֽוֹתְ⁠כֶם֙ לִ⁠קְלָלָ֣ה וּ⁠לְ⁠חֶרְפָּ֔ה בְּ⁠כֹ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","lĕ⁠hakĕʻisé֨⁠niy֙ bĕ̇⁠maʻàşé֣̂y yĕdéy⁠ke֔m lĕ⁠qaté̇֞r lé⁠ʼlòhi֤ym ʼàẖériym֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim ʼàşěr-ʼaţė֥m bá̇ʼi֖ym lá⁠g֣ẇr şá֑̌m lĕma֨ʻan֙ hakĕri֣yţ lá⁠ke֔m ẇ⁠lĕma֤ʻan hèyֽwòţĕ⁠kem֙ li⁠qĕlálá֣h ẇ⁠lĕ⁠ẖerĕpá̇֔h bĕ̇⁠kò֖l ġwòyé֥y há⁠ʼáֽreẕ׃"],[44,9,"הַֽ⁠שְׁכַחְתֶּם֩ אֶת־רָע֨וֹת אֲבוֹתֵי⁠כֶ֜ם וְ⁠אֶת־רָע֣וֹת ׀ מַלְכֵ֣י יְהוּדָ֗ה וְ⁠אֵת֙ רָע֣וֹת נָשָׁ֔י⁠ו וְ⁠אֵת֙ רָעֹ֣תֵ⁠כֶ֔ם וְ⁠אֵ֖ת רָעֹ֣ת נְשֵׁי⁠כֶ֑ם אֲשֶׁ֤ר עָשׂוּ֙ בְּ⁠אֶ֣רֶץ יְהוּדָ֔ה וּ⁠בְ⁠חֻצ֖וֹת יְרוּשָׁלִָֽם׃","haֽ⁠şĕ̌kaẖĕţėm֩ ʼeţ-ráʻ֨wòţ ʼàbwòţéy⁠ke֜m wĕ⁠ʼeţ-ráʻ֣wòţ ׀ malĕké֣y yĕhẇdá֗h wĕ⁠ʼéţ֙ ráʻ֣wòţ náşá̌֔y⁠w wĕ⁠ʼéţ֙ ráʻò֣ţé⁠ke֔m wĕ⁠ʼé֖ţ ráʻò֣ţ nĕşé̌y⁠ke֑m ʼàşě֤r ʻáş̂ẇ֙ bĕ̇⁠ʼe֣reẕ yĕhẇdá֔h ẇ⁠bĕ⁠ẖuẕ֖wòţ yĕrẇşá̌liáֽm׃"],[44,10,"לֹ֣א דֻכְּא֔וּ עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וְ⁠לֹ֣א יָרְא֗וּ וְ⁠לֹֽא־הָלְכ֤וּ בְ⁠תֽוֹרָתִ⁠י֙ וּ⁠בְ⁠חֻקֹּתַ֔⁠י אֲשֶׁר־נָתַ֥תִּי לִ⁠פְנֵי⁠כֶ֖ם וְ⁠לִ⁠פְנֵ֥י אֲבוֹתֵי⁠כֶֽם׃ס","lò֣ʼ dukĕ̇ʼ֔ẇ ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h wĕ⁠lò֣ʼ yárĕʼ֗ẇ wĕ⁠lòֽʼ-hálĕk֤ẇ bĕ⁠ţֽwòráţi⁠y֙ ẇ⁠bĕ⁠ẖuqò̇ţa֔⁠y ʼàşěr-náţa֥ţi̇y li⁠pĕnéy⁠ke֖m wĕ⁠li⁠pĕné֥y ʼàbwòţéy⁠keֽm׃s"],[44,11,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֨י שָׂ֥ם פָּנַ֛⁠י בָּ⁠כֶ֖ם לְ⁠רָעָ֑ה וּ⁠לְ⁠הַכְרִ֖ית אֶת־כָּל־יְהוּדָֽה׃","lá⁠ké֗n kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֨y şá֥̂m pá̇na֛⁠y bá̇⁠ke֖m lĕ⁠ráʻá֑h ẇ⁠lĕ⁠hakĕri֖yţ ʼeţ-ká̇l-yĕhẇdáֽh׃"],[44,12,"וְ⁠לָקַחְתִּ֞י אֶת־שְׁאֵרִ֣ית יְהוּדָ֗ה אֲשֶׁר־שָׂ֨מוּ פְנֵי⁠הֶ֜ם לָ⁠ב֣וֹא אֶֽרֶץ־מִצְרַיִם֮ לָ⁠ג֣וּר שָׁם֒ וְ⁠תַ֨מּוּ כֹ֜ל בְּ⁠אֶ֧רֶץ מִצְרַ֣יִם יִפֹּ֗לוּ בַּ⁠חֶ֤רֶב בָּֽ⁠רָעָב֙ יִתַּ֔מּוּ מִ⁠קָּטֹן֙ וְ⁠עַד־גָּד֔וֹל בַּ⁠חֶ֥רֶב וּ⁠בָ⁠רָעָ֖ב יָמֻ֑תוּ וְ⁠הָיוּ֙ לְ⁠אָלָ֣ה לְ⁠שַׁמָּ֔ה וְ⁠לִ⁠קְלָלָ֖ה וּ⁠לְ⁠חֶרְפָּֽה׃","wĕ⁠láqaẖĕţi̇֞y ʼeţ-şĕ̌ʼéri֣yţ yĕhẇdá֗h ʼàşěr-şá̂֨mẇ pĕnéy⁠he֜m lá⁠b֣wòʼ ʼeֽreẕ-miẕĕrayim֮ lá⁠g֣ẇr şá̌m֒ wĕ⁠ţa֨ṁẇ kò֜l bĕ̇⁠ʼe֧reẕ miẕĕra֣yim yipò̇֗lẇ bȧ⁠ẖe֤reb báֽ̇⁠ráʻáb֙ yiţȧ֔ṁẇ mi⁠qá̇tòn֙ wĕ⁠ʻad-gá̇d֔wòl bȧ⁠ẖe֥reb ẇ⁠bá⁠ráʻá֖b yámu֑ţẇ wĕ⁠háyẇ֙ lĕ⁠ʼálá֣h lĕ⁠şǎmá̇֔h wĕ⁠li⁠qĕlálá֖h ẇ⁠lĕ⁠ẖerĕpáֽ̇h׃"],[44,13,"וּ⁠פָקַדְתִּ֗י עַ֤ל הַ⁠יּֽוֹשְׁבִים֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם כַּ⁠אֲשֶׁ֥ר פָּקַ֖דְתִּי עַל־יְרֽוּשָׁלִָ֑ם בַּ⁠חֶ֥רֶב בָּ⁠רָעָ֖ב וּ⁠בַ⁠דָּֽבֶר׃","ẇ⁠páqadĕţi̇֗y ʻa֤l ha⁠ẏֽwòşĕ̌biym֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim kȧ⁠ʼàşě֥r pá̇qa֖dĕţi̇y ʻal-yĕrֽẇşá̌liá֑m bȧ⁠ẖe֥reb bá̇⁠ráʻá֖b ẇ⁠ba⁠dáֽ̇ber׃"],[44,14,"וְ⁠לֹ֨א יִהְיֶ֜ה פָּלִ֤יט וְ⁠שָׂרִיד֙ לִ⁠שְׁאֵרִ֣ית יְהוּדָ֔ה הַ⁠בָּאִ֥ים לָ⁠גֽוּר־שָׁ֖ם בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠לָ⁠שׁ֣וּב ׀ אֶ֣רֶץ יְהוּדָ֗ה אֲשֶׁר־הֵ֜מָּה מְנַשְּׂאִ֤ים אֶת־נַפְשָׁ⁠ם֙ לָ⁠שׁוּב֙ לָ⁠שֶׁ֣בֶת שָׁ֔ם כִּ֥י לֹֽא־יָשׁ֖וּבוּ כִּ֥י אִם־פְּלֵטִֽים׃ס","wĕ⁠lò֨ʼ yihĕye֜h pá̇li֤yt wĕ⁠şá̂riyd֙ li⁠şĕ̌ʼéri֣yţ yĕhẇdá֔h ha⁠bá̇ʼi֥ym lá⁠gֽẇr-şá֖̌m bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠lá⁠ş֣̌ẇb ׀ ʼe֣reẕ yĕhẇdá֗h ʼàşěr-hé֜má̇h mĕnaşĕ̇̂ʼi֤ym ʼeţ-napĕşá̌⁠m֙ lá⁠ş̌ẇb֙ lá⁠şě֣beţ şá̌֔m ki֥̇y lòֽʼ-yáş֖̌ẇbẇ ki֥̇y ʼim-pĕ̇létiֽym׃s"],[44,15,"וַ⁠יַּעֲנ֣וּ אֶֽת־יִרְמְיָ֗הוּ כָּל־הָ⁠אֲנָשִׁ֤ים הַ⁠יֹּֽדְעִים֙ כִּֽי־מְקַטְּר֤וֹת נְשֵׁי⁠הֶם֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים וְ⁠כָל־הַ⁠נָּשִׁ֥ים הָ⁠עֹמְד֖וֹת קָהָ֣ל גָּד֑וֹל וְ⁠כָל־הָ⁠עָ֛ם הַ⁠יֹּשְׁבִ֥ים בְּ⁠אֶֽרֶץ־מִצְרַ֖יִם בְּ⁠פַתְר֥וֹס לֵ⁠אמֹֽר׃","wa⁠yȧʻàn֣ẇ ʼeֽţ-yirĕmĕyá֗hẇ ká̇l-há⁠ʼànáşǐ֤ym ha⁠yòֽ̇dĕʻiym֙ kiֽ̇y-mĕqatĕ̇r֤wòţ nĕşé̌y⁠hem֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym wĕ⁠kál-ha⁠ná̇şǐ֥ym há⁠ʻòmĕd֖wòţ qáhá֣l gá̇d֑wòl wĕ⁠kál-há⁠ʻá֛m ha⁠yò̇şĕ̌bi֥ym bĕ̇⁠ʼeֽreẕ-miẕĕra֖yim bĕ̇⁠paţĕr֥wòs lé⁠ʼmòֽr׃"],[44,16,"הַ⁠דָּבָ֛ר אֲשֶׁר־דִּבַּ֥רְתָּ אֵלֵ֖י⁠נוּ בְּ⁠שֵׁ֣ם יְהוָ֑ה אֵינֶ֥⁠נּוּ שֹׁמְעִ֖ים אֵלֶֽי⁠ךָ׃","ha⁠dá̇bá֛r ʼàşěr-di̇bȧ֥rĕţá̇ ʼélé֖y⁠nẇ bĕ̇⁠şé֣̌m yĕhwá֑h ʼéyne֥⁠ṅẇ şò̌mĕʻi֖ym ʼéleֽy⁠ká׃"],[44,17,"כִּ֩י עָשֹׂ֨ה נַעֲשֶׂ֜ה אֶֽת־כָּל־הַ⁠דָּבָ֣ר ׀ אֲשֶׁר־יָצָ֣א מִ⁠פִּ֗י⁠נוּ לְ⁠קַטֵּ֞ר לִ⁠מְלֶ֣כֶת הַ⁠שָּׁמַיִם֮ וְ⁠הַסֵּֽיךְ־לָ֣⁠הּ נְסָכִים֒ כַּ⁠אֲשֶׁ֨ר עָשִׂ֜ינוּ אֲנַ֤חְנוּ וַ⁠אֲבֹתֵ֨י⁠נוּ֙ מְלָכֵ֣י⁠נוּ וְ⁠שָׂרֵ֔י⁠נוּ בְּ⁠עָרֵ֣י יְהוּדָ֔ה וּ⁠בְ⁠חֻצ֖וֹת יְרוּשָׁלִָ֑ם וַ⁠נִּֽשְׂבַּֽע־לֶ֨חֶם֙ וַ⁠נִּֽהְיֶ֣ה טוֹבִ֔ים וְ⁠רָעָ֖ה לֹ֥א רָאִֽינוּ׃","ki̇֩y ʻáşò̂֨h naʻàşê֜h ʼeֽţ-ká̇l-ha⁠dá̇bá֣r ׀ ʼàşěr-yáẕá֣ʼ mi⁠pi̇֗y⁠nẇ lĕ⁠qaté̇֞r li⁠mĕle֣keţ ha⁠şá̇̌mayim֮ wĕ⁠haséֽ̇ykĕ-lá֣⁠ḣ nĕsákiym֒ kȧ⁠ʼàşě֨r ʻáşî֜ynẇ ʼàna֤ẖĕnẇ wa⁠ʼàbòţé֨y⁠nẇ֙ mĕláké֣y⁠nẇ wĕ⁠şá̂ré֔y⁠nẇ bĕ̇⁠ʻáré֣y yĕhẇdá֔h ẇ⁠bĕ⁠ẖuẕ֖wòţ yĕrẇşá̌liá֑m wa⁠niֽ̇şĕ̂bȧֽʻ-le֨ẖem֙ wa⁠niֽ̇hĕye֣h twòbi֔ym wĕ⁠ráʻá֖h lò֥ʼ ráʼiֽynẇ׃"],[44,18,"וּ⁠מִן־אָ֡ז חָדַ֜לְנוּ לְ⁠קַטֵּ֨ר לִ⁠מְלֶ֧כֶת הַ⁠שָּׁמַ֛יִם וְ⁠הַסֵּֽךְ־לָ֥⁠הּ נְסָכִ֖ים חָסַ֣רְנוּ כֹ֑ל וּ⁠בַ⁠חֶ֥רֶב וּ⁠בָ⁠רָעָ֖ב תָּֽמְנוּ׃","ẇ⁠min-ʼá֡z ẖáda֜lĕnẇ lĕ⁠qaté̇֨r li⁠mĕle֧keţ ha⁠şá̇̌ma֛yim wĕ⁠haséֽ̇kĕ-lá֥⁠ḣ nĕsáki֖ym ẖása֣rĕnẇ kò֑l ẇ⁠ba⁠ẖe֥reb ẇ⁠bá⁠ráʻá֖b ţáֽ̇mĕnẇ׃"],[44,19,"וְ⁠כִֽי־אֲנַ֤חְנוּ מְקַטְּרִים֙ לִ⁠מְלֶ֣כֶת הַ⁠שָּׁמַ֔יִם וּ⁠לְ⁠הַסֵּ֥ךְ לָ֖⁠הּ נְסָכִ֑ים הֲ⁠מִֽ⁠בַּלְעֲדֵ֣י אֲנָשֵׁ֗י⁠נוּ עָשִׂ֨ינוּ לָ֤⁠הּ כַּוָּנִים֙ לְ⁠הַ֣עֲצִבָ֔⁠ה וְ⁠הַסֵּ֥ךְ לָ֖⁠הּ נְסָכִֽים׃פ","wĕ⁠kiֽy-ʼàna֤ẖĕnẇ mĕqatĕ̇riym֙ li⁠mĕle֣keţ ha⁠şá̇̌ma֔yim ẇ⁠lĕ⁠hasé֥̇kĕ lá֖⁠ḣ nĕsáki֑ym hà⁠miֽ⁠bȧlĕʻàdé֣y ʼànáşé̌֗y⁠nẇ ʻáşî֨ynẇ lá֤⁠ḣ kȧwá̇niym֙ lĕ⁠ha֣ʻàẕibá֔⁠h wĕ⁠hasé֥̇kĕ lá֖⁠ḣ nĕsákiֽym׃p"],[44,20,"וַ⁠יֹּ֥אמֶר יִרְמְיָ֖הוּ אֶל־כָּל־הָ⁠עָ֑ם עַל־הַ⁠גְּבָרִ֤ים וְ⁠עַל־הַ⁠נָּשִׁים֙ וְ⁠עַל־כָּל־הָ⁠עָ֔ם הָ⁠עֹנִ֥ים אֹת֛⁠וֹ דָּבָ֖ר לֵ⁠אמֹֽר׃","wa⁠yò֥̇ʼmer yirĕmĕyá֖hẇ ʼel-ká̇l-há⁠ʻá֑m ʻal-ha⁠gĕ̇bári֤ym wĕ⁠ʻal-ha⁠ná̇şǐym֙ wĕ⁠ʻal-ká̇l-há⁠ʻá֔m há⁠ʻòni֥ym ʼòţ֛⁠wò dá̇bá֖r lé⁠ʼmòֽr׃"],[44,21,"הֲ⁠ל֣וֹא אֶת־הַ⁠קִּטֵּ֗ר אֲשֶׁ֨ר קִטַּרְתֶּ֜ם בְּ⁠עָרֵ֤י יְהוּדָה֙ וּ⁠בְ⁠חֻצ֣וֹת יְרוּשָׁלִַ֔ם אַתֶּ֧ם וַ⁠אֲבֽוֹתֵי⁠כֶ֛ם מַלְכֵי⁠כֶ֥ם וְ⁠שָׂרֵי⁠כֶ֖ם וְ⁠עַ֣ם הָ⁠אָ֑רֶץ אֹתָ⁠ם֙ זָכַ֣ר יְהוָ֔ה וַֽ⁠תַּעֲלֶ֖ה עַל־לִבּֽ⁠וֹ׃","hà⁠l֣wòʼ ʼeţ-ha⁠qi̇té̇֗r ʼàşě֨r qitȧrĕţė֜m bĕ̇⁠ʻáré֤y yĕhẇdáh֙ ẇ⁠bĕ⁠ẖuẕ֣wòţ yĕrẇşá̌lia֔m ʼaţė֧m wa⁠ʼàbֽwòţéy⁠ke֛m malĕkéy⁠ke֥m wĕ⁠şá̂réy⁠ke֖m wĕ⁠ʻa֣m há⁠ʼá֑reẕ ʼòţá⁠m֙ záka֣r yĕhwá֔h waֽ⁠ţȧʻàle֖h ʻal-liḃֽ⁠wò׃"],[44,22,"וְ⁠לֹֽא־יוּכַל֩ יְהוָ֨ה ע֜וֹד לָ⁠שֵׂ֗את מִ⁠פְּנֵי֙ רֹ֣עַ מַעַלְלֵי⁠כֶ֔ם מִ⁠פְּנֵ֥י הַ⁠תּוֹעֵבֹ֖ת אֲשֶׁ֣ר עֲשִׂיתֶ֑ם וַ⁠תְּהִ֣י אַ֠רְצְ⁠כֶם לְ⁠חָרְבָּ֨ה וּ⁠לְ⁠שַׁמָּ֧ה וְ⁠לִ⁠קְלָלָ֛ה מֵ⁠אֵ֥ין יוֹשֵׁ֖ב כְּ⁠הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠lòֽʼ-yẇkal֩ yĕhwá֨h ʻ֜wòd lá⁠şé̂֗ʼţ mi⁠pĕ̇néy֙ rò֣ʻa maʻalĕléy⁠ke֔m mi⁠pĕ̇né֥y ha⁠ţ̇wòʻébò֖ţ ʼàşě֣r ʻàşîyţe֑m wa⁠ţĕ̇hi֣y ʼa֠rĕẕĕ⁠kem lĕ⁠ẖárĕbá̇֨h ẇ⁠lĕ⁠şǎmá֧̇h wĕ⁠li⁠qĕlálá֛h mé⁠ʼé֥yn ywòşé֖̌b kĕ̇⁠ha⁠ẏ֥wòm ha⁠zėֽh׃"],[44,23,"מִ⁠פְּנֵי֩ אֲשֶׁ֨ר קִטַּרְתֶּ֜ם וַ⁠אֲשֶׁ֧ר חֲטָאתֶ֣ם לַ⁠יהוָ֗ה וְ⁠לֹ֤א שְׁמַעְתֶּם֙ בְּ⁠ק֣וֹל יְהוָ֔ה וּ⁠בְ⁠תֹרָת֧⁠וֹ וּ⁠בְ⁠חֻקֹּתָ֛י⁠ו וּ⁠בְ⁠עֵדְוֺתָ֖י⁠ו לֹ֣א הֲלַכְתֶּ֑ם עַל־כֵּ֞ן קָרָ֥את אֶתְ⁠כֶ֛ם הָ⁠רָעָ֥ה הַ⁠זֹּ֖את כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","mi⁠pĕ̇néy֩ ʼàşě֨r qitȧrĕţė֜m wa⁠ʼàşě֧r ẖàtáʼţe֣m la⁠yhwá֗h wĕ⁠lò֤ʼ şĕ̌maʻĕţėm֙ bĕ̇⁠q֣wòl yĕhwá֔h ẇ⁠bĕ⁠ţòráţ֧⁠wò ẇ⁠bĕ⁠ẖuqò̇ţá֛y⁠w ẇ⁠bĕ⁠ʻédĕwֺţá֖y⁠w lò֣ʼ hàlakĕţė֑m ʻal-ké̇֞n qárá֥ʼţ ʼeţĕ⁠ke֛m há⁠ráʻá֥h ha⁠zò֖̇ʼţ kȧ⁠ẏ֥wòm ha⁠zėֽh׃s"],[44,24,"וַ⁠יֹּ֤אמֶר יִרְמְיָ֨הוּ֙ אֶל־כָּל־הָ⁠עָ֔ם וְ⁠אֶ֖ל כָּל־הַ⁠נָּשִׁ֑ים שִׁמְעוּ֙ דְּבַר־יְהוָ֔ה כָּל־יְהוּדָ֕ה אֲשֶׁ֖ר בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃ס","wa⁠yò֤̇ʼmer yirĕmĕyá֨hẇ֙ ʼel-ká̇l-há⁠ʻá֔m wĕ⁠ʼe֖l ká̇l-ha⁠ná̇şǐ֑ym şǐmĕʻẇ֙ dĕ̇bar-yĕhwá֔h ká̇l-yĕhẇdá֕h ʼàşě֖r bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃s"],[44,25,"כֹּֽה־אָמַ֣ר יְהוָֽה־צְבָאוֹת֩ אֱלֹהֵ֨י יִשְׂרָאֵ֜ל לֵ⁠אמֹ֗ר אַתֶּ֨ם וּ⁠נְשֵׁי⁠כֶ֜ם וַ⁠תְּדַבֵּ֣רְנָה בְּ⁠פִי⁠כֶם֮ וּ⁠בִ⁠ידֵי⁠כֶ֣ם מִלֵּאתֶ֣ם ׀ לֵ⁠אמֹר֒ עָשֹׂ֨ה נַעֲשֶׂ֜ה אֶת־נְדָרֵ֗י⁠נוּ אֲשֶׁ֤ר נָדַ֨רְנוּ֙ לְ⁠קַטֵּר֙ לִ⁠מְלֶ֣כֶת הַ⁠שָּׁמַ֔יִם וּ⁠לְ⁠הַסֵּ֥ךְ לָ֖⁠הּ נְסָכִ֑ים הָקֵ֤ים תָּקִ֨ימְנָה֙ אֶת־נִדְרֵי⁠כֶ֔ם וְ⁠עָשֹׂ֥ה תַעֲשֶׂ֖ינָה אֶת־נִדְרֵי⁠כֶֽם׃פ","kòֽ̇h-ʼáma֣r yĕhwáֽh-ẕĕbáʼwòţ֩ ʼèlòhé֨y yişĕ̂ráʼé֜l lé⁠ʼmò֗r ʼaţė֨m ẇ⁠nĕşé̌y⁠ke֜m wa⁠ţĕ̇dabé֣̇rĕnáh bĕ̇⁠piy⁠kem֮ ẇ⁠bi⁠ydéy⁠ke֣m milé̇ʼţe֣m ׀ lé⁠ʼmòr֒ ʻáşò̂֨h naʻàşê֜h ʼeţ-nĕdáré֗y⁠nẇ ʼàşě֤r náda֨rĕnẇ֙ lĕ⁠qaté̇r֙ li⁠mĕle֣keţ ha⁠şá̇̌ma֔yim ẇ⁠lĕ⁠hasé֥̇kĕ lá֖⁠ḣ nĕsáki֑ym háqé֤ym ţá̇qi֨ymĕnáh֙ ʼeţ-nidĕréy⁠ke֔m wĕ⁠ʻáşò֥̂h ţaʻàşê֖ynáh ʼeţ-nidĕréy⁠keֽm׃p"],[44,26,"לָ⁠כֵן֙ שִׁמְע֣וּ דְבַר־יְהוָ֔ה כָּל־יְהוּדָ֕ה הַ⁠יֹּשְׁבִ֖ים בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם הִנְ⁠נִ֨י נִשְׁבַּ֜עְתִּי בִּ⁠שְׁמִ֤⁠י הַ⁠גָּדוֹל֙ אָמַ֣ר יְהוָ֔ה אִם־יִהְיֶה֩ ע֨וֹד שְׁמִ֜⁠י נִקְרָ֣א ׀ בְּ⁠פִ֣י ׀ כָּל־אִ֣ישׁ יְהוּדָ֗ה אֹמֵ֛ר חַי־אֲדֹנָ֥⁠י יְהוִ֖ה בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","lá⁠kén֙ şǐmĕʻ֣ẇ dĕbar-yĕhwá֔h ká̇l-yĕhẇdá֕h ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim hinĕ⁠ni֨y nişĕ̌bȧ֜ʻĕţi̇y bi̇⁠şĕ̌mi֤⁠y ha⁠gá̇dwòl֙ ʼáma֣r yĕhwá֔h ʼim-yihĕyeh֩ ʻ֨wòd şĕ̌mi֜⁠y niqĕrá֣ʼ ׀ bĕ̇⁠pi֣y ׀ ká̇l-ʼi֣yş̌ yĕhẇdá֗h ʼòmé֛r ẖay-ʼàdòná֥⁠y yĕhwi֖h bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[44,27,"הִנְ⁠נִ֨י שֹׁקֵ֧ד עֲלֵי⁠הֶ֛ם לְ⁠רָעָ֖ה וְ⁠לֹ֣א לְ⁠טוֹבָ֑ה וְ⁠תַמּוּ֩ כָל־אִ֨ישׁ יְהוּדָ֜ה אֲשֶׁ֧ר בְּ⁠אֶֽרֶץ־מִצְרַ֛יִם בַּ⁠חֶ֥רֶב וּ⁠בָ⁠רָעָ֖ב עַד־כְּלוֹתָֽ⁠ם׃","hinĕ⁠ni֨y şò̌qé֧d ʻàléy⁠he֛m lĕ⁠ráʻá֖h wĕ⁠lò֣ʼ lĕ⁠twòbá֑h wĕ⁠ţaṁẇ֩ kál-ʼi֨yş̌ yĕhẇdá֜h ʼàşě֧r bĕ̇⁠ʼeֽreẕ-miẕĕra֛yim bȧ⁠ẖe֥reb ẇ⁠bá⁠ráʻá֖b ʻad-kĕ̇lwòţáֽ⁠m׃"],[44,28,"וּ⁠פְלִיטֵ֨י חֶ֜רֶב יְשֻׁב֨וּ⁠ן מִן־אֶ֧רֶץ מִצְרַ֛יִם אֶ֥רֶץ יְהוּדָ֖ה מְתֵ֣י מִסְפָּ֑ר וְֽ⁠יָדְע֞וּ כָּל־שְׁאֵרִ֣ית יְהוּדָ֗ה הַ⁠בָּאִ֤ים לְ⁠אֶֽרֶץ־מִצְרַ֨יִם֙ לָ⁠ג֣וּר שָׁ֔ם דְּבַר־מִ֥י יָק֖וּם מִמֶּ֥⁠נִּי וּ⁠מֵ⁠הֶֽם׃","ẇ⁠pĕliyté֨y ẖe֜reb yĕşǔb֨ẇ⁠n min-ʼe֧reẕ miẕĕra֛yim ʼe֥reẕ yĕhẇdá֖h mĕţé֣y misĕpá֑̇r wĕֽ⁠yádĕʻ֞ẇ ká̇l-şĕ̌ʼéri֣yţ yĕhẇdá֗h ha⁠bá̇ʼi֤ym lĕ⁠ʼeֽreẕ-miẕĕra֨yim֙ lá⁠g֣ẇr şá̌֔m dĕ̇bar-mi֥y yáq֖ẇm mimė֥⁠ni̇y ẇ⁠mé⁠heֽm׃"],[44,29,"וְ⁠זֹאת־לָ⁠כֶ֤ם הָ⁠אוֹת֙ נְאֻם־יְהוָ֔ה כִּֽי־פֹקֵ֥ד אֲנִ֛י עֲלֵי⁠כֶ֖ם בַּ⁠מָּק֣וֹם הַ⁠זֶּ֑ה לְמַ֨עַן֙ תֵּֽדְע֔וּ כִּי֩ ק֨וֹם יָק֧וּמוּ דְבָרַ֛⁠י עֲלֵי⁠כֶ֖ם לְ⁠רָעָֽה׃ס","wĕ⁠zòʼţ-lá⁠ke֤m há⁠ʼwòţ֙ nĕʼum-yĕhwá֔h kiֽ̇y-pòqé֥d ʼàni֛y ʻàléy⁠ke֖m bȧ⁠má̇q֣wòm ha⁠zė֑h lĕma֨ʻan֙ ţéֽ̇dĕʻ֔ẇ ki̇y֩ q֨wòm yáq֧ẇmẇ dĕbára֛⁠y ʻàléy⁠ke֖m lĕ⁠ráʻáֽh׃s"],[44,30,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה הִנְ⁠נִ֣י נֹ֠תֵן אֶת־פַּרְעֹ֨ה חָפְרַ֤ע מֶֽלֶךְ־מִצְרַ֨יִם֙ בְּ⁠יַ֣ד אֹֽיְבָ֔י⁠ו וּ⁠בְ⁠יַ֖ד מְבַקְשֵׁ֣י נַפְשׁ֑⁠וֹ כַּ⁠אֲשֶׁ֨ר נָתַ֜תִּי אֶת־צִדְקִיָּ֣הוּ מֶֽלֶךְ־יְהוּדָ֗ה בְּ⁠יַ֨ד נְבוּכַדְרֶאצַּ֧ר מֶֽלֶךְ־בָּבֶ֛ל אֹיְב֖⁠וֹ וּ⁠מְבַקֵּ֥שׁ נַפְשֽׁ⁠וֹ׃ס","kò֣̇h ׀ ʼáma֣r yĕhwá֗h hinĕ⁠ni֣y nò֠ţén ʼeţ-pȧrĕʻò֨h ẖápĕra֤ʻ meֽlekĕ-miẕĕra֨yim֙ bĕ̇⁠ya֣d ʼòֽyĕbá֔y⁠w ẇ⁠bĕ⁠ya֖d mĕbaqĕşé֣̌y napĕş֑̌⁠wò kȧ⁠ʼàşě֨r náţa֜ţi̇y ʼeţ-ẕidĕqiyá֣̇hẇ meֽlekĕ-yĕhẇdá֗h bĕ̇⁠ya֨d nĕbẇkadĕreʼẕȧ֧r meֽlekĕ-bá̇be֛l ʼòyĕb֖⁠wò ẇ⁠mĕbaqé֥̇ş̌ napĕşֽ̌⁠wò׃s"],[45,1,"הַ⁠דָּבָ֗ר אֲשֶׁ֤ר דִּבֶּר֙ יִרְמְיָ֣הוּ הַ⁠נָּבִ֔יא אֶל־בָּר֖וּךְ בֶּֽן־נֵֽרִיָּ֑ה בְּ⁠כָתְב⁠וֹ֩ אֶת־הַ⁠דְּבָרִ֨ים הָ⁠אֵ֤לֶּה עַל־סֵ֨פֶר֙ מִ⁠פִּ֣י יִרְמְיָ֔הוּ בַּ⁠שָּׁנָה֙ הָֽ⁠רְבִעִ֔ית לִ⁠יהוֹיָקִ֧ים בֶּן־יֹאשִׁיָּ֛הוּ מֶ֥לֶךְ יְהוּדָ֖ה לֵ⁠אמֹֽר׃ס","ha⁠dá̇bá֗r ʼàşě֤r di̇bėr֙ yirĕmĕyá֣hẇ ha⁠ná̇bi֔yʼ ʼel-bá̇r֖ẇkĕ bėֽn-néֽriyá֑̇h bĕ̇⁠káţĕb⁠wò֩ ʼeţ-ha⁠dĕ̇bári֨ym há⁠ʼé֤lėh ʻal-sé֨per֙ mi⁠pi֣̇y yirĕmĕyá֔hẇ bȧ⁠şá̇̌náh֙ háֽ⁠rĕbiʻi֔yţ li⁠yhwòyáqi֧ym bėn-yòʼşǐyá֛̇hẇ me֥lekĕ yĕhẇdá֖h lé⁠ʼmòֽr׃s"],[45,2,"כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל עָלֶ֖י⁠ךָ בָּרֽוּךְ׃","kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʻále֖y⁠ká bá̇rֽẇkĕ׃"],[45,3,"אָמַ֨רְתָּ֙ אֽוֹי־נָ֣א לִ֔⁠י כִּֽי־יָסַ֧ף יְהוָ֛ה יָג֖וֹן עַל־מַכְאֹבִ֑⁠י יָגַ֨עְתִּי֙ בְּ⁠אַנְחָתִ֔⁠י וּ⁠מְנוּחָ֖ה לֹ֥א מָצָֽאתִי׃ס","ʼáma֨rĕţá̇֙ ʼֽwòy-ná֣ʼ li֔⁠y kiֽ̇y-yása֧p yĕhwá֛h yág֖wòn ʻal-makĕʼòbi֑⁠y yága֨ʻĕţi̇y֙ bĕ̇⁠ʼanĕẖáţi֔⁠y ẇ⁠mĕnẇẖá֖h lò֥ʼ máẕáֽʼţiy׃s"],[45,4,"כֹּ֣ה ׀ תֹּאמַ֣ר אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנֵּ֤ה אֲשֶׁר־בָּנִ֨יתִי֙ אֲנִ֣י הֹרֵ֔ס וְ⁠אֵ֥ת אֲשֶׁר־נָטַ֖עְתִּי אֲנִ֣י נֹתֵ֑שׁ וְ⁠אֶת־כָּל־הָ⁠אָ֖רֶץ הִֽיא׃","kò֣̇h ׀ ţò̇ʼma֣r ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h hiné֤̇h ʼàşěr-bá̇ni֨yţiy֙ ʼàni֣y hòré֔s wĕ⁠ʼé֥ţ ʼàşěr-náta֖ʻĕţi̇y ʼàni֣y nòţé֑ş̌ wĕ⁠ʼeţ-ká̇l-há⁠ʼá֖reẕ hiֽyʼ׃"],[45,5,"וְ⁠אַתָּ֛ה תְּבַקֶּשׁ־לְ⁠ךָ֥ גְדֹל֖וֹת אַל־תְּבַקֵּ֑שׁ כִּ֡י הִנְ⁠נִי֩ מֵבִ֨יא רָעָ֤ה עַל־כָּל־בָּשָׂר֙ נְאֻם־יְהוָ֔ה וְ⁠נָתַתִּ֨י לְ⁠ךָ֤ אֶֽת־נַפְשְׁ⁠ךָ֙ לְ⁠שָׁלָ֔ל עַ֥ל כָּל־הַ⁠מְּקֹמ֖וֹת אֲשֶׁ֥ר תֵּֽלֶךְ־שָֽׁם׃ס","wĕ⁠ʼaţá֛̇h ţĕ̇baqėş̌-lĕ⁠ká֥ gĕdòl֖wòţ ʼal-ţĕ̇baqé֑̇ş̌ ki̇֡y hinĕ⁠niy֩ mébi֨yʼ ráʻá֤h ʻal-ká̇l-bá̇şá̂r֙ nĕʼum-yĕhwá֔h wĕ⁠náţaţi̇֨y lĕ⁠ká֤ ʼeֽţ-napĕşĕ̌⁠ká֙ lĕ⁠şá̌lá֔l ʻa֥l ká̇l-ha⁠mĕ̇qòm֖wòţ ʼàşě֥r ţéֽ̇lekĕ-şáֽ̌m׃s"],[46,1,"אֲשֶׁ֨ר הָיָ֧ה דְבַר־יְהוָ֛ה אֶל־יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא עַל־הַ⁠גּוֹיִֽם׃","ʼàşě֨r háyá֧h dĕbar-yĕhwá֛h ʼel-yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ ʻal-ha⁠ġwòyiֽm׃"],[46,2,"לְ⁠מִצְרַ֗יִם עַל־חֵ֨יל פַּרְעֹ֤ה נְכוֹ֙ מֶ֣לֶךְ מִצְרַ֔יִם אֲשֶׁר־הָיָ֥ה עַל־נְהַר־פְּרָ֖ת בְּ⁠כַרְכְּמִ֑שׁ אֲשֶׁ֣ר הִכָּ֗ה נְבֽוּכַדְרֶאצַּר֙ מֶ֣לֶךְ בָּבֶ֔ל בִּ⁠שְׁנַת֙ הָֽ⁠רְבִיעִ֔ית לִ⁠יהוֹיָקִ֥ים בֶּן־יֹאשִׁיָּ֖הוּ מֶ֥לֶךְ יְהוּדָֽה׃","lĕ⁠miẕĕra֗yim ʻal-ẖé֨yl pȧrĕʻò֤h nĕkwò֙ me֣lekĕ miẕĕra֔yim ʼàşěr-háyá֥h ʻal-nĕhar-pĕ̇rá֖ţ bĕ̇⁠karĕkĕ̇mi֑ş̌ ʼàşě֣r hiká̇֗h nĕbֽẇkadĕreʼẕȧr֙ me֣lekĕ bá̇be֔l bi̇⁠şĕ̌naţ֙ háֽ⁠rĕbiyʻi֔yţ li⁠yhwòyáqi֥ym bėn-yòʼşǐyá֖̇hẇ me֥lekĕ yĕhẇdáֽh׃"],[46,3,"עִרְכ֤וּ מָגֵן֙ וְ⁠צִנָּ֔ה וּ⁠גְשׁ֖וּ לַ⁠מִּלְחָמָֽה׃","ʻirĕk֤ẇ mágén֙ wĕ⁠ẕiná̇֔h ẇ⁠gĕş֖̌ẇ la⁠mi̇lĕẖámáֽh׃"],[46,4,"אִסְר֣וּ הַ⁠סּוּסִ֗ים וַֽ⁠עֲלוּ֙ הַ⁠פָּ֣רָשִׁ֔ים וְ⁠הִֽתְיַצְּב֖וּ בְּ⁠כ֥וֹבָעִ֑ים מִרְקוּ֙ הָֽ⁠רְמָחִ֔ים לִבְשׁ֖וּ הַ⁠סִּרְיֹנֹֽת׃","ʼisĕr֣ẇ ha⁠ṡẇsi֗ym waֽ⁠ʻàlẇ֙ ha⁠pá֣̇ráşǐ֔ym wĕ⁠hiֽţĕyaẕĕ̇b֖ẇ bĕ̇⁠k֥wòbáʻi֑ym mirĕqẇ֙ háֽ⁠rĕmáẖi֔ym libĕş֖̌ẇ ha⁠si̇rĕyònòֽţ׃"],[46,5,"מַדּ֣וּעַ רָאִ֗יתִי הֵ֣מָּה חַתִּים֮ נְסֹגִ֣ים אָחוֹר֒ וְ⁠גִבּוֹרֵי⁠הֶ֣ם יֻכַּ֔תּוּ וּ⁠מָנ֥וֹס נָ֖סוּ וְ⁠לֹ֣א הִפְנ֑וּ מָג֥וֹר מִ⁠סָּבִ֖יב נְאֻם־יְהוָֽה׃","maḋ֣ẇʻa ráʼi֗yţiy hé֣má̇h ẖaţi̇ym֮ nĕsògi֣ym ʼáẖwòr֒ wĕ⁠giḃwòréy⁠he֣m yukȧ֔ţ̇ẇ ẇ⁠mán֥wòs ná֖sẇ wĕ⁠lò֣ʼ hipĕn֑ẇ mág֥wòr mi⁠sá̇bi֖yb nĕʼum-yĕhwáֽh׃"],[46,6,"אַל־יָנ֣וּס הַ⁠קַּ֔ל וְ⁠אַל־יִמָּלֵ֖ט הַ⁠גִּבּ֑וֹר צָפ֨וֹנָ⁠ה֙ עַל־יַ֣ד נְהַר־פְּרָ֔ת כָּשְׁל֖וּ וְ⁠נָפָֽלוּ׃","ʼal-yán֣ẇs ha⁠qȧ֔l wĕ⁠ʼal-yimá̇lé֖t ha⁠gi̇ḃ֑wòr ẕáp֨wòná⁠h֙ ʻal-ya֣d nĕhar-pĕ̇rá֔ţ ká̇şĕ̌l֖ẇ wĕ⁠nápáֽlẇ׃"],[46,7,"מִי־זֶ֖ה כַּ⁠יְאֹ֣ר יַֽעֲלֶ֑ה כַּ⁠נְּהָר֕וֹת יִֽתְגָּעֲשׁ֖וּ מֵימָֽי⁠ו׃","miy-ze֖h kȧ⁠yĕʼò֣r yaֽʻàle֑h kȧ⁠nĕ̇hár֕wòţ yiֽţĕgá̇ʻàş֖̌ẇ méymáֽy⁠w׃"],[46,8,"מִצְרַ֨יִם֙ כַּ⁠יְאֹ֣ר יַֽעֲלֶ֔ה וְ⁠כַ⁠נְּהָר֖וֹת יִתְגֹּ֣עֲשׁוּ מָ֑יִם וַ⁠יֹּ֗אמֶר אַֽעֲלֶה֙ אֲכַסֶּה־אֶ֔רֶץ אֹבִ֥ידָה עִ֖יר וְ⁠יֹ֥שְׁבֵי בָֽ⁠הּ׃","miẕĕra֨yim֙ kȧ⁠yĕʼò֣r yaֽʻàle֔h wĕ⁠ka⁠nĕ̇hár֖wòţ yiţĕgò֣̇ʻàş̌ẇ má֑yim wa⁠yò̇֗ʼmer ʼaֽʻàleh֙ ʼàkasėh-ʼe֔reẕ ʼòbi֥ydáh ʻi֖yr wĕ⁠yò֥şĕ̌béy báֽ⁠ḣ׃"],[46,9,"עֲל֤וּ הַ⁠סּוּסִים֙ וְ⁠הִתְהֹלְל֣וּ הָ⁠רֶ֔כֶב וְ⁠יֵצְא֖וּ הַ⁠גִּבּוֹרִ֑ים כּ֤וּשׁ וּ⁠פוּט֙ תֹּפְשֵׂ֣י מָגֵ֔ן וְ⁠לוּדִ֕ים תֹּפְשֵׂ֖י דֹּ֥רְכֵי קָֽשֶׁת׃","ʻàl֤ẇ ha⁠ṡẇsiym֙ wĕ⁠hiţĕhòlĕl֣ẇ há⁠re֔keb wĕ⁠yéẕĕʼ֖ẇ ha⁠gi̇ḃwòri֑ym k֤̇ẇş̌ ẇ⁠pẇt֙ ţò̇pĕşé֣̂y mágé֔n wĕ⁠lẇdi֕ym ţò̇pĕşé֖̂y dò֥̇rĕkéy qáֽşěţ׃"],[46,10,"וְֽ⁠הַ⁠יּ֨וֹם הַ⁠ה֜וּא לַ⁠אדֹנָ֧⁠י יְהוִ֣ה צְבָא֗וֹת י֤וֹם נְקָמָה֙ לְ⁠הִנָּקֵ֣ם מִ⁠צָּרָ֔י⁠ו וְ⁠אָכְלָ֥ה חֶ֨רֶב֙ וְ⁠שָׂ֣בְעָ֔ה וְ⁠רָוְתָ֖ה מִ⁠דָּמָ֑⁠ם כִּ֣י זֶ֠בַח לַ⁠אדֹנָ֨⁠י יְהוִ֧ה צְבָא֛וֹת בְּ⁠אֶ֥רֶץ צָפ֖וֹן אֶל־נְהַר־פְּרָֽת׃","wĕֽ⁠ha⁠ẏ֨wòm ha⁠h֜ẇʼ la⁠ʼdòná֧⁠y yĕhwi֣h ẕĕbáʼ֗wòţ y֤wòm nĕqámáh֙ lĕ⁠hiná̇qé֣m mi⁠ẕá̇rá֔y⁠w wĕ⁠ʼákĕlá֥h ẖe֨reb֙ wĕ⁠şá֣̂bĕʻá֔h wĕ⁠ráwĕţá֖h mi⁠dá̇má֑⁠m ki֣̇y ze֠baẖ la⁠ʼdòná֨⁠y yĕhwi֧h ẕĕbáʼ֛wòţ bĕ̇⁠ʼe֥reẕ ẕáp֖wòn ʼel-nĕhar-pĕ̇ráֽţ׃"],[46,11,"עֲלִ֤י גִלְעָד֙ וּ⁠קְחִ֣י צֳרִ֔י בְּתוּלַ֖ת בַּת־מִצְרָ֑יִם לַ⁠שָּׁוְא֙ הרביתי רְפֻא֔וֹת תְּעָלָ֖ה אֵ֥ין לָֽ⁠ךְ׃","ʻàli֤y gilĕʻád֙ ẇ⁠qĕẖi֣y ẕori֔y bĕ̇ţẇla֖ţ bȧţ-miẕĕrá֑yim la⁠şá̇̌wĕʼ֙ hrbyţy rĕpuʼ֔wòţ ţĕ̇ʻálá֖h ʼé֥yn láֽ⁠kĕ׃"],[46,12,"שָׁמְע֤וּ גוֹיִם֙ קְלוֹנֵ֔⁠ךְ וְ⁠צִוְחָתֵ֖⁠ךְ מָלְאָ֣ה הָ⁠אָ֑רֶץ כִּֽי־גִבּ֤וֹר בְּ⁠גִבּוֹר֙ כָּשָׁ֔לוּ יַחְדָּ֖יו נָפְל֥וּ שְׁנֵי⁠הֶֽם׃פ","şá̌mĕʻ֤ẇ gwòyim֙ qĕlwòné֔⁠kĕ wĕ⁠ẕiwĕẖáţé֖⁠kĕ málĕʼá֣h há⁠ʼá֑reẕ kiֽ̇y-giḃ֤wòr bĕ̇⁠giḃwòr֙ ká̇şá̌֔lẇ yaẖĕdá֖̇yw nápĕl֥ẇ şĕ̌néy⁠heֽm׃p"],[46,13,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר דִּבֶּ֣ר יְהוָ֔ה אֶֽל־יִרְמְיָ֖הוּ הַ⁠נָּבִ֑יא לָ⁠ב֗וֹא נְבֽוּכַדְרֶאצַּר֙ מֶ֣לֶךְ בָּבֶ֔ל לְ⁠הַכּ֖וֹת אֶת־אֶ֥רֶץ מִצְרָֽיִם׃","ha⁠dá̇bár֙ ʼàşě֣r di̇bė֣r yĕhwá֔h ʼeֽl-yirĕmĕyá֖hẇ ha⁠ná̇bi֑yʼ lá⁠b֗wòʼ nĕbֽẇkadĕreʼẕȧr֙ me֣lekĕ bá̇be֔l lĕ⁠hak֖̇wòţ ʼeţ-ʼe֥reẕ miẕĕráֽyim׃"],[46,14,"הַגִּ֤ידוּ בְ⁠מִצְרַ֨יִם֙ וְ⁠הַשְׁמִ֣יעוּ בְ⁠מִגְדּ֔וֹל וְ⁠הַשְׁמִ֥יעוּ בְ⁠נֹ֖ף וּ⁠בְ⁠תַחְפַּנְחֵ֑ס אִמְר֗וּ הִתְיַצֵּב֙ וְ⁠הָכֵ֣ן לָ֔⁠ךְ כִּֽי־אָכְלָ֥ה חֶ֖רֶב סְבִיבֶֽי⁠ךָ׃","hagi֤̇ydẇ bĕ⁠miẕĕra֨yim֙ wĕ⁠haşĕ̌mi֣yʻẇ bĕ⁠migĕḋ֔wòl wĕ⁠haşĕ̌mi֥yʻẇ bĕ⁠nò֖p ẇ⁠bĕ⁠ţaẖĕpȧnĕẖé֑s ʼimĕr֗ẇ hiţĕyaẕé̇b֙ wĕ⁠háké֣n lá֔⁠kĕ kiֽ̇y-ʼákĕlá֥h ẖe֖reb sĕbiybeֽy⁠ká׃"],[46,15,"מַדּ֖וּעַ נִסְחַ֣ף אַבִּירֶ֑י⁠ךָ לֹ֣א עָמַ֔ד כִּ֥י יְהוָ֖ה הֲדָפֽ⁠וֹ׃","maḋ֖ẇʻa nisĕẖa֣p ʼabi̇yre֑y⁠ká lò֣ʼ ʻáma֔d ki֥̇y yĕhwá֖h hàdápֽ⁠wò׃"],[46,16,"הִרְבָּ֖ה כּוֹשֵׁ֑ל גַּם־נָפַ֞ל אִ֣ישׁ אֶל־רֵעֵ֗⁠הוּ וַ⁠יֹּֽאמְרוּ֙ ק֣וּמָ⁠ה ׀ וְ⁠נָשֻׁ֣בָה אֶל־עַמֵּ֗⁠נוּ וְ⁠אֶל־אֶ֨רֶץ֙ מֽוֹלַדְתֵּ֔⁠נוּ מִ⁠פְּנֵ֖י חֶ֥רֶב הַ⁠יּוֹנָֽה׃","hirĕbá֖̇h k̇wòşé֑̌l gȧm-nápa֞l ʼi֣yş̌ ʼel-réʻé֗⁠hẇ wa⁠yòֽ̇ʼmĕrẇ֙ q֣ẇmá⁠h ׀ wĕ⁠náşǔ֣báh ʼel-ʻamé̇֗⁠nẇ wĕ⁠ʼel-ʼe֨reẕ֙ mֽwòladĕţé̇֔⁠nẇ mi⁠pĕ̇né֖y ẖe֥reb ha⁠ẏwònáֽh׃"],[46,17,"קָרְא֖וּ שָׁ֑ם פַּרְעֹ֤ה מֶֽלֶךְ־מִצְרַ֨יִם֙ שָׁא֔וֹן הֶעֱבִ֖יר הַ⁠מּוֹעֵֽד׃","qárĕʼ֖ẇ şá֑̌m pȧrĕʻò֤h meֽlekĕ-miẕĕra֨yim֙ şá̌ʼ֔wòn heʻèbi֖yr ha⁠ṁwòʻéֽd׃"],[46,18,"חַי־אָ֨נִי֙ נְאֻם־הַ⁠מֶּ֔לֶךְ יְהוָ֥ה צְבָא֖וֹת שְׁמ֑⁠וֹ כִּ֚י כְּ⁠תָב֣וֹר בֶּֽ⁠הָרִ֔ים וּ⁠כְ⁠כַרְמֶ֖ל בַּ⁠יָּ֥ם יָבֽוֹא׃","ẖay-ʼá֨niy֙ nĕʼum-ha⁠mė֔lekĕ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌m֑⁠wò ki֚̇y kĕ̇⁠ţáb֣wòr bėֽ⁠hári֔ym ẇ⁠kĕ⁠karĕme֖l bȧ⁠yá֥̇m yábֽwòʼ׃"],[46,19,"כְּלֵ֤י גוֹלָה֙ עֲשִׂ֣י לָ֔⁠ךְ יוֹשֶׁ֖בֶת בַּת־מִצְרָ֑יִם כִּֽי־נֹף֙ לְ⁠שַׁמָּ֣ה תִֽהְיֶ֔ה וְ⁠נִצְּתָ֖ה מֵ⁠אֵ֥ין יוֹשֵֽׁב׃ס","kĕ̇lé֤y gwòláh֙ ʻàşî֣y lá֔⁠kĕ ywòşě֖beţ bȧţ-miẕĕrá֑yim kiֽ̇y-nòp֙ lĕ⁠şǎmá֣̇h ţiֽhĕye֔h wĕ⁠niẕĕ̇ţá֖h mé⁠ʼé֥yn ywòşéֽ̌b׃s"],[46,20,"עֶגְלָ֥ה יְפֵֽה־פִיָּ֖ה מִצְרָ֑יִם קֶ֥רֶץ מִ⁠צָּפ֖וֹן בָּ֥א בָֽא׃","ʻegĕlá֥h yĕpéֽh-piyá֖̇h miẕĕrá֑yim qe֥reẕ mi⁠ẕá̇p֖wòn bá֥̇ʼ báֽʼ׃"],[46,21,"גַּם־שְׂכִרֶ֤י⁠הָ בְ⁠קִרְבָּ⁠הּ֙ כְּ⁠עֶגְלֵ֣י מַרְבֵּ֔ק כִּֽי־גַם־הֵ֧מָּה הִפְנ֛וּ נָ֥סוּ יַחְדָּ֖יו לֹ֣א עָמָ֑דוּ כִּ֣י י֥וֹם אֵידָ֛⁠ם בָּ֥א עֲלֵי⁠הֶ֖ם עֵ֥ת פְּקֻדָּתָֽ⁠ם׃","gȧm-şĕ̂kire֤y⁠há bĕ⁠qirĕbá̇⁠ḣ֙ kĕ̇⁠ʻegĕlé֣y marĕbé̇֔q kiֽ̇y-gam-hé֧má̇h hipĕn֛ẇ ná֥sẇ yaẖĕdá֖̇yw lò֣ʼ ʻámá֑dẇ ki֣̇y y֥wòm ʼéydá֛⁠m bá֥̇ʼ ʻàléy⁠he֖m ʻé֥ţ pĕ̇qudá̇ţáֽ⁠m׃"],[46,22,"קוֹלָ֖⁠הּ כַּ⁠נָּחָ֣שׁ יֵלֵ֑ךְ כִּֽי־בְ⁠חַ֣יִל יֵלֵ֔כוּ וּ⁠בְ⁠קַרְדֻּמּוֹת֙ בָּ֣אוּ לָ֔⁠הּ כְּ⁠חֹטְבֵ֖י עֵצִֽים׃","qwòlá֖⁠ḣ kȧ⁠ná̇ẖá֣ş̌ yélé֑kĕ kiֽ̇y-bĕ⁠ẖa֣yil yélé֔kẇ ẇ⁠bĕ⁠qarĕdu̇ṁwòţ֙ bá֣̇ʼẇ lá֔⁠ḣ kĕ̇⁠ẖòtĕbé֖y ʻéẕiֽym׃"],[46,23,"כָּרְת֤וּ יַעְרָ⁠הּ֙ נְאֻם־יְהוָ֔ה כִּ֖י לֹ֣א יֵֽחָקֵ֑ר כִּ֤י רַבּוּ֙ מֵֽ⁠אַרְבֶּ֔ה וְ⁠אֵ֥ין לָ⁠הֶ֖ם מִסְפָּֽר׃","ká̇rĕţ֤ẇ yaʻĕrá⁠ḣ֙ nĕʼum-yĕhwá֔h ki֖̇y lò֣ʼ yéֽẖáqé֑r ki֤̇y raḃẇ֙ méֽ⁠ʼarĕbė֔h wĕ⁠ʼé֥yn lá⁠he֖m misĕpáֽ̇r׃"],[46,24,"הֹבִ֖ישָׁה בַּת־מִצְרָ֑יִם נִתְּנָ֖ה בְּ⁠יַ֥ד עַם־צָפֽוֹן׃","hòbi֖yşá̌h bȧţ-miẕĕrá֑yim niţĕ̇ná֖h bĕ̇⁠ya֥d ʻam-ẕápֽwòn׃"],[46,25,"אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הִנְ⁠נִ֤י פוֹקֵד֙ אֶל־אָמ֣וֹן מִ⁠נֹּ֔א וְ⁠עַל־פַּרְעֹה֙ וְ⁠עַל־מִצְרַ֔יִם וְ⁠עַל־אֱלֹהֶ֖י⁠הָ וְ⁠עַל־מְלָכֶ֑י⁠הָ וְ⁠עַ֨ל־פַּרְעֹ֔ה וְ⁠עַ֥ל הַ⁠בֹּטְחִ֖ים בּֽ⁠וֹ׃","ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l hinĕ⁠ni֤y pwòqéd֙ ʼel-ʼám֣wòn mi⁠nò̇֔ʼ wĕ⁠ʻal-pȧrĕʻòh֙ wĕ⁠ʻal-miẕĕra֔yim wĕ⁠ʻal-ʼèlòhe֖y⁠há wĕ⁠ʻal-mĕláke֑y⁠há wĕ⁠ʻa֨l-pȧrĕʻò֔h wĕ⁠ʻa֥l ha⁠bò̇tĕẖi֖ym ḃֽ⁠wò׃"],[46,26,"וּ⁠נְתַתִּ֗י⁠ם בְּ⁠יַד֙ מְבַקְשֵׁ֣י נַפְשָׁ֔⁠ם וּ⁠בְ⁠יַ֛ד נְבֽוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל וּ⁠בְ⁠יַד־עֲבָדָ֑י⁠ו וְ⁠אַחֲרֵי־כֵ֛ן תִּשְׁכֹּ֥ן כִּֽ⁠ימֵי־קֶ֖דֶם נְאֻם־יְהוָֽה׃ס","ẇ⁠nĕţaţi̇֗y⁠m bĕ̇⁠yad֙ mĕbaqĕşé֣̌y napĕşá̌֔⁠m ẇ⁠bĕ⁠ya֛d nĕbֽẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l ẇ⁠bĕ⁠yad-ʻàbádá֑y⁠w wĕ⁠ʼaẖàréy-ké֛n ţi̇şĕ̌kò֥̇n kiֽ̇⁠yméy-qe֖dem nĕʼum-yĕhwáֽh׃s"],[46,27,"וְ֠⁠אַתָּה אַל־תִּירָ֞א עַבְדִּ֤⁠י יַֽעֲקֹב֙ וְ⁠אַל־תֵּחַ֣ת יִשְׂרָאֵ֔ל כִּ֠י הִנְ⁠נִ֤י מוֹשִֽׁעֲ⁠ךָ֙ מֵֽ⁠רָח֔וֹק וְ⁠אֶֽת־זַרְעֲ⁠ךָ֖ מֵ⁠אֶ֣רֶץ שִׁבְיָ֑⁠ם וְ⁠שָׁ֧ב יַעֲק֛וֹב וְ⁠שָׁקַ֥ט וְ⁠שַׁאֲנַ֖ן וְ⁠אֵ֥ין מַחֲרִֽיד׃ס","wĕ֠⁠ʼaţá̇h ʼal-ţi̇yrá֞ʼ ʻabĕdi֤̇⁠y yaֽʻàqòb֙ wĕ⁠ʼal-ţé̇ẖa֣ţ yişĕ̂ráʼé֔l ki̇֠y hinĕ⁠ni֤y mwòşǐֽʻà⁠ká֙ méֽ⁠ráẖ֔wòq wĕ⁠ʼeֽţ-zarĕʻà⁠ká֖ mé⁠ʼe֣reẕ şǐbĕyá֑⁠m wĕ⁠şá֧̌b yaʻàq֛wòb wĕ⁠şá̌qa֥t wĕ⁠şǎʼàna֖n wĕ⁠ʼé֥yn maẖàriֽyd׃s"],[46,28,"אַ֠תָּה אַל־תִּירָ֞א עַבְדִּ֤⁠י יַֽעֲקֹב֙ נְאֻם־יְהוָ֔ה כִּ֥י אִתְּ⁠ךָ֖ אָ֑נִי כִּי֩ אֶעֱשֶׂ֨ה כָלָ֜ה בְּ⁠כָֽל־הַ⁠גּוֹיִ֣ם ׀ אֲשֶׁ֧ר הִדַּחְתִּ֣י⁠ךָ שָׁ֗מָּ⁠ה וְ⁠אֹֽתְ⁠ךָ֙ לֹא־אֶעֱשֶׂ֣ה כָלָ֔ה וְ⁠יִסַּרְתִּ֨י⁠ךָ֙ לַ⁠מִּשְׁפָּ֔ט וְ⁠נַקֵּ֖ה לֹ֥א אֲנַקֶּֽ⁠ךָּ׃ס","ʼa֠ţá̇h ʼal-ţi̇yrá֞ʼ ʻabĕdi֤̇⁠y yaֽʻàqòb֙ nĕʼum-yĕhwá֔h ki֥̇y ʼiţĕ̇⁠ká֖ ʼá֑niy ki̇y֩ ʼeʻèşê֨h kálá֜h bĕ̇⁠káֽl-ha⁠ġwòyi֣m ׀ ʼàşě֧r hidȧẖĕţi֣̇y⁠ká şá̌֗má̇⁠h wĕ⁠ʼòֽţĕ⁠ká֙ lòʼ-ʼeʻèşê֣h kálá֔h wĕ⁠yisȧrĕţi̇֨y⁠ká֙ la⁠mi̇şĕ̌pá̇֔t wĕ⁠naqé֖̇h lò֥ʼ ʼànaqėֽ⁠ká̇׃s"],[47,1,"אֲשֶׁ֨ר הָיָ֧ה דְבַר־יְהוָ֛ה אֶל־יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא אֶל־פְּלִשְׁתִּ֑ים בְּ⁠טֶ֛רֶם יַכֶּ֥ה פַרְעֹ֖ה אֶת־עַזָּֽה׃ס","ʼàşě֨r háyá֧h dĕbar-yĕhwá֛h ʼel-yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ ʼel-pĕ̇lişĕ̌ţi֑̇ym bĕ̇⁠te֛rem yakė֥h parĕʻò֖h ʼeţ-ʻazáֽ̇h׃s"],[47,2,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה הִנֵּה־מַ֜יִם עֹלִ֤ים מִ⁠צָּפוֹן֙ וְ⁠הָיוּ֙ לְ⁠נַ֣חַל שׁוֹטֵ֔ף וְ⁠יִשְׁטְפוּ֙ אֶ֣רֶץ וּ⁠מְלוֹאָ֔⁠הּ עִ֖יר וְ⁠יֹ֣שְׁבֵי בָ֑⁠הּ וְ⁠זָֽעֲקוּ֙ הָֽ⁠אָדָ֔ם וְ⁠הֵילִ֕ל כֹּ֖ל יוֹשֵׁ֥ב הָ⁠אָֽרֶץ׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h hiné̇h-ma֜yim ʻòli֤ym mi⁠ẕá̇pwòn֙ wĕ⁠háyẇ֙ lĕ⁠na֣ẖal ş̌wòté֔p wĕ⁠yişĕ̌tĕpẇ֙ ʼe֣reẕ ẇ⁠mĕlwòʼá֔⁠ḣ ʻi֖yr wĕ⁠yò֣şĕ̌béy bá֑⁠ḣ wĕ⁠záֽʻàqẇ֙ háֽ⁠ʼádá֔m wĕ⁠héyli֕l kò֖̇l ywòşé֥̌b há⁠ʼáֽreẕ׃"],[47,3,"מִ⁠קּ֗וֹל שַֽׁעֲטַת֙ פַּרְס֣וֹת אַבִּירָ֔י⁠ו מֵ⁠רַ֣עַשׁ לְ⁠רִכְבּ֔⁠וֹ הֲמ֖וֹן גַּלְגִּלָּ֑י⁠ו לֹֽא־הִפְנ֤וּ אָבוֹת֙ אֶל־בָּנִ֔ים מֵֽ⁠רִפְי֖וֹן יָדָֽיִם׃","mi⁠q̇֗wòl şǎֽʻàtaţ֙ pȧrĕs֣wòţ ʼabi̇yrá֔y⁠w mé⁠ra֣ʻaş̌ lĕ⁠rikĕḃ֔⁠wò hàm֖wòn gȧlĕgi̇lá֑̇y⁠w lòֽʼ-hipĕn֤ẇ ʼábwòţ֙ ʼel-bá̇ni֔ym méֽ⁠ripĕy֖wòn yádáֽyim׃"],[47,4,"עַל־הַ⁠יּ֗וֹם הַ⁠בָּא֙ לִ⁠שְׁד֣וֹד אֶת־כָּל־פְּלִשְׁתִּ֔ים לְ⁠הַכְרִ֤ית לְ⁠צֹר֙ וּ⁠לְ⁠צִיד֔וֹן כֹּ֖ל שָׂרִ֣יד עֹזֵ֑ר כִּֽי־שֹׁדֵ֤ד יְהוָה֙ אֶת־פְּלִשְׁתִּ֔ים שְׁאֵרִ֖ית אִ֥י כַפְתּֽוֹר׃","ʻal-ha⁠ẏ֗wòm ha⁠bá̇ʼ֙ li⁠şĕ̌d֣wòd ʼeţ-ká̇l-pĕ̇lişĕ̌ţi̇֔ym lĕ⁠hakĕri֤yţ lĕ⁠ẕòr֙ ẇ⁠lĕ⁠ẕiyd֔wòn kò֖̇l şá̂ri֣yd ʻòzé֑r kiֽ̇y-şò̌dé֤d yĕhwáh֙ ʼeţ-pĕ̇lişĕ̌ţi̇֔ym şĕ̌ʼéri֖yţ ʼi֥y kapĕţֽ̇wòr׃"],[47,5,"בָּ֤אָה קָרְחָה֙ אֶל־עַזָּ֔ה נִדְמְתָ֥ה אַשְׁקְל֖וֹן שְׁאֵרִ֣ית עִמְקָ֑⁠ם עַד־מָתַ֖י תִּתְגּוֹדָֽדִי׃ס","bá֤̇ʼáh qárĕẖáh֙ ʼel-ʻazá̇֔h nidĕmĕţá֥h ʼaşĕ̌qĕl֖wòn şĕ̌ʼéri֣yţ ʻimĕqá֑⁠m ʻad-máţa֖y ţi̇ţĕġwòdáֽdiy׃s"],[47,6,"ה֗וֹי חֶ֚רֶב לַֽ⁠יהוָ֔ה עַד־אָ֖נָה לֹ֣א תִשְׁקֹ֑טִי הֵאָֽסְפִי֙ אַל־תַּעְרֵ֔⁠ךְ הֵרָגְעִ֖י וָ⁠דֹֽמִּי׃","h֗wòy ẖe֚reb laֽ⁠yhwá֔h ʻad-ʼá֖náh lò֣ʼ ţişĕ̌qò֑tiy héʼáֽsĕpiy֙ ʼal-ţȧʻĕré֔⁠kĕ hérágĕʻi֖y wá⁠dòֽmi̇y׃"],[47,7,"אֵ֣יךְ תִּשְׁקֹ֔טִי וַֽ⁠יהוָ֖ה צִוָּה־לָ֑⁠הּ אֶֽל־אַשְׁקְל֛וֹן וְ⁠אֶל־ח֥וֹף הַ⁠יָּ֖ם שָׁ֥ם יְעָדָֽ⁠הּ׃ס","ʼé֣ykĕ ţi̇şĕ̌qò֔tiy waֽ⁠yhwá֖h ẕiwá̇h-lá֑⁠ḣ ʼeֽl-ʼaşĕ̌qĕl֛wòn wĕ⁠ʼel-ẖ֥wòp ha⁠yá֖̇m şá֥̌m yĕʻádáֽ⁠ḣ׃s"],[48,1,"לְ⁠מוֹאָ֡ב כֹּֽה־אָמַר֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל ה֤וֹי אֶל־נְבוֹ֙ כִּ֣י שֻׁדָּ֔דָה הֹבִ֥ישָׁה נִלְכְּדָ֖ה קִרְיָתָ֑יִם הֹבִ֥ישָׁה הַ⁠מִּשְׂגָּ֖ב וָ⁠חָֽתָּה׃","lĕ⁠mwòʼá֡b kòֽ̇h-ʼámar֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l h֤wòy ʼel-nĕbwò֙ ki֣̇y şǔdá̇֔dáh hòbi֥yşá̌h nilĕkĕ̇dá֖h qirĕyáţá֑yim hòbi֥yşá̌h ha⁠mi̇şĕ̂gá֖̇b wá⁠ẖáֽţá̇h׃"],[48,2,"אֵ֣ין עוֹד֮ תְּהִלַּ֣ת מוֹאָב֒ בְּ⁠חֶשְׁבּ֗וֹן חָשְׁב֤וּ עָלֶ֨י⁠הָ֙ רָעָ֔ה לְכ֖וּ וְ⁠נַכְרִיתֶ֣⁠נָּה מִ⁠גּ֑וֹי גַּם־מַדְמֵ֣ן תִּדֹּ֔מִּי אַחֲרַ֖יִ⁠ךְ תֵּ֥לֶךְ חָֽרֶב׃","ʼé֣yn ʻwòd֮ ţĕ̇hilȧ֣ţ mwòʼáb֒ bĕ̇⁠ẖeşĕ̌ḃ֗wòn ẖáşĕ̌b֤ẇ ʻále֨y⁠há֙ ráʻá֔h lĕk֖ẇ wĕ⁠nakĕriyţe֣⁠ná̇h mi⁠ġ֑wòy gȧm-madĕmé֣n ţi̇dò̇֔mi̇y ʼaẖàra֖yi⁠kĕ ţé֥̇lekĕ ẖáֽreb׃"],[48,3,"ק֥וֹל צְעָקָ֖ה מֵ⁠חֹֽרוֹנָ֑יִם שֹׁ֖ד וָ⁠שֶׁ֥בֶר גָּדֽוֹל׃","q֥wòl ẕĕʻáqá֖h mé⁠ẖòֽrwòná֑yim şò֖̌d wá⁠şě֥ber gá̇dֽwòl׃"],[48,4,"נִשְׁבְּרָ֖ה מוֹאָ֑ב הִשְׁמִ֥יעוּ זְּעָקָ֖ה צעורי⁠ה׃","nişĕ̌bĕ̇rá֖h mwòʼá֑b hişĕ̌mi֥yʻẇ zĕ̇ʻáqá֖h ẕʻwry⁠h׃"],[48,5,"כִּ֚י מַעֲלֵ֣ה ה⁠לחות בִּ⁠בְכִ֖י יַֽעֲלֶה־בֶּ֑כִי כִּ֚י בְּ⁠מוֹרַ֣ד חוֹרֹנַ֔יִם צָרֵ֥י צַֽעֲקַת־שֶׁ֖בֶר שָׁמֵֽעוּ׃","ki֚̇y maʻàlé֣h h⁠lẖwţ bi̇⁠bĕki֖y yaֽʻàleh-bė֑kiy ki֚̇y bĕ̇⁠mwòra֣d ẖwòròna֔yim ẕáré֥y ẕaֽʻàqaţ-şě֖ber şá̌méֽʻẇ׃"],[48,6,"נֻ֖סוּ מַלְּט֣וּ נַפְשְׁ⁠כֶ֑ם וְ⁠תִֽהְיֶ֕ינָה כַּ⁠עֲרוֹעֵ֖ר בַּ⁠מִּדְבָּֽר׃","nu֖sẇ malĕ̇t֣ẇ napĕşĕ̌⁠ke֑m wĕ⁠ţiֽhĕye֕ynáh kȧ⁠ʻàrwòʻé֖r bȧ⁠mi̇dĕbáֽ̇r׃"],[48,7,"כִּ֠י יַ֣עַן בִּטְחֵ֤⁠ךְ בְּ⁠מַעֲשַׂ֨יִ⁠ךְ֙ וּ⁠בְ⁠א֣וֹצְרוֹתַ֔יִ⁠ךְ גַּם־אַ֖תְּ תִּלָּכֵ֑דִי וְ⁠יָצָ֤א כמיש בַּ⁠גּוֹלָ֔ה כֹּהֲנָ֥י⁠ו וְ⁠שָׂרָ֖י⁠ו יחד׃","ki̇֠y ya֣ʻan bi̇tĕẖé֤⁠kĕ bĕ̇⁠maʻàşâ֨yi⁠kĕ֙ ẇ⁠bĕ⁠ʼ֣wòẕĕrwòţa֔yi⁠kĕ gȧm-ʼa֖ţĕ̇ ţi̇lá̇ké֑diy wĕ⁠yáẕá֤ʼ kmyş bȧ⁠ġwòlá֔h kò̇hàná֥y⁠w wĕ⁠şá̂rá֖y⁠w yẖd׃"],[48,8,"וְ⁠יָבֹ֨א שֹׁדֵ֜ד אֶל־כָּל־עִ֗יר וְ⁠עִיר֙ לֹ֣א תִמָּלֵ֔ט וְ⁠אָבַ֥ד הָ⁠עֵ֖מֶק וְ⁠נִשְׁמַ֣ד הַ⁠מִּישֹׁ֑ר אֲשֶׁ֖ר אָמַ֥ר יְהוָֽה׃","wĕ⁠yábò֨ʼ şò̌dé֜d ʼel-ká̇l-ʻi֗yr wĕ⁠ʻiyr֙ lò֣ʼ ţimá̇lé֔t wĕ⁠ʼába֥d há⁠ʻé֖meq wĕ⁠nişĕ̌ma֣d ha⁠mi̇yşò֑̌r ʼàşě֖r ʼáma֥r yĕhwáֽh׃"],[48,9,"תְּנוּ־צִ֣יץ לְ⁠מוֹאָ֔ב כִּ֥י נָצֹ֖א תֵּצֵ֑א וְ⁠עָרֶ֨י⁠הָ֙ לְ⁠שַׁמָּ֣ה תִֽהְיֶ֔ינָה מֵ⁠אֵ֥ין יוֹשֵׁ֖ב בָּ⁠הֵֽן׃","ţĕ̇nẇ-ẕi֣yẕ lĕ⁠mwòʼá֔b ki֥̇y náẕò֖ʼ ţé̇ẕé֑ʼ wĕ⁠ʻáre֨y⁠há֙ lĕ⁠şǎmá֣̇h ţiֽhĕye֔ynáh mé⁠ʼé֥yn ywòşé֖̌b bá̇⁠héֽn׃"],[48,10,"אָר֗וּר עֹשֶׂ֛ה מְלֶ֥אכֶת יְהוָ֖ה רְמִיָּ֑ה וְ⁠אָר֕וּר מֹנֵ֥עַ חַרְבּ֖⁠וֹ מִ⁠דָּֽם׃","ʼár֗ẇr ʻòşê֛h mĕle֥ʼkeţ yĕhwá֖h rĕmiyá֑̇h wĕ⁠ʼár֕ẇr mòné֥ʻa ẖarĕḃ֖⁠wò mi⁠dáֽ̇m׃"],[48,11,"שַׁאֲנַ֨ן מוֹאָ֜ב מִ⁠נְּעוּרָ֗י⁠ו וְ⁠שֹׁקֵ֥ט הוּא֙ אֶל־שְׁמָרָ֔י⁠ו וְ⁠לֹֽא־הוּרַ֤ק מִ⁠כְּלִי֙ אֶל־כֶּ֔לִי וּ⁠בַ⁠גּוֹלָ֖ה לֹ֣א הָלָ֑ךְ עַל־כֵּ֗ן עָמַ֤ד טַעְמ⁠וֹ֙ בּ֔⁠וֹ וְ⁠רֵיח֖⁠וֹ לֹ֥א נָמָֽר׃ס","şǎʼàna֨n mwòʼá֜b mi⁠nĕ̇ʻẇrá֗y⁠w wĕ⁠şò̌qé֥t hẇʼ֙ ʼel-şĕ̌márá֔y⁠w wĕ⁠lòֽʼ-hẇra֤q mi⁠kĕ̇liy֙ ʼel-kė֔liy ẇ⁠ba⁠ġwòlá֖h lò֣ʼ hálá֑kĕ ʻal-ké̇֗n ʻáma֤d taʻĕm⁠wò֙ ḃ֔⁠wò wĕ⁠réyẖ֖⁠wò lò֥ʼ námáֽr׃s"],[48,12,"לָ⁠כֵ֞ן הִנֵּ֖ה־יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וְ⁠שִׁלַּחְתִּי־ל֥⁠וֹ צֹעִ֖ים וְ⁠צֵעֻ֑⁠הוּ וְ⁠כֵלָ֣י⁠ו יָרִ֔יקוּ וְ⁠נִבְלֵי⁠הֶ֖ם יְנַפֵּֽצוּ׃","lá⁠ké֞n hiné֖̇h-yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wĕ⁠şǐlȧẖĕţi̇y-l֥⁠wò ẕòʻi֖ym wĕ⁠ẕéʻu֑⁠hẇ wĕ⁠kélá֣y⁠w yári֔yqẇ wĕ⁠nibĕléy⁠he֖m yĕnapéֽ̇ẕẇ׃"],[48,13,"וּ⁠בֹ֥שׁ מוֹאָ֖ב מִ⁠כְּמ֑וֹשׁ כַּ⁠אֲשֶׁר־בֹּ֨שׁוּ֙ בֵּ֣ית יִשְׂרָאֵ֔ל מִ⁠בֵּ֥ית אֵ֖ל מִבְטֶחָֽ⁠ם׃","ẇ⁠bò֥ş̌ mwòʼá֖b mi⁠kĕ̇m֑wòş̌ kȧ⁠ʼàşěr-bò̇֨ş̌ẇ֙ bé֣̇yţ yişĕ̂ráʼé֔l mi⁠bé֥̇yţ ʼé֖l mibĕteẖáֽ⁠m׃"],[48,14,"אֵ֚יךְ תֹּֽאמְר֔וּ גִּבּוֹרִ֖ים אֲנָ֑חְנוּ וְ⁠אַנְשֵׁי־חַ֖יִל לַ⁠מִּלְחָמָֽה׃","ʼé֚ykĕ ţòֽ̇ʼmĕr֔ẇ gi̇ḃwòri֖ym ʼàná֑ẖĕnẇ wĕ⁠ʼanĕşé̌y-ẖa֖yil la⁠mi̇lĕẖámáֽh׃"],[48,15,"שֻׁדַּ֤ד מוֹאָב֙ וְ⁠עָרֶ֣י⁠הָ עָלָ֔ה וּ⁠מִבְחַ֥ר בַּֽחוּרָ֖י⁠ו יָרְד֣וּ לַ⁠טָּ֑בַח נְאֻ֨ם־הַ⁠מֶּ֔לֶךְ יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃","şǔdȧ֤d mwòʼáb֙ wĕ⁠ʻáre֣y⁠há ʻálá֔h ẇ⁠mibĕẖa֥r bȧֽẖẇrá֖y⁠w yárĕd֣ẇ la⁠tá֑̇baẖ nĕʼu֨m-ha⁠mė֔lekĕ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃"],[48,16,"קָר֥וֹב אֵיד־מוֹאָ֖ב לָ⁠ב֑וֹא וְ⁠רָ֣עָת֔⁠וֹ מִהֲרָ֖ה מְאֹֽד׃","qár֥wòb ʼéyd-mwòʼá֖b lá⁠b֑wòʼ wĕ⁠rá֣ʻáţ֔⁠wò mihàrá֖h mĕʼòֽd׃"],[48,17,"נֻ֤דוּ ל⁠וֹ֙ כָּל־סְבִיבָ֔י⁠ו וְ⁠כֹ֖ל יֹדְעֵ֣י שְׁמ֑⁠וֹ אִמְר֗וּ אֵיכָ֤ה נִשְׁבַּר֙ מַטֵּה־עֹ֔ז מַקֵּ֖ל תִּפְאָרָֽה׃","nu֤dẇ l⁠wò֙ ká̇l-sĕbiybá֔y⁠w wĕ⁠kò֖l yòdĕʻé֣y şĕ̌m֑⁠wò ʼimĕr֗ẇ ʼéyká֤h nişĕ̌bȧr֙ maté̇h-ʻò֔z maqé֖̇l ţi̇pĕʼáráֽh׃"],[48,18,"רְדִ֤י מִ⁠כָּבוֹד֙ ישבי בַ⁠צָּמָ֔א יֹשֶׁ֖בֶת בַּת־דִּיב֑וֹן כִּֽי־שֹׁדֵ֤ד מוֹאָב֙ עָ֣לָה בָ֔⁠ךְ שִׁחֵ֖ת מִבְצָרָֽיִ⁠ךְ׃","rĕdi֤y mi⁠ká̇bwòd֙ yşby ba⁠ẕá̇má֔ʼ yòşě֖beţ bȧţ-di̇yb֑wòn kiֽ̇y-şò̌dé֤d mwòʼáb֙ ʻá֣láh bá֔⁠kĕ şǐẖé֖ţ mibĕẕáráֽyi⁠kĕ׃"],[48,19,"אֶל־דֶּ֛רֶךְ עִמְדִ֥י וְ⁠צַפִּ֖י יוֹשֶׁ֣בֶת עֲרוֹעֵ֑ר שַׁאֲלִי־נָ֣ס וְ⁠נִמְלָ֔טָה אִמְרִ֖י מַה־נִּֽהְיָֽתָה׃","ʼel-dė֛rekĕ ʻimĕdi֥y wĕ⁠ẕapi֖̇y ywòşě֣beţ ʻàrwòʻé֑r şǎʼàliy-ná֣s wĕ⁠nimĕlá֔táh ʼimĕri֖y mah-niֽ̇hĕyáֽţáh׃"],[48,20,"הֹבִ֥ישׁ מוֹאָ֛ב כִּֽי־חַ֖תָּה הילילי ׀ ו⁠זעקי הַגִּ֣ידוּ בְ⁠אַרְנ֔וֹן כִּ֥י שֻׁדַּ֖ד מוֹאָֽב׃","hòbi֥yş̌ mwòʼá֛b kiֽ̇y-ẖa֖ţá̇h hylyly ׀ w⁠zʻqy hagi֣̇ydẇ bĕ⁠ʼarĕn֔wòn ki֥̇y şǔdȧ֖d mwòʼáֽb׃"],[48,21,"וּ⁠מִשְׁפָּ֥ט בָּ֖א אֶל־אֶ֣רֶץ הַ⁠מִּישֹׁ֑ר אֶל־חֹל֥וֹן וְ⁠אֶל־יַ֖הְצָ⁠ה וְ⁠עַל־מופעת׃","ẇ⁠mişĕ̌pá֥̇t bá֖̇ʼ ʼel-ʼe֣reẕ ha⁠mi̇yşò֑̌r ʼel-ẖòl֥wòn wĕ⁠ʼel-ya֖hĕẕá⁠h wĕ⁠ʻal-mwpʻţ׃"],[48,22,"וְ⁠עַל־דִּיב֣וֹן וְ⁠עַל־נְב֔וֹ וְ⁠עַל־בֵּ֖ית דִּבְלָתָֽיִם׃","wĕ⁠ʻal-di̇yb֣wòn wĕ⁠ʻal-nĕb֔wò wĕ⁠ʻal-bé֖̇yţ di̇bĕláţáֽyim׃"],[48,23,"וְ⁠עַ֧ל קִרְיָתַ֛יִם וְ⁠עַל־בֵּ֥ית גָּמ֖וּל וְ⁠עַל־בֵּ֥ית מְעֽוֹן׃","wĕ⁠ʻa֧l qirĕyáţa֛yim wĕ⁠ʻal-bé֥̇yţ gá̇m֖ẇl wĕ⁠ʻal-bé֥̇yţ mĕʻֽwòn׃"],[48,24,"וְ⁠עַל־קְרִיּ֖וֹת וְ⁠עַל־בָּצְרָ֑ה וְ⁠עַ֗ל כָּל־עָרֵי֙ אֶ֣רֶץ מוֹאָ֔ב הָ⁠רְחֹק֖וֹת וְ⁠הַ⁠קְּרֹבֽוֹת׃","wĕ⁠ʻal-qĕriẏ֖wòţ wĕ⁠ʻal-bá̇ẕĕrá֑h wĕ⁠ʻa֗l ká̇l-ʻáréy֙ ʼe֣reẕ mwòʼá֔b há⁠rĕẖòq֖wòţ wĕ⁠ha⁠qĕ̇ròbֽwòţ׃"],[48,25,"נִגְדְּעָה֙ קֶ֣רֶן מוֹאָ֔ב וּ⁠זְרֹע֖⁠וֹ נִשְׁבָּ֑רָה נְאֻ֖ם יְהוָֽה׃","nigĕdĕ̇ʻáh֙ qe֣ren mwòʼá֔b ẇ⁠zĕròʻ֖⁠wò nişĕ̌bá֑̇ráh nĕʼu֖m yĕhwáֽh׃"],[48,26,"הַשְׁכִּירֻ֕⁠הוּ כִּ֥י עַל־יְהוָ֖ה הִגְדִּ֑יל וְ⁠סָפַ֤ק מוֹאָב֙ בְּ⁠קִיא֔⁠וֹ וְ⁠הָיָ֥ה לִ⁠שְׂחֹ֖ק גַּם־הֽוּא׃","haşĕ̌ki̇yru֕⁠hẇ ki֥̇y ʻal-yĕhwá֖h higĕdi֑̇yl wĕ⁠sápa֤q mwòʼáb֙ bĕ̇⁠qiyʼ֔⁠wò wĕ⁠háyá֥h li⁠şĕ̂ẖò֖q gȧm-hֽẇʼ׃"],[48,27,"וְ⁠אִ֣ם ׀ ל֣וֹא הַ⁠שְּׂחֹ֗ק הָיָ֤ה לְ⁠ךָ֙ יִשְׂרָאֵ֔ל אִם־בְּ⁠גַנָּבִ֖ים נמצאה כִּֽי־מִ⁠דֵּ֧י דְבָרֶ֥י⁠ךָ בּ֖⁠וֹ תִּתְנוֹדָֽד׃","wĕ⁠ʼi֣m ׀ l֣wòʼ ha⁠şĕ̇̂ẖò֗q háyá֤h lĕ⁠ká֙ yişĕ̂ráʼé֔l ʼim-bĕ̇⁠ganá̇bi֖ym nmẕʼh kiֽ̇y-mi⁠dé֧̇y dĕbáre֥y⁠ká ḃ֖⁠wò ţi̇ţĕnwòdáֽd׃"],[48,28,"עִזְב֤וּ עָרִים֙ וְ⁠שִׁכְנ֣וּ בַּ⁠סֶּ֔לַע יֹשְׁבֵ֖י מוֹאָ֑ב וִֽ⁠הְי֣וּ כְ⁠יוֹנָ֔ה תְּקַנֵּ֖ן בְּ⁠עֶבְרֵ֥י פִי־פָֽחַת׃","ʻizĕb֤ẇ ʻáriym֙ wĕ⁠şǐkĕn֣ẇ bȧ⁠sė֔laʻ yòşĕ̌bé֖y mwòʼá֑b wiֽ⁠hĕy֣ẇ kĕ⁠ywòná֔h ţĕ̇qané֖̇n bĕ̇⁠ʻebĕré֥y piy-páֽẖaţ׃"],[48,29,"שָׁמַ֥עְנוּ גְאוֹן־מוֹאָ֖ב גֵּאֶ֣ה מְאֹ֑ד גָּבְה֧⁠וֹ וּ⁠גְאוֹנ֛⁠וֹ וְ⁠גַאֲוָת֖⁠וֹ וְ⁠רֻ֥ם לִבּֽ⁠וֹ׃","şá̌ma֥ʻĕnẇ gĕʼwòn-mwòʼá֖b gé̇ʼe֣h mĕʼò֑d gá̇bĕh֧⁠wò ẇ⁠gĕʼwòn֛⁠wò wĕ⁠gaʼàwáţ֖⁠wò wĕ⁠ru֥m liḃֽ⁠wò׃"],[48,30,"אֲנִ֤י יָדַ֨עְתִּי֙ נְאֻם־יְהוָ֔ה עֶבְרָת֖⁠וֹ וְ⁠לֹא־כֵ֑ן בַּדָּ֖י⁠ו לֹא־כֵ֥ן עָשֽׂוּ׃","ʼàni֤y yáda֨ʻĕţi̇y֙ nĕʼum-yĕhwá֔h ʻebĕráţ֖⁠wò wĕ⁠lòʼ-ké֑n bȧdá֖̇y⁠w lòʼ-ké֥n ʻáşֽ̂ẇ׃"],[48,31,"עַל־כֵּן֙ עַל־מוֹאָ֣ב אֲיֵלִ֔יל וּ⁠לְ⁠מוֹאָ֥ב כֻּלֹּ֖⁠ה אֶזְעָ֑ק אֶל־אַנְשֵׁ֥י קִֽיר־חֶ֖רֶשׂ יֶהְגֶּֽה׃","ʻal-ké̇n֙ ʻal-mwòʼá֣b ʼàyéli֔yl ẇ⁠lĕ⁠mwòʼá֥b ku̇lò֖̇⁠h ʼezĕʻá֑q ʼel-ʼanĕşé֥̌y qiֽyr-ẖe֖reş̂ yehĕgėֽh׃"],[48,32,"מִ⁠בְּכִ֨י יַעְזֵ֤ר אֶבְכֶּה־לָּ⁠ךְ֙ הַ⁠גֶּ֣פֶן שִׂבְמָ֔ה נְטִֽישֹׁתַ֨יִ⁠ךְ֙ עָ֣בְרוּ יָ֔ם עַ֛ד יָ֥ם יַעְזֵ֖ר נָגָ֑עוּ עַל־קֵיצֵ֥⁠ךְ וְ⁠עַל־בְּצִירֵ֖⁠ךְ שֹׁדֵ֥ד נָפָֽל׃","mi⁠bĕ̇ki֨y yaʻĕzé֤r ʼebĕkėh-lá̇⁠kĕ֙ ha⁠gė֣pen şîbĕmá֔h nĕtiֽyşò̌ţa֨yi⁠kĕ֙ ʻá֣bĕrẇ yá֔m ʻa֛d yá֥m yaʻĕzé֖r nágá֑ʻẇ ʻal-qéyẕé֥⁠kĕ wĕ⁠ʻal-bĕ̇ẕiyré֖⁠kĕ şò̌dé֥d nápáֽl׃"],[48,33,"וְ⁠נֶאֶסְפָ֨ה שִׂמְחָ֥ה וָ⁠גִ֛יל מִ⁠כַּרְמֶ֖ל וּ⁠מֵ⁠אֶ֣רֶץ מוֹאָ֑ב וְ⁠יַ֨יִן֙ מִ⁠יקָבִ֣ים הִשְׁבַּ֔תִּי לֹֽא־יִדְרֹ֣ךְ הֵידָ֔ד הֵידָ֖ד לֹ֥א הֵידָֽד׃","wĕ⁠neʼesĕpá֨h şîmĕẖá֥h wá⁠gi֛yl mi⁠kȧrĕme֖l ẇ⁠mé⁠ʼe֣reẕ mwòʼá֑b wĕ⁠ya֨yin֙ mi⁠yqábi֣ym hişĕ̌bȧ֔ţi̇y lòֽʼ-yidĕrò֣kĕ héydá֔d héydá֖d lò֥ʼ héydáֽd׃"],[48,34,"מִ⁠זַּעֲקַ֨ת חֶשְׁבּ֜וֹן עַד־אֶלְעָלֵ֗ה עַד־יַ֨הַץ֙ נָתְנ֣וּ קוֹלָ֔⁠ם מִ⁠צֹּ֨עַר֙ עַד־חֹ֣רֹנַ֔יִם עֶגְלַ֖ת שְׁלִֽשִׁיָּ֑ה כִּ֚י גַּם־מֵ֣י נִמְרִ֔ים לִ⁠מְשַׁמּ֖וֹת יִהְיֽוּ׃","mi⁠zȧʻàqa֨ţ ẖeşĕ̌ḃ֜wòn ʻad-ʼelĕʻálé֗h ʻad-ya֨haẕ֙ náţĕn֣ẇ qwòlá֔⁠m mi⁠ẕò̇֨ʻar֙ ʻad-ẖò֣ròna֔yim ʻegĕla֖ţ şĕ̌liֽşǐyá֑̇h ki֚̇y gȧm-mé֣y nimĕri֔ym li⁠mĕşǎṁ֖wòţ yihĕyֽẇ׃"],[48,35,"וְ⁠הִשְׁבַּתִּ֥י לְ⁠מוֹאָ֖ב נְאֻם־יְהוָ֑ה מַעֲלֶ֣ה בָמָ֔ה וּ⁠מַקְטִ֖יר לֵ⁠אלֹהָֽי⁠ו׃","wĕ⁠hişĕ̌bȧţi֥̇y lĕ⁠mwòʼá֖b nĕʼum-yĕhwá֑h maʻàle֣h bámá֔h ẇ⁠maqĕti֖yr lé⁠ʼlòháֽy⁠w׃"],[48,36,"עַל־כֵּ֞ן לִבִּ֤⁠י לְ⁠מוֹאָב֙ כַּ⁠חֲלִלִ֣ים יֶהֱמֶ֔ה וְ⁠לִבִּ⁠י֙ אֶל־אַנְשֵׁ֣י קִֽיר־חֶ֔רֶשׂ כַּ⁠חֲלִילִ֖ים יֶהֱמֶ֑ה עַל־כֵּ֛ן יִתְרַ֥ת עָשָׂ֖ה אָבָֽדוּ׃","ʻal-ké̇֞n libi֤̇⁠y lĕ⁠mwòʼáb֙ kȧ⁠ẖàlili֣ym yehème֔h wĕ⁠libi̇⁠y֙ ʼel-ʼanĕşé֣̌y qiֽyr-ẖe֔reş̂ kȧ⁠ẖàliyli֖ym yehème֑h ʻal-ké֛̇n yiţĕra֥ţ ʻáşá֖̂h ʼábáֽdẇ׃"],[48,37,"כִּ֤י כָל־רֹאשׁ֙ קָרְחָ֔ה וְ⁠כָל־זָקָ֖ן גְּרֻעָ֑ה עַ֤ל כָּל־יָדַ֨יִם֙ גְּדֻדֹ֔ת וְ⁠עַל־מָתְנַ֖יִם שָֽׂק׃","ki֤̇y kál-ròʼş̌֙ qárĕẖá֔h wĕ⁠kál-záqá֖n gĕ̇ruʻá֑h ʻa֤l ká̇l-yáda֨yim֙ gĕ̇dudò֔ţ wĕ⁠ʻal-máţĕna֖yim şáֽ̂q׃"],[48,38,"עַ֣ל כָּל־גַּגּ֥וֹת מוֹאָ֛ב וּ⁠בִ⁠רְחֹבֹתֶ֖י⁠הָ כֻּלֹּ֣⁠ה מִסְפֵּ֑ד כִּֽי־שָׁבַ֣רְתִּי אֶת־מוֹאָ֗ב כִּ⁠כְלִ֛י אֵֽין־חֵ֥פֶץ בּ֖⁠וֹ נְאֻם־יְהוָֽה׃","ʻa֣l ká̇l-gȧġ֥wòţ mwòʼá֛b ẇ⁠bi⁠rĕẖòbòţe֖y⁠há ku̇lò֣̇⁠h misĕpé֑̇d kiֽ̇y-şá̌ba֣rĕţi̇y ʼeţ-mwòʼá֗b ki̇⁠kĕli֛y ʼéֽyn-ẖé֥peẕ ḃ֖⁠wò nĕʼum-yĕhwáֽh׃"],[48,39,"אֵ֥יךְ חַ֨תָּה֙ הֵילִ֔ילוּ אֵ֛יךְ הִפְנָה־עֹ֥רֶף מוֹאָ֖ב בּ֑וֹשׁ וְ⁠הָיָ֥ה מוֹאָ֛ב לִ⁠שְׂחֹ֥ק וְ⁠לִ⁠מְחִתָּ֖ה לְ⁠כָל־סְבִיבָֽי⁠ו׃ס","ʼé֥ykĕ ẖa֨ţá̇h֙ héyli֔ylẇ ʼé֛ykĕ hipĕnáh-ʻò֥rep mwòʼá֖b ḃ֑wòş̌ wĕ⁠háyá֥h mwòʼá֛b li⁠şĕ̂ẖò֥q wĕ⁠li⁠mĕẖiţá֖̇h lĕ⁠kál-sĕbiybáֽy⁠w׃s"],[48,40,"כִּי־כֹה֙ אָמַ֣ר יְהוָ֔ה הִנֵּ֥ה כַ⁠נֶּ֖שֶׁר יִדְאֶ֑ה וּ⁠פָרַ֥שׂ כְּנָפָ֖י⁠ו אֶל־מוֹאָֽב׃","ki̇y-kòh֙ ʼáma֣r yĕhwá֔h hiné֥̇h ka⁠nė֖şěr yidĕʼe֑h ẇ⁠pára֥ş̂ kĕ̇nápá֖y⁠w ʼel-mwòʼáֽb׃"],[48,41,"נִלְכְּדָה֙ הַ⁠קְּרִיּ֔וֹת וְ⁠הַ⁠מְּצָד֖וֹת נִתְפָּ֑שָׂה וְֽ֠⁠הָיָה לֵ֞ב גִּבּוֹרֵ֤י מוֹאָב֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא כְּ⁠לֵ֖ב אִשָּׁ֥ה מְצֵרָֽה׃","nilĕkĕ̇dáh֙ ha⁠qĕ̇riẏ֔wòţ wĕ⁠ha⁠mĕ̇ẕád֖wòţ niţĕpá֑̇şá̂h wĕֽ֠⁠háyáh lé֞b gi̇ḃwòré֤y mwòʼáb֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ kĕ̇⁠lé֖b ʼişá֥̇̌h mĕẕéráֽh׃"],[48,42,"וְ⁠נִשְׁמַ֥ד מוֹאָ֖ב מֵ⁠עָ֑ם כִּ֥י עַל־יְהוָ֖ה הִגְדִּֽיל׃","wĕ⁠nişĕ̌ma֥d mwòʼá֖b mé⁠ʻá֑m ki֥̇y ʻal-yĕhwá֖h higĕdiֽ̇yl׃"],[48,43,"פַּ֥חַד וָ⁠פַ֖חַת וָ⁠פָ֑ח עָלֶ֛י⁠ךָ יוֹשֵׁ֥ב מוֹאָ֖ב נְאֻם־יְהוָֽה׃","pȧ֥ẖad wá⁠pa֖ẖaţ wá⁠pá֑ẖ ʻále֛y⁠ká ywòşé֥̌b mwòʼá֖b nĕʼum-yĕhwáֽh׃"],[48,44,"ה⁠ניס מִ⁠פְּנֵ֤י הַ⁠פַּ֨חַד֙ יִפֹּ֣ל אֶל־הַ⁠פַּ֔חַת וְ⁠הָֽ⁠עֹלֶה֙ מִן־הַ⁠פַּ֔חַת יִלָּכֵ֖ד בַּ⁠פָּ֑ח כִּֽי־אָבִ֨יא אֵלֶ֧י⁠הָ אֶל־מוֹאָ֛ב שְׁנַ֥ת פְּקֻדָּתָ֖⁠ם נְאֻם־יְהוָֽה׃","h⁠nys mi⁠pĕ̇né֤y ha⁠pȧ֨ẖad֙ yipò֣̇l ʼel-ha⁠pȧ֔ẖaţ wĕ⁠háֽ⁠ʻòleh֙ min-ha⁠pȧ֔ẖaţ yilá̇ké֖d bȧ⁠pá֑̇ẖ kiֽ̇y-ʼábi֨yʼ ʼéle֧y⁠há ʼel-mwòʼá֛b şĕ̌na֥ţ pĕ̇qudá̇ţá֖⁠m nĕʼum-yĕhwáֽh׃"],[48,45,"בְּ⁠צֵ֥ל חֶשְׁבּ֛וֹן עָמְד֖וּ מִ⁠כֹּ֣חַ נָסִ֑ים כִּֽי־אֵ֞שׁ יָצָ֣א מֵ⁠חֶשְׁבּ֗וֹן וְ⁠לֶֽהָבָה֙ מִ⁠בֵּ֣ין סִיח֔וֹן וַ⁠תֹּ֨אכַל֙ פְּאַ֣ת מוֹאָ֔ב וְ⁠קָדְקֹ֖ד בְּנֵ֥י שָׁאֽוֹן׃","bĕ̇⁠ẕé֥l ẖeşĕ̌ḃ֛wòn ʻámĕd֖ẇ mi⁠kò֣̇ẖa nási֑ym kiֽ̇y-ʼé֞ş̌ yáẕá֣ʼ mé⁠ẖeşĕ̌ḃ֗wòn wĕ⁠leֽhábáh֙ mi⁠bé֣̇yn siyẖ֔wòn wa⁠ţò̇֨ʼkal֙ pĕ̇ʼa֣ţ mwòʼá֔b wĕ⁠qádĕqò֖d bĕ̇né֥y şá̌ʼֽwòn׃"],[48,46,"אוֹי־לְ⁠ךָ֣ מוֹאָ֔ב אָבַ֖ד עַם־כְּמ֑וֹשׁ כִּֽי־לֻקְּח֤וּ בָנֶ֨י⁠ךָ֙ בַּ⁠שֶּׁ֔בִי וּ⁠בְנֹתֶ֖י⁠ךָ בַּ⁠שִּׁבְיָֽה׃","ʼwòy-lĕ⁠ká֣ mwòʼá֔b ʼába֖d ʻam-kĕ̇m֑wòş̌ kiֽ̇y-luqĕ̇ẖ֤ẇ báne֨y⁠ká֙ bȧ⁠şė̌֔biy ẇ⁠bĕnòţe֖y⁠ká bȧ⁠şi̇̌bĕyáֽh׃"],[48,47,"וְ⁠שַׁבְתִּ֧י שְׁבוּת־מוֹאָ֛ב בְּ⁠אַחֲרִ֥ית הַ⁠יָּמִ֖ים נְאֻם־יְהוָ֑ה עַד־הֵ֖נָּה מִשְׁפַּ֥ט מוֹאָֽב׃ס","wĕ⁠şǎbĕţi֧̇y şĕ̌bẇţ-mwòʼá֛b bĕ̇⁠ʼaẖàri֥yţ ha⁠yá̇mi֖ym nĕʼum-yĕhwá֑h ʻad-hé֖ná̇h mişĕ̌pȧ֥t mwòʼáֽb׃s"],[49,1,"לִ⁠בְנֵ֣י עַמּ֗וֹן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הֲ⁠בָנִ֥ים אֵין֙ לְ⁠יִשְׂרָאֵ֔ל אִם־יוֹרֵ֖שׁ אֵ֣ין ל֑⁠וֹ מַדּ֗וּעַ יָרַ֤שׁ מַלְכָּ⁠ם֙ אֶת־גָּ֔ד וְ⁠עַמּ֖⁠וֹ בְּ⁠עָרָ֥י⁠ו יָשָֽׁב׃","li⁠bĕné֣y ʻaṁ֗wòn kò֚̇h ʼáma֣r yĕhwá֔h hà⁠báni֥ym ʼéyn֙ lĕ⁠yişĕ̂ráʼé֔l ʼim-ywòré֖ş̌ ʼé֣yn l֑⁠wò maḋ֗ẇʻa yára֤ş̌ malĕká̇⁠m֙ ʼeţ-gá̇֔d wĕ⁠ʻaṁ֖⁠wò bĕ̇⁠ʻárá֥y⁠w yáşáֽ̌b׃"],[49,2,"לָ⁠כֵ֡ן הִנֵּה֩ יָמִ֨ים בָּאִ֜ים נְאֻם־יְהוָ֗ה וְ֠⁠הִשְׁמַעְתִּי אֶל־רַבַּ֨ת בְּנֵי־עַמּ֜וֹן תְּרוּעַ֣ת מִלְחָמָ֗ה וְ⁠הָֽיְתָה֙ לְ⁠תֵ֣ל שְׁמָמָ֔ה וּ⁠בְנֹתֶ֖י⁠הָ בָּ⁠אֵ֣שׁ תִּצַּ֑תְנָה וְ⁠יָרַ֧שׁ יִשְׂרָאֵ֛ל אֶת־יֹרְשָׁ֖י⁠ו אָמַ֥ר יְהוָֽה׃","lá⁠ké֡n hiné̇h֩ yámi֨ym bá̇ʼi֜ym nĕʼum-yĕhwá֗h wĕ֠⁠hişĕ̌maʻĕţi̇y ʼel-rabȧ֨ţ bĕ̇néy-ʻaṁ֜wòn ţĕ̇rẇʻa֣ţ milĕẖámá֗h wĕ⁠háֽyĕţáh֙ lĕ⁠ţé֣l şĕ̌mámá֔h ẇ⁠bĕnòţe֖y⁠há bá̇⁠ʼé֣ş̌ ţi̇ẕȧ֑ţĕnáh wĕ⁠yára֧ş̌ yişĕ̂ráʼé֛l ʼeţ-yòrĕşá֖̌y⁠w ʼáma֥r yĕhwáֽh׃"],[49,3,"הֵילִ֨ילִי חֶשְׁבּ֜וֹן כִּ֣י שֻׁדְּדָה־עַ֗י צְעַקְנָה֮ בְּנ֣וֹת רַבָּה֒ חֲגֹ֣רְנָה שַׂקִּ֔ים סְפֹ֕דְנָה וְ⁠הִתְשׁוֹטַ֖טְנָה בַּ⁠גְּדֵר֑וֹת כִּ֤י מַלְכָּ⁠ם֙ בַּ⁠גּוֹלָ֣ה יֵלֵ֔ךְ כֹּהֲנָ֥י⁠ו וְ⁠שָׂרָ֖י⁠ו יַחְדָּֽיו׃","héyli֨yliy ẖeşĕ̌ḃ֜wòn ki֣̇y şǔdĕ̇dáh-ʻa֗y ẕĕʻaqĕnáh֮ bĕ̇n֣wòţ rabá̇h֒ ẖàgò֣rĕnáh şâqi̇֔ym sĕpò֕dĕnáh wĕ⁠hiţĕş̌wòta֖tĕnáh bȧ⁠gĕ̇dér֑wòţ ki֤̇y malĕká̇⁠m֙ bȧ⁠ġwòlá֣h yélé֔kĕ kò̇hàná֥y⁠w wĕ⁠şá̂rá֖y⁠w yaẖĕdáֽ̇yw׃"],[49,4,"מַה־תִּתְהַֽלְלִי֙ בָּֽ⁠עֲמָקִ֔ים זָ֣ב עִמְקֵ֔⁠ךְ הַ⁠בַּ֖ת הַ⁠שּֽׁוֹבֵבָ֑ה הַ⁠בֹּֽטְחָה֙ בְּ⁠אֹ֣צְרֹתֶ֔י⁠הָ מִ֖י יָב֥וֹא אֵלָֽ⁠י׃","mah-ţi̇ţĕhaֽlĕliy֙ báֽ̇⁠ʻàmáqi֔ym zá֣b ʻimĕqé֔⁠kĕ ha⁠bȧ֖ţ ha⁠şֽ̇̌wòbébá֑h ha⁠bòֽ̇tĕẖáh֙ bĕ̇⁠ʼò֣ẕĕròţe֔y⁠há mi֖y yáb֥wòʼ ʼéláֽ⁠y׃"],[49,5,"הִנְ⁠נִי֩ מֵבִ֨יא עָלַ֜יִ⁠ךְ פַּ֗חַד נְאֻם־אֲדֹנָ֧⁠י יְהוִ֛ה צְבָא֖וֹת מִ⁠כָּל־סְבִיבָ֑יִ⁠ךְ וְ⁠נִדַּחְתֶּם֙ אִ֣ישׁ לְ⁠פָנָ֔י⁠ו וְ⁠אֵ֥ין מְקַבֵּ֖ץ לַ⁠נֹּדֵֽד׃","hinĕ⁠niy֩ mébi֨yʼ ʻála֜yi⁠kĕ pȧ֗ẖad nĕʼum-ʼàdòná֧⁠y yĕhwi֛h ẕĕbáʼ֖wòţ mi⁠ká̇l-sĕbiybá֑yi⁠kĕ wĕ⁠nidȧẖĕţėm֙ ʼi֣yş̌ lĕ⁠páná֔y⁠w wĕ⁠ʼé֥yn mĕqabé֖̇ẕ la⁠nò̇déֽd׃"],[49,6,"וְ⁠אַחֲרֵי־כֵ֗ן אָשִׁ֛יב אֶת־שְׁב֥וּת בְּנֵֽי־עַמּ֖וֹן נְאֻם־יְהוָֽה׃ס","wĕ⁠ʼaẖàréy-ké֗n ʼáşǐ֛yb ʼeţ-şĕ̌b֥ẇţ bĕ̇néֽy-ʻaṁ֖wòn nĕʼum-yĕhwáֽh׃s"],[49,7,"לֶ⁠אֱד֗וֹם כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הַ⁠אֵ֥ין ע֛וֹד חָכְמָ֖ה בְּ⁠תֵימָ֑ן אָבְדָ֤ה עֵצָה֙ מִ⁠בָּנִ֔ים נִסְרְחָ֖ה חָכְמָתָֽ⁠ם׃","le⁠ʼèd֗wòm kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ha⁠ʼé֥yn ʻ֛wòd ẖákĕmá֖h bĕ̇⁠ţéymá֑n ʼábĕdá֤h ʻéẕáh֙ mi⁠bá̇ni֔ym nisĕrĕẖá֖h ẖákĕmáţáֽ⁠m׃"],[49,8,"נֻ֤סוּ הָפְנוּ֙ הֶעְמִ֣יקוּ לָ⁠שֶׁ֔בֶת יֹשְׁבֵ֖י דְּדָ֑ן כִּ֣י אֵ֥יד עֵשָׂ֛ו הֵבֵ֥אתִי עָלָ֖י⁠ו עֵ֥ת פְּקַדְתִּֽי⁠ו׃","nu֤sẇ hápĕnẇ֙ heʻĕmi֣yqẇ lá⁠şě֔beţ yòşĕ̌bé֖y dĕ̇dá֑n ki֣̇y ʼé֥yd ʻéşá֛̂w hébé֥ʼţiy ʻálá֖y⁠w ʻé֥ţ pĕ̇qadĕţiֽ̇y⁠w׃"],[49,9,"אִם־בֹּֽצְרִים֙ בָּ֣אוּ לָ֔⁠ךְ לֹ֥א יַשְׁאִ֖רוּ עֽוֹלֵל֑וֹת אִם־גַּנָּבִ֥ים בַּ⁠לַּ֖יְלָה הִשְׁחִ֥יתוּ דַיָּֽ⁠ם׃","ʼim-bòֽ̇ẕĕriym֙ bá֣̇ʼẇ lá֔⁠kĕ lò֥ʼ yaşĕ̌ʼi֖rẇ ʻֽwòlél֑wòţ ʼim-gȧná̇bi֥ym bȧ⁠lȧ֖yĕláh hişĕ̌ẖi֥yţẇ dayáֽ̇⁠m׃"],[49,10,"כִּֽי־אֲנִ֞י חָשַׂ֣פְתִּי אֶת־עֵשָׂ֗ו גִּלֵּ֨יתִי֙ אֶת־מִסְתָּרָ֔י⁠ו וְ⁠נֶחְבָּ֖ה לֹ֣א יוּכָ֑ל שֻׁדַּ֥ד זַרְע֛⁠וֹ וְ⁠אֶחָ֥י⁠ו וּ⁠שְׁכֵנָ֖י⁠ו וְ⁠אֵינֶֽ⁠נּוּ׃","kiֽ̇y-ʼàni֞y ẖáşâ֣pĕţi̇y ʼeţ-ʻéşá̂֗w gi̇lé̇֨yţiy֙ ʼeţ-misĕţá̇rá֔y⁠w wĕ⁠neẖĕbá֖̇h lò֣ʼ yẇká֑l şǔdȧ֥d zarĕʻ֛⁠wò wĕ⁠ʼeẖá֥y⁠w ẇ⁠şĕ̌kéná֖y⁠w wĕ⁠ʼéyneֽ⁠ṅẇ׃"],[49,11,"עָזְבָ֥⁠ה יְתֹמֶ֖י⁠ךָ אֲנִ֣י אֲחַיֶּ֑ה וְ⁠אַלְמְנֹתֶ֖י⁠ךָ עָלַ֥⁠י תִּבְטָֽחוּ׃ס","ʻázĕbá֥⁠h yĕţòme֖y⁠ká ʼàni֣y ʼàẖayė֑h wĕ⁠ʼalĕmĕnòţe֖y⁠ká ʻála֥⁠y ţi̇bĕtáֽẖẇ׃s"],[49,12,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה הִ֠נֵּה אֲשֶׁר־אֵ֨ין מִשְׁפָּטָ֜⁠ם לִ⁠שְׁתּ֤וֹת הַ⁠כּוֹס֙ שָׁת֣וֹ יִשְׁתּ֔וּ וְ⁠אַתָּ֣ה ה֔וּא נָקֹ֖ה תִּנָּקֶ֑ה לֹ֣א תִנָּקֶ֔ה כִּ֥י שָׁתֹ֖ה תִּשְׁתֶּֽה׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h hi֠né̇h ʼàşěr-ʼé֨yn mişĕ̌pá̇tá֜⁠m li⁠şĕ̌ţ֤̇wòţ ha⁠k̇wòs֙ şá̌ţ֣wò yişĕ̌ţ̇֔ẇ wĕ⁠ʼaţá֣̇h h֔ẇʼ náqò֖h ţi̇ná̇qe֑h lò֣ʼ ţiná̇qe֔h ki֥̇y şá̌ţò֖h ţi̇şĕ̌ţėֽh׃"],[49,13,"כִּ֣י בִ֤⁠י נִשְׁבַּ֨עְתִּי֙ נְאֻם־יְהוָ֔ה כִּֽי־לְ⁠שַׁמָּ֧ה לְ⁠חֶרְפָּ֛ה לְ⁠חֹ֥רֶב וְ⁠לִ⁠קְלָלָ֖ה תִּֽהְיֶ֣ה בָצְרָ֑ה וְ⁠כָל־עָרֶ֥י⁠הָ תִהְיֶ֖ינָה לְ⁠חָרְב֥וֹת עוֹלָֽם׃","ki֣̇y bi֤⁠y nişĕ̌bȧ֨ʻĕţi̇y֙ nĕʼum-yĕhwá֔h kiֽ̇y-lĕ⁠şǎmá֧̇h lĕ⁠ẖerĕpá֛̇h lĕ⁠ẖò֥reb wĕ⁠li⁠qĕlálá֖h ţiֽ̇hĕye֣h báẕĕrá֑h wĕ⁠kál-ʻáre֥y⁠há ţihĕye֖ynáh lĕ⁠ẖárĕb֥wòţ ʻwòláֽm׃"],[49,14,"שְׁמוּעָ֤ה שָׁמַ֨עְתִּי֙ מֵ⁠אֵ֣ת יְהוָ֔ה וְ⁠צִ֖יר בַּ⁠גּוֹיִ֣ם שָׁל֑וּחַ הִֽתְקַבְּצוּ֙ וּ⁠בֹ֣אוּ עָלֶ֔י⁠הָ וְ⁠ק֖וּמוּ לַ⁠מִּלְחָמָֽה׃","şĕ̌mẇʻá֤h şá̌ma֨ʻĕţi̇y֙ mé⁠ʼé֣ţ yĕhwá֔h wĕ⁠ẕi֖yr bȧ⁠ġwòyi֣m şá̌l֑ẇẖa hiֽţĕqabĕ̇ẕẇ֙ ẇ⁠bò֣ʼẇ ʻále֔y⁠há wĕ⁠q֖ẇmẇ la⁠mi̇lĕẖámáֽh׃"],[49,15,"כִּֽי־הִנֵּ֥ה קָטֹ֛ן נְתַתִּ֖י⁠ךָ בַּ⁠גּוֹיִ֑ם בָּז֖וּי בָּ⁠אָדָֽם׃","kiֽ̇y-hiné֥̇h qátò֛n nĕţaţi֖̇y⁠ká bȧ⁠ġwòyi֑m bá̇z֖ẇy bá̇⁠ʼádáֽm׃"],[49,16,"תִּֽפְלַצְתְּ⁠ךָ֞ הִשִּׁ֤יא אֹתָ⁠ךְ֙ זְד֣וֹן לִבֶּ֔⁠ךָ שֹֽׁכְנִי֙ בְּ⁠חַגְוֵ֣י הַ⁠סֶּ֔לַע תֹּפְשִׂ֖י מְר֣וֹם גִּבְעָ֑ה כִּֽי־תַגְבִּ֤יהַ כַּ⁠נֶּ֨שֶׁר֙ קִנֶּ֔⁠ךָ מִ⁠שָּׁ֥ם אֽוֹרִידְ⁠ךָ֖ נְאֻם־יְהוָֽה׃","ţiֽ̇pĕlaẕĕţĕ̇⁠ká֞ hişi֤̇̌yʼ ʼòţá⁠kĕ֙ zĕd֣wòn libė֔⁠ká şòֽ̌kĕniy֙ bĕ̇⁠ẖagĕwé֣y ha⁠sė֔laʻ ţò̇pĕşî֖y mĕr֣wòm gi̇bĕʻá֑h kiֽ̇y-ţagĕbi֤̇yha kȧ⁠nė֨şěr֙ qinė֔⁠ká mi⁠şá֥̇̌m ʼֽwòriydĕ⁠ká֖ nĕʼum-yĕhwáֽh׃"],[49,17,"וְ⁠הָיְתָ֥ה אֱד֖וֹם לְ⁠שַׁמָּ֑ה כֹּ֚ל עֹבֵ֣ר עָלֶ֔י⁠הָ יִשֹּׁ֥ם וְ⁠יִשְׁרֹ֖ק עַל־כָּל־מַכּוֹתֶֽ⁠הָ׃","wĕ⁠háyĕţá֥h ʼèd֖wòm lĕ⁠şǎmá֑̇h kò֚̇l ʻòbé֣r ʻále֔y⁠há yişò֥̇̌m wĕ⁠yişĕ̌rò֖q ʻal-ká̇l-mak̇wòţeֽ⁠há׃"],[49,18,"כְּֽ⁠מַהְפֵּכַ֞ת סְדֹ֧ם וַ⁠עֲמֹרָ֛ה וּ⁠שְׁכֵנֶ֖י⁠הָ אָמַ֣ר יְהוָ֑ה לֹֽא־יֵשֵׁ֥ב שָׁם֙ אִ֔ישׁ וְ⁠לֹֽא־יָג֥וּר בָּ֖⁠הּ בֶּן־אָדָֽם׃","kĕֽ̇⁠mahĕpé̇ka֞ţ sĕdò֧m wa⁠ʻàmòrá֛h ẇ⁠şĕ̌kéne֖y⁠há ʼáma֣r yĕhwá֑h lòֽʼ-yéşé֥̌b şá̌m֙ ʼi֔yş̌ wĕ⁠lòֽʼ-yág֥ẇr bá֖̇⁠ḣ bėn-ʼádáֽm׃"],[49,19,"הִ֠נֵּה כְּ⁠אַרְיֵ֞ה יַעֲלֶ֨ה מִ⁠גְּא֣וֹן הַ⁠יַּרְדֵּן֮ אֶל־נְוֵ֣ה אֵיתָן֒ כִּֽי־אַרְגִּ֤יעָה אֲרִיצֶ֨⁠נּוּ מֵֽ⁠עָלֶ֔י⁠הָ וּ⁠מִ֥י בָח֖וּר אֵלֶ֣י⁠הָ אֶפְקֹ֑ד כִּ֣י מִ֤י כָמ֨וֹ⁠נִי֙ וּ⁠מִ֣י יֹעִידֶ֔⁠נִּי וּ⁠מִי־זֶ֣ה רֹעֶ֔ה אֲשֶׁ֥ר יַעֲמֹ֖ד לְ⁠פָנָֽ⁠י׃ס","hi֠né̇h kĕ̇⁠ʼarĕyé֞h yaʻàle֨h mi⁠gĕ̇ʼ֣wòn ha⁠yȧrĕdé̇n֮ ʼel-nĕwé֣h ʼéyţán֒ kiֽ̇y-ʼarĕgi֤̇yʻáh ʼàriyẕe֨⁠ṅẇ méֽ⁠ʻále֔y⁠há ẇ⁠mi֥y báẖ֖ẇr ʼéle֣y⁠há ʼepĕqò֑d ki֣̇y mi֤y kám֨wò⁠niy֙ ẇ⁠mi֣y yòʻiyde֔⁠ni̇y ẇ⁠miy-ze֣h ròʻe֔h ʼàşě֥r yaʻàmò֖d lĕ⁠pánáֽ⁠y׃s"],[49,20,"לָ⁠כֵ֞ן שִׁמְע֣וּ עֲצַת־יְהוָ֗ה אֲשֶׁ֤ר יָעַץ֙ אֶל־אֱד֔וֹם וּ⁠מַ֨חְשְׁבוֹתָ֔י⁠ו אֲשֶׁ֥ר חָשַׁ֖ב אֶל־יֹשְׁבֵ֣י תֵימָ֑ן אִם־לֹ֤א יִסְחָבוּ⁠ם֙ צְעִירֵ֣י הַ⁠צֹּ֔אן אִם־לֹ֥א יַשִּׁ֛ים עֲלֵי⁠הֶ֖ם נְוֵ⁠הֶֽם׃","lá⁠ké֞n şǐmĕʻ֣ẇ ʻàẕaţ-yĕhwá֗h ʼàşě֤r yáʻaẕ֙ ʼel-ʼèd֔wòm ẇ⁠ma֨ẖĕşĕ̌bwòţá֔y⁠w ʼàşě֥r ẖáşǎ֖b ʼel-yòşĕ̌bé֣y ţéymá֑n ʼim-lò֤ʼ yisĕẖábẇ⁠m֙ ẕĕʻiyré֣y ha⁠ẕò̇֔ʼn ʼim-lò֥ʼ yaşi֛̇̌ym ʻàléy⁠he֖m nĕwé⁠heֽm׃"],[49,21,"מִ⁠קּ֣וֹל נִפְלָ֔⁠ם רָעֲשָׁ֖ה הָ⁠אָ֑רֶץ צְעָקָ֕ה בְּ⁠יַם־ס֖וּף נִשְׁמַ֥ע קוֹלָֽ⁠הּ׃","mi⁠q֣̇wòl nipĕlá֔⁠m ráʻàşá֖̌h há⁠ʼá֑reẕ ẕĕʻáqá֕h bĕ̇⁠yam-s֖ẇp nişĕ̌ma֥ʻ qwòláֽ⁠ḣ׃"],[49,22,"הִנֵּ֤ה כַ⁠נֶּ֨שֶׁר֙ יַעֲלֶ֣ה וְ⁠יִדְאֶ֔ה וְ⁠יִפְרֹ֥שׂ כְּנָפָ֖י⁠ו עַל־בָּצְרָ֑ה וְֽ֠⁠הָיָה לֵ֞ב גִּבּוֹרֵ֤י אֱדוֹם֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא כְּ⁠לֵ֖ב אִשָּׁ֥ה מְצֵרָֽה׃ס","hiné֤̇h ka⁠nė֨şěr֙ yaʻàle֣h wĕ⁠yidĕʼe֔h wĕ⁠yipĕrò֥ş̂ kĕ̇nápá֖y⁠w ʻal-bá̇ẕĕrá֑h wĕֽ֠⁠háyáh lé֞b gi̇ḃwòré֤y ʼèdwòm֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ kĕ̇⁠lé֖b ʼişá֥̇̌h mĕẕéráֽh׃s"],[49,23,"לְ⁠דַמֶּ֗שֶׂק בּ֤וֹשָֽׁה חֲמָת֙ וְ⁠אַרְפָּ֔ד כִּי־שְׁמֻעָ֥ה רָעָ֛ה שָׁמְע֖וּ נָמֹ֑גוּ בַּ⁠יָּ֣ם דְּאָגָ֔ה הַשְׁקֵ֖ט לֹ֥א יוּכָֽל׃","lĕ⁠damė֗şêq ḃ֤wòşáֽ̌h ẖàmáţ֙ wĕ⁠ʼarĕpá̇֔d ki̇y-şĕ̌muʻá֥h ráʻá֛h şá̌mĕʻ֖ẇ námò֑gẇ bȧ⁠yá֣̇m dĕ̇ʼágá֔h haşĕ̌qé֖t lò֥ʼ yẇkáֽl׃"],[49,24,"רָפְתָ֥ה דַמֶּ֛שֶׂק הִפְנְתָ֥ה לָ⁠נ֖וּס וְ⁠רֶ֣טֶט ׀ הֶחֱזִ֑יקָה צָרָ֧ה וַ⁠חֲבָלִ֛ים אֲחָזַ֖תָּ⁠ה כַּ⁠יּוֹלֵדָֽה׃","rápĕţá֥h damė֛şêq hipĕnĕţá֥h lá⁠n֖ẇs wĕ⁠re֣tet ׀ heẖèzi֑yqáh ẕárá֧h wa⁠ẖàbáli֛ym ʼàẖáza֖ţá̇⁠h kȧ⁠ẏwòlédáֽh׃"],[49,25,"אֵ֥יךְ לֹֽא־עֻזְּבָ֖ה עִ֣יר תהלה קִרְיַ֖ת מְשׂוֹשִֽׂ⁠י׃","ʼé֥ykĕ lòֽʼ-ʻuzĕ̇bá֖h ʻi֣yr ţhlh qirĕya֖ţ mĕş̂wòşîֽ⁠y׃"],[49,26,"לָ⁠כֵ֛ן יִפְּל֥וּ בַחוּרֶ֖י⁠הָ בִּ⁠רְחֹבֹתֶ֑י⁠הָ וְ⁠כָל־אַנְשֵׁ֨י הַ⁠מִּלְחָמָ֤ה יִדַּ֨מּוּ֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","lá⁠ké֛n yipĕ̇l֥ẇ baẖẇre֖y⁠há bi̇⁠rĕẖòbòţe֑y⁠há wĕ⁠kál-ʼanĕşé̌֨y ha⁠mi̇lĕẖámá֤h yidȧ֨ṁẇ֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[49,27,"וְ⁠הִצַּ֥תִּי אֵ֖שׁ בְּ⁠חוֹמַ֣ת דַּמָּ֑שֶׂק וְ⁠אָכְלָ֖ה אַרְמְנ֥וֹת בֶּן־הֲדָֽד׃ס","wĕ⁠hiẕȧ֥ţi̇y ʼé֖ş̌ bĕ̇⁠ẖwòma֣ţ dȧmá֑̇şêq wĕ⁠ʼákĕlá֖h ʼarĕmĕn֥wòţ bėn-hàdáֽd׃s"],[49,28,"לְ⁠קֵדָ֣ר ׀ וּֽ⁠לְ⁠מַמְלְכ֣וֹת חָצ֗וֹר אֲשֶׁ֤ר הִכָּה֙ נבוכדראצור מֶֽלֶךְ־בָּבֶ֔ל כֹּ֖ה אָמַ֣ר יְהוָ֑ה ק֚וּמוּ עֲל֣וּ אֶל־קֵדָ֔ר וְ⁠שָׁדְד֖וּ אֶת־בְּנֵי־קֶֽדֶם׃","lĕ⁠qédá֣r ׀ ẇֽ⁠lĕ⁠mamĕlĕk֣wòţ ẖáẕ֗wòr ʼàşě֤r hiká̇h֙ nbwkdrʼẕwr meֽlekĕ-bá̇be֔l kò֖̇h ʼáma֣r yĕhwá֑h q֚ẇmẇ ʻàl֣ẇ ʼel-qédá֔r wĕ⁠şá̌dĕd֖ẇ ʼeţ-bĕ̇néy-qeֽdem׃"],[49,29,"אָהֳלֵי⁠הֶ֤ם וְ⁠צֹאנָ⁠ם֙ יִקָּ֔חוּ יְרִיעוֹתֵי⁠הֶ֧ם וְ⁠כָל־כְּלֵי⁠הֶ֛ם וּ⁠גְמַלֵּי⁠הֶ֖ם יִשְׂא֣וּ לָ⁠הֶ֑ם וְ⁠קָרְא֧וּ עֲלֵי⁠הֶ֛ם מָג֖וֹר מִ⁠סָּבִֽיב׃","ʼáholéy⁠he֤m wĕ⁠ẕòʼná⁠m֙ yiqá̇֔ẖẇ yĕriyʻwòţéy⁠he֧m wĕ⁠kál-kĕ̇léy⁠he֛m ẇ⁠gĕmalé̇y⁠he֖m yişĕ̂ʼ֣ẇ lá⁠he֑m wĕ⁠qárĕʼ֧ẇ ʻàléy⁠he֛m mág֖wòr mi⁠sá̇biֽyb׃"],[49,30,"נֻסוּ֩ נֻּ֨דוּ מְאֹ֜ד הֶעְמִ֧יקוּ לָ⁠שֶׁ֛בֶת יֹשְׁבֵ֥י חָצ֖וֹר נְאֻם־יְהוָ֑ה כִּֽי־יָעַ֨ץ עֲלֵי⁠כֶ֜ם נְבוּכַדְרֶאצַּ֤ר מֶֽלֶךְ־בָּבֶל֙ עֵצָ֔ה וְ⁠חָשַׁ֥ב עלי⁠הם מַחֲשָׁבָֽה׃","nusẇ֩ nu̇֨dẇ mĕʼò֜d heʻĕmi֧yqẇ lá⁠şě֛beţ yòşĕ̌bé֥y ẖáẕ֖wòr nĕʼum-yĕhwá֑h kiֽ̇y-yáʻa֨ẕ ʻàléy⁠ke֜m nĕbẇkadĕreʼẕȧ֤r meֽlekĕ-bá̇bel֙ ʻéẕá֔h wĕ⁠ẖáşǎ֥b ʻly⁠hm maẖàşá̌báֽh׃"],[49,31,"ק֣וּמוּ עֲל֗וּ אֶל־גּ֥וֹי שְׁלֵ֛יו יוֹשֵׁ֥ב לָ⁠בֶ֖טַח נְאֻם־יְהוָ֑ה לֹא־דְלָתַ֧יִם וְ⁠לֹֽא־בְרִ֛יחַ ל֖⁠וֹ בָּדָ֥ד יִשְׁכֹּֽנוּ׃","q֣ẇmẇ ʻàl֗ẇ ʼel-ġ֥wòy şĕ̌lé֛yw ywòşé֥̌b lá⁠be֖taẖ nĕʼum-yĕhwá֑h lòʼ-dĕláţa֧yim wĕ⁠lòֽʼ-bĕri֛yẖa l֖⁠wò bá̇dá֥d yişĕ̌kòֽ̇nẇ׃"],[49,32,"וְ⁠הָי֨וּ גְמַלֵּי⁠הֶ֜ם לָ⁠בַ֗ז וַ⁠הֲמ֤וֹן מִקְנֵי⁠הֶם֙ לְ⁠שָׁלָ֔ל וְ⁠זֵרִתִ֥י⁠ם לְ⁠כָל־ר֖וּחַ קְצוּצֵ֣י פֵאָ֑ה וּ⁠מִ⁠כָּל־עֲבָרָ֛י⁠ו אָבִ֥יא אֶת־אֵידָ֖⁠ם נְאֻם־יְהוָֽה׃","wĕ⁠háy֨ẇ gĕmalé̇y⁠he֜m lá⁠ba֗z wa⁠hàm֤wòn miqĕnéy⁠hem֙ lĕ⁠şá̌lá֔l wĕ⁠zériţi֥y⁠m lĕ⁠kál-r֖ẇẖa qĕẕẇẕé֣y péʼá֑h ẇ⁠mi⁠ká̇l-ʻàbárá֛y⁠w ʼábi֥yʼ ʼeţ-ʼéydá֖⁠m nĕʼum-yĕhwáֽh׃"],[49,33,"וְ⁠הָיְתָ֨ה חָצ֜וֹר לִ⁠מְע֥וֹן תַּנִּ֛ים שְׁמָמָ֖ה עַד־עוֹלָ֑ם לֹֽא־יֵשֵׁ֥ב שָׁם֙ אִ֔ישׁ וְ⁠לֹֽא־יָג֥וּר בָּ֖⁠הּ בֶּן־אָדָֽם׃ס","wĕ⁠háyĕţá֨h ẖáẕ֜wòr li⁠mĕʻ֥wòn ţȧni֛̇ym şĕ̌mámá֖h ʻad-ʻwòlá֑m lòֽʼ-yéşé֥̌b şá̌m֙ ʼi֔yş̌ wĕ⁠lòֽʼ-yág֥ẇr bá֖̇⁠ḣ bėn-ʼádáֽm׃s"],[49,34,"אֲשֶׁ֨ר הָיָ֧ה דְבַר־יְהוָ֛ה אֶל־יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא אֶל־עֵילָ֑ם בְּ⁠רֵאשִׁ֗ית מַלְכ֛וּת צִדְקִיָּ֥ה מֶֽלֶךְ־יְהוּדָ֖ה לֵ⁠אמֹֽר׃","ʼàşě֨r háyá֧h dĕbar-yĕhwá֛h ʼel-yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ ʼel-ʻéylá֑m bĕ̇⁠réʼşǐ֗yţ malĕk֛ẇţ ẕidĕqiyá֥̇h meֽlekĕ-yĕhẇdá֖h lé⁠ʼmòֽr׃"],[49,35,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִ֥י שֹׁבֵ֖ר אֶת־קֶ֣שֶׁת עֵילָ֑ם רֵאשִׁ֖ית גְּבוּרָתָֽ⁠ם׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠ni֥y şò̌bé֖r ʼeţ-qe֣şěţ ʻéylá֑m réʼşǐ֖yţ gĕ̇bẇráţáֽ⁠m׃"],[49,36,"וְ⁠הֵבֵאתִ֨י אֶל־עֵילָ֜ם אַרְבַּ֣ע רוּח֗וֹת מֵֽ⁠אַרְבַּע֙ קְצ֣וֹת הַ⁠שָּׁמַ֔יִם וְ⁠זֵ֣רִתִ֔י⁠ם לְ⁠כֹ֖ל הָ⁠רֻח֣וֹת הָ⁠אֵ֑לֶּה וְ⁠לֹֽא־יִהְיֶ֣ה הַ⁠גּ֔וֹי אֲשֶׁ֛ר לֹֽא־יָב֥וֹא שָׁ֖ם נִדְּחֵ֥י עולם׃","wĕ⁠hébéʼţi֨y ʼel-ʻéylá֜m ʼarĕbȧ֣ʻ rẇẖ֗wòţ méֽ⁠ʼarĕbȧʻ֙ qĕẕ֣wòţ ha⁠şá̇̌ma֔yim wĕ⁠zé֣riţi֔y⁠m lĕ⁠kò֖l há⁠ruẖ֣wòţ há⁠ʼé֑lėh wĕ⁠lòֽʼ-yihĕye֣h ha⁠ġ֔wòy ʼàşě֛r lòֽʼ-yáb֥wòʼ şá֖̌m nidĕ̇ẖé֥y ʻwlm׃"],[49,37,"וְ⁠הַחְתַּתִּ֣י אֶת־עֵ֠ילָם לִ⁠פְנֵ֨י אֹיְבֵי⁠הֶ֜ם וְ⁠לִ⁠פְנֵ֣י ׀ מְבַקְשֵׁ֣י נַפְשָׁ֗⁠ם וְ⁠הֵבֵאתִ֨י עֲלֵי⁠הֶ֧ם ׀ רָעָ֛ה אֶת־חֲר֥וֹן אַפִּ֖⁠י נְאֻם־יְהוָ֑ה וְ⁠שִׁלַּחְתִּ֤י אַֽחֲרֵי⁠הֶם֙ אֶת־הַ⁠חֶ֔רֶב עַ֥ד כַּלּוֹתִ֖⁠י אוֹתָֽ⁠ם׃","wĕ⁠haẖĕţȧţi֣̇y ʼeţ-ʻé֠ylám li⁠pĕné֨y ʼòyĕbéy⁠he֜m wĕ⁠li⁠pĕné֣y ׀ mĕbaqĕşé֣̌y napĕşá̌֗⁠m wĕ⁠hébéʼţi֨y ʻàléy⁠he֧m ׀ ráʻá֛h ʼeţ-ẖàr֥wòn ʼapi֖̇⁠y nĕʼum-yĕhwá֑h wĕ⁠şǐlȧẖĕţi֤̇y ʼaֽẖàréy⁠hem֙ ʼeţ-ha⁠ẖe֔reb ʻa֥d kȧl̇wòţi֖⁠y ʼwòţáֽ⁠m׃"],[49,38,"וְ⁠שַׂמְתִּ֥י כִסְאִ֖⁠י בְּ⁠עֵילָ֑ם וְ⁠הַאֲבַדְתִּ֥י מִ⁠שָּׁ֛ם מֶ֥לֶךְ וְ⁠שָׂרִ֖ים נְאֻם־יְהוָֽה׃","wĕ⁠şâmĕţi֥̇y kisĕʼi֖⁠y bĕ̇⁠ʻéylá֑m wĕ⁠haʼàbadĕţi֥̇y mi⁠şá֛̇̌m me֥lekĕ wĕ⁠şá̂ri֖ym nĕʼum-yĕhwáֽh׃"],[49,39,"וְ⁠הָיָ֣ה ׀ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֗ים אשוב אֶת־שבית עֵילָ֖ם נְאֻם־יְהוָֽה׃ס","wĕ⁠háyá֣h ׀ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֗ym ʼşwb ʼeţ-şbyţ ʻéylá֖m nĕʼum-yĕhwáֽh׃s"],[50,1,"הַ⁠דָּבָ֗ר אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אֶל־בָּבֶ֖ל אֶל־אֶ֣רֶץ כַּשְׂדִּ֑ים בְּ⁠יַ֖ד יִרְמְיָ֥הוּ הַ⁠נָּבִֽיא׃","ha⁠dá̇bá֗r ʼàşě֨r di̇bė֧r yĕhwá֛h ʼel-bá̇be֖l ʼel-ʼe֣reẕ kȧşĕ̂di֑̇ym bĕ̇⁠ya֖d yirĕmĕyá֥hẇ ha⁠ná̇biֽyʼ׃"],[50,2,"הַגִּ֨ידוּ בַ⁠גּוֹיִ֤ם וְ⁠הַשְׁמִ֨יעוּ֙ וּֽ⁠שְׂאוּ־נֵ֔ס הַשְׁמִ֖יעוּ אַל־תְּכַחֵ֑דוּ אִמְרוּ֩ נִלְכְּדָ֨ה בָבֶ֜ל הֹבִ֥ישׁ בֵּל֙ חַ֣ת מְרֹדָ֔ךְ הֹבִ֣ישׁוּ עֲצַבֶּ֔י⁠הָ חַ֖תּוּ גִּלּוּלֶֽי⁠הָ׃","hagi̇֨ydẇ ba⁠ġwòyi֤m wĕ⁠haşĕ̌mi֨yʻẇ֙ ẇֽ⁠şĕ̂ʼẇ-né֔s haşĕ̌mi֖yʻẇ ʼal-ţĕ̇kaẖé֑dẇ ʼimĕrẇ֩ nilĕkĕ̇dá֨h bábe֜l hòbi֥yş̌ bé̇l֙ ẖa֣ţ mĕròdá֔kĕ hòbi֣yş̌ẇ ʻàẕabė֔y⁠há ẖa֖ţ̇ẇ gi̇l̇ẇleֽy⁠há׃"],[50,3,"כִּ֣י עָלָה֩ עָלֶ֨י⁠הָ גּ֜וֹי מִ⁠צָּפ֗וֹן הֽוּא־יָשִׁ֤ית אֶת־אַרְצָ⁠הּ֙ לְ⁠שַׁמָּ֔ה וְ⁠לֹֽא־יִהְיֶ֥ה יוֹשֵׁ֖ב בָּ֑⁠הּ מֵ⁠אָדָ֥ם וְ⁠עַד־בְּהֵמָ֖ה נָ֥דוּ הָלָֽכוּ׃","ki֣̇y ʻáláh֩ ʻále֨y⁠há ġ֜wòy mi⁠ẕá̇p֗wòn hֽẇʼ-yáşǐ֤yţ ʼeţ-ʼarĕẕá⁠ḣ֙ lĕ⁠şǎmá̇֔h wĕ⁠lòֽʼ-yihĕye֥h ywòşé֖̌b bá֑̇⁠ḣ mé⁠ʼádá֥m wĕ⁠ʻad-bĕ̇hémá֖h ná֥dẇ háláֽkẇ׃"],[50,4,"בַּ⁠יָּמִ֨ים הָ⁠הֵ֜מָּה וּ⁠בָ⁠עֵ֤ת הַ⁠הִיא֙ נְאֻם־יְהוָ֔ה יָבֹ֧אוּ בְנֵֽי־יִשְׂרָאֵ֛ל הֵ֥מָּה וּ⁠בְנֵֽי־יְהוּדָ֖ה יַחְדָּ֑ו הָל֤וֹךְ וּ⁠בָכוֹ֙ יֵלֵ֔כוּ וְ⁠אֶת־יְהוָ֥ה אֱלֹהֵי⁠הֶ֖ם יְבַקֵּֽשׁוּ׃","bȧ⁠yá̇mi֨ym há⁠hé֜má̇h ẇ⁠bá⁠ʻé֤ţ ha⁠hiyʼ֙ nĕʼum-yĕhwá֔h yábò֧ʼẇ bĕnéֽy-yişĕ̂ráʼé֛l hé֥má̇h ẇ⁠bĕnéֽy-yĕhẇdá֖h yaẖĕdá֑̇w hál֤wòkĕ ẇ⁠bákwò֙ yélé֔kẇ wĕ⁠ʼeţ-yĕhwá֥h ʼèlòhéy⁠he֖m yĕbaqéֽ̇ş̌ẇ׃"],[50,5,"צִיּ֣וֹן יִשְׁאָ֔לוּ דֶּ֖רֶךְ הֵ֣נָּה פְנֵי⁠הֶ֑ם בֹּ֚אוּ וְ⁠נִלְו֣וּ אֶל־יְהוָ֔ה בְּרִ֥ית עוֹלָ֖ם לֹ֥א תִשָּׁכֵֽחַ׃ס","ẕiẏ֣wòn yişĕ̌ʼá֔lẇ dė֖rekĕ hé֣ná̇h pĕnéy⁠he֑m bò֚̇ʼẇ wĕ⁠nilĕw֣ẇ ʼel-yĕhwá֔h bĕ̇ri֥yţ ʻwòlá֖m lò֥ʼ ţişá̇̌kéֽẖa׃s"],[50,6,"צֹ֤אן אֹֽבְדוֹת֙ היה עַמִּ֔⁠י רֹעֵי⁠הֶ֣ם הִתְע֔וּ⁠ם הָרִ֖ים שובבים מֵ⁠הַ֤ר אֶל־גִּבְעָה֙ הָלָ֔כוּ שָׁכְח֖וּ רִבְצָֽ⁠ם׃","ẕò֤ʼn ʼòֽbĕdwòţ֙ hyh ʻami̇֔⁠y ròʻéy⁠he֣m hiţĕʻ֔ẇ⁠m hári֖ym şwbbym mé⁠ha֤r ʼel-gi̇bĕʻáh֙ hálá֔kẇ şá̌kĕẖ֖ẇ ribĕẕáֽ⁠m׃"],[50,7,"כָּל־מוֹצְאֵי⁠הֶ֣ם אֲכָל֔וּ⁠ם וְ⁠צָרֵי⁠הֶ֥ם אָמְר֖וּ לֹ֣א נֶאְשָׁ֑ם תַּ֗חַת אֲשֶׁ֨ר חָטְא֤וּ לַֽ⁠יהוָה֙ נְוֵה־צֶ֔דֶק וּ⁠מִקְוֵ֥ה אֲבֽוֹתֵי⁠הֶ֖ם יְהוָֽה׃ס","ká̇l-mwòẕĕʼéy⁠he֣m ʼàkál֔ẇ⁠m wĕ⁠ẕáréy⁠he֥m ʼámĕr֖ẇ lò֣ʼ neʼĕşá֑̌m ţȧ֗ẖaţ ʼàşě֨r ẖátĕʼ֤ẇ laֽ⁠yhwáh֙ nĕwéh-ẕe֔deq ẇ⁠miqĕwé֥h ʼàbֽwòţéy⁠he֖m yĕhwáֽh׃s"],[50,8,"נֻ֚דוּ מִ⁠תּ֣וֹךְ בָּבֶ֔ל וּ⁠מֵ⁠אֶ֥רֶץ כַּשְׂדִּ֖ים יצאו וִ⁠הְי֕וּ כְּ⁠עַתּוּדִ֖ים לִ⁠פְנֵי־צֹֽאן׃","nu֚dẇ mi⁠ţ֣̇wòkĕ bá̇be֔l ẇ⁠mé⁠ʼe֥reẕ kȧşĕ̂di֖̇ym yẕʼw wi⁠hĕy֕ẇ kĕ̇⁠ʻaţ̇ẇdi֖ym li⁠pĕnéy-ẕòֽʼn׃"],[50,9,"כִּ֣י הִנֵּ֣ה אָנֹכִ֡י מֵעִיר֩ וּ⁠מַעֲלֶ֨ה עַל־בָּבֶ֜ל קְהַל־גּוֹיִ֤ם גְּדֹלִים֙ מֵ⁠אֶ֣רֶץ צָפ֔וֹן וְ⁠עָ֣רְכוּ לָ֔⁠הּ מִ⁠שָּׁ֖ם תִּלָּכֵ֑ד חִצָּי⁠ו֙ כְּ⁠גִבּ֣וֹר מַשְׁכִּ֔יל לֹ֥א יָשׁ֖וּב רֵיקָֽם׃","ki֣̇y hiné֣̇h ʼánòki֡y méʻiyr֩ ẇ⁠maʻàle֨h ʻal-bá̇be֜l qĕhal-ġwòyi֤m gĕ̇dòliym֙ mé⁠ʼe֣reẕ ẕáp֔wòn wĕ⁠ʻá֣rĕkẇ lá֔⁠ḣ mi⁠şá֖̇̌m ţi̇lá̇ké֑d ẖiẕá̇y⁠w֙ kĕ̇⁠giḃ֣wòr maşĕ̌ki̇֔yl lò֥ʼ yáş֖̌ẇb réyqáֽm׃"],[50,10,"וְ⁠הָיְתָ֥ה כַשְׂדִּ֖ים לְ⁠שָׁלָ֑ל כָּל־שֹׁלְלֶ֥י⁠הָ יִשְׂבָּ֖עוּ נְאֻם־יְהוָֽה׃","wĕ⁠háyĕţá֥h kaşĕ̂di֖̇ym lĕ⁠şá̌lá֑l ká̇l-şò̌lĕle֥y⁠há yişĕ̂bá֖̇ʻẇ nĕʼum-yĕhwáֽh׃"],[50,11,"כִּ֤י תשמחי כִּ֣י תעלזי שֹׁסֵ֖י נַחֲלָתִ֑⁠י כִּ֤י תפושי כְּ⁠עֶגְלָ֣ה דָשָׁ֔ה ו⁠תצהלי כָּ⁠אֲבִּרִֽים׃","ki֤̇y ţşmẖy ki֣̇y ţʻlzy şò̌sé֖y naẖàláţi֑⁠y ki֤̇y ţpwşy kĕ̇⁠ʻegĕlá֣h dáşá̌֔h w⁠ţẕhly ká̇⁠ʼàbi̇riֽym׃"],[50,12,"בּ֤וֹשָׁה אִמְּ⁠כֶם֙ מְאֹ֔ד חָפְרָ֖ה יֽוֹלַדְתְּ⁠כֶ֑ם הִנֵּה֙ אַחֲרִ֣ית גּוֹיִ֔ם מִדְבָּ֖ר צִיָּ֥ה וַ⁠עֲרָבָֽה׃","ḃ֤wòşá̌h ʼimĕ̇⁠kem֙ mĕʼò֔d ẖápĕrá֖h yֽwòladĕţĕ̇⁠ke֑m hiné̇h֙ ʼaẖàri֣yţ ġwòyi֔m midĕbá֖̇r ẕiyá֥̇h wa⁠ʻàrábáֽh׃"],[50,13,"מִ⁠קֶּ֤צֶף יְהוָה֙ לֹ֣א תֵשֵׁ֔ב וְ⁠הָיְתָ֥ה שְׁמָמָ֖ה כֻּלָּ֑⁠הּ כֹּ֚ל עֹבֵ֣ר עַל־בָּבֶ֔ל יִשֹּׁ֥ם וְ⁠יִשְׁרֹ֖ק עַל־כָּל־מַכּוֹתֶֽי⁠הָ׃","mi⁠qė֤ẕep yĕhwáh֙ lò֣ʼ ţéşé̌֔b wĕ⁠háyĕţá֥h şĕ̌mámá֖h ku̇lá֑̇⁠ḣ kò֚̇l ʻòbé֣r ʻal-bá̇be֔l yişò֥̇̌m wĕ⁠yişĕ̌rò֖q ʻal-ká̇l-mak̇wòţeֽy⁠há׃"],[50,14,"עִרְכ֨וּ עַל־בָּבֶ֤ל ׀ סָבִיב֙ כָּל־דֹּ֣רְכֵי קֶ֔שֶׁת יְד֣וּ אֵלֶ֔י⁠הָ אַֽל־תַּחְמְל֖וּ אֶל־חֵ֑ץ כִּ֥י לַֽ⁠יהוָ֖ה חָטָֽאָה׃","ʻirĕk֨ẇ ʻal-bá̇be֤l ׀ sábiyb֙ ká̇l-dò֣̇rĕkéy qe֔şěţ yĕd֣ẇ ʼéle֔y⁠há ʼaֽl-ţȧẖĕmĕl֖ẇ ʼel-ẖé֑ẕ ki֥̇y laֽ⁠yhwá֖h ẖátáֽʼáh׃"],[50,15,"הָרִ֨יעוּ עָלֶ֤י⁠הָ סָבִיב֙ נָתְנָ֣ה יָדָ֔⁠הּ נָֽפְלוּ֙ אשויתי⁠ה נֶהֶרְס֖וּ חֽוֹמוֹתֶ֑י⁠הָ כִּי֩ נִקְמַ֨ת יְהוָ֥ה הִיא֙ הִנָּ֣קְמוּ בָ֔⁠הּ כַּ⁠אֲשֶׁ֥ר עָשְׂתָ֖ה עֲשׂוּ־לָֽ⁠הּ׃","hári֨yʻẇ ʻále֤y⁠há sábiyb֙ náţĕná֣h yádá֔⁠ḣ náֽpĕlẇ֙ ʼşwyţy⁠h neherĕs֖ẇ ẖֽwòmwòţe֑y⁠há ki̇y֩ niqĕma֨ţ yĕhwá֥h hiyʼ֙ hiná֣̇qĕmẇ bá֔⁠ḣ kȧ⁠ʼàşě֥r ʻáşĕ̂ţá֖h ʻàş̂ẇ-láֽ⁠ḣ׃"],[50,16,"כִּרְת֤וּ זוֹרֵ֨עַ֙ מִ⁠בָּבֶ֔ל וְ⁠תֹפֵ֥שׂ מַגָּ֖ל בְּ⁠עֵ֣ת קָצִ֑יר מִ⁠פְּנֵי֙ חֶ֣רֶב הַ⁠יּוֹנָ֔ה אִ֤ישׁ אֶל־עַמּ⁠וֹ֙ יִפְנ֔וּ וְ⁠אִ֥ישׁ לְ⁠אַרְצ֖⁠וֹ יָנֻֽסוּ׃ס","ki̇rĕţ֤ẇ zwòré֨ʻa֙ mi⁠bá̇be֔l wĕ⁠ţòpé֥ş̂ magá֖̇l bĕ̇⁠ʻé֣ţ qáẕi֑yr mi⁠pĕ̇néy֙ ẖe֣reb ha⁠ẏwòná֔h ʼi֤yş̌ ʼel-ʻaṁ⁠wò֙ yipĕn֔ẇ wĕ⁠ʼi֥yş̌ lĕ⁠ʼarĕẕ֖⁠wò yánuֽsẇ׃s"],[50,17,"שֶׂ֧ה פְזוּרָ֛ה יִשְׂרָאֵ֖ל אֲרָי֣וֹת הִדִּ֑יחוּ הָ⁠רִאשׁ֤וֹן אֲכָל⁠וֹ֙ מֶ֣לֶךְ אַשּׁ֔וּר וְ⁠זֶ֤ה הָ⁠אַחֲרוֹן֙ עִצְּמ֔⁠וֹ נְבוּכַדְרֶאצַּ֖ר מֶ֥לֶךְ בָּבֶֽל׃ס","şê֧h pĕzẇrá֛h yişĕ̂ráʼé֖l ʼàráy֣wòţ hidi֑̇yẖẇ há⁠riʼş֤̌wòn ʼàkál⁠wò֙ me֣lekĕ ʼaş̇̌֔ẇr wĕ⁠ze֤h há⁠ʼaẖàrwòn֙ ʻiẕĕ̇m֔⁠wò nĕbẇkadĕreʼẕȧ֖r me֥lekĕ bá̇beֽl׃s"],[50,18,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֞ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִ֥י פֹקֵ֛ד אֶל־מֶ֥לֶךְ בָּבֶ֖ל וְ⁠אֶל־אַרְצ֑⁠וֹ כַּ⁠אֲשֶׁ֥ר פָּקַ֖דְתִּי אֶל־מֶ֥לֶךְ אַשּֽׁוּר׃","lá⁠ké֗n kòֽ̇h-ʼáma֞r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠ni֥y pòqé֛d ʼel-me֥lekĕ bá̇be֖l wĕ⁠ʼel-ʼarĕẕ֑⁠wò kȧ⁠ʼàşě֥r pá̇qa֖dĕţi̇y ʼel-me֥lekĕ ʼaşֽ̇̌ẇr׃"],[50,19,"וְ⁠שֹׁבַבְתִּ֤י אֶת־יִשְׂרָאֵל֙ אֶל־נָוֵ֔⁠הוּ וְ⁠רָעָ֥ה הַ⁠כַּרְמֶ֖ל וְ⁠הַ⁠בָּשָׁ֑ן וּ⁠בְ⁠הַ֥ר אֶפְרַ֛יִם וְ⁠הַ⁠גִּלְעָ֖ד תִּשְׂבַּ֥ע נַפְשֽׁ⁠וֹ׃","wĕ⁠şò̌babĕţi֤̇y ʼeţ-yişĕ̂ráʼél֙ ʼel-náwé֔⁠hẇ wĕ⁠ráʻá֥h ha⁠kȧrĕme֖l wĕ⁠ha⁠bá̇şá֑̌n ẇ⁠bĕ⁠ha֥r ʼepĕra֛yim wĕ⁠ha⁠gi̇lĕʻá֖d ţi̇şĕ̂bȧ֥ʻ napĕşֽ̌⁠wò׃"],[50,20,"בַּ⁠יָּמִ֣ים הָ⁠הֵם֩ וּ⁠בָ⁠עֵ֨ת הַ⁠הִ֜יא נְאֻם־יְהוָ֗ה יְבֻקַּ֞שׁ אֶת־עֲוֺ֤ן יִשְׂרָאֵל֙ וְ⁠אֵינֶ֔⁠נּוּ וְ⁠אֶת־חַטֹּ֥את יְהוּדָ֖ה וְ⁠לֹ֣א תִמָּצֶ֑אינָה כִּ֥י אֶסְלַ֖ח לַ⁠אֲשֶׁ֥ר אַשְׁאִֽיר׃","bȧ⁠yá̇mi֣ym há⁠hém֩ ẇ⁠bá⁠ʻé֨ţ ha⁠hi֜yʼ nĕʼum-yĕhwá֗h yĕbuqȧ֞ş̌ ʼeţ-ʻàwֺ֤n yişĕ̂ráʼél֙ wĕ⁠ʼéyne֔⁠ṅẇ wĕ⁠ʼeţ-ẖatò֥̇ʼţ yĕhẇdá֖h wĕ⁠lò֣ʼ ţimá̇ẕe֑ʼynáh ki֥̇y ʼesĕla֖ẖ la⁠ʼàşě֥r ʼaşĕ̌ʼiֽyr׃"],[50,21,"עַל־הָ⁠אָ֤רֶץ מְרָתַ֨יִם֙ עֲלֵ֣ה עָלֶ֔י⁠הָ וְ⁠אֶל־יוֹשְׁבֵ֖י פְּק֑וֹד חֲרֹ֨ב וְ⁠הַחֲרֵ֤ם אַֽחֲרֵי⁠הֶם֙ נְאֻם־יְהוָ֔ה וַ⁠עֲשֵׂ֕ה כְּ⁠כֹ֖ל אֲשֶׁ֥ר צִוִּיתִֽי⁠ךָ׃ס","ʻal-há⁠ʼá֤reẕ mĕráţa֨yim֙ ʻàlé֣h ʻále֔y⁠há wĕ⁠ʼel-ywòşĕ̌bé֖y pĕ̇q֑wòd ẖàrò֨b wĕ⁠haẖàré֤m ʼaֽẖàréy⁠hem֙ nĕʼum-yĕhwá֔h wa⁠ʻàşé̂֕h kĕ̇⁠kò֖l ʼàşě֥r ẕiwi̇yţiֽy⁠ká׃s"],[50,22,"ק֥וֹל מִלְחָמָ֖ה בָּ⁠אָ֑רֶץ וְ⁠שֶׁ֖בֶר גָּדֽוֹל׃","q֥wòl milĕẖámá֖h bá̇⁠ʼá֑reẕ wĕ⁠şě֖ber gá̇dֽwòl׃"],[50,23,"אֵ֤יךְ נִגְדַּע֙ וַ⁠יִּשָּׁבֵ֔ר פַּטִּ֖ישׁ כָּל־הָ⁠אָ֑רֶץ אֵ֣יךְ הָיְתָ֧ה לְ⁠שַׁמָּ֛ה בָּבֶ֖ל בַּ⁠גּוֹיִֽם׃","ʼé֤ykĕ nigĕdȧʻ֙ wa⁠yi̇şá̇̌bé֔r pȧti֖̇yş̌ ká̇l-há⁠ʼá֑reẕ ʼé֣ykĕ háyĕţá֧h lĕ⁠şǎmá֛̇h bá̇be֖l bȧ⁠ġwòyiֽm׃"],[50,24,"יָקֹ֨שְׁתִּי לָ֤⁠ךְ וְ⁠גַם־נִלְכַּדְתְּ֙ בָּבֶ֔ל וְ⁠אַ֖תְּ לֹ֣א יָדָ֑עַתְּ נִמְצֵאת֙ וְ⁠גַם־נִתְפַּ֔שְׂתְּ כִּ֥י בַֽ⁠יהוָ֖ה הִתְגָּרִֽית׃","yáqò֨şĕ̌ţi̇y lá֤⁠kĕ wĕ⁠gam-nilĕkȧdĕţĕ̇֙ bá̇be֔l wĕ⁠ʼa֖ţĕ̇ lò֣ʼ yádá֑ʻaţĕ̇ nimĕẕéʼţ֙ wĕ⁠gam-niţĕpȧ֔şĕ̂ţĕ̇ ki֥̇y baֽ⁠yhwá֖h hiţĕgá̇riֽyţ׃"],[50,25,"פָּתַ֤ח יְהוָה֙ אֶת־א֣וֹצָר֔⁠וֹ וַ⁠יּוֹצֵ֖א אֶת־כְּלֵ֣י זַעְמ֑⁠וֹ כִּי־מְלָאכָ֣ה הִ֗יא לַֽ⁠אדֹנָ֧⁠י יְהוִ֛ה צְבָא֖וֹת בְּ⁠אֶ֥רֶץ כַּשְׂדִּֽים׃","pá̇ţa֤ẖ yĕhwáh֙ ʼeţ-ʼ֣wòẕár֔⁠wò wa⁠ẏwòẕé֖ʼ ʼeţ-kĕ̇lé֣y zaʻĕm֑⁠wò ki̇y-mĕláʼká֣h hi֗yʼ laֽ⁠ʼdòná֧⁠y yĕhwi֛h ẕĕbáʼ֖wòţ bĕ̇⁠ʼe֥reẕ kȧşĕ̂diֽ̇ym׃"],[50,26,"בֹּֽאוּ־לָ֤⁠הּ מִ⁠קֵּץ֙ פִּתְח֣וּ מַאֲבֻסֶ֔י⁠הָ סָלּ֥וּ⁠הָ כְמוֹ־עֲרֵמִ֖ים וְ⁠הַחֲרִימ֑וּ⁠הָ אַל־תְּהִי־לָ֖⁠הּ שְׁאֵרִֽית׃","bòֽ̇ʼẇ-lá֤⁠ḣ mi⁠qé̇ẕ֙ pi̇ţĕẖ֣ẇ maʼàbuse֔y⁠há sál֥̇ẇ⁠há kĕmwò-ʻàrémi֖ym wĕ⁠haẖàriym֑ẇ⁠há ʼal-ţĕ̇hiy-lá֖⁠ḣ şĕ̌ʼériֽyţ׃"],[50,27,"חִרְבוּ֙ כָּל־פָּרֶ֔י⁠הָ יֵרְד֖וּ לַ⁠טָּ֑בַח ה֣וֹי עֲלֵי⁠הֶ֔ם כִּֽי־בָ֥א יוֹמָ֖⁠ם עֵ֥ת פְּקֻדָּתָֽ⁠ם׃ס","ẖirĕbẇ֙ ká̇l-pá̇re֔y⁠há yérĕd֖ẇ la⁠tá֑̇baẖ h֣wòy ʻàléy⁠he֔m kiֽ̇y-bá֥ʼ ywòmá֖⁠m ʻé֥ţ pĕ̇qudá̇ţáֽ⁠m׃s"],[50,28,"ק֥וֹל נָסִ֛ים וּ⁠פְלֵטִ֖ים מֵ⁠אֶ֣רֶץ בָּבֶ֑ל לְ⁠הַגִּ֣יד בְּ⁠צִיּ֗וֹן אֶת־נִקְמַת֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ נִקְמַ֖ת הֵיכָלֽ⁠וֹ׃","q֥wòl nási֛ym ẇ⁠pĕléti֖ym mé⁠ʼe֣reẕ bá̇be֑l lĕ⁠hagi֣̇yd bĕ̇⁠ẕiẏ֗wòn ʼeţ-niqĕmaţ֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ niqĕma֖ţ héykálֽ⁠wò׃"],[50,29,"הַשְׁמִ֣יעוּ אֶל־בָּבֶ֣ל ׀ רַ֠בִּים כָּל־דֹּ֨רְכֵי קֶ֜שֶׁת חֲנ֧וּ עָלֶ֣י⁠הָ סָבִ֗יב אַל־יְהִי־פְּלֵטָ֔ה שַׁלְּמוּ־לָ֣⁠הּ כְּ⁠פָעֳלָ֔⁠הּ כְּ⁠כֹ֛ל אֲשֶׁ֥ר עָשְׂתָ֖ה עֲשׂוּ־לָ֑⁠הּ כִּ֧י אֶל־יְהוָ֛ה זָ֖דָה אֶל־קְד֥וֹשׁ יִשְׂרָאֵֽל׃","haşĕ̌mi֣yʻẇ ʼel-bá̇be֣l ׀ ra֠bi̇ym ká̇l-dò̇֨rĕkéy qe֜şěţ ẖàn֧ẇ ʻále֣y⁠há sábi֗yb ʼal-yĕhiy-pĕ̇létá֔h şǎlĕ̇mẇ-lá֣⁠ḣ kĕ̇⁠páʻolá֔⁠ḣ kĕ̇⁠kò֛l ʼàşě֥r ʻáşĕ̂ţá֖h ʻàş̂ẇ-lá֑⁠ḣ ki֧̇y ʼel-yĕhwá֛h zá֖dáh ʼel-qĕd֥wòş̌ yişĕ̂ráʼéֽl׃"],[50,30,"לָ⁠כֵ֛ן יִפְּל֥וּ בַחוּרֶ֖י⁠הָ בִּ⁠רְחֹבֹתֶ֑י⁠הָ וְ⁠כָל־אַנְשֵׁ֨י מִלְחַמְתָּ֥⁠הּ יִדַּ֛מּוּ בַּ⁠יּ֥וֹם הַ⁠ה֖וּא נְאֻם־יְהוָֽה׃ס","lá⁠ké֛n yipĕ̇l֥ẇ baẖẇre֖y⁠há bi̇⁠rĕẖòbòţe֑y⁠há wĕ⁠kál-ʼanĕşé̌֨y milĕẖamĕţá֥̇⁠ḣ yidȧ֛ṁẇ bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ nĕʼum-yĕhwáֽh׃s"],[50,31,"הִנְ⁠נִ֤י אֵלֶ֨י⁠ךָ֙ זָד֔וֹן נְאֻם־אֲדֹנָ֥⁠י יְהוִ֖ה צְבָא֑וֹת כִּ֛י בָּ֥א יוֹמְ⁠ךָ֖ עֵ֥ת פְּקַדְתִּֽי⁠ךָ׃","hinĕ⁠ni֤y ʼéle֨y⁠ká֙ zád֔wòn nĕʼum-ʼàdòná֥⁠y yĕhwi֖h ẕĕbáʼ֑wòţ ki֛̇y bá֥̇ʼ ywòmĕ⁠ká֖ ʻé֥ţ pĕ̇qadĕţiֽ̇y⁠ká׃"],[50,32,"וְ⁠כָשַׁ֤ל זָדוֹן֙ וְ⁠נָפַ֔ל וְ⁠אֵ֥ין ל֖⁠וֹ מֵקִ֑ים וְ⁠הִצַּ֤תִּי אֵשׁ֙ בְּ⁠עָרָ֔י⁠ו וְ⁠אָכְלָ֖ה כָּל־סְבִיבֹתָֽי⁠ו׃ס","wĕ⁠káşǎ֤l zádwòn֙ wĕ⁠nápa֔l wĕ⁠ʼé֥yn l֖⁠wò méqi֑ym wĕ⁠hiẕȧ֤ţi̇y ʼéş̌֙ bĕ̇⁠ʻárá֔y⁠w wĕ⁠ʼákĕlá֖h ká̇l-sĕbiybòţáֽy⁠w׃s"],[50,33,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת עֲשׁוּקִ֛ים בְּנֵי־יִשְׂרָאֵ֥ל וּ⁠בְנֵי־יְהוּדָ֖ה יַחְדָּ֑ו וְ⁠כָל־שֹֽׁבֵי⁠הֶם֙ הֶחֱזִ֣יקוּ בָ֔⁠ם מֵאֲנ֖וּ שַׁלְּחָֽ⁠ם׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻàş̌ẇqi֛ym bĕ̇néy-yişĕ̂ráʼé֥l ẇ⁠bĕnéy-yĕhẇdá֖h yaẖĕdá֑̇w wĕ⁠kál-şòֽ̌béy⁠hem֙ heẖèzi֣yqẇ bá֔⁠m méʼàn֖ẇ şǎlĕ̇ẖáֽ⁠m׃"],[50,34,"גֹּאֲלָ֣⁠ם ׀ חָזָ֗ק יְהוָ֤ה צְבָאוֹת֙ שְׁמ֔⁠וֹ רִ֥יב יָרִ֖יב אֶת־רִיבָ֑⁠ם לְמַ֨עַן֙ הִרְגִּ֣יעַ אֶת־הָ⁠אָ֔רֶץ וְ⁠הִרְגִּ֖יז לְ⁠יֹשְׁבֵ֥י בָבֶֽל׃","gò̇ʼàlá֣⁠m ׀ ẖázá֗q yĕhwá֤h ẕĕbáʼwòţ֙ şĕ̌m֔⁠wò ri֥yb yári֖yb ʼeţ-riybá֑⁠m lĕma֨ʻan֙ hirĕgi֣̇yʻa ʼeţ-há⁠ʼá֔reẕ wĕ⁠hirĕgi֖̇yz lĕ⁠yòşĕ̌bé֥y bábeֽl׃"],[50,35,"חֶ֥רֶב עַל־כַּשְׂדִּ֖ים נְאֻם־יְהוָ֑ה וְ⁠אֶל־יֹשְׁבֵ֣י בָבֶ֔ל וְ⁠אֶל־שָׂרֶ֖י⁠הָ וְ⁠אֶל־חֲכָמֶֽי⁠הָ׃","ẖe֥reb ʻal-kȧşĕ̂di֖̇ym nĕʼum-yĕhwá֑h wĕ⁠ʼel-yòşĕ̌bé֣y bábe֔l wĕ⁠ʼel-şá̂re֖y⁠há wĕ⁠ʼel-ẖàkámeֽy⁠há׃"],[50,36,"חֶ֥רֶב אֶל־הַ⁠בַּדִּ֖ים וְ⁠נֹאָ֑לוּ חֶ֥רֶב אֶל־גִּבּוֹרֶ֖י⁠הָ וָ⁠חָֽתּוּ׃","ẖe֥reb ʼel-ha⁠bȧdi֖̇ym wĕ⁠nòʼá֑lẇ ẖe֥reb ʼel-gi̇ḃwòre֖y⁠há wá⁠ẖáֽţ̇ẇ׃"],[50,37,"חֶ֜רֶב אֶל־סוּסָ֣י⁠ו וְ⁠אֶל־רִכְבּ֗⁠וֹ וְ⁠אֶל־כָּל־הָ⁠עֶ֛רֶב אֲשֶׁ֥ר בְּ⁠תוֹכָ֖⁠הּ וְ⁠הָי֣וּ לְ⁠נָשִׁ֑ים חֶ֥רֶב אֶל־אוֹצְרֹתֶ֖י⁠הָ וּ⁠בֻזָּֽזוּ׃","ẖe֜reb ʼel-sẇsá֣y⁠w wĕ⁠ʼel-rikĕḃ֗⁠wò wĕ⁠ʼel-ká̇l-há⁠ʻe֛reb ʼàşě֥r bĕ̇⁠ţwòká֖⁠ḣ wĕ⁠háy֣ẇ lĕ⁠náşǐ֑ym ẖe֥reb ʼel-ʼwòẕĕròţe֖y⁠há ẇ⁠buzáֽ̇zẇ׃"],[50,38,"חֹ֥רֶב אֶל־מֵימֶ֖י⁠הָ וְ⁠יָבֵ֑שׁוּ כִּ֣י אֶ֤רֶץ פְּסִלִים֙ הִ֔יא וּ⁠בָ⁠אֵימִ֖ים יִתְהֹלָֽלוּ׃","ẖò֥reb ʼel-méyme֖y⁠há wĕ⁠yábé֑ş̌ẇ ki֣̇y ʼe֤reẕ pĕ̇siliym֙ hi֔yʼ ẇ⁠bá⁠ʼéymi֖ym yiţĕhòláֽlẇ׃"],[50,39,"לָ⁠כֵ֗ן יֵשְׁב֤וּ צִיִּים֙ אֶת־אִיִּ֔ים וְ⁠יָ֥שְׁבוּ בָ֖⁠הּ בְּנ֣וֹת יַֽעֲנָ֑ה וְ⁠לֹֽא־תֵשֵׁ֥ב עוֹד֙ לָ⁠נֶ֔צַח וְ⁠לֹ֥א תִשְׁכּ֖וֹן עַד־דּ֥וֹר וָ⁠דֽוֹר׃","lá⁠ké֗n yéşĕ̌b֤ẇ ẕiyi̇ym֙ ʼeţ-ʼiyi̇֔ym wĕ⁠yá֥şĕ̌bẇ bá֖⁠ḣ bĕ̇n֣wòţ yaֽʻàná֑h wĕ⁠lòֽʼ-ţéşé֥̌b ʻwòd֙ lá⁠ne֔ẕaẖ wĕ⁠lò֥ʼ ţişĕ̌k֖̇wòn ʻad-ḋ֥wòr wá⁠dֽwòr׃"],[50,40,"כְּ⁠מַהְפֵּכַ֨ת אֱלֹהִ֜ים אֶת־סְדֹ֧ם וְ⁠אֶת־עֲמֹרָ֛ה וְ⁠אֶת־שְׁכֵנֶ֖י⁠הָ נְאֻם־יְהוָ֑ה לֹֽא־יֵשֵׁ֥ב שָׁם֙ אִ֔ישׁ וְ⁠לֹֽא־יָג֥וּר בָּ֖⁠הּ בֶּן־אָדָֽם׃","kĕ̇⁠mahĕpé̇ka֨ţ ʼèlòhi֜ym ʼeţ-sĕdò֧m wĕ⁠ʼeţ-ʻàmòrá֛h wĕ⁠ʼeţ-şĕ̌kéne֖y⁠há nĕʼum-yĕhwá֑h lòֽʼ-yéşé֥̌b şá̌m֙ ʼi֔yş̌ wĕ⁠lòֽʼ-yág֥ẇr bá֖̇⁠ḣ bėn-ʼádáֽm׃"],[50,41,"הִנֵּ֛ה עַ֥ם בָּ֖א מִ⁠צָּפ֑וֹן וְ⁠ג֤וֹי גָּדוֹל֙ וּ⁠מְלָכִ֣ים רַבִּ֔ים יֵעֹ֖רוּ מִ⁠יַּרְכְּתֵי־אָֽרֶץ׃","hiné֛̇h ʻa֥m bá֖̇ʼ mi⁠ẕá̇p֑wòn wĕ⁠g֤wòy gá̇dwòl֙ ẇ⁠mĕláki֣ym rabi̇֔ym yéʻò֖rẇ mi⁠yȧrĕkĕ̇ţéy-ʼáֽreẕ׃"],[50,42,"קֶ֣שֶׁת וְ⁠כִידֹ֞ן יַחֲזִ֗יקוּ אַכְזָרִ֥י הֵ֨מָּה֙ וְ⁠לֹ֣א יְרַחֵ֔מוּ קוֹלָ⁠ם֙ כַּ⁠יָּ֣ם יֶהֱמֶ֔ה וְ⁠עַל־סוּסִ֖ים יִרְכָּ֑בוּ עָר֗וּךְ כְּ⁠אִישׁ֙ לַ⁠מִּלְחָמָ֔ה עָלַ֖יִ⁠ךְ בַּת־בָּבֶֽל׃","qe֣şěţ wĕ⁠kiydò֞n yaẖàzi֗yqẇ ʼakĕzári֥y hé֨má̇h֙ wĕ⁠lò֣ʼ yĕraẖé֔mẇ qwòlá⁠m֙ kȧ⁠yá֣̇m yehème֔h wĕ⁠ʻal-sẇsi֖ym yirĕká֑̇bẇ ʻár֗ẇkĕ kĕ̇⁠ʼiyş̌֙ la⁠mi̇lĕẖámá֔h ʻála֖yi⁠kĕ bȧţ-bá̇beֽl׃"],[50,43,"שָׁמַ֧ע מֶֽלֶךְ־בָּבֶ֛ל אֶת־שִׁמְעָ֖⁠ם וְ⁠רָפ֣וּ יָדָ֑י⁠ו צָרָה֙ הֶחֱזִיקַ֔תְ⁠הוּ חִ֖יל כַּ⁠יּוֹלֵדָֽה׃","şá̌ma֧ʻ meֽlekĕ-bá̇be֛l ʼeţ-şǐmĕʻá֖⁠m wĕ⁠ráp֣ẇ yádá֑y⁠w ẕáráh֙ heẖèziyqa֔ţĕ⁠hẇ ẖi֖yl kȧ⁠ẏwòlédáֽh׃"],[50,44,"הִ֠נֵּה כְּ⁠אַרְיֵ֞ה יַעֲלֶ֨ה מִ⁠גְּא֣וֹן הַ⁠יַּרְדֵּן֮ אֶל־נְוֵ֣ה אֵיתָן֒ כִּֽי־אַרְגִּ֤עָה ארוצ⁠ם מֵֽ⁠עָלֶ֔י⁠הָ וּ⁠מִ֥י בָח֖וּר אֵלֶ֣י⁠הָ אֶפְקֹ֑ד כִּ֣י מִ֤י כָמ֨וֹ⁠נִי֙ וּ⁠מִ֣י יוֹעִדֶ֔⁠נִּי וּ⁠מִֽי־זֶ֣ה רֹעֶ֔ה אֲשֶׁ֥ר יַעֲמֹ֖ד לְ⁠פָנָֽ⁠י׃","hi֠né̇h kĕ̇⁠ʼarĕyé֞h yaʻàle֨h mi⁠gĕ̇ʼ֣wòn ha⁠yȧrĕdé̇n֮ ʼel-nĕwé֣h ʼéyţán֒ kiֽ̇y-ʼarĕgi֤̇ʻáh ʼrwẕ⁠m méֽ⁠ʻále֔y⁠há ẇ⁠mi֥y báẖ֖ẇr ʼéle֣y⁠há ʼepĕqò֑d ki֣̇y mi֤y kám֨wò⁠niy֙ ẇ⁠mi֣y ywòʻide֔⁠ni̇y ẇ⁠miֽy-ze֣h ròʻe֔h ʼàşě֥r yaʻàmò֖d lĕ⁠pánáֽ⁠y׃"],[50,45,"לָ⁠כֵ֞ן שִׁמְע֣וּ עֲצַת־יְהוָ֗ה אֲשֶׁ֤ר יָעַץ֙ אֶל־בָּבֶ֔ל וּ⁠מַ֨חְשְׁבוֹתָ֔י⁠ו אֲשֶׁ֥ר חָשַׁ֖ב אֶל־אֶ֣רֶץ כַּשְׂדִּ֑ים אִם־לֹ֤א יִסְחָבוּ⁠ם֙ צְעִירֵ֣י הַ⁠צֹּ֔אן אִם־לֹ֥א יַשִּׁ֛ים עֲלֵי⁠הֶ֖ם נָוֶֽה׃","lá⁠ké֞n şǐmĕʻ֣ẇ ʻàẕaţ-yĕhwá֗h ʼàşě֤r yáʻaẕ֙ ʼel-bá̇be֔l ẇ⁠ma֨ẖĕşĕ̌bwòţá֔y⁠w ʼàşě֥r ẖáşǎ֖b ʼel-ʼe֣reẕ kȧşĕ̂di֑̇ym ʼim-lò֤ʼ yisĕẖábẇ⁠m֙ ẕĕʻiyré֣y ha⁠ẕò̇֔ʼn ʼim-lò֥ʼ yaşi֛̇̌ym ʻàléy⁠he֖m náweֽh׃"],[50,46,"מִ⁠קּוֹל֙ נִתְפְּשָׂ֣ה בָבֶ֔ל נִרְעֲשָׁ֖ה הָ⁠אָ֑רֶץ וּ⁠זְעָקָ֖ה בַּ⁠גּוֹיִ֥ם נִשְׁמָֽע׃ס","mi⁠q̇wòl֙ niţĕpĕ̇şá֣̂h bábe֔l nirĕʻàşá֖̌h há⁠ʼá֑reẕ ẇ⁠zĕʻáqá֖h bȧ⁠ġwòyi֥m nişĕ̌máֽʻ׃s"],[51,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִי֙ מֵעִ֣יר עַל־בָּבֶ֔ל וְ⁠אֶל־יֹשְׁבֵ֖י לֵ֣ב קָמָ֑י ר֖וּחַ מַשְׁחִֽית׃","kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠niy֙ méʻi֣yr ʻal-bá̇be֔l wĕ⁠ʼel-yòşĕ̌bé֖y lé֣b qámá֑y r֖ẇẖa maşĕ̌ẖiֽyţ׃"],[51,2,"וְ⁠שִׁלַּחְתִּ֨י לְ⁠בָבֶ֤ל ׀ זָרִים֙ וְ⁠זֵר֔וּ⁠הָ וִ⁠יבֹקְק֖וּ אֶת־אַרְצָ֑⁠הּ כִּֽי־הָי֥וּ עָלֶ֛י⁠הָ מִ⁠סָּבִ֖יב בְּ⁠י֥וֹם רָעָֽה׃","wĕ⁠şǐlȧẖĕţi̇֨y lĕ⁠bábe֤l ׀ záriym֙ wĕ⁠zér֔ẇ⁠há wi⁠ybòqĕq֖ẇ ʼeţ-ʼarĕẕá֑⁠ḣ kiֽ̇y-háy֥ẇ ʻále֛y⁠há mi⁠sá̇bi֖yb bĕ̇⁠y֥wòm ráʻáֽh׃"],[51,3,"אֶֽל־יִדְרֹ֤ךְ ידרך הַ⁠דֹּרֵךְ֙ קַשְׁתּ֔⁠וֹ וְ⁠אֶל־יִתְעַ֖ל בְּ⁠סִרְיֹנ֑⁠וֹ וְ⁠אַֽל־תַּחְמְלוּ֙ אֶל־בַּ֣חֻרֶ֔י⁠הָ הַחֲרִ֖ימוּ כָּל־צְבָאָֽ⁠הּ׃","ʼeֽl-yidĕrò֤kĕ ydrk ha⁠dò̇rékĕ֙ qaşĕ̌ţ̇֔⁠wò wĕ⁠ʼel-yiţĕʻa֖l bĕ̇⁠sirĕyòn֑⁠wò wĕ⁠ʼaֽl-ţȧẖĕmĕlẇ֙ ʼel-bȧ֣ẖure֔y⁠há haẖàri֖ymẇ ká̇l-ẕĕbáʼáֽ⁠ḣ׃"],[51,4,"וְ⁠נָפְל֥וּ חֲלָלִ֖ים בְּ⁠אֶ֣רֶץ כַּשְׂדִּ֑ים וּ⁠מְדֻקָּרִ֖ים בְּ⁠חוּצוֹתֶֽי⁠הָ׃","wĕ⁠nápĕl֥ẇ ẖàláli֖ym bĕ̇⁠ʼe֣reẕ kȧşĕ̂di֑̇ym ẇ⁠mĕduqá̇ri֖ym bĕ̇⁠ẖẇẕwòţeֽy⁠há׃"],[51,5,"כִּ֠י לֹֽא־אַלְמָ֨ן יִשְׂרָאֵ֤ל וִֽ⁠יהוּדָה֙ מֵֽ⁠אֱלֹהָ֔י⁠ו מֵֽ⁠יְהוָ֖ה צְבָא֑וֹת כִּ֤י אַרְצָ⁠ם֙ מָלְאָ֣ה אָשָׁ֔ם מִ⁠קְּד֖וֹשׁ יִשְׂרָאֵֽל׃","ki̇֠y lòֽʼ-ʼalĕmá֨n yişĕ̂ráʼé֤l wiֽ⁠yhẇdáh֙ méֽ⁠ʼèlòhá֔y⁠w méֽ⁠yĕhwá֖h ẕĕbáʼ֑wòţ ki֤̇y ʼarĕẕá⁠m֙ málĕʼá֣h ʼáşá̌֔m mi⁠qĕ̇d֖wòş̌ yişĕ̂ráʼéֽl׃"],[51,6,"נֻ֣סוּ ׀ מִ⁠תּ֣וֹךְ בָּבֶ֗ל וּ⁠מַלְּטוּ֙ אִ֣ישׁ נַפְשׁ֔⁠וֹ אַל־תִּדַּ֖מּוּ בַּ⁠עֲוֺנָ֑⁠הּ כִּי֩ עֵ֨ת נְקָמָ֥ה הִיא֙ לַֽ⁠יהוָ֔ה גְּמ֕וּל ה֥וּא מְשַׁלֵּ֖ם לָֽ⁠הּ׃","nu֣sẇ ׀ mi⁠ţ֣̇wòkĕ bá̇be֗l ẇ⁠malĕ̇tẇ֙ ʼi֣yş̌ napĕş̌֔⁠wò ʼal-ţi̇dȧ֖ṁẇ bȧ⁠ʻàwֺná֑⁠ḣ ki̇y֩ ʻé֨ţ nĕqámá֥h hiyʼ֙ laֽ⁠yhwá֔h gĕ̇m֕ẇl h֥ẇʼ mĕşǎlé֖̇m láֽ⁠ḣ׃"],[51,7,"כּוֹס־זָהָ֤ב בָּבֶל֙ בְּ⁠יַד־יְהוָ֔ה מְשַׁכֶּ֖רֶת כָּל־הָ⁠אָ֑רֶץ מִ⁠יֵּינָ⁠הּ֙ שָׁת֣וּ גוֹיִ֔ם עַל־כֵּ֖ן יִתְהֹלְל֥וּ גוֹיִֽם׃","k̇wòs-záhá֤b bá̇bel֙ bĕ̇⁠yad-yĕhwá֔h mĕşǎkė֖reţ ká̇l-há⁠ʼá֑reẕ mi⁠yé̇yná⁠ḣ֙ şá̌ţ֣ẇ gwòyi֔m ʻal-ké֖̇n yiţĕhòlĕl֥ẇ gwòyiֽm׃"],[51,8,"פִּתְאֹ֛ם נָפְלָ֥ה בָבֶ֖ל וַ⁠תִּשָּׁבֵ֑ר הֵילִ֣ילוּ עָלֶ֗י⁠הָ קְח֤וּ צֳרִי֙ לְ⁠מַכְאוֹבָ֔⁠הּ אוּלַ֖י תֵּרָפֵֽא׃","pi̇ţĕʼò֛m nápĕlá֥h bábe֖l wa⁠ţi̇şá̇̌bé֑r héyli֣ylẇ ʻále֗y⁠há qĕẖ֤ẇ ẕoriy֙ lĕ⁠makĕʼwòbá֔⁠ḣ ʼẇla֖y ţé̇rápéֽʼ׃"],[51,9,"רפאנו אֶת־בָּבֶל֙ וְ⁠לֹ֣א נִרְפָּ֔תָה עִזְב֕וּ⁠הָ וְ⁠נֵלֵ֖ךְ אִ֣ישׁ לְ⁠אַרְצ֑⁠וֹ כִּֽי־נָגַ֤ע אֶל־הַ⁠שָּׁמַ֨יִם֙ מִשְׁפָּטָ֔⁠הּ וְ⁠נִשָּׂ֖א עַד־שְׁחָקִֽים׃","rpʼnw ʼeţ-bá̇bel֙ wĕ⁠lò֣ʼ nirĕpá̇֔ţáh ʻizĕb֕ẇ⁠há wĕ⁠nélé֖kĕ ʼi֣yş̌ lĕ⁠ʼarĕẕ֑⁠wò kiֽ̇y-nága֤ʻ ʼel-ha⁠şá̇̌ma֨yim֙ mişĕ̌pá̇tá֔⁠ḣ wĕ⁠nişá֖̇̂ʼ ʻad-şĕ̌ẖáqiֽym׃"],[51,10,"הוֹצִ֥יא יְהוָ֖ה אֶת־צִדְקֹתֵ֑י⁠נוּ בֹּ֚אוּ וּ⁠נְסַפְּרָ֣ה בְ⁠צִיּ֔וֹן אֶֽת־מַעֲשֵׂ֖ה יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","hwòẕi֥yʼ yĕhwá֖h ʼeţ-ẕidĕqòţé֑y⁠nẇ bò֚̇ʼẇ ẇ⁠nĕsapĕ̇rá֣h bĕ⁠ẕiẏ֔wòn ʼeֽţ-maʻàşé֖̂h yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[51,11,"הָבֵ֣רוּ הַ⁠חִצִּים֮ מִלְא֣וּ הַ⁠שְּׁלָטִים֒ הֵעִ֣יר יְהוָ֗ה אֶת־ר֨וּחַ֙ מַלְכֵ֣י מָדַ֔י כִּֽי־עַל־בָּבֶ֥ל מְזִמָּת֖⁠וֹ לְ⁠הַשְׁחִיתָ֑⁠הּ כִּֽי־נִקְמַ֤ת יְהוָה֙ הִ֔יא נִקְמַ֖ת הֵיכָלֽ⁠וֹ׃","hábé֣rẇ ha⁠ẖiẕi̇ym֮ milĕʼ֣ẇ ha⁠şĕ̇̌látiym֒ héʻi֣yr yĕhwá֗h ʼeţ-r֨ẇẖa֙ malĕké֣y máda֔y kiֽ̇y-ʻal-bá̇be֥l mĕzimá̇ţ֖⁠wò lĕ⁠haşĕ̌ẖiyţá֑⁠ḣ kiֽ̇y-niqĕma֤ţ yĕhwáh֙ hi֔yʼ niqĕma֖ţ héykálֽ⁠wò׃"],[51,12,"אֶל־חוֹמֹ֨ת בָּבֶ֜ל שְׂאוּ־נֵ֗ס הַחֲזִ֨יקוּ֙ הַ⁠מִּשְׁמָ֔ר הָקִ֨ימוּ֙ שֹֽׁמְרִ֔ים הָכִ֖ינוּ הָ⁠אֹֽרְבִ֑ים כִּ֚י גַּם־זָמַ֣ם יְהוָ֔ה גַּם־עָשָׂ֕ה אֵ֥ת אֲשֶׁר־דִּבֶּ֖ר אֶל־יֹשְׁבֵ֥י בָבֶֽל׃","ʼel-ẖwòmò֨ţ bá̇be֜l şĕ̂ʼẇ-né֗s haẖàzi֨yqẇ֙ ha⁠mi̇şĕ̌má֔r háqi֨ymẇ֙ şòֽ̌mĕri֔ym háki֖ynẇ há⁠ʼòֽrĕbi֑ym ki֚̇y gȧm-záma֣m yĕhwá֔h gȧm-ʻáşá̂֕h ʼé֥ţ ʼàşěr-di̇bė֖r ʼel-yòşĕ̌bé֥y bábeֽl׃"],[51,13,"שכנתי עַל־מַ֣יִם רַבִּ֔ים רַבַּ֖ת אֽוֹצָרֹ֑ת בָּ֥א קִצֵּ֖⁠ךְ אַמַּ֥ת בִּצְעֵֽ⁠ךְ׃","şknţy ʻal-ma֣yim rabi̇֔ym rabȧ֖ţ ʼֽwòẕárò֑ţ bá֥̇ʼ qiẕé֖̇⁠kĕ ʼamȧ֥ţ bi̇ẕĕʻéֽ⁠kĕ׃"],[51,14,"נִשְׁבַּ֛ע יְהוָ֥ה צְבָא֖וֹת בְּ⁠נַפְשׁ֑⁠וֹ כִּ֣י אִם־מִלֵּאתִ֤י⁠ךְ אָדָם֙ כַּ⁠יֶּ֔לֶק וְ⁠עָנ֥וּ עָלַ֖יִ⁠ךְ הֵידָֽד׃ס","nişĕ̌bȧ֛ʻ yĕhwá֥h ẕĕbáʼ֖wòţ bĕ̇⁠napĕş֑̌⁠wò ki֣̇y ʼim-milé̇ʼţi֤y⁠kĕ ʼádám֙ kȧ⁠yė֔leq wĕ⁠ʻán֥ẇ ʻála֖yi⁠kĕ héydáֽd׃s"],[51,15,"עֹשֵׂ֥ה אֶ֨רֶץ֙ בְּ⁠כֹח֔⁠וֹ מֵכִ֥ין תֵּבֵ֖ל בְּ⁠חָכְמָת֑⁠וֹ וּ⁠בִ⁠תְבוּנָת֖⁠וֹ נָטָ֥ה שָׁמָֽיִם׃","ʻòşé֥̂h ʼe֨reẕ֙ bĕ̇⁠kòẖ֔⁠wò méki֥yn ţé̇bé֖l bĕ̇⁠ẖákĕmáţ֑⁠wò ẇ⁠bi⁠ţĕbẇnáţ֖⁠wò nátá֥h şá̌máֽyim׃"],[51,16,"לְ⁠ק֨וֹל תִּתּ֜⁠וֹ הֲמ֥וֹן מַ֨יִם֙ בַּ⁠שָּׁמַ֔יִם וַ⁠יַּ֥עַל נְשִׂאִ֖ים מִ⁠קְצֵה־אָ֑רֶץ בְּרָקִ֤ים לַ⁠מָּטָר֙ עָשָׂ֔ה וַ⁠יֹּ֥צֵא ר֖וּחַ מֵ⁠אֹצְרֹתָֽי⁠ו׃","lĕ⁠q֨wòl ţi̇ţ̇֜⁠wò hàm֥wòn ma֨yim֙ bȧ⁠şá̇̌ma֔yim wa⁠yȧ֥ʻal nĕşîʼi֖ym mi⁠qĕẕéh-ʼá֑reẕ bĕ̇ráqi֤ym la⁠má̇tár֙ ʻáşá̂֔h wa⁠yò֥̇ẕéʼ r֖ẇẖa mé⁠ʼòẕĕròţáֽy⁠w׃"],[51,17,"נִבְעַ֤ר כָּל־אָדָם֙ מִ⁠דַּ֔עַת הֹבִ֥ישׁ כָּל־צֹרֵ֖ף מִ⁠פָּ֑סֶל כִּ֛י שֶׁ֥קֶר נִסְכּ֖⁠וֹ וְ⁠לֹא־ר֥וּחַ בָּֽ⁠ם׃","nibĕʻa֤r ká̇l-ʼádám֙ mi⁠dȧ֔ʻaţ hòbi֥yş̌ ká̇l-ẕòré֖p mi⁠pá֑̇sel ki֛̇y şě֥qer nisĕk֖̇⁠wò wĕ⁠lòʼ-r֥ẇẖa báֽ̇⁠m׃"],[51,18,"הֶ֣בֶל הֵ֔מָּה מַעֲשֵׂ֖ה תַּעְתֻּעִ֑ים בְּ⁠עֵ֥ת פְּקֻדָּתָ֖⁠ם יֹאבֵֽדוּ׃","he֣bel hé֔má̇h maʻàşé֖̂h ţȧʻĕţu̇ʻi֑ym bĕ̇⁠ʻé֥ţ pĕ̇qudá̇ţá֖⁠m yòʼbéֽdẇ׃"],[51,19,"לֹֽא־כְ⁠אֵ֜לֶּה חֵ֣לֶק יַעֲק֗וֹב כִּֽי־יוֹצֵ֤ר הַ⁠כֹּל֙ ה֔וּא וְ⁠שֵׁ֖בֶט נַחֲלָת֑⁠וֹ יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃ס","lòֽʼ-kĕ⁠ʼé֜lėh ẖé֣leq yaʻàq֗wòb kiֽ̇y-ywòẕé֤r ha⁠kò̇l֙ h֔ẇʼ wĕ⁠şé֖̌bet naẖàláţ֑⁠wò yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃s"],[51,20,"מַפֵּץ־אַתָּ֣ה לִ֔⁠י כְּלֵ֖י מִלְחָמָ֑ה וְ⁠נִפַּצְתִּ֤י בְ⁠ךָ֙ גּוֹיִ֔ם וְ⁠הִשְׁחַתִּ֥י בְ⁠ךָ֖ מַמְלָכֽוֹת׃","mapé̇ẕ-ʼaţá֣̇h li֔⁠y kĕ̇lé֖y milĕẖámá֑h wĕ⁠nipȧẕĕţi֤̇y bĕ⁠ká֙ ġwòyi֔m wĕ⁠hişĕ̌ẖaţi֥̇y bĕ⁠ká֖ mamĕlákֽwòţ׃"],[51,21,"וְ⁠נִפַּצְתִּ֣י בְ⁠ךָ֔ ס֖וּס וְ⁠רֹֽכְב֑⁠וֹ וְ⁠נִפַּצְתִּ֣י בְ⁠ךָ֔ רֶ֖כֶב וְ⁠רֹכְבֽ⁠וֹ׃","wĕ⁠nipȧẕĕţi֣̇y bĕ⁠ká֔ s֖ẇs wĕ⁠ròֽkĕb֑⁠wò wĕ⁠nipȧẕĕţi֣̇y bĕ⁠ká֔ re֖keb wĕ⁠ròkĕbֽ⁠wò׃"],[51,22,"וְ⁠נִפַּצְתִּ֤י בְ⁠ךָ֙ אִ֣ישׁ וְ⁠אִשָּׁ֔ה וְ⁠נִפַּצְתִּ֥י בְ⁠ךָ֖ זָקֵ֣ן וָ⁠נָ֑עַר וְ⁠נִפַּצְתִּ֣י בְ⁠ךָ֔ בָּח֖וּר וּ⁠בְתוּלָֽה׃","wĕ⁠nipȧẕĕţi֤̇y bĕ⁠ká֙ ʼi֣yş̌ wĕ⁠ʼişá̇̌֔h wĕ⁠nipȧẕĕţi֥̇y bĕ⁠ká֖ záqé֣n wá⁠ná֑ʻar wĕ⁠nipȧẕĕţi֣̇y bĕ⁠ká֔ bá̇ẖ֖ẇr ẇ⁠bĕţẇláֽh׃"],[51,23,"וְ⁠נִפַּצְתִּ֤י בְ⁠ךָ֙ רֹעֶ֣ה וְ⁠עֶדְר֔⁠וֹ וְ⁠נִפַּצְתִּ֥י בְ⁠ךָ֖ אִכָּ֣ר וְ⁠צִמְדּ֑⁠וֹ וְ⁠נִפַּצְתִּ֣י בְ⁠ךָ֔ פַּח֖וֹת וּ⁠סְגָנִֽים׃","wĕ⁠nipȧẕĕţi֤̇y bĕ⁠ká֙ ròʻe֣h wĕ⁠ʻedĕr֔⁠wò wĕ⁠nipȧẕĕţi֥̇y bĕ⁠ká֖ ʼiká֣̇r wĕ⁠ẕimĕḋ֑⁠wò wĕ⁠nipȧẕĕţi֣̇y bĕ⁠ká֔ pȧẖ֖wòţ ẇ⁠sĕgániֽym׃"],[51,24,"וְ⁠שִׁלַּמְתִּ֨י לְ⁠בָבֶ֜ל וּ⁠לְ⁠כֹ֣ל ׀ יוֹשְׁבֵ֣י כַשְׂדִּ֗ים אֵ֧ת כָּל־רָעָתָ֛⁠ם אֲשֶׁר־עָשׂ֥וּ בְ⁠צִיּ֖וֹן לְ⁠עֵֽינֵי⁠כֶ֑ם נְאֻ֖ם יְהוָֽה׃ס","wĕ⁠şǐlȧmĕţi̇֨y lĕ⁠bábe֜l ẇ⁠lĕ⁠kò֣l ׀ ywòşĕ̌bé֣y kaşĕ̂di̇֗ym ʼé֧ţ ká̇l-ráʻáţá֛⁠m ʼàşěr-ʻáş֥̂ẇ bĕ⁠ẕiẏ֖wòn lĕ⁠ʻéֽynéy⁠ke֑m nĕʼu֖m yĕhwáֽh׃s"],[51,25,"הִנְ⁠נִ֨י אֵלֶ֜י⁠ךָ הַ֤ר הַ⁠מַּשְׁחִית֙ נְאֻם־יְהוָ֔ה הַ⁠מַּשְׁחִ֖ית אֶת־כָּל־הָ⁠אָ֑רֶץ וְ⁠נָטִ֨יתִי אֶת־יָדִ֜⁠י עָלֶ֗י⁠ךָ וְ⁠גִלְגַּלְתִּ֨י⁠ךָ֙ מִן־הַ⁠סְּלָעִ֔ים וּ⁠נְתַתִּ֖י⁠ךָ לְ⁠הַ֥ר שְׂרֵפָֽה׃","hinĕ⁠ni֨y ʼéle֜y⁠ká ha֤r ha⁠mȧşĕ̌ẖiyţ֙ nĕʼum-yĕhwá֔h ha⁠mȧşĕ̌ẖi֖yţ ʼeţ-ká̇l-há⁠ʼá֑reẕ wĕ⁠náti֨yţiy ʼeţ-yádi֜⁠y ʻále֗y⁠ká wĕ⁠gilĕgȧlĕţi̇֨y⁠ká֙ min-ha⁠sĕ̇láʻi֔ym ẇ⁠nĕţaţi֖̇y⁠ká lĕ⁠ha֥r şĕ̂répáֽh׃"],[51,26,"וְ⁠לֹֽא־יִקְח֤וּ מִמְּ⁠ךָ֙ אֶ֣בֶן לְ⁠פִנָּ֔ה וְ⁠אֶ֖בֶן לְ⁠מֽוֹסָד֑וֹת כִּֽי־שִׁמְמ֥וֹת עוֹלָ֛ם תִּֽהְיֶ֖ה נְאֻם־יְהוָֽה׃","wĕ⁠lòֽʼ-yiqĕẖ֤ẇ mimĕ̇⁠ká֙ ʼe֣ben lĕ⁠piná̇֔h wĕ⁠ʼe֖ben lĕ⁠mֽwòsád֑wòţ kiֽ̇y-şǐmĕm֥wòţ ʻwòlá֛m ţiֽ̇hĕye֖h nĕʼum-yĕhwáֽh׃"],[51,27,"שְׂאוּ־נֵ֣ס בָּ⁠אָ֗רֶץ תִּקְע֨וּ שׁוֹפָ֤ר בַּ⁠גּוֹיִם֙ קַדְּשׁ֤וּ עָלֶ֨י⁠הָ֙ גּוֹיִ֔ם הַשְׁמִ֧יעוּ עָלֶ֛י⁠הָ מַמְלְכ֥וֹת אֲרָרַ֖ט מִנִּ֣י וְ⁠אַשְׁכְּנָ֑ז פִּקְד֤וּ עָלֶ֨י⁠הָ֙ טִפְסָ֔ר הַֽעֲלוּ־ס֖וּס כְּ⁠יֶ֥לֶק סָמָֽר׃","şĕ̂ʼẇ-né֣s bá̇⁠ʼá֗reẕ ţi̇qĕʻ֨ẇ ş̌wòpá֤r bȧ⁠ġwòyim֙ qadĕ̇ş֤̌ẇ ʻále֨y⁠há֙ ġwòyi֔m haşĕ̌mi֧yʻẇ ʻále֛y⁠há mamĕlĕk֥wòţ ʼàrára֖t mini֣̇y wĕ⁠ʼaşĕ̌kĕ̇ná֑z pi̇qĕd֤ẇ ʻále֨y⁠há֙ tipĕsá֔r haֽʻàlẇ-s֖ẇs kĕ̇⁠ye֥leq sámáֽr׃"],[51,28,"קַדְּשׁ֨וּ עָלֶ֤י⁠הָ גוֹיִם֙ אֶת־מַלְכֵ֣י מָדַ֔י אֶת־פַּחוֹתֶ֖י⁠הָ וְ⁠אֶת־כָּל־סְגָנֶ֑י⁠הָ וְ⁠אֵ֖ת כָּל־אֶ֥רֶץ מֶמְשַׁלְתּֽ⁠וֹ׃","qadĕ̇ş̌֨ẇ ʻále֤y⁠há gwòyim֙ ʼeţ-malĕké֣y máda֔y ʼeţ-pȧẖwòţe֖y⁠há wĕ⁠ʼeţ-ká̇l-sĕgáne֑y⁠há wĕ⁠ʼé֖ţ ká̇l-ʼe֥reẕ memĕşǎlĕţֽ̇⁠wò׃"],[51,29,"וַ⁠תִּרְעַ֥שׁ הָ⁠אָ֖רֶץ וַ⁠תָּחֹ֑ל כִּ֣י קָ֤מָה עַל־בָּבֶל֙ מַחְשְׁב֣וֹת יְהוָ֔ה לָ⁠שׂ֞וּם אֶת־אֶ֧רֶץ בָּבֶ֛ל לְ⁠שַׁמָּ֖ה מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","wa⁠ţi̇rĕʻa֥ş̌ há⁠ʼá֖reẕ wa⁠ţá̇ẖò֑l ki֣̇y qá֤máh ʻal-bá̇bel֙ maẖĕşĕ̌b֣wòţ yĕhwá֔h lá⁠ş̂֞ẇm ʼeţ-ʼe֧reẕ bá̇be֛l lĕ⁠şǎmá֖̇h mé⁠ʼé֥yn ywòşéֽ̌b׃"],[51,30,"חָדְלוּ֩ גִבּוֹרֵ֨י בָבֶ֜ל לְ⁠הִלָּחֵ֗ם יָֽשְׁבוּ֙ בַּ⁠מְּצָד֔וֹת נָשְׁתָ֥ה גְבוּרָתָ֖⁠ם הָי֣וּ לְ⁠נָשִׁ֑ים הִצִּ֥יתוּ מִשְׁכְּנֹתֶ֖י⁠הָ נִשְׁבְּר֥וּ בְרִיחֶֽי⁠הָ׃","ẖádĕlẇ֩ giḃwòré֨y bábe֜l lĕ⁠hilá̇ẖé֗m yáֽşĕ̌bẇ֙ bȧ⁠mĕ̇ẕád֔wòţ náşĕ̌ţá֥h gĕbẇráţá֖⁠m háy֣ẇ lĕ⁠náşǐ֑ym hiẕi֥̇yţẇ mişĕ̌kĕ̇nòţe֖y⁠há nişĕ̌bĕ̇r֥ẇ bĕriyẖeֽy⁠há׃"],[51,31,"רָ֤ץ לִ⁠קְרַאת־רָץ֙ יָר֔וּץ וּ⁠מַגִּ֖יד לִ⁠קְרַ֣את מַגִּ֑יד לְ⁠הַגִּיד֙ לְ⁠מֶ֣לֶךְ בָּבֶ֔ל כִּֽי־נִלְכְּדָ֥ה עִיר֖⁠וֹ מִ⁠קָּצֶֽה׃","rá֤ẕ li⁠qĕraʼţ-ráẕ֙ yár֔ẇẕ ẇ⁠magi֖̇yd li⁠qĕra֣ʼţ magi֑̇yd lĕ⁠hagi̇yd֙ lĕ⁠me֣lekĕ bá̇be֔l kiֽ̇y-nilĕkĕ̇dá֥h ʻiyr֖⁠wò mi⁠qá̇ẕeֽh׃"],[51,32,"וְ⁠הַ⁠מַּעְבָּר֣וֹת נִתְפָּ֔שׂוּ וְ⁠אֶת־הָ⁠אֲגַמִּ֖ים שָׂרְפ֣וּ בָ⁠אֵ֑שׁ וְ⁠אַנְשֵׁ֥י הַ⁠מִּלְחָמָ֖ה נִבְהָֽלוּ׃ס","wĕ⁠ha⁠mȧʻĕbá̇r֣wòţ niţĕpá̇֔ş̂ẇ wĕ⁠ʼeţ-há⁠ʼàgami֖̇ym şá̂rĕp֣ẇ bá⁠ʼé֑ş̌ wĕ⁠ʼanĕşé֥̌y ha⁠mi̇lĕẖámá֖h nibĕháֽlẇ׃s"],[51,33,"כִּי֩ כֹ֨ה אָמַ֜ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל בַּת־בָּבֶ֕ל כְּ⁠גֹ֖רֶן עֵ֣ת הִדְרִיכָ֑⁠הּ ע֣וֹד מְעַ֔ט וּ⁠בָ֥אָה עֵֽת־הַ⁠קָּצִ֖יר לָֽ⁠הּ׃","ki̇y֩ kò֨h ʼáma֜r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l bȧţ-bá̇be֕l kĕ̇⁠gò֖ren ʻé֣ţ hidĕriyká֑⁠ḣ ʻ֣wòd mĕʻa֔t ẇ⁠bá֥ʼáh ʻéֽţ-ha⁠qá̇ẕi֖yr láֽ⁠ḣ׃"],[51,34,"אכל⁠נו הממ⁠נו נְבוּכַדְרֶאצַּר֮ מֶ֣לֶךְ בָּבֶל֒ הציג⁠נו כְּלִ֣י רִ֔יק בלע⁠נו כַּ⁠תַּנִּ֔ין מִלָּ֥א כְרֵשׂ֖⁠וֹ מֵֽ⁠עֲדָנָ֑⁠י הדיח⁠נו׃","ʼkl⁠nw hmm⁠nw nĕbẇkadĕreʼẕȧr֮ me֣lekĕ bá̇bel֒ hẕyg⁠nw kĕ̇li֣y ri֔yq blʻ⁠nw kȧ⁠ţȧni̇֔yn milá֥̇ʼ kĕréş֖̂⁠wò méֽ⁠ʻàdáná֑⁠y hdyẖ⁠nw׃"],[51,35,"חֲמָסִ֤⁠י וּ⁠שְׁאֵרִ⁠י֙ עַל־בָּבֶ֔ל תֹּאמַ֖ר יֹשֶׁ֣בֶת צִיּ֑וֹן וְ⁠דָמִ⁠י֙ אֶל־יֹשְׁבֵ֣י כַשְׂדִּ֔ים תֹּאמַ֖ר יְרוּשָׁלִָֽם׃ס","ẖàmási֤⁠y ẇ⁠şĕ̌ʼéri⁠y֙ ʻal-bá̇be֔l ţò̇ʼma֖r yòşě֣beţ ẕiẏ֑wòn wĕ⁠dámi⁠y֙ ʼel-yòşĕ̌bé֣y kaşĕ̂di̇֔ym ţò̇ʼma֖r yĕrẇşá̌liáֽm׃s"],[51,36,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִי־רָב֙ אֶת־רִיבֵ֔⁠ךְ וְ⁠נִקַּמְתִּ֖י אֶת־נִקְמָתֵ֑⁠ךְ וְ⁠הַחֲרַבְתִּי֙ אֶת־יַמָּ֔⁠הּ וְ⁠הֹבַשְׁתִּ֖י אֶת־מְקוֹרָֽ⁠הּ׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠niy-ráb֙ ʼeţ-riybé֔⁠kĕ wĕ⁠niqȧmĕţi֖̇y ʼeţ-niqĕmáţé֑⁠kĕ wĕ⁠haẖàrabĕţi̇y֙ ʼeţ-yamá̇֔⁠ḣ wĕ⁠hòbaşĕ̌ţi֖̇y ʼeţ-mĕqwòráֽ⁠ḣ׃"],[51,37,"וְ⁠הָיְתָה֩ בָבֶ֨ל ׀ לְ⁠גַלִּ֧ים ׀ מְעוֹן־תַּנִּ֛ים שַׁמָּ֥ה וּ⁠שְׁרֵקָ֖ה מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","wĕ⁠háyĕţáh֩ bábe֨l ׀ lĕ⁠gali֧̇ym ׀ mĕʻwòn-ţȧni֛̇ym şǎmá֥̇h ẇ⁠şĕ̌réqá֖h mé⁠ʼé֥yn ywòşéֽ̌b׃"],[51,38,"יַחְדָּ֖ו כַּ⁠כְּפִרִ֣ים יִשְׁאָ֑גוּ נָעֲר֖וּ כְּ⁠גוֹרֵ֥י אֲרָיֽוֹת׃","yaẖĕdá֖̇w kȧ⁠kĕ̇piri֣ym yişĕ̌ʼá֑gẇ náʻàr֖ẇ kĕ̇⁠gwòré֥y ʼàráyֽwòţ׃"],[51,39,"בְּ⁠חֻמָּ֞⁠ם אָשִׁ֣ית אֶת־מִשְׁתֵּי⁠הֶ֗ם וְ⁠הִשְׁכַּרְתִּי⁠ם֙ לְמַ֣עַן יַעֲלֹ֔זוּ וְ⁠יָשְׁנ֥וּ שְׁנַת־עוֹלָ֖ם וְ⁠לֹ֣א יָקִ֑יצוּ נְאֻ֖ם יְהוָֽה׃","bĕ̇⁠ẖumá̇֞⁠m ʼáşǐ֣yţ ʼeţ-mişĕ̌ţé̇y⁠he֗m wĕ⁠hişĕ̌kȧrĕţi̇y⁠m֙ lĕma֣ʻan yaʻàlò֔zẇ wĕ⁠yáşĕ̌n֥ẇ şĕ̌naţ-ʻwòlá֖m wĕ⁠lò֣ʼ yáqi֑yẕẇ nĕʼu֖m yĕhwáֽh׃"],[51,40,"אֽוֹרִידֵ֖⁠ם כְּ⁠כָרִ֣ים לִ⁠טְב֑וֹחַ כְּ⁠אֵילִ֖ים עִם־עַתּוּדִֽים׃","ʼֽwòriydé֖⁠m kĕ̇⁠kári֣ym li⁠tĕb֑wòẖa kĕ̇⁠ʼéyli֖ym ʻim-ʻaţ̇ẇdiֽym׃"],[51,41,"אֵ֚יךְ נִלְכְּדָ֣ה שֵׁשַׁ֔ךְ וַ⁠תִּתָּפֵ֖שׂ תְּהִלַּ֣ת כָּל־הָ⁠אָ֑רֶץ אֵ֣יךְ הָיְתָ֧ה לְ⁠שַׁמָּ֛ה בָּבֶ֖ל בַּ⁠גּוֹיִֽם׃","ʼé֚ykĕ nilĕkĕ̇dá֣h şé̌şǎ֔kĕ wa⁠ţi̇ţá̇pé֖ş̂ ţĕ̇hilȧ֣ţ ká̇l-há⁠ʼá֑reẕ ʼé֣ykĕ háyĕţá֧h lĕ⁠şǎmá֛̇h bá̇be֖l bȧ⁠ġwòyiֽm׃"],[51,42,"עָלָ֥ה עַל־בָּבֶ֖ל הַ⁠יָּ֑ם בַּ⁠הֲמ֥וֹן גַּלָּ֖י⁠ו נִכְסָֽתָה׃","ʻálá֥h ʻal-bá̇be֖l ha⁠yá֑̇m bȧ⁠hàm֥wòn gȧlá֖̇y⁠w nikĕsáֽţáh׃"],[51,43,"הָי֤וּ עָרֶ֨י⁠הָ֙ לְ⁠שַׁמָּ֔ה אֶ֖רֶץ צִיָּ֣ה וַ⁠עֲרָבָ֑ה אֶ֗רֶץ לֹֽא־יֵשֵׁ֤ב בָּ⁠הֵן֙ כָּל־אִ֔ישׁ וְ⁠לֹֽא־יַעֲבֹ֥ר בָּ⁠הֵ֖ן בֶּן־אָדָֽם׃","háy֤ẇ ʻáre֨y⁠há֙ lĕ⁠şǎmá̇֔h ʼe֖reẕ ẕiyá֣̇h wa⁠ʻàrábá֑h ʼe֗reẕ lòֽʼ-yéşé֤̌b bá̇⁠hén֙ ká̇l-ʼi֔yş̌ wĕ⁠lòֽʼ-yaʻàbò֥r bá̇⁠hé֖n bėn-ʼádáֽm׃"],[51,44,"וּ⁠פָקַדְתִּ֨י עַל־בֵּ֜ל בְּ⁠בָבֶ֗ל וְ⁠הֹצֵאתִ֤י אֶת־בִּלְע⁠וֹ֙ מִ⁠פִּ֔י⁠ו וְ⁠לֹֽא־יִנְהֲר֥וּ אֵלָ֛י⁠ו ע֖וֹד גּוֹיִ֑ם גַּם־חוֹמַ֥ת בָּבֶ֖ל נָפָֽלָה׃","ẇ⁠páqadĕţi̇֨y ʻal-bé̇֜l bĕ̇⁠bábe֗l wĕ⁠hòẕéʼţi֤y ʼeţ-bi̇lĕʻ⁠wò֙ mi⁠pi̇֔y⁠w wĕ⁠lòֽʼ-yinĕhàr֥ẇ ʼélá֛y⁠w ʻ֖wòd ġwòyi֑m gȧm-ẖwòma֥ţ bá̇be֖l nápáֽláh׃"],[51,45,"צְא֤וּ מִ⁠תּוֹכָ⁠הּ֙ עַמִּ֔⁠י וּ⁠מַלְּט֖וּ אִ֣ישׁ אֶת־נַפְשׁ֑⁠וֹ מֵ⁠חֲר֖וֹן אַף־יְהוָֽה׃","ẕĕʼ֤ẇ mi⁠ţ̇wòká⁠ḣ֙ ʻami̇֔⁠y ẇ⁠malĕ̇t֖ẇ ʼi֣yş̌ ʼeţ-napĕş֑̌⁠wò mé⁠ẖàr֖wòn ʼap-yĕhwáֽh׃"],[51,46,"וּ⁠פֶן־יֵרַ֤ךְ לְבַבְ⁠כֶם֙ וְ⁠תִֽירְא֔וּ בַּ⁠שְּׁמוּעָ֖ה הַ⁠נִּשְׁמַ֣עַת בָּ⁠אָ֑רֶץ וּ⁠בָ֧א בַ⁠שָּׁנָ֣ה הַ⁠שְּׁמוּעָ֗ה וְ⁠אַחֲרָ֤י⁠ו בַּ⁠שָּׁנָה֙ הַ⁠שְּׁמוּעָ֔ה וְ⁠חָמָ֣ס בָּ⁠אָ֔רֶץ וּ⁠מֹשֵׁ֖ל עַל־מֹשֵֽׁל׃","ẇ⁠pen-yéra֤kĕ lĕbabĕ⁠kem֙ wĕ⁠ţiֽyrĕʼ֔ẇ bȧ⁠şĕ̇̌mẇʻá֖h ha⁠ni̇şĕ̌ma֣ʻaţ bá̇⁠ʼá֑reẕ ẇ⁠bá֧ʼ ba⁠şá̇̌ná֣h ha⁠şĕ̇̌mẇʻá֗h wĕ⁠ʼaẖàrá֤y⁠w bȧ⁠şá̇̌náh֙ ha⁠şĕ̇̌mẇʻá֔h wĕ⁠ẖámá֣s bá̇⁠ʼá֔reẕ ẇ⁠mòşé֖̌l ʻal-mòşéֽ̌l׃"],[51,47,"לָ⁠כֵן֙ הִנֵּ֣ה יָמִ֣ים בָּאִ֔ים וּ⁠פָקַדְתִּי֙ עַל־פְּסִילֵ֣י בָבֶ֔ל וְ⁠כָל־אַרְצָ֖⁠הּ תֵּב֑וֹשׁ וְ⁠כָל־חֲלָלֶ֖י⁠הָ יִפְּל֥וּ בְ⁠תוֹכָֽ⁠הּ׃","lá⁠kén֙ hiné֣̇h yámi֣ym bá̇ʼi֔ym ẇ⁠páqadĕţi̇y֙ ʻal-pĕ̇siylé֣y bábe֔l wĕ⁠kál-ʼarĕẕá֖⁠ḣ ţé̇b֑wòş̌ wĕ⁠kál-ẖàlále֖y⁠há yipĕ̇l֥ẇ bĕ⁠ţwòkáֽ⁠ḣ׃"],[51,48,"וְ⁠רִנְּנ֤וּ עַל־בָּבֶל֙ שָׁמַ֣יִם וָ⁠אָ֔רֶץ וְ⁠כֹ֖ל אֲשֶׁ֣ר בָּ⁠הֶ֑ם כִּ֧י מִ⁠צָּפ֛וֹן יָבוֹא־לָ֥⁠הּ הַ⁠שּׁוֹדְדִ֖ים נְאֻם־יְהוָֽה׃","wĕ⁠rinĕ̇n֤ẇ ʻal-bá̇bel֙ şá̌ma֣yim wá⁠ʼá֔reẕ wĕ⁠kò֖l ʼàşě֣r bá̇⁠he֑m ki֧̇y mi⁠ẕá̇p֛wòn yábwòʼ-lá֥⁠ḣ ha⁠ş̇̌wòdĕdi֖ym nĕʼum-yĕhwáֽh׃"],[51,49,"גַּם־בָּבֶ֕ל לִ⁠נְפֹּ֖ל חַֽלְלֵ֣י יִשְׂרָאֵ֑ל גַּם־לְ⁠בָבֶ֥ל נָפְל֖וּ חַֽלְלֵ֥י כָל־הָ⁠אָֽרֶץ׃","gȧm-bá̇be֕l li⁠nĕpò֖̇l ẖaֽlĕlé֣y yişĕ̂ráʼé֑l gȧm-lĕ⁠bábe֥l nápĕl֖ẇ ẖaֽlĕlé֥y kál-há⁠ʼáֽreẕ׃"],[51,50,"פְּלֵטִ֣ים מֵ⁠חֶ֔רֶב הִלְכ֖וּ אַֽל־תַּעֲמֹ֑דוּ זִכְר֤וּ מֵֽ⁠רָחוֹק֙ אֶת־יְהוָ֔ה וִ⁠ירֽוּשָׁלִַ֖ם תַּעֲלֶ֥ה עַל־לְבַבְ⁠כֶֽם׃","pĕ̇léti֣ym mé⁠ẖe֔reb hilĕk֖ẇ ʼaֽl-ţȧʻàmò֑dẇ zikĕr֤ẇ méֽ⁠ráẖwòq֙ ʼeţ-yĕhwá֔h wi⁠yrֽẇşá̌lia֖m ţȧʻàle֥h ʻal-lĕbabĕ⁠keֽm׃"],[51,51,"בֹּ֚שְׁנוּ כִּֽי־שָׁמַ֣עְנוּ חֶרְפָּ֔ה כִּסְּתָ֥ה כְלִמָּ֖ה פָּנֵ֑י⁠נוּ כִּ֚י בָּ֣אוּ זָרִ֔ים עַֽל־מִקְדְּשֵׁ֖י בֵּ֥ית יְהוָֽה׃ס","bò֚̇şĕ̌nẇ kiֽ̇y-şá̌ma֣ʻĕnẇ ẖerĕpá̇֔h ki̇sĕ̇ţá֥h kĕlimá֖̇h pá̇né֑y⁠nẇ ki֚̇y bá֣̇ʼẇ zári֔ym ʻaֽl-miqĕdĕ̇şé֖̌y bé֥̇yţ yĕhwáֽh׃s"],[51,52,"לָ⁠כֵ֞ן הִנֵּֽה־יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וּ⁠פָקַדְתִּ֖י עַל־פְּסִילֶ֑י⁠הָ וּ⁠בְ⁠כָל־אַרְצָ֖⁠הּ יֶאֱנֹ֥ק חָלָֽל׃","lá⁠ké֞n hinéֽ̇h-yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h ẇ⁠páqadĕţi֖̇y ʻal-pĕ̇siyle֑y⁠há ẇ⁠bĕ⁠kál-ʼarĕẕá֖⁠ḣ yeʼènò֥q ẖáláֽl׃"],[51,53,"כִּֽי־תַעֲלֶ֤ה בָבֶל֙ הַ⁠שָּׁמַ֔יִם וְ⁠כִ֥י תְבַצֵּ֖ר מְר֣וֹם עֻזָּ֑⁠הּ מֵ⁠אִתִּ֗⁠י יָבֹ֧אוּ שֹׁדְדִ֛ים לָ֖⁠הּ נְאֻם־יְהוָֽה׃ס","kiֽ̇y-ţaʻàle֤h bábel֙ ha⁠şá̇̌ma֔yim wĕ⁠ki֥y ţĕbaẕé֖̇r mĕr֣wòm ʻuzá֑̇⁠ḣ mé⁠ʼiţi̇֗⁠y yábò֧ʼẇ şò̌dĕdi֛ym lá֖⁠ḣ nĕʼum-yĕhwáֽh׃s"],[51,54,"ק֥וֹל זְעָקָ֖ה מִ⁠בָּבֶ֑ל וְ⁠שֶׁ֥בֶר גָּד֖וֹל מֵ⁠אֶ֥רֶץ כַּשְׂדִּֽים׃","q֥wòl zĕʻáqá֖h mi⁠bá̇be֑l wĕ⁠şě֥ber gá̇d֖wòl mé⁠ʼe֥reẕ kȧşĕ̂diֽ̇ym׃"],[51,55,"כִּֽי־שֹׁדֵ֤ד יְהוָה֙ אֶת־בָּבֶ֔ל וְ⁠אִבַּ֥ד מִמֶּ֖⁠נָּה ק֣וֹל גָּד֑וֹל וְ⁠הָמ֤וּ גַלֵּי⁠הֶם֙ כְּ⁠מַ֣יִם רַבִּ֔ים נִתַּ֥ן שְׁא֖וֹן קוֹלָֽ⁠ם׃","kiֽ̇y-şò̌dé֤d yĕhwáh֙ ʼeţ-bá̇be֔l wĕ⁠ʼibȧ֥d mimė֖⁠ná̇h q֣wòl gá̇d֑wòl wĕ⁠hám֤ẇ galé̇y⁠hem֙ kĕ̇⁠ma֣yim rabi̇֔ym niţȧ֥n şĕ̌ʼ֖wòn qwòláֽ⁠m׃"],[51,56,"כִּי֩ בָ֨א עָלֶ֤י⁠הָ עַל־בָּבֶל֙ שׁוֹדֵ֔ד וְ⁠נִלְכְּדוּ֙ גִּבּוֹרֶ֔י⁠הָ חִתְּתָ֖ה קַשְּׁתוֹתָ֑⁠ם כִּ֣י אֵ֧ל גְּמֻל֛וֹת יְהוָ֖ה שַׁלֵּ֥ם יְשַׁלֵּֽם׃","ki̇y֩ bá֨ʼ ʻále֤y⁠há ʻal-bá̇bel֙ ş̌wòdé֔d wĕ⁠nilĕkĕ̇dẇ֙ gi̇ḃwòre֔y⁠há ẖiţĕ̇ţá֖h qaşĕ̇̌ţwòţá֑⁠m ki֣̇y ʼé֧l gĕ̇mul֛wòţ yĕhwá֖h şǎlé֥̇m yĕşǎléֽ̇m׃"],[51,57,"וְ֠⁠הִשְׁכַּרְתִּי שָׂרֶ֨י⁠הָ וַ⁠חֲכָמֶ֜י⁠הָ פַּחוֹתֶ֤י⁠הָ וּ⁠סְגָנֶ֨י⁠הָ֙ וְ⁠גִבּוֹרֶ֔י⁠הָ וְ⁠יָשְׁנ֥וּ שְׁנַת־עוֹלָ֖ם וְ⁠לֹ֣א יָקִ֑יצוּ נְאֻ֨ם־הַ⁠מֶּ֔לֶךְ יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃ס","wĕ֠⁠hişĕ̌kȧrĕţi̇y şá̂re֨y⁠há wa⁠ẖàkáme֜y⁠há pȧẖwòţe֤y⁠há ẇ⁠sĕgáne֨y⁠há֙ wĕ⁠giḃwòre֔y⁠há wĕ⁠yáşĕ̌n֥ẇ şĕ̌naţ-ʻwòlá֖m wĕ⁠lò֣ʼ yáqi֑yẕẇ nĕʼu֨m-ha⁠mė֔lekĕ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃s"],[51,58,"כֹּֽה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת חֹ֠מוֹת בָּבֶ֤ל הָֽ⁠רְחָבָה֙ עַרְעֵ֣ר תִּתְעַרְעָ֔ר וּ⁠שְׁעָרֶ֥י⁠הָ הַ⁠גְּבֹהִ֖ים בָּ⁠אֵ֣שׁ יִצַּ֑תּוּ וְ⁠יִֽגְע֨וּ עַמִּ֧ים בְּ⁠דֵי־רִ֛יק וּ⁠לְאֻמִּ֥ים בְּ⁠דֵי־אֵ֖שׁ וְ⁠יָעֵֽפוּ׃ס","kòֽ̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ẖò֠mwòţ bá̇be֤l háֽ⁠rĕẖábáh֙ ʻarĕʻé֣r ţi̇ţĕʻarĕʻá֔r ẇ⁠şĕ̌ʻáre֥y⁠há ha⁠gĕ̇bòhi֖ym bá̇⁠ʼé֣ş̌ yiẕȧ֑ţ̇ẇ wĕ⁠yiֽgĕʻ֨ẇ ʻami֧̇ym bĕ̇⁠déy-ri֛yq ẇ⁠lĕʼumi֥̇ym bĕ̇⁠déy-ʼé֖ş̌ wĕ⁠yáʻéֽpẇ׃s"],[51,59,"הַ⁠דָּבָ֞ר אֲשֶׁר־צִוָּ֣ה ׀ יִרְמְיָ֣הוּ הַ⁠נָּבִ֗יא אֶת־שְׂרָיָ֣ה בֶן־נֵרִיָּה֮ בֶּן־מַחְסֵיָה֒ בְּ⁠לֶכְתּ֞⁠וֹ אֶת־צִדְקִיָּ֤הוּ מֶֽלֶךְ־יְהוּדָה֙ בָּבֶ֔ל בִּ⁠שְׁנַ֥ת הָ⁠רְבִעִ֖ית לְ⁠מָלְכ֑⁠וֹ וּ⁠שְׂרָיָ֖ה שַׂ֥ר מְנוּחָֽה׃","ha⁠dá̇bá֞r ʼàşěr-ẕiwá֣̇h ׀ yirĕmĕyá֣hẇ ha⁠ná̇bi֗yʼ ʼeţ-şĕ̂ráyá֣h ben-nériyá̇h֮ bėn-maẖĕséyáh֒ bĕ̇⁠lekĕţ̇֞⁠wò ʼeţ-ẕidĕqiyá֤̇hẇ meֽlekĕ-yĕhẇdáh֙ bá̇be֔l bi̇⁠şĕ̌na֥ţ há⁠rĕbiʻi֖yţ lĕ⁠málĕk֑⁠wò ẇ⁠şĕ̂ráyá֖h şâ֥r mĕnẇẖáֽh׃"],[51,60,"וַ⁠יִּכְתֹּ֣ב יִרְמְיָ֗הוּ אֵ֧ת כָּל־הָ⁠רָעָ֛ה אֲשֶׁר־תָּב֥וֹא אֶל־בָּבֶ֖ל אֶל־סֵ֣פֶר אֶחָ֑ד אֵ֚ת כָּל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה הַ⁠כְּתֻבִ֖ים אֶל־בָּבֶֽל׃","wa⁠yi̇kĕţò֣̇b yirĕmĕyá֗hẇ ʼé֧ţ ká̇l-há⁠ráʻá֛h ʼàşěr-ţá̇b֥wòʼ ʼel-bá̇be֖l ʼel-sé֣per ʼeẖá֑d ʼé֚ţ ká̇l-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ha⁠kĕ̇ţubi֖ym ʼel-bá̇beֽl׃"],[51,61,"וַ⁠יֹּ֥אמֶר יִרְמְיָ֖הוּ אֶל־שְׂרָיָ֑ה כְּ⁠בֹאֲ⁠ךָ֣ בָבֶ֔ל וְֽ⁠רָאִ֔יתָ וְֽ⁠קָרָ֔אתָ אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yò֥̇ʼmer yirĕmĕyá֖hẇ ʼel-şĕ̂ráyá֑h kĕ̇⁠bòʼà⁠ká֣ bábe֔l wĕֽ⁠ráʼi֔yţá wĕֽ⁠qárá֔ʼţá ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[51,62,"וְ⁠אָמַרְתָּ֗ יְהוָה֙ אַתָּ֨ה דִבַּ֜רְתָּ אֶל־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ לְ⁠הַכְרִית֔⁠וֹ לְ⁠בִלְתִּ֤י הֱיֽוֹת־בּ⁠וֹ֙ יוֹשֵׁ֔ב לְ⁠מֵ⁠אָדָ֖ם וְ⁠עַד־בְּהֵמָ֑ה כִּֽי־שִׁמְמ֥וֹת עוֹלָ֖ם תִּֽהְיֶֽה׃","wĕ⁠ʼámarĕţá̇֗ yĕhwáh֙ ʼaţá̇֨h dibȧ֜rĕţá̇ ʼel-ha⁠má̇q֤wòm ha⁠zėh֙ lĕ⁠hakĕriyţ֔⁠wò lĕ⁠bilĕţi֤̇y hèyֽwòţ-ḃ⁠wò֙ ywòşé̌֔b lĕ⁠mé⁠ʼádá֖m wĕ⁠ʻad-bĕ̇hémá֑h kiֽ̇y-şǐmĕm֥wòţ ʻwòlá֖m ţiֽ̇hĕyeֽh׃"],[51,63,"וְ⁠הָיָה֙ כְּ⁠כַלֹּ֣תְ⁠ךָ֔ לִ⁠קְרֹ֖א אֶת־הַ⁠סֵּ֣פֶר הַ⁠זֶּ֑ה תִּקְשֹׁ֤ר עָלָי⁠ו֙ אֶ֔בֶן וְ⁠הִשְׁלַכְתּ֖⁠וֹ אֶל־תּ֥וֹךְ פְּרָֽת׃","wĕ⁠háyáh֙ kĕ̇⁠kalò֣̇ţĕ⁠ká֔ li⁠qĕrò֖ʼ ʼeţ-ha⁠sé֣̇per ha⁠zė֑h ţi̇qĕşò֤̌r ʻáláy⁠w֙ ʼe֔ben wĕ⁠hişĕ̌lakĕţ֖̇⁠wò ʼel-ţ֥̇wòkĕ pĕ̇ráֽţ׃"],[51,64,"וְ⁠אָמַרְתָּ֗ כָּ֠כָה תִּשְׁקַ֨ע בָּבֶ֤ל וְ⁠לֹֽא־תָקוּם֙ מִ⁠פְּנֵ֣י הָ⁠רָעָ֗ה אֲשֶׁ֧ר אָנֹכִ֛י מֵבִ֥יא עָלֶ֖י⁠הָ וְ⁠יָעֵ֑פוּ עַד־הֵ֖נָּה דִּבְרֵ֥י יִרְמְיָֽהוּ׃ס","wĕ⁠ʼámarĕţá̇֗ ká̇֠káh ţi̇şĕ̌qa֨ʻ bá̇be֤l wĕ⁠lòֽʼ-ţáqẇm֙ mi⁠pĕ̇né֣y há⁠ráʻá֗h ʼàşě֧r ʼánòki֛y mébi֥yʼ ʻále֖y⁠há wĕ⁠yáʻé֑pẇ ʻad-hé֖ná̇h di̇bĕré֥y yirĕmĕyáֽhẇ׃s"],[52,1,"בֶּן־עֶשְׂרִ֨ים וְ⁠אַחַ֤ת שָׁנָה֙ צִדְקִיָּ֣הוּ בְ⁠מָלְכ֔⁠וֹ וְ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירֽוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ חמיטל בַּֽת־יִרְמְיָ֖הוּ מִ⁠לִּבְנָֽה׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ʼaẖa֤ţ şá̌náh֙ ẕidĕqiyá֣̇hẇ bĕ⁠málĕk֔⁠wò wĕ⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h mála֖kĕ bi̇⁠yrֽẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ẖmytl bȧֽţ-yirĕmĕyá֖hẇ mi⁠li̇bĕnáֽh׃"],[52,2,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה יְהוֹיָקִֽים׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h yĕhwòyáqiֽym׃"],[52,3,"כִּ֣י ׀ עַל־אַ֣ף יְהוָ֗ה הָֽיְתָה֙ בִּ⁠ירוּשָׁלִַ֣ם וִֽ⁠יהוּדָ֔ה עַד־הִשְׁלִיכ֥⁠וֹ אוֹתָ֖⁠ם מֵ⁠עַ֣ל פָּנָ֑י⁠ו וַ⁠יִּמְרֹ֥ד צִדְקִיָּ֖הוּ בְּ⁠מֶ֥לֶךְ בָּבֶֽל׃","ki֣̇y ׀ ʻal-ʼa֣p yĕhwá֗h háֽyĕţáh֙ bi̇⁠yrẇşá̌lia֣m wiֽ⁠yhẇdá֔h ʻad-hişĕ̌liyk֥⁠wò ʼwòţá֖⁠m mé⁠ʻa֣l pá̇ná֑y⁠w wa⁠yi̇mĕrò֥d ẕidĕqiyá֖̇hẇ bĕ̇⁠me֥lekĕ bá̇beֽl׃"],[52,4,"וַ⁠יְהִי֩ בַ⁠שָּׁנָ֨ה הַ⁠תְּשִׁעִ֜ית לְ⁠מָלְכ֗⁠וֹ בַּ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִי֮ בֶּ⁠עָשׂ֣וֹר לַ⁠חֹדֶשׁ֒ בָּ֠א נְבוּכַדְרֶאצַּ֨ר מֶֽלֶךְ־בָּבֶ֜ל ה֤וּא וְ⁠כָל־חֵיל⁠וֹ֙ עַל־יְר֣וּשָׁלִַ֔ם וַֽ⁠יַּחֲנ֖וּ עָלֶ֑י⁠הָ וַ⁠יִּבְנ֥וּ עָלֶ֛י⁠הָ דָּיֵ֖ק סָבִֽיב׃","wa⁠yĕhiy֩ ba⁠şá̇̌ná֨h ha⁠ţĕ̇şǐʻi֜yţ lĕ⁠málĕk֗⁠wò bȧ⁠ẖò֣deş̌ há⁠ʻàşîyriy֮ bė⁠ʻáş֣̂wòr la⁠ẖòdeş̌֒ bá̇֠ʼ nĕbẇkadĕreʼẕȧ֨r meֽlekĕ-bá̇be֜l h֤ẇʼ wĕ⁠kál-ẖéyl⁠wò֙ ʻal-yĕr֣ẇşá̌lia֔m waֽ⁠yȧẖàn֖ẇ ʻále֑y⁠há wa⁠yi̇bĕn֥ẇ ʻále֛y⁠há dá̇yé֖q sábiֽyb׃"],[52,5,"וַ⁠תָּבֹ֥א הָ⁠עִ֖יר בַּ⁠מָּצ֑וֹר עַ֚ד עַשְׁתֵּ֣י עֶשְׂרֵ֣ה שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ צִדְקִיָּֽהוּ׃","wa⁠ţá̇bò֥ʼ há⁠ʻi֖yr bȧ⁠má̇ẕ֑wòr ʻa֚d ʻaşĕ̌ţé֣̇y ʻeşĕ̂ré֣h şá̌ná֔h la⁠mė֖lekĕ ẕidĕqiyáֽ̇hẇ׃"],[52,6,"בַּ⁠חֹ֤דֶשׁ הָֽ⁠רְבִיעִי֙ בְּ⁠תִשְׁעָ֣ה לַ⁠חֹ֔דֶשׁ וַ⁠יֶּחֱזַ֥ק הָ⁠רָעָ֖ב בָּ⁠עִ֑יר וְ⁠לֹא־הָיָ֥ה לֶ֖חֶם לְ⁠עַ֥ם הָ⁠אָֽרֶץ׃","bȧ⁠ẖò֤deş̌ háֽ⁠rĕbiyʻiy֙ bĕ̇⁠ţişĕ̌ʻá֣h la⁠ẖò֔deş̌ wa⁠yėẖèza֥q há⁠ráʻá֖b bá̇⁠ʻi֑yr wĕ⁠lòʼ-háyá֥h le֖ẖem lĕ⁠ʻa֥m há⁠ʼáֽreẕ׃"],[52,7,"וַ⁠תִּבָּקַ֣ע הָ⁠עִ֗יר וְ⁠כָל־אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֡ה יִבְרְחוּ֩ וַ⁠יֵּצְא֨וּ מֵ⁠הָ⁠עִ֜יר לַ֗יְלָה דֶּ֜רֶךְ שַׁ֤עַר בֵּין־הַ⁠חֹמֹתַ֨יִם֙ אֲשֶׁר֙ עַל־גַּ֣ן הַ⁠מֶּ֔לֶךְ וְ⁠כַשְׂדִּ֥ים עַל־הָ⁠עִ֖יר סָבִ֑יב וַ⁠יֵּלְכ֖וּ דֶּ֥רֶךְ הָ⁠עֲרָבָֽה׃","wa⁠ţi̇bá̇qa֣ʻ há⁠ʻi֗yr wĕ⁠kál-ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֡h yibĕrĕẖẇ֩ wa⁠yé̇ẕĕʼ֨ẇ mé⁠há⁠ʻi֜yr la֗yĕláh dė֜rekĕ şǎ֤ʻar bé̇yn-ha⁠ẖòmòţa֨yim֙ ʼàşěr֙ ʻal-gȧ֣n ha⁠mė֔lekĕ wĕ⁠kaşĕ̂di֥̇ym ʻal-há⁠ʻi֖yr sábi֑yb wa⁠yé̇lĕk֖ẇ dė֥rekĕ há⁠ʻàrábáֽh׃"],[52,8,"וַ⁠יִּרְדְּפ֤וּ חֵיל־כַּשְׂדִּים֙ אַחֲרֵ֣י הַ⁠מֶּ֔לֶךְ וַ⁠יַּשִּׂ֥יגוּ אֶת־צִדְקִיָּ֖הוּ בְּ⁠עַֽרְבֹ֣ת יְרֵח֑וֹ וְ⁠כָל־חֵיל֔⁠וֹ נָפֹ֖צוּ מֵ⁠עָלָֽי⁠ו׃","wa⁠yi̇rĕdĕ̇p֤ẇ ẖéyl-kȧşĕ̂di̇ym֙ ʼaẖàré֣y ha⁠mė֔lekĕ wa⁠yȧşi֥̇̂ygẇ ʼeţ-ẕidĕqiyá֖̇hẇ bĕ̇⁠ʻaֽrĕbò֣ţ yĕréẖ֑wò wĕ⁠kál-ẖéyl֔⁠wò nápò֖ẕẇ mé⁠ʻáláֽy⁠w׃"],[52,9,"וַֽ⁠יִּתְפְּשׂוּ֙ אֶת־הַ⁠מֶּ֔לֶךְ וַ⁠יַּעֲל֨וּ אֹת֜⁠וֹ אֶל־מֶ֧לֶךְ בָּבֶ֛ל רִבְלָ֖תָ⁠ה בְּ⁠אֶ֣רֶץ חֲמָ֑ת וַ⁠יְדַבֵּ֥ר אִתּ֖⁠וֹ מִשְׁפָּטִֽים׃","waֽ⁠yi̇ţĕpĕ̇ş̂ẇ֙ ʼeţ-ha⁠mė֔lekĕ wa⁠yȧʻàl֨ẇ ʼòţ֜⁠wò ʼel-me֧lekĕ bá̇be֛l ribĕlá֖ţá⁠h bĕ̇⁠ʼe֣reẕ ẖàmá֑ţ wa⁠yĕdabé֥̇r ʼiţ֖̇⁠wò mişĕ̌pá̇tiֽym׃"],[52,10,"וַ⁠יִּשְׁחַ֧ט מֶֽלֶךְ־בָּבֶ֛ל אֶת־בְּנֵ֥י צִדְקִיָּ֖הוּ לְ⁠עֵינָ֑י⁠ו וְ⁠גַ֛ם אֶת־כָּל־שָׂרֵ֥י יְהוּדָ֖ה שָׁחַ֥ט בְּ⁠רִבְלָֽתָ⁠ה׃","wa⁠yi̇şĕ̌ẖa֧t meֽlekĕ-bá̇be֛l ʼeţ-bĕ̇né֥y ẕidĕqiyá֖̇hẇ lĕ⁠ʻéyná֑y⁠w wĕ⁠ga֛m ʼeţ-ká̇l-şá̂ré֥y yĕhẇdá֖h şá̌ẖa֥t bĕ̇⁠ribĕláֽţá⁠h׃"],[52,11,"וְ⁠אֶת־עֵינֵ֥י צִדְקִיָּ֖הוּ עִוֵּ֑ר וַ⁠יַּאַסְרֵ֣⁠הוּ בַֽ⁠נְחֻשְׁתַּ֗יִם וַ⁠יְבִאֵ֤⁠הוּ מֶֽלֶךְ־בָּבֶל֙ בָּבֶ֔לָ⁠ה וַ⁠יִּתְּנֵ֥⁠הוּ ב⁠בית־הַ⁠פְּקֻדֹּ֖ת עַד־י֥וֹם מוֹתֽ⁠וֹ׃","wĕ⁠ʼeţ-ʻéyné֥y ẕidĕqiyá֖̇hẇ ʻiwé֑̇r wa⁠yȧʼasĕré֣⁠hẇ baֽ⁠nĕẖuşĕ̌ţȧ֗yim wa⁠yĕbiʼé֤⁠hẇ meֽlekĕ-bá̇bel֙ bá̇be֔lá⁠h wa⁠yi̇ţĕ̇né֥⁠hẇ b⁠byţ-ha⁠pĕ̇qudò֖̇ţ ʻad-y֥wòm mwòţֽ⁠wò׃"],[52,12,"וּ⁠בַ⁠חֹ֤דֶשׁ הַֽ⁠חֲמִישִׁי֙ בֶּ⁠עָשׂ֣וֹר לַ⁠חֹ֔דֶשׁ הִ֗יא שְׁנַת֙ תְּשַֽׁע־עֶשְׂרֵ֣ה שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ נְבוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֑ל בָּ֗א נְבֽוּזַרְאֲדָן֙ רַב־טַבָּחִ֔ים עָמַ֛ד לִ⁠פְנֵ֥י מֶֽלֶךְ־בָּבֶ֖ל בִּ⁠ירוּשָׁלִָֽם׃","ẇ⁠ba⁠ẖò֤deş̌ hֽa⁠ẖàmiyşǐy֙ bė⁠ʻáş֣̂wòr la⁠ẖò֔deş̌ hi֗yʼ şĕ̌naţ֙ ţĕ̇şǎֽʻ-ʻeşĕ̂ré֣h şá̌ná֔h la⁠mė֖lekĕ nĕbẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇be֑l bá̇֗ʼ nĕbֽẇzarĕʼàdán֙ rab-tabá̇ẖi֔ym ʻáma֛d li⁠pĕné֥y meֽlekĕ-bá̇be֖l bi̇⁠yrẇşá̌liáֽm׃"],[52,13,"וַ⁠יִּשְׂרֹ֥ף אֶת־בֵּית־יְהוָ֖ה וְ⁠אֶת־בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ⁠אֵ֨ת כָּל־בָּתֵּ֧י יְרוּשָׁלִַ֛ם וְ⁠אֶת־כָּל־בֵּ֥ית הַ⁠גָּד֖וֹל שָׂרַ֥ף בָּ⁠אֵֽשׁ׃","wa⁠yi̇şĕ̂rò֥p ʼeţ-bé̇yţ-yĕhwá֖h wĕ⁠ʼeţ-bé֣̇yţ ha⁠mė֑lekĕ wĕ⁠ʼé֨ţ ká̇l-bá̇ţé֧̇y yĕrẇşá̌lia֛m wĕ⁠ʼeţ-ká̇l-bé֥̇yţ ha⁠gá̇d֖wòl şá̂ra֥p bá̇⁠ʼéֽş̌׃"],[52,14,"וְ⁠אֶת־כָּל־חֹמ֥וֹת יְרוּשָׁלִַ֖ם סָבִ֑יב נָֽתְצוּ֙ כָּל־חֵ֣יל כַּשְׂדִּ֔ים אֲשֶׁ֖ר אֶת־רַב־טַבָּחִֽים׃","wĕ⁠ʼeţ-ká̇l-ẖòm֥wòţ yĕrẇşá̌lia֖m sábi֑yb náֽţĕẕẇ֙ ká̇l-ẖé֣yl kȧşĕ̂di̇֔ym ʼàşě֖r ʼeţ-rab-tabá̇ẖiֽym׃"],[52,15,"וּ⁠מִ⁠דַּלּ֨וֹת הָ⁠עָ֜ם וְֽ⁠אֶת־יֶ֥תֶר הָ⁠עָ֣ם ׀ הַ⁠נִּשְׁאָרִ֣ים בָּ⁠עִ֗יר וְ⁠אֶת־הַ⁠נֹּֽפְלִים֙ אֲשֶׁ֤ר נָֽפְלוּ֙ אֶל־מֶ֣לֶךְ בָּבֶ֔ל וְ⁠אֵ֖ת יֶ֣תֶר הָֽ⁠אָמ֑וֹן הֶגְלָ֕ה נְבוּזַרְאֲדָ֖ן רַב־טַבָּחִֽים׃","ẇ⁠mi⁠dȧl̇֨wòţ há⁠ʻá֜m wĕֽ⁠ʼeţ-ye֥ţer há⁠ʻá֣m ׀ ha⁠ni̇şĕ̌ʼári֣ym bá̇⁠ʻi֗yr wĕ⁠ʼeţ-ha⁠nòֽ̇pĕliym֙ ʼàşě֤r náֽpĕlẇ֙ ʼel-me֣lekĕ bá̇be֔l wĕ⁠ʼé֖ţ ye֣ţer háֽ⁠ʼám֑wòn hegĕlá֕h nĕbẇzarĕʼàdá֖n rab-tabá̇ẖiֽym׃"],[52,16,"וּ⁠מִ⁠דַּלּ֣וֹת הָ⁠אָ֔רֶץ הִשְׁאִ֕יר נְבוּזַרְאֲדָ֖ן רַב־טַבָּחִ֑ים לְ⁠כֹרְמִ֖ים וּ⁠לְ⁠יֹגְבִֽים׃","ẇ⁠mi⁠dȧl֣̇wòţ há⁠ʼá֔reẕ hişĕ̌ʼi֕yr nĕbẇzarĕʼàdá֖n rab-tabá̇ẖi֑ym lĕ⁠kòrĕmi֖ym ẇ⁠lĕ⁠yògĕbiֽym׃"],[52,17,"וְ⁠אֶת־עַמּוּדֵ֨י הַ⁠נְּחֹ֜שֶׁת אֲשֶׁ֣ר לְ⁠בֵית־יְהוָ֗ה וְֽ⁠אֶת־הַ⁠מְּכֹנ֞וֹת וְ⁠אֶת־יָ֧ם הַ⁠נְּחֹ֛שֶׁת אֲשֶׁ֥ר בְּ⁠בֵית־יְהוָ֖ה שִׁבְּר֣וּ כַשְׂדִּ֑ים וַ⁠יִּשְׂא֥וּ אֶת־כָּל־נְחֻשְׁתָּ֖⁠ם בָּבֶֽלָ⁠ה׃","wĕ⁠ʼeţ-ʻaṁẇdé֨y ha⁠nĕ̇ẖò֜şěţ ʼàşě֣r lĕ⁠béyţ-yĕhwá֗h wĕֽ⁠ʼeţ-ha⁠mĕ̇kòn֞wòţ wĕ⁠ʼeţ-yá֧m ha⁠nĕ̇ẖò֛şěţ ʼàşě֥r bĕ̇⁠béyţ-yĕhwá֖h şǐbĕ̇r֣ẇ kaşĕ̂di֑̇ym wa⁠yi̇şĕ̂ʼ֥ẇ ʼeţ-ká̇l-nĕẖuşĕ̌ţá֖̇⁠m bá̇beֽlá⁠h׃"],[52,18,"וְ⁠אֶת־הַ֠⁠סִּרוֹת וְ⁠אֶת־הַ⁠יָּעִ֨ים וְ⁠אֶת־הַֽ⁠מְזַמְּר֜וֹת וְ⁠אֶת־הַ⁠מִּזְרָקֹ֣ת וְ⁠אֶת־הַ⁠כַּפּ֗וֹת וְ⁠אֵ֨ת כָּל־כְּלֵ֧י הַ⁠נְּחֹ֛שֶׁת אֲשֶׁר־יְשָׁרְת֥וּ בָ⁠הֶ֖ם לָקָֽחוּ׃","wĕ⁠ʼeţ-ha֠⁠si̇rwòţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֨ym wĕ⁠ʼeţ-haֽ⁠mĕzamĕ̇r֜wòţ wĕ⁠ʼeţ-ha⁠mi̇zĕráqò֣ţ wĕ⁠ʼeţ-ha⁠kȧṗ֗wòţ wĕ⁠ʼé֨ţ ká̇l-kĕ̇lé֧y ha⁠nĕ̇ẖò֛şěţ ʼàşěr-yĕşá̌rĕţ֥ẇ bá⁠he֖m láqáֽẖẇ׃"],[52,19,"וְ⁠אֶת־הַ֠⁠סִּפִּים וְ⁠אֶת־הַ⁠מַּחְתּ֨וֹת וְ⁠אֶת־הַ⁠מִּזְרָק֜וֹת וְ⁠אֶת־הַ⁠סִּיר֣וֹת וְ⁠אֶת־הַ⁠מְּנֹר֗וֹת וְ⁠אֶת־הַ⁠כַּפּוֹת֙ וְ⁠אֶת־הַ⁠מְּנַקִי֔וֹת אֲשֶׁ֤ר זָהָב֙ זָהָ֔ב וַ⁠אֲשֶׁר־כֶּ֖סֶף כָּ֑סֶף לָקַ֖ח רַב־טַבָּחִֽים׃","wĕ⁠ʼeţ-ha֠⁠si̇pi̇ym wĕ⁠ʼeţ-ha⁠mȧẖĕţ̇֨wòţ wĕ⁠ʼeţ-ha⁠mi̇zĕráq֜wòţ wĕ⁠ʼeţ-ha⁠si̇yr֣wòţ wĕ⁠ʼeţ-ha⁠mĕ̇nòr֗wòţ wĕ⁠ʼeţ-ha⁠kȧṗwòţ֙ wĕ⁠ʼeţ-ha⁠mĕ̇naqiy֔wòţ ʼàşě֤r záháb֙ záhá֔b wa⁠ʼàşěr-kė֖sep ká֑̇sep láqa֖ẖ rab-tabá̇ẖiֽym׃"],[52,20,"הָ⁠עַמּוּדִ֣ים ׀ שְׁנַ֗יִם הַ⁠יָּ֤ם אֶחָד֙ וְ⁠הַ⁠בָּקָ֞ר שְׁנֵים־עָשָׂ֤ר נְחֹ֨שֶׁת֙ אֲשֶׁר־תַּ֣חַת הַ⁠מְּכֹנ֔וֹת אֲשֶׁ֥ר עָשָׂ֛ה הַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה לְ⁠בֵ֣ית יְהוָ֑ה לֹא־הָיָ֣ה מִשְׁקָ֔ל לִ⁠נְחֻשְׁתָּ֖⁠ם כָּל־הַ⁠כֵּלִ֥ים הָ⁠אֵֽלֶּה׃","há⁠ʻaṁẇdi֣ym ׀ şĕ̌na֗yim ha⁠yá֤̇m ʼeẖád֙ wĕ⁠ha⁠bá̇qá֞r şĕ̌néym-ʻáşá֤̂r nĕẖò֨şěţ֙ ʼàşěr-ţȧ֣ẖaţ ha⁠mĕ̇kòn֔wòţ ʼàşě֥r ʻáşá֛̂h ha⁠mė֥lekĕ şĕ̌lòmò֖h lĕ⁠bé֣yţ yĕhwá֑h lòʼ-háyá֣h mişĕ̌qá֔l li⁠nĕẖuşĕ̌ţá֖̇⁠m ká̇l-ha⁠ké̇li֥ym há⁠ʼéֽlėh׃"],[52,21,"וְ⁠הָ⁠עַמּוּדִ֗ים שְׁמֹנֶ֨ה עֶשְׂרֵ֤ה אַמָּה֙ קומה הָ⁠עַמֻּ֣ד הָ⁠אֶחָ֔ד וְ⁠ח֛וּט שְׁתֵּים־עֶשְׂרֵ֥ה אַמָּ֖ה יְסֻבֶּ֑⁠נּוּ וְ⁠עָבְי֛⁠וֹ אַרְבַּ֥ע אַצְבָּע֖וֹת נָבֽוּב׃","wĕ⁠há⁠ʻaṁẇdi֗ym şĕ̌mòne֨h ʻeşĕ̂ré֤h ʼamá̇h֙ qwmh há⁠ʻamu֣̇d há⁠ʼeẖá֔d wĕ⁠ẖ֛ẇt şĕ̌ţé̇ym-ʻeşĕ̂ré֥h ʼamá֖̇h yĕsubė֑⁠ṅẇ wĕ⁠ʻábĕy֛⁠wò ʼarĕbȧ֥ʻ ʼaẕĕbá̇ʻ֖wòţ nábֽẇb׃"],[52,22,"וְ⁠כֹתֶ֨רֶת עָלָ֜י⁠ו נְחֹ֗שֶׁת וְ⁠קוֹמַ֨ת הַ⁠כֹּתֶ֥רֶת הָ⁠אַחַת֮ חָמֵ֣שׁ אַמּוֹת֒ וּ⁠שְׂבָכָ֨ה וְ⁠רִמּוֹנִ֧ים עַֽל־הַ⁠כּוֹתֶ֛רֶת סָבִ֖יב הַ⁠כֹּ֣ל נְחֹ֑שֶׁת וְ⁠כָ⁠אֵ֛לֶּה לַֽ⁠עַמּ֥וּד הַ⁠שֵּׁנִ֖י וְ⁠רִמּוֹנִֽים׃","wĕ⁠kòţe֨reţ ʻálá֜y⁠w nĕẖò֗şěţ wĕ⁠qwòma֨ţ ha⁠kò̇ţe֥reţ há⁠ʼaẖaţ֮ ẖámé֣ş̌ ʼaṁwòţ֒ ẇ⁠şĕ̂báká֨h wĕ⁠riṁwòni֧ym ʻaֽl-ha⁠k̇wòţe֛reţ sábi֖yb ha⁠kò֣̇l nĕẖò֑şěţ wĕ⁠ká⁠ʼé֛lėh laֽ⁠ʻaṁ֥ẇd ha⁠şé̇̌ni֖y wĕ⁠riṁwòniֽym׃"],[52,23,"וַ⁠יִּֽהְיוּ֙ הָֽ⁠רִמֹּנִ֔ים תִּשְׁעִ֥ים וְ⁠שִׁשָּׁ֖ה ר֑וּחָ⁠ה כָּל־הָ⁠רִמּוֹנִ֥ים מֵאָ֛ה עַל־הַ⁠שְּׂבָכָ֖ה סָבִֽיב׃","wa⁠yiֽ̇hĕyẇ֙ háֽ⁠rimò̇ni֔ym ţi̇şĕ̌ʻi֥ym wĕ⁠şǐşá֖̇̌h r֑ẇẖá⁠h ká̇l-há⁠riṁwòni֥ym méʼá֛h ʻal-ha⁠şĕ̇̂báká֖h sábiֽyb׃"],[52,24,"וַ⁠יִּקַּ֣ח רַב־טַבָּחִ֗ים אֶת־שְׂרָיָה֙ כֹּהֵ֣ן הָ⁠רֹ֔אשׁ וְ⁠אֶת־צְפַנְיָ֖ה כֹּהֵ֣ן הַ⁠מִּשְׁנֶ֑ה וְ⁠אֶת־שְׁלֹ֖שֶׁת שֹׁמְרֵ֥י הַ⁠סַּֽף׃","wa⁠yi̇qȧ֣ẖ rab-tabá̇ẖi֗ym ʼeţ-şĕ̂ráyáh֙ kò̇hé֣n há⁠rò֔ʼş̌ wĕ⁠ʼeţ-ẕĕpanĕyá֖h kò̇hé֣n ha⁠mi̇şĕ̌ne֑h wĕ⁠ʼeţ-şĕ̌lò֖şěţ şò̌mĕré֥y ha⁠sȧֽp׃"],[52,25,"וּ⁠מִן־הָ⁠עִ֡יר לָקַח֩ סָרִ֨יס אֶחָ֜ד אֲֽשֶׁר־הָיָ֥ה פָקִ֣יד ׀ עַל־אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה וְ⁠שִׁבְעָ֨ה אֲנָשִׁ֜ים מֵ⁠רֹאֵ֤י פְנֵי־הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר נִמְצְא֣וּ בָ⁠עִ֔יר וְ⁠אֵ֗ת סֹפֵר֙ שַׂ֣ר הַ⁠צָּבָ֔א הַ⁠מַּצְבִּ֖א אֶת־עַ֣ם הָ⁠אָ֑רֶץ וְ⁠שִׁשִּׁ֥ים אִישׁ֙ מֵ⁠עַ֣ם הָ⁠אָ֔רֶץ הַֽ⁠נִּמְצְאִ֖ים בְּ⁠ת֥וֹךְ הָ⁠עִֽיר׃","ẇ⁠min-há⁠ʻi֡yr láqaẖ֩ sári֨ys ʼeẖá֜d ʼàֽşěr-háyá֥h páqi֣yd ׀ ʻal-ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h wĕ⁠şǐbĕʻá֨h ʼànáşǐ֜ym mé⁠ròʼé֤y pĕnéy-ha⁠mė֨lekĕ֙ ʼàşě֣r nimĕẕĕʼ֣ẇ bá⁠ʻi֔yr wĕ⁠ʼé֗ţ sòpér֙ şâ֣r ha⁠ẕá̇bá֔ʼ ha⁠mȧẕĕbi֖̇ʼ ʼeţ-ʻa֣m há⁠ʼá֑reẕ wĕ⁠şǐşi֥̇̌ym ʼiyş̌֙ mé⁠ʻa֣m há⁠ʼá֔reẕ haֽ⁠ni̇mĕẕĕʼi֖ym bĕ̇⁠ţ֥wòkĕ há⁠ʻiֽyr׃"],[52,26,"וַ⁠יִּקַּ֣ח אוֹתָ֔⁠ם נְבוּזַרְאֲדָ֖ן רַב־טַבָּחִ֑ים וַ⁠יֹּ֧לֶךְ אוֹתָ֛⁠ם אֶל־מֶ֥לֶךְ בָּבֶ֖ל רִבְלָֽתָ⁠ה׃","wa⁠yi̇qȧ֣ẖ ʼwòţá֔⁠m nĕbẇzarĕʼàdá֖n rab-tabá̇ẖi֑ym wa⁠yò֧̇lekĕ ʼwòţá֛⁠m ʼel-me֥lekĕ bá̇be֖l ribĕláֽţá⁠h׃"],[52,27,"וַ⁠יַּכֶּ֣ה אוֹתָ⁠ם֩ מֶ֨לֶךְ בָּבֶ֧ל וַ⁠יְמִתֵ֛⁠ם בְּ⁠רִבְלָ֖ה בְּ⁠אֶ֣רֶץ חֲמָ֑ת וַ⁠יִּ֥גֶל יְהוּדָ֖ה מֵ⁠עַ֥ל אַדְמָתֽ⁠וֹ׃","wa⁠yȧkė֣h ʼwòţá⁠m֩ me֨lekĕ bá̇be֧l wa⁠yĕmiţé֛⁠m bĕ̇⁠ribĕlá֖h bĕ̇⁠ʼe֣reẕ ẖàmá֑ţ wa⁠yi֥̇gel yĕhẇdá֖h mé⁠ʻa֥l ʼadĕmáţֽ⁠wò׃"],[52,28,"זֶ֣ה הָ⁠עָ֔ם אֲשֶׁ֥ר הֶגְלָ֖ה נְבֽוּכַדְרֶאצַּ֑ר בִּ⁠שְׁנַת־שֶׁ֕בַע יְהוּדִ֕ים שְׁלֹ֥שֶׁת אֲלָפִ֖ים וְ⁠עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃","ze֣h há⁠ʻá֔m ʼàşě֥r hegĕlá֖h nĕbֽẇkadĕreʼẕȧ֑r bi̇⁠şĕ̌naţ-şě֕baʻ yĕhẇdi֕ym şĕ̌lò֥şěţ ʼàlápi֖ym wĕ⁠ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃"],[52,29,"בִּ⁠שְׁנַ֛ת שְׁמוֹנֶ֥ה עֶשְׂרֵ֖ה לִ⁠נְבֽוּכַדְרֶאצַּ֑ר מִ⁠יר֣וּשָׁלִַ֔ם נֶ֕פֶשׁ שְׁמֹנֶ֥ה מֵא֖וֹת שְׁלֹשִׁ֥ים וּ⁠שְׁנָֽיִם׃","bi̇⁠şĕ̌na֛ţ şĕ̌mwòne֥h ʻeşĕ̂ré֖h li⁠nĕbֽẇkadĕreʼẕȧ֑r mi⁠yr֣ẇşá̌lia֔m ne֕peş̌ şĕ̌mòne֥h méʼ֖wòţ şĕ̌lòşǐ֥ym ẇ⁠şĕ̌náֽyim׃"],[52,30,"בִּ⁠שְׁנַ֨ת שָׁלֹ֣שׁ וְ⁠עֶשְׂרִים֮ לִ⁠נְבֽוּכַדְרֶאצַּר֒ הֶגְלָ֗ה נְבֽוּזַרְאֲדָן֙ רַב־טַבָּחִ֔ים יְהוּדִ֕ים נֶ֕פֶשׁ שְׁבַ֥ע מֵא֖וֹת אַרְבָּעִ֣ים וַ⁠חֲמִשָּׁ֑ה כָּל־נֶ֕פֶשׁ אַרְבַּ֥עַת אֲלָפִ֖ים וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃פ","bi̇⁠şĕ̌na֨ţ şá̌lò֣ş̌ wĕ⁠ʻeşĕ̂riym֮ li⁠nĕbֽẇkadĕreʼẕȧr֒ hegĕlá֗h nĕbֽẇzarĕʼàdán֙ rab-tabá̇ẖi֔ym yĕhẇdi֕ym ne֕peş̌ şĕ̌ba֥ʻ méʼ֖wòţ ʼarĕbá̇ʻi֣ym wa⁠ẖàmişá֑̇̌h ká̇l-ne֕peş̌ ʼarĕbȧ֥ʻaţ ʼàlápi֖ym wĕ⁠şé֥̌ş̌ méʼֽwòţ׃p"],[52,31,"וַ⁠יְהִי֩ בִ⁠שְׁלֹשִׁ֨ים וָ⁠שֶׁ֜בַע שָׁנָ֗ה לְ⁠גָלוּת֙ יְהוֹיָכִ֣ן מֶֽלֶךְ־יְהוּדָ֔ה בִּ⁠שְׁנֵ֤ים עָשָׂר֙ חֹ֔דֶשׁ בְּ⁠עֶשְׂרִ֥ים וַ⁠חֲמִשָּׁ֖ה לַ⁠חֹ֑דֶשׁ נָשָׂ֡א אֱוִ֣יל מְרֹדַךְ֩ מֶ֨לֶךְ בָּבֶ֜ל בִּ⁠שְׁנַ֣ת מַלְכֻת֗⁠וֹ אֶת־רֹאשׁ֙ יְהוֹיָכִ֣ין מֶֽלֶךְ־יְהוּדָ֔ה וַ⁠יֹּצֵ֥א אוֹת֖⁠וֹ מִ⁠בֵּ֥ית ה⁠כליא׃","wa⁠yĕhiy֩ bi⁠şĕ̌lòşǐ֨ym wá⁠şě֜baʻ şá̌ná֗h lĕ⁠gálẇţ֙ yĕhwòyáki֣n meֽlekĕ-yĕhẇdá֔h bi̇⁠şĕ̌né֤ym ʻáşá̂r֙ ẖò֔deş̌ bĕ̇⁠ʻeşĕ̂ri֥ym wa⁠ẖàmişá֖̇̌h la⁠ẖò֑deş̌ náşá̂֡ʼ ʼèwi֣yl mĕròdakĕ֩ me֨lekĕ bá̇be֜l bi̇⁠şĕ̌na֣ţ malĕkuţ֗⁠wò ʼeţ-ròʼş̌֙ yĕhwòyáki֣yn meֽlekĕ-yĕhẇdá֔h wa⁠yò̇ẕé֥ʼ ʼwòţ֖⁠wò mi⁠bé֥̇yţ h⁠klyʼ׃"],[52,32,"וַ⁠יְדַבֵּ֥ר אִתּ֖⁠וֹ טֹב֑וֹת וַ⁠יִּתֵּן֙ אֶת־כִּסְא֔⁠וֹ מִ⁠מַּ֗עַל לְ⁠כִסֵּ֧א מלכים אֲשֶׁ֥ר אִתּ֖⁠וֹ בְּ⁠בָבֶֽל׃","wa⁠yĕdabé֥̇r ʼiţ֖̇⁠wò tòb֑wòţ wa⁠yi̇ţé̇n֙ ʼeţ-ki̇sĕʼ֔⁠wò mi⁠mȧ֗ʻal lĕ⁠kisé֧̇ʼ mlkym ʼàşě֥r ʼiţ֖̇⁠wò bĕ̇⁠bábeֽl׃"],[52,33,"וְ⁠שִׁנָּ֕ה אֵ֖ת בִּגְדֵ֣י כִלְא֑⁠וֹ וְ⁠אָכַ֨ל לֶ֧חֶם לְ⁠פָנָ֛י⁠ו תָּמִ֖יד כָּל־יְמֵ֥י חַיָּֽ⁠ו׃","wĕ⁠şǐná̇֕h ʼé֖ţ bi̇gĕdé֣y kilĕʼ֑⁠wò wĕ⁠ʼáka֨l le֧ẖem lĕ⁠páná֛y⁠w ţá̇mi֖yd ká̇l-yĕmé֥y ẖayáֽ̇⁠w׃"],[52,34,"וַ⁠אֲרֻחָת֗⁠וֹ אֲרֻחַת֩ תָּמִ֨יד נִתְּנָה־לּ֜⁠וֹ מֵ⁠אֵ֧ת מֶֽלֶךְ־בָּבֶ֛ל דְּבַר־י֥וֹם בְּ⁠יוֹמ֖⁠וֹ עַד־י֣וֹם מוֹת֑⁠וֹ כֹּ֖ל יְמֵ֥י חַיָּֽי⁠ו׃","wa⁠ʼàruẖáţ֗⁠wò ʼàruẖaţ֩ ţá̇mi֨yd niţĕ̇náh-l̇֜⁠wò mé⁠ʼé֧ţ meֽlekĕ-bá̇be֛l dĕ̇bar-y֥wòm bĕ̇⁠ywòm֖⁠wò ʻad-y֣wòm mwòţ֑⁠wò kò֖̇l yĕmé֥y ẖayáֽ̇y⁠w׃"]]}};